// Live data layer for the operator dashboard.
//
// The mockup HTML is the visual frame. live.js takes over once the page
// loads: requires auth, then hands the pipeline view real data via the
// pipeline_list / pipeline_counts RPCs, and rewires paAction(...) to
// call send_screening_link / send_booking_link / decline_applicant.
//
// Other tabs still show mockup data — they get wired up in follow-ups.

import { createClient } from "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/+esm";
import { planScheduleWeek } from "./scheduling-engine.js?v=b2ebeec00db5";
import { assessPlan as rrAssessLaborPlan, driversNeeded as rrDriversNeeded, FORECAST_KIND_LABEL as RR_FC_LABEL, FORECAST_KIND_CLASS as RR_FC_CLASS } from "./forecast-core.js?v=b2ebeec00db5";
import { effectiveWindows as _slotEffectiveWindows, isClosedDate as _slotIsClosedDate, slotStarts as _slotStarts, daySlotCapacity as _slotDayCapacity } from "./ivcal-slots.js?v=b2ebeec00db5";
import { loadWorkbooksView, createReportWorkbook, registerReportProvider, registerReportsScreen, openReportsScreen, registerScheduleEngine, registerDriverActions, parseXlsxBytes, requestOpenWorkbook } from "./workbook.js?v=b2ebeec00db5";
import { initReportsBuilder, renderReportsInto, buildReportData } from "./reports.js?v=b2ebeec00db5";

const cfg = window.RR_CONFIG;
if (!cfg) throw new Error("RR_CONFIG missing — load config.js before live.js");

const sb = createClient(cfg.SUPABASE_URL, cfg.SUPABASE_ANON_KEY, {
  auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true },
});
window.RR = { sb, user: null, dsp: null };
// Reports Builder — launched from the app-launcher Reports button; the
// workbook-creation dependency is injected here so reports.js never
// imports workbook.js directly (avoids a second module instance via a
// mismatched ?v= specifier). evalPolicy hands the attendance report the
// same normalized block policy the Attendance screen scores with —
// function declarations hoist, so referencing _evalPolicy here is safe.
initReportsBuilder({
  createReportWorkbook,
  evalPolicy: () => (typeof _evalPolicy === "function" ? _evalPolicy() : null),
});
registerReportProvider(buildReportData);
registerReportsScreen(renderReportsInto);
// Sheet-to-Schedule (workbook "Build Schedule from Sheet"): hand the
// workbook the SAME engine Smart Fill runs, plus the driver drawer for
// row-level actions. Arrow-wrapped so openDriverDrawer resolves at call
// time (it's declared later in this module).
registerScheduleEngine(planScheduleWeek);
registerDriverActions((id, opts) => { if (typeof openDriverDrawer === "function") openDriverDrawer(id, opts || {}); });
window.openReportsScreen = openReportsScreen;
// Devtools convenience: surface the Supabase client + a one-liner
// for the okami_demand diagnostic so operators can paste a single
// command without knowing about RR.sb.
window.sb = sb;
window.debugDemand = async (weekStart) => {
  const r = await sb.rpc('debug_okami_demand', { p_week_start: weekStart });
  if (r.error) { console.error(r.error); return; }
  console.table(r.data);
  return r.data;
};

// ─── Client error telemetry ────────────────────────────────────────────────
// Reports uncaught errors + unhandled promise rejections to the
// client_errors table (migration 0385) so production incidents are
// visible without waiting for an operator to report them. Hard rules:
// telemetry must NEVER throw, never loop (its own failures are
// swallowed), and never spam — max 5 distinct errors per page load,
// deduped by message. Inserts silently no-op before sign-in (RLS
// allows authenticated only), which is fine: pre-auth failures
// redirect to login anyway.
(() => {
  const seen = new Set();
  let sent = 0;
  async function report(kind, message, stack) {
    try {
      if (!message || sent >= 5) return;
      const key = String(message).slice(0, 300);
      if (seen.has(key)) return;
      seen.add(key);
      sent++;
      const ver = (document.querySelector('script[src*="live.js?v="]')?.getAttribute("src") || "").match(/v=([\w.-]+)/)?.[1] || null;
      await sb.from("client_errors").insert({
        dsp_id: window.RR?.dsp?.id || null,
        user_id: window.RR?.user?.id || null,
        page: location.pathname + "#" + (document.querySelector(".view.active")?.id || ""),
        message: key,
        stack: String(stack || "").slice(0, 4000),
        source: kind,
        user_agent: navigator.userAgent.slice(0, 300),
        app_version: ver,
      });
    } catch (_) { /* telemetry must never throw */ }
  }
  window.addEventListener("error", (e) => report("onerror", e?.message, e?.error?.stack));
  window.addEventListener("unhandledrejection", (e) => {
    const r = e?.reason;
    report("unhandledrejection", (r && (r.message || String(r))) || "unhandled rejection", r?.stack);
  });
  window._rrReportError = (msg, stack) => report("manual", msg, stack);
})();

// ─── View partials gate ────────────────────────────────────────────────────
// The big views' markup is injected from cacheable views/*.frag files
// by the inline injector in index.html (monolith split phase 2). Wait
// for injection before anything below touches view DOM. A failed
// partial is a boot failure: throwing here means __RR_BOOT_OK never
// flips, so the index.html boot gate shows the honest error card
// instead of a half-empty app.
if (window.__RR_VIEWS_READY) await window.__RR_VIEWS_READY;
if (window.__RR_VIEW_LOAD_FAILED) throw new Error("view partials failed to load");

// ─── Shared utility rail · relocate out of the per-view subtree ─────────────
// The right-edge utility rail (Notes / Tasks / Operations-Health / Forms) and
// its slide-out panels ship as static markup inside view-schedule.frag, so
// they're injected as descendants of #view-schedule — which is display:none
// when that view is inactive. To let the SAME rail serve the recruiting /
// onboarding view too, we hoist those four nodes (keeping their ids) into a
// single fixed global mount that's a direct child of <body>, outside every
// .view hidden subtree. CSS then view-gates the mount's visibility to
// #view-schedule + #view-onboarding-ops via body[data-rr-active-view]; all
// existing JS keeps resolving the rail/panels by their unchanged ids. Runs
// BEFORE the auth gate below so the relocation happens even on the login
// redirect path (harmless if the markup is missing).
(function _rrHoistUtilRail() {
  try {
    // NOTE: every rail panel aside must be listed here — an unhoisted panel
    // renders as unstyled flow content at the bottom of the schedule view.
    const ids = ["rr-sched-util-rail", "rr-sched-notes", "rr-sched-tasks", "rr-sched-checklists", "rr-sched-forms", "rr-sched-contacts", "rr-sched-recog", "rr-sched-receipts"];
    const nodes = ids.map((id) => document.getElementById(id)).filter(Boolean);
    if (!nodes.length) return;
    let mount = document.getElementById("rr-util-rail-mount");
    if (!mount) {
      mount = document.createElement("div");
      mount.id = "rr-util-rail-mount";
      document.body.appendChild(mount);
    }
    nodes.forEach((n) => mount.appendChild(n));
  } catch (_) {}
})();
// Seed the active-view signal from whichever view is active at boot (Schedule
// by default), so the rail shows immediately without waiting for a goto().
// goto() (mock-wiring.js) keeps this in sync on every navigation.
(function _rrSeedActiveViewSignal() {
  try {
    const active = document.querySelector(".view.active");
    if (active && active.id) document.body.dataset.rrActiveView = active.id;
  } catch (_) {}
})();
// The active top-level view element, but ONLY when it's one the utility rail
// serves (Schedule, Onboarding-Ops or Fleet). Used so the rail's top-sync +
// push effect target the live view instead of a hardcoded #view-schedule.
function _rrUtilRailView() {
  const id = document.body && document.body.dataset ? document.body.dataset.rrActiveView : "";
  if (id === "view-schedule" || id === "view-onboarding-ops" || id === "view-fleet2") return document.getElementById(id);
  return null;
}

// ─── Auth gate ─────────────────────────────────────────────────────────────
const { data: { session } } = await sb.auth.getSession();
if (!session) {
  const next = encodeURIComponent(location.pathname + location.search);
  location.replace(`./login.html?next=${next}`);
  throw new Error("redirecting to login");
}

// When the SDK can't refresh the access token (network blip, JWT secret
// rotation, refresh-token expiry) the dashboard keeps running with cached
// state but every authenticated REST call returns 401 — RLS sees the
// caller as anon, dsp-scoped queries return 0 rows, and SECURITY DEFINER
// RPCs raise 'forbidden'.  The operator sees half-broken panels showing
// "Forbidden" / "no drivers" / "no forms" with no clue why.  Detect the
// failure and force a clean re-login instead.
// Durable, non-sensitive UI preferences that must survive a sign-out /
// forced relogin. This runs on EVERY SIGNED_OUT (see onAuthStateChange
// below), so a plain localStorage.clear() here silently reset them — most
// visibly the Messages favorites (rr_msg_favs), which vanished every time
// the operator logged out and back in. Carry these across the wipe.
const _RR_KEEP_ACROSS_RELOGIN = ["rr_msg_favs", "rr_msg_details_open"];
function _forceRelogin(reason) {
  const next = encodeURIComponent(location.pathname + location.search);
  try { sb.auth.signOut().catch(() => {}); } catch {}
  try {
    const keep = {};
    for (const k of _RR_KEEP_ACROSS_RELOGIN) {
      const v = localStorage.getItem(k);
      if (v != null) keep[k] = v;
    }
    localStorage.clear(); sessionStorage.clear();
    for (const k in keep) { try { localStorage.setItem(k, keep[k]); } catch {} }
  } catch {}
  location.replace(`./login.html?err=${encodeURIComponent(reason || "session_expired")}&next=${next}`);
  throw new Error(`force relogin: ${reason}`);
}
function _isAuthError(err) {
  if (!err) return false;
  if (err.status === 401 || err.status === 403) return true;
  if (err.code === "PGRST301" || err.code === "401" || err.code === "403") return true;
  const m = (err.message || "").toLowerCase();
  return /jwt|unauthor|expired|forbidden/.test(m);
}
window._rrForceRelogin = _forceRelogin;
// Forward the access token to the Realtime websocket so RLS-protected
// tables (applicants, cal_events, …) actually deliver postgres_changes
// to this client. supabase-js sets it on connect, but doesn't re-push
// it when autoRefreshToken rotates the JWT — so an hour into a session
// the channel goes silent and the operator has to F5 to see new state
// like a freshly-completed screening video.
sb.realtime.setAuth(session.access_token);
sb.auth.onAuthStateChange((event, newSession) => {
  if (event === "SIGNED_OUT") _forceRelogin("session_expired");
  if (newSession?.access_token) sb.realtime.setAuth(newSession.access_token);
});

// ─── MFA step-up gate (dark until RR_CONFIG.MFA_ENABLED) ────────────────────
// If MFA is enabled AND this user has a verified authenticator factor but the
// current session is only AAL1, require the 6-digit code to step up to AAL2
// before the dashboard loads. Opt-in by design: a user with NO factor is never
// blocked, so turning MFA on can't lock out anyone who hasn't enrolled. Fails
// OPEN on any MFA API error (a bug must never lock people out); only a wrong or
// absent code blocks. Lost-device recovery: an admin deletes the user's row
// from auth.mfa_factors — see docs/MFA.md.
async function _rrMfaGateOnBoot() {
  if (!(window.RR_CONFIG && window.RR_CONFIG.MFA_ENABLED)) return;
  let factorId = null;
  try {
    const { data: aal, error } = await sb.auth.mfa.getAuthenticatorAssuranceLevel();
    if (error || !aal) return;                                   // fail open
    if (aal.currentLevel === "aal2" || aal.nextLevel !== "aal2") return; // stepped up already, or no factor
    const { data: fl, error: flErr } = await sb.auth.mfa.listFactors();
    if (flErr) return;
    const totp = (fl && fl.totp && fl.totp[0]) || null;
    if (!totp || totp.status !== "verified") return;
    factorId = totp.id;
  } catch (_) { return; }

  await new Promise((resolve) => {
    const ov = document.createElement("div");
    ov.setAttribute("role", "dialog");
    ov.setAttribute("aria-modal", "true");
    ov.setAttribute("aria-label", "Two-factor verification");
    ov.style.cssText = "position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;background:#0d1320;color:#e9eef8;font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;padding:24px";
    ov.innerHTML =
      '<div style="width:100%;max-width:360px;background:#141d2c;border:1px solid rgba(150,172,205,.18);border-radius:14px;padding:28px 24px;box-shadow:0 18px 50px -24px rgba(0,0,0,.7)">' +
        '<div style="font-size:1.15rem;font-weight:680;letter-spacing:-.01em">Enter your code</div>' +
        '<p style="margin:8px 0 18px;color:#95a7c2;font-size:.92rem;line-height:1.5">Open your authenticator app and enter the current 6-digit code to finish signing in.</p>' +
        '<input id="rr-mfa-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456" ' +
          'style="width:100%;font-family:ui-monospace,Menlo,monospace;font-size:1.4rem;letter-spacing:.3em;text-align:center;padding:12px;border-radius:9px;border:1px solid rgba(150,172,205,.28);background:#0d1320;color:#e9eef8;box-sizing:border-box"/>' +
        '<div id="rr-mfa-err" style="min-height:18px;margin-top:10px;color:#e5604d;font-size:.85rem" role="alert"></div>' +
        '<button id="rr-mfa-verify" type="button" style="width:100%;margin-top:6px;padding:12px;border:none;border-radius:99px;background:#3d7bff;color:#f4f8ff;font-weight:640;font-size:.98rem;cursor:pointer">Verify</button>' +
        '<button id="rr-mfa-signout" type="button" style="width:100%;margin-top:10px;padding:10px;border:1px solid rgba(150,172,205,.28);border-radius:99px;background:transparent;color:#95a7c2;font-weight:560;font-size:.88rem;cursor:pointer">Sign out</button>' +
      '</div>';
    document.body.appendChild(ov);
    const input = ov.querySelector("#rr-mfa-code");
    const errEl = ov.querySelector("#rr-mfa-err");
    const verifyBtn = ov.querySelector("#rr-mfa-verify");
    const signoutBtn = ov.querySelector("#rr-mfa-signout");
    setTimeout(function () { if (input) input.focus(); }, 50);
    let busy = false;
    async function submit() {
      if (busy) return;
      const code = (input.value || "").replace(/\D/g, "");
      if (code.length !== 6) { errEl.textContent = "Enter the 6-digit code."; return; }
      busy = true; verifyBtn.disabled = true; verifyBtn.textContent = "Verifying…"; errEl.textContent = "";
      try {
        const { data: ch, error: chErr } = await sb.auth.mfa.challenge({ factorId });
        if (chErr) throw chErr;
        const { error: vErr } = await sb.auth.mfa.verify({ factorId, challengeId: ch.id, code });
        if (vErr) throw vErr;
        ov.remove(); resolve(); return;
      } catch (_) {
        errEl.textContent = "That code didn't work. Use the current one from your app.";
        input.value = ""; input.focus();
      } finally {
        busy = false; verifyBtn.disabled = false; verifyBtn.textContent = "Verify";
      }
    }
    verifyBtn.addEventListener("click", submit);
    input.addEventListener("keydown", function (e) { if (e.key === "Enter") submit(); });
    signoutBtn.addEventListener("click", async function () {
      try { await sb.auth.signOut(); } catch (_) {}
      location.replace("./login.html");
    });
  });
}
await _rrMfaGateOnBoot();

const { data: profile, error: profileErr } = await sb.from("app_users")
  .select("id, dsp_id, email, full_name, role, allowed_pages").eq("id", session.user.id).maybeSingle();

if (profileErr) {
  // 401 / JWT issue at boot — refresh failed.  Force re-login.
  if (_isAuthError(profileErr)) _forceRelogin("session_expired");
  console.error("profile load failed:", profileErr);
  _forceRelogin("profile_load_failed");
}
if (!profile) {
  // Auth user exists but app_users row doesn't — auth hook failed (most
  // likely a non-allowed domain that slipped through). Send to login with
  // an error.
  await sb.auth.signOut();
  location.replace("./login.html?err=no_profile");
  throw new Error("no app_users row");
}
window.RR.user = profile;
// Expose the caller's role on <body> so CSS can gate owner-only controls
// (e.g. the Settings → Export your data row) regardless of async frag load
// order: `.rr-owner-only { display:none }` + `body[data-rr-role="owner"] …`.
try { document.body.dataset.rrRole = profile.role || ""; } catch (_) {}
// Reveal the Settings → Two-factor panel only when MFA is enabled
// (`.rr-mfa-only { display:none }` + `body[data-rr-mfa="on"] …`).
try { document.body.dataset.rrMfa = (window.RR_CONFIG && window.RR_CONFIG.MFA_ENABLED) ? "on" : "off"; } catch (_) {}

// ─── Product usage analytics ────────────────────────────────────────────────
// Non-PII event log (event name + tenant + user + minimal props) → usage_events,
// so you can see whether a tenant is actually active. Batched, non-blocking,
// fails silent; disabled via RR_CONFIG.ANALYTICS_ENABLED=false. NEVER pass
// record contents or PII in props. occurred_at is the server default (now()).
const _rrEvQueue = [];
function rrTrack(event, props) {
  if (window.RR_CONFIG && window.RR_CONFIG.ANALYTICS_ENABLED === false) return;
  try {
    _rrEvQueue.push({
      dsp_id:  (window.RR && window.RR.user && window.RR.user.dsp_id) || null,
      user_id: (window.RR && window.RR.user && window.RR.user.id) || null,
      event:   String(event).slice(0, 60),
      props:   (props && typeof props === "object") ? props : {},
    });
    if (_rrEvQueue.length >= 25) _rrFlushEvents();
  } catch (_) {}
}
async function _rrFlushEvents() {
  if (!_rrEvQueue.length) return;
  if (window.RR_CONFIG && window.RR_CONFIG.ANALYTICS_ENABLED === false) { _rrEvQueue.length = 0; return; }
  const batch = _rrEvQueue.splice(0, _rrEvQueue.length);
  try { await sb.from("usage_events").insert(batch); } catch (_) { /* fail silent — telemetry never blocks */ }
}
window.rrTrack = rrTrack;
try { setInterval(_rrFlushEvents, 30000); } catch (_) {}
window.addEventListener("visibilitychange", function () { if (document.visibilityState === "hidden") _rrFlushEvents(); });
window.addEventListener("pagehide", function () { _rrFlushEvents(); });
rrTrack("session_start", { role: profile.role });

// ─── Idle session timeout ────────────────────────────────────────────────
// HR / termination / PII data on a shared dispatcher machine must not stay
// logged in indefinitely. After a stretch of no real interaction we force a
// clean re-login (signOut + storage clear via _forceRelogin). The deadline is
// pushed forward by genuine activity, throttled so we aren't re-arming the
// timer on every mousemove. Configurable via RR_CONFIG.IDLE_TIMEOUT_MINUTES;
// 0 or unset disables it. The auto-refreshed access token keeps the session
// valid server-side regardless — this is purely an inactivity guard.
(function armIdleTimeout() {
  const minutes = Number((window.RR_CONFIG && window.RR_CONFIG.IDLE_TIMEOUT_MINUTES) || 30);
  if (!(minutes > 0)) return;
  const LIMIT = minutes * 60 * 1000;
  let deadline = Date.now() + LIMIT;
  let timer = null;
  let lastBump = 0;
  function tick() {
    // A bump may have pushed the deadline out after this tick was queued;
    // reschedule rather than expiring early.
    if (Date.now() < deadline) { schedule(); return; }
    _forceRelogin("idle_timeout");
  }
  function schedule() {
    clearTimeout(timer);
    timer = setTimeout(tick, Math.max(1000, deadline - Date.now()));
  }
  function bump() {
    const now = Date.now();
    deadline = now + LIMIT;
    if (now - lastBump > 5000) { lastBump = now; schedule(); } // re-arm at most every 5s
  }
  ["mousedown", "keydown", "scroll", "touchstart", "click", "mousemove", "visibilitychange"]
    .forEach((ev) => window.addEventListener(ev, bump, { passive: true }));
  schedule();
})();

// Apply per-user sidebar hiding. Owners always see everything (so
// they can manage the team and won't accidentally lock themselves
// out). For other roles, hide top-level nav items not in their
// allowed_pages list. NULL allowed_pages = no restriction. Settings
// is always visible because that's how a restricted user appeals.
(function applyAllowedPages() {
  const allowed = profile.allowed_pages;
  if (profile.role === "owner" || profile.role === "platform_admin") return;
  if (!Array.isArray(allowed) || allowed.length === 0) return;
  const apply = () => {
    document.querySelectorAll(".nav-item[data-view]").forEach(btn => {
      const view = btn.getAttribute("data-view");
      // Settings is the one documented escape-hatch (account / sign-out must
      // always be reachable). Dashboard/Today is a real content page that
      // aggregates schedule + fleet + pipeline data and IS a togglable page
      // in the permissions catalog ({ key: "dashboard", label: "Today" }), so
      // it must honor allowed_pages like any other view — owners/admins still
      // always see it via the role short-circuit above.
      if (view === "settings") return;
      if (!allowed.includes(view)) {
        btn.style.display = "none";
      }
    });
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", apply, { once: true });
  } else {
    apply();
  }
})();

// ── First-run welcome zone ─────────────────────────────────────────────
// Shown on the dashboard view for newly-activated DSPs (within 14 days
// of dsps.activated_at) until the owner dismisses.  Dismissal writes
// metadata.first_run_dismissed_at so it survives across devices /
// browsers (vs. localStorage).
//
// Existing DSPs have activated_at backfilled by migration 0126 to
// their created_at, so any DSP older than 14 days at migration time
// never sees the banner — important for not surprising long-time
// operators with a "Welcome!" message.
function _initFirstRunZone() {
  const zone = document.getElementById("rr-firstrun");
  if (!zone) return;
  const dsp = window.RR?.dsp;
  if (!dsp) return;
  const activated = dsp.activated_at ? new Date(dsp.activated_at).getTime() : null;
  const dismissed = dsp.metadata?.first_run_dismissed_at
    ? new Date(dsp.metadata.first_run_dismissed_at).getTime()
    : null;
  const ageMs = activated ? (Date.now() - activated) : Infinity;
  const isFresh = activated != null && ageMs < (14 * 24 * 60 * 60 * 1000);
  // Platform admins skip the welcome — admin tooling is their
  // surface, and a "Welcome to RouteReady" banner reads weird when
  // they're managing customers.
  if (profile.role === "platform_admin") return;
  if (!isFresh || dismissed) return;

  // Suffix with the owner's first name (from app_users.full_name).
  const firstName = (profile.full_name || "").split(/\s+/)[0];
  const suffix = document.getElementById("rr-firstrun-name-suffix");
  if (suffix && firstName) suffix.textContent = `, ${firstName}`;
  zone.hidden = false;

  // Live progress · check off steps whose data already exists. Cheap
  // head-only count queries (RLS scopes them to this DSP); each tile
  // flips to .done independently as its count lands. Failures are
  // non-fatal — a step just stays unchecked.
  const _frChecks = [
    ["drivers",  "drivers"],
    ["vans",     "vehicles"],
    ["schedule", "shifts"],
  ];
  for (const [step, table] of _frChecks) {
    sb.from(table).select("id", { count: "exact", head: true }).then(({ count, error }) => {
      if (error || !count) return;
      const tile = zone.querySelector(`[data-fr-step="${step}"]`);
      if (!tile || tile.classList.contains("done")) return;
      tile.classList.add("done");
      const num = tile.querySelector(".rr-firstrun-tile-num");
      if (num) num.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" style="width:13px;height:13px"><polyline points="20 6 9 17 4 12"/></svg>';
    }).catch(() => {});
  }

  document.getElementById("rr-firstrun-dismiss")?.addEventListener("click", async () => {
    zone.hidden = true;
    const nowIso = new Date().toISOString();
    const newMeta = Object.assign({}, dsp.metadata || {}, { first_run_dismissed_at: nowIso });
    // Optimistic local update so a re-paint doesn't flash the banner.
    if (window.RR?.dsp) window.RR.dsp.metadata = newMeta;
    const { error } = await sb.from("dsps").update({ metadata: newMeta }).eq("id", dsp.id);
    if (error) {
      // Non-fatal: banner is hidden in-session even if persistence
      // failed.  Log so we know about it.
      console.warn("first_run_dismissed_at persist failed:", error);
    }
  });
}
// Defer the call until DOM is settled (the welcome zone lives inside
// the dashboard view, mounted after live.js's top-level await).
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", _initFirstRunZone, { once: true });
} else {
  _initFirstRunZone();
}

// ── Onboarding wizard gate ─────────────────────────────────────────────
// Newly-provisioned DSP owners land in the dashboard with their workspace
// in status='pending' or 'onboarding'.  Until they finish the wizard,
// the regular dashboard chrome is hidden and #view-onboarding takes
// over the screen.  Migration 0126 backfilled status='active' DSPs to
// onboarding_step='complete', so existing workspaces (Air Capital
// Logistics, etc.) bypass the wizard cleanly.
//
// Platform admins skip the wizard for their own DSP — admin tooling is
// the right surface for them, not the customer-flavored onboarding.
if (window.RR.dsp
    && (window.RR.dsp.status === "pending" || window.RR.dsp.status === "onboarding")
    && profile.role !== "platform_admin") {
  document.body.dataset.rrOnboarding = "1";
  // Defer the actual wizard mount until DOM is fully present (post-await
  // module timing means the body exists but mutation observers might
  // not be ready).
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => _mountOnboarding(), { once: true });
  } else {
    _mountOnboarding();
  }
}

// Reveal the platform-admin nav-item only for users who actually have
// that role.  The button is `display:none` by default in the HTML, so
// regular owners / dispatchers / drivers never see it.  See the
// 0124_platform_admin.sql migration + bootstrap for how to grant the
// role.  All cross-tenant data calls go through admin_* RPCs, each of
// which re-checks is_platform_admin() in its body — hiding the nav
// item is UX, not security.
(function revealPlatformAdminNav() {
  if (profile.role !== "platform_admin") return;
  const apply = () => {
    document.querySelectorAll('.nav-item[data-rr-platform-admin-only="1"]').forEach((btn) => {
      btn.style.display = "";
    });
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", apply, { once: true });
  } else {
    apply();
  }
})();

const { data: dspRow, error: dspErr } = await sb.from("dsps")
  .select("id, name, short_code, timezone, metadata").eq("id", profile.dsp_id).single();
if (dspErr || !dspRow || !dspRow.id) {
  // .single() on dsps fails when (a) the JWT was rejected so RLS sees
  // the caller as anon and returns 0 rows, or (b) profile.dsp_id is
  // genuinely missing/wrong.  Either way, every dsp-scoped query
  // downstream would silently return 0 rows or 401.  Don't paint a
  // half-broken UI — bounce through login with an explanation.
  console.error("dsp load failed:", dspErr, "profile.dsp_id:", profile.dsp_id);
  _forceRelogin(_isAuthError(dspErr) ? "session_expired" : "dsp_unresolved");
}
window.RR.dsp = dspRow;
// Route color-coding choices live on dsps.metadata.route_colors so they
// follow the operator across devices. The picker IIFE (index.html) paints
// from localStorage/defaults at parse time (before the DSP is loaded);
// now that the account is in memory, re-apply so account colors win.
try { if (typeof window._rrReapplyRouteColors === "function") window._rrReapplyRouteColors(); } catch (_) {}

// ─── Per-DSP entitlements · platform-admin page/feature gating ──────────
// A platform admin can turn top-level pages (nav modules) and in-app
// features off for an entire DSP from the control center.  The choice
// lives on dsps.metadata as two opt-out lists:
//
//     metadata.disabled_pages    → data-view keys hidden from the sidebar
//     metadata.disabled_features → feature keys whose entry buttons hide
//
// Absent = everything enabled.  We enforce with a single injected
// <style> block rather than per-element JS: the nav items exist at parse
// time but the feature buttons live inside view frags that are injected
// lazily on first navigation, so a stylesheet is the only approach that
// covers markup which doesn't exist yet.  `settings` and `admin` are
// never gateable (a restricted user must keep a way back / the admin
// surface is platform-admin-only anyway).
//
// Catalog is shared with the control center via window.RR_ENTITLEMENTS
// so the admin drawer and this gate can never drift apart.
window.RR_ENTITLEMENTS = {
  pages: [
    { key: "schedule",       label: "Schedule",   desc: "Routes, dispatch & the daily board" },
    { key: "onboarding-ops", label: "Onboarding", desc: "New-hire onboarding workflow" },
    { key: "fleet2",         label: "Fleet",      desc: "Vehicles, maintenance & assignments" },
    { key: "workbooks",      label: "Workbooks",  desc: "Spreadsheets & saved reports" },
    { key: "messages",       label: "Messages",   desc: "Driver & team messaging" },
    { key: "email",          label: "Email",      desc: "Connected email inbox" },
    { key: "recognition",    label: "Recognition",desc: "Kudos & awards page" },
  ],
  features: [
    { key: "notes",      label: "Notes",             desc: "Quick notes panel",            sel: "[data-rr-notes-toggle]" },
    { key: "tasks",      label: "My Tasks",          desc: "Personal task list",           sel: "[data-rr-tasks-toggle]" },
    { key: "checklists", label: "Checklists",        desc: "Shift checklists",             sel: "[data-rr-checklists-toggle]" },
    { key: "contacts",   label: "Contacts",          desc: "Station contacts directory",   sel: "[data-rr-contacts-toggle]" },
    { key: "ophealth",   label: "Operations Health", desc: "Live ops-health readout",      sel: "[data-rr-ophealth-toggle]" },
    { key: "forms",      label: "Forms panel",       desc: "Quick-forms side panel",       sel: "[data-rr-forms-toggle]" },
    { key: "recog",      label: "Kudos panel",       desc: "Recognition quick panel",      sel: "[data-rr-recog-toggle]" },
    { key: "receipts",   label: "Receipts panel",    desc: "Driver receipt review & reconcile", sel: "[data-rr-receipts-toggle]" },
  ],
};

(function applyDspEntitlements() {
  const md = window.RR?.dsp?.metadata || {};
  const disabledPages    = Array.isArray(md.disabled_pages)    ? md.disabled_pages    : [];
  const disabledFeatures = Array.isArray(md.disabled_features) ? md.disabled_features : [];
  const cat = window.RR_ENTITLEMENTS;
  const rules = [];
  disabledPages.forEach((key) => {
    if (key === "settings" || key === "admin") return;
    // data-view is a static, sanitised key from our own catalog; guard
    // anyway so a malformed metadata value can't break the selector.
    if (!/^[a-z0-9-]+$/.test(key)) return;
    rules.push(`.nav-item[data-view="${key}"]{display:none !important}`);
  });
  disabledFeatures.forEach((key) => {
    const f = cat.features.find((x) => x.key === key);
    if (f && f.sel) rules.push(`${f.sel}{display:none !important}`);
  });
  let styleEl = document.getElementById("rr-dsp-entitlements");
  if (!rules.length) { if (styleEl) styleEl.remove(); return; }
  if (!styleEl) {
    styleEl = document.createElement("style");
    styleEl.id = "rr-dsp-entitlements";
    (document.head || document.documentElement).appendChild(styleEl);
  }
  styleEl.textContent = rules.join("\n");
})();

// ─── Operator activity ping ────────────────────────────────────────────
// Bump dsps.last_seen_at so the platform-admin console shows *real* last
// activity instead of the newest-teammate-signup proxy.  Fire-and-forget,
// throttled to ~once/hour per browser so a reload storm doesn't hammer the
// row.  Failure is silent — this is telemetry, never load-bearing.
(function pingDspActivity() {
  try {
    const dspId = window.RR?.dsp?.id;
    if (!dspId) return;
    const key = `rr-touch:${dspId}`;
    const last = Number(localStorage.getItem(key) || 0);
    if (Date.now() - last < 3600000) return;
    localStorage.setItem(key, String(Date.now()));
    sb.rpc("touch_dsp_activity").then(({ error }) => {
      if (error) localStorage.removeItem(key); // let the next boot retry
    }).catch(() => { try { localStorage.removeItem(key); } catch (_) {} });
  } catch (_) { /* telemetry only */ }
})();

// ─── Brand · paint DSP name + station code into the sidebar chip ────────
// The chip in dashboard/index.html is a static placeholder ("Cardinal
// Logistics") so the file looks fine in a static preview. Replace it
// with the live DSP record so the operator sees their own brand, and
// re-paint after the Workspace settings save.
function _paintWorkspaceChip() {
  const dsp = window.RR?.dsp;
  if (!dsp) return;
  const name   = dsp.name || "Workspace";
  const code   = dsp.short_code || "";
  const initials = name
    .split(/\s+/).filter(Boolean).slice(0, 2)
    .map((w) => w[0]?.toUpperCase() || "").join("") || "··";
  const elName   = document.getElementById("rr-workspace-chip-name");
  const elSub    = document.getElementById("rr-workspace-chip-sub");
  const elAvatar = document.getElementById("rr-workspace-chip-avatar");
  if (elName)   elName.textContent = name;
  if (elSub)    elSub.textContent  = code ? `DSP · ${code}` : "DSP";
  if (elAvatar) elAvatar.textContent = initials;
  // Top-of-sidebar brand wordmark stays "RouteReady" (the platform
  // brand the operator pays for); the operator's DSP name lives in
  // the workspace chip below it.
  document.title = `${name} · Dispatcher`;
  // Surface the DSP's team email under the Fleet Bridge view title
  // so operators always see what address vendors will see on their
  // outbound mail. Computed from short_code → mail.gorouteready.com.
  const fbSub = document.getElementById("rr-fb-team-email");
  if (fbSub && typeof _fbEmailFromCode === "function") {
    fbSub.textContent = _fbEmailFromCode(code);
  }
}
_paintWorkspaceChip();

// ── Header account chip · initials + name/email in the account menu.
// Companion to _paintWorkspaceChip; ids live in the topbar markup.
function _paintHeaderAccount() {
  const display = (profile && profile.full_name) || window.RR?.user?.email || "Operator";
  const initials = String(display).split(/[\s@.]+/).filter(Boolean).slice(0, 2)
    .map((w) => w[0]?.toUpperCase() || "").join("") || "U";
  const av = document.getElementById("rr-hdr-avatar");
  if (av) av.textContent = initials;
  const nm = document.getElementById("rr-hdr-account-name");
  if (nm) nm.textContent = (profile && profile.full_name) || "Operator";
  const em = document.getElementById("rr-hdr-account-email");
  if (em) em.textContent = window.RR?.user?.email || "";
}
_paintHeaderAccount();

// ── Real header notifications · v1 ─────────────────────────────────
// Paints PENDING time-off requests into #rr-notif-list and lights the
// bell dot. Replaces the retired mockup items — a signed-in operator
// must never see fake operational data. Swap-offer notifications can
// join once their query shape is confirmed.
async function _rrLoadNotifications() {
  const list = document.getElementById("rr-notif-list");
  if (!list || !window.RR?.dsp?.id) return;
  try {
    const [toRes, drvRes] = await Promise.all([
      sb.from("time_off_requests")
        .select("id, driver_id, start_date, end_date, status, created_at")
        .eq("dsp_id", window.RR.dsp.id)
        .eq("status", "pending")
        .order("created_at", { ascending: false })
        .limit(8),
      sb.from("drivers").select("id, full_name, preferred_name").eq("dsp_id", window.RR.dsp.id),
    ]);
    if (toRes.error) return;   // leave the honest empty state
    const nameById = new Map((drvRes.data || []).map((d) => [d.id, d.preferred_name || d.full_name || "Driver"]));
    const items = (toRes.data || []);
    const dot = document.querySelector('#rr-hdr-notif .dot');
    // block (not '') — the stylesheet hides the dot by default, so an
    // empty inline value would fall back to display:none (Codex P2).
    if (dot) dot.style.display = items.length ? "block" : "none";
    if (!items.length) return; // keep "You're all caught up"
    const fmt = (iso) => new Date(iso + "T12:00:00").toLocaleDateString(undefined, { month: "short", day: "numeric" });
    const _rrRelTime = (ts) => {
      if (!ts) return "";
      const s = Math.floor((Date.now() - new Date(ts).getTime()) / 1000);
      if (s < 60) return "just now";
      if (s < 3600) return `${Math.floor(s / 60)}m ago`;
      if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
      return `${Math.floor(s / 86400)}d ago`;
    };
    list.innerHTML = items.map((r) => `
      <div class="notif-item" data-rr-notif-timeoff="1">
        <div class="notif-icon amber"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg></div>
        <div><div class="notif-title">${escapeHtml(nameById.get(r.driver_id) || "Driver")} · time off request</div><div class="notif-msg">${fmt(r.start_date)} – ${fmt(r.end_date)} awaiting approval</div><div class="notif-time">${_rrRelTime(r.created_at)}</div></div>
      </div>`).join("");
    list.querySelectorAll("[data-rr-notif-timeoff]").forEach((el) => el.addEventListener("click", () => {
      window._rrGotoSubIntent = { view: "schedule", sub: "requests" };
      window.goto?.("schedule");
      window.closePopovers?.();
    }));
  } catch (_) { /* honest empty state remains */ }
}
_rrLoadNotifications();

// Sign out from the account menu — ends the Supabase session and
// returns to the sign-in page.
document.addEventListener("click", async (e) => {
  if (!e.target.closest || !e.target.closest("#rr-hdr-signout")) return;
  e.preventDefault();
  try { await sb.auth.signOut(); } catch (_) {}
  location.replace("./login.html");
});

// ─── Tiny DOM helpers ──────────────────────────────────────────────────────
const $  = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

// ─── Driver photos · paint avatars wherever they show up ───────────────
// The roster, schedule grid, coaching feed, message list, etc. all
// render <div class="avatar-sm">XY</div> with the driver's initials.
// Rather than touch every render site, we cache the photo URL per
// driver once and walk the DOM after each render painting a CSS
// background-image on every avatar near a [data-rr-driver-id] node.
//
// This means a driver who uploads a photo on the PWA shows up across
// the dispatcher dashboard automatically, and adding a new avatar
// somewhere later doesn't require remembering to wire up the photo.
const _driverPhotos = { loaded: null, map: new Map() };

async function _loadDriverPhotos() {
  if (_driverPhotos.loaded) return _driverPhotos.loaded;
  _driverPhotos.loaded = (async () => {
    const dspId = window.RR?.dsp?.id;
    if (!dspId) return _driverPhotos.map;
    const { data, error } = await sb.from("drivers")
      .select("id, photo_path")
      .eq("dsp_id", dspId)
      .not("photo_path", "is", null);
    if (error) { console.warn("loadDriverPhotos:", error); return _driverPhotos.map; }
    // driver-photos is a PRIVATE bucket (migration 0446) — sign the paths.
    // Batch-sign once here; every avatar surface reads the signed URL from
    // this map (keyed by driver id) via _driverPhotoUrl().
    const rows = (data || []).filter((r) => r.photo_path);
    const byPath = new Map(rows.map((r) => [r.photo_path, r.id]));
    try {
      const { data: signed } = await sb.storage
        .from("driver-photos")
        .createSignedUrls(rows.map((r) => r.photo_path), 60 * 60 * 8);
      for (const s of (signed || [])) {
        if (s && s.path && s.signedUrl && !s.error) {
          const id = byPath.get(s.path);
          if (id) _driverPhotos.map.set(id, s.signedUrl);
        }
      }
    } catch (e) { console.warn("signDriverPhotos:", e); }
    return _driverPhotos.map;
  })();
  return _driverPhotos.loaded;
}

// Signed driver-photo URL for a driver id, or a "<driver_id>/…" storage path.
// Backed by the pre-signed _driverPhotos map; returns null (→ initials) when
// the driver has no photo or the map hasn't loaded yet.
function _driverPhotoUrl(idOrPath) {
  if (!idOrPath) return null;
  const s = String(idOrPath);
  const id = s.includes("/") ? s.split("/")[0] : s;
  return _driverPhotos.map.get(id) || null;
}

function _resolveDriverIdForAvatar(el) {
  // Direct attribute on the avatar itself (cal-row-label, etc.)
  let id = el.getAttribute("data-rr-driver-id");
  if (id) return id;
  // Walk up the tree. Some renders put the id on a deep wrapper
  // (.cell-driver row -> <tr data-driver-id>), some on a sibling
  // text node (.cell-name[data-rr-driver-id]), some on the row
  // itself. We try each ancestor in turn until we find one.
  let cur = el.parentElement;
  while (cur && cur !== document.body) {
    if (cur.dataset?.rrDriverId)        return cur.dataset.rrDriverId;
    if (cur.dataset?.driverId)          return cur.dataset.driverId;
    if (cur.dataset?.rrCoachFeedDriver) return cur.dataset.rrCoachFeedDriver;
    const tagged = cur.querySelector?.("[data-rr-driver-id]");
    if (tagged) return tagged.getAttribute("data-rr-driver-id");
    // Stop at row-style boundaries so we don't bleed into a sibling
    // driver's id when an avatar lives inside a wider container.
    // (.cell-driver is a per-cell wrapper, NOT a row — keep walking.)
    if (cur.matches?.("tr, .msg-item, .cal-row-label, .checkin-row, .iv-card, .driver-row, .dr-coach-row")) return null;
    cur = cur.parentElement;
  }
  return null;
}

function _paintDriverAvatars(root) {
  if (_driverPhotos.map.size === 0) return;
  const scope = root && root.querySelectorAll ? root : document;
  scope.querySelectorAll(".avatar-sm").forEach((el) => {
    if (el.dataset.rrPhotoPainted) return;
    // Opt-out for branded / non-driver avatars (e.g. RouteReady Support).
    if (el.dataset.rrNoPhoto) return;
    const id = _resolveDriverIdForAvatar(el);
    if (!id) return;
    const url = _driverPhotos.map.get(id);
    if (!url) return;
    el.style.backgroundImage    = `url('${url}')`;
    el.style.backgroundSize     = "cover";
    el.style.backgroundPosition = "center";
    el.style.color              = "transparent"; // hide initials
    el.dataset.rrPhotoPainted   = "1";
  });
}

// Repaint after any DOM change. Debounced so a heavy render doesn't
// cause a flood — one paint pass after the dust settles is enough.
let _paintTimer = null;
function _schedulePaint() {
  if (_paintTimer) return;
  _paintTimer = setTimeout(() => { _paintTimer = null; _paintDriverAvatars(document); }, 50);
}

_loadDriverPhotos().then(() => {
  _paintDriverAvatars(document);
  new MutationObserver(_schedulePaint).observe(document.body, { childList: true, subtree: true });
});

// Public hook so a freshly-uploaded photo (e.g. via the driver record
// drawer in the future) can refresh without a page reload.
window.RR.refreshDriverPhotos = async function () {
  _driverPhotos.loaded = null;
  _driverPhotos.map.clear();
  document.querySelectorAll(".avatar-sm[data-rr-photo-painted]").forEach((el) => {
    el.style.backgroundImage = "";
    el.style.color = "";
    delete el.dataset.rrPhotoPainted;
  });
  await _loadDriverPhotos();
  _paintDriverAvatars(document);
};

function toast(msg, kind) {
  if (typeof window.toast === "function") return window.toast(msg, kind);
  console.log("[toast]", kind ?? "", msg);
}

// Settings → Export your data. Owner-only (also enforced server-side by the
// export_my_dsp_data RPC). Pulls the tenant's core HR/ops data as one JSON
// bundle and downloads it — data portability / the floor of a DSR workflow.
async function rrExportMyData(btn) {
  if (window.RR?.user?.role !== "owner") {
    toast("Only the owner can export tenant data.", "warn");
    return;
  }
  const label = btn ? btn.textContent : "";
  if (btn) { btn.disabled = true; btn.textContent = "Exporting…"; }
  try {
    const { data, error } = await sb.rpc("export_my_dsp_data");
    if (error) throw error;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const slug = (window.RR?.user?.dsp_id || "dsp").slice(0, 8);
    const stamp = new Date().toISOString().slice(0, 10);
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `routeready-export-${slug}-${stamp}.json`;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 0);
    toast("Your data export downloaded.", "success");
    try { rrTrack("export_data"); } catch (_) {}
  } catch (e) {
    if (typeof _isAuthError === "function" && _isAuthError(e)) { _forceRelogin("session_expired"); return; }
    toast("Export failed — " + (e?.message || "please try again."), "warn");
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = label; }
  }
}
window.rrExportMyData = rrExportMyData;

// Settings → Export document files. Owner-only (also enforced by the
// export-tenant-files edge function). Downloads a JSON manifest of fresh,
// 1-hour signed download links for every driver-document FILE in the tenant —
// the bytes the metadata export can't include.
async function rrExportMyFiles(btn) {
  if (window.RR?.user?.role !== "owner") {
    toast("Only the owner can export files.", "warn");
    return;
  }
  const label = btn ? btn.textContent : "";
  if (btn) { btn.disabled = true; btn.textContent = "Preparing…"; }
  try {
    const { data, error } = await sb.functions.invoke("export-tenant-files");
    if (error) throw error;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const slug = (window.RR?.user?.dsp_id || "dsp").slice(0, 8);
    const stamp = new Date().toISOString().slice(0, 10);
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `routeready-files-${slug}-${stamp}.json`;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 0);
    const n = (data && typeof data.count === "number") ? data.count : 0;
    toast(`File manifest downloaded — ${n} link${n === 1 ? "" : "s"}, valid 1 hour.`, "success");
    try { rrTrack("export_files", { count: n }); } catch (_) {}
  } catch (e) {
    if (typeof _isAuthError === "function" && _isAuthError(e)) { _forceRelogin("session_expired"); return; }
    toast("File export failed — " + (e?.message || "please try again."), "warn");
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = label; }
  }
}
window.rrExportMyFiles = rrExportMyFiles;

// ─── Two-factor (TOTP) enrollment · Settings → Two-factor ───────────────────
// Only wired when RR_CONFIG.MFA_ENABLED (the panel is CSS-hidden otherwise).
// Supabase returns the QR as an SVG in enroll().data.totp.qr_code, so no QR
// library is needed. A factor must be verified once (challenge+verify) to
// activate; after that the boot gate challenges for it at login.
async function rrMfaRefreshStatus() {
  const statusEl = document.getElementById("rr-mfa-status");
  const setupBtn = document.getElementById("rr-mfa-setup-btn");
  const offBtn   = document.getElementById("rr-mfa-off-btn");
  if (!statusEl) return;
  try {
    const { data, error } = await sb.auth.mfa.listFactors();
    if (error) throw error;
    const verified = ((data && data.totp) || []).filter((f) => f.status === "verified");
    const on = verified.length > 0;
    statusEl.textContent = on
      ? "Two-factor is ON for your account."
      : "Two-factor is off. Set it up to require a code at sign-in.";
    statusEl.style.color = on ? "var(--good, #16965c)" : "";
    if (setupBtn) setupBtn.style.display = on ? "none" : "";
    if (offBtn)   offBtn.style.display   = on ? "" : "none";
  } catch (_) {
    statusEl.textContent = "";
  }
}
window.rrMfaRefreshStatus = rrMfaRefreshStatus;

async function rrMfaSetup(btn) {
  const host = document.getElementById("rr-mfa-enroll");
  if (!host) return;
  if (btn) { btn.disabled = true; btn.textContent = "Starting…"; }
  try {
    // Clear any half-finished unverified factor so re-running is clean.
    try {
      const { data: existing } = await sb.auth.mfa.listFactors();
      for (const f of ((existing && existing.totp) || [])) {
        if (f.status !== "verified") await sb.auth.mfa.unenroll({ factorId: f.id });
      }
    } catch (_) {}
    const { data, error } = await sb.auth.mfa.enroll({ factorType: "totp", friendlyName: "Authenticator" });
    if (error) throw error;
    const factorId = data.id;
    const qr = data.totp && data.totp.qr_code ? data.totp.qr_code : "";
    const secret = data.totp && data.totp.secret ? data.totp.secret : "";
    host.style.display = "block";
    host.innerHTML =
      '<div style="display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start">' +
        '<div style="background:#fff;padding:10px;border-radius:10px;line-height:0">' + qr + '</div>' +
        '<div style="flex:1;min-width:220px">' +
          '<div class="form-help">Scan this with Google Authenticator, Authy, or 1Password — then enter the 6-digit code it shows.</div>' +
          '<div class="u-xs-subtle" style="margin-top:8px;font-family:ui-monospace,Menlo,monospace;word-break:break-all">Manual key: ' + escapeHtml(secret) + '</div>' +
          '<div style="display:flex;gap:var(--s-2);align-items:center;margin-top:12px;flex-wrap:wrap">' +
            '<input id="rr-mfa-activate-code" class="form-input" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456" style="max-width:130px;letter-spacing:.15em;text-align:center"/>' +
            '<button class="btn btn-sm btn-primary" type="button" id="rr-mfa-activate-btn">Activate</button>' +
          '</div>' +
          '<div id="rr-mfa-activate-err" style="min-height:16px;margin-top:8px;color:var(--bad,#cf4433);font-size:.85rem" role="alert"></div>' +
        '</div>' +
      '</div>';
    const codeEl = document.getElementById("rr-mfa-activate-code");
    const actBtn = document.getElementById("rr-mfa-activate-btn");
    const errEl  = document.getElementById("rr-mfa-activate-err");
    if (codeEl) setTimeout(() => codeEl.focus(), 50);
    async function activate() {
      const code = (codeEl.value || "").replace(/\D/g, "");
      if (code.length !== 6) { errEl.textContent = "Enter the 6-digit code."; return; }
      actBtn.disabled = true; actBtn.textContent = "Activating…"; errEl.textContent = "";
      try {
        const { data: ch, error: chErr } = await sb.auth.mfa.challenge({ factorId });
        if (chErr) throw chErr;
        const { error: vErr } = await sb.auth.mfa.verify({ factorId, challengeId: ch.id, code });
        if (vErr) throw vErr;
        host.style.display = "none"; host.innerHTML = "";
        toast("Two-factor is on. You'll enter a code next time you sign in.", "success");
        try { rrTrack("mfa_enroll"); } catch (_) {}
        rrMfaRefreshStatus();
      } catch (_) {
        errEl.textContent = "That code didn't work. Use the current one from your app.";
        actBtn.disabled = false; actBtn.textContent = "Activate";
      }
    }
    if (actBtn) actBtn.addEventListener("click", activate);
    if (codeEl) codeEl.addEventListener("keydown", (e) => { if (e.key === "Enter") activate(); });
  } catch (e) {
    toast("Couldn't start two-factor setup — " + (e?.message || "try again."), "warn");
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = "Set up"; }
  }
}
window.rrMfaSetup = rrMfaSetup;

async function rrMfaDisable(btn) {
  if (!confirm("Turn off two-factor for your account? You'll sign in with just the email link again.")) return;
  if (btn) { btn.disabled = true; btn.textContent = "Turning off…"; }
  try {
    const { data, error } = await sb.auth.mfa.listFactors();
    if (error) throw error;
    for (const f of ((data && data.totp) || [])) {
      await sb.auth.mfa.unenroll({ factorId: f.id });
    }
    toast("Two-factor turned off.", "info");
    rrMfaRefreshStatus();
  } catch (e) {
    toast("Couldn't turn off two-factor — " + (e?.message || "try again."), "warn");
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = "Turn off"; }
  }
}
window.rrMfaDisable = rrMfaDisable;

// ─── Set / change password · Settings → Workspace → Password ────────────────
// Lets a signed-in user set (or change) the password they use for email +
// password sign-in, straight from the dashboard — no reset email needed.
// Works for magic-link-only accounts too: updateUser just adds the password.
async function rrSetPassword(btn) {
  const p1 = document.getElementById("rr-set-password");
  const p2 = document.getElementById("rr-set-password-confirm");
  const status = document.getElementById("rr-set-password-status");
  const pass = (p1 && p1.value) || "";
  const conf = (p2 && p2.value) || "";
  if (status) status.textContent = "";
  if (pass.length < 8) { toast("Password must be at least 8 characters.", "warn"); return; }
  if (pass !== conf)   { toast("Passwords don't match.", "warn"); return; }
  if (btn) { btn.disabled = true; btn.textContent = "Saving…"; }
  try {
    const { error } = await sb.auth.updateUser({ password: pass });
    if (error) throw error;
    if (p1) p1.value = "";
    if (p2) p2.value = "";
    if (status) { status.textContent = "Password saved. You can now sign in with your email and password."; status.style.color = "var(--good, #16965c)"; }
    toast("Password saved.", "success");
    try { rrTrack("password_set"); } catch (_) {}
  } catch (e) {
    toast("Couldn't save password — " + (e?.message || "try again."), "warn");
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = "Save password"; }
  }
}
window.rrSetPassword = rrSetPassword;

// Populate the panel's status once at boot when MFA is on (best-effort; the
// frag may still be loading, in which case rrMfaRefreshStatus no-ops and the
// user's first click on Set up still works).
if (window.RR_CONFIG && window.RR_CONFIG.MFA_ENABLED) {
  setTimeout(() => { try { rrMfaRefreshStatus(); } catch (_) {} }, 2500);
}

// Actionable toast — a blocking warning the operator can resolve in one
// click (see mock-wiring.js toastAction). Falls back to a plain confirm()
// so the fix path still works if the rich toast isn't available.
function toastAction(msg, opts) {
  if (typeof window.toastAction === "function") return window.toastAction(msg, opts);
  opts = opts || {};
  if (opts.onConfirm && typeof confirm === "function" && confirm(String(msg || "").replace(/<[^>]+>/g, ""))) {
    try { opts.onConfirm(); } catch (e) { console.warn("[toastAction fallback]", e); }
  } else if (opts.onDismiss) {
    try { opts.onDismiss(); } catch (_) {}
  }
  return null;
}

function fmtDate(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  return d.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}

// ─── Pipeline render ───────────────────────────────────────────────────────

const STAGE_LABELS = {
  applied: "Applied",
  screened: "Screening",
  booking_pending: "Booking pending",
  booking_scheduled: "Booking scheduled",
  hired: "Hired",
};

// Stage → recommended next action.  Shipped to the operator as the
// "Recommended next step" card on every applicant; the headline + sub
// line read naturally next to the action button beneath them.
function _recommendedNextStep(a) {
  switch (a.pipeline_stage) {
    case "applied":
      return { headline: "Send the screening invite", sub: "Applicant hasn't started their screening yet.", btn: "Resend screening", action: "resend_screening" };
    case "screened":
      return { headline: "Move to booking", sub: a.video_url ? "Video completed. Review and send the booking link." : "Screening complete. Send the booking link.", btn: "Send booking link", action: "send_link" };
    case "booking_pending":
      return { headline: "Nudge the applicant", sub: "Booking link sent — waiting on the candidate to pick a slot.", btn: "Resend booking link", action: "resend_link" };
    case "booking_scheduled":
      return { headline: "Interview is scheduled", sub: a.next_event_starts_at ? `Confirmed for ${fmtDate(a.next_event_starts_at)}.` : "Confirmed slot is on the calendar.", btn: "Reschedule", action: "reschedule" };
    case "hired":
      return { headline: "Start onboarding", sub: "Move them into Onboarding to begin paperwork.", btn: "Open onboarding", action: "open_onboarding" };
    default:
      return { headline: "Review applicant", sub: "Open to see the latest detail.", btn: "View", action: "noop" };
  }
}

// Pick the most stage-relevant timestamp for "time in stage" / sub-row
// math so we don't show a flat "30 days ago" on every applicant.
function _stageAnchorIso(a) {
  switch (a.pipeline_stage) {
    case "applied":           return a.created_at;
    case "screened":          return a.screening_completed_at || a.created_at;
    case "booking_pending":   return a.last_sms_at || a.screening_completed_at || a.created_at;
    case "booking_scheduled": return a.next_event_starts_at || a.last_sms_at || a.created_at;
    case "hired":             return a.last_sms_at || a.created_at;
    default:                  return a.created_at;
  }
}

function _fmtDurationShort(ms) {
  if (!ms || ms < 0) return "—";
  const s = Math.floor(ms / 1000);
  if (s < 60)      return `${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60)      return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24)      return `${h}h ${m % 60}m`;
  const d = Math.floor(h / 24);
  if (d < 30)      return `${d}d`;
  const mo = Math.floor(d / 30);
  return `${mo}mo`;
}

// "Today, 10:24 AM" / "Yesterday, 10:24 AM" / "May 16, 10:24 AM"
function _fmtAbsTouch(iso) {
  if (!iso) return "—";
  const d   = new Date(iso);
  const now = new Date();
  const sameDay = d.toDateString() === now.toDateString();
  const yest    = new Date(now.getTime() - 86400000).toDateString() === d.toDateString();
  const time    = d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  if (sameDay) return `Today, ${time}`;
  if (yest)    return `Yesterday, ${time}`;
  return `${d.toLocaleDateString(undefined, { month: "short", day: "numeric" })}, ${time}`;
}

// Whether a screening invite has gone out. `last_sms_at` is only stamped when
// an SMS actually delivers (and never for email-only sends), but
// send_screening_link flips status applied→contacted synchronously — so key off
// status too, otherwise clicking "Send screening" appears to do nothing.
const _SENT_STATUSES = new Set(["contacted", "screening_started"]);
function _screeningInviteSent(a) {
  return !!a.last_sms_at || _SENT_STATUSES.has(a.status);
}

// "Added {date} · {N days ago}" on each card. DSPs use applicant *age* to
// decide when to stop chasing a stale lead ("cut and run"), so we show the
// date plus a relative age, and escalate the colour as it gets old: subtle
// under 2 weeks, amber at 2+ weeks, red at a month+.
function _addedBadge(a) {
  if (!a.created_at) return "";
  const d = new Date(a.created_at);
  if (isNaN(d)) return "";
  const date = d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
  const days = Math.max(0, Math.floor((Date.now() - d.getTime()) / 86400000));
  const ageTxt = days === 0 ? "today" : days === 1 ? "1 day ago" : `${days} days ago`;
  // Neutral meta — staleness is conveyed by the Action-needed tab + stage chip,
  // so the "Added …" line no longer colours itself amber/red (kept the page
  // calm, colour lives in the stage chip).
  const tone = "var(--text-subtle)";
  return `<div class="pa-id-added" style="color:${tone};font-variant-numeric:tabular-nums;font-size:var(--fs-xs)">Added ${escapeHtml(date)} · ${escapeHtml(ageTxt)}</div>`;
}

// Time-in-stage chip · how long the applicant has sat in their CURRENT stage
// (distinct from the neutral "Added" age above). Only the stages where waiting
// is actionable age — applied / screened / booking_pending — since scheduled
// and hired are settled. Stays a quiet neutral duration until it passes a
// per-stage target, then picks up a subtle amber "overdue" chip so a recruiter
// can scan the list for who's stuck without the whole page shouting.
const _STAGE_SLA_DAYS = { applied: 2, screened: 2, booking_pending: 3 };
function _stageAgeChip(a) {
  const stage = a.pipeline_stage;
  if (!(stage in _STAGE_SLA_DAYS)) return "";
  const iso = _stageAnchorIso(a);
  const t = iso ? new Date(iso).getTime() : NaN;
  if (isNaN(t)) return "";
  const days = Math.floor((Date.now() - t) / 86400000);
  if (days < 0) return "";
  const overdue = days >= _STAGE_SLA_DAYS[stage];
  // Short label (just the duration) so it never overflows the dense nowrap pills
  // row; the stage pill beside it already names the stage, and the tooltip
  // carries the full "N days in {stage}" context.
  const label = days === 0 ? "today" : `${days}d`;
  const stageName = STAGE_LABELS[stage] || stage;
  const title = overdue
    ? `Waiting ${days} day${days === 1 ? "" : "s"} in ${stageName} — past the ${_STAGE_SLA_DAYS[stage]}-day target`
    : `${days} day${days === 1 ? "" : "s"} in ${stageName}`;
  return `<span class="pa-stage-age${overdue ? " is-overdue" : ""}" title="${escapeHtml(title)}">${escapeHtml(label)}</span>`;
}

// Attention score · a single derived urgency number used to rank the "Action
// needed" inbox most-urgent-first. Built only from signals already on the
// applicant row: how long they've waited in stage, whether that's past the
// stage target, how much leverage the stage has (screened is one step from
// booked), and quality (chase strong candidates first). Higher = more urgent.
function _attentionScore(a) {
  const iso = _stageAnchorIso(a);
  const t = iso ? new Date(iso).getTime() : NaN;
  const days = isNaN(t) ? 0 : Math.max(0, Math.floor((Date.now() - t) / 86400000));
  const sla = _STAGE_SLA_DAYS[a.pipeline_stage] || 3;
  let s = days * 10;                                   // longer wait ⇒ more urgent
  if (days >= sla) s += 40;                            // past the stage target
  if (a.pipeline_stage === "screened") s += 15;        // one step from booked — high leverage
  if (a.score != null && a.screening_completed_at) s += Math.min(20, a.score * 2); // chase quality
  return s;
}

// "Screening invite sent" / "Video completed" / "Applicant added" — pick
// the verb tied to the latest activity so the Last touch column reads
// like a verb, not a timestamp.
function _lastTouchLabel(a) {
  if (_screeningInviteSent(a))   return "Screening invite sent";
  if (a.screening_completed_at)  return "Screening completed";
  return "Applicant added";
}

// Compact activity timeline derived from the timestamps we already have
// on the applicant row.  Returns the steps in chronological order with
// a `current` flag on the most recent.
function _activitySteps(a) {
  const steps = [];
  if (a.created_at)              steps.push({ label: "Applicant added",      at: a.created_at });
  // Use last_sms_at when we have it; otherwise (just contacted, SMS not yet
  // delivered / email-only) fall back to just after "added" so the step shows.
  const inviteAt = a.last_sms_at
    || (_screeningInviteSent(a) && a.created_at ? new Date(new Date(a.created_at).getTime() + 1000).toISOString() : null);
  if (inviteAt)                 steps.push({ label: "Screening invite sent", at: inviteAt });
  if (a.screening_completed_at)  steps.push({ label: "Screening completed",   at: a.screening_completed_at });
  if (a.next_event_starts_at)    steps.push({ label: "Interview scheduled",   at: a.next_event_starts_at });
  // Sort by time so a later last_sms_at doesn't appear before a screening
  // that already happened.
  steps.sort((x, y) => new Date(x.at) - new Date(y.at));
  if (steps.length > 0) steps[steps.length - 1].current = true;
  return steps;
}

// Some upstream systems hand us applicant names in ALL CAPS; render
// them title-cased so the Pipeline cards don't shout. Word-boundary
// regex handles hyphens, apostrophes, and other separators correctly
// (e.g. "MARY-JANE O'BRIEN" → "Mary-Jane O'Brien").
function rrTitleCaseName(s) {
  return (s || "").toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());
}

// Compact one-strip card: stage pill + identity + activity timeline +
// four inline icon buttons (phone, email, notes, more). Clicking each
// icon opens a popover scoped to that task — there's no expand/detail
// panel anymore.
// Screening-video review state. There's no server-side "watched" flag,
// so the operator's review state is tracked locally — just enough to
// calm the loud "Review video" CTA once they've actually opened it.
function _paVideoWatched(id) {
  try { return localStorage.getItem("rr-pa-vid-" + id) === "1"; }
  catch { return false; }
}
function _paMarkVideoWatched(id) {
  try { localStorage.setItem("rr-pa-vid-" + id, "1"); } catch (_) {}
}

// ── 5-column funnel row helpers (enterprise redesign) ──────────────────────
// A modern hiring timeline: Applied → Screening → Interview → Offer → Hired.
// Completed = green check + line, current = blue-outlined circle + bold label,
// future = light-grey circle. RouteReady's stages map onto these five.
const _PIPE_STAGES = ["Applied", "Screening", "Interview", "Offer", "Hired"];
function _pipelineStageIndex(stage) {
  switch (stage) {
    case "applied": return 0;
    case "screened": return 1;
    case "booking_pending":
    case "booking_scheduled": return 2;
    case "hired": return 4;
    default: return 0;
  }
}
function _pipelineTimeline(a) {
  const cur = _pipelineStageIndex(a.pipeline_stage);
  const chk = '<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';
  return `<div class="pa-pl">` + _PIPE_STAGES.map((label, i) => {
    const state = i < cur ? "done" : i === cur ? "current" : "future";
    // "reached" colours the connector running INTO this node (green up to the
    // current step). The connector is drawn by CSS (::before) so the node/label
    // stay a clean two-row stack with the label centred under its node.
    const reached = i <= cur ? " is-reached" : "";
    return `<div class="pa-pl-step is-${state}${reached}">` +
      `<span class="pa-pl-node">${state === "done" ? chk : ""}</span>` +
      `<span class="pa-pl-lbl">${label}</span>` +
    `</div>`;
  }).join("") + `</div>`;
}
// Relative date label for the Last Contact column (Today / Yesterday / Jun 7).
function _lcRelDate(d) {
  const now = new Date();
  if (d.toDateString() === now.toDateString()) return "Today";
  if (new Date(now.getTime() - 86400000).toDateString() === d.toDateString()) return "Yesterday";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

// Fixed-milestone progress stepper: Applied → Screening invite sent →
// Screening → Interview → Hired. Each node is "done" (green check, behind the
// current step), "current" (accent, the furthest reached), or "upcoming"
// (outline). Completed nodes show the date they happened.
function _milestoneStepper(a) {
  const fmtShort = (iso) => { if (!iso) return ""; const d = new Date(iso); return isNaN(d) ? "" : d.toLocaleDateString(undefined, { month: "short", day: "numeric" }); };
  const inStage = (...s) => s.includes(a.pipeline_stage);
  const screeningReached = !!a.screening_completed_at || inStage("screened", "booking_pending", "booking_scheduled", "hired");
  const interviewReached = !!a.next_event_starts_at || a.status === "interview_completed" || inStage("booking_scheduled", "hired");
  const hiredReached = a.status === "hired";

  const ICON = {
    send: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>',
    clipboard: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 2h6a1 1 0 0 1 1 1v1H8V3a1 1 0 0 1 1-1z"/><path d="M8 4H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-2"/></svg>',
    calendar: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>',
    star: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>',
    check: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>',
  };

  const m = [
    { label: "Applied",               reached: true,                   date: a.created_at,            icon: ICON.check },
    { label: "Screening invite sent", reached: _screeningInviteSent(a), date: a.last_sms_at,          icon: ICON.send },
    { label: "Screening",             reached: screeningReached,       date: a.screening_completed_at, icon: ICON.clipboard },
    { label: "Interview",             reached: interviewReached,       date: a.next_event_starts_at,  icon: ICON.calendar },
    { label: "Hired",                 reached: hiredReached,           date: null,                    icon: ICON.star },
  ];
  let currentIdx = 0;
  m.forEach((s, i) => { if (s.reached) currentIdx = i; });

  return `<div class="pa-mstep">` + m.map((s, i) => {
    const state = i < currentIdx ? "is-done" : (i === currentIdx ? "is-current" : "is-upcoming");
    const reached = i <= currentIdx; // colours the connector leading into this node
    const inner = state === "is-done" ? ICON.check : (state === "is-current" ? s.icon : "");
    const dateTxt = s.date ? fmtShort(s.date) : "";
    return `<div class="pa-mstep-item ${state}${reached ? " is-reached" : ""}">
      <div class="pa-mstep-dot">${inner}</div>
      <div class="pa-mstep-label">${escapeHtml(s.label)}</div>
      <div class="pa-mstep-date">${escapeHtml(dateTxt)}</div>
    </div>`;
  }).join("") + `</div>`;
}

function renderApplicantCard(a) {
  const stage = a.pipeline_stage;
  const slug  = (a.full_name || "").toLowerCase().replace(/\s+/g, "-");
  const name  = rrTitleCaseName(a.full_name);

  // Stage pill copy · a compact one-word-ish badge. The booked time
  // lives on the timeline ("Interview scheduled · …"), so the badge
  // stays short and never wraps.
  let stageLabel = STAGE_LABELS[stage] ?? stage;

  // Score chip — only meaningful once the applicant has actually
  // completed screening. Before then a "score" reading is misleading
  // (a 0 looks like a hard-failure when it really means "no data").
  let scoreChip = "";
  if (a.score != null && a.screening_completed_at) {
    const cls = a.score >= 7 ? "score" : a.score >= 4 ? "score score-mid" : "score score-low";
    scoreChip = `<span class="pa-card-tag ${cls}">Score ${a.score}</span>`;
  }

  const sourceMetaTxt = a.source ? `via ${rrTitleCaseName(a.source)}` : "Direct applicant";

  // Progress: a fixed milestone stepper (Applied → Screening invite sent →
  // Screening → Interview → Hired) showing how far the applicant has moved.
  const timelineHtml = _milestoneStepper(a);
  // Stage status reads as two lines (like the Roster risk card): the stage
  // chip + the recommended next step, so an operator sees status + what to do.
  const nextStep = _recommendedNextStep(a);
  // The static "applied" headline ("Send the screening invite") contradicts the
  // CTA ("Resend") and the stepper once the invite has gone out — derive the
  // line from the same _screeningInviteSent signal so the card never disagrees.
  const stageNextTxt = (stage === "applied" && _screeningInviteSent(a)) ? "Awaiting screening" : nextStep.headline;

  // "Last updated" column — most recent activity timestamp (date + time).
  const upd = _lastUpdatedAt(a);
  const updDate = upd ? upd.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" }) : "—";
  const updTime = upd ? upd.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : "";

  // Stage CTA. Operator-requested single-primary card: only the stage
  // CTA (Resend screening / Send booking link / etc.) reads as a button.
  // Decline + Video + the contact icon row all moved into the ⋯ menu
  // (or, for Decline + Video, removed entirely) so each card carries
  // one obvious workflow + a quiet overflow.
  let ctaAction = "", ctaLabel = "", ctaNeedsAction = false;
  // "Send" until a screening invite has actually gone out (same signal the
  // timeline uses for "Screening invite sent"), "Resend" after — so the button
  // and the card's timeline never disagree. Same action either way.
  //
  // ctaNeedsAction = the ball is in the DSP's court to advance the applicant
  // (send the first screening invite, send the booking link). The quieter
  // cases are follow-ups where we're waiting on the applicant and the button
  // is just a re-send nudge. The two render differently (strong blue vs muted
  // neutral) so a DSP can scan the list for what actually needs them.
  if (stage === "applied")           { const sent = _screeningInviteSent(a); ctaAction = "resend_screening"; ctaLabel = sent ? "Resend screening" : "Send screening"; ctaNeedsAction = !sent; }
  else if (stage === "screened")     { ctaAction = "send_link";        ctaLabel = "Send booking link";    ctaNeedsAction = true; }
  else if (stage === "booking_pending") { ctaAction = "resend_link";   ctaLabel = "Resend booking link"; }
  else if (stage === "booking_scheduled") { ctaAction = "reschedule";  ctaLabel = "Reschedule"; }

  // Compact icon-button action row (operator preference): the primary action,
  // Decline, and ⋯ as small square icon buttons with the label in the tooltip.
  const _sendIco = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>';
  const _calIco  = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
  const advanceBtn = ctaAction
    ? `<button class="pa-act-ico pa-act-adv ${ctaNeedsAction ? "is-action" : "is-followup"}" type="button" data-rr-action="${ctaAction}" data-applicant-id="${escapeHtml(a.id)}" title="${escapeHtml(ctaLabel)}" aria-label="${escapeHtml(ctaLabel)}">${ctaAction === "reschedule" ? _calIco : _sendIco}</button>`
    : "";

  // Review video · secondary button alongside the primary CTA when
  // the applicant has uploaded a screening video. Operators were
  // missing the entry point — the comment row near _recommendedNextStep
  // hinted at the video in the subtitle but offered no way to actually
  // open it. Renders only when a.video_url is set so cards without a
  // video stay single-CTA.
  // Opens the in-dashboard video modal (handleAction → "play_video" →
  // openVideoModal) rather than a new tab, and tracks local "watched" state
  // so the CTA calms (drops the dot, becomes "Re-watch") after first view.
  const _vidWatched = _paVideoWatched(a.id);
  // Video · a visible icon in the action row when a screening video is on file.
  // Blue (is-unwatched) until it's been viewed, then it calms to grey.
  const reviewVideoBtn = a.video_url
    ? `<button type="button" class="pa-act-ico pa-act-video${_vidWatched ? "" : " is-unwatched"}" data-rr-action="play_video" data-applicant-id="${escapeHtml(a.id)}" data-video-url="${escapeHtml(a.video_url)}" title="${_vidWatched ? "Re-watch screening video" : "Review screening video"}" aria-label="${_vidWatched ? "Re-watch screening video" : "Review screening video"}"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polygon points="6 4 20 12 6 20 6 4" fill="currentColor" stroke="none"/></svg></button>`
    : "";

  // Decline · an icon button in the Actions column (operator wants it as an
  // icon, matching the video icon). Red circle-slash glyph; same decline
  // dispatcher (opens the decline email in the composer for review — nothing
  // is sent until the operator hits send).
  const declineBtn = `<button class="pa-act-ico pa-act-decline" type="button" data-rr-action="decline" data-applicant-id="${escapeHtml(a.id)}" title="Decline applicant" aria-label="Decline applicant"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/></svg></button>`;

  // Quiet ⋯ overflow · Phone / Email / Note utilities. Tertiary color,
  // no border, only reads on hover. Menu opens via _paOpenMoreMenu below.
  const moreBtn = `<button class="pa-act-ico pa-act-more" type="button" data-rr-pa-more aria-label="More actions" title="More actions">
      <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true">
        <circle cx="5"  cy="12" r="1.7"/>
        <circle cx="12" cy="12" r="1.7"/>
        <circle cx="19" cy="12" r="1.7"/>
      </svg>
    </button>`;

  // ── Applicant badge · subtle, at most one, derived from data we have. ──
  let _badgeTxt = "";
  if (a.score != null && a.screening_completed_at && a.score >= 8) _badgeTxt = "Top Candidate";
  else if (/refer/i.test(String(a.source || ""))) _badgeTxt = "Referral";
  const _badgeHtml = _badgeTxt ? `<span class="pa-a-badge">${escapeHtml(_badgeTxt)}</span>` : "";

  // ── Last Contact · the last outbound SMS we sent (the one contact channel
  //    tracked on the row; email history lives in the record). ──
  const _lc = a.last_sms_at ? new Date(a.last_sms_at) : null;
  const _lcOk = _lc && !isNaN(_lc.getTime());
  const _lcDate = _lcOk ? _lcRelDate(_lc) : "—";
  const _lcTime = _lcOk ? _lc.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : "";
  const _smsIco = '<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>';
  const _lcChannel = _lcOk ? `<span class="pa-lc-ch">${_smsIco} SMS</span>` : "";

  // ── Next Step · contextual headline + sub + one small button. ──
  const _ageIso = _stageAnchorIso(a);
  const _ageDays = _ageIso ? Math.max(0, Math.floor((Date.now() - new Date(_ageIso).getTime()) / 86400000)) : 0;
  let _nsSub = nextStep.sub;
  if (stage === "booking_scheduled" && a.next_event_starts_at) _nsSub = fmtDate(a.next_event_starts_at);
  else if (stage === "applied" || stage === "screened" || stage === "booking_pending") _nsSub = `Waiting ${_ageDays}d`;
  const _nsBtn = ctaAction
    ? `<button class="pa-ns-btn" type="button" data-rr-action="${ctaAction}" data-applicant-id="${escapeHtml(a.id)}">${escapeHtml(ctaLabel)}</button>`
    : "";
  // Past the stage SLA, the Next Step zone gains a hover-only follow-up
  // link — the existing CTAs are one-click sends; this captures the human
  // chase ("call them") as an owned task. Absent entirely on on-track cards.
  const _qtOverdue = (stage in _STAGE_SLA_DAYS) && _ageDays >= _STAGE_SLA_DAYS[stage];
  const _qtFollowUp = _qtOverdue ? `<div style="margin-top:2px">${rrQtLink({
    hover: true,
    label: "Add follow-up task",
    title: `Follow up with ${name} — ${_ageDays}d in ${STAGE_LABELS[stage] || stage}`,
    description: `Waiting ${_ageDays} day${_ageDays === 1 ? "" : "s"} in ${STAGE_LABELS[stage] || stage} (target ${_STAGE_SLA_DAYS[stage]}d). Next step: ${stageNextTxt}. Last contact: ${_lcDate}${_lcTime ? ` ${_lcTime}` : ""}.\nOpen: Pipeline → ${name}`,
    category: "Hiring",
    sourceKey: `hire:${a.id}`,
    entityType: "applicant",
    entityId: a.id,
  })}</div>` : "";

  return `
    <div class="pa-card" data-stage="${stage}" data-applicant="${a.id}" data-applicant-slug="${slug}" tabindex="0">
      <div class="pa-row pa-row-v5">

        <div class="pa-zone pa-c-applicant">
          <div class="pa-card-avatar ${_tierClassFromScore(a.score)}">${escapeHtml(_initialsOf(name))}</div>
          <div class="pa-a-main">
            <div class="pa-a-nameline"><span class="pa-a-name">${escapeHtml(name)}</span>${_badgeHtml}</div>
            ${a.phone ? `<div class="pa-a-contact">${phoneCell(a.phone)}</div>` : ""}
            ${a.email ? `<div class="pa-a-contact">${escapeHtml(a.email)}</div>` : ""}
            ${_addedBadge(a)}
          </div>
        </div>

        <div class="pa-zone pa-c-pipeline">${_pipelineTimeline(a)}</div>

        <div class="pa-zone pa-c-contact">
          <div class="pa-lc-date">${escapeHtml(_lcDate)}</div>
          ${_lcTime ? `<div class="pa-lc-time">${escapeHtml(_lcTime)}</div>` : ""}
          ${_lcChannel}
        </div>

        <div class="pa-zone pa-c-next">
          <div class="pa-ns-head">${escapeHtml(stageNextTxt)}</div>
          <div class="pa-ns-sub">${escapeHtml(_nsSub)}</div>
          ${_qtFollowUp}
          ${_nsBtn}
        </div>

        <div class="pa-zone pa-c-actions">
          ${reviewVideoBtn}${declineBtn}
        </div>

      </div>
    </div>`;
}

// ── Candidate record · a right-side drawer opened by clicking a card's
//    identity area. The #1 gap the funnel audit flagged: one place to see a
//    person's full record — identity, journey, next step, and the whole message
//    history — instead of hunting across popovers. Additive and reuse-first:
//    core fields come from the cached pipeline row (window._rrPipelineById), the
//    stepper/actions reuse the card's own helpers + the global data-rr-action
//    dispatcher, and the message thread reuses applicant_email_thread +
//    _renderEmailRow + openEmailThreadModal. (Screening answers + interview
//    scorecard are a natural v2 once those are on the row/an RPC.) ──────────────
function _paRecordCta(a) {
  switch (a.pipeline_stage) {
    case "applied": { const sent = _screeningInviteSent(a); return { action: "resend_screening", label: sent ? "Resend screening" : "Send screening", primary: !sent }; }
    case "screened":          return { action: "send_link",   label: "Send booking link",   primary: true };
    case "booking_pending":   return { action: "resend_link", label: "Resend booking link", primary: false };
    case "booking_scheduled": return { action: "reschedule",  label: "Reschedule",          primary: false };
    default:                  return null;
  }
}
async function _paOpenRecord(id) {
  const a = window._rrPipelineById && window._rrPipelineById.get(id);
  if (!a) { toast("Open the applicant from the list first", "info"); return; }
  document.getElementById("rr-pa-record")?.remove();

  const name = rrTitleCaseName(a.full_name) || "Applicant";
  const stage = a.pipeline_stage;
  const stageLabel = STAGE_LABELS[stage] ?? stage;
  const next = _recommendedNextStep(a);
  const cta = _paRecordCta(a);
  const esc = escapeHtml;
  const kv = (label, val) => `<div class="rec-kv"><span class="rec-kv-k">${esc(label)}</span><span class="rec-kv-v">${val}</span></div>`;
  const appliedTxt = a.created_at ? new Date(a.created_at).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" }) : "—";
  const nextEvt = a.next_event_starts_at ? fmtDate(a.next_event_starts_at) : "—";
  const upd = _lastUpdatedAt(a);
  const updTxt = upd ? _fmtAbsTouch(upd.toISOString()) : "—";
  const scoreTxt = (a.score != null && a.screening_completed_at) ? `${a.score}/10` : "Not screened yet";

  const ctaBtn = cta
    ? `<button class="rec-cta ${cta.primary ? "is-primary" : ""}" type="button" data-rr-action="${cta.action}" data-applicant-id="${esc(a.id)}">${esc(cta.label)}</button>`
    : "";
  const videoBtn = a.video_url
    ? `<button class="rec-act" type="button" data-rr-action="play_video" data-applicant-id="${esc(a.id)}" data-video-url="${esc(a.video_url)}">▶ Review video</button>` : "";

  const ov = document.createElement("div");
  ov.id = "rr-pa-record";
  ov.innerHTML = `
    <style>
      #rr-pa-record{position:fixed;inset:0;z-index:9600}
      #rr-pa-record .rec-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.34)}
      #rr-pa-record .rec-panel{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
        width:min(460px,94vw);max-height:88vh;background:var(--surface,#fff);border-radius:14px;
        box-shadow:0 24px 70px rgba(15,23,42,.30);display:flex;flex-direction:column;overflow:hidden;animation:recIn .16s ease}
      @keyframes recIn{from{transform:translate(-50%,-50%) scale(.96);opacity:0}to{transform:translate(-50%,-50%) scale(1);opacity:1}}
      @media(prefers-reduced-motion:reduce){#rr-pa-record .rec-panel{animation:none}}
      #rr-pa-record .rec-head{display:flex;gap:12px;align-items:flex-start;padding:18px 18px 14px;border-bottom:1px solid var(--border,#e5e7eb)}
      #rr-pa-record .rec-av{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:15px;flex:0 0 auto}
      #rr-pa-record .rec-h-main{min-width:0;flex:1 1 auto}
      #rr-pa-record .rec-name{font-size:17px;font-weight:680;color:var(--text,#111);line-height:1.2}
      #rr-pa-record .rec-pills{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px;align-items:center}
      #rr-pa-record .rec-x{flex:0 0 auto;border:0;background:transparent;font-size:20px;line-height:1;cursor:pointer;color:var(--text-subtle,#6b7280);padding:2px 4px}
      #rr-pa-record .rec-body{flex:1 1 auto;overflow-y:auto;padding:16px 18px 24px;display:flex;flex-direction:column;gap:18px}
      #rr-pa-record .rec-sec-t{font-size:11px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle,#6b7280);margin:0 0 8px}
      #rr-pa-record .rec-contact{display:flex;flex-wrap:wrap;gap:8px}
      #rr-pa-record .rec-contact a{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:var(--accent-text,#1d4ed8);background:var(--accent-soft,#eaf1fe);border-radius:8px;padding:6px 10px;text-decoration:none}
      #rr-pa-record .rec-kv{display:flex;justify-content:space-between;gap:12px;font-size:13px;padding:4px 0}
      #rr-pa-record .rec-kv-k{color:var(--text-subtle,#6b7280)}
      #rr-pa-record .rec-kv-v{color:var(--text,#111);font-weight:560;text-align:right}
      #rr-pa-record .rec-next{background:var(--surface-secondary,#f5f7fa);border:1px solid var(--border,#e5e7eb);border-radius:10px;padding:12px 14px}
      #rr-pa-record .rec-next-h{font-size:14px;font-weight:640;color:var(--text,#111)}
      #rr-pa-record .rec-next-s{font-size:12.5px;color:var(--text-subtle,#6b7280);margin-top:2px}
      #rr-pa-record .rec-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
      #rr-pa-record .rec-cta,#rr-pa-record .rec-act{font:inherit;font-size:13px;font-weight:600;border-radius:8px;padding:8px 13px;cursor:pointer;border:1px solid var(--border,#e5e7eb);background:var(--surface,#fff);color:var(--text,#111)}
      #rr-pa-record .rec-cta.is-primary{background:var(--accent,#2563eb);border-color:var(--accent,#2563eb);color:#fff}
      #rr-pa-record .rec-act:hover,#rr-pa-record .rec-cta:hover{background:var(--surface-hover,#f3f4f6)}
      #rr-pa-record .rec-cta.is-primary:hover{background:#1d4ed8}
      #rr-pa-record .rec-act.rec-danger{color:var(--red,#b91c1c)}
      #rr-pa-record .rec-steps{display:block}
      #rr-pa-record .rec-msgs{display:flex;flex-direction:column;gap:10px}
      #rr-pa-record .rec-msg-empty{font-size:13px;color:var(--text-subtle,#6b7280)}
    </style>
    <div class="rec-backdrop" data-rec-close></div>
    <aside class="rec-panel" role="dialog" aria-modal="true" aria-label="Candidate record">
      <div class="rec-head">
        <div class="rec-av ${_tierClassFromScore(a.score)} pa-card-avatar">${esc(_initialsOf(name))}</div>
        <div class="rec-h-main">
          <div class="rec-name">${esc(name)}</div>
          <div class="rec-pills">
            <span class="pa-stage-pill ${stage}">${esc(stageLabel)}</span>
            ${_stageAgeChip(a)}
          </div>
        </div>
        <button class="rec-x" type="button" data-rec-close aria-label="Close">✕</button>
      </div>
      <div class="rec-body">
        <section>
          <div class="rec-contact">
            ${a.phone ? `<a href="tel:${esc(a.phone)}">📞 ${esc(a.phone)}</a>` : ""}
            ${a.email ? `<a href="mailto:${esc(a.email)}">✉ ${esc(a.email)}</a>` : ""}
            ${(!a.phone && !a.email) ? `<span class="rec-msg-empty">No contact info on file.</span>` : ""}
          </div>
        </section>
        <section>
          ${kv("Source", esc(a.source ? rrTitleCaseName(a.source) : "Direct applicant"))}
          ${kv("Applied", esc(appliedTxt))}
          ${kv("Screening score", esc(scoreTxt))}
          ${kv("Interview", esc(nextEvt))}
          ${kv("Last activity", esc(updTxt))}
        </section>
        <section>
          <div class="rec-sec-t">Progress</div>
          <div class="rec-steps">${_milestoneStepper(a)}</div>
        </section>
        <section>
          <div class="rec-next">
            <div class="rec-next-h">${esc(next.headline)}</div>
            <div class="rec-next-s">${esc(next.sub)}</div>
          </div>
          <div class="rec-actions">
            ${ctaBtn}
            <button class="rec-act" type="button" data-rec-email>✉ Message</button>
            <button class="rec-act" type="button" data-rec-note>📝 Note</button>
            ${videoBtn}
            <button class="rec-act rec-danger" type="button" data-rr-action="decline" data-applicant-id="${esc(a.id)}">Decline</button>
          </div>
        </section>
        <section>
          <div class="rec-sec-t">Message history</div>
          <div class="rec-msgs" data-rec-msgs><div class="rec-msg-empty">Loading…</div></div>
        </section>
      </div>
    </aside>`;
  document.body.appendChild(ov);

  const close = () => { ov.remove(); document.removeEventListener("keydown", onKey); };
  const onKey = (e) => { if (e.key === "Escape") close(); };
  document.addEventListener("keydown", onKey);
  ov.addEventListener("click", (e) => {
    if (e.target.closest("[data-rec-close]")) { close(); return; }
    if (e.target.closest("[data-rec-email]")) { close(); openEmailThreadModal(a.id, a.full_name || "", a.email || ""); return; }
    if (e.target.closest("[data-rec-note]")) { _paOpenNotesPopover(e.target.closest("[data-rec-note]"), a); return; }
    // A funnel action (CTA / decline / video) fires via the global data-rr-action
    // handler, which reloads the list — close the drawer so it doesn't show stale
    // state (video keeps the drawer; it opens its own modal).
    const act = e.target.closest("[data-rr-action]");
    if (act && act.getAttribute("data-rr-action") !== "play_video") setTimeout(close, 60);
  });

  // Message history — reuse the applicant email thread.
  const msgs = ov.querySelector("[data-rec-msgs]");
  try {
    const { data: rows, error } = await sb.rpc("applicant_email_thread", { p_applicant_id: a.id });
    if (error) throw error;
    if (!msgs) return;
    msgs.innerHTML = (rows && rows.length)
      ? rows.map(_renderEmailRow).join("")
      : `<div class="rec-msg-empty">No messages yet.</div>`;
  } catch (e) {
    if (msgs) msgs.innerHTML = `<div class="rec-msg-empty">Couldn't load messages: ${escapeHtml(e.message || String(e))}</div>`;
  }
}
// Click anywhere on an applicant row → drop down an inline notes drawer.
// Buttons, links, inputs, the Next-step CTA, the ⋯ menu, and clicks inside an
// already-open drawer keep their own behaviour (typing notes must not collapse
// it). Re-clicking the row toggles the drawer shut.
document.addEventListener("click", (e) => {
  if (!e.target.closest) return;
  const card = e.target.closest("#view-pipeline .pa-card");
  if (!card) return;
  if (e.target.closest("button, a, input, textarea, label, select, [data-rr-action], [data-rr-pa-more], [data-rr-pa-pop], [data-rr-more-act], .pa-drawer, .pa-pop")) return;
  e.preventDefault();
  _paToggleNotesDrawer(card);
});

// Keyboard select · Enter / Space on a focused applicant row selects it (same
// as a click). Only fires when the card itself holds focus — a focused button
// inside the row keeps its own behaviour.
document.addEventListener("keydown", (e) => {
  if (e.key !== "Enter" && e.key !== " " && e.key !== "Spacebar") return;
  const card = e.target.closest && e.target.closest("#view-pipeline .pa-card");
  if (!card || e.target !== card) return;
  e.preventDefault();
  _paToggleNotesDrawer(card);
});

// Build (once) / toggle the inline notes drawer under a funnel row. Acts as an
// accordion — opening one row collapses any other open drawer in the list.
function _paToggleNotesDrawer(card) {
  if (!card) return;
  const id = card.getAttribute("data-applicant");
  if (!id) return;

  const existing = card.querySelector(":scope > .pa-drawer");
  if (existing) {
    const open = existing.classList.toggle("is-open");
    card.classList.toggle("is-open", open);
    // Selection tracks the active card — the enterprise accent bar stays while
    // the record is active, clears when it's toggled shut.
    card.classList.toggle("is-selected", open);
    return;
  }

  // Accordion: only one applicant is the active/selected record at a time.
  document.querySelectorAll("#view-pipeline .pa-card.is-open, #view-pipeline .pa-card.is-selected").forEach((c) => {
    c.classList.remove("is-open");
    c.classList.remove("is-selected");
    const d = c.querySelector(":scope > .pa-drawer");
    if (d) d.classList.remove("is-open");
  });

  const name = card.querySelector(".pa-a-name")?.textContent || "";
  const drawer = document.createElement("div");
  drawer.className = "pa-drawer";
  drawer.setAttribute("data-rr-drawer", "");
  drawer.innerHTML = `
    <div class="pa-drawer-inner">
      <div class="pa-drawer-body">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
          <div class="pa-drawer-label">Private notes${name ? " · " + escapeHtml(name) : ""}</div>
          <button type="button" class="btn btn-sm btn-ghost" data-rr-pa-notebook title="Open this candidate's notebook" style="display:inline-flex;align-items:center;gap:6px"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 4h11l5 5v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1z"/><path d="M14 4v6h6"/></svg>Notebook</button>
        </div>
        <div class="pa-pop-notes" data-rr-notes-slot>
          <textarea class="pa-notes-input" data-rr-notes-input placeholder="Private notes for your team — call summaries, follow-ups, gut checks…" disabled></textarea>
          <div class="pa-pop-status" data-rr-notes-status>Loading…</div>
        </div>
      </div>
    </div>`;
  card.appendChild(drawer);

  const _paNbBtn = drawer.querySelector("[data-rr-pa-notebook]");
  if (_paNbBtn) _paNbBtn.addEventListener("click", (ev) => {
    ev.stopPropagation();
    if (window.RRNotebooks) window.RRNotebooks.openFor("applicant", id, name || "Applicant");
  });

  const slot = drawer.querySelector("[data-rr-notes-slot]");
  if (slot) _initApplicantNotes(slot, id);

  // Open on the next frame so the 0fr→1fr row transition (and the accent bar's
  // 0→4px animation) actually runs.
  requestAnimationFrame(() => {
    drawer.classList.add("is-open");
    card.classList.add("is-open");
    card.classList.add("is-selected");
  });
  const ta = drawer.querySelector("[data-rr-notes-input]");
  if (ta) setTimeout(() => { if (!ta.disabled) ta.focus(); }, 320);
}

// Most recent activity timestamp for the "Last updated" column.
function _lastUpdatedAt(a) {
  const ts = [a.created_at, a.last_sms_at, a.screening_completed_at, a.next_event_starts_at]
    .filter(Boolean).map((s) => new Date(s).getTime()).filter((n) => !isNaN(n));
  return ts.length ? new Date(Math.max(...ts)) : null;
}

// Column header row, prepended to the list so it aligns with the card grid.
function _paListHeader() {
  return `<div class="pa-listhead pa-row-v5" aria-hidden="true">
    <div class="pa-zone">Applicant</div>
    <div class="pa-zone">Pipeline</div>
    <div class="pa-zone">Last contact</div>
    <div class="pa-zone">Next step</div>
    <div class="pa-zone"></div>
  </div>`;
}

function _initialsOf(name) {
  if (!name) return "?";
  const parts = String(name).trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function _tierClassFromScore(score) {
  if (score === null || score === undefined) return "tier-d";
  if (score >= 7) return "tier-a";
  if (score >= 4) return "tier-b";
  if (score >= 1) return "tier-c";
  return "tier-d";
}

function _relTimeShort(iso) {
  const d = new Date(iso);
  const now = new Date();
  const diffMs = now.getTime() - d.getTime();
  const diffDays = Math.floor(diffMs / 86400000);
  if (diffDays <= 0) return "Today";
  if (diffDays === 1) return "Yesterday";
  if (diffDays < 7) return `${diffDays} days ago`;
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

// Open the applicant's video intro in a simple modal overlay.
function openVideoModal(url) {
  // In-dashboard screening-video player: dim backdrop + centered player with
  // an explicit Fullscreen control and a close (×). Backdrop-click and Esc
  // close; clicks on the player itself do not. (The native <video> controls
  // also expose fullscreen — this just makes it obvious.)
  if (!document.getElementById("rr-video-style")) {
    const st = document.createElement("style");
    st.id = "rr-video-style";
    st.textContent = `
      .rr-video-overlay{position:fixed;inset:0;z-index:9999;background:rgba(8,10,18,.82);
        display:flex;align-items:center;justify-content:center;padding:32px;backdrop-filter:blur(2px)}
      .rr-video-shell{position:relative;display:flex;flex-direction:column;gap:10px;width:100%;max-width:min(900px,92vw)}
      .rr-video-bar{display:flex;justify-content:flex-end;gap:8px}
      .rr-video-bar button{display:inline-flex;align-items:center;justify-content:center;
        width:34px;height:34px;border-radius:8px;cursor:pointer;color:#fff;
        background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.18);
        transition:background .12s,border-color .12s}
      .rr-video-bar button:hover{background:rgba(255,255,255,.22);border-color:rgba(255,255,255,.34)}
      .rr-video-el{width:100%;max-height:80vh;border-radius:12px;background:#000;box-shadow:0 18px 60px rgba(0,0,0,.55)}`;
    document.head.appendChild(st);
  }
  document.getElementById("rr-video-overlay")?.remove();
  const overlay = document.createElement("div");
  overlay.id = "rr-video-overlay";
  overlay.className = "rr-video-overlay";
  overlay.innerHTML = `
    <div class="rr-video-shell" role="dialog" aria-modal="true" aria-label="Screening video">
      <div class="rr-video-bar">
        <button type="button" class="rr-video-fs" title="Fullscreen" aria-label="Fullscreen">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3H5a2 2 0 0 0-2 2v3M16 3h3a2 2 0 0 1 2 2v3M21 16v3a2 2 0 0 1-2 2h-3M3 16v3a2 2 0 0 0 2 2h3"/></svg>
        </button>
        <button type="button" class="rr-video-close" title="Close" aria-label="Close">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="6" y1="6" x2="18" y2="18"/><line x1="18" y1="6" x2="6" y2="18"/></svg>
        </button>
      </div>
      <video class="rr-video-el" controls autoplay playsinline></video>
    </div>`;
  document.body.appendChild(overlay);

  const videoEl = overlay.querySelector(".rr-video-el");
  videoEl.src = url; // set via property so signed-URL chars never break markup

  function close() {
    document.removeEventListener("keydown", onKey, true);
    overlay.remove();
  }
  function onKey(e) { if (e.key === "Escape") { e.stopPropagation(); close(); } }
  document.addEventListener("keydown", onKey, true);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  overlay.querySelector(".rr-video-close").addEventListener("click", close);
  overlay.querySelector(".rr-video-fs").addEventListener("click", () => {
    if (document.fullscreenElement) { document.exitFullscreen?.(); return; }
    if (videoEl.requestFullscreen)            videoEl.requestFullscreen();
    else if (videoEl.webkitRequestFullscreen) videoEl.webkitRequestFullscreen();
    else if (videoEl.webkitEnterFullscreen)   videoEl.webkitEnterFullscreen(); // iOS Safari
  });
}

// ─── Applicant email thread modal ─────────────────────────────────────
//
// Two-way email on the applicant card. Reads the thread via
// applicant_email_thread RPC (added in migration 0095), renders inbound
// + outbound rows, and lets the operator queue a reply that send-email
// will dispatch on its next tick.

// ── Icon-popover machinery for the applicant card ─────────────────────
// Click handler routes each icon (phone / email / notes / more) to its
// own popover. Email piggybacks on the existing thread modal; the rest
// open small positioned popovers anchored to the icon.

let _paOpenPop = null;
function _paClosePop() {
  if (_paOpenPop) {
    try { _paOpenPop.el.remove(); } catch {}
    if (_paOpenPop.offClick) document.removeEventListener("click", _paOpenPop.offClick, true);
    if (_paOpenPop.offKey)   document.removeEventListener("keydown", _paOpenPop.offKey, true);
    _paOpenPop = null;
  }
}

function _paOpenPopover(anchor, html) {
  _paClosePop();
  const pop = document.createElement("div");
  pop.className = "pa-pop";
  pop.innerHTML = html;
  document.body.appendChild(pop);

  // Position: prefer below-right, flip up/left if off-viewport.
  const rect = anchor.getBoundingClientRect();
  const popW = pop.offsetWidth;
  const popH = pop.offsetHeight;
  let left = rect.right - popW;
  if (left < 8) left = Math.max(8, rect.left);
  if (left + popW > window.innerWidth - 8) left = window.innerWidth - popW - 8;
  let top = rect.bottom + 6;
  if (top + popH > window.innerHeight - 8) top = Math.max(8, rect.top - popH - 6);
  pop.style.left = left + "px";
  pop.style.top  = top  + "px";

  // Outside-click & Esc close.
  const offClick = (e) => {
    if (!pop.contains(e.target) && e.target !== anchor && !anchor.contains(e.target)) _paClosePop();
  };
  const offKey = (e) => { if (e.key === "Escape") _paClosePop(); };
  setTimeout(() => document.addEventListener("click", offClick, true), 0);
  document.addEventListener("keydown", offKey, true);

  _paOpenPop = { el: pop, offClick, offKey, anchor };
  return pop;
}

function _paOpenPhonePopover(anchor, a) {
  if (!a.phone) return;
  _paOpenPopover(anchor, `
    <div class="pa-pop-h">Phone</div>
    <a class="pa-pop-row pa-pop-row-strong" href="tel:${escapeHtml(a.phone)}">
      <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
      ${escapeHtml(a.phone)}
    </a>`);
}

function _paOpenNotesPopover(anchor, a) {
  const pop = _paOpenPopover(anchor, `
    <div class="pa-pop-h">Notes · ${escapeHtml(rrTitleCaseName(a.full_name))}</div>
    <div class="pa-pop-notes" data-rr-notes-slot>
      <textarea class="pa-notes-input" data-rr-notes-input placeholder="Private notes for your team — call summaries, follow-ups, gut checks…" disabled></textarea>
      <div class="pa-pop-status" data-rr-notes-status>Loading…</div>
    </div>`);
  const slot = pop.querySelector("[data-rr-notes-slot]");
  if (slot) _initApplicantNotes(slot, a.id);
  // Focus the textarea once loaded.
  const ta = pop.querySelector("[data-rr-notes-input]");
  if (ta) setTimeout(() => { if (!ta.disabled) ta.focus(); }, 300);
}

document.addEventListener("click", (e) => {
  // Overflow ⋯ menu · the only secondary surface on the card. Opens
  // a single popover with Phone / Email / Note utilities; each row
  // dispatches to the existing _paOpen* handlers so the underlying
  // contact flows stay unchanged.
  const moreBtn = e.target.closest("[data-rr-pa-more]");
  if (moreBtn) {
    e.preventDefault();
    e.stopImmediatePropagation();
    const card = moreBtn.closest(".pa-card");
    const id = card?.getAttribute("data-applicant");
    if (!id) return;
    if (_paOpenPop && _paOpenPop.anchor === moreBtn) { _paClosePop(); return; }
    const a = (window._rrPipelineById?.get?.(id))
      || { id, full_name: card.querySelector(".pa-card-name")?.textContent || "" };
    _paOpenMoreMenu(moreBtn, a);
    return;
  }
  const icon = e.target.closest("[data-rr-pa-pop]");
  if (!icon) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  if (icon.classList.contains("is-disabled")) return;
  const card = icon.closest(".pa-card");
  const id = card?.getAttribute("data-applicant");
  if (!id) return;
  // Re-clicking the same icon closes the popover.
  if (_paOpenPop && _paOpenPop.anchor === icon) { _paClosePop(); return; }
  const kind = icon.getAttribute("data-rr-pa-pop");
  // Pull the applicant row from the in-memory list cached by loadPipeline.
  const a = (window._rrPipelineById?.get?.(id)) || { id, full_name: card.querySelector(".pa-card-name")?.textContent || "" };
  if      (kind === "phone") _paOpenPhonePopover(icon, a);
  else if (kind === "notes") _paOpenNotesPopover(icon, a);
  else if (kind === "email") {
    if (!a.email) return;
    _rrComposeFreeEmail(id, a.email, a.full_name || "");
  }
}, true);

// ── Overflow ⋯ menu builder · one popover with Phone / Email / Note
// rows. Each row dispatches to the existing per-utility opener so all
// the downstream flows (call / email thread modal / notes popover)
// stay exactly as they were.
function _paOpenMoreMenu(anchor, a) {
  const phoneSub = a.phone ? escapeHtml(a.phone) : "No phone on file";
  const emailSub = a.email ? escapeHtml(a.email) : "No email on file";
  const phoneIcon = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>';
  const emailIcon = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="M22 7l-10 6L2 7"/></svg>';
  const noteIcon  = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="8" y1="13" x2="16" y2="13"/><line x1="8" y1="17" x2="13" y2="17"/></svg>';
  const declineIcon = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/></svg>';
  // Review video is now a visible icon in the card's action row (not here) —
  // the ⋯ menu is contact utilities only, no duplication.
  const row = (act, icon, label, sub, disabled) => `
    <button class="pa-pop-mi${disabled ? " is-disabled" : ""}" type="button" data-rr-more-act="${act}"${disabled ? " disabled" : ""}>
      <span class="pa-pop-mi-icon">${icon}</span>
      <span class="pa-pop-mi-body">
        <span class="pa-pop-mi-label">${label}</span>
        <span class="pa-pop-mi-sub">${sub}</span>
      </span>
    </button>`;
  // The primary workflow button now lives in the Next Step column and the video
  // icon sits in the Actions column, so the ⋯ menu carries the quiet secondary
  // utilities: Phone / Email / Note, plus Decline (which was previously a visible
  // icon but reads better tucked at the bottom of the overflow, set apart).
  const html =
      row("phone", phoneIcon, "Phone", phoneSub, !a.phone)
    + row("email", emailIcon, "Email", emailSub, !a.email)
    + row("note",  noteIcon,  "Note",  "Add an internal note", false)
    + `<div class="pa-pop-sep" role="separator"></div>`
    + `<button class="pa-pop-mi pa-pop-mi-danger" type="button" data-rr-more-act="decline">
        <span class="pa-pop-mi-icon">${declineIcon}</span>
        <span class="pa-pop-mi-body">
          <span class="pa-pop-mi-label">Decline</span>
          <span class="pa-pop-mi-sub">Remove from the funnel</span>
        </span>
      </button>`;
  const pop = _paOpenPopover(anchor, html);
  if (!pop) return;
  pop.classList.add("pa-pop-menu");
  pop.addEventListener("click", (ev) => {
    const btn = ev.target.closest("[data-rr-more-act]");
    if (!btn || btn.disabled) return;
    const act = btn.getAttribute("data-rr-more-act");
    _paClosePop();
    if (act === "phone" && a.phone)  _paOpenPhonePopover(anchor, a);
    else if (act === "email" && a.email) _rrComposeFreeEmail(a.id, a.email, a.full_name || "");
    else if (act === "note")          _paOpenNotesPopover(anchor, a);
    else if (act === "decline")       _rrComposeDeclineEmail(a.id);
  });
}

// Any data-rr-action click inside the More popover should close the
// popover before firing (the handler at the bottom will refresh the list).
document.addEventListener("click", (e) => {
  if (!_paOpenPop) return;
  if (e.target.closest("[data-rr-action]") && _paOpenPop.el.contains(e.target)) {
    _paClosePop();
  }
}, true);

// Lazy-load notes textarea contents and wire blur-based auto-save.
// Idempotent — re-opening the same slot is a no-op.
async function _initApplicantNotes(slot, applicantId) {
  if (!slot || slot.dataset.loaded === "1") return;
  slot.dataset.loaded = "1";

  const ta     = slot.querySelector("[data-rr-notes-input]");
  const status = slot.querySelector("[data-rr-notes-status]");
  if (!ta || !status) return;

  const { data, error } = await sb
    .from("applicants")
    .select("operator_notes")
    .eq("id", applicantId)
    .single();
  if (error) {
    status.textContent = "Couldn't load notes: " + error.message;
    status.style.color = "var(--red)";
    slot.dataset.loaded = "";
    return;
  }
  ta.value = data?.operator_notes ?? "";
  ta.disabled = false;
  status.textContent = "";

  let lastSaved = ta.value;
  ta.addEventListener("blur", async () => {
    const next = ta.value;
    if (next === lastSaved) return;
    status.textContent = "Saving…";
    status.style.color = "var(--text-subtle)";
    const { error: upErr } = await sb
      .from("applicants")
      .update({ operator_notes: next || null })
      .eq("id", applicantId);
    if (upErr) {
      status.textContent = "Save failed: " + upErr.message;
      status.style.color = "var(--red)";
      return;
    }
    lastSaved = next;
    const t = new Date().toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
    status.textContent = `Saved at ${t}`;
    status.style.color = "var(--text-subtle)";
  });
}


// Consolidated "Recruiting" footer for the sourcing tile group (Funnel /
// Interview / Onboarding). Instead of a separate "Rules" launcher per tile, the
// whole group gets ONE centered caption on the strip's bottom line plus a single
// box-arrow launcher pinned bottom-right — matching the calendar group's
// "Rules". The launcher opens a small chooser with two options (Screening
// questions → funnel rules, Onboarding steps → onboarding blueprint), each
// forwarding to its existing popover. Built/repositioned from live.js (DOM +
// inline styles) so it reliably reaches the browser regardless of cached HTML.
function _rrCloseRecruitingChooser() {
  const m = document.getElementById("rr-recruiting-chooser");
  if (m) m.remove();
}
// The Funnel/Onboarding rules popovers are anchored to their tile, so opening
// them from the right-side launcher pushed them off the right edge and past the
// bottom of the viewport with no usable scroll. Re-pin the opened popover as a
// fixed panel under the strip, right-aligned, bounded to the viewport height
// with its own scroll. Re-fit on resize while it's open.
// One-time style that constrains the rules popovers' inner content so there's a
// SINGLE scrollbar (the popover's own, at its right edge) and nothing spills
// horizontally past it. A style rule (not inline) survives the builder's
// re-renders of its rows.
function _rrInstallRulesPopoverStyle() {
  if (document.getElementById("rr-rules-pop-fit-style")) return;
  const st = document.createElement("style");
  st.id = "rr-rules-pop-fit-style";
  st.textContent = `
    #rr-ob-rules-popover, #rr-funnel-rules-popover { overflow-x: hidden !important; }
    #rr-ob-rules-popover .ob-rules-body, #rr-ob-rules-popover #obsub-builder,
    #rr-funnel-rules-popover .ob-rules-body, #rr-funnel-rules-popover [data-rr-questions]{
      overflow: visible !important; max-height: none !important; min-width: 0 !important; width: auto !important;
    }
    #rr-ob-rules-popover .ob-bld-card, #rr-funnel-rules-popover .cal-edit-card {
      max-width: 100% !important; box-sizing: border-box !important;
    }
  `;
  document.head.appendChild(st);
}
// Left edge of the fixed right utility rail when it's visible. The rail is
// an opaque body-level strip that deliberately paints ABOVE in-page chrome
// (z 90 vs the TCP strip's stacking context), so fixed popovers anchored to
// the viewport's right edge slide underneath it and lose their right-hand
// controls. Fitters clamp against this edge instead of the raw viewport.
// Falls back to the viewport width when the rail is hidden (other views).
function _rrRightChromeEdge() {
  const rail = document.querySelector("#rr-util-rail-mount .sched-util-rail");
  if (!rail) return window.innerWidth;
  const r = rail.getBoundingClientRect();
  if (!r.width || r.left <= 0 || r.left >= window.innerWidth) return window.innerWidth;
  return Math.round(r.left);
}
function _rrFitRulesPopover(pop) {
  if (!pop) return;
  _rrInstallRulesPopoverStyle();
  let top = 64;
  const strip = document.querySelector("#view-onboarding-ops .sched-nav-heading-actions")
    || document.querySelector("#view-onboarding-ops .sched-nav-heading");
  if (strip) { const r = strip.getBoundingClientRect(); if (r.bottom > 0) top = Math.round(r.bottom + 8); }
  const set = (k, v) => pop.style.setProperty(k, v, "important");
  // Keep clear of the right utility rail — anchoring at right:16 put the
  // popover's right edge underneath the opaque rail on 13"/scaled displays.
  const rightGap = (window.innerWidth - _rrRightChromeEdge()) + 16;
  set("position", "fixed"); set("top", top + "px"); set("right", rightGap + "px");
  set("left", "auto"); set("bottom", "auto"); set("box-sizing", "border-box");
  set("width", "min(720px, calc(100vw - " + (rightGap + 16) + "px))");
  set("max-width", "calc(100vw - " + (rightGap + 16) + "px)");
  set("max-height", "calc(100vh - " + (top + 16) + "px)");
  set("overflow-y", "auto"); set("overflow-x", "hidden");
  set("z-index", "9998");
  // Keep it fitted if the window is resized while open.
  if (!pop._rrFitBound) {
    pop._rrFitBound = true;
    window.addEventListener("resize", () => { if (!pop.hidden) _rrFitRulesPopover(pop); });
  }
}
function _rrToggleRecruitingChooser(anchor) {
  if (document.getElementById("rr-recruiting-chooser")) { _rrCloseRecruitingChooser(); return; }
  const menu = document.createElement("div");
  menu.id = "rr-recruiting-chooser";
  Object.assign(menu.style, {
    position: "fixed", zIndex: "10000", background: "var(--surface,#fff)",
    border: "1px solid var(--border,rgba(15,23,42,.12))", borderRadius: "8px",
    boxShadow: "0 12px 32px rgba(15,23,42,.18)", padding: "4px", minWidth: "190px",
    display: "flex", flexDirection: "column", gap: "1px",
  });
  const mk = (label, fn) => {
    const b = document.createElement("button");
    b.type = "button"; b.textContent = label;
    Object.assign(b.style, {
      display: "block", width: "100%", textAlign: "left", appearance: "none",
      border: "0", background: "transparent", cursor: "pointer", font: "inherit",
      fontSize: "13px", color: "var(--text,#111827)", padding: "8px 12px", borderRadius: "6px",
    });
    b.addEventListener("mouseenter", () => { b.style.background = "rgba(37,99,235,.08)"; b.style.color = "#2563EB"; });
    b.addEventListener("mouseleave", () => { b.style.background = "transparent"; b.style.color = "var(--text,#111827)"; });
    b.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); _rrCloseRecruitingChooser(); fn(); });
    return b;
  };
  menu.appendChild(mk("Screening questions", () => {
    if (window._rrToggleObRules) window._rrToggleObRules(false);
    if (window._rrToggleFunnelRules) window._rrToggleFunnelRules(true);
    _rrFitRulesPopover(document.getElementById("rr-funnel-rules-popover"));
  }));
  menu.appendChild(mk("Onboarding steps", () => {
    if (window._rrToggleFunnelRules) window._rrToggleFunnelRules(false);
    if (window._rrToggleObRules) window._rrToggleObRules(true);
    _rrFitRulesPopover(document.getElementById("rr-ob-rules-popover"));
  }));
  document.body.appendChild(menu);
  const r = anchor.getBoundingClientRect();
  menu.style.top = (r.bottom + 4) + "px";
  menu.style.left = Math.max(8, r.right - menu.offsetWidth) + "px";
  setTimeout(() => {
    document.addEventListener("click", function onDoc(e) {
      if (!e.target.closest("#rr-recruiting-chooser") && !e.target.closest(".rr-recruiting-foot")) {
        _rrCloseRecruitingChooser();
        document.removeEventListener("click", onDoc);
      }
    });
  }, 0);
}
function _rrBuildRecruitingFooter() {
  // RETIRED · the combined "Recruiting" chooser is replaced by
  // context-specific per-tab buttons surfaced directly on the action bar
  // (Funnel → "Screening questions" via #rr-funnel-rules-toggle,
  // Onboarding → "Onboarding steps" via #rr-ob-rules-toggle). Leaving the
  // per-tile launchers visible, so this footer builder is a no-op now.
  return;
  // eslint-disable-next-line no-unreachable
  if (typeof document === "undefined") return;
  const group = document.querySelector('#view-onboarding-ops .sched-ribbon-group[data-group="sourcing"]');
  if (!group) return;
  // Hide every per-tile launcher in the group — one footer replaces them all.
  group.querySelectorAll('#rr-ob-rules-toggle, #rr-funnel-rules-toggle, .ob-rules-foot, .rr-rules-injected')
    .forEach((el) => el.style.setProperty("display", "none", "important"));
  // Full strip height + relative anchor so the caption/launcher sit on the
  // bottom hairline (the calendar group sets the strip height); top-align the
  // tiles so they match the calendar group's tiles.
  group.style.setProperty("align-self", "stretch", "important");
  group.style.setProperty("position", "relative", "important");
  const sub = group.querySelector(".subnav");
  if (sub) sub.style.setProperty("align-self", "flex-start", "important");
  if (group.querySelector(".rr-recruiting-cap")) return; // footer already built
  const cap = document.createElement("span");
  cap.className = "rr-recruiting-cap";
  cap.textContent = "Recruiting";
  Object.assign(cap.style, {
    position: "absolute", left: "0", right: "0", bottom: "-4px", textAlign: "center",
    fontSize: "11px", fontWeight: "800", lineHeight: "1", letterSpacing: ".01em",
    whiteSpace: "nowrap", color: "var(--text-subtle)", pointerEvents: "none", zIndex: "1",
  });
  const launch = document.createElement("button");
  launch.type = "button";
  launch.className = "rr-recruiting-foot";
  launch.title = "Recruiting rules — screening questions & onboarding steps";
  launch.innerHTML = '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2.5" y="2.5" width="7" height="7" rx="1"/><line x1="8" y1="8" x2="13.5" y2="13.5"/><polyline points="13.5 10 13.5 13.5 10 13.5"/></svg>';
  Object.assign(launch.style, {
    position: "absolute", right: "6px", bottom: "-3px", display: "inline-flex",
    alignItems: "center", justifyContent: "center", appearance: "none", border: "0",
    background: "transparent", cursor: "pointer", color: "var(--text-subtle)",
    padding: "1px 4px", margin: "0", borderRadius: "999px", zIndex: "2", opacity: ".85",
  });
  launch.addEventListener("mouseenter", () => { launch.style.opacity = "1"; launch.style.color = "var(--accent-text,#2563EB)"; launch.style.background = "var(--accent-soft,rgba(37,99,235,.08))"; });
  launch.addEventListener("mouseleave", () => { launch.style.opacity = ".85"; launch.style.color = "var(--text-subtle)"; launch.style.background = "transparent"; });
  launch.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); _rrToggleRecruitingChooser(launch); });
  group.appendChild(cap);
  group.appendChild(launch);
  // The footer can nudge strip layout; re-fit the calendar so its sticky header
  // stays pinned (deferred so it runs after module init and this paint).
  setTimeout(() => { try { if (typeof _ivcalFitHeight === "function") _ivcalFitHeight(); } catch (_) {} }, 0);
}
let _rrRecruitingQueued = false;
function _rrBuildRecruitingFooterSoon() {
  if (_rrRecruitingQueued) return;
  _rrRecruitingQueued = true;
  setTimeout(() => { _rrRecruitingQueued = false; _rrBuildRecruitingFooter(); }, 200);
}
if (typeof document !== "undefined") {
  _rrBuildRecruitingFooter();
  setTimeout(_rrBuildRecruitingFooter, 600);
  setTimeout(_rrBuildRecruitingFooter, 1800);
  try { new MutationObserver(_rrBuildRecruitingFooterSoon).observe(document.documentElement, { childList: true, subtree: true }); } catch (_) {}
}

let _emailThreadChannel = null;
function _closeEmailThreadChannel() {
  if (_emailThreadChannel) { try { sb.removeChannel(_emailThreadChannel); } catch {} _emailThreadChannel = null; }
}

// ── Shared "email tools" ribbon ─────────────────────────────────────────────
// The same Outlook-style ribbon the calendar event editor uses, reused on every
// email surface (driver thread, Mail composer) so it reads as one email system.
// Tiles carry data-mailact; each surface wires the actions that apply to it.
const _RR_MAIL_RIBBON_ICONS = {
  send:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>',
  save:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>',
  invite:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><line x1="19" y1="8" x2="19" y2="14"/><line x1="16" y1="11" x2="22" y2="11"/></svg>',
  meeting:'<svg viewBox="0 0 24 24" fill="url(#rr-mail-meet-grad)" aria-hidden="true"><defs><linearGradient id="rr-mail-meet-grad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#60A5FA"/><stop offset="52%" stop-color="#2563EB"/><stop offset="100%" stop-color="#1D4ED8"/></linearGradient></defs><rect x="1.5" y="5.5" width="14" height="13" rx="3" ry="3"/><path d="M22.5 7.2 16 11.4v1.2l6.5 4.2z"/></svg>',
  recur:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>',
  important:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="3" x2="12" y2="14"/><line x1="12" y1="19" x2="12" y2="19.5"/></svg>',
  attach:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>',
  dictate:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0"/><line x1="12" y1="19" x2="12" y2="22"/><line x1="8" y1="22" x2="16" y2="22"/></svg>',
  trash:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg>',
};
function _rrMailRibbonStyle(rootId) {
  return `<style>
    #${rootId} .rr-mail-ribbon{display:flex;align-items:stretch;gap:2px;padding:7px 12px;border-bottom:1px solid var(--border-subtle,rgba(15,23,42,.06));background:var(--surface);flex-wrap:wrap}
    #${rootId} .rr-mail-vdiv{width:1px;align-self:stretch;background:var(--border);margin:4px 7px}
    #${rootId} .rr-mail-ico{display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-width:62px;padding:5px 8px 6px;border:0;background:transparent;cursor:pointer;border-radius:7px;color:var(--text);font:inherit;font-size:11px;line-height:1.1;transition:background var(--t-fast),color var(--t-fast),transform .12s cubic-bezier(.2,.7,.2,1)}
    #${rootId} .rr-mail-ico span{white-space:nowrap}
    #${rootId} .rr-mail-ico:hover{background:rgba(15,23,42,.05);color:var(--text)}
    #${rootId} .rr-mail-ico:active{transform:translateY(1px) scale(.97)}
    #${rootId} .rr-mail-ico.active{color:var(--accent-text);background:var(--accent-soft)}
    #${rootId} .rr-mail-ico.danger:hover{background:rgba(220,38,38,.12);color:#DC2626}
    #${rootId} .rr-mail-ico.send{color:#fff;background:var(--accent);font-weight:600}
    #${rootId} .rr-mail-ico.send:hover{background:var(--accent-hover)}
    #${rootId} .rr-mail-ico svg{width:33px;height:33px;stroke-linecap:round;stroke-linejoin:round}
  </style>`;
}
function _rrMailRibbonHtml(sendLabel) {
  const tile = (id, label, icon, extra) => `<button type="button" class="rr-mail-ico${extra?(" "+extra):""}" data-mailact="${id}" title="${label}" aria-label="${label}">${icon}<span>${label}</span></button>`;
  const V = `<span class="rr-mail-vdiv" aria-hidden="true"></span>`;
  return `<div class="rr-mail-ribbon">
    ${tile("send", sendLabel || "Send", _RR_MAIL_RIBBON_ICONS.send, "send")}
    ${tile("save", "Save", _RR_MAIL_RIBBON_ICONS.save)}
    ${V}
    ${tile("invite", "Invite Attendees", _RR_MAIL_RIBBON_ICONS.invite)}
    ${tile("meeting", "Schedule Meeting", _RR_MAIL_RIBBON_ICONS.meeting)}
    ${tile("recur", "Recurrence", _RR_MAIL_RIBBON_ICONS.recur)}
    ${V}
    ${tile("important", "High Importance", _RR_MAIL_RIBBON_ICONS.important)}
    ${V}
    ${tile("attach", "Attach", _RR_MAIL_RIBBON_ICONS.attach)}
    ${tile("dictate", "Dictate", _RR_MAIL_RIBBON_ICONS.dictate)}
    ${V}
    ${tile("delete", "Delete", _RR_MAIL_RIBBON_ICONS.trash, "danger")}
  </div>`;
}
function _rrMailRibbonWire(rootEl, handlers) {
  rootEl.addEventListener("click", (e) => {
    const b = e.target.closest("[data-mailact]");
    if (!b || !rootEl.contains(b)) return;
    e.preventDefault(); e.stopPropagation();
    const fn = handlers[b.getAttribute("data-mailact")];
    if (typeof fn === "function") fn(b);
  });
}
// Shared dictation (Web Speech API) for the email surfaces. Works on a
// <textarea>/<input> (value) or a contenteditable element (execCommand).
let _rrDictateRecog = null;
function _rrToggleDictate(targetEl, btn) {
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) { toast("Dictation isn't supported in this browser", "warn"); return; }
  if (_rrDictateRecog) { try { _rrDictateRecog.stop(); } catch (_) {} return; }
  const r = new SR(); _rrDictateRecog = r;
  r.continuous = true; r.interimResults = false; r.lang = "en-US";
  const insert = (t) => {
    t = (t || "").trim(); if (!t) return;
    const s = t.charAt(0).toUpperCase() + t.slice(1) + ". ";
    if (targetEl && "value" in targetEl) {
      targetEl.value += (targetEl.value && !/\s$/.test(targetEl.value) ? " " : "") + s;
    } else if (targetEl) {
      targetEl.focus(); document.execCommand("insertText", false, s);
    }
  };
  r.onresult = (e) => { let t = ""; for (let i = e.resultIndex; i < e.results.length; i++) if (e.results[i].isFinal) t += e.results[i][0].transcript; insert(t); };
  r.onend = () => { _rrDictateRecog = null; if (btn) btn.classList.remove("active"); };
  r.onerror = () => { toast("Dictation stopped", "warn"); _rrDictateRecog = null; if (btn) btn.classList.remove("active"); };
  try { r.start(); if (btn) btn.classList.add("active"); toast("Listening… speak now (click Dictate again to stop)", "info"); }
  catch (_) { _rrDictateRecog = null; }
}
// Open the calendar event editor prefilled with an email recipient, used by the
// Schedule Meeting tile on email surfaces to bridge into a calendar invite.
function _rrScheduleMeetingFor(toEmail) {
  if (typeof _ivcalNewEvent !== "function") { toast("Open the Calendar tab once, then try Schedule Meeting", "warn"); return; }
  const now = new Date(); const base = (typeof _ivcalISODate === "function") ? _ivcalISODate(now) : now.toISOString().slice(0, 10);
  _ivcalNewEvent(base, 9 * 60, 9 * 60 + 30);
  setTimeout(() => { const r = document.getElementById("rr-ne-required"); if (r && toEmail) { r.value = toEmail; } const t = document.getElementById("rr-ne-title"); if (t) t.focus(); }, 60);
}

async function openEmailThreadModal(applicantId, fullName, toEmail) {
  let m = document.getElementById("rr-email-thread-modal");
  if (m) m.remove();
  _closeEmailThreadChannel();
  m = document.createElement("div");
  m.id = "rr-email-thread-modal";
  m.style.cssText = "position:fixed;inset:0;background:var(--overlay);z-index:9999;display:flex;align-items:center;justify-content:center;padding:var(--s-6)";
  m.innerHTML = `
    ${_rrMailRibbonStyle("rr-email-thread-modal")}
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);width:min(1100px,96vw);height:88vh;max-height:88vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 70px rgba(15,23,42,.34)">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:var(--s-4) var(--s-5);border-bottom:1px solid var(--border)">
        <div>
          <div style="font-size:var(--fs-lg);font-weight:600">Email · ${escapeHtml(rrTitleCaseName(fullName))}</div>
          <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${escapeHtml(toEmail || "—")}</div>
        </div>
        <button class="btn btn-sm" data-rr-email-close>Close</button>
      </div>
      ${_rrMailRibbonHtml("Send")}
      <div id="rr-email-thread-body" style="flex:1;overflow-y:auto;padding:var(--s-4) var(--s-5);display:flex;flex-direction:column;gap:var(--s-3-5)">
        <div style="color:var(--text-subtle);font-size:var(--fs-sm)">Loading thread…</div>
      </div>
      <div style="border-top:1px solid var(--border);padding:var(--s-3-5) 22px;background:var(--surface)">
        <textarea id="rr-email-reply-body" placeholder="Type your reply…  (Enter to send · Shift+Enter for a new line)" style="width:100%;min-height:80px;padding:var(--s-2-5) var(--s-3);border:1px solid var(--border);border-radius:8px;font:inherit;resize:vertical;box-sizing:border-box"></textarea>
        <div style="display:flex;justify-content:flex-end;gap:var(--s-2);margin-top:10px">
          <button class="btn btn-primary" id="rr-email-reply-send">Send reply</button>
        </div>
      </div>
      <input type="file" id="rr-email-file" multiple style="display:none" aria-hidden="true">
    </div>`;
  document.body.appendChild(m);
  // Restore any saved draft for this driver.
  try { const d = localStorage.getItem("rr-reply-draft-" + applicantId); if (d) { const ta = document.getElementById("rr-email-reply-body"); if (ta) ta.value = d; } } catch (_) {}

  // Live-refresh the thread when a new email_messages row lands for this
  // applicant (e.g. an inbound reply arriving via webhook-email-inbound),
  // so the operator doesn't have to re-open the modal.
  _emailThreadChannel = sb.channel("rr-email-thread-" + applicantId)
    .on("postgres_changes",
        { event: "*", schema: "public", table: "email_messages", filter: "applicant_id=eq." + applicantId },
        () => { if (document.getElementById("rr-email-thread-modal")) _renderEmailThread(applicantId); })
    .subscribe();

  const closeThread = () => { _closeEmailThreadChannel(); m.remove(); };
  const draftKey = "rr-reply-draft-" + applicantId;

  async function doSendReply() {
    const ta = document.getElementById("rr-email-reply-body");
    const body = (ta?.value || "").trim();
    if (!body) { toast("Type a reply first", "warn"); return; }
    const sendBtn = document.getElementById("rr-email-reply-send");
    const ribbonSend = m.querySelector('[data-mailact="send"]');
    if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = "Sending…"; }
    if (ribbonSend) ribbonSend.style.opacity = ".5";
    const { error } = await sb.rpc("send_applicant_email", {
      p_applicant_id: applicantId, p_body: body, p_subject: null,
    });
    if (sendBtn) { sendBtn.disabled = false; sendBtn.textContent = "Send reply"; }
    if (ribbonSend) ribbonSend.style.opacity = "";
    if (error) { toast("Send failed: " + error.message, "warn"); return; }
    if (ta) ta.value = "";
    try { localStorage.removeItem(draftKey); } catch (_) {}
    toast("Reply queued", "success");
    await _renderEmailThread(applicantId);
  }

  // Enter sends; Shift+Enter inserts a newline.
  m.addEventListener("keydown", (e) => {
    if (e.target?.id === "rr-email-reply-body" && e.key === "Enter" && !e.shiftKey && !e.isComposing) {
      e.preventDefault(); doSendReply();
    }
  });

  // Backdrop / Close button / bottom send button.
  m.addEventListener("click", (e) => {
    if (e.target === m || e.target.closest("[data-rr-email-close]")) { closeThread(); return; }
    if (e.target.closest("#rr-email-reply-send")) { e.preventDefault(); doSendReply(); }
  });

  // Attach picker (replies don't carry attachments yet — warn rather than fail silently).
  const fileInp = document.getElementById("rr-email-file");
  if (fileInp) fileInp.addEventListener("change", () => {
    if (fileInp.files.length) toast("Attachments aren't sent with quick replies yet — compose from the Mail tab to attach files", "info");
    fileInp.value = "";
  });

  // The shared 9-tool ribbon.
  _rrMailRibbonWire(m, {
    send: () => doSendReply(),
    save: () => { const ta = document.getElementById("rr-email-reply-body"); try { localStorage.setItem(draftKey, ta?.value || ""); } catch (_) {} toast("Draft saved", "success"); },
    invite: () => toast(`This is a 1:1 thread with ${rrTitleCaseName(fullName) || "this driver"}. Use Schedule Meeting to set up a call.`, "info"),
    meeting: () => { closeThread(); _rrScheduleMeetingFor(toEmail); },
    recur: () => toast("Recurrence applies to scheduled meetings — use Schedule Meeting.", "info"),
    important: (b) => b.classList.toggle("active"),
    attach: () => fileInp && fileInp.click(),
    dictate: (b) => _rrToggleDictate(document.getElementById("rr-email-reply-body"), b),
    delete: () => closeThread(),
  });

  await _renderEmailThread(applicantId);
}

async function _renderEmailThread(applicantId) {
  const body = document.getElementById("rr-email-thread-body");
  if (!body) return;
  const { data: rows, error } = await sb.rpc("applicant_email_thread", { p_applicant_id: applicantId });
  if (error) {
    body.innerHTML = `<div style="color:var(--red);font-size:var(--fs-sm)">${escapeHtml(error.message)}</div>`;
    return;
  }
  if (!rows || rows.length === 0) {
    body.innerHTML = `<div style="color:var(--text-subtle);font-size:var(--fs-sm)">No emails yet. Send the first one below.</div>`;
    return;
  }
  body.innerHTML = rows.map(_renderEmailRow).join("");
  body.scrollTop = body.scrollHeight;
}

// Trim the quoted-original tail from an email reply ("On … wrote: > …",
// Outlook "Original Message" blocks, signature delimiters) so the bubble
// shows just what the person actually typed. Conservative: if trimming
// would leave nothing, keep the original.
function _stripQuotedReply(text) {
  if (!text) return "";
  const s = String(text).replace(/\r\n/g, "\n");
  const markers = [
    /\n>+ ?.*$/m,                                   // first quoted line
    /\nOn\b[\s\S]{0,400}?\bwrote: *(?:\n|$)/,       // "On <date>, <name> wrote:" (may wrap)
    /\n-{2,} ?Original Message ?-{2,}/i,            // Outlook
    /\n_{10,}\n/,                                   // Outlook divider
    /\nFrom: .*\n(?:Sent|Date|To|Subject): /i,      // Outlook header block
    /\n-- ?\n/,                                     // signature delimiter
  ];
  let cutAt = s.length;
  for (const re of markers) {
    const m = s.match(re);
    if (m && m.index !== undefined && m.index < cutAt) cutAt = m.index;
  }
  const trimmed = s.slice(0, cutAt).replace(/\s+$/g, "");
  return trimmed.trim() ? trimmed : s.replace(/\s+$/g, "");
}

function _renderEmailRow(r) {
  const inbound = r.direction === "inbound";
  const side    = inbound ? "in" : "out";
  const sender  = inbound ? "Applicant" : "You";
  const when    = r.created_at ? new Date(r.created_at).toLocaleString() : "";
  const status  = inbound ? "" : ` · ${r.status}`;
  // Plaintext only — body_html is intentionally not injected to avoid
  // remote-content shenanigans inside the operator dashboard. For inbound
  // replies, drop the quoted-original tail.
  const text = inbound
    ? _stripQuotedReply(r.body_text || "")
    : (r.body_text || "").replace(/\s+$/g, "");
  return `
    <div class="rr-email-row rr-email-row-${side}">
      <div class="u-xs-subtle rr-email-meta">${escapeHtml(sender)} · ${escapeHtml(when)}${status}</div>
      <div class="rr-email-bubble">
        <div class="rr-email-subject">${escapeHtml(r.subject || "(no subject)")}</div>
        <div class="rr-email-body">${escapeHtml(text)}</div>
      </div>
    </div>`;
}

// Skeleton card matching the .pa-card geometry — header (avatar +
// name/meta) plus a summary band of three label/value columns.  Used
// while the pipeline_list RPC is in flight so stage switches don't
// flash the previous stage's rows.
const _PA_SKEL_CARD = `
  <div class="pa-skel-card">
    <div class="pa-skel-stage"><span class="rr-skel rr-skel-sm" style="width:74px"></span><span class="rr-skel rr-skel-sm" style="width:54px"></span></div>
    <div class="pa-skel-body">
      <div class="pa-skel-header"><span class="rr-skel rr-skel-circle" style="width:36px;height:36px;flex:0 0 auto"></span><div class="pa-skel-headtext"><span class="rr-skel rr-skel-md" style="width:62%"></span><span class="rr-skel rr-skel-sm" style="width:78%"></span></div></div>
    </div>
    <div class="pa-skel-summary">
      <div class="pa-skel-col"><span class="rr-skel rr-skel-sm" style="width:60%"></span><span class="rr-skel rr-skel-md" style="width:84%"></span></div>
      <div class="pa-skel-col"><span class="rr-skel rr-skel-sm" style="width:54%"></span><span class="rr-skel rr-skel-md" style="width:72%"></span></div>
      <div class="pa-skel-col"><span class="rr-skel rr-skel-sm" style="width:64%"></span><span class="rr-skel rr-skel-md" style="width:90%"></span></div>
    </div>
  </div>`;

async function loadPipeline(stage = "all") {
  const list = $("#pipe-applicants");
  if (!list) return;

  // Paint the skeleton before the RPC so a stage switch never flashes
  // the previous stage's rows.  Stale data is also cleared when the
  // operator changes tabs.
  list.innerHTML = `${_PA_SKEL_CARD}${_PA_SKEL_CARD}${_PA_SKEL_CARD}${_PA_SKEL_CARD}`;

  const [{ data: rows, error }, { data: counts }] = await Promise.all([
    sb.rpc("pipeline_list", { p_stage: stage, p_limit: 200 }),
    sb.rpc("pipeline_counts"),
  ]);
  if (error) {
    toast("Pipeline load failed: " + error.message, "warn");
    return;
  }

  // Update tab counts. Always set (including 0) so the mockup defaults
  // don't bleed through when a stage is empty.
  const countMap = Object.fromEntries((counts ?? []).map(r => [r.stage, r.count]));
  $$("#pipeline-stage-tabs .stage-tab").forEach(btn => {
    const s = btn.getAttribute("data-stage");
    const el = btn.querySelector(".stage-tab-count");
    if (el) el.textContent = countMap[s] ?? 0;
  });

  // Cache rows by id so the per-card icon popovers can look up the full
  // applicant record (phone, email, video_url, …) without re-fetching.
  window._rrPipelineById = new Map((rows ?? []).map(r => [r.id, r]));

  const emptyMsg = stage === "action_needed"
    ? "You're all caught up — nothing needs action right now."
    : "No applicants yet — share your apply link or add one manually.";
  // Ranked triage · in the "Action needed" inbox, order most-urgent-first by a
  // derived attention score (time-in-stage + overdue + stage leverage + quality)
  // so the recruiter works top-down instead of scrolling to hunt. Other tabs
  // keep the server order.
  const ordered = (stage === "action_needed" && rows && rows.length)
    ? [...rows].sort((x, y) => _attentionScore(y) - _attentionScore(x))
    : rows;
  list.innerHTML = (ordered && ordered.length)
    ? ordered.map(renderApplicantCard).join("")
    : `<div class="rr-empty-inline">${emptyMsg}</div>`;
  // Workspace header count.
  const nRows = (rows && rows.length) || 0;
  setText("pa-ws-count", `(${nRows})`);
  setText("pa-ws-count-n", nRows);
  requestAnimationFrame(_pipeFitList);
}

// Size the applicant list so it scrolls within the viewport — the page
// header, KPI strip and stage tabs above it stay put while the DSP
// works down a long applicant queue.
function _pipeFitList() {
  // The .pa-workspace is the scroll container now (its scrollbar matches the
  // Schedule grid's .cal-wrap). Cap its height to the viewport so the rows
  // scroll inside it with an always-visible bar.
  const list = document.querySelector("#view-pipeline .pa-workspace")
    || document.getElementById("pipe-applicants");
  if (!list || !list.offsetParent) return;
  // Clear any stale inline height left on the inner list from older builds.
  const inner = document.getElementById("pipe-applicants");
  if (inner && inner !== list) inner.style.maxHeight = "";
  const top = list.getBoundingClientRect().top;
  // Stretch the list to nearly the bottom of the viewport so its scrollbar
  // runs the full height — matching the Schedule grid (which leaves a 12px
  // gap). Only the list scrolls internally; the page itself never scrolls.
  const h = Math.max(260, window.innerHeight - top - 12);
  list.style.maxHeight = h + "px";
  // Funnel is content-sized (secondary), not stretched to full height.
  const log = document.getElementById("rr-funnel-panel");
  if (log) log.style.height = "";
  // Native bars auto-hide on the operator's Chrome — attach the always-on
  // JS faux bar now that the workspace is sized and visible.
  if (window.rrSetupFauxScrollbars) window.rrSetupFauxScrollbars();
  // Force the faux track to re-measure to the just-applied height so its
  // groove spans the full container (the attach-time measure can be stale).
  requestAnimationFrame(function () {
    if (list._rrFauxUpdate) list._rrFauxUpdate();
  });
}
window.addEventListener("resize", _pipeFitList);

// Size the schedule week grid so it scrolls within the viewport — the
// command strip, KPI strip and the grid's own sticky column header all
// stay put while the DSP scrolls the driver rows.
function _schedFitGrid() {
  const wrap = document.querySelector("#sched-sub-week .cal-wrap");
  if (!wrap || !wrap.offsetParent) return;
  // Reassigning maxHeight on an overflow:scroll element briefly shrinks
  // its scrollable area and clamps scrollTop — which made the grid
  // "bounce" back toward the top after a re-render (this runs on render,
  // on resize, and via the body ResizeObserver ~60ms after rows re-add).
  // Snapshot and restore the scroll position around the resize so the
  // operator stays exactly where they were.
  const _st = wrap.scrollTop, _sl = wrap.scrollLeft;
  // Size against the actual scroll parent (.tcp-body), NOT the viewport.
  // window.innerHeight is fixed, so `innerHeight - grid.top` changed every
  // time chrome above the grid (KPI strip filling in, a banner appearing,
  // the page settling on navigation) shifted the grid's viewport `top` —
  // and it runs 2-3 times per render (sync + rAF + body ResizeObserver),
  // so the grid stepped through heights = the "grows then shrinks" bounce.
  // Measuring the gap between the grid's top and its container's bottom is
  // invariant to that: when the chrome shifts the whole block, top and
  // bottom move together, so the height stays put.
  const top = wrap.getBoundingClientRect().top;
  const scroller = wrap.closest(".tcp-body");
  const bottom = scroller ? scroller.getBoundingClientRect().bottom : window.innerHeight - 36;
  const h = Math.max(320, bottom - top - 12);
  wrap.style.maxHeight = h + "px";
  // The right rail (Open shifts) shares the row — cap it to the same
  // height so it can't stretch the page taller than the viewport.
  const rail = document.querySelector("#sched-sub-week .sched-right-rail");
  if (rail) rail.style.maxHeight = h + "px";
  if (wrap.scrollTop !== _st)  wrap.scrollTop  = _st;
  if (wrap.scrollLeft !== _sl) wrap.scrollLeft = _sl;
}
window.addEventListener("resize", _schedFitGrid);

// Re-fit the scrolling regions whenever the page settles — KPI strips,
// banners and async content shift the grid's top after first paint,
// which would otherwise leave the whole page scrollable.
let _rrFitTimer = null;
function _rrRefit() {
  clearTimeout(_rrFitTimer);
  _rrFitTimer = setTimeout(() => { _schedFitGrid(); _pipeFitList(); }, 60);
}
if (window.ResizeObserver) {
  try { new ResizeObserver(_rrRefit).observe(document.body); } catch (_) {}
}

// ─── paAction override ─────────────────────────────────────────────────────
//
// The mockup wires onclick="paAction(this,'send_link','Marcus Hill')". We
// intercept at the document level via delegated listener; if the button
// has data-rr-action (live cards), we use that and dispatch to the RPC.
// If it has the legacy onclick (static seeded HTML), we still handle it
// the same way using the card's data-applicant.

// Plaintext template body → light HTML for the composer: escape, autolink
// URLs, and convert newlines to <br> so the message reads cleanly.
function _rrTextToHtml(text) {
  const esc = (s) => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const h = esc(text)
    .replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1">$1</a>')
    .replace(/\n/g, "<br>");
  return `<div style="font-family:Calibri,Arial,sans-serif;font-size:14px;line-height:1.55">${h}</div>`;
}

// Prepare an applicant-facing email (screening / booking invite) and open it in
// the email composer for the operator to review and send — instead of auto-
// sending. Mints the link server-side, prefills the composer, and on Send flips
// the applicant's status the same way the old auto-send path did.
async function _rrComposeApplicantEmail(applicantId, purpose) {
  let prev;
  try {
    const { data, error } = await sb.rpc("preview_applicant_email", { p_id: applicantId, p_purpose: purpose });
    if (error) throw error;
    prev = data;
  } catch (e) {
    const msg = String(e.message || e);
    if (/applicant_has_no_email/.test(msg)) toast("This applicant has no email on file", "warn");
    else toast("Couldn't prepare the email: " + msg, "warn");
    return false;
  }
  if (!prev || !prev.to_email) { toast("This applicant has no email on file", "warn"); return false; }
  if (typeof window.rrOpenEmailComposer !== "function") { toast("Email composer isn't ready — open the Mail tab once, then retry", "warn"); return false; }
  window.rrOpenEmailComposer({
    mode: "new",
    to: prev.to_email,
    subject: prev.subject || "",
    html: _rrTextToHtml(prev.body_text || ""),
    applicantId,
    templateId: prev.template_id || null,
    onSent: async () => {
      try { await sb.rpc("mark_applicant_email_sent", { p_id: applicantId, p_purpose: purpose }); } catch (_) {}
      try { if (typeof loadPipeline === "function") await loadPipeline(getActiveStage()); } catch (_) {}
    },
  });
  return true;
}

// Open a blank email to the applicant in the composer (the "Email" contact
// action). Recipient prefilled; the operator writes and sends.
function _rrComposeFreeEmail(applicantId, toEmail, fullName) {
  if (!toEmail) { toast("This applicant has no email on file", "warn"); return false; }
  if (typeof window.rrOpenEmailComposer !== "function") { toast("Email composer isn't ready — open the Mail tab once, then retry", "warn"); return false; }
  window.rrOpenEmailComposer({ mode: "new", to: toEmail, subject: "", html: "", applicantId });
  return true;
}

// Open a decline/rejection email in the composer for review. On Send, the
// applicant is declined (status→rejected). Falls back to a plain confirm +
// decline when there's no email to send.
async function _rrComposeDeclineEmail(applicantId) {
  let app;
  try {
    const { data, error } = await sb.from("applicants")
      .select("first_name, full_name, email").eq("id", applicantId).single();
    if (error) throw error;
    app = data;
  } catch (e) { toast("Couldn't load applicant: " + (e.message || e), "warn"); return false; }

  const declineNow = async () => {
    try {
      const { error } = await sb.rpc("decline_applicant", { p_id: applicantId, p_reason: "Manual decline" });
      if (error) throw error;
      toast("Applicant declined");
      if (typeof loadPipeline === "function") await loadPipeline(getActiveStage());
    } catch (e) { toast("Decline failed: " + (e.message || e), "warn"); }
  };

  // No email → keep the old immediate-decline behaviour (with a confirm).
  if (!app || !app.email) {
    if (confirm("Decline this applicant and remove them from the funnel? No email will be sent.")) await declineNow();
    return true;
  }
  if (typeof window.rrOpenEmailComposer !== "function") { toast("Email composer isn't ready — open the Mail tab once, then retry", "warn"); return false; }

  const first = app.first_name || (app.full_name || "").split(" ")[0] || "there";
  const dspName = (window.RR && window.RR.dsp && window.RR.dsp.name) ? window.RR.dsp.name : "the team";
  const body =
`Hi ${first},

Thank you for your interest in driving with us and for taking the time to apply. After careful review, we've decided not to move forward with your application at this time.

We genuinely appreciate the effort you put in, and we wish you the very best in your search.

Warm regards,
${dspName}`;

  window.rrOpenEmailComposer({
    mode: "new",
    to: app.email,
    subject: "Update on your application",
    html: _rrTextToHtml(body),
    applicantId,
    onSent: async () => {
      try { await sb.rpc("decline_applicant", { p_id: applicantId, p_reason: "Declined via email" }); } catch (_) {}
      try { if (typeof loadPipeline === "function") await loadPipeline(getActiveStage()); } catch (_) {}
    },
  });
  return true;
}

async function handleAction(btn) {
  // Funnel cards use .pa-card[data-applicant]; Interview Day cards use
  // .iv-card[data-applicant-id]; popover rows carry data-applicant-id
  // directly since they live outside the card in document.body.
  const card = btn.closest(".pa-card, .iv-card");
  const id     = btn.getAttribute("data-applicant-id")
               || card?.getAttribute("data-applicant")
               || card?.getAttribute("data-applicant-id");
  const action = btn.getAttribute("data-rr-action");
  if (!id || !action) return;

  btn.disabled = true;

  try {
    if (action === "resend_screening") {
      // Open the screening invite in the email composer for review instead of
      // auto-sending — the operator edits if needed and hits Send themselves.
      await _rrComposeApplicantEmail(id, "screening");
      btn.disabled = false;
      return;
    } else if (action === "send_link" || action === "resend_link") {
      await _rrComposeApplicantEmail(id, "interview");
      btn.disabled = false;
      return;
    } else if (action === "decline") {
      // Open a decline email in the composer for review. The applicant is only
      // declined (status→rejected, removed from funnel) once the operator
      // actually sends. If they have no email on file, fall back to a confirm.
      await _rrComposeDeclineEmail(id);
      btn.disabled = false;
      return;
    } else if (action === "remove_event") {
      const eventId = btn.getAttribute("data-event-id");
      if (!eventId) { btn.disabled = false; return; }
      if (!confirm("Remove this booking? No message will be sent to the applicant and they will not get a re-booking link.")) {
        btn.disabled = false;
        return;
      }
      const { error } = await sb.rpc("cancel_cal_event_silent", { p_event_id: eventId });
      if (error) throw error;
      toast("Booking removed · no message sent", "success");
    } else if (action === "reschedule" || action === "cancel_interview") {
      const isReschedule = action === "reschedule";
      const promptText = isReschedule
        ? "Reason for asking them to reschedule? (optional · stays internal)"
        : "Reason for cancelling the interview? (optional · stays internal)";
      const reason = prompt(promptText);
      if (reason === null) { btn.disabled = false; return; }
      // Both wire to the cancel_interview RPC: it voids the current
      // booking, queues the cancellation SMS/email with a fresh booking
      // link, and reverts applicant.status to interview_invited so they
      // show up in Booking pending. Operators get separate buttons
      // because the wording on the operator side ("Reschedule" vs
      // "Cancel interview") matches different conversations they're
      // having with the applicant.
      const { error } = await sb.rpc("cancel_interview", { p_applicant_id: id, p_reason: reason || null });
      if (error) throw error;
      toast(isReschedule
        ? "Reschedule requested · applicant sent a new booking link"
        : "Interview cancelled · applicant sent a new booking link", "success");
    } else if (action === "call") {
      // Dial via tel: link; no backend call.
      const { data } = await sb.from("applicants").select("phone").eq("id", id).single();
      if (data?.phone) location.href = `tel:${data.phone}`;
      else toast("No phone on file", "warn");
      btn.disabled = false;
      return;
    } else if (action === "play_video") {
      const url = btn.getAttribute("data-video-url");
      if (url) openVideoModal(url);
      // Mark the video reviewed and calm the CTA in place — drop the
      // unwatched dot, relabel, and hand the loud-primary state to the
      // advance button. No refetch needed.
      _paMarkVideoWatched(id);
      if (btn.classList.contains("pa-btn-video")) {
        btn.classList.add("is-watched");
        btn.querySelector(".pa-btn-video-dot")?.remove();
        const lbl = btn.querySelector(".pa-btn-video-lbl");
        if (lbl) lbl.textContent = "Re-watch video";
        card?.querySelector(".pa-btn-advance")?.classList.add("is-primary");
      }
      btn.disabled = false;
      return;
    } else if (action === "open_onboarding") {
      // Hired-card CTA — the driver row already exists (record_outcome
      // created it on hire); take the operator to the onboarding roster.
      btn.disabled = false;
      goto("onboarding-ops");
      return;
    } else if (action === "email_thread") {
      // Look up the applicant's display name for the modal header.
      const { data: a } = await sb.from("applicants")
        .select("full_name, email").eq("id", id).single();
      openEmailThreadModal(id, a?.full_name || "", a?.email || "");
      btn.disabled = false;
      return;
    }
    await loadPipeline(getActiveStage());
    // If the action originated from the Interview Day card, also refresh
    // that view so the rescheduled / cancelled applicant disappears
    // immediately. Funnel-only actions still refresh just the funnel.
    if (card?.classList.contains("iv-card") && typeof loadInterviewDay === "function") {
      await loadInterviewDay();
    }
  } catch (e) {
    toast("Action failed: " + (e.message ?? e), "warn");
    btn.disabled = false;
  }
}

document.addEventListener("click", (e) => {
  // Watch-video pill works on both .pa-card and .iv-card — handle as a
  // standalone action that doesn't need a parent card lookup.
  const playBtn = e.target.closest("[data-rr-play-video]");
  if (playBtn) {
    e.preventDefault();
    e.stopImmediatePropagation();
    const url = playBtn.getAttribute("data-video-url");
    if (url) openVideoModal(url);
    return;
  }
  const btn = e.target.closest("[data-rr-action]");
  if (btn) {
    e.preventDefault();
    e.stopImmediatePropagation();
    handleAction(btn);
  }
}, true);

// Replace the mockup's window.paAction with a thin shim that uses the
// data-rr-action path so legacy seeded inline-onclick markup keeps working
// after the first re-render (until then it triggers the mockup's toast).
const _legacyPaAction = window.paAction;
window.paAction = function (btn, action, _name) {
  btn.setAttribute("data-rr-action", action);
  return handleAction(btn);
};

// ── Schedule command strip · Schedule / Print mode tabs ────────────
// The "Print" tab swaps the icon ribbon for a single left-justified
// print button; the choice sticks until the DSP clicks back to
// "Schedule". The print button clones the week grid + a heading into
// a print-only mount and calls window.print() — only the schedule
// (not the surrounding page chrome) ends up on the page / PDF.
function _schedCmdTab(mode) {
  const cmd = document.getElementById("rr-sched-cmd");
  if (cmd) {
    cmd.classList.toggle("is-print",    mode === "print");
    cmd.classList.toggle("is-insights", mode === "insights");
    // Intelligence mode · swaps the icon stripe for 5 forecast tiles.
    // Page contents below the stripe stay exactly as the operator
    // left them on the Schedule tab; only the ribbon swaps. Real
    // wiring lands in a follow-up (risk forecast / compliance watch
    // / hiring pulse / peak days / what-if).
    cmd.classList.toggle("is-intel",    mode === "intelligence");
  }
  document.body.classList.toggle("rr-sched-insights", mode === "insights");
  // The tabs themselves moved out of #rr-sched-cmd to the V2 strip
  // in PR #1621, so the .active class must be toggled document-wide
  // (and on any legacy tabs still in the DOM in case both copies
  // are ever rendered).
  document.querySelectorAll(".sched-cmd-tab").forEach((t) => {
    const on = t.getAttribute("data-cmd-tab") === mode;
    t.classList.toggle("active", on);
    t.setAttribute("aria-selected", on ? "true" : "false");
  });
  // Render the Insights view on first activation; reveal the existing
  // node on subsequent clicks.
  if (mode === "insights" && typeof _renderSchedInsights === "function") {
    _renderSchedInsights();
  }
}

// Placeholder Insights tab. Stub for now — drops a panel above the
// week grid that's only visible when the Insights tab is active;
// future work fills it with week-over-week analytics, surprise-shifts,
// projection breakdowns, etc.
function _renderSchedInsights() {
  const host = document.getElementById("sched-sub-week");
  if (!host) return;
  let panel = document.getElementById("rr-sched-insights-panel");
  if (!panel) {
    panel = document.createElement("div");
    panel.id = "rr-sched-insights-panel";
    panel.className = "sched-insights-panel";
    host.prepend(panel);
  }
  // (Re)render the contents every time the tab is activated so the
  // latest run + a fresh AI explanation are reachable.
  _rrPaintInsightsPanel(panel);
}

// Insights tab body — fetches the latest optimization_run for the
// current DSP/week and shows its metrics + an "Explain in plain
// English" button that calls the explain-optimization-run edge
// function. Cached explanations come back instantly.
async function _rrPaintInsightsPanel(panel) {
  panel.innerHTML = `
    <div class="rr-insights-card">
      <div class="rr-insights-card-head">
        <span class="rr-insights-card-title">Latest Smart Fill run</span>
        <span class="rr-insights-card-meta" id="rr-insights-run-meta">Loading…</span>
      </div>
      <div class="rr-insights-metrics" id="rr-insights-metrics"></div>
      <div class="rr-insights-explain">
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button type="button" class="rr-insights-explain-btn" id="rr-insights-explain-btn" disabled>
            Explain in plain English
          </button>
          <button type="button" class="rr-insights-explain-btn" id="rr-insights-diag-btn" disabled>
            Download diagnostics
          </button>
        </div>
        <div class="rr-insights-explain-out" id="rr-insights-explain-out"></div>
      </div>
    </div>
  `;
  _rrInjectInsightsPanelCss();

  // Diagnostics: re-run the LAST Smart Fill payload through the solver
  // in trace mode and download the full decision report (.txt + .json).
  // Wired before the run fetch below — it depends only on the payload
  // cached by autoFill in this tab, not on the audit row loading.
  const diagBtn = document.getElementById("rr-insights-diag-btn");
  if (diagBtn) {
    if (window._rrLastSmartFillPayload && typeof _rrSmartFillDiagnostics === "function") {
      diagBtn.disabled = false;
      diagBtn.title = "Re-run the last Smart Fill in the solver's trace mode and " +
        "download the per-driver / per-shift decision report. Read-only — never changes the schedule.";
      diagBtn.onclick = async () => {
        diagBtn.disabled = true;
        diagBtn.textContent = "Tracing…";
        try { await _rrSmartFillDiagnostics({ download: true }); }
        finally {
          diagBtn.disabled = false;
          diagBtn.textContent = "Download diagnostics";
        }
      };
    } else {
      diagBtn.title = "Run Smart Fill first — diagnostics re-run the most recent " +
        "Smart Fill from this tab in trace mode.";
    }
  }

  const dspId = window.RR?.dsp?.id;
  if (!dspId) {
    document.getElementById("rr-insights-run-meta").textContent = "DSP not loaded.";
    return;
  }

  // Pull the most recent OK run for the visible week (fall back to most
  // recent overall if none for this week).
  const weekStart = _schedStart || null;
  let q = sb.from("optimization_runs")
    .select("id, week_start, trigger_kind, status, metrics, enqueued_at, finished_at")
    .eq("dsp_id", dspId)
    .order("enqueued_at", { ascending: false })
    .limit(1);
  if (weekStart) q = q.eq("week_start", weekStart);
  let { data: rows } = await q;
  if (!rows || rows.length === 0) {
    // Try without week filter for the fallback.
    const fb = await sb.from("optimization_runs")
      .select("id, week_start, trigger_kind, status, metrics, enqueued_at, finished_at")
      .eq("dsp_id", dspId)
      .order("enqueued_at", { ascending: false })
      .limit(1);
    rows = fb.data || [];
  }
  if (!rows || rows.length === 0) {
    document.getElementById("rr-insights-run-meta").textContent =
      "No Smart Fill runs yet — click Smart Fill on the Schedule tab to generate one.";
    return;
  }
  const run = rows[0];
  const m = run.metrics || {};
  const date = new Date(run.enqueued_at).toLocaleString();
  document.getElementById("rr-insights-run-meta").textContent =
    `Week ${run.week_start} · ${run.trigger_kind} · ${run.status} · ${date}`;
  const fmt = (n) => (n == null ? "—" : n);
  document.getElementById("rr-insights-metrics").innerHTML = `
    <div class="rr-insights-metric"><div class="v">${fmt(m.coverage_pct)}%</div><div class="l">Coverage</div></div>
    <div class="rr-insights-metric"><div class="v">${fmt(m.assigned)}</div><div class="l">Assigned</div></div>
    <div class="rr-insights-metric"><div class="v">${fmt(m.uncovered)}</div><div class="l">Uncovered</div></div>
    <div class="rr-insights-metric"><div class="v">${fmt(m.unscheduled_drivers)}</div><div class="l">Drivers off</div></div>
    <div class="rr-insights-metric"><div class="v">${fmt(m.total_shifts)}</div><div class="l">Total shifts</div></div>
  `;
  const btn = document.getElementById("rr-insights-explain-btn");
  const out = document.getElementById("rr-insights-explain-out");
  btn.disabled = false;
  btn.dataset.runId = run.id;
  btn.onclick = async () => {
    btn.disabled = true;
    btn.textContent = "Asking Claude…";
    out.style.display = "block";
    out.textContent = "…";
    try {
      const { data, error } = await sb.functions.invoke("explain-optimization-run", {
        body: { run_id: run.id, question_kind: "summary" },
      });
      if (error) throw error;
      out.textContent = data?.answer || _rrLocalRunSummary(run, m);
    } catch (e) {
      // The AI explanation edge function is unavailable (not deployed,
      // offline, rate-limited, …). Rather than dump a deploy command at
      // the operator, fall back to a plain-English summary built from the
      // run metrics we already have on hand.
      out.textContent = _rrLocalRunSummary(run, m);
    } finally {
      btn.disabled = false;
      btn.textContent = "Explain in plain English";
    }
  };
}
// Plain-English summary of a Smart Fill run, generated locally from the
// metrics we already loaded — the graceful fallback when the AI
// explain-optimization-run edge function isn't reachable. Deterministic,
// no network, always available.
function _rrLocalRunSummary(run, m) {
  m = m || {};
  const num = (v) => (v == null ? null : v);
  const cov = num(m.coverage_pct);
  const assigned = num(m.assigned);
  const total = num(m.total_shifts);
  const uncovered = num(m.uncovered);
  const offDrivers = num(m.unscheduled_drivers);
  const parts = [];

  parts.push(
    `Smart Fill for the week of ${run.week_start}` +
    (cov != null ? ` covered ${cov}% of shifts.` : ` finished (${run.status}).`)
  );

  if (assigned != null || total != null) {
    parts.push(
      `It assigned ${assigned ?? "—"}${total != null ? " of " + total : ""} shift` +
      ((assigned === 1 && total == null) ? "" : "s") +
      (uncovered ? `, leaving ${uncovered} uncovered.` : ".")
    );
  }

  if (offDrivers) {
    parts.push(`${offDrivers} driver${offDrivers === 1 ? "" : "s"} ended up with no shifts this week.`);
  }

  if (uncovered) {
    parts.push(
      `To close the ${uncovered} open shift${uncovered === 1 ? "" : "s"}, open the Coverage drill-down to see who's eligible, ` +
      `or relax a Smart Fill rule (5th-day, max days per week, or attendance weighting) and re-run.`
    );
  } else if (cov === 100 || (uncovered === 0 && assigned != null)) {
    parts.push(`Every shift is covered — no action needed.`);
  }

  parts.push("(Quick summary generated on-device — the AI explanation service wasn't reachable just now.)");
  return parts.join(" ");
}

