// Inject the Insights panel's show/hide rule once on script load.
(function _rrInjectInsightsCss() {
  if (typeof document === "undefined") return;
  if (document.getElementById("rr-sched-insights-css")) return;
  const css = document.createElement("style");
  css.id = "rr-sched-insights-css";
  css.textContent =
    "#rr-sched-insights-panel{display:none}" +
    "body.rr-sched-insights #rr-sched-insights-panel{display:block}";
  document.head?.appendChild(css);
})();

function _schedPrint() {
  const sub  = document.getElementById("sched-sub-week");
  const grid = sub && sub.querySelector(".cal-wrap");
  const area = document.getElementById("rr-sched-print-area");
  if (!grid || !area) { window.print(); return; }
  const subTxt = (document.getElementById("rr-sched-page-sub")?.textContent || "").trim();
  area.innerHTML = "";
  const head = document.createElement("div");
  head.className = "rr-print-head";
  head.textContent = subTxt ? "Schedule — " + subTxt : "Schedule";
  area.appendChild(head);
  area.appendChild(grid.cloneNode(true));
  _rrApplyPrintOrient("schedule");
  document.documentElement.classList.add("rr-printing");
  window.addEventListener("afterprint", function _done() {
    window.removeEventListener("afterprint", _done);
    document.documentElement.classList.remove("rr-printing");
    area.innerHTML = "";
    _rrClearPrintOrient();
  });
  window.print();
}

// Export the visible week schedule as a CSV (opens straight into Excel).
// Scrapes the rendered grid so it captures exactly what's on screen.
function _schedCsvField(v) {
  const s = String(v == null ? "" : v);
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function _schedDownloadSchedule() {
  const wrap = document.querySelector("#sched-sub-week .cal-wrap");
  if (!wrap) { toast("Open the week schedule first", "warn"); return; }
  const clean = (el) => (el ? el.innerText : "")
    .split("\n").map(s => s.trim()).filter(Boolean).join(" · ");
  const rows = [];
  const header = ["Driver", "Details"];
  wrap.querySelectorAll(".cal-cell-head").forEach(h => header.push(clean(h)));
  rows.push(header);
  wrap.querySelectorAll(".cal-grid").forEach(g => {
    const name = clean(g.querySelector(".cal-row-label-name"));
    if (!name) return;
    const row = [name, clean(g.querySelector(".cal-row-label-meta"))];
    g.querySelectorAll(".cal-cell").forEach(c => row.push(clean(c)));
    rows.push(row);
  });
  if (rows.length < 2) { toast("Nothing to download yet", "warn"); return; }
  const bom = String.fromCharCode(0xFEFF);
  const csv = bom + rows.map(r => r.map(_schedCsvField).join(",")).join("\r\n");
  const week = ((document.getElementById("rr-sched-page-sub")?.textContent) || "schedule")
    .trim().replace(/[^\w]+/g, "-").replace(/^-+|-+$/g, "").toLowerCase() || "schedule";
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `routeready-${week}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast("Schedule downloaded", "success");
}

document.addEventListener("click", (e) => {
  const tab = e.target.closest(".sched-cmd-tab");
  if (tab) {
    e.preventDefault();
    const mode = tab.getAttribute("data-cmd-tab");
    // Roster + Onboarding + Fleet + Workflows render their views,
    // but they're conceptually PART of Schedule — sidebar stays
    // lit on Schedule throughout.
    if (mode === "roster" || mode === "onboarding" || mode === "fleet" || mode === "workflows") {
      const dest =
        mode === "fleet"     ? "fleet" :
        mode === "workflows" ? "forms" :
                               "onboarding-ops";
      try { window.goto(dest); } catch (_) {}
      setTimeout(() => {
        if (mode === "fleet") {
          if (typeof _flCmdTab === "function") _flCmdTab("fleet");
        } else if (mode !== "workflows" && typeof _obCmdTab === "function") {
          _obCmdTab(mode === "roster" ? "roster" : "ops");
        }
        // Keep sidebar lit on Schedule.
        document.querySelectorAll(".nav-item[data-view].active").forEach((b) => b.classList.remove("active"));
        const schedNav = document.querySelector('.nav-item[data-view="schedule"]');
        if (schedNav) schedNav.classList.add("active");
      }, 0);
      return;
    }
    _schedCmdTab(mode);
    // Leaving the Intelligence ribbon · close any open intel view
    // so the operator returns to the normal schedule surfaces.
    if (mode !== "intelligence") _rrIntelHide();
    return;
  }
  if (e.target.closest("#rr-sched-print-btn")) { e.preventDefault(); _schedPrint(); return; }
  if (e.target.closest("#rr-sched-download-btn")) { e.preventDefault(); _schedDownloadSchedule(); return; }
  // Intelligence ribbon · clicking a tile shows / toggles its view.
  const intelTile = e.target.closest("[data-rr-intel]");
  if (intelTile) {
    e.preventDefault();
    const name = intelTile.getAttribute("data-rr-intel");
    _rrIntelToggle(name);
    return;
  }
  // Close button inside an intel view.
  if (e.target.closest("[data-rr-intel-close]")) {
    e.preventDefault();
    _rrIntelHide();
    return;
  }
});

// ─── Intelligence views · routing + renderers ──────────────────────
// Activated by the 5 Intelligence-ribbon tiles. Each view writes its
// HTML into a single host (#rr-intel-host) and swaps the active
// .sched-subview out so the operator sees the analysis full-width
// under the schedule's KPI strip. The schedule's command strip and
// KPI strip stay put — only the content area below them is owned by
// the active intel view. Clicking the Schedule tab restores the
// previously-active sub-view.
let _rrIntelActiveName = null;
let _rrIntelPriorSubview = null;

function _rrIntelToggle(name) {
  if (_rrIntelActiveName === name) { _rrIntelHide(); return; }
  _rrIntelShow(name);
}

function _rrIntelShow(name) {
  const host = document.getElementById("rr-intel-host");
  const view = document.getElementById("rr-intel-view-" + name);
  if (!host || !view) return;
  // Remember which sched-subview was visible so we can restore it.
  // Check the CSSOM property, not the style attribute: schedSub hides
  // views with el.style.display = "none", which serializes as
  // "display: none" (with a space), so a [style*='display:none']
  // attribute match misses every JS-hidden view and would always
  // record the first subview in DOM order (the week grid).
  if (!_rrIntelActiveName) {
    const active = Array.from(document.querySelectorAll("#view-schedule .sched-subview"))
      .find((s) => s.style.display !== "none");
    _rrIntelPriorSubview = active?.id || null;
  }
  // Hide every sched-subview while the intel view is up.
  document.querySelectorAll("#view-schedule .sched-subview").forEach((s) => { s.style.display = "none"; });
  // Hide every other intel view; show this one.
  document.querySelectorAll(".rr-intel-view").forEach((v) => { v.hidden = (v !== view); });
  host.hidden = false;
  // Tile active-state mirrors the active view.
  document.querySelectorAll(".sched-v2-intel-tile").forEach((t) => {
    t.classList.toggle("is-active", t.getAttribute("data-rr-intel") === name);
  });
  _rrIntelActiveName = name;
  // Dispatch to the named renderer.
  const renderer = _RR_INTEL_RENDERERS[name];
  if (typeof renderer === "function") {
    try { renderer(view); } catch (e) { console.warn("intel render", name, e); }
  } else {
    view.innerHTML = `<div class="rr-intel-empty">Coming soon · ${name.replace(/-/g, " ")}</div>`;
  }
}

function _rrIntelHide() {
  const host = document.getElementById("rr-intel-host");
  if (host) host.hidden = true;
  document.querySelectorAll(".rr-intel-view").forEach((v) => { v.hidden = true; });
  document.querySelectorAll(".sched-v2-intel-tile").forEach((t) => t.classList.remove("is-active"));
  // Restore the sched-subview that was visible before we took over.
  // "block" (not "") matches how schedSub shows a subview, and keeps
  // the rrx flex-sizing rule keyed on [style*="block"] applying.
  if (_rrIntelPriorSubview) {
    const prior = document.getElementById(_rrIntelPriorSubview);
    if (prior) prior.style.display = "block";
  } else {
    // No prior recorded — default to whatever the data-sub button
    // says is active in the schedule's sub-nav.
    const activeBtn = document.querySelector("#view-schedule .subnav-item.active[data-sub]");
    const sub = activeBtn?.getAttribute("data-sub") || "week";
    const target = document.getElementById("sched-sub-" + sub);
    if (target) target.style.display = "block";
  }
  _rrIntelActiveName = null;
  _rrIntelPriorSubview = null;
}

// ── Risk forecast · summarizes the OKAMI 13-week table as a calm,
//    Microsoft-style coverage analysis. Reads what's already in the
//    DOM (#okami-tbody, populated by renderOkamiLive or the hard-
//    coded seed); we don't issue new RPCs so the view opens instantly
//    and the analysis matches whatever the operator just saw on the
//    13-week planner.
// Simulation cache · populated by the "Simulate 13 weeks" button on
// the Targets planner card. Shape: { [yyyy-mm-dd weekStart]: { available,
// onTimeOff, onPto, totalActive } }. When set, _rrReadOkamiWeeks
// overrides each week's `avail` with the PTO-adjusted number from the
// projection so the Risk Forecast reads the real-data view instead of
// OKAMI's planning seed.
window._rrSimResultsByWeek = window._rrSimResultsByWeek || null;
window._rrSimResultsRanAt  = window._rrSimResultsRanAt  || null;

// ── Forecast rates · observed callout %, attrition %, onboarding ramp ──────
// The honest-supply inputs for forecast-core.js: how often scheduled shifts
// actually go uncovered (60-day callout/no-show rate), how fast the roster
// shrinks (90-day termination rate, pro-rated weekly), which onboarding
// drivers aren't road-ready yet (hire_date gate — same convention as the
// staffing outlook), and the configured drivers-per-route ratio so OKAMI
// and the outlook stop disagreeing about demand. Cached 10 minutes; loads
// lazily so the Targets page and Risk Forecast first-paint stay instant,
// then repaints both surfaces when the real rates land.
window._rrForecastRates = window._rrForecastRates || null;
let _rrForecastRatesPromise = null;
function _rrEnsureForecastRates() {
  const cached = window._rrForecastRates;
  if (cached && Date.now() - cached.loadedAt < 10 * 60 * 1000) return Promise.resolve(cached);
  if (_rrForecastRatesPromise) return _rrForecastRatesPromise;
  _rrForecastRatesPromise = (async () => {
    const dspId = window.RR?.dsp?.id;
    if (!dspId) return null;
    const since60 = fmtIsoDate(addDays(new Date(), -60));
    const since90 = new Date(Date.now() - 90 * 86400000).toISOString();
    const [calloutRes, totalRes, termRes, activeRes, onbRes, hsRes] = await Promise.all([
      sb.from("shifts").select("id", { count: "exact", head: true }).eq("dsp_id", dspId).gte("date", since60).in("status", ["called_off", "no_show"]),
      sb.from("shifts").select("id", { count: "exact", head: true }).eq("dsp_id", dspId).gte("date", since60).in("status", ["scheduled", "completed", "called_off", "no_show"]),
      sb.from("drivers").select("id", { count: "exact", head: true }).eq("dsp_id", dspId).eq("status", "terminated").gte("updated_at", since90),
      sb.from("drivers").select("id", { count: "exact", head: true }).eq("dsp_id", dspId).eq("status", "active"),
      sb.from("drivers").select("id, hire_date").eq("dsp_id", dspId).eq("status", "onboarding"),
      sb.rpc("hiring_settings_get"),
    ]);
    const totalShifts = totalRes.count || 0;
    const calloutRate = totalShifts > 0 ? Math.min(0.5, (calloutRes.count || 0) / totalShifts) : 0;
    const activeCount = activeRes.count || 0;
    const terms90 = termRes.count || 0;
    // Terminations per week over the trailing 90 days ÷ current actives.
    // Capped at 10%/wk so one bad data import can't zero the forecast.
    const weeklyAttritionRate = activeCount > 0
      ? Math.min(0.10, (terms90 / (90 / 7)) / activeCount)
      : 0;
    const onboarding = (onbRes.data || []).map((d) => ({ id: d.id, hire_date: d.hire_date || null }));
    const dprRaw = Number(hsRes?.data?.drivers_per_route);
    const driversPerRoute = Number.isFinite(dprRaw) ? Math.max(1, Math.min(5, dprRaw)) : 2;
    const rates = {
      calloutRate, weeklyAttritionRate, onboarding, driversPerRoute,
      terms90, activeCount, totalShifts60: totalShifts, loadedAt: Date.now(),
    };
    window._rrForecastRates = rates;
    // Repaint the surfaces that fold these in, if they're on screen.
    try { if (typeof _rrRefreshTargetsGapCard === "function") _rrRefreshTargetsGapCard(); } catch (_) {}
    try {
      if (typeof _rrIntelActiveName !== "undefined" && _rrIntelActiveName === "risk-forecast") {
        const view = document.getElementById("rr-intel-view-risk-forecast");
        if (view) _rrIntelRenderRiskForecast(view);
      }
    } catch (_) {}
    return rates;
  })().catch((e) => { console.warn("forecast-rates:", e?.message || e); return null; })
     .finally(() => { _rrForecastRatesPromise = null; });
  return _rrForecastRatesPromise;
}

// Onboarding drivers count toward supply only from their road-ready week
// (hire_date ≤ week start — the staffing outlook's convention). Missing
// hire_date = not schedulable for planning purposes.
function _rrOnboardingNotReadyByWeek(weeks) {
  const rates = window._rrForecastRates;
  const out = {};
  if (!rates || !Array.isArray(rates.onboarding) || !rates.onboarding.length) return out;
  for (const w of weeks) {
    if (!w.weekStartIso) continue;
    out[w.weekStartIso] = rates.onboarding
      .filter((o) => !o.hire_date || o.hire_date > w.weekStartIso).length;
  }
  return out;
}

// One assessment call shared by the Risk Forecast view and the Targets gap
// card — both render from the exact same forecast-core result.
function _rrAssessOkamiPlan(weeks, overrides) {
  const rates = window._rrForecastRates || {};
  const o = overrides || {};
  return rrAssessLaborPlan(weeks, {
    todayIso: fmtIsoDate(new Date()),
    hireLeadDays: Number.isFinite(o.hireLeadDays) ? o.hireLeadDays : RR_OKAMI_HIRE_LEAD_DAYS,
    calloutRate: Number.isFinite(o.calloutRate) ? o.calloutRate : (rates.calloutRate || 0),
    weeklyAttritionRate: Number.isFinite(o.weeklyAttritionRate) ? o.weeklyAttritionRate : (rates.weeklyAttritionRate || 0),
    onboardingNotReadyByWeek: _rrOnboardingNotReadyByWeek(weeks),
    extraSupply: o.extraSupply || null,
    demandOverride: o.demandOverride || null,
  });
}

// ── Risk-forecast calculator · sandbox assumption overrides ───────────────
// State behind the Risk Forecast's assumptions bar. Every field is an
// override over the observed/configured value; null (or an empty state) =
// use observed. Lives on window so the dials survive re-renders and rate
// loads. Display-only — nothing here writes back to the plan.
window._rrRfCalc = window._rrRfCalc || {};
function _rrRfOverrides() {
  const c = window._rrRfCalc || {};
  const o = {};
  if (c.calloutPct != null) o.calloutRate = c.calloutPct / 100;
  if (c.attrPct != null) o.weeklyAttritionRate = c.attrPct / 100;
  if (c.leadDays != null) o.hireLeadDays = c.leadDays;
  if (c.dpr != null || c.padPct != null) {
    o.demandOverride = {
      driversPerRoute: c.dpr != null ? c.dpr : (window._rrForecastRates?.driversPerRoute ?? 2),
      padPct: c.padPct != null ? c.padPct
        : Math.max(0, Math.min(50, Number(window.RR?.dsp?.metadata?.staffing?.plan_pad_pct ?? 10) || 0)),
    };
  }
  if (c.hires > 0 && c.fromIso) o.extraSupply = { fromIso: c.fromIso, count: c.hires };
  return o;
}

// ── Flex capacity · tier-aware absorption + hiring plan (edge engine) ──────
// Calls the flex-capacity edge function, which loads the DSP-week's live
// rows (driver availability, preferred days, 5th-day opt-ins, certs, PTO,
// scheduled shifts, demand) and runs the pure engine in /flex-capacity.
// scenario_simple carries what-if counts; omitted → a no-op scenario, whose
// WhatIfResult is the coverage verdict for the week exactly as planned.
// Results cache 10 minutes per (week, scenario). Degrades silently when the
// function isn't reachable — the UI simply doesn't show the plan block.
window._rrFlexByWeek = window._rrFlexByWeek || {};
const _RR_FLEX_NOOP = { addRoutesPerDay: 0 };
async function _rrFlexForWeek(weekStartIso, scenarioSimple) {
  if (!weekStartIso) return null;
  const simple = scenarioSimple || _RR_FLEX_NOOP;
  const key = weekStartIso + "|" + JSON.stringify(simple);
  const cached = window._rrFlexByWeek[key];
  if (cached && Date.now() - cached.at < 10 * 60 * 1000) return cached.data;
  try {
    const { data, error } = await sb.functions.invoke("flex-capacity", {
      body: { week_start: weekStartIso, scenario_simple: simple },
    });
    if (error || !data || data.error) throw (error || new Error(data?.error || "flex_failed"));
    window._rrFlexByWeek[key] = { at: Date.now(), data };
    return data;
  } catch (e) {
    console.warn("flex-capacity:", e?.message || e);
    return null;
  }
}
function _rrFlexBaseCached(weekStartIso) {
  const hit = window._rrFlexByWeek[weekStartIso + "|" + JSON.stringify(_RR_FLEX_NOOP)];
  return hit && Date.now() - hit.at < 10 * 60 * 1000 ? hit.data : null;
}

// Engine verdict (green/yellow/red/critical) → display language + the
// legacy status classes. Tier words, not alarm words: the verdict answers
// "HOW would this week be covered", not "is it at risk".
const _RR_FLEX_VERDICT = {
  green:    { label: "Covered comfortably",  cls: "ok",    hint: "Preferred days and normal patterns absorb it." },
  yellow:   { label: "Covered at stretch",   cls: "tight", hint: "Needs non-preferred days and voluntary 5th days." },
  red:      { label: "Needs hires",          cls: "risk",  hint: "Even the emergency ceiling barely covers it — hire." },
  critical: { label: "Cannot cover",         cls: "risk",  hint: "Demand exceeds the maximum tier — hire and mitigate." },
};

// Fill the Risk Forecast coverage-plan block for the break week. Patches
// the placeholder in place (no full re-render); bails silently if the view
// changed underneath or the engine isn't reachable.
async function _rrFillFlexPlan(weekStartIso, weekLabel) {
  const host = document.getElementById("rr-intel-flex-plan");
  if (!host || host.dataset.week !== weekStartIso) return;
  const data = await _rrFlexForWeek(weekStartIso);
  const still = document.getElementById("rr-intel-flex-plan");
  if (!still || still.dataset.week !== weekStartIso) return;
  if (!data || !data.flex) { still.remove(); return; }
  const { flex, whatIf } = data;
  const v = _RR_FLEX_VERDICT[whatIf?.status] || _RR_FLEX_VERDICT.green;
  const kpi = flex.kpi || {};
  const hireLine = whatIf && whatIf.driversNeeded > 0
    ? `<div class="rr-intel-flexmini-hire"><strong>Hire ${whatIf.driversNeeded}</strong>
        (${whatIf.recommendedFtHires} FT + ${whatIf.recommendedPtHires} PT)
        · OT risk ${escapeHtml(whatIf.otRisk || "—")} · ${Math.round(whatIf.confidenceScore || 0)}% conf</div>`
    : `<div class="rr-intel-flexmini-hire">No hires required${
        whatIf?.status === "yellow" ? " — use voluntary 5th days" : ""}.</div>`;
  // Compact card — lives in the third column of the detail band so the
  // panel fits one viewport. Tier meanings move to title tooltips.
  still.innerHTML = `
    <div class="rr-intel-flexmini-head" title="From live availability, preferred days, 5th-day opt-ins, certs, PTO + scheduled shifts">
      <span>Coverage plan · ${escapeHtml(weekLabel)}</span>
      <span class="rr-intel-headline-pill ${v.cls}"><span class="dot"></span>${escapeHtml(v.label)}</span>
    </div>
    <div class="rr-intel-flexmini-rows">
      <div title="Preferred days, no pattern disruption"><span>Comfortable</span><strong>+${Number(kpi.comfortableRoutesAvailable) || 0} rt/day</strong></div>
      <div title="Non-preferred days + voluntary 5th days"><span>Stretch</span><strong>+${Number(kpi.stretchRoutesAvailable) || 0} rt/day</strong></div>
      <div title="Emergency only — not sustainable"><span>Maximum</span><strong>+${Number(kpi.maximumRoutesAvailable) || 0} rt/day</strong></div>
    </div>
    ${hireLine}`;
  // The gap card can now enrich its prescription with the FT/PT split.
  try { if (typeof _rrRefreshTargetsGapCard === "function") _rrRefreshTargetsGapCard(); } catch (_) {}
}

// Map an OKAMI row's week label (e.g. "W22 May 24–30") to an ISO date
// the simulation cache is keyed by. _okamiStart is the ISO date of
// week-0 in the table; each subsequent row is +7 days. Returns null
// when _okamiStart isn't loaded yet.
function _rrOkamiWeekStartIso(idx) {
  const start = window._okamiStart;
  if (!start) return null;
  const d = new Date(start + "T12:00:00");
  d.setDate(d.getDate() + (idx * 7));
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

function _rrReadOkamiWeeks() {
  // Preferred path: the data model renderOkamiLive publishes on every
  // render (window._rrOkamiModel). Reading data instead of scraping table
  // cells means the Risk Forecast and gap card can't drift from the
  // planner because of markup changes, and they keep working even when
  // the OKAMI table isn't mounted.
  const model = window._rrOkamiModel;
  if (model && Array.isArray(model.weeks) && model.weeks.length) {
    return model.weeks.map((w) => {
      let simAvail = null, simOnPto = null, simOnTimeOff = null;
      if (window._rrSimResultsByWeek && w.weekStartIso) {
        const sim = window._rrSimResultsByWeek[w.weekStartIso];
        if (sim) {
          simAvail     = sim.available;
          simOnPto     = sim.onPto;
          simOnTimeOff = sim.onTimeOff;
        }
      }
      const effectiveAvail = simAvail != null ? simAvail : w.avail;
      const effectiveGap   = effectiveAvail - w.needed;
      return {
        idx: w.idx, label: w.label, dates: w.dates, needed: w.needed,
        routesMax: w.routesMax,
        weekStartIso: w.weekStartIso,
        avail: effectiveAvail,
        gap: effectiveGap,
        gapKind: effectiveGap >= 0 ? "ok" : "bad",
        statusText: w.statusText, statusKind: w.statusKind, hireBy: w.hireBy,
        plannedAvail: w.avail,
        simAvail, simOnPto, simOnTimeOff,
        isSimulated: simAvail != null,
      };
    });
  }

  // Fallback: scrape the rendered table (pre-model mock content). Each
  // non-detail <tr> = one week. Cells:
  //   col 0: Week label + dates (+ tags)
  //   col 1: Routes (max) — operator input
  //   col 2: Drivers needed (.plan-calc)
  //   col 3: Available (.plan-calc)
  //   col 4: Gap (.plan-gap.{ok|warn|bad})
  //   col 5: Strategy pills
  //   col 6: Hire by
  //   col 7: Status pill (.plan-status-pill.{ok|warn|bad})
  const rows = document.querySelectorAll("#okami-tbody > tr:not(.okami-detail)");
  const weeks = [];
  rows.forEach((row, idx) => {
    const label = (row.querySelector(".plan-week-label")?.textContent || "").trim();
    const dates = (row.querySelector(".plan-week-dates")?.textContent || "").trim();
    const cells = row.querySelectorAll("td");
    const needed = _rrToInt(cells[2]?.querySelector(".plan-calc")?.textContent);
    const avail  = _rrToInt(cells[3]?.querySelector(".plan-calc")?.textContent);
    const gapEl  = cells[4]?.querySelector(".plan-gap");
    const gap    = _rrToInt(gapEl?.textContent);
    const gapKind = gapEl?.classList.contains("bad") ? "bad"
                  : gapEl?.classList.contains("warn") ? "warn"
                  : "ok";
    const statusEl = cells[7]?.querySelector(".plan-status-pill");
    const statusText = (statusEl?.textContent || "").trim();
    const statusKind = statusEl?.classList.contains("bad") ? "risk"
                     : statusEl?.classList.contains("warn") ? "tight"
                     : "ok";
    const hireBy = (cells[6]?.querySelector(".plan-calc")?.textContent || "").trim();
    // Simulation override · if the operator has run the planner
    // simulation, the PTO-adjusted available count for this week
    // replaces OKAMI's static planning seed. Capture the original
    // so the Risk Forecast view can show "planned X · projected Y"
    // when the two differ.
    let simAvail = null, simOnPto = null, simOnTimeOff = null;
    const weekStartIso = _rrOkamiWeekStartIso(idx);
    if (window._rrSimResultsByWeek && weekStartIso) {
      const sim = window._rrSimResultsByWeek[weekStartIso];
      if (sim) {
        simAvail     = sim.available;
        simOnPto     = sim.onPto;
        simOnTimeOff = sim.onTimeOff;
      }
    }
    const effectiveAvail = simAvail != null ? simAvail : avail;
    const effectiveGap   = simAvail != null ? (effectiveAvail - needed) : gap;
    weeks.push({
      idx, label, dates, needed, weekStartIso,
      avail: effectiveAvail,
      gap: effectiveGap,
      gapKind, statusText, statusKind, hireBy,
      plannedAvail: avail,
      simAvail, simOnPto, simOnTimeOff,
      isSimulated: simAvail != null,
    });
  });
  return weeks;
}

function _rrToInt(text) {
  if (text == null) return 0;
  // Handles "−7" (figure dash), "-9", "+10", "85", "—", etc.
  const cleaned = String(text).replace(/[−–—]/g, "-").replace(/[^\d-]/g, "");
  const n = parseInt(cleaned, 10);
  return Number.isFinite(n) ? n : 0;
}

// ── Simulate 13 weeks · per-week PTO-aware headcount projection ───
// Called when the operator clicks "Simulate 13 weeks" on the Targets
// planner card. Hits active_drivers_for_horizon (migration 0329) for
// one round-trip across the visible horizon, caches per-week results
// on window._rrSimResultsByWeek, annotates the OKAMI table in place
// with the projected number, and re-renders the Risk Forecast view
// if it's currently open. Phase 1 is headcount-only — a follow-up PR
// will run the CP-SAT solver per week against this same projected
// pool so we can also catch constraint-level breaks (cert mismatch,
// wave fit, etc.).
async function _rrSimulateNext13Weeks() {
  const btn    = document.getElementById("rr-tgt-sim-btn");
  const status = document.getElementById("rr-tgt-sim-status");
  if (btn && btn.disabled) return;
  const baseIso = window._okamiStart;
  if (!baseIso) {
    if (status) status.textContent = "Load the 13-week plan first";
    return;
  }
  if (btn) {
    btn.disabled = true;
    btn.classList.add("is-loading");
    const lbl = btn.querySelector(":scope > span:not(.sched-v2-intel-tile-status)");
    if (lbl) lbl.dataset.rrOrig = lbl.textContent;
    if (lbl) lbl.textContent = "Running…";
  }
  if (status) status.textContent = "in progress";

  try {
    const { data, error } = await sb.rpc("active_drivers_for_horizon", {
      p_first_week_start: baseIso,
      p_weeks: 13,
    });
    if (error) throw error;
    const rows = Array.isArray(data) ? data : [];
    const cache = {};
    for (const r of rows) {
      cache[r.week_start] = {
        available:   r.available,
        onTimeOff:   r.on_time_off,
        onPto:       r.on_pto,
        totalActive: r.total_active,
      };
    }
    window._rrSimResultsByWeek = cache;
    window._rrSimResultsRanAt  = new Date().toISOString();
    _rrPaintOkamiSimAnnotations();
    // If the Risk Forecast view is open, re-render it so the headline
    // pill, KPIs, strip, and detail card all reflect the projection.
    if (typeof _rrIntelActiveName !== "undefined" && _rrIntelActiveName === "risk-forecast") {
      const view = document.getElementById("rr-intel-view-risk-forecast");
      if (view && typeof _rrIntelRenderRiskForecast === "function") {
        _rrIntelRenderRiskForecast(view);
      }
    }
    if (status) {
      const ranAt = new Date().toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
      status.textContent = `ran ${ranAt}`;
      status.title = `Last simulation: ${ranAt} · PTO + time-off folded in.`;
    }
    if (typeof toast === "function") toast("13-week projection complete", "success");
  } catch (e) {
    console.warn("simulate-13-weeks:", e);
    if (status) status.textContent = "failed";
    if (typeof toast === "function") toast("Simulation failed: " + (e?.message || String(e)), "warn");
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.classList.remove("is-loading");
      const lbl = btn.querySelector(":scope > span:not(.sched-v2-intel-tile-status)");
      if (lbl && lbl.dataset.rrOrig) { lbl.textContent = lbl.dataset.rrOrig; delete lbl.dataset.rrOrig; }
    }
  }
}
window._rrSimulateNext13Weeks = _rrSimulateNext13Weeks;

// Annotate each row's "Available" cell in the OKAMI table with the
// projected available (vs. planned) so the planner table itself
// surfaces the simulation right next to the planning numbers.
// Severity tint matches the Risk Forecast thresholds.
function _rrPaintOkamiSimAnnotations() {
  if (!window._rrSimResultsByWeek) return;
  const rows = document.querySelectorAll("#okami-tbody > tr:not(.okami-detail)");
  rows.forEach((row, idx) => {
    const wkIso = _rrOkamiWeekStartIso(idx);
    if (!wkIso) return;
    const sim = window._rrSimResultsByWeek[wkIso];
    if (!sim) return;
    const cells = row.querySelectorAll("td");
    const availCell = cells[3];
    if (!availCell) return;
    let ann = availCell.querySelector(".okami-sim-avail");
    if (!ann) {
      ann = document.createElement("div");
      ann.className = "okami-sim-avail";
      availCell.appendChild(ann);
    }
    // Tint severity vs. drivers needed for that row.
    const needed = _rrToInt(cells[2]?.querySelector(".plan-calc")?.textContent);
    const cov = needed > 0 ? sim.available / needed : 1;
    ann.classList.toggle("is-warn", cov < 0.95 && cov >= 0.80);
    ann.classList.toggle("is-risk", cov < 0.80);
    const offBits = [];
    if (sim.onPto)     offBits.push(`${sim.onPto} PTO`);
    const unpaid = sim.onTimeOff - sim.onPto;
    if (unpaid > 0)    offBits.push(`${unpaid} off`);
    const offSuffix = offBits.length ? ` · −${offBits.join(", ")}` : "";
    ann.textContent = `Sim ${sim.available}${offSuffix}`;
    ann.title = `PTO-adjusted available: ${sim.available} of ${sim.totalActive} active · ${sim.onTimeOff} on approved time-off (${sim.onPto} PTO)`;
  });
}

// Click handler for the Simulate action tile in the Intelligence
// ribbon. Lives at document level so it survives the ribbon being
// re-rendered or the operator switching tabs. The data-rr-intel-action
// attribute is distinct from data-rr-intel (which opens a view) so
// the main intel click router doesn't try to open a "simulate" view.
document.addEventListener("click", (e) => {
  const action = e.target.closest("[data-rr-intel-action]");
  if (!action) return;
  e.preventDefault();
  e.stopPropagation();
  if (action.dataset.rrIntelAction === "simulate") {
    _rrSimulateNext13Weeks();
  }
});

function _rrIntelRenderRiskForecast(view) {
  const weeks = _rrReadOkamiWeeks();
  if (!weeks.length) {
    view.innerHTML = `
      <header class="rr-intel-view-head">
        <div class="rr-intel-view-head-l">
          <p class="rr-intel-view-eyebrow">Intelligence · Risk forecast</p>
          <h2 class="rr-intel-view-title">Risk forecast</h2>
          <p class="rr-intel-view-sub">Smart Fill projections of coverage across your 13-week plan.</p>
        </div>
        <button type="button" class="rr-intel-view-close" data-rr-intel-close title="Close" aria-label="Close">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </header>
      <div class="rr-intel-empty">No 13-week plan data yet. Visit Schedule → Targets to load it, then come back.</div>`;
    return;
  }

  // Shell = header + the assumptions bar (a live calculator: every input
  // re-runs the pure forecast-core client-side, instantly — no network) +
  // the output host. The output re-renders on each dial change without
  // touching the bar, so typing never loses focus. Rates load lazily and
  // repaint the whole panel when they land; untouched dials reseed to the
  // fresh observed values, edited dials persist via window._rrRfCalc.
  _rrEnsureForecastRates();
  const shellRates = window._rrForecastRates || null;
  const c = window._rrRfCalc || (window._rrRfCalc = {});
  const seedCallout = c.calloutPct ?? Math.round(((shellRates?.calloutRate) || 0) * 100);
  const seedAttr    = c.attrPct    ?? Number((100 * ((shellRates?.weeklyAttritionRate) || 0)).toFixed(1));
  const seedLead    = c.leadDays   ?? RR_OKAMI_HIRE_LEAD_DAYS;
  const seedDpr     = c.dpr        ?? (shellRates?.driversPerRoute ?? 2);
  const seedPad     = c.padPct     ?? Math.max(0, Math.min(50, Number(window.RR?.dsp?.metadata?.staffing?.plan_pad_pct ?? 10) || 0));
  const seedHires   = c.hires      ?? 0;
  const weekIsos = weeks.filter((w) => w.weekStartIso);
  const seedFrom = c.fromIso || (weekIsos[0]?.weekStartIso || "");
  const fromOpts = weekIsos.map((w) =>
    `<option value="${escapeHtml(w.weekStartIso)}"${w.weekStartIso === seedFrom ? " selected" : ""}>${escapeHtml(w.label)}</option>`).join("");

  view.innerHTML = `
    <header class="rr-intel-view-head">
      <div class="rr-intel-view-head-l">
        <p class="rr-intel-view-eyebrow">Intelligence · Risk forecast</p>
        <h2 class="rr-intel-view-title">
          Risk forecast
          <span class="rr-intel-headline-pill ok" id="rr-rf-pill" hidden><span class="dot"></span></span>
        </h2>
        <p class="rr-intel-view-sub">${window._rrSimResultsByWeek
          ? "Reading from your last <strong>Simulate 13 weeks</strong> run."
          : "Effective-supply projections across your 13-week plan."}</p>
      </div>
      <button type="button" class="rr-intel-view-close" data-rr-intel-close title="Close" aria-label="Close">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </header>

    <div class="rr-intel-calcrow">
      <button type="button" class="rr-intel-calc-toggle${window._rrRfCalcOpen ? " is-open" : ""}" id="rr-rf-calc-toggle" aria-expanded="${window._rrRfCalcOpen ? "true" : "false"}" aria-controls="rr-rf-calc" title="Adjust the forecast's assumptions — sandbox only, your plan is not changed">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="4" y1="8" x2="20" y2="8"/><circle cx="9" cy="8" r="2.2"/><line x1="4" y1="16" x2="20" y2="16"/><circle cx="15" cy="16" r="2.2"/></svg>
        Assumptions
        <svg class="rr-intel-calc-caret" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="2 4 6 8 10 4"/></svg>
      </button>
      <span class="rr-intel-flexplan-hint" id="rr-rf-calc-note"></span>
    </div>
    <form class="rr-intel-whatif-form rr-intel-calcbar" id="rr-rf-calc"${window._rrRfCalcOpen ? "" : " hidden"} title="Every field recalculates the forecast instantly. Sandbox only — your plan is not changed.">
      <label class="rr-intel-whatif-field"><span>Callout %</span><input type="number" id="rr-rf-callout" min="0" max="50" step="1" value="${seedCallout}"></label>
      <label class="rr-intel-whatif-field"><span>Attrition %/wk</span><input type="number" id="rr-rf-attr" min="0" max="10" step="0.1" value="${seedAttr}"></label>
      <label class="rr-intel-whatif-field"><span>Hire lead · days</span><input type="number" id="rr-rf-lead" min="7" max="90" step="1" value="${seedLead}"></label>
      <label class="rr-intel-whatif-field"><span>Drivers/route</span><input type="number" id="rr-rf-dpr" min="1" max="5" step="0.1" value="${seedDpr}"></label>
      <label class="rr-intel-whatif-field"><span>Pad %</span><input type="number" id="rr-rf-pad" min="0" max="50" step="1" value="${seedPad}"></label>
      <label class="rr-intel-whatif-field"><span>+ Hires</span><input type="number" id="rr-rf-hires" min="0" max="200" step="1" value="${seedHires}"></label>
      <label class="rr-intel-whatif-field"><span>Arriving</span><select id="rr-rf-from">${fromOpts}</select></label>
      <button type="button" class="rr-intel-whatif-run" id="rr-rf-reset" hidden>Reset to observed</button>
    </form>
    <div id="rr-intel-rf-out"></div>`;

  // The bar stays collapsed until asked for — the forecast reads as a calm
  // report first, calculator second. Open state persists for the session.
  const calcToggle = view.querySelector("#rr-rf-calc-toggle");
  if (calcToggle) calcToggle.addEventListener("click", () => {
    const form = view.querySelector("#rr-rf-calc");
    if (!form) return;
    window._rrRfCalcOpen = form.hidden;
    form.hidden = !form.hidden;
    calcToggle.setAttribute("aria-expanded", String(!form.hidden));
    calcToggle.classList.toggle("is-open", !form.hidden);
  });

  const bar = view.querySelector("#rr-rf-calc");
  let barDebounce = null;
  // Only the dial the operator actually edited becomes an override —
  // untouched dials keep tracking the observed rates (storing the whole
  // bar would freeze pre-load fallbacks and rounded display seeds as
  // unintended overrides). Clearing a field hands it back to observed.
  const RR_RF_FIELDS = {
    "rr-rf-callout": ["calloutPct", 0, 50],
    "rr-rf-attr":    ["attrPct", 0, 10],
    "rr-rf-lead":    ["leadDays", 7, 90],
    "rr-rf-dpr":     ["dpr", 1, 5],
    "rr-rf-pad":     ["padPct", 0, 50],
    "rr-rf-hires":   ["hires", 0, 200],
    "rr-rf-from":    ["fromIso"],
  };
  if (bar) {
    bar.addEventListener("input", (e) => {
      const spec = RR_RF_FIELDS[e.target?.id];
      if (!spec) return;
      const st = window._rrRfCalc || (window._rrRfCalc = {});
      if (spec[0] === "fromIso") {
        st.fromIso = e.target.value || "";
      } else if (String(e.target.value).trim() === "") {
        delete st[spec[0]]; // cleared → back to observed
      } else {
        const v = Number(e.target.value);
        if (Number.isFinite(v)) st[spec[0]] = Math.max(spec[1], Math.min(spec[2], v));
      }
      // "+ Hires" needs an arrival week even if the select was never
      // touched — capture its current value once.
      if (spec[0] === "hires" && st.hires > 0 && !st.fromIso) {
        st.fromIso = view.querySelector("#rr-rf-from")?.value || "";
      }
      clearTimeout(barDebounce);
      barDebounce = setTimeout(() => _rrRenderRiskForecastOut(view, weeks), 120);
    });
    bar.addEventListener("submit", (e) => e.preventDefault());
  }
  const resetBtn = view.querySelector("#rr-rf-reset");
  if (resetBtn) resetBtn.addEventListener("click", () => {
    window._rrRfCalc = {};
    _rrIntelRenderRiskForecast(view); // full re-render reseeds the bar
  });

  _rrRenderRiskForecastOut(view, weeks);
}

// The recomputable body: KPIs, strip, narrative, detail card, coverage
// plan, upper funnel, footer. Pure forecast-core math over the plan weeks
// plus whatever the assumptions bar overrides — cheap enough to run on
// every keystroke.
function _rrRenderRiskForecastOut(view, weeks) {
  const out = view.querySelector("#rr-intel-rf-out");
  if (!out) return;
  const rates = window._rrForecastRates || null;
  const overrides = _rrRfOverrides();
  const activeCalloutPct = Math.round((Number.isFinite(overrides.calloutRate) ? overrides.calloutRate : (rates?.calloutRate || 0)) * 100);
  const activeLeadDays = Number.isFinite(overrides.hireLeadDays) ? overrides.hireLeadDays : RR_OKAMI_HIRE_LEAD_DAYS;
  const A  = _rrAssessOkamiPlan(weeks, overrides);
  const aw = A.weeks;
  const thisWeek = aw[0];
  const coveragePct = Math.min(100, thisWeek.coveragePct);
  const trendLabel  = A.trend === "improving" ? "Improving"
                    : A.trend === "declining" ? "Declining" : "Steady";
  const trendDetail = A.trend === "improving" ? "Coverage strengthens over the next 4 weeks"
                    : A.trend === "declining" ? "Coverage erodes over the next 4 weeks"
                    : "Coverage holds across the next 4 weeks";
  const nextBreak    = A.firstBreak;
  const overallKind  = A.headline;               // ok | watch | risk
  const overallLabel = RR_FC_LABEL[overallKind];
  const overallClass = RR_FC_CLASS[overallKind]; // legacy css class names
  const fmtIsoShort  = (iso) => (iso ? fmtMD(new Date(iso + "T12:00:00")) : "");

  // Narrative · plain, calm sentences. No alarm color in the prose;
  // status carries that signal via the pill + bars. Shows its work on
  // effective supply, and never presents a past hire-by as actionable.
  const rx = A.prescription;
  let narrative;
  if (!nextBreak) {
    narrative = `Coverage holds across your full 13-week horizon. The 4-week look-ahead shows
      <strong>${A.horizon.effAvail.toLocaleString()}</strong> effective drivers against
      <strong>${A.horizon.needed.toLocaleString()}</strong> needed — every week sits at or above 95% cushion.
      Hire-by dates from the planner stay quiet through this window.`;
  } else {
    const breakKind = nextBreak.kind === "risk" ? "critical" : "watch";
    const breakShort = Math.max(0, nextBreak.needed - nextBreak.effAvail);
    const idx = nextBreak.idx;
    const lead = idx === 0 ? "this week" : `in ${idx} week${idx === 1 ? "" : "s"}`;
    const s = nextBreak.supply;
    const supplyBits = [];
    if (s.notReadyOnboarding) supplyBits.push(`${s.notReadyOnboarding} onboarding not yet road-ready`);
    if (s.attritionLoss)      supplyBits.push(`${s.attritionLoss} projected attrition`);
    if (s.calloutLoss)        supplyBits.push(`${s.calloutLoss} expected callout${s.calloutLoss === 1 ? "" : "s"} at ${activeCalloutPct}%`);
    const hiresTxt = s.extraHires ? ` plus ${s.extraHires} sandbox hire${s.extraHires === 1 ? "" : "s"}` : "";
    const supplyTxt = supplyBits.length || s.extraHires
      ? ` Effective supply starts from ${s.rawAvail.toLocaleString()} on payroll${supplyBits.length ? " minus " + supplyBits.join(", ") : ""}${hiresTxt}.`
      : "";
    let actionTxt = "";
    if (rx.action === "hire") {
      actionTxt = `Hiring <strong>${rx.hires}</strong> by <strong>${fmtIsoShort(rx.deadlineIso)}</strong> closes every week hiring can still reach.`;
      if (rx.unreachable.length) {
        const names = rx.unreachable.map((u) => escapeHtml(u.label)).join(", ");
        actionTxt += ` <strong>${names}</strong> ${rx.unreachable.length === 1 ? "is" : "are"} already inside the
          ${activeLeadDays}-day hire window — cover ${rx.unreachable.length === 1 ? "it" : "them"} with OT,
          voluntary 5th days, or flex instead.`;
      }
    } else if (rx.action === "mitigate") {
      actionTxt = `The hire window for every short week has passed — a hire started today is road-ready
        around <strong>${fmtIsoShort(rx.readyByIso)}</strong>. Cover the gap with OT, voluntary 5th days,
        or flex, and hire now to protect the weeks after that.`;
    }
    narrative = `Your next ${breakKind} window is <strong>${escapeHtml(nextBreak.label)}</strong>
      (${escapeHtml(nextBreak.dates)}) — ${lead}. The forecast sees
      <strong>${nextBreak.needed.toLocaleString()}</strong> drivers needed against
      <strong>${nextBreak.effAvail.toLocaleString()}</strong> effective, leaving
      <strong>${breakShort.toLocaleString()}</strong> open.${supplyTxt} ${actionTxt}`;
  }

  // 13-week strip · one bar per week. Height encodes drivers needed
  // (relative to the peak); the solid cap on top is the UNCOVERED slice,
  // so a big-but-covered week no longer looks scarier than a small-but-
  // short one. Color encodes the shared coverage vocabulary.
  const maxNeeded = Math.max(1, ...aw.map((w) => w.needed));
  const stripHtml = aw.map((w) => {
    const heightPx = 10 + Math.round((w.needed / maxNeeded) * 30); // 10–40px
    const shortPx = w.gap < 0 && w.needed > 0
      ? Math.max(2, Math.round(heightPx * Math.min(1, -w.gap / w.needed)))
      : 0;
    const isCurrent = w.idx === 0;
    const titleAttr = `${w.label} · ${w.dates} · ${w.needed} needed / ${w.effAvail} effective · ${w.coveragePct}% coverage`
      + (w.gap < 0 ? ` · ${-w.gap} open` : "");
    return `<div class="rr-intel-strip-bar${isCurrent ? " is-current" : ""}" title="${escapeHtml(titleAttr)}">
      <div class="rr-intel-strip-fill ${RR_FC_CLASS[w.kind]}" style="height:${heightPx}px">${
        shortPx ? `<div class="rr-intel-strip-short" style="height:${shortPx}px"></div>` : ""}</div>
      <div class="rr-intel-strip-label">${escapeHtml(w.label)}</div>
    </div>`;
  }).join("");

  // Detail fact card · shows the effective-supply work line by line so
  // the number is auditable, and never shows a past hire-by date as if
  // it were still an action.
  const supplyFacts = (w) => {
    const s = w.supply;
    const rows = [`<div class="rr-intel-detail-fact"><span>On payroll</span><span>${s.rawAvail.toLocaleString()}</span></div>`];
    if (s.notReadyOnboarding) rows.push(`<div class="rr-intel-detail-fact"><span>− Onboarding not ready</span><span>${s.notReadyOnboarding}</span></div>`);
    if (s.attritionLoss)      rows.push(`<div class="rr-intel-detail-fact"><span>− Projected attrition</span><span>${s.attritionLoss}</span></div>`);
    if (s.extraHires)         rows.push(`<div class="rr-intel-detail-fact"><span>+ Sandbox hires</span><span>${s.extraHires}</span></div>`);
    if (s.calloutLoss)        rows.push(`<div class="rr-intel-detail-fact"><span>− Expected callouts</span><span>${s.calloutLoss}</span></div>`);
    rows.push(`<div class="rr-intel-detail-fact"><span>Effective</span><span>${w.effAvail.toLocaleString()}</span></div>`);
    return rows.join("");
  };
  const hireByFact = (w) => {
    if (w.gap >= 0 || !w.hireByIso) return "";
    return w.hireByStatus === "past"
      ? `<div class="rr-intel-detail-fact"><span>Hire by</span><span class="is-past-due">${escapeHtml(fmtIsoShort(w.hireByIso))} · window passed</span></div>`
      : `<div class="rr-intel-detail-fact"><span>Hire by</span><span>${escapeHtml(fmtIsoShort(w.hireByIso))}</span></div>`;
  };
  // One three-column band — narrative · facts · coverage plan — so the
  // whole panel fits a single viewport (operator: "I don't want to
  // scroll"). The facts card compacts to a first-break week: fewer
  // redundant rows; Week/Dates/Coverage already live in the KPI strip
  // and the narrative.
  const factsHtml = nextBreak ? `
      <aside class="rr-intel-detail-facts">
        <div class="rr-intel-detail-fact"><span>Needed</span><span>${nextBreak.needed.toLocaleString()}</span></div>
        ${supplyFacts(nextBreak)}
        <div class="rr-intel-detail-fact"><span>Open</span><span>${Math.max(0, -nextBreak.gap).toLocaleString()}</span></div>
        ${hireByFact(nextBreak)}
      </aside>` : `
      <aside class="rr-intel-detail-facts">
        <div class="rr-intel-detail-fact"><span>Needed</span><span>${thisWeek.needed.toLocaleString()}</span></div>
        ${supplyFacts(thisWeek)}
        <div class="rr-intel-detail-fact"><span>Coverage</span><span>${coveragePct}%</span></div>
      </aside>`;
  const detailHtml = `
    <div class="rr-intel-grid3">
      <div class="rr-intel-detail-narrative">${narrative}</div>
      ${factsHtml}
      ${nextBreak && nextBreak.weekStartIso ? `
      <div class="rr-intel-flexmini" id="rr-intel-flex-plan" data-week="${escapeHtml(nextBreak.weekStartIso)}">
        <div class="rr-intel-flexmini-head"><span>Coverage plan · ${escapeHtml(nextBreak.label)}</span></div>
        <div class="rr-intel-flexmini-hint">Computing from live availability…</div>
      </div>` : ""}
    </div>`;

  // Headline pill lives in the shell header — update it in place.
  const pill = view.querySelector("#rr-rf-pill");
  if (pill) {
    pill.hidden = false;
    pill.className = "rr-intel-headline-pill " + overallClass;
    pill.innerHTML = `<span class="dot"></span>${overallLabel}`;
  }
  // Sandbox note — deltas vs the observed baseline, shown while any dial
  // is set (visible even with the bar collapsed, so edits are never
  // silent). Reset only appears when there is something to reset.
  const note = view.querySelector("#rr-rf-calc-note");
  const resetEl = view.querySelector("#rr-rf-reset");
  const hasOverrides = Object.keys(overrides).length > 0;
  if (resetEl) resetEl.hidden = !hasOverrides;
  if (note) {
    if (hasOverrides) {
      const B = _rrAssessOkamiPlan(weeks);
      const shortN = (X) => X.weeks.filter((w) => w.gap < 0).length;
      note.textContent = (B.worstWeek?.gap !== A.worstWeek?.gap || shortN(B) !== shortN(A))
        ? `Sandbox · worst week ${B.worstWeek ? B.worstWeek.gap : 0} → ${A.worstWeek ? A.worstWeek.gap : 0} · short weeks ${shortN(B)} → ${shortN(A)} · plan unchanged`
        : "Sandbox · matches observed · plan unchanged";
    } else {
      note.textContent = "";
    }
  }

  out.classList.add("rr-intel-dense");
  out.innerHTML = `
    <div class="rr-intel-kpis">
      <div class="rr-intel-kpi">
        <div class="rr-intel-kpi-label">Coverage · this week</div>
        <div class="rr-intel-kpi-val ${coveragePct < 90 ? "is-warn" : ""}">${coveragePct}<span style="font-size:13px;font-weight:500;color:var(--text-subtle)">%</span></div>
        <div class="rr-intel-kpi-sub">${thisWeek.effAvail.toLocaleString()} of ${thisWeek.needed.toLocaleString()} effective drivers</div>
      </div>
      <div class="rr-intel-kpi">
        <div class="rr-intel-kpi-label">4-week trend</div>
        <div class="rr-intel-kpi-val">${trendLabel}</div>
        <div class="rr-intel-kpi-sub">${trendDetail}</div>
      </div>
      <div class="rr-intel-kpi">
        <div class="rr-intel-kpi-label">Short over 4 weeks</div>
        <div class="rr-intel-kpi-val ${A.horizon.driverWeeksShort > 0 ? "is-warn" : ""}">${A.horizon.driverWeeksShort.toLocaleString()}</div>
        <div class="rr-intel-kpi-sub" title="Weekly gaps summed — a workload unit, not people to hire">Driver-weeks — not hires</div>
      </div>
      <div class="rr-intel-kpi">
        <div class="rr-intel-kpi-label">Next break</div>
        <div class="rr-intel-kpi-val ${overallKind === "risk" ? "is-risk" : (overallKind === "watch" ? "is-warn" : "")}">${nextBreak ? escapeHtml(nextBreak.label) : "None"}</div>
        <div class="rr-intel-kpi-sub">${nextBreak ? escapeHtml(nextBreak.dates) + " · " + (nextBreak.idx === 0 ? "this week" : "in " + nextBreak.idx + " wk" + (nextBreak.idx === 1 ? "" : "s")) : "Clear horizon"}</div>
      </div>
    </div>

    <div class="rr-intel-strip-section">
      <div class="rr-intel-section-head">
        <h3 class="rr-intel-section-title">13-week risk strip</h3>
        <span class="rr-intel-section-aside">height = needed · cap = uncovered</span>
      </div>
      <div class="rr-intel-strip" role="list" aria-label="13-week risk bars">${stripHtml}</div>
    </div>

    ${detailHtml}

    <div id="rr-intel-upper-funnel"></div>

    <footer class="rr-intel-foot rr-intel-foot--one">
      <span class="rr-intel-foot-bullet"><span class="dot"></span>${window._rrSimResultsByWeek
        ? "Simulation ran " + (window._rrSimResultsRanAt ? new Date(window._rrSimResultsRanAt).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : "just now") + " — PTO folded in"
        : "Live 13-week plan — Simulate 13 weeks folds in PTO"}${rates
        ? ` · observed: ${Math.round((rates.calloutRate || 0) * 100)}% callouts · ${(100 * (rates.weeklyAttritionRate || 0)).toFixed(1)}%/wk attrition · ${(rates.onboarding || []).length} onboarding gated`
        : " · loading observed rates…"}</span>
    </footer>
  `;

  // Tier-aware coverage plan for the break week — fills in asynchronously
  // from the flex-capacity engine; the placeholder disappears quietly if
  // the engine isn't reachable.
  if (nextBreak && nextBreak.weekStartIso) {
    _rrFillFlexPlan(nextBreak.weekStartIso, nextBreak.label);
  }

  // Upper funnel · backward-solve the next break into a sourcing quota.
  // Async (one cached RPC) so the core forecast still paints instantly.
  // Assessed weeks carry the forecast-core shape: gap = effAvail − needed.
  if (nextBreak && nextBreak.gap < 0) {
    const ufHost = view.querySelector("#rr-intel-upper-funnel");
    if (ufHost) {
      ufHost.innerHTML = `<div class="rr-intel-empty">Sizing your hiring funnel…</div>`;
      _rrFetchHiringPlanning().then((plan) => {
        if (!view.isConnected) return;
        const host = view.querySelector("#rr-intel-upper-funnel");
        if (host) host.innerHTML = _rrUpperFunnelSectionHtml(_rrUpperFunnelMath(plan), nextBreak);
      });
    }
  }
}

// ── Upper funnel · backward-solve the hiring funnel ────────────────
// The Amazon "upper funnel" discipline: routes → drivers needed (2:1
// + cushion, already in the 13-week plan) → gap → ÷ conversion rate →
// applicants needed at the top of the funnel, due by (hire-by − funnel
// velocity). Powered by hiring_pipeline_planning (migration 0458),
// which returns the DSP's own measured stage→hire rates, median
// applied→hired days, application pace, and the live in-funnel counts.

// Industry-default P(hire | currently at stage), used verbatim until the
// DSP has RR_UF_MIN_HIRES hires of history in the lookback window. The
// UI always labels which basis is in effect.
const RR_UF_DEFAULT_STAGE_RATES = { 1: 8, 2: 12, 3: 20, 4: 30, 5: 35, 6: 45, 7: 85 };
const RR_UF_DEFAULT_FUNNEL_DAYS = 21;   // applied → hired, when unmeasured
const RR_UF_MIN_HIRES = 5;              // measured rates need ≥ this many hires
const RR_UF_WINDOW_DAYS = 180;

let _rrHiringPlanCache = null;          // { at: ms, data: payload|null }
let _rrHiringPlanPromise = null;

function _rrFetchHiringPlanning() {
  const FRESH_MS = 5 * 60 * 1000;
  if (_rrHiringPlanCache && Date.now() - _rrHiringPlanCache.at < FRESH_MS) {
    return Promise.resolve(_rrHiringPlanCache.data);
  }
  if (_rrHiringPlanPromise) return _rrHiringPlanPromise;
  _rrHiringPlanPromise = sb.rpc("hiring_pipeline_planning", { p_window_days: RR_UF_WINDOW_DAYS })
    .then(({ data, error }) => {
      if (error) throw error;
      // Guard: a not-yet-migrated backend (or a stub) can hand back an
      // array / null — treat anything but a plain object as "no data"
      // and fall through to the labeled industry defaults.
      const obj = data && typeof data === "object" && !Array.isArray(data) ? data : null;
      _rrHiringPlanCache = { at: Date.now(), data: obj };
      return obj;
    })
    .catch((e) => {
      console.warn("hiring_pipeline_planning:", e);
      _rrHiringPlanCache = { at: Date.now(), data: null };
      return null;
    })
    .finally(() => { _rrHiringPlanPromise = null; });
  return _rrHiringPlanPromise;
}

// Fold the RPC payload into the numbers backward-planning needs. Works
// with plan = null (cold start / RPC unavailable): defaults everywhere,
// zero live pipeline, and measured=false so every surface says so.
function _rrUpperFunnelMath(plan) {
  const stages = Array.isArray(plan?.stages) ? plan.stages : [];
  const hired = Number(plan?.hired || 0);
  const byRank = {};
  for (const s of stages) byRank[Number(s.rank)] = s;
  const reachedTop = Number(byRank[1]?.reached || 0);
  const measured = hired >= RR_UF_MIN_HIRES && reachedTop > 0;

  let inFunnelTotal = 0;
  let expectedHires = 0;
  const rows = [];
  for (let r = 1; r <= 7; r++) {
    const s = byRank[r] || {};
    const inF = Number(s.in_funnel || 0);
    const reached = Number(s.reached || 0);
    const hiredFrom = Number(s.hired_from || 0);
    const ratePct = measured && reached > 0
      ? (100 * hiredFrom) / reached
      : RR_UF_DEFAULT_STAGE_RATES[r];
    inFunnelTotal += inF;
    expectedHires += (inF * ratePct) / 100;
    rows.push({ rank: r, key: s.key || String(r), label: s.label || "", inFunnel: inF, ratePct });
  }

  const e2ePct = measured
    ? Math.max(0.5, (100 * Number(byRank[1]?.hired_from || 0)) / reachedTop)
    : RR_UF_DEFAULT_STAGE_RATES[1];
  const medianTTH = Number(plan?.median_days_to_hire);
  const funnelDays = measured && Number.isFinite(medianTTH) && medianTTH > 0
    ? Math.round(medianTTH)
    : RR_UF_DEFAULT_FUNNEL_DAYS;

  return {
    measured, hired,
    windowDays: Number(plan?.window_days || RR_UF_WINDOW_DAYS),
    applied: Number(plan?.applied || 0),
    appsPerWeek: Number(plan?.apps_per_week || 0),
    e2ePct, funnelDays,
    inFunnelTotal,
    expectedHires,
    stages: rows,
  };
}

// Applications needed at the top of the funnel to yield `gap` hires.
function _rrUfAppsNeeded(gap, e2ePct) {
  if (!(gap > 0)) return 0;
  return Math.ceil(gap / (Math.max(0.5, e2ePct) / 100));
}

// "Get them into the funnel by" — the week's hire-by (which already
// backs out the 28-day onboarding/training lead) minus the funnel's own
// applied→hired velocity. Returns { date, label, overdue }.
function _rrUfEntryDeadline(weekIdx, funnelDays) {
  const iso = _rrOkamiWeekStartIso(weekIdx);
  if (!iso) return null;
  const d = addDays(new Date(iso + "T12:00:00"), -(RR_OKAMI_HIRE_LEAD_DAYS + funnelDays));
  return { date: d, label: fmtMD(d), overdue: d < new Date() };
}

// One-line description of the basis behind the math, shown under every
// upper-funnel surface so the numbers are never mystery meat.
function _rrUfBasisNote(m) {
  if (m.measured) {
    return `Using your measured rates — ${m.hired} hire${m.hired === 1 ? "" : "s"} from `
      + `${m.applied.toLocaleString()} applications over the last ${Math.round(m.windowDays / 7)} weeks `
      + `(${m.e2ePct.toFixed(m.e2ePct < 10 ? 1 : 0)}% application→hire, ~${m.funnelDays} days applied→hired).`;
  }
  return `Using industry defaults (${RR_UF_DEFAULT_STAGE_RATES[1]}% application→hire, `
    + `~${RR_UF_DEFAULT_FUNNEL_DAYS} days in funnel) until you have ${RR_UF_MIN_HIRES}+ hires of history — `
    + `your own rates take over automatically as the funnel fills.`;
}

// Upper-funnel section for the Risk forecast: the backward-solve for the
// next break week. gap → live pipeline yield → unsourced gap → apps
// needed → funnel-entry deadline.
function _rrUpperFunnelSectionHtml(m, nextBreak) {
  // Accepts a forecast-core assessed week (gap = effAvail − needed).
  const gap = Math.max(0, -(Number(nextBreak.gap) || 0));
  if (gap <= 0) return "";
  const unsourced = Math.max(0, Math.ceil(gap - m.expectedHires));
  const apps = _rrUfAppsNeeded(unsourced, m.e2ePct);
  const dl = _rrUfEntryDeadline(nextBreak.idx, m.funnelDays);
  const weeksOfPace = m.appsPerWeek > 0 ? Math.ceil(apps / m.appsPerWeek) : null;
  // Single stat line so the risk panel fits one viewport; the full
  // basis sentence lives in the tooltip, the ladder in Hiring pulse.
  const basisTip = _rrUfBasisNote(m)
    + (weeksOfPace && unsourced > 0
      ? ` At your current pace of ${m.appsPerWeek}/week, that's ~${weeksOfPace} week${weeksOfPace === 1 ? "" : "s"} of applications.`
      : "");
  return `
    <div class="rr-intel-ufsec" title="${escapeHtml(basisTip)}">
      <div class="rr-intel-section-head">
        <h3 class="rr-intel-section-title">Upper funnel · ${escapeHtml(nextBreak.label)}</h3>
        <span class="rr-intel-section-aside">${m.measured
          ? `Your measured rates · ${m.e2ePct.toFixed(m.e2ePct < 10 ? 1 : 0)}% app→hire · ~${m.funnelDays}d in funnel`
          : "Industry defaults until 5+ hires of history"}</span>
      </div>
      <div class="rr-intel-ufline">
        <span><em>Open</em><strong class="is-risk">${gap.toLocaleString()}</strong></span>
        <span><em>In funnel</em><strong>${m.inFunnelTotal.toLocaleString()}</strong> ≈ ${m.expectedHires.toFixed(1)} hires</span>
        <span><em>Apps needed</em><strong${unsourced > 0 ? ' class="is-warn"' : ""}>${unsourced > 0 ? "≈ " + apps.toLocaleString() : "0"}</strong>${unsourced > 0 ? ` for the last ${unsourced.toLocaleString()}` : " — pipeline covers it"}</span>
        <span><em>In funnel by</em><strong${dl?.overdue ? ' class="is-risk"' : ""}>${dl ? escapeHtml(dl.label) : "—"}</strong>${dl?.overdue ? " — source now" : ""}</span>
      </div>
    </div>`;
}

// ── Hiring pulse · the always-on upper-funnel view ─────────────────
// Left-to-right: funnel health KPIs, the live stage ladder, then every
// short week in the 13-week plan solved back to an application quota.
function _rrIntelRenderHiringPulse(view) {
  view.innerHTML = `
    <header class="rr-intel-view-head">
      <div class="rr-intel-view-head-l">
        <p class="rr-intel-view-eyebrow">Intelligence · Hiring pulse</p>
        <h2 class="rr-intel-view-title">Hiring pulse</h2>
        <p class="rr-intel-view-sub">Your hiring funnel, solved against the 13-week plan — how many applicants you need at the top, and by when.</p>
      </div>
      <button type="button" class="rr-intel-view-close" data-rr-intel-close title="Close" aria-label="Close">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </header>
    <div class="rr-intel-empty" id="rr-hp-loading">Reading your funnel…</div>
    <div id="rr-hp-body"></div>`;

  _rrFetchHiringPlanning().then((plan) => {
    if (!view.isConnected) return;
    const loading = view.querySelector("#rr-hp-loading");
    const body = view.querySelector("#rr-hp-body");
    if (loading) loading.remove();
    if (!body) return;
    const m = _rrUpperFunnelMath(plan);

    // Live stage ladder — count in funnel × P(hire | stage).
    const ladderHtml = m.stages.map((s) => `
      <div class="rr-intel-detail-fact">
        <span>${escapeHtml(s.label)}</span>
        <span>${s.inFunnel.toLocaleString()} <span style="color:var(--text-subtle);font-weight:500">· ${s.ratePct.toFixed(s.ratePct < 10 ? 1 : 0)}% hire</span></span>
      </div>`).join("");

    // Per-short-week backward solve. Each week is solved independently —
    // the live pipeline's expected yield applies to every week (a hire
    // made for W28 is still on the roster in W29). Gaps come from the
    // shared forecast-core assessment (effective supply, same numbers
    // the Risk forecast and gap card show); raw plan rows are the
    // fallback if the assessment can't run.
    let weeks = [];
    try {
      const raw = (_rrReadOkamiWeeks() || []).filter((w) => Number.isFinite(w.gap));
      try {
        _rrEnsureForecastRates();
        weeks = (_rrAssessOkamiPlan(raw)?.weeks || []).filter((w) => Number.isFinite(w.gap));
      } catch (_) { weeks = raw; }
    } catch (_) {}
    const shortWeeks = weeks.filter((w) => w.gap < 0);
    let weeksHtml;
    if (!weeks.length) {
      weeksHtml = `<div class="rr-intel-empty">No 13-week plan data yet. Visit Schedule → Targets to load it, then come back.</div>`;
    } else if (!shortWeeks.length) {
      weeksHtml = `<div class="rr-intel-empty">Fully staffed through the plan — and your funnel adds ≈ ${m.expectedHires.toFixed(1)} expected hires of cushion on top.</div>`;
    } else {
      const rows = shortWeeks.map((w) => {
        const gap = Math.abs(w.gap);
        const unsourced = Math.max(0, Math.ceil(gap - m.expectedHires));
        const apps = _rrUfAppsNeeded(unsourced, m.e2ePct);
        const dl = _rrUfEntryDeadline(w.idx, m.funnelDays);
        return `
          <div style="display:grid;grid-template-columns:minmax(120px,1.4fr) repeat(4,minmax(90px,1fr));gap:8px;padding:9px 4px;border-top:1px solid var(--rr-ctl-border,rgba(15,23,42,.08));align-items:baseline">
            <span><strong>${escapeHtml(w.label)}</strong> <span style="color:var(--text-subtle)">${escapeHtml(w.dates)}</span></span>
            <span class="rr-intel-kpi-val is-risk" style="font-size:inherit">${gap.toLocaleString()} open</span>
            <span>${unsourced > 0 ? `${unsourced.toLocaleString()} unsourced` : "pipeline covers it"}</span>
            <span>${unsourced > 0 ? `≈ ${apps.toLocaleString()} apps` : "—"}</span>
            <span class="${dl?.overdue ? "rr-intel-kpi-val is-risk" : ""}" style="font-size:inherit">${dl ? "by " + escapeHtml(dl.label) : "—"}</span>
          </div>`;
      }).join("");
      weeksHtml = `
        <div class="rr-intel-strip-section">
          <div class="rr-intel-section-head">
            <h3 class="rr-intel-section-title">Short weeks · sourcing quotas</h3>
            <span class="rr-intel-section-aside">Week · open · after pipeline · applications · in funnel by</span>
          </div>
          ${rows}
        </div>`;
    }

    body.innerHTML = `
      <div class="rr-intel-kpis">
        <div class="rr-intel-kpi">
          <div class="rr-intel-kpi-label">In funnel now</div>
          <div class="rr-intel-kpi-val">${m.inFunnelTotal.toLocaleString()}</div>
          <div class="rr-intel-kpi-sub">Active applicants, all stages</div>
        </div>
        <div class="rr-intel-kpi">
          <div class="rr-intel-kpi-label">Expected hires</div>
          <div class="rr-intel-kpi-val">${m.expectedHires.toFixed(1)}</div>
          <div class="rr-intel-kpi-sub">Pipeline × ${m.measured ? "your" : "default"} stage rates</div>
        </div>
        <div class="rr-intel-kpi">
          <div class="rr-intel-kpi-label">Application→hire</div>
          <div class="rr-intel-kpi-val">${m.e2ePct.toFixed(m.e2ePct < 10 ? 1 : 0)}%</div>
          <div class="rr-intel-kpi-sub">${m.measured ? `Measured · ${m.hired} hires / ${Math.round(m.windowDays / 7)} wks` : "Industry default"}</div>
        </div>
        <div class="rr-intel-kpi">
          <div class="rr-intel-kpi-label">Funnel velocity</div>
          <div class="rr-intel-kpi-val">${m.funnelDays}<span style="font-size:13px;font-weight:500;color:var(--text-subtle)"> days</span></div>
          <div class="rr-intel-kpi-sub">${m.measured ? "Median applied→hired" : "Default applied→hired"}</div>
        </div>
        <div class="rr-intel-kpi">
          <div class="rr-intel-kpi-label">Application pace</div>
          <div class="rr-intel-kpi-val">${m.appsPerWeek || "—"}</div>
          <div class="rr-intel-kpi-sub">Per week, recent window</div>
        </div>
      </div>
      <div class="rr-intel-detail">
        <div class="rr-intel-detail-narrative">
          Your funnel holds <strong>${m.inFunnelTotal.toLocaleString()}</strong> active applicant${m.inFunnelTotal === 1 ? "" : "s"},
          worth about <strong>${m.expectedHires.toFixed(1)}</strong> hires at ${m.measured ? "your measured" : "default"} stage rates.
          Every short week below is solved back to an application quota: open drivers, minus what the pipeline
          should yield, divided by your ${m.e2ePct.toFixed(m.e2ePct < 10 ? 1 : 0)}% application→hire rate — due in the funnel
          <em>hire-by minus ~${m.funnelDays} days</em> so training still lands before the week breaks.
        </div>
        <aside class="rr-intel-detail-facts">${ladderHtml}</aside>
      </div>
      ${weeksHtml}
      <footer class="rr-intel-foot">
        <span class="rr-intel-foot-bullet"><span class="dot"></span>${escapeHtml(_rrUfBasisNote(m))}</span>
        <span>Source more applicants from Onboarding → Funnel.</span>
      </footer>`;
  });
}

// ── What-if · stress-test a week against the flex-capacity engine ─────────
// The operator picks a week and turns four dials (extra routes/day, demand
// multiplier, callouts, attrition); the edge function materializes the
// counts against the live roster (deterministic — most-scheduled drivers
// first) and scores the scenario at the three capacity tiers.
function _rrIntelRenderWhatIf(view) {
  const weeks = _rrReadOkamiWeeks();
  const head = `
    <header class="rr-intel-view-head">
      <div class="rr-intel-view-head-l">
        <p class="rr-intel-view-eyebrow">Intelligence · What-if</p>
        <h2 class="rr-intel-view-title">What-if</h2>
        <p class="rr-intel-view-sub">Stress-test a week before it happens: pile on routes, a Prime-Week multiplier,
          callouts, or attrition, and the flex engine answers with tier headroom and a hiring plan —
          from live availability, preferred days, 5th-day opt-ins, certs, PTO and scheduled shifts.</p>
      </div>
      <button type="button" class="rr-intel-view-close" data-rr-intel-close title="Close" aria-label="Close">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </header>`;
  if (!weeks.length) {
    view.innerHTML = head + `<div class="rr-intel-empty">No 13-week plan data yet. Visit Schedule → Targets to load it, then come back.</div>`;
    return;
  }
  let A = null;
  try { A = _rrAssessOkamiPlan(weeks); } catch (_) {}
  const defaultIso = (A && A.firstBreak && A.firstBreak.weekStartIso) || weeks[0].weekStartIso || "";
  const options = weeks
    .filter((w) => w.weekStartIso)
    .map((w) => `<option value="${escapeHtml(w.weekStartIso)}"${w.weekStartIso === defaultIso ? " selected" : ""}>${escapeHtml(w.label)} · ${escapeHtml(w.dates)}</option>`)
    .join("");
  view.innerHTML = head + `
    <div class="rr-intel-whatif">
      <form class="rr-intel-whatif-form" id="rr-wi-form">
        <label class="rr-intel-whatif-field">
          <span>Week</span>
          <select id="rr-wi-week">${options}</select>
        </label>
        <label class="rr-intel-whatif-field">
          <span>Extra routes/day</span>
          <input type="number" id="rr-wi-routes" min="0" max="30" step="1" value="0">
        </label>
        <label class="rr-intel-whatif-field">
          <span>Demand</span>
          <select id="rr-wi-mult">
            <option value="1" selected>As planned</option>
            <option value="1.15">+15% surge</option>
            <option value="1.25">Prime Week (+25%)</option>
            <option value="1.5">Peak (+50%)</option>
          </select>
        </label>
        <label class="rr-intel-whatif-field">
          <span>Callouts</span>
          <input type="number" id="rr-wi-callouts" min="0" max="15" step="1" value="0">
        </label>
        <label class="rr-intel-whatif-field">
          <span>Drivers quit</span>
          <input type="number" id="rr-wi-attrition" min="0" max="10" step="1" value="0">
        </label>
        <button type="submit" class="rr-intel-whatif-run" id="rr-wi-run">Run scenario</button>
      </form>
      <div class="rr-intel-whatif-result" id="rr-wi-result">
        <div class="rr-intel-empty">Pick a week, set the dials, and run. Callouts and attrition are simulated
        against your most-scheduled drivers first, so reruns are comparable.</div>
      </div>
    </div>`;
  const form = view.querySelector("#rr-wi-form");
  if (form) form.addEventListener("submit", (e) => { e.preventDefault(); _rrRunWhatIf(view); });
}

async function _rrRunWhatIf(view) {
  const btn = view.querySelector("#rr-wi-run");
  const out = view.querySelector("#rr-wi-result");
  if (!out) return;
  const weekIso = view.querySelector("#rr-wi-week")?.value || "";
  const clampInt = (id, max) => Math.max(0, Math.min(max, parseInt(view.querySelector(id)?.value, 10) || 0));
  const simple = {
    addRoutesPerDay: clampInt("#rr-wi-routes", 30),
    routeMultiplier: Number(view.querySelector("#rr-wi-mult")?.value) || 1,
    calloutCount: clampInt("#rr-wi-callouts", 15),
    attritionCount: clampInt("#rr-wi-attrition", 10),
  };
  if (btn) { btn.disabled = true; btn.textContent = "Running…"; }
  out.innerHTML = `<div class="rr-intel-empty">Loading the week's live roster and scoring the scenario…</div>`;
  const data = await _rrFlexForWeek(weekIso, simple);
  if (btn) { btn.disabled = false; btn.textContent = "Run scenario"; }
  if (!data || !data.whatIf) {
    out.innerHTML = `<div class="rr-intel-empty">The flex-capacity engine isn't reachable right now
      (it deploys with the next main build). Try again in a few minutes.</div>`;
    return;
  }
  const w = data.whatIf;
  const v = _RR_FLEX_VERDICT[w.status] || _RR_FLEX_VERDICT.green;
  const shortDays = (w.dailyShortages || []).filter((d) => d.shortage > 0);
  const dayNames = { mon: "Mon", tue: "Tue", wed: "Wed", thu: "Thu", fri: "Fri", sat: "Sat", sun: "Sun" };
  out.innerHTML = `
    <div class="rr-intel-flexplan-verdict">
      <span class="rr-intel-headline-pill ${v.cls}"><span class="dot"></span>${escapeHtml(v.label)}</span>
      <span class="rr-intel-flexplan-hint">${escapeHtml(v.hint)}
        · confidence ${Math.round(w.confidenceScore || 0)}%</span>
    </div>
    <div class="rr-intel-flexplan-tiers">
      <div class="rr-intel-flexplan-tier"><span>Comfortable headroom left</span><strong>+${Number(w.comfortableRemaining) || 0} routes/day</strong><em>preferred days, no pattern disruption</em></div>
      <div class="rr-intel-flexplan-tier"><span>Stretch headroom left</span><strong>+${Number(w.stretchRemaining) || 0} routes/day</strong><em>non-preferred days + voluntary 5th days</em></div>
      <div class="rr-intel-flexplan-tier"><span>Maximum ceiling left</span><strong>+${Number(w.maximumRemaining) || 0} routes/day</strong><em>emergency only — not sustainable</em></div>
    </div>
    ${shortDays.length ? `<div class="rr-intel-flexplan-hire">Uncoverable even at maximum:
      ${shortDays.map((d) => `<strong>${dayNames[d.day] || d.day} −${d.shortage}</strong>`).join(" · ")}
      (${w.weeklyShortage} route-day${w.weeklyShortage === 1 ? "" : "s"} short across the week)</div>` : ""}
    <div class="rr-intel-flexplan-hire">${w.driversNeeded > 0
      ? `<strong>Hire ${w.driversNeeded}</strong> (${w.recommendedFtHires} FT + ${w.recommendedPtHires} PT)
         to restore comfortable coverage · OT risk ${escapeHtml(w.otRisk || "—")} · schedule-disruption risk ${escapeHtml(w.scheduleDisruptionRisk || "—")}`
      : `No hires required for this scenario.`}</div>`;
}

const _RR_INTEL_RENDERERS = {
  "risk-forecast": _rrIntelRenderRiskForecast,
  "hiring-pulse": _rrIntelRenderHiringPulse,
  "what-if": _rrIntelRenderWhatIf,
  // 2 other intel views land in follow-up PRs:
  //   compliance-watch, peak-days
};

// ── Undo stack ─────────────────────────────────────────────────────
// A cross-app undo: each undoable action pushes { label, undo } onto
// a 30-deep stack. The topbar Undo button pops the most recent
// action; the caret opens a history of the last 30 so the DSP can
// roll back many changes. Reversible state changes only — actions
// that send a message (booking link, screening invite) can't be
// truly undone, so they don't go on the stack.
const _rrUndoStack = [];
const _RR_UNDO_MAX = 30;

function _rrPushUndo(entry) {
  if (!entry || typeof entry.undo !== "function") return;
  _rrUndoStack.push(entry);
  while (_rrUndoStack.length > _RR_UNDO_MAX) _rrUndoStack.shift();
  _rrRenderUndo();
}

function _rrRenderUndo() {
  const btn   = document.getElementById("rr-undo-btn");
  const caret = document.getElementById("rr-undo-caret");
  const menu  = document.getElementById("rr-undo-menu");
  if (!btn) return;
  const n = _rrUndoStack.length;
  btn.disabled = n === 0;
  if (caret) caret.disabled = n === 0;
  btn.title = n ? "Undo: " + _rrUndoStack[n - 1].label : "Nothing to undo";
  if (menu) {
    let rows = "";
    for (let idx = n - 1; idx >= 0; idx--) {
      const fromTop = n - 1 - idx;
      rows += `<button type="button" class="hdr-undo-item" data-undo-to="${idx}">`
            + `<span class="hdr-undo-item-ord">${fromTop === 0 ? "Last" : "−" + (fromTop + 1)}</span>`
            + `<span class="hdr-undo-item-lbl">${escapeHtml(_rrUndoStack[idx].label)}</span></button>`;
    }
    menu.innerHTML = '<div class="hdr-undo-head">Recent actions</div>'
      + (n ? rows : '<div class="hdr-undo-empty">Nothing to undo</div>');
  }
}

async function _rrUndoOne() {
  const entry = _rrUndoStack.pop();
  if (!entry) return false;
  _rrRenderUndo();
  try {
    await entry.undo();
    toast("Undone · " + entry.label, "success");
    return true;
  } catch (err) {
    _rrUndoStack.push(entry);
    _rrRenderUndo();
    toast("Undo failed: " + (err && err.message ? err.message : err), "warn");
    return false;
  }
}

async function _rrUndoTo(targetIndex) {
  // Undo from the top of the stack down to (and including) targetIndex.
  while (_rrUndoStack.length > targetIndex) {
    const ok = await _rrUndoOne();
    if (!ok) break;
  }
}

// Cmd/Ctrl+Z → undo the last schedule action. Dispatchers expect this; without
// it the undo affordance is effectively invisible mid-task. Ignored while typing
// in a field and only when there's something to undo.
document.addEventListener("keydown", (e) => {
  if ((e.key === "z" || e.key === "Z") && (e.metaKey || e.ctrlKey) && !e.shiftKey && !e.altKey) {
    const tag = (document.activeElement && document.activeElement.tagName) || "";
    if (/INPUT|TEXTAREA|SELECT/.test(tag) || document.activeElement?.isContentEditable) return;
    if (Array.isArray(_rrUndoStack) && _rrUndoStack.length) {
      e.preventDefault();
      _rrUndoOne();
    }
  }
});

document.addEventListener("click", (e) => {
  const menu = document.getElementById("rr-undo-menu");
  if (e.target.closest("#rr-undo-btn"))   { _rrUndoOne(); return; }
  const caret = e.target.closest("#rr-undo-caret");
  if (caret) {
    if (menu) { menu.hidden = !menu.hidden; caret.setAttribute("aria-expanded", menu.hidden ? "false" : "true"); }
    return;
  }
  const item = e.target.closest(".hdr-undo-item");
  if (item) {
    if (menu) menu.hidden = true;
    _rrUndoTo(parseInt(item.getAttribute("data-undo-to"), 10) || 0);
    return;
  }
  if (menu && !menu.hidden && !e.target.closest("#rr-undo-menu")) menu.hidden = true;
});

// ─── Stage filter + view-switch hooks ──────────────────────────────────────

function getActiveStage() {
  const active = $("#pipeline-stage-tabs .stage-tab.active");
  return active?.getAttribute("data-stage") ?? "all";
}

const _legacyFilter = window.filterPipelineStage;
window.filterPipelineStage = function (btn) {
  if (typeof _legacyFilter === "function") _legacyFilter(btn);
  loadPipeline(btn.getAttribute("data-stage") ?? "all");
};

const _legacyGoto = window.goto;
window.goto = function (view) {
  // Clear the fleet-calendar Expand overlay so its body class (and the
  // overflow:hidden it sets) can't linger and pin the next view.
  document.body.classList.remove("rr-fc-focus");
  if (typeof _closeAttKpiDetail === "function")     _closeAttKpiDetail();
  if (typeof _closeAvailKpiDetail === "function")   _closeAvailKpiDetail();
  if (typeof _closeRosterKpiDetail === "function")  _closeRosterKpiDetail();
  // The hiring pipeline (Funnel / Interview Day / Calendar) now lives
  // inside the Onboarding page — redirect legacy entry points there.
  let _pipeSub = null;
  if (view === "pipeline" || view === "interview" || view === "calendar") {
    _pipeSub = view === "pipeline" ? "funnel" : view;
    view = "onboarding-ops";
  }
  if (typeof _legacyGoto === "function") _legacyGoto(view);
  if (view === "pipeline")  loadPipeline(getActiveStage());
  if (view === "drivers")   {
    // KPI strip starts hidden every time the operator returns to Drivers.
    const insBox = document.getElementById("rr-roster-insights");
    if (insBox) insBox.style.display = "none";
    const insBtn = document.getElementById("rr-roster-insights-toggle");
    if (insBtn) { insBtn.setAttribute("aria-pressed", "false"); insBtn.classList.remove("is-on"); }
    // And the stage always returns to Active.
    _driverStage = "active";
    document.querySelectorAll('[data-rr-tabbar="drivers-stage"] .stage-tab').forEach((b) => {
      b.classList.toggle("active", b.getAttribute("data-stage") === "active");
    });
    const inLink = document.getElementById("rr-roster-inactive-link");
    if (inLink) inLink.classList.remove("is-on");
    loadDriversRoster(); refreshI9Badge();
  }
  if (view === "onboarding-ops") {
    if (_pipeSub) { loadOnboardingOps({ keepTab: true }); if (typeof window.obSub === "function") window.obSub(_pipeSub); }
    else {
      // Opening the Onboarding page lands on the Calendar in Work Week view.
      // Re-assert across the next ticks so a late default (Funnel) can't win
      // the sub-view race on first paint.
      loadOnboardingOps({ keepTab: true });
      _ivcalView = "workweek";
      const _openCal = () => { try { if (typeof window.obSub === "function") window.obSub("calendar"); } catch (_) {} };
      _openCal();
      requestAnimationFrame(_openCal);
      setTimeout(_openCal, 60);
      setTimeout(_openCal, 280);
    }
  }
  if (view === "checkin")   loadCheckinView();
  if (view === "dashboard") { loadTodayPlan(); _toFetchPendingCount(); }
  if (view === "messages")  { _msgInboxTab = "drivers"; _msgInboxMode = "direct"; _msgChannelKind = "broadcast"; _msgSyncTabStrip("drivers"); loadDriverChatInbox(); }
  if (view === "workspaces") loadWorkspacesView();
  if (view === "workbooks") loadWorkbooksView();
  if (view === "notebooks" && window.RRNotebooks) window.RRNotebooks.loadView();
  if (view === "forms")     loadFormsList();
  if (view === "admin")     { loadPlatformAdmin(); loadAdminSupportInbox(); }
  if (view === "outlook")   loadStaffingOutlook();
  // Fleet lives on #view-fleet2 now ('fleet' is redirected to 'fleet2'
  // by the base goto). Load the roster + restore the last sub-view on
  // entry to either alias.
  if ((view === "fleet" || view === "fleet2") && typeof loadFleetView === "function") {
    loadFleetView();
    if (typeof window.fleetSub === "function") window.fleetSub(_fleetSub || "vehicles");
    // Park the global bell on Fleet's action bar so the app launcher
    // docks beside it — same top-right chrome spot as Schedule.
    if (typeof _rrMoveChromeToFleet === "function") _rrMoveChromeToFleet();
  }
  if (view === "recognition" && typeof loadRecognitionView === "function") loadRecognitionView();
  if (view === "compliance" && typeof loadComplianceWorkspace === "function") loadComplianceWorkspace();
};

// ── Platform admin view ────────────────────────────────────────────────────
// Cross-tenant DSP management.  Backed by the SECURITY DEFINER admin_*
// RPCs from migration 0124; each RPC re-checks is_platform_admin() in
// its body so calling it as a non-admin returns 'forbidden'.

// Module-level state for the admin table.  Loaded once per view-enter
// from admin_list_dsps(); search / filter / sort / page operate on the
// in-memory copy (it tops out at a few hundred rows even at 100×
// growth, so client-side is fine and feels instant).
const _admin = {
  dsps: [],
  search: "",
  filterStatus: "",
  filterPlan: "",
  sort: "created_at:desc",
  page: 1,
  pageSize: 25,
  loaded: false,
};

async function loadPlatformAdmin() {
  if (profile.role !== "platform_admin") {
    // Defensive: a non-admin somehow landed on the view (deep link,
    // back button after role change, etc.).  Bounce them rather than
    // letting them sit on a permission-denied page.
    window.goto("dashboard");
    return;
  }
  await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);
}

async function _loadPlatformAdminStats() {
  const { data, error } = await sb.rpc("admin_kpis");
  const slots = document.querySelectorAll('#view-admin [data-rr-admin-stat-value]');
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    console.error("admin_kpis failed:", error);
    slots.forEach((el) => { el.textContent = "—"; });
    if (typeof toast === "function") toast(`Couldn't load admin stats: ${error.message}`, "warn");
    return;
  }
  const kpis = data || {};
  const map = {
    total:     kpis.total ?? 0,
    active:    kpis.active ?? 0,
    pending:   kpis.pending ?? 0,
    suspended: kpis.suspended ?? 0,
  };
  for (const [key, value] of Object.entries(map)) {
    const card = document.querySelector(`#view-admin [data-rr-admin-stat="${key}"]`);
    if (!card) continue;
    const slot = card.querySelector("[data-rr-admin-stat-value]");
    if (!slot) continue;
    slot.textContent = String(value);
  }
}

async function _loadPlatformAdminDsps() {
  const tbody = document.getElementById("rr-admin-tbody");
  if (!tbody) return;
  // Skeleton rows are already in the markup; only show them on the
  // FIRST load to avoid a flash on subsequent re-paints.
  if (!_admin.loaded) {
    tbody.innerHTML = `
      <tr><td colspan="11" class="rr-admin-skel"><span></span></td></tr>
      <tr><td colspan="11" class="rr-admin-skel"><span></span></td></tr>
      <tr><td colspan="11" class="rr-admin-skel"><span></span></td></tr>`;
  }
  const { data, error } = await sb.rpc("admin_list_dsps");
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    console.error("admin_list_dsps failed:", error);
    tbody.innerHTML = `<tr><td colspan="11" style="padding:var(--s-6);color:var(--red);text-align:center">${escapeHtml(error.message)}</td></tr>`;
    return;
  }
  _admin.dsps = data || [];
  _admin.loaded = true;
  _renderPlatformAdminTable();
  _adminRenderInsights();
}

function _adminFilteredDsps() {
  const q = _admin.search.trim().toLowerCase();
  let rows = _admin.dsps.slice();
  if (q) {
    rows = rows.filter((d) => {
      const haystack = [
        d.name, d.short_code, d.owner_email, d.owner_name, d.phone, d.address, d.notes,
      ].filter(Boolean).join(" ").toLowerCase();
      return haystack.includes(q);
    });
  }
  if (_admin.filterStatus) rows = rows.filter((d) => d.status === _admin.filterStatus);
  if (_admin.filterPlan)   rows = rows.filter((d) => d.subscription_plan === _admin.filterPlan);

  const [field, dir] = _admin.sort.split(":");
  const mul = dir === "asc" ? 1 : -1;
  rows.sort((a, b) => {
    const av = a[field], bv = b[field];
    // null-last sort: missing values always sink regardless of direction
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    if (typeof av === "number" && typeof bv === "number") return (av - bv) * mul;
    if (field === "created_at" || field === "last_active_at") {
      return (new Date(av).getTime() - new Date(bv).getTime()) * mul;
    }
    return String(av).localeCompare(String(bv)) * mul;
  });
  return rows;
}

function _adminFmtRelative(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  const ms = Date.now() - d.getTime();
  const m = Math.floor(ms / 60000);
  if (m < 1)   return "just now";
  if (m < 60)  return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24)  return `${h}h ago`;
  const days = Math.floor(h / 24);
  if (days < 30) return `${days}d ago`;
  return d.toLocaleDateString();
}

// ── Control-center insights ─────────────────────────────────────────────
// Everything below is derived client-side from the in-memory DSP list
// (_admin.dsps) — no extra round-trips.  Drives the KPI context lines,
// the Needs-attention queue, and the Portfolio snapshot.

const _ADMIN_DAY_MS = 86400000;
function _adminDaysSince(iso) {
  if (!iso) return null;
  return Math.floor((Date.now() - new Date(iso).getTime()) / _ADMIN_DAY_MS);
}

// Attention signals for one DSP.  Suspended is deliberately excluded —
// it's an intentional admin state (surfaced as a red health dot), not a
// "something's wrong" queue item.
function _adminRowSignals(d) {
  const sig = [];
  if (!d || d.status === "suspended") return sig;
  if (!d.owner_email) {
    sig.push({ sev: 3, short: "No owner", label: "No owner has signed up yet" });
  }
  if (d.status === "pending") {
    const age = _adminDaysSince(d.created_at);
    if (age != null && age >= 7) {
      sig.push({ sev: 3, short: `Pending ${age}d`, label: `Awaiting owner signup for ${age} days` });
    }
  }
  if (d.status === "active" && (d.driver_count ?? 0) === 0) {
    sig.push({ sev: 2, short: "0 drivers", label: "Active, but no drivers added yet" });
  }
  if (d.status === "active") {
    const idle = _adminDaysSince(d.last_active_at);
    if (idle != null && idle >= 30) {
      sig.push({ sev: 1, short: `Idle ${idle}d`, label: `No activity for ${idle} days` });
    }
  }
  // Client-error spike — bump to high severity past 10 in a week.
  const errs = d.error_count_7d ?? 0;
  if (errs >= 3) {
    sig.push({
      sev: errs >= 10 ? 3 : 2,
      short: `${errs} error${errs === 1 ? "" : "s"}`,
      label: `${errs} client error${errs === 1 ? "" : "s"} in the last 7 days`,
    });
  }
  return sig;
}

function _adminRenderInsights() {
  const dsps = _admin.dsps || [];
  const total = dsps.length;
  const active    = dsps.filter((d) => d.status === "active").length;
  const pending   = dsps.filter((d) => d.status === "pending");
  const suspended = dsps.filter((d) => d.status === "suspended").length;

  // ── KPI context lines ────────────────────────────────────────────────
  const setSub = (key, html) => {
    const el = document.querySelector(`#view-admin [data-rr-admin-substat="${key}"]`);
    if (el) el.innerHTML = html;
  };
  const newLast30 = dsps.filter((d) => {
    const age = _adminDaysSince(d.created_at);
    return age != null && age <= 30;
  }).length;
  setSub("total", newLast30 > 0
    ? `<span class="rr-kpi-trend rr-kpi-trend--up">+${newLast30}</span> new · last 30 days`
    : `All registered DSPs`);

  const activePct = total ? Math.round((active / total) * 100) : 0;
  const bar = document.querySelector('#view-admin [data-rr-admin-bar="active"]');
  if (bar) bar.style.width = `${activePct}%`;
  setSub("active", total ? `${activePct}% of portfolio operating` : `Operating normally`);

  const pendingAges = pending.map((d) => _adminDaysSince(d.created_at)).filter((a) => a != null);
  const oldestPending = pendingAges.length ? Math.max(...pendingAges) : null;
  setSub("pending", pending.length === 0
    ? `None awaiting signup`
    : (oldestPending != null
        ? `Oldest waiting <strong>${oldestPending}d</strong>`
        : `Awaiting owner signup`));

  setSub("suspended", suspended > 0
    ? `${suspended} account${suspended === 1 ? "" : "s"} disabled`
    : `None suspended`);

  _adminRenderAttention();
  _adminRenderPortfolio();
}

function _adminRenderAttention() {
  const host = document.getElementById("rr-admin-attention");
  const countEl = document.getElementById("rr-admin-attention-count");
  if (!host) return;

  const flagged = (_admin.dsps || [])
    .map((d) => ({ d, signals: _adminRowSignals(d) }))
    .filter((x) => x.signals.length > 0)
    .map((x) => ({ ...x, top: Math.max(...x.signals.map((s) => s.sev)) }))
    .sort((a, b) => (b.top - a.top) || (a.d.name || "").localeCompare(b.d.name || ""));

  if (countEl) {
    countEl.hidden = flagged.length === 0;
    countEl.textContent = String(flagged.length);
  }

  if (flagged.length === 0) {
    host.innerHTML = `
      <div class="rr-cc-allclear">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
        <div class="rr-cc-allclear__title">All clear</div>
        <div class="rr-cc-allclear__sub">No DSPs need attention right now.</div>
      </div>`;
    return;
  }

  const MAX = 6;
  const shown = flagged.slice(0, MAX);
  const sevClass = (s) => s >= 3 ? "high" : s >= 2 ? "med" : "low";
  host.innerHTML = shown.map(({ d, signals, top }) => {
    const chips = signals.slice(0, 3).map((s) =>
      `<span class="rr-cc-chip rr-cc-chip--${sevClass(s.sev)}" title="${escapeHtml(s.label)}">${escapeHtml(s.short)}</span>`
    ).join("");
    return `
      <button class="rr-cc-att-row" type="button" data-rr-admin-focus="${escapeHtml(d.id)}">
        <span class="rr-cc-att-row__dot rr-cc-att-row__dot--${sevClass(top)}" aria-hidden="true"></span>
        <span class="rr-cc-att-row__body">
          <span class="rr-cc-att-row__name">${escapeHtml(d.name || "—")}${d.short_code ? ` <span class="rr-cc-att-row__code">${escapeHtml(d.short_code)}</span>` : ""}</span>
          <span class="rr-cc-att-row__chips">${chips}</span>
        </span>
        <svg class="rr-cc-att-row__go" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="9 18 15 12 9 6"/></svg>
      </button>`;
  }).join("") + (flagged.length > MAX
    ? `<div class="rr-cc-att-more">+${flagged.length - MAX} more with signals</div>`
    : "");
}

function _adminRenderPortfolio() {
  const host = document.getElementById("rr-admin-portfolio");
  if (!host) return;
  const dsps = _admin.dsps || [];
  const totalDrivers = dsps.reduce((sum, d) => sum + (d.driver_count ?? 0), 0);
  const plans = [
    { key: "starter",    label: "Starter",    cls: "starter" },
    { key: "growth",     label: "Growth",     cls: "growth" },
    { key: "enterprise", label: "Enterprise", cls: "enterprise" },
  ];
  const counts = plans.map((p) => ({ ...p, n: dsps.filter((d) => (d.subscription_plan || "starter") === p.key).length }));
  const maxN = Math.max(1, ...counts.map((c) => c.n));

  host.innerHTML = `
    <div class="rr-cc-metric">
      <div class="rr-cc-metric__value">${totalDrivers.toLocaleString()}</div>
      <div class="rr-cc-metric__label">Drivers under management</div>
    </div>
    <div class="rr-cc-plans">
      <div class="rr-cc-plans__head">Plan mix</div>
      ${counts.map((c) => `
        <div class="rr-cc-plan">
          <span class="rr-cc-plan__name">${c.label}</span>
          <span class="rr-cc-plan__track"><span class="rr-cc-plan__fill rr-cc-plan__fill--${c.cls}" style="width:${Math.round((c.n / maxN) * 100)}%"></span></span>
          <span class="rr-cc-plan__n">${c.n}</span>
        </div>`).join("")}
    </div>`;
}

function _renderPlatformAdminTable() {
  const tbody    = document.getElementById("rr-admin-tbody");
  const empty    = document.getElementById("rr-admin-empty");
  const emptySub = document.getElementById("rr-admin-empty-sub");
  const count    = document.getElementById("rr-admin-row-count");
  const pagWrap  = document.getElementById("rr-admin-pagination");
  if (!tbody) return;

  const filtered = _adminFilteredDsps();
  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / _admin.pageSize));
  if (_admin.page > totalPages) _admin.page = totalPages;
  const start = (_admin.page - 1) * _admin.pageSize;
  const pageRows = filtered.slice(start, start + _admin.pageSize);

  if (count) {
    const all = _admin.dsps.length;
    count.textContent = total === all
      ? `${all} DSP${all === 1 ? "" : "s"}`
      : `${total} of ${all} DSPs`;
  }

  if (total === 0) {
    tbody.innerHTML = "";
    if (empty) empty.hidden = false;
    if (emptySub) {
      emptySub.textContent = (_admin.dsps.length === 0)
        ? "Add your first DSP client to get started."
        : "Try clearing filters or search.";
    }
    if (pagWrap) pagWrap.hidden = true;
    return;
  }
  if (empty) empty.hidden = true;

  tbody.innerHTML = pageRows.map((d) => _renderAdminRow(d)).join("");
  _bindAdminRowActions();

  // Pagination
  if (pagWrap) {
    pagWrap.hidden = total <= _admin.pageSize;
    const sumEl  = document.getElementById("rr-admin-pagination-summary");
    const lblEl  = document.getElementById("rr-admin-page-label");
    const prevEl = document.getElementById("rr-admin-page-prev");
    const nextEl = document.getElementById("rr-admin-page-next");
    if (sumEl)  sumEl.textContent  = `Showing ${start + 1}–${Math.min(start + _admin.pageSize, total)} of ${total}`;
    if (lblEl)  lblEl.textContent  = `Page ${_admin.page} of ${totalPages}`;
    if (prevEl) prevEl.disabled    = _admin.page <= 1;
    if (nextEl) nextEl.disabled    = _admin.page >= totalPages;
  }
}

function _renderAdminRow(d) {
  const statusClass =
    d.status === "active"    ? "status-pill-success" :
    d.status === "pending"   ? "status-pill-pending" :
    d.status === "suspended" ? "status-pill-danger"  : "status-pill-neutral";
  const statusLabel =
    d.status === "active"    ? "Active" :
    d.status === "pending"   ? "Pending" :
    d.status === "suspended" ? "Suspended" : (d.status || "—");
  const planClass = d.subscription_plan === "enterprise"
    ? "rr-admin-cell-plan rr-admin-cell-plan--enterprise"
    : d.subscription_plan === "growth"
      ? "rr-admin-cell-plan rr-admin-cell-plan--growth"
      : "rr-admin-cell-plan";
  const ownerLine = d.owner_name
    ? escapeHtml(d.owner_name)
    : `<span class="rr-admin-cell-muted">No owner yet</span>`;
  const emailLine = d.owner_email
    ? `<a href="mailto:${escapeHtml(d.owner_email)}" style="color:inherit;text-decoration:none">${escapeHtml(d.owner_email)}</a>`
    : `<span class="rr-admin-cell-muted">—</span>`;
  const phoneLine = d.phone
    ? phoneCell(d.phone)
    : `<span class="rr-admin-cell-muted">—</span>`;

  // Health dot — a glanceable roll-up of this DSP's attention signals
  // (same logic as the Needs-attention queue).  Green = all clear,
  // amber = a soft signal, red = suspended.
  const signals = _adminRowSignals(d);
  const health = d.status === "suspended" ? "red" : (signals.length ? "amber" : "green");
  const healthTitle = d.status === "suspended"
    ? "Suspended"
    : (signals.length ? signals.map((s) => s.short).join(" · ") : "All clear");

  // Modules cell — how many pages/features are enabled vs the catalog.
  // Full = "All on" chip; anything trimmed shows the fraction so an
  // admin can see at a glance which DSPs are on a reduced package.
  const cat = window.RR_ENTITLEMENTS || { pages: [], features: [] };
  const totalMods = cat.pages.length + cat.features.length;
  const offMods = (Array.isArray(d.disabled_pages) ? d.disabled_pages.length : 0)
                + (Array.isArray(d.disabled_features) ? d.disabled_features.length : 0);
  const onMods = Math.max(0, totalMods - offMods);
  const modulesCell = totalMods === 0
    ? `<span class="rr-admin-cell-muted">—</span>`
    : (offMods === 0
        ? `<button class="rr-admin-mods rr-admin-mods--all" data-rr-admin-action="access" type="button" title="All modules on">All on</button>`
        : `<button class="rr-admin-mods rr-admin-mods--trimmed" data-rr-admin-action="access" type="button" title="${offMods} module${offMods === 1 ? "" : "s"} off — click to manage">${onMods}/${totalMods}</button>`);

  // Suspend vs Reactivate based on current status.
  const suspendItem = d.status === "suspended"
    ? `<button class="rr-admin-row-actions__item" data-rr-admin-action="reactivate"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>Reactivate account</button>`
    : `<button class="rr-admin-row-actions__item rr-admin-row-actions__item--danger" data-rr-admin-action="suspend"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/></svg>Suspend account</button>`;

  return `
    <tr data-rr-admin-row="${escapeHtml(d.id)}">
      <td>
        <div class="rr-admin-cell-dsp">
          <span class="rr-admin-health rr-admin-health--${health}" title="${escapeHtml(healthTitle)}" aria-label="${escapeHtml(healthTitle)}"></span>
          <div style="min-width:0">
            <div class="rr-admin-cell-dsp__name">${escapeHtml(d.name || "—")}</div>
            ${d.short_code ? `<div class="rr-admin-cell-dsp__sub">${escapeHtml(d.short_code)}</div>` : ""}
          </div>
        </div>
      </td>
      <td>${ownerLine}</td>
      <td>${emailLine}</td>
      <td>${phoneLine}</td>
      <td><span class="status-pill ${statusClass}">${escapeHtml(statusLabel)}</span></td>
      <td class="rr-admin-cell-num">${d.driver_count ?? 0}</td>
      <td class="rr-admin-cell-num">${(d.route_count ?? 0) > 0 ? d.route_count : `<span class="rr-admin-cell-muted">0</span>`}</td>
      <td><span class="${planClass}">${escapeHtml(d.subscription_plan || "starter")}</span></td>
      <td>${modulesCell}</td>
      <td class="rr-admin-cell-muted">${_adminFmtRelative(d.last_active_at)}</td>
      <td class="rr-admin-row-actions">
        <button class="rr-admin-row-actions__btn" data-rr-admin-toggle="${escapeHtml(d.id)}" aria-label="Open actions">
          <svg viewBox="0 0 24 24" fill="currentColor" stroke="none"><circle cx="5" cy="12" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="19" cy="12" r="1.6"/></svg>
        </button>
        <div class="rr-admin-row-actions__menu" data-rr-admin-menu="${escapeHtml(d.id)}" hidden>
          <button class="rr-admin-row-actions__item" data-rr-admin-action="view"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>View details</button>
          <button class="rr-admin-row-actions__item" data-rr-admin-action="edit"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>Edit account</button>
          <button class="rr-admin-row-actions__item" data-rr-admin-action="users"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>Manage users</button>
          <button class="rr-admin-row-actions__item" data-rr-admin-action="access"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>Access &amp; modules</button>
          <div class="rr-admin-row-actions__sep"></div>
          ${suspendItem}
          <button class="rr-admin-row-actions__item rr-admin-row-actions__item--danger" data-rr-admin-action="delete"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>Delete account</button>
        </div>
      </td>
    </tr>`;
}

function _bindAdminRowActions() {
  // Action buttons on rows.  Delegated to the document so the bind
  // happens once and survives every re-render.
  if (_bindAdminRowActions._bound) return;
  _bindAdminRowActions._bound = true;

  document.addEventListener("click", (e) => {
    // Toggle the per-row "..." menu.
    const tgl = e.target.closest("[data-rr-admin-toggle]");
    if (tgl) {
      e.stopPropagation();
      const id = tgl.getAttribute("data-rr-admin-toggle");
      const menu = document.querySelector(`[data-rr-admin-menu="${id}"]`);
      const wasOpen = menu && !menu.hidden;
      // Close every other menu first.
      document.querySelectorAll('[data-rr-admin-menu]').forEach((m) => { m.hidden = true; });
      if (menu && !wasOpen) menu.hidden = false;
      return;
    }
    // Run an action.
    const item = e.target.closest("[data-rr-admin-action]");
    if (item) {
      const row = item.closest("[data-rr-admin-row]");
      const dspId = row?.getAttribute("data-rr-admin-row");
      const action = item.getAttribute("data-rr-admin-action");
      if (!dspId) return;
      _runAdminAction(action, dspId);
      // Close the menu.
      document.querySelectorAll('[data-rr-admin-menu]').forEach((m) => { m.hidden = true; });
      return;
    }
    // Click anywhere else closes any open menu.
    if (!e.target.closest('[data-rr-admin-menu]')) {
      document.querySelectorAll('[data-rr-admin-menu]').forEach((m) => { m.hidden = true; });
    }
  });
}

async function _runAdminAction(action, dspId) {
  const dsp = _admin.dsps.find((d) => d.id === dspId);
  if (!dsp) return;
  switch (action) {
    case "view":
      _openAdminDspProfile(dspId);
      return;
    case "edit":
      _openAdminEditDspModal(dspId);
      return;
    case "users":
      _openAdminManageUsers(dspId);
      return;
    case "access":
      _openAdminAccessDrawer(dspId);
      return;
    case "suspend": {
      if (!(await _rrConfirmDialog({ title: `Suspend "${dsp.name}"?`, body: "All users at this DSP will lose access until you reactivate.", confirmLabel: "Suspend", danger: true }))) return;
      const { error } = await sb.rpc("admin_suspend_dsp", { p_dsp_id: dspId });
      if (error) {
        if (_isAuthError(error)) _forceRelogin("session_expired");
        toast(`Couldn't suspend: ${error.message}`, "warn");
        return;
      }
      toast(`${dsp.name} suspended.`, "ok");
      await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);
      return;
    }
    case "reactivate": {
      if (!(await _rrConfirmDialog({ title: `Reactivate "${dsp.name}"?`, confirmLabel: "Reactivate" }))) return;
      const { error } = await sb.rpc("admin_reactivate_dsp", { p_dsp_id: dspId });
      if (error) {
        if (_isAuthError(error)) _forceRelogin("session_expired");
        toast(`Couldn't reactivate: ${error.message}`, "warn");
        return;
      }
      toast(`${dsp.name} reactivated.`, "ok");
      await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);
      return;
    }
    case "delete": {
      _openAdminDeleteDspModal(dsp);
      return;
    }
  }
}

function _adminCsvExport() {
  const rows = _adminFilteredDsps();
  const cols = [
    ["DSP",          (d) => d.name || ""],
    ["Short code",   (d) => d.short_code || ""],
    ["Owner",        (d) => d.owner_name || ""],
    ["Email",        (d) => d.owner_email || ""],
    ["Phone",        (d) => d.phone || ""],
    ["Address",      (d) => d.address || ""],
    ["Status",       (d) => d.status || ""],
    ["Plan",         (d) => d.subscription_plan || ""],
    ["Drivers",      (d) => d.driver_count ?? 0],
    ["Routes",       (d) => d.route_count ?? 0],
    ["Last active",  (d) => d.last_active_at || ""],
    ["Created",      (d) => d.created_at || ""],
    ["Notes",        (d) => d.notes || ""],
  ];
  const esc = (v) => {
    const s = String(v ?? "");
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const lines = [cols.map(([h]) => esc(h)).join(",")];
  for (const r of rows) lines.push(cols.map(([, fn]) => esc(fn(r))).join(","));
  const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `routeready-dsps-${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Wire the toolbar + CTA buttons once the DOM is ready.  IMPORTANT:
// live.js uses top-level `await` (the auth gate at the top of the
// file).  The HTML spec does NOT delay DOMContentLoaded for module
// promises, so any code AFTER the top-level await runs AFTER DCL has
// already fired.  Registering `document.addEventListener("DOMContent-
// Loaded", ...)` here would silently never fire — the original Phase
// 3/4a/4c bug where Add-DSP / Invite-user / search / sort / etc. all
// looked dead.  Bind directly instead; the DOM is guaranteed parsed
// by the time the post-await code reaches this line.
function _bindAdminPageHandlers() {
  const search   = document.getElementById("rr-admin-search");
  const fStatus  = document.getElementById("rr-admin-filter-status");
  const fPlan    = document.getElementById("rr-admin-filter-plan");
  const sortSel  = document.getElementById("rr-admin-sort");
  const exportEl = document.getElementById("rr-admin-export");
  const prevEl   = document.getElementById("rr-admin-page-prev");
  const nextEl   = document.getElementById("rr-admin-page-next");
  const emptyCta = document.getElementById("rr-admin-empty-cta");

  search?.addEventListener("input", () => {
    _admin.search = search.value;
    _admin.page = 1;
    _renderPlatformAdminTable();
  });
  fStatus?.addEventListener("change", () => { _admin.filterStatus = fStatus.value; _admin.page = 1; _renderPlatformAdminTable(); });
  fPlan?.addEventListener("change",   () => { _admin.filterPlan   = fPlan.value;   _admin.page = 1; _renderPlatformAdminTable(); });
  sortSel?.addEventListener("change", () => { _admin.sort         = sortSel.value;  _renderPlatformAdminTable(); });
  exportEl?.addEventListener("click", () => _adminCsvExport());
  prevEl?.addEventListener("click", () => { if (_admin.page > 1) { _admin.page -= 1; _renderPlatformAdminTable(); }});
  nextEl?.addEventListener("click", () => { _admin.page += 1; _renderPlatformAdminTable(); });
  emptyCta?.addEventListener("click", () => document.getElementById("rr-admin-add-dsp")?.click());

  // Needs-attention queue → clicking a row opens that DSP's profile
  // drawer (drill-down).  Delegated so it survives every re-paint.
  document.addEventListener("click", (e) => {
    const row = e.target.closest("[data-rr-admin-focus]");
    if (!row) return;
    const id = row.getAttribute("data-rr-admin-focus");
    if (!(_admin.dsps || []).some((d) => d.id === id)) return;
    _openAdminDspProfile(id);
  });

  // "Add DSP client" → open the Phase-4a modal.
  document.getElementById("rr-admin-add-dsp")?.addEventListener("click", () => {
    _openAdminAddDspModal();
  });
  // "Invite user" → open the invite modal.
  document.getElementById("rr-admin-invite-user")?.addEventListener("click", () => {
    _openAdminInviteUser();
  });
  // Invite form submit.
  document.getElementById("rr-admin-invite-form")?.addEventListener("submit", _submitAdminInviteUser);

  // Auto-suggest short code from DSP name as the operator types.
  // (The Add-DSP modal used to expose a "Station code" field that
  // collided whenever multiple DSPs operated out of the same Amazon
  // station.  Migration 0125 makes the server auto-generate a unique
  // workspace identifier from the DSP name, so the field is gone
  // from the UI and the auto-suggest logic that fed it is no longer
  // needed.)

  // Form submit handlers.
  document.getElementById("rr-admin-add-dsp-form")?.addEventListener("submit", _submitAdminAddDsp);
  document.getElementById("rr-admin-edit-dsp-form")?.addEventListener("submit", _submitAdminEditDsp);
}
// Run immediately (post-await means the DOM is already parsed) — no
// need to wait for DCL, and waiting would silently break us.
_bindAdminPageHandlers();

// ── Delete-DSP modal ───────────────────────────────────────────────────────
// Hard delete via admin_delete_dsp RPC.  Typed-name confirmation
// guards against accidental clicks.  The Delete button stays
// disabled until the confirmation input matches the DSP name
// exactly (case-insensitive whitespace-trimmed).

function _openAdminDeleteDspModal(dsp) {
  const idEl    = document.getElementById("rr-delete-dsp-id");
  const nameEl  = document.getElementById("rr-delete-dsp-name");
  const dispEl  = document.getElementById("rr-delete-dsp-name-display");
  const subEl   = document.getElementById("rr-delete-dsp-sub");
  const confEl  = document.getElementById("rr-delete-dsp-confirm");
  const submit  = document.getElementById("rr-admin-delete-dsp-submit");
  const errEl   = document.getElementById("rr-admin-delete-dsp-error");
  if (idEl)    idEl.value      = dsp.id;
  if (nameEl)  nameEl.value    = dsp.name || "";
  if (dispEl)  dispEl.textContent = dsp.name || "—";
  if (subEl)   subEl.textContent  = `${dsp.name} · ${dsp.short_code || "—"}`;
  if (confEl)  { confEl.value = ""; confEl.placeholder = dsp.name || ""; }
  if (submit)  submit.disabled = true;
  if (errEl)   { errEl.hidden = true; errEl.textContent = ""; }
  if (typeof window.openModal === "function") window.openModal("modal-admin-delete-dsp");
  setTimeout(() => confEl?.focus(), 60);
}

function _bindAdminDeleteDspHandlers() {
  const confEl = document.getElementById("rr-delete-dsp-confirm");
  const nameEl = document.getElementById("rr-delete-dsp-name");
  const submit = document.getElementById("rr-admin-delete-dsp-submit");
  const form   = document.getElementById("rr-admin-delete-dsp-form");
  if (!confEl || !nameEl || !submit || !form) return;

  // Live match check on the confirmation input.
  const refresh = () => {
    const target = (nameEl.value || "").trim().toLowerCase();
    const typed  = (confEl.value || "").trim().toLowerCase();
    submit.disabled = !(target && target === typed);
  };
  confEl.addEventListener("input", refresh);

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    const dspId  = document.getElementById("rr-delete-dsp-id")?.value;
    const name   = nameEl.value || "";
    const lbl    = submit.querySelector("[data-rr-delete-dsp-label]");
    const errEl  = document.getElementById("rr-admin-delete-dsp-error");
    if (!dspId) return;

    submit.disabled = true;
    if (lbl) lbl.textContent = "Deleting…";
    if (errEl) errEl.hidden = true;

    // Delete via the admin-delete-dsp edge function (full scrub —
    // DB cascade + auth.users + storage objects).  Falls back to the
    // SQL admin_delete_dsp RPC if the edge function isn't deployed
    // yet (DB-only delete; auth users + storage are left orphaned
    // but the DSP itself is gone).
    let resp = await sb.functions.invoke("admin-delete-dsp", {
      body: { p_dsp_id: dspId },
    });
    let raw = "";
    if (resp.error) {
      // Surface the function's structured error if present.
      try {
        const ctx = await resp.error.context?.json?.();
        if (ctx?.error) raw = ctx.error;
      } catch { /* fall through */ }
      raw = raw || resp.error.message || "";

      // If the edge function literally isn't deployed yet (404),
      // fall back to the SQL RPC so admins still have a delete
      // path during the deploy window.
      if (/not[\s_-]*found|404|deployment/i.test(raw) && !/dsp_not_found/.test(raw)) {
        const sqlResp = await sb.rpc("admin_delete_dsp", { p_dsp_id: dspId });
        if (!sqlResp.error) {
          resp = { data: { ok: true, fallback: "sql" }, error: null };
          raw = "";
        } else {
          raw = sqlResp.error.message || raw;
        }
      }
    }

    if (raw) {
      if (_isAuthError(resp.error)) _forceRelogin("session_expired");
      let msg = raw;
      if (/cannot_delete_own_dsp/.test(raw)) msg = "You can't delete the DSP your own account is attached to.";
      else if (/platform_admin_in_target_dsp/.test(raw)) msg = "Cannot delete this DSP — a platform admin is a member.  Move their account to another workspace first, then retry.";
      else if (/dsp_not_found/.test(raw))    msg = "That DSP no longer exists. Refresh the table.";
      else if (/forbidden/.test(raw))        msg = "You don't have admin access. Sign in as the platform admin.";
      else if (/inactive_caller/.test(raw))  msg = "Your account is inactive.  Contact an admin.";
      if (errEl) {
        errEl.textContent = msg;
        errEl.hidden = false;
      }
      submit.disabled = false;
      if (lbl) lbl.textContent = "Delete forever";
      return;
    }

    // Surface the per-leg cleanup tally so the operator can see what
    // actually got scrubbed.  Keeps the toast short for the happy
    // path; partial failures pass details into a longer toast.
    const summary = resp.data || {};
    const errs = Array.isArray(summary.errors) ? summary.errors : [];
    if (errs.length > 0) {
      console.warn("admin-delete-dsp partial errors:", errs);
      if (typeof toast === "function") {
        toast(`${name} deleted (with ${errs.length} cleanup warning${errs.length === 1 ? "" : "s"} — check console)`, "warn", 6000);
      }
    } else if (typeof toast === "function") {
      const auth = summary.auth_users_deleted ?? 0;
      const storage = summary.storage_objects_deleted ?? 0;
      const tail = (auth || storage)
        ? ` · ${auth} user${auth === 1 ? "" : "s"}, ${storage} file${storage === 1 ? "" : "s"} scrubbed`
        : "";
      toast(`${name} deleted${tail}.`, "ok", 5000);
    }
    if (typeof window.closeModal === "function") window.closeModal("modal-admin-delete-dsp");
    submit.disabled = false;
    if (lbl) lbl.textContent = "Delete forever";
    await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);
  });
}
// Bind once at module init (post-await DOM is parsed; no DCL race).
_bindAdminDeleteDspHandlers();

// ── Onboarding wizard ──────────────────────────────────────────────────────
// Backed by the migration 0126 RPCs:
//   onboarding_get_state()  — read + auto-flip pending → onboarding
//   onboarding_save_step()  — autosave per step (debounced 500ms on field blur)
//   onboarding_complete()   — finalize, flip status → active
//
// State machine in JS mirrors the schema:
//   not_started / company → contact → billing → complete
// Each card stays in the DOM at all times (display:none for inactive
// steps) so autosaved values from prior steps stay rehydrated without
// a re-render.

const _onb = {
  state:    null,            // last-known onboarding_get_state payload
  current:  "company",       // visible step
  saveTimer: null,           // debounce handle
  pendingStep: null,         // step whose payload is queued for autosave
};

async function _mountOnboarding() {
  // Kick off the state fetch + paint the form values when it lands.
  // Every other handler in this section is bound here too.
  await _onbLoadState();
  _onbBindHandlers();
  _onbGoToStep(_onbResumeStep());
}

async function _onbLoadState() {
  const { data, error } = await sb.rpc("onboarding_get_state");
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    console.error("onboarding_get_state failed:", error);
    // Hard-fail: if the wizard can't even read its state, the user
    // can't make progress.  Surface the error in the company step's
    // error banner so they can at least see what's wrong.
    _onbError("company", `Couldn't load onboarding: ${error.message}`);
    return;
  }
  _onb.state = data || {};
  _onbPaintFromState();
  // Capacity for plan readonly + the activation copy.
  const plan = _onb.state.subscription_plan || "starter";
  const planEl = document.getElementById("rr-onb-plan-readonly");
  if (planEl) planEl.textContent = plan.charAt(0).toUpperCase() + plan.slice(1);
}

function _onbResumeStep() {
  // Resume at the FIRST incomplete step.  onboarding_step on the
  // schema means "the step the user has reached"; we want them on
  // that step, not past it.
  const s = _onb.state?.onboarding_step;
  if (s === "contact")  return "contact";
  if (s === "billing")  return "billing";
  return "company";
}

function _onbPaintFromState() {
  const s = _onb.state || {};
  const v = (id, val) => { const el = document.getElementById(id); if (el && val != null) el.value = val; };
  v("rr-onb-name",                s.name);
  v("rr-onb-dba",                 s.dba);
  v("rr-onb-business-address",    s.business_address);
  v("rr-onb-business-phone",      s.business_phone);
  v("rr-onb-support-email",       s.support_email);
  v("rr-onb-timezone",            s.timezone || "America/New_York");
  v("rr-onb-owner-name",          s.owner_name);
  v("rr-onb-owner-phone",         s.owner_phone);
  v("rr-onb-emerg-name",          s.emergency_contact_name);
  v("rr-onb-emerg-phone",         s.emergency_contact_phone);
  const billing = s.billing || {};
  v("rr-onb-cardholder",          billing.cardholder);
  v("rr-onb-billing-email",       billing.billing_email || s.support_email || profile?.email);
  // We never restore the card number — only the last 4 are persisted,
  // and the form should look empty so the user knows the field is
  // editable / placeholder.
}

function _onbGoToStep(step) {
  _onb.current = step;
  // Toggle card visibility.
  ["company","contact","billing"].forEach((s) => {
    const card = document.querySelector(`[data-rr-onb-card="${s}"]`);
    if (card) card.style.display = (s === step) ? "" : "none";
  });
  // Update progress dots.
  const order = ["company","contact","billing"];
  const currentIdx = order.indexOf(step);
  order.forEach((s, i) => {
    const dot = document.querySelector(`[data-rr-onb-step="${s}"]`);
    if (!dot) return;
    dot.classList.remove("done","current");
    if (i < currentIdx) dot.classList.add("done");
    else if (i === currentIdx) dot.classList.add("current");
  });
  // Focus the first input of the visible step.
  setTimeout(() => {
    const el = document.querySelector(`[data-rr-onb-card="${step}"] input, [data-rr-onb-card="${step}"] select`);
    el?.focus();
  }, 60);
}

function _onbBindHandlers() {
  // Autosave on blur for every field within the wizard cards.  Blur
  // (not input) avoids hammering the RPC on every keystroke; the user
  // gets confirmation when they tab away.
  document.querySelectorAll('[data-rr-onb-card] input, [data-rr-onb-card] select').forEach((el) => {
    el.addEventListener("blur", () => _onbAutosave(_onb.current));
    // Also save on change for selects (they don't fire blur reliably
    // on touch devices).
    if (el.tagName === "SELECT") el.addEventListener("change", () => _onbAutosave(_onb.current));
  });

  // Step submit (Continue button).
  document.getElementById("rr-onb-form-company")?.addEventListener("submit", (e) => {
    e.preventDefault();
    _onbSubmitStep("company", "contact");
  });
  document.getElementById("rr-onb-form-contact")?.addEventListener("submit", (e) => {
    e.preventDefault();
    _onbSubmitStep("contact", "billing");
  });
  document.getElementById("rr-onb-form-billing")?.addEventListener("submit", (e) => {
    e.preventDefault();
    _onbActivate();
  });

  // Back buttons.
  document.querySelectorAll("[data-rr-onb-back]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const target = btn.getAttribute("data-rr-onb-back");
      _onbGoToStep(target);
    });
  });

  // Save & sign out · autosave the current step then sign out.
  document.getElementById("rr-onb-signout")?.addEventListener("click", async () => {
    await _onbAutosave(_onb.current);
    try { await sb.auth.signOut(); } catch {}
    location.replace("./login.html?msg=onboarding_paused");
  });

  // Card-number formatter (placeholder UX): collapse to last 4 stored.
  const cardNum = document.getElementById("rr-onb-card-number");
  if (cardNum) {
    cardNum.addEventListener("input", () => {
      // Strip non-digits, group every 4 chars for readability.
      const digits = cardNum.value.replace(/\D/g, "").slice(0, 19);
      cardNum.value = digits.replace(/(.{4})/g, "$1 ").trim();
    });
  }
}

function _onbCollectStepPayload(step) {
  if (step === "company") {
    return {
      name:             _onbVal("rr-onb-name"),
      dba:              _onbVal("rr-onb-dba"),
      business_address: _onbVal("rr-onb-business-address"),
      business_phone:   _onbVal("rr-onb-business-phone"),
      support_email:    _onbVal("rr-onb-support-email"),
      timezone:         _onbVal("rr-onb-timezone"),
    };
  }
  if (step === "contact") {
    return {
      owner_name:              _onbVal("rr-onb-owner-name"),
      owner_phone:             _onbVal("rr-onb-owner-phone"),
      emergency_contact_name:  _onbVal("rr-onb-emerg-name"),
      emergency_contact_phone: _onbVal("rr-onb-emerg-phone"),
    };
  }
  if (step === "billing") {
    const card = (_onbVal("rr-onb-card-number") || "").replace(/\D/g, "");
    return {
      cardholder:    _onbVal("rr-onb-cardholder"),
      card_last4:    card.length >= 4 ? card.slice(-4) : null,
      billing_email: _onbVal("rr-onb-billing-email"),
    };
  }
  return {};
}
function _onbVal(id) {
  const el = document.getElementById(id);
  if (!el) return null;
  const v = (el.value || "").trim();
  return v || null;
}

function _onbSetSaving(step, isSaving) {
  const el = document.querySelector(`[data-rr-onb-card="${step}"] .rr-onb-save-status`);
  if (!el) return;
  el.dataset.rrSaving = isSaving ? "1" : "0";
  el.textContent = isSaving ? "Saving…" : "Saved";
}

function _onbError(step, message) {
  const el = document.getElementById(`rr-onb-error-${step}`);
  if (!el) return;
  if (!message) { el.hidden = true; el.textContent = ""; return; }
  el.textContent = message;
  el.hidden = false;
}

async function _onbAutosave(step) {
  if (!step) return;
  const payload = _onbCollectStepPayload(step);
  _onbSetSaving(step, true);
  const { error } = await sb.rpc("onboarding_save_step", {
    p_step: step,
    p_payload: payload,
  });
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    console.error("onboarding_save_step failed:", error);
    _onbSetSaving(step, false);
    _onbError(step, `Couldn't save: ${error.message}`);
    return;
  }
  _onbSetSaving(step, false);
  _onbError(step, null);
}

async function _onbSubmitStep(step, nextStep) {
  // Light client-side validation so the user gets the same friendly
  // wording the rest of the dashboard uses.
  if (step === "company") {
    if (!_onbVal("rr-onb-name"))                     return _onbError(step, "DSP name is required.");
    if (!_onbVal("rr-onb-business-address"))         return _onbError(step, "Business address is required.");
    const supEmail = _onbVal("rr-onb-support-email");
    if (supEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(supEmail)) {
      return _onbError(step, "Support email looks invalid.");
    }
  } else if (step === "contact") {
    if (!_onbVal("rr-onb-owner-name"))               return _onbError(step, "Owner full name is required.");
    if (!_onbVal("rr-onb-owner-phone"))              return _onbError(step, "Preferred contact number is required.");
  }

  await _onbAutosave(step);
  _onbGoToStep(nextStep);
}

async function _onbActivate() {
  const submit = document.getElementById("rr-onb-activate");
  const lbl    = submit?.querySelector("[data-rr-onb-activate-label]");
  if (submit) submit.disabled = true;
  if (lbl)    lbl.textContent = "Activating…";

  const billingPayload = _onbCollectStepPayload("billing");
  const billingEmail = billingPayload.billing_email;
  if (billingEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(billingEmail)) {
    if (submit) submit.disabled = false;
    if (lbl)    lbl.textContent = "Activate workspace";
    return _onbError("billing", "Billing email looks invalid.");
  }

  const { error } = await sb.rpc("onboarding_complete", { p_payload: billingPayload });
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    if (submit) submit.disabled = false;
    if (lbl)    lbl.textContent = "Activate workspace";
    return _onbError("billing", `Activation failed: ${error.message}`);
  }

  // Show the success state briefly, then reload the dashboard so the
  // boot logic can re-evaluate window.RR.dsp.status (now 'active')
  // and render the regular operator UX.
  ["company","contact","billing"].forEach((s) => {
    const c = document.querySelector(`[data-rr-onb-card="${s}"]`); if (c) c.style.display = "none";
  });
  const success = document.getElementById("rr-onb-success");
  if (success) success.style.display = "";
  setTimeout(() => { location.replace("./index.html?welcome=1"); }, 1400);
}

// ── Add-DSP modal · open / submit ──────────────────────────────────────────
function _openAdminAddDspModal() {
  const form = document.getElementById("rr-admin-add-dsp-form");
  if (form) form.reset();
  const err = document.getElementById("rr-admin-add-dsp-error");
  if (err) { err.hidden = true; err.textContent = ""; err.classList.remove("rr-admin-add-dsp-error--ok"); }
  if (typeof window.openModal === "function") window.openModal("modal-admin-add-dsp");
  setTimeout(() => document.getElementById("rr-add-dsp-name")?.focus(), 60);
}

function _adminAddDspError(message, kind) {
  const el = document.getElementById("rr-admin-add-dsp-error");
  if (!el) return;
  el.textContent = message;
  el.classList.toggle("rr-admin-add-dsp-error--ok", kind === "ok");
  el.hidden = false;
}

// ── Invite User modal ──────────────────────────────────────────────────────
// Calls the invite-team-member edge function with `target_dsp_id` so a
// platform admin can drop a new staff member into ANY DSP at any role
// (the function's own gate enforces that target_dsp_id is honored only
// for platform_admin callers; tenant owners stay scoped to their DSP).
//
// Why an edge function instead of an RPC: sending the magic-link
// invite requires `auth.admin.inviteUserByEmail`, which only works
// with the service-role key — we cannot ship that to the browser.
// The RPC layer can't bridge it either; auth.admin is intentionally
// not exposed via PostgREST.

function _openAdminInviteUser() {
  const form = document.getElementById("rr-admin-invite-form");
  if (form) form.reset();
  const err = document.getElementById("rr-admin-invite-error");
  if (err) { err.hidden = true; err.textContent = ""; err.classList.remove("rr-admin-add-dsp-error--ok"); }

  // Populate the target DSP dropdown from the in-memory list.  If
  // the admin clicked Invite-User before ever opening the table,
  // _admin.dsps may be empty; fetch lazily then continue.
  const select = document.getElementById("rr-invite-target-dsp");
  const fillOptions = (dsps) => {
    if (!select) return;
    const sorted = (dsps || []).slice().sort((a, b) => (a.name || "").localeCompare(b.name || ""));
    select.innerHTML = `<option value="">Select a DSP…</option>` + sorted.map((d) =>
      `<option value="${escapeHtml(d.id)}">${escapeHtml(d.name)}${d.short_code ? ` · ${escapeHtml(d.short_code)}` : ""}</option>`
    ).join("");
  };
  if (_admin.loaded && _admin.dsps.length) {
    fillOptions(_admin.dsps);
  } else {
    fillOptions([]);
    // Kick off a load and refresh the dropdown when it lands.
    _loadPlatformAdminDsps().then(() => fillOptions(_admin.dsps));
  }

  if (typeof window.openModal === "function") window.openModal("modal-admin-invite-user");
  setTimeout(() => document.getElementById("rr-invite-target-dsp")?.focus(), 60);
}

function _adminInviteError(message) {
  const el = document.getElementById("rr-admin-invite-error");
  if (!el) return;
  el.textContent = message;
  el.classList.remove("rr-admin-add-dsp-error--ok");
  el.hidden = false;
}

async function _submitAdminInviteUser(e) {
  e.preventDefault();
  const form    = e.currentTarget;
  const submit  = document.getElementById("rr-admin-invite-submit");
  const lbl     = submit?.querySelector("[data-rr-invite-label]");
  const errEl   = document.getElementById("rr-admin-invite-error");
  if (errEl) errEl.hidden = true;

  const get = (n) => (form.elements.namedItem(n)?.value || "").trim();
  const target_dsp_id = get("target_dsp_id");
  const email         = get("email").toLowerCase();
  const full_name     = get("full_name");
  const role          = get("role") || "dispatcher";

  if (!target_dsp_id)                                       return _adminInviteError("Pick a target DSP.");
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))            return _adminInviteError("Enter a valid email.");
  if (!["dispatcher", "ops", "owner", "platform_admin"].includes(role)) {
    return _adminInviteError("Pick a valid role.");
  }

  if (submit) submit.disabled = true;
  if (lbl)    lbl.textContent = "Sending…";

  // sb.functions.invoke automatically forwards the user's JWT in the
  // Authorization header, which is what the edge function uses to
  // resolve the caller's app_users row + role.
  const { data, error } = await sb.functions.invoke("invite-team-member", {
    body: { email, full_name, role, target_dsp_id },
  });

  if (submit) submit.disabled = false;
  if (lbl)    lbl.textContent = "Send invite";

  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    // The edge function returns body.error on validation failure;
    // sb.functions.invoke surfaces that in error.context.
    let raw = error.message || "";
    try {
      const ctxBody = await error.context?.json?.();
      if (ctxBody?.error) raw = ctxBody.error;
    } catch { /* fall through with raw */ }
    let friendly = raw;
    if (/already_on_team/.test(raw))            friendly = "That email is already on this DSP's team.";
    else if (/already_in_other_dsp/.test(raw))  friendly = "That email is already attached to another workspace.  Move them out first, then retry.";
    else if (/target_dsp_id_required/.test(raw))friendly = "Pick a target DSP.";
    else if (/target_dsp_not_found/.test(raw))  friendly = "That DSP doesn't exist anymore.";
    else if (/cross_dsp_invite_forbidden/.test(raw)) friendly = "You can only invite into your own DSP.";
    else if (/insufficient_role/.test(raw))     friendly = "You don't have permission to invite users.";
    else if (/inactive_caller/.test(raw))       friendly = "Your account is inactive.  Contact an admin.";
    else if (/invalid_email/.test(raw))         friendly = "Email looks invalid.";
    else if (/invalid_role/.test(raw))          friendly = "That role isn't allowed.";
    else if (/invite_failed/.test(raw))         friendly = raw.replace(/^invite_failed:\s*/, "Invite failed: ");
    return _adminInviteError(friendly);
  }

  // Success copy depends on whether the edge function sent a fresh
  // invite or re-issued a magic link to a returning user.
  const kind = data?.kind || "invited";
  const msg = kind === "resent_magic_link"
    ? `${email} already had an account; sent a fresh sign-in link.`
    : `Invite sent to ${email}.`;
  if (typeof toast === "function") toast(msg, "ok");
  if (typeof window.closeModal === "function") window.closeModal("modal-admin-invite-user");

  // Refresh the table — if the invitee already had an auth account,
  // the upsert path inside the edge function may have placed them
  // in the target DSP's app_users immediately.
  await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);
}

// ── DSP detail / edit modal ────────────────────────────────────────────────
// Single modal for both "View details" and "Edit account" row actions.
// Reads from the in-memory _admin.dsps list (already populated by
// admin_list_dsps), then writes via direct UPDATE on the dsps table —
// the dsps_admin_all RLS policy from migration 0124 authorizes the
// update.  Status / suspend / reactivate stay in the row-actions
// menu so destructive flows are clearly separate from this surface.

function _openAdminEditDspModal(dspId) {
  const dsp = _admin.dsps.find((d) => d.id === dspId);
  if (!dsp) {
    if (typeof toast === "function") toast("Couldn't find that DSP — try refreshing.", "warn");
    return;
  }

  const get = (id) => document.getElementById(id);

  if (get("rr-edit-dsp-title")) get("rr-edit-dsp-title").textContent = `Edit · ${dsp.name || "DSP"}`;
  if (get("rr-edit-dsp-sub"))   get("rr-edit-dsp-sub").textContent   = dsp.short_code || "—";

  // Read-only meta strip · created date / status pill / driver count.
  const meta = get("rr-edit-dsp-meta");
  if (meta) {
    const created = dsp.created_at ? new Date(dsp.created_at).toLocaleDateString() : "—";
    const statusClass =
      dsp.status === "active"    ? "status-pill-success" :
      dsp.status === "pending"   ? "status-pill-pending" :
      dsp.status === "suspended" ? "status-pill-danger"  : "status-pill-neutral";
    const statusLabel =
      dsp.status === "active"    ? "Active" :
      dsp.status === "pending"   ? "Pending" :
      dsp.status === "suspended" ? "Suspended" : (dsp.status || "—");
    meta.innerHTML = `
      <div class="rr-edit-dsp-meta__cell">
        <span class="rr-edit-dsp-meta__label">Created</span>
        <span class="rr-edit-dsp-meta__value">${escapeHtml(created)}</span>
      </div>
      <div class="rr-edit-dsp-meta__cell">
        <span class="rr-edit-dsp-meta__label">Status</span>
        <span class="rr-edit-dsp-meta__value"><span class="status-pill ${statusClass}">${escapeHtml(statusLabel)}</span></span>
      </div>
      <div class="rr-edit-dsp-meta__cell">
        <span class="rr-edit-dsp-meta__label">Drivers</span>
        <span class="rr-edit-dsp-meta__value">${dsp.driver_count ?? 0}</span>
      </div>`;
  }

  // Prefill form fields.
  if (get("rr-edit-dsp-id"))         get("rr-edit-dsp-id").value         = dsp.id;
  if (get("rr-edit-dsp-name"))       get("rr-edit-dsp-name").value       = dsp.name        || "";
  if (get("rr-edit-dsp-short-code")) get("rr-edit-dsp-short-code").value = dsp.short_code  || "";
  if (get("rr-edit-dsp-phone"))      get("rr-edit-dsp-phone").value      = dsp.phone       || "";
  if (get("rr-edit-dsp-address"))    get("rr-edit-dsp-address").value    = dsp.address     || "";
  if (get("rr-edit-dsp-plan"))       get("rr-edit-dsp-plan").value       = dsp.subscription_plan || "starter";
  if (get("rr-edit-dsp-notes"))      get("rr-edit-dsp-notes").value      = dsp.notes       || "";

  const errEl = get("rr-admin-edit-dsp-error");
  if (errEl) { errEl.hidden = true; errEl.textContent = ""; errEl.classList.remove("rr-admin-add-dsp-error--ok"); }

  if (typeof window.openModal === "function") window.openModal("modal-admin-edit-dsp");
  setTimeout(() => get("rr-edit-dsp-name")?.focus(), 60);
}

function _adminEditDspError(message) {
  const el = document.getElementById("rr-admin-edit-dsp-error");
  if (!el) return;
  el.textContent = message;
  el.classList.remove("rr-admin-add-dsp-error--ok");
  el.hidden = false;
}

async function _submitAdminEditDsp(e) {
  e.preventDefault();
  const form = e.currentTarget;
  const submit = document.getElementById("rr-admin-edit-dsp-submit");
  const lbl    = submit?.querySelector("[data-rr-edit-dsp-label]");
  const errEl  = document.getElementById("rr-admin-edit-dsp-error");
  if (errEl) errEl.hidden = true;

  const dspId = document.getElementById("rr-edit-dsp-id")?.value;
  if (!dspId) return _adminEditDspError("Lost track of which DSP to update — close and reopen.");

  const get = (n) => (form.elements.namedItem(n)?.value || "").trim();
  const name              = get("name");
  const phone             = get("phone");
  const address           = get("address");
  const subscription_plan = get("subscription_plan") || "starter";
  const notes             = get("notes");

  if (name.length < 2) return _adminEditDspError("DSP company name is required.");
  if (!["starter", "growth", "enterprise"].includes(subscription_plan)) {
    return _adminEditDspError("Pick a subscription plan.");
  }

  if (submit) submit.disabled = true;
  if (lbl)    lbl.textContent = "Saving…";

  // Direct UPDATE — gated by the dsps_admin_all RLS policy from
  // migration 0124.  A non-platform-admin caller would get 0 rows
  // affected (silent no-op), which is fine because non-admins can't
  // see the modal in the first place.
  const { error } = await sb.from("dsps")
    .update({
      name,
      phone:             phone   || null,
      address:           address || null,
      subscription_plan,
      notes:             notes   || null,
    })
    .eq("id", dspId);

  if (submit) submit.disabled = false;
  if (lbl)    lbl.textContent = "Save changes";

  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    return _adminEditDspError(error.message || "Couldn't save the changes.");
  }

  if (typeof toast === "function") toast(`${name} updated.`, "ok");
  if (typeof window.closeModal === "function") window.closeModal("modal-admin-edit-dsp");
  await _loadPlatformAdminDsps();
}

// Edit-DSP form submit is wired by _bindAdminPageHandlers above
// (single bind point so we don't double-fire on submit).  Removed
// the original DOMContentLoaded wrapper that silently never ran due
// to live.js's top-level await — same root cause as the Add-DSP +
// Invite-user buttons looking dead.

// ── Manage-Users slide-over ────────────────────────────────────────────────
// Right-side drawer that lists every app_users row attached to a DSP
// and lets a platform admin change their role / active flag.  Backed
// by admin_dsp_detail() (read) + admin_set_user_permissions() (write).
//
// Re-renders the entire user list after each successful write so the
// UI never drifts from the DB state — easier to reason about than
// patching individual rows in place.

let _adminUsersCurrentDspId = null;

// ── Admin drawer accessibility ──────────────────────────────────────────
// Shared focus management for the three platform-admin side-drawers
// (Manage users / Access & modules / DSP profile).  On open: remember the
// trigger, move focus into the drawer, and trap Tab within it (aria-modal).
// On close: restore focus to the trigger.  Drawers can stack (profile →
// access), so we keep a small stack of previously-focused elements.
const _rrDrawerFocusStack = [];
function _rrDrawerFocusables(drawer) {
  return Array.from(drawer.querySelectorAll(
    'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])'
  )).filter((el) => el.offsetParent !== null);
}
function _rrTrapDrawer(drawer) {
  if (!drawer) return;
  _rrDrawerFocusStack.push(document.activeElement);
  drawer.setAttribute("aria-modal", "true");
  if (drawer._rrTrapHandler) drawer.removeEventListener("keydown", drawer._rrTrapHandler);
  drawer._rrTrapHandler = (e) => {
    if (e.key !== "Tab") return;
    const f = _rrDrawerFocusables(drawer);
    if (!f.length) return;
    const first = f[0], last = f[f.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  };
  drawer.addEventListener("keydown", drawer._rrTrapHandler);
  // Move focus in once the open transition has begun.
  setTimeout(() => {
    const f = _rrDrawerFocusables(drawer);
    (drawer.querySelector(".rr-drawer-close") || f[0])?.focus();
  }, 40);
}
function _rrReleaseDrawer(drawer) {
  if (!drawer) return;
  if (drawer._rrTrapHandler) { drawer.removeEventListener("keydown", drawer._rrTrapHandler); drawer._rrTrapHandler = null; }
  drawer.removeAttribute("aria-modal");
  const prev = _rrDrawerFocusStack.pop();
  if (prev && typeof prev.focus === "function") setTimeout(() => { try { prev.focus(); } catch (_) {} }, 0);
}
// Screen-reader announcer for admin actions (save / suspend / etc.).
function _rrAdminAnnounce(msg) {
  let el = document.getElementById("rr-admin-a11y-live");
  if (!el) {
    el = document.createElement("div");
    el.id = "rr-admin-a11y-live";
    el.className = "rr-sr-only";
    el.setAttribute("aria-live", "polite");
    el.setAttribute("aria-atomic", "true");
    document.body.appendChild(el);
  }
  el.textContent = "";
  setTimeout(() => { el.textContent = msg; }, 30);
}

function _openAdminManageUsers(dspId) {
  _adminUsersCurrentDspId = dspId;
  const drawer  = document.getElementById("rr-admin-users-drawer");
  const backdrop = document.getElementById("rr-admin-users-backdrop");
  const titleEl = document.getElementById("rr-admin-users-title");
  const subEl   = document.getElementById("rr-admin-users-sub");
  const bodyEl  = document.getElementById("rr-admin-users-body");
  if (!drawer || !backdrop || !bodyEl) return;

  const dsp = _admin.dsps.find((d) => d.id === dspId);
  if (titleEl) titleEl.textContent = `Manage users · ${dsp?.name || "DSP"}`;
  if (subEl)   subEl.textContent   = dsp?.short_code
    ? `${dsp.short_code} · ${dsp?.driver_count ?? 0} driver${dsp?.driver_count === 1 ? "" : "s"}`
    : "—";

  // Skeleton rows while admin_dsp_detail is in flight.
  bodyEl.innerHTML = `
    <div class="rr-admin-users-skel" aria-hidden="true">
      <div></div><div></div><div></div>
    </div>`;

  drawer.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  backdrop.classList.add("open");
  _rrTrapDrawer(drawer);

  _loadAdminManageUsers(dspId);
}

function _closeAdminManageUsers() {
  const drawer   = document.getElementById("rr-admin-users-drawer");
  const backdrop = document.getElementById("rr-admin-users-backdrop");
  if (drawer)   { drawer.classList.remove("open"); drawer.setAttribute("aria-hidden", "true"); _rrReleaseDrawer(drawer); }
  if (backdrop) backdrop.classList.remove("open");
  _adminUsersCurrentDspId = null;
}

// ─── Access & modules drawer ────────────────────────────────────────────
// Turn top-level pages + in-app features on/off for one DSP.  Reads the
// entitlement lists already present on each row (admin_list_dsps returns
// disabled_pages / disabled_features) and writes via
// admin_set_dsp_entitlements().  Catalog lives on window.RR_ENTITLEMENTS
// so these toggles and the runtime gate share one source of truth.
let _adminAccessCurrentDspId = null;

function _openAdminAccessDrawer(dspId) {
  _adminAccessCurrentDspId = dspId;
  const drawer   = document.getElementById("rr-admin-access-drawer");
  const backdrop = document.getElementById("rr-admin-access-backdrop");
  const titleEl  = document.getElementById("rr-admin-access-title");
  const subEl    = document.getElementById("rr-admin-access-sub");
  const bodyEl   = document.getElementById("rr-admin-access-body");
  const footEl   = document.getElementById("rr-admin-access-foot");
  if (!drawer || !backdrop || !bodyEl) return;

  const dsp = _admin.dsps.find((d) => d.id === dspId);
  const cat = window.RR_ENTITLEMENTS || { pages: [], features: [] };
  const disabledPages    = new Set(Array.isArray(dsp?.disabled_pages)    ? dsp.disabled_pages    : []);
  const disabledFeatures = new Set(Array.isArray(dsp?.disabled_features) ? dsp.disabled_features : []);

  if (titleEl) titleEl.textContent = `Access & modules · ${dsp?.name || "DSP"}`;
  if (subEl)   subEl.textContent   = "Turn pages and features on or off for everyone in this DSP.";

  const onCount  = cat.pages.length - disabledPages.size;
  const onCountF = cat.features.length - disabledFeatures.size;

  const row = (kind, item, isOn) => `
    <label class="rr-access-row">
      <span class="rr-access-row__meta">
        <span class="rr-access-row__label">${escapeHtml(item.label)}</span>
        <span class="rr-access-row__desc">${escapeHtml(item.desc || "")}</span>
      </span>
      <span class="rr-admin-toggle">
        <input type="checkbox" data-rr-access-kind="${kind}" data-rr-access-key="${escapeHtml(item.key)}" ${isOn ? "checked" : ""} aria-label="${escapeHtml(item.label)}" />
        <span class="rr-admin-toggle__slider"></span>
      </span>
    </label>`;

  bodyEl.innerHTML = `
    <div class="rr-access-group">
      <div class="rr-access-group__head">
        <span class="rr-admin-users-section-head" style="margin:0">Pages</span>
        <span class="rr-access-group__count" data-rr-access-count="pages">${onCount}/${cat.pages.length} on</span>
      </div>
      <div class="rr-access-list">${cat.pages.map((p) => row("page", p, !disabledPages.has(p.key))).join("")}</div>
    </div>
    <div class="rr-access-group">
      <div class="rr-access-group__head">
        <span class="rr-admin-users-section-head" style="margin:0">Features</span>
        <span class="rr-access-group__count" data-rr-access-count="features">${onCountF}/${cat.features.length} on</span>
      </div>
      <div class="rr-access-list">${cat.features.map((f) => row("feature", f, !disabledFeatures.has(f.key))).join("")}</div>
    </div>
    <p class="rr-access-note">Changes apply to <strong>every user</strong> in this DSP the next time they load the dashboard. Data stays protected by account permissions regardless — this controls what's visible, not who can sign in.</p>`;

  if (footEl) footEl.hidden = false;
  _refreshAccessCounts();

  drawer.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  backdrop.classList.add("open");
  _rrTrapDrawer(drawer);
}

function _closeAdminAccessDrawer() {
  const drawer   = document.getElementById("rr-admin-access-drawer");
  const backdrop = document.getElementById("rr-admin-access-backdrop");
  if (drawer)   { drawer.classList.remove("open"); drawer.setAttribute("aria-hidden", "true"); _rrReleaseDrawer(drawer); }
  if (backdrop) backdrop.classList.remove("open");
  _adminAccessCurrentDspId = null;
}

// Live "N/M on" counter next to each group head as toggles flip.
function _refreshAccessCounts() {
  const body = document.getElementById("rr-admin-access-body");
  if (!body) return;
  ["pages", "features"].forEach((group) => {
    const kind = group === "pages" ? "page" : "feature";
    const boxes = body.querySelectorAll(`[data-rr-access-kind="${kind}"]`);
    const on = Array.from(boxes).filter((b) => b.checked).length;
    const el = body.querySelector(`[data-rr-access-count="${group}"]`);
    if (el) el.textContent = `${on}/${boxes.length} on`;
  });
}

async function _saveAdminAccess() {
  const dspId = _adminAccessCurrentDspId;
  const body  = document.getElementById("rr-admin-access-body");
  const saveBtn = document.getElementById("rr-admin-access-save");
  if (!dspId || !body) return;

  // Collect the OFF keys (opt-out model) from unchecked toggles.
  const disabledPages = Array.from(body.querySelectorAll('[data-rr-access-kind="page"]'))
    .filter((b) => !b.checked).map((b) => b.getAttribute("data-rr-access-key"));
  const disabledFeatures = Array.from(body.querySelectorAll('[data-rr-access-kind="feature"]'))
    .filter((b) => !b.checked).map((b) => b.getAttribute("data-rr-access-key"));

  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = "Saving…"; }
  const { error } = await sb.rpc("admin_set_dsp_entitlements", {
    p_dsp_id:            dspId,
    p_disabled_pages:    disabledPages,
    p_disabled_features: disabledFeatures,
  });
  if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = "Save changes"; }
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    toast(`Couldn't save access: ${error.message}`, "warn");
    return;
  }
  // Reflect locally so the table + a re-open of the drawer are correct
  // without a full reload.
  const dsp = _admin.dsps.find((d) => d.id === dspId);
  if (dsp) { dsp.disabled_pages = disabledPages; dsp.disabled_features = disabledFeatures; }
  toast("Access updated.", "ok");
  _rrAdminAnnounce(`Access saved for ${dsp?.name || "DSP"}.`);
  _renderPlatformAdminTable();
  _closeAdminAccessDrawer();
}

// Delegated handlers: toggle counters, save, close.
(function bindAdminAccessHandlers() {
  document.addEventListener("change", (e) => {
    if (e.target && e.target.getAttribute && e.target.getAttribute("data-rr-access-kind")) {
      _refreshAccessCounts();
    }
  });
  document.addEventListener("click", (e) => {
    if (e.target.closest("#rr-admin-access-save")) { _saveAdminAccess(); return; }
    if (e.target.closest("[data-rr-admin-access-close]")) _closeAdminAccessDrawer();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      const drawer = document.getElementById("rr-admin-access-drawer");
      if (drawer && drawer.classList.contains("open")) _closeAdminAccessDrawer();
    }
  });
})();

// ─── DSP profile drawer ─────────────────────────────────────────────────
// Drill-down for one DSP: usage stats, entitlement summary, recent
// support + errors, and quick actions.  Backed by admin_dsp_detail()
// (extended in migration 0443).
let _adminProfileCurrentDspId = null;

function _openAdminDspProfile(dspId) {
  _adminProfileCurrentDspId = dspId;
  const drawer   = document.getElementById("rr-admin-profile-drawer");
  const backdrop = document.getElementById("rr-admin-profile-backdrop");
  const titleEl  = document.getElementById("rr-admin-profile-title");
  const subEl    = document.getElementById("rr-admin-profile-sub");
  const bodyEl   = document.getElementById("rr-admin-profile-body");
  if (!drawer || !backdrop || !bodyEl) return;

  const dsp = _admin.dsps.find((d) => d.id === dspId);
  if (titleEl) titleEl.textContent = dsp?.name || "DSP profile";
  if (subEl)   subEl.textContent   = dsp?.short_code ? `${dsp.short_code} · loading…` : "loading…";
  bodyEl.innerHTML = `<div class="rr-admin-users-skel" aria-hidden="true"><div></div><div></div><div></div></div>`;

  drawer.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  backdrop.classList.add("open");
  _rrTrapDrawer(drawer);

  _loadAdminDspProfile(dspId);
}

function _closeAdminDspProfile() {
  const drawer   = document.getElementById("rr-admin-profile-drawer");
  const backdrop = document.getElementById("rr-admin-profile-backdrop");
  if (drawer)   { drawer.classList.remove("open"); drawer.setAttribute("aria-hidden", "true"); _rrReleaseDrawer(drawer); }
  if (backdrop) backdrop.classList.remove("open");
  _adminProfileCurrentDspId = null;
}

async function _loadAdminDspProfile(dspId) {
  const bodyEl = document.getElementById("rr-admin-profile-body");
  const subEl  = document.getElementById("rr-admin-profile-sub");
  if (!bodyEl) return;

  const { data, error } = await sb.rpc("admin_dsp_detail", { p_dsp_id: dspId });
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    bodyEl.innerHTML = `<div class="rr-admin-users-empty" style="color:var(--red);border-color:var(--red-soft)">Couldn't load profile: ${escapeHtml(error.message)}</div>`;
    return;
  }
  if (!data || !data.dsp) {
    bodyEl.innerHTML = `<div class="rr-admin-users-empty">DSP not found.</div>`;
    return;
  }
  _renderAdminDspProfile(dspId, data, subEl);
}

function _renderAdminDspProfile(dspId, detail, subEl) {
  const bodyEl = document.getElementById("rr-admin-profile-body");
  if (!bodyEl) return;
  const dsp = detail.dsp || {};
  // Prefer the live table row for owner/last-active/status (it carries the
  // rolled-up fields admin_list_dsps computes); fall back to the detail row.
  const row = _admin.dsps.find((d) => d.id === dspId) || {};

  const status = dsp.status || row.status || "active";
  const statusClass =
    status === "active"    ? "status-pill-success" :
    status === "pending"   ? "status-pill-pending" :
    status === "suspended" ? "status-pill-danger"  : "status-pill-neutral";
  const statusLabel = status.charAt(0).toUpperCase() + status.slice(1);
  const plan = dsp.subscription_plan || row.subscription_plan || "starter";
  const planClass = plan === "enterprise"
    ? "rr-admin-cell-plan rr-admin-cell-plan--enterprise"
    : plan === "growth" ? "rr-admin-cell-plan rr-admin-cell-plan--growth" : "rr-admin-cell-plan";

  const signals = _adminRowSignals(row.id ? row : { ...dsp, error_count_7d: detail.error_count_7d, last_active_at: detail.last_seen_at, owner_email: row.owner_email });
  const health = status === "suspended" ? "red" : (signals.length ? "amber" : "green");

  const users = Array.isArray(detail.users) ? detail.users : [];
  const activeUsers = users.filter((u) => u.active).length;
  const errors7d = detail.error_count_7d ?? 0;
  const routeCount = detail.route_count ?? 0;
  const lastSeen = detail.last_seen_at || row.last_active_at;

  if (subEl) subEl.textContent = dsp.short_code ? `${dsp.short_code} · member since ${_adminFmtDate(dsp.created_at)}` : `member since ${_adminFmtDate(dsp.created_at)}`;

  // Stat tiles.
  const tile = (label, value, tone) =>
    `<div class="rr-prof-tile${tone ? ` rr-prof-tile--${tone}` : ""}"><div class="rr-prof-tile__value">${value}</div><div class="rr-prof-tile__label">${escapeHtml(label)}</div></div>`;
  const tiles = [
    tile("Drivers", detail.driver_count ?? 0),
    tile("Active users", activeUsers),
    tile("Routes · this wk", routeCount),
    tile("Errors · 7d", errors7d, errors7d >= 10 ? "danger" : errors7d >= 3 ? "warn" : ""),
    tile("Last active", `<span style="font-size:var(--fs-md)">${escapeHtml(_adminFmtRelative(lastSeen))}</span>`),
    tile("Plan", `<span class="${planClass}" style="font-size:var(--fs-xs)">${escapeHtml(plan)}</span>`),
  ].join("");

  // Entitlements summary.
  const cat = window.RR_ENTITLEMENTS || { pages: [], features: [] };
  const md = dsp.metadata || {};
  const dPages = new Set(Array.isArray(md.disabled_pages) ? md.disabled_pages : []);
  const dFeat  = new Set(Array.isArray(md.disabled_features) ? md.disabled_features : []);
  const offList = (items, set) => items.filter((i) => set.has(i.key)).map((i) => escapeHtml(i.label));
  const offPages = offList(cat.pages, dPages);
  const offFeat  = offList(cat.features, dFeat);
  const entLine = (label, total, offNames) => {
    const on = total - offNames.length;
    return `<div class="rr-prof-ent-row">
        <span class="rr-prof-ent-row__label">${label}</span>
        <span class="rr-prof-ent-row__val">${on}/${total} on${offNames.length ? ` <span class="rr-admin-cell-muted">· off: ${offNames.join(", ")}</span>` : ""}</span>
      </div>`;
  };

  // Support summary.
  const sup = detail.support || null;
  const supHtml = sup && sup.last_message_at
    ? `<div class="rr-prof-support">
         <div class="rr-prof-support__head">
           ${sup.unread > 0 ? `<span class="rr-cc-badge" style="background:var(--amber-soft-strong);color:var(--amber)">${sup.unread} unread</span>` : `<span class="rr-admin-cell-muted">No unread</span>`}
           <span class="rr-admin-cell-muted">${escapeHtml(_adminFmtRelative(sup.last_message_at))}</span>
         </div>
         <div class="rr-prof-support__msg">${escapeHtml((sup.last_message || "").slice(0, 160) || "—")}</div>
         <button class="btn btn-ghost btn-sm" type="button" data-rr-prof-support>Open support thread →</button>
       </div>`
    : `<div class="rr-admin-users-empty" style="padding:var(--s-4)">No support conversation yet.</div>`;

  // Recent errors.
  const recent = Array.isArray(detail.recent_errors) ? detail.recent_errors : [];
  const errHtml = recent.length
    ? `<div class="rr-prof-errs">${recent.map((e) => `
        <div class="rr-prof-err">
          <div class="rr-prof-err__top"><span class="rr-prof-err__page">${escapeHtml(e.page || e.source || "—")}</span><span class="rr-admin-cell-muted">${escapeHtml(_adminFmtRelative(e.created_at))}</span></div>
          <div class="rr-prof-err__msg">${escapeHtml((e.message || "").slice(0, 180))}</div>
        </div>`).join("")}</div>`
    : `<div class="rr-admin-users-empty" style="padding:var(--s-4)">No client errors recorded. 🎉</div>`;

  const suspendBtn = status === "suspended"
    ? `<button class="btn btn-ghost btn-sm" type="button" data-rr-prof-action="reactivate">Reactivate</button>`
    : `<button class="btn btn-ghost btn-sm" type="button" data-rr-prof-action="suspend" style="color:var(--red)">Suspend</button>`;

  bodyEl.innerHTML = `
    <div class="rr-prof-hero">
      <span class="rr-admin-health rr-admin-health--${health}" style="width:10px;height:10px"></span>
      <span class="status-pill ${statusClass}">${escapeHtml(statusLabel)}</span>
      ${dsp.phone ? `<span class="rr-admin-cell-muted" style="font-size:var(--fs-sm)">${escapeHtml(dsp.phone)}</span>` : ""}
      ${row.owner_email ? `<a href="mailto:${escapeHtml(row.owner_email)}" style="font-size:var(--fs-sm);color:var(--accent-text);text-decoration:none;margin-left:auto">${escapeHtml(row.owner_email)}</a>` : ""}
    </div>

    <div class="rr-prof-tiles">${tiles}</div>

    <div class="rr-prof-actions">
      <button class="btn btn-sm" type="button" data-rr-prof-action="edit">Edit account</button>
      <button class="btn btn-sm" type="button" data-rr-prof-action="users">Manage users</button>
      <button class="btn btn-sm" type="button" data-rr-prof-action="access">Access &amp; modules</button>
      ${suspendBtn}
    </div>

    <div class="rr-prof-section">
      <div class="rr-prof-section__head">Modules</div>
      ${entLine("Pages", cat.pages.length, offPages)}
      ${entLine("Features", cat.features.length, offFeat)}
    </div>

    <div class="rr-prof-section">
      <div class="rr-prof-section__head">Support</div>
      ${supHtml}
    </div>

    <div class="rr-prof-section">
      <div class="rr-prof-section__head">Recent errors ${errors7d > 0 ? `<span class="rr-admin-cell-muted" style="font-weight:500">· ${errors7d} in 7d</span>` : ""}</div>
      ${errHtml}
    </div>`;
}

// Delegated handlers for the profile drawer (close, quick actions).
(function bindAdminProfileHandlers() {
  document.addEventListener("click", (e) => {
    if (e.target.closest("[data-rr-admin-profile-close]")) { _closeAdminDspProfile(); return; }
    const actBtn = e.target.closest("[data-rr-prof-action]");
    if (actBtn) {
      const id = _adminProfileCurrentDspId;
      if (!id) return;
      const action = actBtn.getAttribute("data-rr-prof-action");
      if (action === "edit")   { _closeAdminDspProfile(); _openAdminEditDspModal(id); return; }
      if (action === "users")  { _openAdminManageUsers(id); return; }
      if (action === "access") { _openAdminAccessDrawer(id); return; }
      if (action === "suspend" || action === "reactivate") {
        _closeAdminDspProfile();
        _runAdminAction(action, id);
        return;
      }
    }
    if (e.target.closest("[data-rr-prof-support]")) {
      // Jump to the support inbox section + open this DSP's thread.
      const id = _adminProfileCurrentDspId;
      _closeAdminDspProfile();
      const section = document.getElementById("rr-supadm-section");
      section?.scrollIntoView({ behavior: "smooth", block: "start" });
      if (id && typeof _supAdmOpen === "function") {
        try { _supAdmOpen(id); } catch (_) {}
      }
      return;
    }
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      const drawer = document.getElementById("rr-admin-profile-drawer");
      if (drawer && drawer.classList.contains("open")) _closeAdminDspProfile();
    }
  });
})();

function _adminFmtDate(iso) {
  if (!iso) return "—";
  try { return new Date(iso).toLocaleDateString(undefined, { month: "short", year: "numeric" }); }
  catch (_) { return "—"; }
}

async function _loadAdminManageUsers(dspId) {
  const bodyEl = document.getElementById("rr-admin-users-body");
  if (!bodyEl) return;

  const { data, error } = await sb.rpc("admin_dsp_detail", { p_dsp_id: dspId });
  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    bodyEl.innerHTML = `<div class="rr-admin-users-empty" style="color:var(--red);border-color:var(--red-soft)">Couldn't load users: ${escapeHtml(error.message)}</div>`;
    return;
  }
  const users = (data && data.users) || [];

  if (users.length === 0) {
    bodyEl.innerHTML = `<div class="rr-admin-users-empty">No users in this DSP yet.</div>`;
    return;
  }

  // Group: active first (sorted by role rank desc, then name), then
  // inactive at the bottom so the admin can see everyone in one
  // glance without losing the "who's currently in the DSP" signal.
  const ROLE_RANK = { platform_admin: 4, owner: 3, ops: 2, dispatcher: 1, driver: 0 };
  const sortByRoleThenName = (a, b) => {
    const r = (ROLE_RANK[b.role] ?? -1) - (ROLE_RANK[a.role] ?? -1);
    return r !== 0 ? r : (a.full_name || a.email || "").localeCompare(b.full_name || b.email || "");
  };
  const active   = users.filter((u) => u.active).sort(sortByRoleThenName);
  const inactive = users.filter((u) => !u.active).sort(sortByRoleThenName);

  let html = "";
  if (active.length) {
    html += `<div class="rr-admin-users-section-head">Active · ${active.length}</div>`;
    html += `<div class="rr-admin-users-list">${active.map(_renderAdminUserRow).join("")}</div>`;
  }
  if (inactive.length) {
    html += `<div class="rr-admin-users-section-head">Inactive · ${inactive.length}</div>`;
    html += `<div class="rr-admin-users-list">${inactive.map(_renderAdminUserRow).join("")}</div>`;
  }
  bodyEl.innerHTML = html;
}

function _renderAdminUserRow(u) {
  const initials = (u.full_name || u.email || "?")
    .split(/\s+/).filter(Boolean).slice(0, 2)
    .map((w) => (w[0] || "").toUpperCase()).join("") || "?";
  const roleOptions = [
    ["driver",         "Driver"],
    ["dispatcher",     "Dispatcher"],
    ["ops",            "Ops"],
    ["owner",          "Owner"],
    ["platform_admin", "Platform admin"],
  ].map(([v, label]) => `<option value="${v}"${v === u.role ? " selected" : ""}>${label}</option>`).join("");
  return `
    <div class="rr-admin-user-row" data-rr-admin-user-id="${escapeHtml(u.id)}" data-rr-inactive="${u.active ? "0" : "1"}">
      <div class="rr-admin-user-row__avatar">${escapeHtml(initials)}</div>
      <div style="min-width:0">
        <div class="rr-admin-user-row__name">${escapeHtml(u.full_name || "—")}</div>
        <div class="rr-admin-user-row__email">${escapeHtml(u.email || "—")}</div>
      </div>
      <div class="rr-admin-user-row__actions">
        <select class="rr-admin-user-row__role" data-rr-admin-user-role="${escapeHtml(u.id)}" data-rr-role="${escapeHtml(u.role)}" aria-label="Role">
          ${roleOptions}
        </select>
        <label class="rr-admin-toggle" title="${u.active ? "Active" : "Inactive"}">
          <input type="checkbox" data-rr-admin-user-active="${escapeHtml(u.id)}" ${u.active ? "checked" : ""} aria-label="Active" />
          <span class="rr-admin-toggle__slider"></span>
        </label>
      </div>
    </div>`;
}

// Bind role-change + active-toggle handlers via delegation so they
// survive every re-render of the user list.
(function bindAdminManageUsersHandlers() {
  document.addEventListener("change", async (e) => {
    const t = e.target;
    if (!t) return;

    // Role change.
    const roleId = t.getAttribute && t.getAttribute("data-rr-admin-user-role");
    if (roleId) {
      const newRole = t.value;
      t.disabled = true;
      const { error } = await sb.rpc("admin_set_user_permissions", {
        p_user_id: roleId,
        p_role:    newRole,
        p_allowed_pages: null,
        p_active:        null,
      });
      t.disabled = false;
      if (error) {
        if (_isAuthError(error)) _forceRelogin("session_expired");
        toast(`Role change failed: ${error.message}`, "warn");
        return;
      }
      toast(`Role updated.`, "ok");
      // Re-load both the panel (to reflect grouping/sort changes) and
      // the table (in case role flipped someone in/out of the owner
      // column).
      if (_adminUsersCurrentDspId) await _loadAdminManageUsers(_adminUsersCurrentDspId);
      await _loadPlatformAdminDsps();
      return;
    }

    // Active toggle.
    const activeId = t.getAttribute && t.getAttribute("data-rr-admin-user-active");
    if (activeId) {
      const newActive = !!t.checked;
      t.disabled = true;
      const { error } = await sb.rpc("admin_set_user_permissions", {
        p_user_id: activeId,
        p_role:           null,
        p_allowed_pages:  null,
        p_active:         newActive,
      });
      t.disabled = false;
      if (error) {
        if (_isAuthError(error)) _forceRelogin("session_expired");
        // Roll the toggle back on failure so the UI doesn't lie.
        t.checked = !newActive;
        toast(`Couldn't update: ${error.message}`, "warn");
        return;
      }
      toast(newActive ? "User reactivated." : "User deactivated.", "ok");
      if (_adminUsersCurrentDspId) await _loadAdminManageUsers(_adminUsersCurrentDspId);
      return;
    }
  });

  // Close the slide-over via backdrop / X button / Escape.
  document.addEventListener("click", (e) => {
    if (e.target.closest("[data-rr-admin-users-close]")) _closeAdminManageUsers();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      const drawer = document.getElementById("rr-admin-users-drawer");
      if (drawer && drawer.classList.contains("open")) _closeAdminManageUsers();
    }
  });
})();

async function _submitAdminAddDsp(e) {
  e.preventDefault();
  const form = e.currentTarget;
  const submit = document.getElementById("rr-admin-add-dsp-submit");
  const lbl = submit?.querySelector("[data-rr-add-dsp-label]");
  const errEl = document.getElementById("rr-admin-add-dsp-error");
  if (errEl) errEl.hidden = true;

  // Collect + trim form values.  short_code is no longer collected
  // from the form — the server (admin_create_dsp / dsp_unique_short_
  // code) generates a unique workspace identifier from the name so
  // the operator never has to think about collisions.
  const get = (n) => (form.elements.namedItem(n)?.value || "").trim();
  const name        = get("name");
  const owner_email = get("owner_email").toLowerCase();
  const owner_name  = get("owner_name");
  const phone       = get("phone");
  const address     = get("address");
  const subscription_plan = get("subscription_plan") || "starter";
  const notes       = get("notes");

  // Client-side validation matches the migration's CHECK constraints
  // and the email-format expectation. Surfaces friendly inline errors
  // before we burn an RPC round-trip on a known-bad payload.
  if (name.length < 2)                               return _adminAddDspError("DSP company name is required.");
  if (owner_name.length < 2)                         return _adminAddDspError("Owner name is required.");
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(owner_email)) return _adminAddDspError("Owner email looks invalid.");
  if (!["starter", "growth", "enterprise"].includes(subscription_plan)) {
    return _adminAddDspError("Pick a subscription plan.");
  }

  // Lock the form while the RPC runs so a double-click can't
  // accidentally provision two DSPs with the same intent.
  if (submit) submit.disabled = true;
  if (lbl)    lbl.textContent = "Creating…";

  const { data, error } = await sb.rpc("admin_create_dsp", {
    p_name:               name,
    p_owner_email:        owner_email,
    p_owner_name:         owner_name,
    p_phone:              phone || null,
    p_address:            address || null,
    p_subscription_plan:  subscription_plan,
    p_notes:              notes || null,
  });

  if (submit) submit.disabled = false;
  if (lbl)    lbl.textContent = "Create account";

  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    // Friendlier wording for the predictable failure modes.  The
    // server now auto-generates a unique short_code, so a UNIQUE
    // collision would only come from a duplicate name + race; treat
    // it as a generic conflict.
    let msg = error.message || "Couldn't create the DSP.";
    if (/duplicate key|unique/i.test(msg))      msg = `That DSP already exists.`;
    else if (/forbidden/i.test(msg))            msg = "You don't have admin access. Sign in as the platform admin.";
    return _adminAddDspError(msg);
  }

  // The RPC returns the new DSP's id; without it we can't fire the
  // owner invite.  This SHOULD never happen given the RPC's contract,
  // but guard against a NULL return rather than crashing the next call.
  const newDspId = data;
  if (!newDspId) {
    if (typeof toast === "function") toast(`${name} created, but couldn't read its id back. Invite the owner manually from "Invite user".`, "warn");
    if (typeof window.closeModal === "function") window.closeModal("modal-admin-add-dsp");
    await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);
    return;
  }

  // Fire the owner invite via the same edge function the standalone
  // Invite-user modal uses.  We treat invite failure as non-fatal —
  // the DSP is created and the platform admin can re-invite from
  // the row actions menu / Invite-user modal.  Surface it clearly so
  // the operator knows to follow up.
  if (lbl) lbl.textContent = "Sending invite…";
  const { data: invData, error: invError } = await sb.functions.invoke("invite-team-member", {
    body: {
      email:         owner_email,
      full_name:     owner_name,
      role:          "owner",
      target_dsp_id: newDspId,
    },
  });

  if (typeof window.closeModal === "function") window.closeModal("modal-admin-add-dsp");
  await Promise.all([_loadPlatformAdminStats(), _loadPlatformAdminDsps()]);

  if (invError) {
    let raw = invError.message || "";
    try {
      const ctxBody = await invError.context?.json?.();
      if (ctxBody?.error) raw = ctxBody.error;
    } catch { /* fall through */ }
    if (typeof toast === "function") {
      toast(`${name} created — but the owner invite failed (${raw}). Use "Invite user" to resend.`, "warn", 9000);
    }
    return;
  }

  // Edge function distinguishes a fresh invite from a re-issued
  // magic link (returning user).  Both are success paths from the
  // operator's perspective, but the wording matters.
  const kind = invData?.kind || "invited";
  const successMsg = kind === "resent_magic_link"
    ? `${name} created. ${owner_email} already had an account — sent a fresh sign-in link.`
    : `${name} created. Invite sent to ${owner_email}.`;
  if (typeof toast === "function") toast(successMsg, "ok", 6000);
}


// ─── Bulk-import drivers · CSV paste flow ─────────────────────────────────
// UI lives at #modal-bulk-drivers (Drivers view → "Bulk import" button).
// Parses pasted CSV, shows a live preview, then calls the
// bulk_create_drivers RPC (migration 0130) which validates server-side
// and returns per-row results.
//
// CSV parser is hand-rolled (RFC-4180-ish) so we don't pull in a
// dependency for ~30 lines of logic.  Handles quoted fields with
// embedded commas + escaped quotes.

function _bulkDriversParseCsv(text) {
  // Split into rows respecting quoted newlines.  Tab-separated paste
  // (from Google Sheets / Excel) also works — we treat \t and , as
  // delimiters interchangeably.
  const rows = [];
  let cur = [];
  let field = "";
  let inQuotes = false;
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += ch; i++; continue;
    }
    if (ch === '"') { inQuotes = true; i++; continue; }
    if (ch === "," || ch === "\t") { cur.push(field); field = ""; i++; continue; }
    if (ch === "\r") { i++; continue; }
    if (ch === "\n") { cur.push(field); rows.push(cur); cur = []; field = ""; i++; continue; }
    field += ch; i++;
  }
  if (field !== "" || cur.length) { cur.push(field); rows.push(cur); }
  return rows.map((r) => r.map((c) => c.trim())).filter((r) => r.some((c) => c !== ""));
}

function _bulkDriversNormalize(rows) {
  // Detect header row.  Match any of: first_name, firstname, first
  // name, fname; same families for last, phone, email.  Letters
  // case-insensitive.
  const headerKey = (s) => (s || "").toLowerCase().replace(/[^a-z]/g, "");
  const looksLikeHeader = (r) =>
    r.some((c) => /^(first|last|phone|email)/i.test(c)) ||
    r.some((c) => ["firstname","lastname","phonenumber","emailaddress"].includes(headerKey(c)));

  let headers = ["first_name", "last_name", "phone", "email"];
  let dataRows = rows;
  if (rows.length && looksLikeHeader(rows[0])) {
    headers = rows[0].map((c) => {
      const k = headerKey(c);
      if (k.startsWith("first") || k === "fname")  return "first_name";
      if (k.startsWith("last")  || k === "lname" || k === "surname") return "last_name";
      if (k.startsWith("phone") || k === "tel" || k === "mobile" || k === "cell") return "phone";
      if (k.startsWith("email") || k === "mail")   return "email";
      return c.toLowerCase();
    });
    dataRows = rows.slice(1);
  }
  return dataRows.map((r) => {
    const obj = {};
    headers.forEach((h, idx) => { obj[h] = r[idx] || ""; });
    return {
      first_name: (obj.first_name || "").trim(),
      last_name:  (obj.last_name  || "").trim(),
      phone:      (obj.phone      || "").trim(),
      email:      (obj.email      || "").trim(),
    };
  });
}

function _bulkDriversValidate(rows) {
  const issues = [];
  rows.forEach((r, idx) => {
    if (!r.first_name) issues.push({ row: idx + 1, msg: "missing first name" });
    if (!r.last_name)  issues.push({ row: idx + 1, msg: "missing last name" });
    if (r.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email)) {
      issues.push({ row: idx + 1, msg: `invalid email "${r.email}"` });
    }
  });
  return issues;
}

function _renderBulkDriversPreview() {
  const txt = document.getElementById("rr-bulk-drivers-csv")?.value || "";
  const wrap = document.getElementById("rr-bulk-drivers-preview-wrap");
  const body = document.getElementById("rr-bulk-drivers-preview-body");
  const cnt  = document.getElementById("rr-bulk-drivers-preview-count");
  const sufx = document.getElementById("rr-bulk-drivers-preview-s");
  const warn = document.getElementById("rr-bulk-drivers-warnings");
  const sub  = document.getElementById("rr-bulk-drivers-submit");
  const errEl = document.getElementById("rr-bulk-drivers-error");

  if (!txt.trim()) {
    if (wrap) wrap.hidden = true;
    if (sub)  sub.disabled = true;
    if (errEl) errEl.hidden = true;
    return;
  }

  let parsed, normalized, issues;
  try {
    parsed = _bulkDriversParseCsv(txt);
    normalized = _bulkDriversNormalize(parsed);
    issues = _bulkDriversValidate(normalized);
  } catch (e) {
    if (errEl) { errEl.textContent = `Parse error: ${e.message}`; errEl.hidden = false; }
    if (sub)  sub.disabled = true;
    return;
  }

  if (errEl) errEl.hidden = true;
  if (wrap)  wrap.hidden = false;
  if (cnt)   cnt.textContent = normalized.length;
  if (sufx)  sufx.textContent = normalized.length === 1 ? "" : "s";

  // Render preview rows · max 50 to keep DOM light, with a "+N more" line
  if (body) {
    const head = normalized.slice(0, 50);
    body.innerHTML = head.map((r, i) => {
      const rowIssues = issues.filter((x) => x.row === i + 1).map((x) => x.msg).join("; ");
      const dot = rowIssues
        ? `<span title="${escapeHtml(rowIssues)}" style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--amber)"></span>`
        : `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green-bright)"></span>`;
      return `<tr>
        <td>${dot}</td>
        <td>${escapeHtml(r.first_name)}</td>
        <td>${escapeHtml(r.last_name)}</td>
        <td>${phoneCell(r.phone)}</td>
        <td>${escapeHtml(r.email)}</td>
      </tr>`;
    }).join("") + (normalized.length > 50
      ? `<tr><td colspan="5" style="text-align:center;color:var(--text-subtle);font-style:italic">+ ${normalized.length - 50} more rows (will all be imported)</td></tr>`
      : "");
  }

  if (warn) {
    warn.textContent = issues.length
      ? `${issues.length} row${issues.length === 1 ? " has" : "s have"} issues — hover the amber dot for details.  Bad rows are skipped on import.`
      : "All rows look good.";
  }

  if (sub) sub.disabled = normalized.length === 0;
}

async function _submitBulkDrivers() {
  const txt = document.getElementById("rr-bulk-drivers-csv")?.value || "";
  const sub = document.getElementById("rr-bulk-drivers-submit");
  const lbl = sub?.querySelector("[data-rr-bulk-drivers-label]");
  const errEl = document.getElementById("rr-bulk-drivers-error");
  const resEl = document.getElementById("rr-bulk-drivers-result");
  if (errEl) errEl.hidden = true;
  if (resEl) resEl.hidden = true;

  let normalized;
  try {
    normalized = _bulkDriversNormalize(_bulkDriversParseCsv(txt));
  } catch (e) {
    if (errEl) { errEl.textContent = `Parse error: ${e.message}`; errEl.hidden = false; }
    return;
  }
  if (normalized.length === 0) {
    if (errEl) { errEl.textContent = "No rows to import."; errEl.hidden = false; }
    return;
  }

  if (sub) sub.disabled = true;
  if (lbl) lbl.textContent = `Importing ${normalized.length}…`;

  const { data, error } = await sb.rpc("bulk_create_drivers", { p_rows: normalized });

  if (sub) sub.disabled = false;
  if (lbl) lbl.textContent = "Import";

  if (error) {
    if (_isAuthError(error)) _forceRelogin("session_expired");
    let msg = error.message || "Couldn't import drivers.";
    if (/forbidden/i.test(msg)) msg = "You don't have permission to add drivers (need dispatcher or higher).";
    if (errEl) { errEl.textContent = msg; errEl.hidden = false; }
    return;
  }

  const summary = data || {};
  const inserted = summary.inserted ?? 0;
  const skipped  = summary.skipped  ?? 0;
  const errored  = summary.errored  ?? 0;
  const rows     = Array.isArray(summary.rows) ? summary.rows : [];

  if (resEl) {
    const failedRows = rows.filter((r) => !r.ok);
    resEl.innerHTML = `
      <div style="background:${inserted > 0 ? "var(--green-soft)" : "var(--canvas)"};border:1px solid ${inserted > 0 ? "rgba(22,163,74,.20)" : "var(--border)"};border-radius:var(--r-md);padding:var(--s-3) var(--s-4);font-size:var(--fs-sm);line-height:1.5">
        <div style="font-weight:700;color:${inserted > 0 ? "var(--green-dark)" : "var(--text)"};margin-bottom:6px">Import complete</div>
        <div class="u-muted">
          ✅ ${inserted} created
          ${skipped > 0 ? `· ⏭️ ${skipped} skipped (duplicate email)` : ""}
          ${errored > 0 ? `· ⚠️ ${errored} errored` : ""}
        </div>
        ${failedRows.length > 0 ? `
          <details class="u-mt-2">
            <summary style="cursor:pointer;font-weight:600;color:var(--text-muted)">Show ${failedRows.length} skipped/errored row${failedRows.length === 1 ? "" : "s"}</summary>
            <ul style="margin:6px 0 0 18px;padding:0;color:var(--text-subtle);font-size:var(--fs-xs)">
              ${failedRows.map((r) => {
                const reason = r.reason === "duplicate_email" ? `already exists: ${r.email}`
                  : r.reason === "missing_name"     ? "missing first or last name"
                  : r.reason === "db_error"         ? `DB error: ${r.detail || ""}`
                  : r.reason || "unknown";
                return `<li>Row ${r.index}: ${escapeHtml(reason)}</li>`;
              }).join("")}
            </ul>
          </details>
        ` : ""}
      </div>`;
    resEl.hidden = false;
  }

  if (typeof toast === "function") {
    toast(`Imported ${inserted} driver${inserted === 1 ? "" : "s"}` + (skipped + errored > 0 ? ` (${skipped + errored} skipped/errored — see modal)` : ""), inserted > 0 ? "ok" : "warn");
  }

  // Refresh the roster to show the new drivers.
  if (typeof loadDriversRoster === "function" && inserted > 0) loadDriversRoster();
}

(function bindBulkDriversHandlers() {
  // Defer to the DOM being parsed.  live.js's top-level await makes
  // DOMContentLoaded unreliable here (same gotcha as the admin handlers),
  // so we do an immediate bind + readyState fallback.
  const bind = () => {
    const ta = document.getElementById("rr-bulk-drivers-csv");
    if (ta) ta.addEventListener("input", _renderBulkDriversPreview);
    const sub = document.getElementById("rr-bulk-drivers-submit");
    if (sub) sub.addEventListener("click", _submitBulkDrivers);
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", bind, { once: true });
  } else {
    bind();
  }
})();

// ─── Drivers roster ────────────────────────────────────────────────────────
//
// Replaces the mockup roster rows with live rows from public.drivers.
// Records are minimal today (name, contact, station, hire_date, status)
// so the columns the mockup defined for Score / Attendance / Coach show
// "—" until a future migration fills them in.

// Driver stage state — what the operator has filtered to.
let _driverStage = "active";
// Roster filter / sort state (set by the toolbar dropdowns + search).
let _rosterFilters = { station: "", tenure: "", score: "", risk: "", q: "", sort: "risk-desc" };

// Status-header filter options · the Status column dropdown switches
// _driverStage so the roster can show non-active drivers (On leave /
// Inactive / Terminated). Onboarding is intentionally omitted — that
// stage swaps the table to the milestone columns (and the page surfaces
// onboarding separately), which would hide this very control.
const _RR_ROSTER_STATUS_FILTERS = [
  { stage: "all",          label: "All statuses", dot: null },
  { stage: "active",       label: "Active",       dot: "active" },
  { stage: "seasonal",     label: "Seasonal",     dot: "seasonal" },
  { stage: "onleave",      label: "On leave",     dot: "leave" },
  { stage: "inactiveonly", label: "Inactive",     dot: "inactive" },
  { stage: "terminated",   label: "Terminated",   dot: "terminated" },
];
function _rrRosterStatusFilterLabel() {
  const f = _RR_ROSTER_STATUS_FILTERS.find(o => o.stage === _driverStage);
  return f ? f.label : "Active";
}
// Cached roster rows so filter/sort changes don't refetch.
let _rosterRows = [];

let _rosterAppStatus = new Map();   // driver_id -> { invited, signed_in_at, last_seen_at, has_push }
let _rosterAttPoints = new Map();   // driver_id -> active attendance points within the policy window
let _rosterAttCounts = new Map();   // driver_id -> { worked, eligible, pct } over the recent window
let _rosterRisk = new Map();        // driver_id -> "atrisk" | "watch" (highest active corrective action)
let _rosterAttnCoached = new Set(); // driver_ids with ≥1 active attendance-topic coaching (any level)
let _rosterI9 = new Map();          // driver_id -> i9_list row (status, first_day_of_employment, …)
let _rosterProg = new Map();        // driver_id -> onboarding_progress row
let _rosterState = new Map();        // driver_id -> driver_onboarding_state.steps  ({ step_key: { status, at } })

async function loadDriversRoster() {
  const tbody = document.getElementById("drivers-tbody");
  if (!tbody) return;
  // Paint skeleton rows immediately so the page feels instant.
  tbody.innerHTML = _rosterSkeleton(_driverStage === "onboarding" ? 7 : 10);

  // Recent attendance (worked vs eligible) for the Attendance column and the
  // driver-line %. 30-day rolling window, same worked/eligible model as the
  // driver record (worked = completed+late, eligible = +no_show+called_off).
  const _att30 = new Date(); _att30.setDate(_att30.getDate() - 30);
  const [{ data: rows, error }, { data: appStatus }, { data: coachRows }, { data: i9Rows }, { data: attCountRows }] = await Promise.all([
    sb.from("drivers")
      .select(`id, full_name, first_name, last_name, preferred_name, email, phone, status, hire_date, tier, score, updated_at, metadata,
               background_check_completed_at, drug_test_completed_at,
               training_scheduled_at, training_date, dl_expires_on,
               dot_certified, xl_certified, edv_certified, is_trainer,
               station:station_id (code)`)
      .eq("dsp_id", window.RR.dsp.id)
      .order("hire_date", { ascending: false })
      .limit(500),
    sb.rpc("driver_app_status"),
    sb.from("coachings")
      .select("driver_id, occurred_at, topic, severity, resolved_at")
      .eq("dsp_id", window.RR.dsp.id)
      .is("archived_at", null)
      .order("occurred_at", { ascending: false })
      .limit(2000),
    sb.rpc("i9_list").then((r) => r, () => ({ data: [] })),
    sb.from("shifts").select("driver_id, status")
      .eq("dsp_id", window.RR.dsp.id)
      .in("status", ["completed", "late", "no_show", "called_off"])
      .gte("date", fmtIsoDate(_att30))
      .limit(20000).then((r) => r, () => ({ data: [] })),
  ]);

  _rosterAppStatus = new Map((appStatus ?? []).map((s) => [s.driver_id, s]));
  _rosterI9 = new Map((Array.isArray(i9Rows) ? i9Rows : []).map((r) => [r.driver_id, r]));

  // Aggregate recent attendance per driver → worked / eligible / pct.
  _rosterAttCounts = new Map();
  {
    const agg = new Map();
    for (const sh of (attCountRows || [])) {
      if (!sh.driver_id) continue;
      const a = agg.get(sh.driver_id) || { worked: 0, eligible: 0 };
      if (sh.status === "completed" || sh.status === "late") a.worked++;
      a.eligible++;
      agg.set(sh.driver_id, a);
    }
    for (const [id, a] of agg) {
      a.pct = a.eligible ? Math.round((a.worked / a.eligible) * 100) : null;
      _rosterAttCounts.set(id, a);
    }
  }

  // Active attendance points per driver — same math as the Attendance
  // report: count called_off / no_show / late shifts in the policy decay
  // window, drop operator-excused ones, weight by the policy's per-event
  // points. Best-effort; a fetch failure just leaves the column at 0.
  try {
    const _attEval = (typeof _evalPolicy === "function") ? _evalPolicy() : null;
    // Policy OFF → no points accumulate. Leave the column blank (—).
    if (!_attEval || _attEval.enabled === false) {
      _rosterAttPoints = new Map();
    } else {
    const _ptsCallout = _attEval?.events?.callout ? Number(_attEval.events.callout.points) || 0 : 0;
    const _ptsNoshow  = _attEval?.events?.no_show ? Number(_attEval.events.no_show.points) || 0 : 0;
    const _ptsLate    = _attEval?.events?.late    ? Number(_attEval.events.late.points)    || 0 : 0;
    const _decay = Number(_attEval?.decay_days) || 90;
    const _since = new Date(); _since.setDate(_since.getDate() - _decay);
    const _sinceIso = fmtIsoDate(_since);
    const _todayIso = fmtIsoDate(new Date());
    const [attShiftsRes, attDecisionsRes] = await Promise.all([
      sb.from("shifts").select("id, driver_id, status, date")
        .eq("dsp_id", window.RR.dsp.id)
        .in("status", ["late", "called_off", "no_show"])
        .gte("date", _sinceIso).lte("date", _todayIso),
      sb.from("attendance_decisions").select("shift_id")
        .eq("dsp_id", window.RR.dsp.id).eq("decision", "deny")
        .gte("created_at", _since.toISOString()),
    ]);
    const _excused = new Set((attDecisionsRes?.data || []).map((d) => d.shift_id));
    const _pts = new Map();
    for (const sh of (attShiftsRes?.data || [])) {
      if (!sh.driver_id || _excused.has(sh.id)) continue;
      const w = sh.status === "late" ? _ptsLate
        : sh.status === "called_off" ? _ptsCallout
        : sh.status === "no_show" ? _ptsNoshow : 0;
      if (w) _pts.set(sh.driver_id, (_pts.get(sh.driver_id) || 0) + w);
    }
    _rosterAttPoints = _pts;
    }
  } catch (e) {
    console.warn("attendance points load failed:", e);
    _rosterAttPoints = new Map();
  }

  _rosterLastCoached = new Map();
  _rosterAttnCoached = new Set();
  _rosterRisk = new Map();
  const _RISK_RANK = { atrisk: 2, watch: 1 };
  for (const c of (coachRows ?? [])) {
    if (!_rosterLastCoached.has(c.driver_id)) _rosterLastCoached.set(c.driver_id, c.occurred_at);
    // "On attendance coaching" = has at least one active (non-archived)
    // coaching whose topic is attendance, at any level/severity.
    if (c.topic && /attend/i.test(c.topic)) _rosterAttnCoached.add(c.driver_id);
    // Risk = highest active (unresolved) corrective action. Final/Termination
    // → At Risk; Written → Watch. Verbal/Note don't flag.
    if (!c.resolved_at) {
      const lvl = (c.severity === "final" || c.severity === "termination") ? "atrisk"
                : (c.severity === "written" || c.severity === "warning")    ? "watch"
                : null;
      if (lvl) {
        const cur = _rosterRisk.get(c.driver_id);
        if (!cur || _RISK_RANK[lvl] > _RISK_RANK[cur]) _rosterRisk.set(c.driver_id, lvl);
      }
    }
  }
  _rosterRows = rows ?? [];
  refreshDriverStatRow(_rosterRows);
  _populateRosterStationFilter(_rosterRows);
  renderDriverTable(_rosterRows, error);

  // Page sub-line: a steady descriptive subtitle (matches the Schedule
  // page's header hierarchy). Live counts live in the KPI strip + table.
  const sub = document.getElementById("rr-drivers-page-sub");
  if (sub) {
    sub.textContent = "Manage drivers, attendance, credentials and employment records.";
  }
}

function _rowsForStage(rows, stage) {
  switch (stage) {
    case "onboarding": return rows.filter(r => r.status === "onboarding");
    case "active":     return rows.filter(r => r.status === "active");
    case "seasonal":   return rows.filter(r => r.status === "seasonal");
    // "At risk" = drivers with an open corrective action (the same signal
    // the roster's Risk column shows). drivers.score is not used — nothing
    // computes it.
    case "atrisk":     return rows.filter(r => r.status === "active" && _rosterRisk.get(r.id));
    case "onleave":    return rows.filter(r => r.status === "leave");
    case "inactive":   return rows.filter(r => ["inactive","terminated"].includes(r.status));
    // Granular status filters driven by the Status-header dropdown.
    case "inactiveonly": return rows.filter(r => r.status === "inactive");
    case "terminated":   return rows.filter(r => r.status === "terminated");
    case "all":          return rows;
    default:           return rows;
  }
}
function visibleDriversForStage(rows, stage) {
  return _applyRosterFiltersAndSort(_rowsForStage(rows, stage));
}

function _applyRosterFiltersAndSort(rows) {
  const f = _rosterFilters;
  let out = rows;
  if (f.q) {
    const q = f.q.toLowerCase();
    out = out.filter(r => {
      const hay = [
        r.preferred_name, r.full_name, r.first_name, r.last_name,
        r.email, r.phone, r.station?.code,
      ].filter(Boolean).join(" ").toLowerCase();
      return hay.includes(q);
    });
  }
  if (f.station) out = out.filter(r => (r.station?.code || "") === f.station);
  if (f.tenure) {
    const today = Date.now();
    out = out.filter(r => {
      if (!r.hire_date) return false;
      const days = Math.floor((today - new Date(r.hire_date).getTime()) / 86400000);
      switch (f.tenure) {
        case "0-30":   return days >= 0   && days <= 30;
        case "31-90":  return days >= 31  && days <= 90;
        case "91-365": return days >= 91  && days <= 365;
        case "365+":   return days > 365;
        default:       return true;
      }
    });
  }
  if (f.score) {
    out = out.filter(r => {
      const s = r.score;
      switch (f.score) {
        case "0-69":  return s != null && s < 70;
        case "70-84": return s != null && s >= 70 && s < 85;
        case "85+":   return s != null && s >= 85;
        case "none":  return s == null;
        default:      return true;
      }
    });
  }
  const dispName = (r) => (r.preferred_name?.trim() || r.full_name || "").toLowerCase();
  // Status priority for status-asc sort (active first, terminated last).
  const statusPri = { active: 0, seasonal: 1, onboarding: 2, leave: 3, inactive: 4, terminated: 5 };
  const statusRank = (r) => (statusPri[r.status] ?? 99);
  // Last-active timestamp from the in-memory roster app-session
  // cache. Drivers with no app session sort to the end on asc, to
  // the start on desc — same "no data" behaviour as score sorts.
  const lastActiveMs = (r) => {
    const s = _rosterAppStatus && _rosterAppStatus.get ? _rosterAppStatus.get(r.id) : null;
    const iso = s ? (s.last_seen_at || s.signed_in_at) : null;
    return iso ? new Date(iso).getTime() : null;
  };
  // Risk rank from the map the roster loader fills: At Risk (2) > Watch (1)
  // > none (0). Drives the Risk column sort.
  const riskRank = (r) => { const v = (_rosterRisk && _rosterRisk.get) ? _rosterRisk.get(r.id) : null; return v === "atrisk" ? 2 : v === "watch" ? 1 : 0; };
  // "At risk" view chip → only drivers with an open corrective action
  // (Watch or At Risk), the same signal the Risk column renders.
  if (f.risk === "flagged") out = out.filter(r => riskRank(r) > 0);
  // Attendance points + last-coaching date drive their roster columns' sorts.
  const ptsVal = (r) => (_rosterAttPoints && _rosterAttPoints.get) ? (_rosterAttPoints.get(r.id) || 0) : 0;
  const lastCoachMs = (r) => { const iso = (_rosterLastCoached && _rosterLastCoached.get) ? _rosterLastCoached.get(r.id) : null; return iso ? new Date(iso).getTime() : null; };
  switch (f.sort) {
    case "score-asc":      out = [...out].sort((a, b) => (a.score ?? 999) - (b.score ?? 999)); break;
    case "score-desc":     out = [...out].sort((a, b) => (b.score ?? -1)  - (a.score ?? -1));  break;
    case "risk-desc":      out = [...out].sort((a, b) => riskRank(b) - riskRank(a)); break;
    case "risk-asc":       out = [...out].sort((a, b) => riskRank(a) - riskRank(b)); break;
    case "name":           out = [...out].sort((a, b) => dispName(a).localeCompare(dispName(b))); break;
    case "name-desc":      out = [...out].sort((a, b) => dispName(b).localeCompare(dispName(a))); break;
    case "tenure-desc":    out = [...out].sort((a, b) => new Date(a.hire_date || 0) - new Date(b.hire_date || 0)); break;
    case "tenure-asc":     out = [...out].sort((a, b) => new Date(b.hire_date || 0) - new Date(a.hire_date || 0)); break;
    case "status-asc":     out = [...out].sort((a, b) => statusRank(a) - statusRank(b)); break;
    case "status-desc":    out = [...out].sort((a, b) => statusRank(b) - statusRank(a)); break;
    case "lastactive-desc": out = [...out].sort((a, b) => (lastActiveMs(b) ?? -Infinity) - (lastActiveMs(a) ?? -Infinity)); break;
    case "lastactive-asc":  out = [...out].sort((a, b) => (lastActiveMs(a) ?? Infinity)  - (lastActiveMs(b) ?? Infinity));  break;
    case "points-desc":     out = [...out].sort((a, b) => ptsVal(b) - ptsVal(a)); break;
    case "points-asc":      out = [...out].sort((a, b) => ptsVal(a) - ptsVal(b)); break;
    case "lastcoach-desc":  out = [...out].sort((a, b) => (lastCoachMs(b) ?? -Infinity) - (lastCoachMs(a) ?? -Infinity)); break;
    case "lastcoach-asc":   out = [...out].sort((a, b) => (lastCoachMs(a) ?? Infinity)  - (lastCoachMs(b) ?? Infinity));  break;
  }
  return out;
}

function _populateRosterStationFilter(rows) {
  const sel = document.getElementById("rr-roster-station");
  if (!sel) return;
  const codes = [...new Set(rows.map(r => r.station?.code).filter(Boolean))].sort();
  const cur = sel.value;
  sel.innerHTML = '<option value="">All locations</option>'
    + codes.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join("");
  if (codes.includes(cur)) sel.value = cur;
}

document.addEventListener("change", (e) => {
  const id = e.target?.id;
  if (id === "rr-roster-stage-select") {
    // Toolbar stage dropdown drives the (now-hidden) stage-tab buttons
    // so filterDriversStage() keeps a single source of truth.
    const stage = e.target.value || "active";
    const btn = document.querySelector(`.stage-tabs [data-stage="${stage}"]`);
    if (btn && typeof window.filterDriversStage === "function") window.filterDriversStage(btn);
    return;
  }
  if (id === "rr-roster-station" || id === "rr-roster-tenure"
   || id === "rr-roster-score") {
    _rosterFilters = {
      ..._rosterFilters,
      station: document.getElementById("rr-roster-station")?.value || "",
      tenure:  document.getElementById("rr-roster-tenure")?.value  || "",
      score:   document.getElementById("rr-roster-score")?.value   || "",
    };
    const stSel = document.getElementById("rr-roster-station");
    if (stSel) stSel.classList.toggle("is-set", !!stSel.value);
    renderDriverTable(_rosterRows, null);
  }
});

// Roster search — live filter against name / email / phone / station.
let _rosterSearchT = null;
document.addEventListener("input", (e) => {
  if (e.target?.id !== "rr-roster-search") return;
  const val = e.target.value || "";
  clearTimeout(_rosterSearchT);
  _rosterSearchT = setTimeout(() => {
    _rosterFilters = { ..._rosterFilters, q: val.trim() };
    renderDriverTable(_rosterRows, null);
  }, 120);
});

// Click a sortable column header → toggle direction (or set to that
// column at its default direction).
document.addEventListener("click", (e) => {
  const th = e.target.closest("[data-rr-roster-sort]");
  if (!th) return;
  const col = th.dataset.rrRosterSort;
  const cur = _rosterFilters.sort;
  let next;
  if (col === "name")            next = cur === "name" ? "name-desc" : "name";
  else if (col === "tenure")     next = cur === "tenure-desc" ? "tenure-asc" : "tenure-desc";
  else if (col === "score")      next = cur === "score-asc"   ? "score-desc" : "score-asc";
  else if (col === "risk")       next = cur === "risk-desc" ? "risk-asc" : "risk-desc";
  else if (col === "status")     next = cur === "status-asc"  ? "status-desc": "status-asc";
  else if (col === "lastactive") next = cur === "lastactive-desc" ? "lastactive-asc" : "lastactive-desc";
  else if (col === "points")     next = cur === "points-desc" ? "points-asc" : "points-desc";
  else if (col === "lastcoach")  next = cur === "lastcoach-desc" ? "lastcoach-asc" : "lastcoach-desc";
  if (!next) return;
  _rosterFilters = { ..._rosterFilters, sort: next };
  renderDriverTable(_rosterRows, null);
});

function renderDriverTable(rows, error) {
  const tbody = document.getElementById("drivers-tbody");
  const thead = tbody?.parentElement?.querySelector("thead tr");
  if (!tbody || !thead) return;

  // Sort caret helper — shows the active sort direction next to the
  // matching header. Inactive columns render a faded dual-arrow
  // glyph so the operator can see EVERY header is sortable, not
  // just the one that happens to be active.
  const f = _rosterFilters;
  const caret = (col) => {
    const map = {
      name:       ["name", "name-desc"],
      tenure:     ["tenure-asc", "tenure-desc"],
      score:      ["score-asc", "score-desc"],
      risk:       ["risk-asc", "risk-desc"],
      status:     ["status-asc", "status-desc"],
      lastactive: ["lastactive-asc", "lastactive-desc"],
    };
    const ours = map[col] || [];
    const active = ours.includes(f.sort);
    if (!active) {
      // Faded dual-arrow glyph — signals "click to sort" without
      // claiming a direction.
      return ' <span class="rr-sort-caret rr-sort-caret-idle" aria-hidden="true">⇅</span>';
    }
    const isAsc = f.sort.endsWith("-asc") || f.sort === "name";
    return ` <span class="rr-sort-caret rr-sort-caret-active" aria-hidden="true">${isAsc ? "▲" : "▼"}</span>`;
  };

  // Swap headers per stage.  Onboarding still uses the milestone
  // columns; Active drops the Status column (everyone's "Active" in
  // this stage by definition) and turns the sortable columns into
  // clickable headers (data-rr-roster-sort).
  // The active roster shows each driver's app-view icon in the first column
  // instead of a select checkbox (per operator), so the select-all header only
  // applies to the onboarding stage, whose rows still carry row checkboxes.
  const cbHeader = _driverStage === "onboarding"
    ? `<th class="dr-cb" data-rr-no-drawer><input type="checkbox" class="dr-cb-in" id="rr-roster-cb-all" aria-label="Select all drivers"></th>`
    : `<th class="dr-cb" data-rr-no-drawer></th>`;
  if (_driverStage === "onboarding") {
    thead.innerHTML = cbHeader + `
      <th>Driver</th>
      <th>Days since hire</th>
      <th>Onboarding</th>
      <th>Form I-9</th>
      <th>App</th>
      <th></th>`;
  } else {
    thead.innerHTML = `
      <th class="rr-roster-th-driver"><span class="rr-roster-th-driver-label" data-rr-roster-sort="name" style="cursor:pointer;user-select:none">Driver${caret("name")}</span></th>
      <th class="rr-roster-th-attpoints" data-rr-roster-sort="risk" style="cursor:pointer;user-select:none" title="Drivers on a corrective action: Watch (Written) or At Risk (Final)">Risk${caret("risk")}</th>
      <th class="rr-att-col" title="Recent attendance — worked vs eligible shifts (last 30 days)">Attendance</th>
      <th data-rr-roster-sort="tenure" style="cursor:pointer;user-select:none">Tenure${caret("tenure")}</th>
      <th class="rr-lastcoach-col" data-rr-roster-sort="lastcoach" style="cursor:pointer;user-select:none" title="Most recent coaching of any topic">Last coaching${caret("lastcoach")}</th>
      <th data-rr-roster-sort="lastactive" style="cursor:pointer;user-select:none">Last active${caret("lastactive")}</th>
      <th class="rr-roster-th-app">App</th>
      <th class="rr-roster-th-actions"></th>`;
    thead.dataset.rrColCount = "8";
  }

  // Roster toolbar · search + status filter + Add driver live here, not in the
  // column header. Relocate the search input into the toolbar once (it keeps
  // its listeners when moved), and sync the status-filter label/state. The
  // filter + Add buttons use document-delegated handlers, so they work wherever
  // they're rendered.
  const _rosterToolbar = document.getElementById("rr-roster-toolbar");
  if (_rosterToolbar) {
    const _searchSlot  = _rosterToolbar.querySelector(".rr-roster-toolbar-search");
    const _searchInput = document.getElementById("rr-roster-search");
    const _searchWrap  = _searchInput ? _searchInput.closest(".dr-search") : null;
    // Prefer the top KPI-strip search host (operator: search lives up top with
    // the action pills); fall back to the toolbar slot when the strip host
    // isn't present (e.g. the standalone Drivers view).
    const _searchDest  = document.getElementById("rr-kpi-search-host") || _searchSlot;
    if (_searchDest && _searchWrap && _searchWrap.parentNode !== _searchDest) _searchDest.appendChild(_searchWrap);
    const _filtLabel = _rosterToolbar.querySelector(".rr-roster-status-filter-label");
    if (_filtLabel) _filtLabel.textContent = _rrRosterStatusFilterLabel();
    const _filtBtn = _rosterToolbar.querySelector("[data-rr-roster-status-filter]");
    if (_filtBtn) _filtBtn.classList.toggle("is-set", _driverStage !== "active");
  }

  _obSetStrip(error ? null : rows);

  const colspan = _driverStage === "onboarding" ? 7 : 11;
  if (error) {
    tbody.innerHTML = `<tr><td colspan="${colspan}" style="padding:0">${_rosterEmpty({
      error: true, title: "Couldn't load drivers", body: escapeHtml(error.message),
    })}</td></tr>`;
    _updateRosterHint(0, 0); _rosterBulkRefresh();
    return;
  }

  const stageTotal = _rowsForStage(rows, _driverStage).length;
  let visible = visibleDriversForStage(rows, _driverStage);
  if (_driverStage === "onboarding") {
    visible = visible.slice().sort((a, b) => {
      const wa = _obReadiness(a).weight, wb = _obReadiness(b).weight;
      if (wa !== wb) return wa - wb;
      const da = a.hire_date ? new Date(a.hire_date).getTime() : 0;
      const db = b.hire_date ? new Date(b.hire_date).getTime() : 0;
      return da - db;   // oldest hire first within a bucket
    });
  }
  // Search PROMOTES matches instead of filtering them away: `visible` stays the
  // matched set (and still drives the result hint + CSV export), while
  // `_rosterOthers` is the rest of the roster that passes the OTHER filters.
  // The others render below the matches under an "Other drivers" header, so a
  // search keeps the page full instead of leaving a big empty space.
  let _rosterOthers = [];
  const _q = (_rosterFilters.q || "").trim();
  if (_q) {
    const matchIds = new Set(visible.map((r) => r.id));
    const _savedQ = _rosterFilters.q;
    _rosterFilters.q = "";
    try { _rosterOthers = visibleDriversForStage(rows, _driverStage).filter((r) => !matchIds.has(r.id)); }
    finally { _rosterFilters.q = _savedQ; }
    if (_driverStage === "onboarding") {
      _rosterOthers = _rosterOthers.slice().sort((a, b) => {
        const wa = _obReadiness(a).weight, wb = _obReadiness(b).weight;
        if (wa !== wb) return wa - wb;
        return (a.hire_date ? new Date(a.hire_date).getTime() : 0) - (b.hire_date ? new Date(b.hire_date).getTime() : 0);
      });
    }
  }
  if (visible.length === 0 && _rosterOthers.length === 0) {
    const searching = !!(_rosterFilters.q || _rosterFilters.station || _rosterFilters.tenure || _rosterFilters.score);
    const cfg = searching
      ? { icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>',
          title: "No drivers match", body: "Try a different search term or clear the filters." }
      : _driverStage === "onboarding"
      ? { title: "No one in onboarding", body: "Drivers in onboarding appear here. New hires from Interview Day land here automatically; they can also self-onboard via the PWA." }
      : _driverStage === "active"
      ? { title: "No active drivers yet", body: "Hire someone in Interview Day, or use Add driver / Bulk import to build the roster." }
      : _driverStage === "atrisk"
      ? { title: "No at-risk drivers", body: "Drivers with an open corrective action (Watch or At Risk) surface here so you can intervene early." }
      : _driverStage === "seasonal"
      ? { title: "No seasonal drivers", body: "Drivers set to Seasonal appear here." }
      : _driverStage === "onleave"
      ? { title: "No one on leave", body: "Drivers marked on leave appear here." }
      : _driverStage === "inactiveonly"
      ? { title: "No inactive drivers", body: "Drivers set to Inactive appear here." }
      : _driverStage === "terminated"
      ? { title: "No terminated drivers", body: "Drivers set to Terminated appear here." }
      : { title: "No drivers in this stage", body: "Nothing to show here right now." };
    tbody.innerHTML = `<tr><td colspan="${colspan}" style="padding:0">${_rosterEmpty(cfg)}</td></tr>`;
    _updateRosterHint(0, stageTotal); _rosterBulkRefresh();
    return;
  }

  const renderer = _driverStage === "onboarding" ? renderOnboardingRow : renderDriverRow;
  if (_q && _rosterOthers.length) {
    // Two-group promote view: matches on top, everyone else below — keeps the
    // roster full and makes the search read as a sort, not a hide. Span the
    // ACTUAL column count (not the oversized empty-state colspan) so a header
    // row doesn't invent phantom columns and skew the table layout.
    const cspan = (thead.children && thead.children.length) || colspan;
    const grp = (label, n) => `<tr class="rr-roster-group" data-rr-no-drawer><td colspan="${cspan}"><span class="rr-roster-group-label">${escapeHtml(label)}</span><span class="rr-roster-group-count">${n}</span></td></tr>`;
    let html = "";
    if (visible.length) html += grp(`Matches for “${_q}”`, visible.length) + visible.map(renderer).join("");
    else html += `<tr class="rr-roster-group rr-roster-group--none" data-rr-no-drawer><td colspan="${cspan}">No exact matches for “${escapeHtml(_q)}” — showing the full roster</td></tr>`;
    html += grp("Other drivers", _rosterOthers.length) + _rosterOthers.map(renderer).join("");
    tbody.innerHTML = html;
  } else {
    tbody.innerHTML = visible.map(renderer).join("");
  }
  _updateRosterHint(visible.length, stageTotal); _rosterBulkRefresh();
  _rrMaybeRestoreLastDriver(rows);
  requestAnimationFrame(_rrSizeRosterSplit);
}

// Size the roster split so its cards (the list + the record pane) extend to
// the bottom of the viewport — measure the split's actual top so we don't
// depend on a hand-tuned offset for the chrome height. Each pane scrolls
// internally within this height, so the page itself never scrolls.
//
// The split lives inside `.page`, which carries a bottom padding (--s-8).
// We subtract that real padding (read from the computed style) so the split
// bottom + the page's bottom padding land flush with the viewport edge —
// otherwise the leftover padding overflows the scroll container and the
// whole page creeps a few px. floor() avoids a sub-pixel rounding overshoot.
function _rrSizeRosterSplit() {
  const split = document.getElementById("rr-roster-split");
  if (!split || split.offsetParent === null) return;            // not on a visible roster
  if (window.matchMedia && window.matchMedia("(max-width:1024px)").matches) {
    split.style.maxHeight = "";                                 // mobile stacks + flows
    return;
  }
  const page = split.closest(".page");
  const padBottom = page ? (parseFloat(getComputedStyle(page).paddingBottom) || 0) : 12;
  const top = split.getBoundingClientRect().top;
  const h = Math.max(280, Math.floor(window.innerHeight - top - padBottom));
  split.style.maxHeight = h + "px";
}
window.addEventListener("resize", () => { try { _rrSizeRosterSplit(); } catch (_) {} });

// Restore the last-viewed driver into the persistent record pane (instead of
// the "no driver selected" placeholder) the first time the roster renders
// while visible. Runs at most once per page load so it never fights an
// in-session close.
let _rrLastDriverRestored = false;
function _rrMaybeRestoreLastDriver(rows) {
  // The record card is hidden by default now — it only opens on an explicit
  // row click, so we no longer auto-restore the last-viewed driver.
  return;
  // eslint-disable-next-line no-unreachable
  if (_rrLastDriverRestored) return;
  const mount = document.getElementById("driver-record-mount");
  if (!mount || mount.offsetParent === null) return;          // roster pane not visible yet
  if (mount.classList.contains("is-filled")) { _rrLastDriverRestored = true; return; }
  let lastId = null;
  try { lastId = localStorage.getItem("rr-roster-last-driver"); } catch (_) {}
  if (!lastId) return;
  if (!Array.isArray(rows) || !rows.some((r) => r && r.id === lastId)) return; // not in the current set
  _rrLastDriverRestored = true;
  if (typeof openDriverDrawer === "function") openDriverDrawer(lastId);
}

function _rosterEmpty({ icon, title, body, error }) {
  const ic = error
    ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>'
    : (icon || '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>');
  return `<div class="dr-empty"><div class="ic"${error ? ' style="color:var(--red);background:var(--red-soft);border-color:rgba(220,38,38,.20)"' : ""}>${ic}</div><h3>${escapeHtml(title)}</h3><p>${body}</p></div>`;
}

// Generic card/list skeleton for the Drivers sub-views (Licenses,
// Attendance, Coaching, Availability) — painted before their data lands.
function _drSkelList(n = 6) {
  const row = `<div class="row">
    <div style="flex:1"><div class="bar" style="width:${40 + Math.round(Math.random()*30)}%"></div><div class="bar" style="width:${20 + Math.round(Math.random()*20)}%;margin-top:7px;height:10px"></div></div>
    <div class="bar" style="width:80px;height:11px"></div>
    <div class="bar" style="width:64px;height:22px;border-radius:var(--r-pill)"></div>
  </div>`;
  return `<div class="dr-skel-list">${Array.from({ length: n }, () => row).join("")}</div>`;
}

function _rosterSkeleton(colspan, n = 6) {
  // Layout: [checkbox][driver][...mid...][trailing] = colspan cells.
  const cells = Array.from({ length: Math.max(0, colspan - 3) }, () => `<td><div class="dr-skel-cell" style="width:${50 + Math.round(Math.random()*40)}%"></div></td>`).join("");
  const row = `<tr style="pointer-events:none">
    <td class="dr-cb"></td>
    <td><div class="cell-driver"><div class="dr-skel-avatar"></div><div style="flex:1"><div class="dr-skel-cell" style="width:55%"></div><div class="dr-skel-cell" style="width:38%;margin-top:6px;height:10px"></div></div></div></td>
    ${cells}
    <td></td>
  </tr>`;
  return Array.from({ length: n }, () => row).join("");
}

function _updateRosterHint(shown, total) {
  const el = document.getElementById("rr-roster-bar-hint");
  if (!el) return;
  if (_rosterFilters.q || _rosterFilters.station || _rosterFilters.tenure || _rosterFilters.score) {
    el.textContent = `${shown} of ${total} ${total === 1 ? "driver" : "drivers"}`;
  } else {
    el.textContent = "";
  }
}

function pillCheck(when) {
  if (when) return `<span class="tag" style="background:var(--green-soft);color:var(--green)">Done · ${new Date(when).toLocaleDateString()}</span>`;
  return `<span class="tag" style="background:var(--canvas);color:var(--text-subtle)">Pending</span>`;
}

// ── Roster bulk-select: Send message + Export CSV ──────────────────────
let _rosterBulkWired = false;
function _rosterBulkPicks() {
  return Array.from(document.querySelectorAll('#rr-roster-table-wrap input.dr-cb-in[data-rr-roster-pick]:checked'))
    .map((c) => c.getAttribute("data-rr-roster-pick"));
}
function _rosterBulkRefresh() {
  if (!_rosterBulkWired) _wireRosterBulk();
  const bar = document.getElementById("rr-roster-bulkbar");
  if (!bar) return;
  const picks = _rosterBulkPicks();
  const all   = document.querySelectorAll('#rr-roster-table-wrap input.dr-cb-in[data-rr-roster-pick]');
  const allCb = document.getElementById("rr-roster-cb-all");
  if (picks.length === 0) { bar.hidden = true; if (allCb) { allCb.checked = false; allCb.indeterminate = false; } return; }
  bar.hidden = false;
  const cnt = document.getElementById("rr-roster-bulk-count");
  if (cnt) cnt.textContent = picks.length === 1 ? "1 driver selected" : `${picks.length} drivers selected`;
  if (allCb) { allCb.checked = picks.length === all.length; allCb.indeterminate = picks.length > 0 && picks.length < all.length; }
}
function _wireRosterBulk() {
  if (_rosterBulkWired) return;
  _rosterBulkWired = true;
  const tw = document.getElementById("rr-roster-table-wrap");
  // Delegate checkbox changes on the persistent table wrapper.
  tw?.addEventListener("change", (e) => {
    if (e.target?.id === "rr-roster-cb-all") {
      const on = e.target.checked;
      tw.querySelectorAll('input.dr-cb-in[data-rr-roster-pick]').forEach((c) => { c.checked = on; });
      _rosterBulkRefresh();
      return;
    }
    if (e.target?.matches?.('input.dr-cb-in[data-rr-roster-pick]')) _rosterBulkRefresh();
  });
  document.getElementById("rr-roster-bulk-clear")?.addEventListener("click", () => {
    document.querySelectorAll('#rr-roster-table-wrap input.dr-cb-in[data-rr-roster-pick]').forEach((c) => { c.checked = false; });
    _rosterBulkRefresh();
  });
  // Top-right Export button shares the same handler as the bulk-bar
  // Export — if any rows are picked it exports those, otherwise the
  // currently-visible page.
  document.getElementById("rr-roster-export-btn")?.addEventListener("click", () => {
    document.getElementById("rr-roster-bulk-export")?.click();
  });

  // Filters popover — toggle on button, close on outside / Escape,
  // refresh badge whenever a tenure/score filter changes.
  const filterBtn = document.getElementById("rr-roster-filters-btn");
  const filterPop = document.getElementById("rr-roster-filters-popover");
  const filterBadge = document.getElementById("rr-roster-filters-badge");
  const resetBtn = document.getElementById("rr-roster-filters-reset");
  const refreshFilterBadge = () => {
    if (!filterBadge) return;
    const count = (_rosterFilters.tenure ? 1 : 0) + (_rosterFilters.score ? 1 : 0);
    if (count > 0) { filterBadge.hidden = false; filterBadge.textContent = String(count); }
    else { filterBadge.hidden = true; filterBadge.textContent = ""; }
  };
  if (filterBtn && filterPop) {
    const closeFilterPop = () => {
      filterPop.classList.remove("open");
      filterBtn.setAttribute("aria-expanded", "false");
    };
    filterBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const willOpen = !filterPop.classList.contains("open");
      filterPop.classList.toggle("open", willOpen);
      filterBtn.setAttribute("aria-expanded", willOpen ? "true" : "false");
    });
    filterPop.addEventListener("click", (e) => e.stopPropagation());
    document.addEventListener("click", () => {
      if (filterPop.classList.contains("open")) closeFilterPop();
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && filterPop.classList.contains("open")) closeFilterPop();
    });
    resetBtn?.addEventListener("click", () => {
      const t = document.getElementById("rr-roster-tenure");
      const s = document.getElementById("rr-roster-score");
      if (t) t.value = "";
      if (s) s.value = "";
      _rosterFilters = { ..._rosterFilters, tenure: "", score: "" };
      refreshFilterBadge();
      renderDriverTable(_rosterRows, null);
    });
    document.addEventListener("change", (e) => {
      if (e.target?.id === "rr-roster-tenure" || e.target?.id === "rr-roster-score") {
        refreshFilterBadge();
      }
    });
    refreshFilterBadge();
  }

  // Add driver ▾ — toggle a popover with Add / Bulk import.  Closes
  // on outside click, Escape, or after picking a menu item.
  const addBtn = document.getElementById("rr-roster-add-btn");
  const addMenu = document.getElementById("rr-roster-add-menu");
  if (addBtn && addMenu) {
    const closeAddMenu = () => {
      addMenu.classList.remove("open");
      addBtn.setAttribute("aria-expanded", "false");
    };
    addBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const willOpen = !addMenu.classList.contains("open");
      addMenu.classList.toggle("open", willOpen);
      addBtn.setAttribute("aria-expanded", willOpen ? "true" : "false");
    });
    addMenu.addEventListener("click", (e) => {
      const item = e.target.closest("[data-rr-add-action]");
      if (!item) return;
      const action = item.getAttribute("data-rr-add-action");
      closeAddMenu();
      if (action === "single") openModal("modal-add-driver");
      else if (action === "bulk") openModal("modal-bulk-driver-ingest");
    });
    document.addEventListener("click", (e) => {
      if (!addMenu.classList.contains("open")) return;
      if (e.target.closest("#rr-roster-add-anchor")) return;
      closeAddMenu();
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && addMenu.classList.contains("open")) closeAddMenu();
    });
  }
  document.getElementById("rr-roster-bulk-export")?.addEventListener("click", () => {
    const picks = new Set(_rosterBulkPicks());
    const rows = (picks.size ? _rosterRows.filter((r) => picks.has(r.id)) : visibleDriversForStage(_rosterRows, _driverStage));
    const cols = ["Name","Preferred name","Email","Phone","Station","Status","Hire date","Tenure (days)","Attendance points","Score","On the app","App invited","Last active (UTC)","Driver ID"];
    const cell = (v) => { const s = v == null ? "" : String(v); return /[",\n]/.test(s) ? `"${s.replace(/"/g,'""')}"` : s; };
    const lines = [cols.join(",")];
    for (const r of rows) {
      const app = _rosterAppStatus.get(r.id) || {};
      const days = r.hire_date ? Math.max(0, Math.floor((Date.now() - new Date(r.hire_date).getTime()) / 86400000)) : "";
      lines.push([
        r.full_name || "", r.preferred_name || "", r.email || "", r.phone || "",
        r.station?.code || "", r.status || "",
        r.hire_date ? new Date(r.hire_date).toISOString().slice(0,10) : "",
        days, (_rosterAttPoints.get(r.id) ?? ""), (r.score ?? ""),
        app.signed_in_at ? "yes" : "no", app.invited ? "yes" : "no",
        app.last_seen_at ? new Date(app.last_seen_at).toISOString() : "",
        r.id,
      ].map(cell).join(","));
    }
    const blob = new Blob(["﻿" + lines.join("\r\n")], { type: "text/csv;charset=utf-8" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `drivers-${_driverStage}-${new Date().toISOString().slice(0,10)}.csv`;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    toast(`Exported ${rows.length} ${rows.length === 1 ? "driver" : "drivers"} ✓`, "success");
  });
  document.getElementById("rr-roster-bulk-msg")?.addEventListener("click", async () => {
    const picks = _rosterBulkPicks();
    if (picks.length === 0) { toast("Select at least one driver", "warn"); return; }
    const msg = prompt(`Send a message to ${picks.length} ${picks.length === 1 ? "driver" : "drivers"} (delivered in their RouteReady app):`);
    if (msg === null) return;
    const body = msg.trim();
    if (!body) { toast("Message can't be empty", "warn"); return; }
    const btn = document.getElementById("rr-roster-bulk-msg");
    btn.disabled = true;
    let ok = 0, fail = 0;
    for (let i = 0; i < picks.length; i++) {
      btn.textContent = `Sending ${i + 1}/${picks.length}…`;
      const { error } = await sb.rpc("dispatch_chat_send", { p_driver_id: picks[i], p_body: body });
      if (error) fail++; else ok++;
    }
    btn.disabled = false; btn.textContent = "Send message";
    if (fail === 0) toast(`Message sent to ${ok} ${ok === 1 ? "driver" : "drivers"} ✓`, "success");
    else toast(`Sent to ${ok}, ${fail} failed.`, "warn");
  });
}

// Driver-app presence chip for the roster: On the app / Invited / Not invited.
function _appStatusCell(driverId) {
  const s = _rosterAppStatus.get(driverId);
  if (!s) return `<span class="u-subtle">—</span>`;
  if (s.signed_in_at) {
    const ref = s.last_seen_at || s.signed_in_at;
    const refDate = new Date(ref);
    const diffMs = Date.now() - refDate.getTime();
    let label;
    if (diffMs < 60_000) label = "Just now";
    else if (diffMs < 3_600_000) {
      const m = Math.floor(diffMs / 60_000);
      label = `${m} min ago`;
    } else if (diffMs < 86_400_000) {
      const h = Math.floor(diffMs / 3_600_000);
      label = `${h} hr ago`;
    } else {
      const d = Math.floor(diffMs / 86_400_000);
      label = d === 1 ? "1 day ago" : `${d} days ago`;
    }
    const title = `Signed in ${new Date(s.signed_in_at).toLocaleString()}`
      + (s.last_seen_at ? ` · last active ${new Date(s.last_seen_at).toLocaleString()}` : "");
    return `<span title="${escapeHtml(title)}">${escapeHtml(label)}</span>`;
  }
  if (s.invited) return `<span title="Invite sent — hasn't signed in yet">Invited</span>`;
  return `<span class="u-subtle" title="No app invite sent yet">Not invited</span>`;
}

// ── Onboarding steps — the full ordered checklist for one driver ─────
// Combines public.drivers (status, *_completed_at), public.i9_records
// (Section 2 verified), and public.onboarding_progress (the recorded
// "sent" / handbook / offer / scheduled timestamps) into one ordered
// list. `isGate` marks the five steps that gate "ready to activate".
function _onbSteps(d, prog, i9rec) {
  prog = prog || {};
  const i9 = _i9Derived(i9rec);
  const i9Done = i9.key === "verified" || i9.key === "verified_expiring" || i9.key === "sealing";
  return [
    { key: "welcome",    label: "Welcome email sent",            kind: "event",        progField: "welcome_email_sent_at",   at: prog.welcome_email_sent_at,    done: !!prog.welcome_email_sent_at },
    { key: "bg_sent",    label: "Background-check instructions sent", kind: "event",    progField: "bg_instructions_sent_at", at: prog.bg_instructions_sent_at,  done: !!prog.bg_instructions_sent_at },
    { key: "bg_clear",   label: "Background check cleared",       kind: "driver",       driverField: "background_check_completed_at", at: d.background_check_completed_at, done: !!d.background_check_completed_at, isGate: true },
    { key: "drug_sent",  label: "Drug-testing information sent",  kind: "event",        progField: "drug_info_sent_at",       at: prog.drug_info_sent_at,        done: !!prog.drug_info_sent_at },
    { key: "drug_clear", label: "Drug test cleared",             kind: "driver",       driverField: "drug_test_completed_at", at: d.drug_test_completed_at,      done: !!d.drug_test_completed_at, isGate: true },
    { key: "handbook",   label: "Employment handbook",           kind: "sentcomplete", sentField: "handbook_sent_at", completedField: "handbook_completed_at", sentAt: prog.handbook_sent_at, completedAt: prog.handbook_completed_at, done: !!prog.handbook_completed_at, isGate: true },
    { key: "i9",         label: "Form I-9",                      kind: "i9",           sentField: "i9_sent_at", sentAt: prog.i9_sent_at, completedAt: (i9rec && i9rec.section2_completed_at) || null, done: i9Done, i9: i9, isGate: true },
    { key: "offer",      label: "Job offer",                     kind: "sentcomplete", sentField: "job_offer_sent_at", completedField: "job_offer_completed_at", sentAt: prog.job_offer_sent_at, completedAt: prog.job_offer_completed_at, done: !!prog.job_offer_completed_at, isGate: true },
    { key: "active",     label: "Driver active",                 kind: "status",       done: d.status === "active" },
    { key: "scheduled",  label: "Driver scheduled",              kind: "event",        progField: "scheduled_at",            at: prog.scheduled_at,             done: !!prog.scheduled_at },
  ];
}

// ── Blueprint ↔ underlying-field bridge ───────────────────────────────
// _onbSteps owns the canonical underlying fields; the DSP's blueprint
// (migration 0178) owns which steps are enabled, their order, names, and
// whether each blocks activation. Custom steps the DSP added live in
// public.driver_onboarding_state (migration 0179) — a step_key → {status,at} map.
const _OB_FIXED_TO_BP = {            // _onbSteps key → blueprint key (null = synthetic, always kept)
  welcome: "welcome_email", bg_sent: "bg_instructions", bg_clear: "bg_check",
  drug_sent: "drug_info", drug_clear: "drug_test", handbook: "handbook",
  i9: "i9", offer: "job_offer", scheduled: "scheduled", active: null,
};
const _OB_CANON_KEYS = new Set(["welcome_email","bg_instructions","bg_check","drug_info","drug_test","handbook","i9","job_offer","training","scheduled"]);
const _OB_STATE_LABELS = { not_started: "Not started", in_progress: "In progress", sent: "Sent to the driver", viewed: "Viewed by the driver", awaiting_review: "Awaiting your review", acknowledged: "Acknowledged", signed: "Signed", complete: "Complete", declined: "Declined" };

// _onbSteps, narrowed to the DSP's configured blueprint: canonical steps
// the DSP disabled drop out, the blueprint's `blocking` flag overrides
// `isGate`, an enabled "Training" step is inserted, and custom steps
// (status read from driver_onboarding_state) are appended.
function _onbStepsResolved(d, prog, i9rec, stateOverride) {
  const state = (stateOverride !== undefined) ? (stateOverride || {})
    : ((_rosterState && _rosterState.get(d.id)) || {});
  const bp = (typeof _obSteps === "function") ? _obSteps() : null;
  const base = _onbSteps(d, prog, i9rec);
  if (!Array.isArray(bp) || !bp.length) return base;     // no blueprint loaded — fixed list
  const en = {};                                          // blueprint key → step (enabled only)
  for (const s of bp) if (s && s.enabled && s.key) en[s.key] = s;
  const out = base.filter(s => {
    const bk = _OB_FIXED_TO_BP[s.key];
    return bk == null ? true : !!en[bk];                  // synthetic ("active") always; canonical only if enabled
  }).map(s => {
    const bk = _OB_FIXED_TO_BP[s.key];
    return (bk && en[bk]) ? { ...s, isGate: !!en[bk].blocking, label: en[bk].title || s.label } : s;
  });
  if (en.training && !out.some(s => s.key === "training")) {
    const at = d.training_date || null;
    const tStep = { key: "training", label: en.training.title || "Training", kind: "driver", driverField: "training_date", at, done: !!at, isGate: !!en.training.blocking };
    const i = out.findIndex(s => s.key === "active");
    if (i >= 0) out.splice(i, 0, tStep); else out.push(tStep);
  }
  for (const s of bp) {
    if (!s || !s.enabled || !s.key || _OB_CANON_KEYS.has(s.key)) continue;
    const entry = state[s.key] || null;
    const status = (entry && entry.status) || "not_started";
    out.push({
      key: s.key, label: s.title || "Step", kind: "state", stateStatus: status, stepType: s.type || "task",
      at: (entry && entry.at) || null, done: status === "complete", isGate: !!s.blocking,
      owner: s.owner === "driver" ? "driver" : "dsp",
    });
  }
  return out;
}

// One computed state per onboarding driver — derived from the five
// gates above plus the I-9 deadline state. Drives the readiness pill,
// the segment bar, the queue ordering, and the one-line next step.
function _obReadiness(d, i9recOverride, progOverride, stateOverride) {
  const i9r  = (i9recOverride !== undefined) ? i9recOverride  : (_rosterI9   ? _rosterI9.get(d.id)   : null);
  const prog = (progOverride  !== undefined) ? progOverride   : (_rosterProg ? _rosterProg.get(d.id) : null);
  const steps = _onbStepsResolved(d, prog, i9r, stateOverride);
  const gates = steps.filter(s => s.isGate);
  const doneN = gates.filter(s => s.done).length;
  const totalN = gates.length;
  const pct = totalN ? Math.round((doneN / totalN) * 100) : 0;
  const isActive = d.status === "active";
  const i9cls = _i9Classify(i9r);
  const i9d   = _i9Derived(i9r);
  const hasI9 = steps.some(s => s.key === "i9");          // false if the DSP disabled the I-9 step

  // Driver-level status — calm, but more nuanced than ready / blocked.
  let key, label, tone;
  if (isActive)                                        { key = "active";           label = "Active";               tone = "green"; }
  else if (doneN === totalN)                           { key = "ready";            label = "Ready to activate";    tone = "green"; }
  else if (hasI9 && i9cls.bucket === "needs_correction")        { key = "needs_correction"; label = "Needs correction";     tone = "red"; }
  else if (hasI9 && i9cls.bucket === "s2_overdue")              { key = "compliance_risk";  label = "Compliance risk";      tone = "red"; }
  else if (hasI9 && i9d.key === "verified_expiring" && i9d.daysLeft != null && i9d.daysLeft < 0) { key = "compliance_risk"; label = "Work auth expired"; tone = "red"; }
  else if (hasI9 && i9cls.bucket === "s2_due")                  { key = "due_soon";         label = "Due soon";             tone = "amber"; }
  else if (hasI9 && i9cls.bucket === "s2_needed" && i9cls.note) { key = "due_soon";         label = "Set the first day";    tone = "amber"; }
  else if (hasI9 && i9d.key === "section1_complete")            { key = "awaiting_review";  label = "Awaiting your review"; tone = "blue"; }
  else if (steps.some(s => s.kind === "state" && s.stateStatus === "awaiting_review")) { key = "awaiting_review"; label = "Awaiting your review"; tone = "blue"; }
  else if (doneN === 0)                                { key = "not_started";      label = "Not started";          tone = "slate"; }
  else {
    const pendGate = gates.find(g => !g.done);
    const driverActs = pendGate && (
      pendGate.kind === "sentcomplete" ||
      (pendGate.kind === "state" && pendGate.owner === "driver") ||
      (pendGate.kind === "i9" && ["no_record", "not_started", "section1_in_progress"].includes(i9d.key))
    );
    if (driverActs) { key = "waiting_on_driver"; label = "Waiting on the driver"; tone = "blue"; }
    else            { key = "in_progress";       label = "In progress";           tone = "slate"; }
  }

  // One-line next step.
  let next = "";
  if (key === "active") next = "Active — onboarding complete";
  else if (key === "ready") next = "All gates complete — activate when ready";
  else if (key === "needs_correction") next = "Form I-9 correction unresolved — awaiting the employee";
  else if (key === "compliance_risk" && i9cls.bucket === "s2_overdue") next = "Form I-9 Section 2 overdue — complete it now";
  else if (key === "compliance_risk") next = "Work authorization expired — reverification required";
  else if (key === "due_soon" && i9cls.bucket === "s2_due") next = "Form I-9 Section 2 due soon";
  else if (key === "due_soon") next = "Set the Form I-9 first day to start the clock";
  else if (key === "awaiting_review") {
    if (hasI9 && i9d.key === "section1_complete") next = "Complete Form I-9 Section 2";
    else { const s = steps.find(x => x.kind === "state" && x.stateStatus === "awaiting_review"); next = s ? `Review the submission: ${s.label}` : "Review the pending submission"; }
  }
  else {
    const pend = steps.find(s => !s.done && s.key !== "active" && s.isGate) || steps.find(s => !s.done && s.key !== "active");
    if (pend) {
      if (pend.kind === "i9") {
        const k = i9d.key;
        next = (k === "no_record" || k === "not_started") ? "Form I-9 — awaiting the employee's Section 1"
          : k === "section1_in_progress" ? "Employee is completing Form I-9 Section 1"
          : "Form I-9 in progress";
      } else if (pend.kind === "sentcomplete") next = pend.sentAt ? `${pend.label} — awaiting completion` : `Send the ${pend.label.toLowerCase()}`;
      else if (pend.kind === "driver") next = `Record the ${pend.label.toLowerCase()}`;
      else if (pend.kind === "state") next = pend.stateStatus === "sent" ? `${pend.label} — awaiting the driver` : pend.owner === "driver" ? `Driver to complete: ${pend.label}` : pend.label;
      else next = pend.label;
    }
  }

  // Sort weight — risks first, then quick wins (ready / due soon), then
  // waiting states, then in-progress, not-started, and finally active.
  const weight = (key === "compliance_risk" || key === "needs_correction") ? 0
    : key === "ready"            ? 1
    : key === "due_soon"         ? 2
    : key === "awaiting_review"  ? 3
    : key === "waiting_on_driver"? 4
    : key === "in_progress"      ? 5
    : key === "not_started"      ? 6 : 7;
  return { key, label, tone, doneN, totalN, pct, steps, gates, next, weight };
}
function _obPill(label, tone) {
  const T = tone === "green" ? "background:var(--green-soft);color:var(--green-dark)"
    : tone === "red"   ? "background:var(--red-soft);color:var(--red-dark)"
    : tone === "amber" ? "background:var(--amber-soft);color:var(--amber-dark)"
    : tone === "blue"  ? "background:var(--accent-soft);color:#1E40AF"
    : "background:var(--canvas);color:var(--text-muted)";
  return `<span style="display:inline-flex;align-items:center;font-size:var(--fs-xs);font-weight:700;letter-spacing:.01em;padding:2px 9px;border-radius:var(--r-pill);white-space:nowrap;${T}">${escapeHtml(label)}</span>`;
}
// The "N onboarding · X ready · Y blocked · biggest bottleneck …" strip
// over the roster table — only on the Onboarding stage tab.
function _obSetStrip(rows) {
  const el = document.getElementById("rr-onboarding-strip");
  if (!el) return;
  const list = (_driverStage === "onboarding" && Array.isArray(rows)) ? _rowsForStage(rows, "onboarding") : [];
  if (!list.length) { el.style.display = "none"; el.innerHTML = ""; return; }
  let ready = 0, blocked = 0;
  const stuck = { bg: 0, drug: 0, i9: 0, train: 0 };
  for (const d of list) {
    const ob = _obReadiness(d);
    if (ob.key === "ready") ready++;
    else if (ob.key === "blocked") blocked++;
    for (const m of ob.milestones) if (!m.done) stuck[m.k]++;
  }
  const labels = { bg: "background checks", drug: "drug tests", i9: "Form I-9", train: "training" };
  const slow = Object.entries(stuck).sort((a, b) => b[1] - a[1])[0];
  const slowTxt = slow && slow[1] > 0 ? `${labels[slow[0]]} (${slow[1]} pending)` : null;
  const parts = [`<strong>${list.length}</strong> onboarding`];
  if (ready)   parts.push(`<strong style="color:var(--green)">${ready}</strong> ready to activate`);
  if (blocked) parts.push(`<strong style="color:var(--red)">${blocked}</strong> blocked`);
  el.innerHTML = `<div style="display:flex;align-items:center;gap:var(--s-3-5);flex-wrap:wrap;padding:11px 14px;border:1px solid var(--border);border-radius:var(--r-lg);background:var(--surface);font-size:var(--fs-sm)">
    <span style="display:inline-flex;align-items:center;gap:var(--s-2);flex-wrap:wrap">${parts.join('<span class="u-subtle">·</span>')}</span>
    ${slowTxt ? `<span style="color:var(--text-subtle);font-size:var(--fs-xs);margin-left:auto">Biggest bottleneck: ${escapeHtml(slowTxt)}</span>` : ""}
  </div>`;
  el.style.display = "block";
}

// Refresh whichever onboarding surface is open after a step action.
async function _refreshAfterOnboardingAction(driverId) {
  if (document.getElementById("rr-dd-drawer")) await loadDriverDrawer(driverId);
  if (document.getElementById("view-onboarding-ops")?.classList.contains("active")) loadOnboardingOps();
}

// "Activate driver" inside the driver drawer — flips the status select
// and clicks Save. (The matrix on the Onboarding page has its own
// Active dot wired through the matrix click handler.)
document.addEventListener("click", (e) => {
  if (!e.target.closest("[data-rr-ob-activate]")) return;
  if (!e.target.closest("#rr-dd-drawer")) return;
  e.preventDefault();
  const sel = document.querySelector('#rr-dd-drawer [data-rr-dd-field="status"]');
  if (sel) sel.value = "active";
  document.querySelector("#rr-dd-drawer [data-rr-dd-save]")?.click();
});

// Onboarding step timestamps (welcome email / handbook / offer / scheduled …)
// from inside the driver drawer — kept for the slim Employment summary's
// future use; persists via onboarding_progress_set then refreshes.
document.addEventListener("click", async (e) => {
  const b = e.target.closest("[data-rr-ob-prog]");
  if (!b || !b.closest("#rr-dd-drawer")) return;
  e.preventDefault();
  const driverId = _ddDriver?.driver?.id;
  if (!driverId) return;
  const field = b.getAttribute("data-rr-ob-prog");
  const clear = b.getAttribute("data-rr-ob-act") === "clear";
  const orig = b.textContent; b.disabled = true; b.textContent = "Saving…";
  const { error } = await sb.rpc("onboarding_progress_set", { p_driver_id: driverId, p_field: field, p_value: clear ? null : new Date().toISOString() });
  if (error) { b.disabled = false; b.textContent = orig; toast("Couldn't update: " + (error.message || "error"), "warn"); return; }
  await _refreshAfterOnboardingAction(driverId);
});

// Onboarding matrix — clicking any dot toggles that step for that
// driver. Single-state per dot (empty / done); the cycle of "sent →
// completed → clear" is available in the per-driver detail panel.
document.addEventListener("click", async (e) => {
  const b = e.target.closest("[data-rr-ob-mxdot]");
  if (!b || b.disabled || b.classList.contains("readonly")) return;
  e.preventDefault();
  const id = b.getAttribute("data-driver-id");
  const kind = b.getAttribute("data-kind");
  const field = b.getAttribute("data-field");
  const state = b.getAttribute("data-state");
  const nextStamp = state === "done" ? null : new Date().toISOString();
  const orig = b.disabled;
  b.disabled = true;
  let err = null;
  if (kind === "prog") {
    ({ error: err } = await sb.rpc("onboarding_progress_set", { p_driver_id: id, p_field: field, p_value: nextStamp }));
  } else if (kind === "drv") {
    ({ error: err } = await sb.from("drivers").update({ [field]: nextStamp }).eq("id", id));
  } else if (kind === "state") {
    ({ error: err } = await sb.rpc("driver_onboarding_step_set", { p_driver_id: id, p_step_key: field, p_status: state === "done" ? "not_started" : "complete" }));
  } else if (kind === "status") {
    const nextStatus = state === "done" ? "onboarding" : "active";
    if (nextStatus === "active") {
      // Activation is now gated on a materialized training pairing
      // (Day 1+2 training shifts + Day 3 ride-along). The RPC inserts
      // those shifts, texts both drivers, and only then flips status.
      // Falls back to a direct update if no pairing exists yet — keeps
      // legacy drivers without a pairing row from getting stuck.
      const { data: pair } = await sb.rpc("training_pairing_for", { p_trainee_id: id });
      if (pair && pair.id) {
        ({ error: err } = await sb.rpc("activate_driver_with_pairing", { p_driver_id: id }));
        if (err && /no active training pairing/i.test(err.message || "")) {
          // Pairing was cleared in another tab — fall through to direct update.
          ({ error: err } = await sb.from("drivers").update({ status: nextStatus }).eq("id", id));
        }
      } else {
        ({ error: err } = await sb.from("drivers").update({ status: nextStatus }).eq("id", id));
      }
    } else {
      ({ error: err } = await sb.from("drivers").update({ status: nextStatus }).eq("id", id));
    }
  }
  if (err) { b.disabled = orig; toast("Couldn't update: " + (err.message || ""), "warn"); return; }
  await loadOnboardingOps();
});

