  // delegated) with a message I haven't seen. (0435)
  const udot = document.getElementById("rr-nt-task-udot");
  if (udot) { const anyUnread = server && all.some(_rrTaskUnread); udot.hidden = !anyUnread; }
  if (!list) return;
