      const nDeleg = all.filter((t) => !t.done && _rrTaskIsDelegated(t)).length;
      const bMine = views.querySelector('[data-rr-task-view="mine"]');
      const bDeleg = views.querySelector('[data-rr-task-view="delegated"]');
