      if (bDeleg) { bDeleg.classList.toggle("on", _rrTasksView === "delegated"); bDeleg.setAttribute("aria-selected", _rrTasksView === "delegated" ? "true" : "false"); const c = bDeleg.querySelector("b"); if (c) c.textContent = String(nDeleg); }
