// ─── Dashboard · Today's tasks (Attendance card + header counts) ───────

async function loadDashboardTasks() {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;
  const todayIso = fmtIsoDate(new Date());
  const weekStart = fmtIsoDate(startOfWeekMonday(new Date()));
  const weekEnd   = fmtIsoDate(addDays(new Date(weekStart + "T12:00:00"), 6));

  // Date eyebrow
  const eyebrow = document.getElementById("db-eyebrow");
  if (eyebrow) eyebrow.textContent = new Date().toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric" });

  // Today's shifts: total, present (completed), pending (scheduled), and stations.
  const [shiftsRes, stationsRes, recentAbsentRes] = await Promise.all([
    sb.from("shifts")
      .select("id, status, driver_id, station_id, starts_at, ends_at")
      .eq("dsp_id", dspId)
      .eq("date", todayIso),
    sb.from("stations").select("code, active").eq("dsp_id", dspId).eq("active", true),
    // 30-day absences for the "callout patterns" pill.
    sb.from("shifts")
      .select("driver_id, status")
      .eq("dsp_id", dspId)
      .in("status", ["called_off", "no_show"])
      .gte("date", fmtIsoDate(addDays(new Date(), -30)))
      .lte("date", todayIso),
  ]);

  const shifts = shiftsRes.data || [];
  const stations = stationsRes.data || [];

  const total       = shifts.length;
  const checkedIn   = shifts.filter(sh => sh.status === "completed" || sh.status === "late").length;
  const callouts    = shifts.filter(sh => sh.status === "called_off" || sh.status === "no_show").length;
  const coverageNeeded = shifts.filter(sh => sh.status !== "called_off" && sh.status !== "no_show").length;
  const coveragePct = total === 0 ? 0 : Math.round(checkedIn / Math.max(1, coverageNeeded) * 100);

  const setText = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  setText("dash-pip-checkin", checkedIn);
  setText("dash-pip-total", total);
  setText("dash-coverage", total === 0 ? "—" : `${coveragePct}%`);

  // Loadout = earliest scheduled start time today; stations comma-list.
  const earliest = shifts
    .filter(sh => sh.starts_at)
    .map(sh => new Date(sh.starts_at))
    .sort((a, b) => a - b)[0];
  const loadoutLabel = earliest
    ? `Loadout ${earliest.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })}`
    : "No shifts today";
  const stationLabel = stations.length > 0 ? ` · ${stations.map(s => s.code).join(", ")}` : "";
  setText("dash-pip-meta", `${loadoutLabel}${stationLabel}`);

  // "Callout patterns" — drivers with 3+ callouts/no-shows in last 30 days.
  const absencesPerDriver = new Map();
  for (const sh of (recentAbsentRes.data || [])) {
    if (!sh.driver_id) continue;
    absencesPerDriver.set(sh.driver_id, (absencesPerDriver.get(sh.driver_id) || 0) + 1);
  }
  const flagged = Array.from(absencesPerDriver.values()).filter(n => n >= 3).length;
  const flagEl = document.getElementById("dash-pip-flag");
  const flagTextEl = document.getElementById("dash-pip-flag-text");
  if (flagEl && flagTextEl) {
    if (flagged > 0) {
      flagEl.style.display = "";
      flagTextEl.textContent = `${flagged} callout pattern${flagged === 1 ? "" : "s"} flagged`;
    } else {
      flagEl.style.display = "none";
    }
  }
}

async function loadCheckinView() {
  const list = document.querySelector("#view-checkin .checkin-list");
  if (!list) return;
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;
  const todayIso = fmtIsoDate(new Date());
  // Look 7 days ahead. If today has no assigned shifts, fall back to the
  // next day that does — operator on a Sunday wants to see Monday's roster
  // without manually navigating.
  const horizonIso = fmtIsoDate(addDays(new Date(), 7));

  const shiftQuery = (cols) => sb.from("shifts")
    .select(cols)
    .eq("dsp_id", dspId)
    .gte("date", todayIso)
    .lte("date", horizonIso)
    .not("driver_id", "is", null)
    .order("date", { ascending: true });

  let [driversRes, shiftsRes] = await Promise.all([
    sb.from("drivers")
      .select("id, full_name, first_name, last_name, preferred_name, phone, station:station_id (code), tier")
      .eq("dsp_id", dspId)
      .eq("status", "active"),
    shiftQuery("id, driver_id, status, date, callout_reason"),
  ]);
  // callout_reason ships with migration 0419 — degrade gracefully if the
  // column isn't applied yet so check-in never hard-breaks.
  if (shiftsRes.error) shiftsRes = await shiftQuery("id, driver_id, status, date");

  if (driversRes.error || shiftsRes.error) {
    console.warn("checkin load:", driversRes.error || shiftsRes.error);
    return;
  }
  const drivers = driversRes.data || [];
  const allShifts = shiftsRes.data  || [];

  // Pick target date: today if it has shifts, otherwise earliest day with any.
  const todayShifts = allShifts.filter(sh => sh.date === todayIso);
  const targetIso = todayShifts.length > 0
    ? todayIso
    : (allShifts[0]?.date || todayIso);
  const shifts = allShifts.filter(sh => sh.date === targetIso);

  const driverShift = new Map(); // driver_id -> shift row
  for (const sh of shifts) {
    if (sh.driver_id) driverShift.set(sh.driver_id, sh);
  }

  // Head sub line — note when we're showing a future date.
  const sub = document.querySelector("#view-checkin .page-sub");
  if (sub) {
    const expected = drivers.filter(d => driverShift.has(d.id)).length;
    const targetDate = new Date(targetIso + "T12:00:00");
    const dateLabel = targetDate.toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric" });
    if (targetIso !== todayIso) {
      sub.textContent = `${dateLabel} · ${expected} drivers expected (no shifts scheduled today)`;
    } else {
      sub.textContent = `${dateLabel} · ${expected} drivers expected`;
    }
  }

  const rows = drivers
    .filter(d => driverShift.has(d.id))
    .map(d => {
      const display = displayDriverName(d);
      const initials = displayDriverInitials(d);
      const station = d.station?.code || "—";
      const tier = d.tier ? `tier-${String(d.tier).toLowerCase()}` : "";
      const sh = driverShift.get(d.id);
      const ciKey = _STATUS_TO_CI[sh.status]; // present / late / callout / noshow / undefined
      const markedClass = ciKey ? ` marked marked-${ciKey === "callout" ? "callout" : ciKey === "noshow" ? "noshow" : ciKey}` : "";
      const btn = (key, title, svg) => {
        const active = ciKey === key ? " active" : "";
        return `<button type="button" class="status-btn s-${key}${active}" data-rr-ci-shift="${sh.id}" data-rr-ci-status="${key}" title="${title}">${svg}</button>`;
      };
      // Reason (cause) picker — revealed when the row is marked call-out or
      // no-show. Pre-selects any stored cause. 'weather' feeds the direct
      // weather-attribution signal in the call-out forecast.
      const showReason = ciKey === "callout" || ciKey === "noshow";
      const reasonChips = CALLOUT_REASONS.map(([val, lbl]) =>
        `<button type="button" class="reason-chip${sh.callout_reason === val ? " active" : ""}"
           data-rr-reason-shift="${sh.id}" data-rr-reason="${val}">${escapeHtml(lbl)}</button>`
      ).join("");
      const reasonHtml = `<div class="checkin-reason${showReason ? "" : " hidden"}" data-rr-reason-box="${sh.id}">
          <span class="checkin-reason-label">Reason</span>
          ${reasonChips}
        </div>`;
      return `<div class="checkin-row${markedClass}" data-name="${escapeHtml(initials)}">
        <div class="checkin-driver">
          <div class="avatar-sm ${tier}">${initials}</div>
          <div>
            <div class="checkin-driver-name" data-rr-driver-id="${d.id}">${escapeHtml(display)}</div>
            <div class="checkin-driver-meta">${phoneCell(d.phone || "")}</div>
          </div>
        </div>
        <div class="checkin-station">${escapeHtml(station)}</div>
        <div class="status-row">
          ${btn("present", "Present", '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>')}
          ${btn("late",    "Late",    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>')}
          ${btn("callout", "Callout", '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>')}
          ${btn("noshow",  "No-show", '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/></svg>')}
          ${btn("vto",     "VTO · Voluntary Time Off (operator-granted, no points)", '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="M12 8v4l3 3"/><circle cx="12" cy="12" r="10"/></svg>')}
        </div>
        ${reasonHtml}
      </div>`;
    });

  list.innerHTML = rows.length === 0
    ? `<div class="rr-empty-inline">No shifts scheduled for today.</div>`
    : rows.join("");

  _updateCheckinProgress();
}

function _updateCheckinProgress() {
  const list = document.querySelector("#view-checkin .checkin-list");
  if (!list) return;
  const total = list.querySelectorAll(".checkin-row").length;
  const marked = list.querySelectorAll(".checkin-row.marked").length;
  const pct = total > 0 ? Math.round(marked / total * 100) : 0;
  const fill = document.getElementById("ci-progress");
  if (fill) fill.style.width = `${pct}%`;
  const m = document.getElementById("ci-marked");
  if (m) m.textContent = String(marked);
  const meta = document.querySelector("#view-checkin .checkin-progress-meta span:first-child");
  if (meta) meta.textContent = `${marked} of ${total} marked`;
}

// Click handler: write the status to public.shifts and toggle UI.
document.addEventListener("click", async (e) => {
  const btn = e.target.closest("[data-rr-ci-shift][data-rr-ci-status]");
  if (!btn) return;
  e.preventDefault();
  const shiftId = btn.dataset.rrCiShift;
  const ciKey   = btn.dataset.rrCiStatus;
  const newStatus = _CI_TO_STATUS[ciKey];
  if (!shiftId || !newStatus) return;

  const row = btn.closest(".checkin-row");
  _markLocalShiftMutation();
  const { error } = await sb.from("shifts").update({ status: newStatus }).eq("id", shiftId);
  if (error) { toast("Save failed: " + error.message, "warn"); return; }

  // Visual: clear sibling active states, mark row, add active to clicked.
  if (row) {
    row.classList.remove("marked-present", "marked-late", "marked-callout", "marked-noshow", "marked-vto");
    row.classList.add("marked", `marked-${ciKey === "noshow" ? "noshow" : ciKey === "callout" ? "callout" : ciKey === "vto" ? "vto" : ciKey}`);
    row.querySelectorAll(".status-btn").forEach(b => b.classList.remove("active"));
    btn.classList.add("active");

    // Reveal the cause picker for absences; hide + clear it otherwise.
    const reasonBox = row.querySelector(".checkin-reason");
    if (reasonBox) {
      if (newStatus === "called_off" || newStatus === "no_show") {
        reasonBox.classList.remove("hidden");
      } else {
        reasonBox.classList.add("hidden");
        const hadReason = !!reasonBox.querySelector(".reason-chip.active");
        reasonBox.querySelectorAll(".reason-chip.active").forEach(c => c.classList.remove("active"));
        // Drop any stored cause so a flipped-back shift doesn't keep it.
        if (hadReason) sb.from("shifts").update({ callout_reason: null }).eq("id", shiftId);
      }
    }
  }
  _updateCheckinProgress();
  // Refresh the live Attendance Report (it queries shifts by status) so
  // the tally updates without a full nav. Shifts isn't in the realtime
  // channel, so we trigger the refresh here.
  if (typeof loadAttendanceLive === "function") loadAttendanceLive();
});

// Click handler: capture the cause of an absence on public.shifts.
// Re-clicking the active chip clears it (toggle).
document.addEventListener("click", async (e) => {
  const chip = e.target.closest("[data-rr-reason][data-rr-reason-shift]");
  if (!chip) return;
  e.preventDefault();
  const shiftId = chip.dataset.rrReasonShift;
  if (!shiftId) return;
  const box = chip.closest(".checkin-reason");
  const wasActive = chip.classList.contains("active");
  const value = wasActive ? null : chip.dataset.rrReason;
  _markLocalShiftMutation();
  const { error } = await sb.from("shifts").update({ callout_reason: value }).eq("id", shiftId);
  if (error) { toast("Save failed: " + error.message, "warn"); return; }
  box?.querySelectorAll(".reason-chip").forEach(c => c.classList.remove("active"));
  if (value) chip.classList.add("active");
});


// ─── Drivers · Attendance · Policy + Event log ──────────────────────────

const _ATT_DEFAULT_POLICY = {
  policy_enabled: true,
  decay_days: 90,
  // What counts as one occurrence.  Most DSPs don't count tardies as
  // an "occurrence" but do count callouts and no-shows.
  count_tardy:    false,
  count_callout:  true,
  count_noshow:   true,
  threshold_warn:   3,
  threshold_action: 6,
  // Auto-escalations.  ncns_terminates triggers a Termination
  // recommendation on the very first NCNS, regardless of count.
  ncns_terminates: false,
  // Coaching is a progressive ladder by definition: each qualifying
  // occurrence in the rolling window steps the driver up one rung
  // (Verbal → Written → Final → Termination). No on/off knob.
  // Auto-coaching: master toggle + per-level toggles. When the master
  // is ON and the per-level toggle for the recommended action is also
  // ON, hitting Approve on the daily tool fires the coaching record
  // and posts an in-app message to the driver immediately. Levels
  // not auto-fired drop into the coaching drawer for the leader to
  // finalize. Termination is never auto — a leader always confirms.
  auto_coaching:    false,
  auto_verbal:      false,
  auto_written:     false,
  auto_final:       false,
  // Per-severity delivery requirement — what the driver must do in
  // the RouteReady app to clear an auto-fired coaching of that
  // level.  Surfaces as the default in the manual Send-coaching
  // modal too, so dispatchers don't reset it every time.
  delivery_verbal:      "ack",
  delivery_written:     "ack_and_sign",
  delivery_final:       "ack_and_sign",
  delivery_termination: "ack_and_sign",
  // First-30-days strict rule: any callout/no-show inside the
  // probationary window jumps the driver straight to Action.
  first_30_strict: false,
  first_30_window_days: 30,
};

function _getAttPolicy() {
  const p = window.RR?.dsp?.metadata?.attendance?.policy || {};
  // Translate legacy records (points-mode, the old progressive_coaching
  // toggle, multi-action side effects) into the current shape.  The
  // ladder is now always progressive and "auto-fire on a level"
  // implies a single side effect (in-app driver message).
  const merged = { ..._ATT_DEFAULT_POLICY, ...p };
  delete merged.mode;
  delete merged.points_per_tardy;
  delete merged.points_per_callout;
  delete merged.points_per_noshow;
  delete merged.progressive_coaching;
  delete merged.auto_coaching_actions;
  return merged;
}

// _evalPolicy — walk the blocks-style policy and produce a clean
// normalized object the rest of the dashboard reads from.  Migration
// 0086 backfills `blocks` for every existing tenant; new tenants get
// blocks the first time the policy builder saves.  When `blocks` is
// missing or empty (defensive), we fall back to the legacy fields so
// nothing breaks during the rollout.
//
// Output shape:
//   {
//     enabled: bool,
//     auto_coaching: bool,
//     decay_days: int,
//     events: { callout?: { points }, no_show?: { points }, late?: { points } },
//     ladder: [{ severity, threshold, delivery, auto_fire }, ...],   // sorted by threshold asc
//     ncns_terminates: bool,
//     first_30:        { active: bool, days: int },
//   }
function _evalPolicy() {
  const p   = window.RR?.dsp?.metadata?.attendance?.policy || {};
  const out = {
    enabled:         p.policy_enabled !== false,
    auto_coaching:   !!p.auto_coaching,
    decay_days:      90,
    events:          {},
    ladder:          [],
    ncns_terminates: false,
    first_30:        { active: false, days: 30 },
  };
  const blocks = Array.isArray(p.blocks) ? p.blocks : [];
  if (blocks.length === 0) {
    // Fallback to legacy fields — should only matter on a tenant that
    // somehow missed the 0086 backfill.  The Report still renders.
    const legacy = _getAttPolicy();
    out.decay_days      = legacy.decay_days || 90;
    if (legacy.count_callout) out.events.callout = { points: 1 };
    if (legacy.count_noshow)  out.events.no_show = { points: 1 };
    if (legacy.count_tardy)   out.events.late    = { points: 1 };
    const warn = Math.max(1, legacy.threshold_warn || 1);
    out.ladder = [
      { severity: "verbal",      threshold: warn,     delivery: legacy.delivery_verbal      || "ack",          auto_fire: !!legacy.auto_verbal },
      { severity: "written",     threshold: warn + 1, delivery: legacy.delivery_written     || "ack_and_sign", auto_fire: !!legacy.auto_written },
      { severity: "final",       threshold: warn + 2, delivery: legacy.delivery_final       || "ack_and_sign", auto_fire: !!legacy.auto_final },
      { severity: "termination", threshold: warn + 3, delivery: legacy.delivery_termination || "ack_and_sign", auto_fire: false },
    ];
    out.ncns_terminates = !!legacy.ncns_terminates;
    out.first_30        = { active: !!legacy.first_30_strict, days: legacy.first_30_window_days || 30 };
    return out;
  }
  for (const b of blocks) {
    if (!b || !b.type) continue;
    if (b.type === "window") {
      out.decay_days = Number(b.days) > 0 ? Number(b.days) : 90;
    } else if (b.type === "event") {
      const k = b.kind;
      if (k === "callout" || k === "no_show" || k === "late") {
        out.events[k] = { points: Number(b.points) || 0 };
      }
    } else if (b.type === "ladder_rung") {
      out.ladder.push({
        severity:  b.severity || "verbal",
        threshold: Number(b.threshold) || 0,
        delivery:  b.delivery  || "ack",
        auto_fire: b.severity === "termination" ? false : !!b.auto_fire,
      });
    } else if (b.type === "auto_escalation") {
      if (b.kind === "ncns_terminates")  out.ncns_terminates = true;
      if (b.kind === "first_30_strict")  out.first_30 = { active: true, days: Number(b.days) || 30 };
    }
    // recovery / others: ignored for now (Tier 2 scope)
  }
  // Ladder sorted ascending by threshold so "highest rung whose
  // threshold ≤ points" is just a linear walk.
  out.ladder.sort((a, b) => a.threshold - b.threshold);
  return out;
}

// Find the ladder rung a driver currently sits at, given accumulated
// points.  Returns null when the driver is below the lowest rung
// (Clear) or when the policy has no ladder rungs.
function _evalLadderRung(eval_, points) {
  let rung = null;
  for (const r of (eval_.ladder || [])) {
    if (points >= r.threshold) rung = r;
    else break;
  }
  return rung;
}

// ─── Attendance policy editor · structured form ────────────────────
// Same data model as the previous drag-and-drop builder (blocks
// array on dsps.metadata.attendance.policy), different UX: a normal
// settings page that reads top-to-bottom.  All flexibility preserved
// — variable rung count, custom point values per event, per-rung
// threshold/delivery/auto-fire — without the empty-canvas / drag-
// blocks ceremony.
const _RR_SEVERITY_OPTIONS = [
  { value: "verbal",      label: "Verbal" },
  { value: "written",     label: "Written" },
  { value: "final",       label: "Final" },
  { value: "termination", label: "Termination" },
];
const _RR_DELIVERY_OPTIONS = [
  { value: "none",         label: "Read only · no action required" },
  { value: "ack",          label: "Acknowledge" },
  { value: "sign",         label: "Sign" },
  { value: "ack_and_sign", label: "Acknowledge & sign" },
];

// Working state for the editor (mutated as the operator types).
const _polState = {
  master: { policy_enabled: true, auto_coaching: false },
  window_days: 90,
  events: [
    { kind: "callout", enabled: true,  points: 1 },
    { kind: "no_show", enabled: true,  points: 1 },
    { kind: "late",    enabled: false, points: 0.5 },
  ],
  ladder: [],
  ncns_terminates: false,
  first_30: { active: false, days: 30 },
  timing:   { tardy_grace_minutes: 10, ncns_after_minutes: 60 },
};

function _newRungId() {
  return "rung_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

// Convert dsps.metadata.attendance.policy.blocks into the editor's
// state shape.  Falls back to legacy fields when blocks aren't there.
function _polStateFromMeta(meta) {
  const p = meta?.attendance?.policy || {};
  const blocks = Array.isArray(p.blocks) ? p.blocks : [];

  const out = {
    master: {
      policy_enabled: p.policy_enabled !== false,
      auto_coaching:  !!p.auto_coaching,
    },
    window_days: 90,
    events: [
      { kind: "callout", enabled: false, points: 1 },
      { kind: "no_show", enabled: false, points: 1 },
      { kind: "late",    enabled: false, points: 0.5 },
    ],
    ladder: [],
    ncns_terminates: false,
    first_30: { active: false, days: 30 },
  };

  for (const b of blocks) {
    if (!b || !b.type) continue;
    if (b.type === "window") out.window_days = Number(b.days) || 90;
    else if (b.type === "event") {
      const ev = out.events.find(e => e.kind === b.kind);
      if (ev) { ev.enabled = true; ev.points = Number(b.points) || 0; }
    }
    else if (b.type === "ladder_rung") {
      out.ladder.push({
        id:        _newRungId(),
        severity:  b.severity || "verbal",
        threshold: Number(b.threshold) || 0,
        delivery:  b.delivery  || "ack",
        auto_fire: b.severity === "termination" ? false : !!b.auto_fire,
      });
    }
    else if (b.type === "auto_escalation") {
      if (b.kind === "ncns_terminates") out.ncns_terminates = true;
      if (b.kind === "first_30_strict") out.first_30 = { active: true, days: Number(b.days) || 30 };
    }
  }
  out.ladder.sort((a, b) => a.threshold - b.threshold);
  return out;
}

// Convert editor state back into the blocks array.
function _polStateToBlocks(s) {
  const blocks = [];
  blocks.push({ id: "blk_window_" + Date.now(), type: "window", days: Number(s.window_days) || 90 });
  for (const ev of (s.events || [])) {
    if (!ev.enabled) continue;
    blocks.push({ id: "blk_evt_" + ev.kind, type: "event", kind: ev.kind, points: Number(ev.points) || 0 });
  }
  for (const r of (s.ladder || [])) {
    blocks.push({
      id:        "blk_rung_" + r.id,
      type:      "ladder_rung",
      severity:  r.severity,
      threshold: Number(r.threshold) || 0,
      delivery:  r.delivery,
      auto_fire: r.severity === "termination" ? false : !!r.auto_fire,
    });
  }
  if (s.ncns_terminates) {
    blocks.push({ id: "blk_esc_ncns", type: "auto_escalation", kind: "ncns_terminates" });
  }
  if (s.first_30 && s.first_30.active) {
    blocks.push({ id: "blk_esc_first30", type: "auto_escalation", kind: "first_30_strict", days: Number(s.first_30.days) || 30 });
  }
  return blocks;
}

async function loadAttendancePolicy() {
  const pane = document.getElementById("att-pane-policy");
  if (!pane) return;
  const dspId = window.RR?.dsp?.id;
  // Start from the metadata already in memory (the schedule loads it for
  // the attendance-points column / _evalPolicy), so the editor can ALWAYS
  // render — even if the freshness re-fetch below fails or is blocked.
  // Previously a failed/rejected query returned early and left the
  // popover stuck on the "Loading policy" spinner.
  let meta = window.RR?.dsp?.metadata || {};
  let setRow = null;
  if (dspId) {
    try {
      const [dspRes, setRes] = await Promise.all([
        sb.from("dsps").select("metadata").eq("id", dspId).single(),
        sb.from("scheduling_settings")
          .select("checkin_lead_minutes, tardy_grace_minutes, ncns_after_minutes")
          .eq("dsp_id", dspId).is("week_start", null).maybeSingle(),
      ]);
      if (!dspRes.error && dspRes.data && dspRes.data.metadata) {
        meta = dspRes.data.metadata;
        if (window.RR?.dsp) window.RR.dsp.metadata = meta;
      } else if (dspRes.error) {
        console.warn("policy load (using cached metadata):", dspRes.error.message);
      }
      setRow = setRes.data || null;
    } catch (err) {
      console.warn("policy load (using cached metadata):", err);
    }
  }

  const fromMeta = _polStateFromMeta(meta);
  Object.assign(_polState, fromMeta);
  _polState.timing = {
    tardy_grace_minutes: setRow?.tardy_grace_minutes ?? 10,
    ncns_after_minutes:  setRow?.ncns_after_minutes  ?? 60,
  };

  _renderPolicyEditor();
  _wirePolicyEditor();
}

function _renderPolicyEditor() {
  const pane = document.getElementById("att-pane-policy");
  if (!pane) return;
  const s = _polState;

  const evRow = (kind, label) => {
    const ev = s.events.find(e => e.kind === kind) || { enabled: false, points: 0 };
    return `
      <label class="rr-pol-evrow">
        <input type="checkbox" data-rr-pol-event="${kind}" ${ev.enabled ? "checked" : ""}/>
        <span class="rr-pol-evlabel">${escapeHtml(label)}</span>
        <span class="rr-pol-evpoints">worth
          <input type="number" min="0" max="20" step="0.5" data-rr-pol-event-points="${kind}" value="${Number(ev.points) || 0}" ${ev.enabled ? "" : "disabled"}/>
          point(s) each
        </span>
      </label>`;
  };

  const rungRow = (r, idx) => {
    const sevOpts = _RR_SEVERITY_OPTIONS.map(o => `<option value="${o.value}" ${r.severity === o.value ? "selected" : ""}>${escapeHtml(o.label)}</option>`).join("");
    const delOpts = _RR_DELIVERY_OPTIONS.map(o => `<option value="${o.value}" ${r.delivery === o.value ? "selected" : ""}>${escapeHtml(o.label)}</option>`).join("");
    const autoLocked = r.severity === "termination";
    return `
      <div class="rr-pol-rung" data-rr-pol-rung="${escapeHtml(r.id)}">
        <div class="rr-pol-rung-head">
          <select data-rr-pol-rung-prop="severity">${sevOpts}</select>
          <span class="rr-pol-rung-sep">at</span>
          <input type="number" min="0" step="0.5" data-rr-pol-rung-prop="threshold" value="${Number(r.threshold) || 0}" />
          <span class="rr-pol-rung-sep">pt</span>
          <button type="button" class="rr-pol-rung-remove" data-rr-pol-rung-remove="${escapeHtml(r.id)}" aria-label="Remove level">×</button>
        </div>
        <label class="rr-pol-rung-toggle">
          <input type="checkbox" data-rr-pol-rung-prop="auto_fire" ${r.auto_fire && !autoLocked ? "checked" : ""} ${autoLocked ? "disabled" : ""}/>
          <span>${autoLocked ? "Auto-fire (always manual for Termination)" : "Auto-fire on Approve"}</span>
        </label>
        <label class="rr-pol-rung-delivery">
          <span>Driver must:</span>
          <select data-rr-pol-rung-prop="delivery">${delOpts}</select>
        </label>
      </div>`;
  };

  pane.innerHTML = `
    <div class="pol-section" style="display:flex;align-items:center;gap:var(--s-3-5)">
      <span style="flex:1">
        <h3 class="pol-section-title">Attendance policy</h3>
        <p class="pol-section-sub" style="margin:0">When ON, points accumulate against the rules below and every driver is scored. When OFF, <strong>no points accumulate</strong> — attendance is still logged, but never scored, flagged, or coached.</p>
      </span>
      <label class="toggle">
        <input type="checkbox" id="rr-pol-master-enabled" ${s.master.policy_enabled ? "checked" : ""}/>
        <span class="toggle-slider"></span>
      </label>
    </div>

    <div class="pol-section">
      <h3 class="pol-section-title">Window</h3>
      <p class="pol-section-sub">How far back the Report and the ladder look for events.</p>
      <label class="rr-pol-row">
        <span>Track events from the last</span>
        <input type="number" min="1" max="365" step="1" id="rr-pol-window" value="${Number(s.window_days) || 90}"/>
        <span>days</span>
      </label>
    </div>

    <div class="pol-section">
      <h3 class="pol-section-title">What I count</h3>
      <p class="pol-section-sub">Pick which events accumulate points toward the ladder, and how much each is worth.</p>
      ${evRow("callout", "Callout")}
      ${evRow("no_show", "No-show")}
      ${evRow("late",    "Late")}
    </div>

    <div class="pol-section">
      <div style="display:flex;align-items:center;gap:var(--s-3-5);margin-bottom:10px">
        <span style="flex:1">
          <h3 class="pol-section-title" style="margin:0">Coaching ladder</h3>
          <p class="pol-section-sub" style="margin:2px 0 0">Each level has a points threshold. With <strong>Auto-coach ON</strong>, the coaching sends automatically the moment a driver's points cross a level (Termination never auto-fires). With <strong>Auto-coach OFF</strong>, the crossing waits in the Report as a “Send coaching” action for you to review and send.</p>
        </span>
        <span style="display:flex;align-items:center;gap:var(--s-2);font-size:var(--fs-sm);color:var(--text-muted)">
          Auto-coach
          <label class="toggle">
            <input type="checkbox" id="rr-pol-master-auto" ${s.master.auto_coaching ? "checked" : ""}/>
            <span class="toggle-slider"></span>
          </label>
        </span>
      </div>
      <div id="rr-pol-rungs" class="rr-pol-rungs">
        ${(s.ladder || []).map(rungRow).join("")}
        ${(s.ladder || []).length === 0 ? `<div class="rr-pol-empty-rungs">No coaching levels yet. Click <strong>+ Add a level</strong> below to start.</div>` : ""}
      </div>
      <button type="button" class="btn btn-sm" id="rr-pol-add-rung" style="margin-top:10px">+ Add a level</button>
    </div>

    <div class="pol-section">
      <h3 class="pol-section-title">Auto-escalations</h3>
      <p class="pol-section-sub">Optional rules that bypass the normal threshold ladder for severe events.</p>
      <label class="rr-pol-toggle-row">
        <input type="checkbox" id="rr-pol-ncns" ${s.ncns_terminates ? "checked" : ""}/>
        <span><strong>First NCNS = Termination</strong> · any no-call no-show triggers a Termination recommendation regardless of points.</span>
      </label>
      <label class="rr-pol-toggle-row">
        <input type="checkbox" id="rr-pol-first30" ${s.first_30.active ? "checked" : ""}/>
        <span><strong>First-30-days strict</strong> · any callout / no-show inside the probation window jumps to the highest rung.</span>
      </label>
      <label class="rr-pol-row" style="margin-top:6px;${s.first_30.active ? "" : "opacity:.55"}">
        <span>Probation window</span>
        <input type="number" min="7" max="120" step="1" id="rr-pol-first30-days" value="${Number(s.first_30.days) || 30}" ${s.first_30.active ? "" : "disabled"}/>
        <span>days</span>
      </label>
    </div>

    <div class="pol-section">
      <h3 class="pol-section-title">Tardy &amp; NCNS timing</h3>
      <p class="pol-section-sub">When the daily approvals card flags a driver Tardy or No-call no-show.</p>
      <label class="rr-pol-row">
        <span>Tardy after</span>
        <input type="number" min="0" max="120" step="1" id="rr-pol-tardy" value="${Number(s.timing.tardy_grace_minutes) || 0}"/>
        <span>min after shift start</span>
      </label>
      <label class="rr-pol-row">
        <span>NCNS after</span>
        <input type="number" min="30" max="240" step="30" id="rr-pol-ncns-min" value="${Number(s.timing.ncns_after_minutes) || 0}"/>
        <span>min after shift start</span>
      </label>
    </div>

    <div style="display:flex;align-items:center;gap:var(--s-2-5);margin-top:6px">
      <button class="btn btn-primary" type="button" id="rr-pol-save">Save policy</button>
      <span id="rr-pol-status" class="u-sm-subtle"></span>
    </div>`;
}

function _wirePolicyEditor() {
  const pane = document.getElementById("att-pane-policy");
  if (!pane || pane.dataset.rrWired === "1") return;
  pane.dataset.rrWired = "1";

  // Two-way binding for the simple top-level fields.
  pane.addEventListener("input", (e) => {
    const t = e.target;
    if (t.id === "rr-pol-window")        _polState.window_days = Number(t.value);
    if (t.id === "rr-pol-first30-days")  _polState.first_30.days = Number(t.value);
    if (t.id === "rr-pol-tardy")         _polState.timing.tardy_grace_minutes = Number(t.value);
    if (t.id === "rr-pol-ncns-min")      _polState.timing.ncns_after_minutes  = Number(t.value);

    // Event point input.
    const evPts = t.dataset?.rrPolEventPoints;
    if (evPts) {
      const ev = _polState.events.find(e => e.kind === evPts);
      if (ev) ev.points = Number(t.value);
    }

    // Rung props (severity / threshold / delivery / auto_fire).
    const rungEl = t.closest && t.closest("[data-rr-pol-rung]");
    const propKey = t.dataset?.rrPolRungProp;
    if (rungEl && propKey) {
      const id = rungEl.getAttribute("data-rr-pol-rung");
      const r  = _polState.ladder.find(x => x.id === id);
      if (r) {
        if (propKey === "auto_fire")  r.auto_fire = !!t.checked;
        else if (propKey === "threshold") r.threshold = Number(t.value);
        else r[propKey] = t.value;
      }
    }
  });

  pane.addEventListener("change", (e) => {
    const t = e.target;
    if (t.id === "rr-pol-master-enabled") _polState.master.policy_enabled = !!t.checked;
    if (t.id === "rr-pol-master-auto")    _polState.master.auto_coaching  = !!t.checked;
    if (t.id === "rr-pol-ncns")           _polState.ncns_terminates       = !!t.checked;
    if (t.id === "rr-pol-first30") {
      _polState.first_30.active = !!t.checked;
      // Toggle the days-input enabled state by re-rendering the row's
      // enabled/disabled state.  Light re-render: just walk the input.
      const daysEl = pane.querySelector("#rr-pol-first30-days");
      const wrap   = daysEl ? daysEl.closest("label") : null;
      if (daysEl) daysEl.disabled = !t.checked;
      if (wrap)   wrap.style.opacity = t.checked ? "" : ".55";
    }
    // Event enabled toggle.
    const evK = t.dataset?.rrPolEvent;
    if (evK) {
      const ev = _polState.events.find(e => e.kind === evK);
      if (ev) {
        ev.enabled = !!t.checked;
        const ptsEl = pane.querySelector(`[data-rr-pol-event-points="${evK}"]`);
        if (ptsEl) ptsEl.disabled = !t.checked;
      }
    }
    // Rung severity changing — termination flips auto_fire off.
    const rungEl = t.closest && t.closest("[data-rr-pol-rung]");
    if (rungEl && t.dataset?.rrPolRungProp === "severity") {
      const id = rungEl.getAttribute("data-rr-pol-rung");
      const r  = _polState.ladder.find(x => x.id === id);
      if (r && r.severity === "termination") r.auto_fire = false;
      _renderPolicyEditor();
    }
  });

  pane.addEventListener("click", async (e) => {
    // Add a level.
    if (e.target.id === "rr-pol-add-rung") {
      e.preventDefault();
      // _renderPolicyEditor() below replaces the pane and detaches this
      // button; without stopping propagation the document outside-click
      // handler would then see a now-detached target (no longer inside the
      // popover) and close the whole popup. Keep the event local.
      e.stopPropagation();
      const next = _polState.ladder.length;
      const nextThreshold = _polState.ladder.length > 0
        ? Number(_polState.ladder[_polState.ladder.length - 1].threshold) + 1
        : 1;
      const sevSeq = ["verbal","written","final","termination"];
      _polState.ladder.push({
        id:        _newRungId(),
        severity:  sevSeq[Math.min(next, 3)],
        threshold: nextThreshold,
        delivery:  "ack",
        auto_fire: false,
      });
      _renderPolicyEditor();
      return;
    }
    // Remove a level.
    const rm = e.target.closest && e.target.closest("[data-rr-pol-rung-remove]");
    if (rm) {
      e.preventDefault();
      e.stopPropagation();   // same detach-on-re-render guard as Add a level
      const id = rm.getAttribute("data-rr-pol-rung-remove");
      _polState.ladder = _polState.ladder.filter(r => r.id !== id);
      _renderPolicyEditor();
      return;
    }
    // Save.
    if (e.target.id === "rr-pol-save") {
      e.preventDefault();
      const dspId = window.RR?.dsp?.id;
      if (!dspId) return;
      const status = document.getElementById("rr-pol-status");
      if (status) { status.style.color = "var(--text-subtle)"; status.textContent = "Saving…"; }

      const newPolicy = {
        policy_enabled: _polState.master.policy_enabled,
        auto_coaching:  _polState.master.auto_coaching,
        blocks:         _polStateToBlocks(_polState),
      };

      const { data: row } = await sb.from("dsps").select("metadata").eq("id", dspId).single();
      const meta = row?.metadata || {};
      const newMeta = { ...meta, attendance: { ...(meta.attendance || {}), policy: newPolicy } };
      const { error: upErr } = await sb.from("dsps").update({ metadata: newMeta }).eq("id", dspId);
      if (upErr) { if (status) { status.style.color = "var(--red)"; status.textContent = "Failed: " + upErr.message; } return; }
      if (window.RR?.dsp) window.RR.dsp.metadata = newMeta;

      // Timing.
      const timing = {};
      if (Number.isFinite(_polState.timing.tardy_grace_minutes)) timing.tardy_grace_minutes = _polState.timing.tardy_grace_minutes;
      if (Number.isFinite(_polState.timing.ncns_after_minutes))  timing.ncns_after_minutes  = _polState.timing.ncns_after_minutes;
      if (Object.keys(timing).length > 0) {
        const { data: existing } = await sb.from("scheduling_settings")
          .select("id").eq("dsp_id", dspId).is("week_start", null).maybeSingle();
        if (existing?.id) {
          const { error: setErr } = await sb.from("scheduling_settings")
            .update(timing).eq("id", existing.id);
          if (setErr) console.warn("timing save:", setErr.message);
        } else {
          const { error: insErr } = await sb.from("scheduling_settings")
            .insert([{ dsp_id: dspId, week_start: null, ...timing }]);
          if (insErr) console.warn("timing insert:", insErr.message);
        }
      }

      if (status) { status.style.color = "var(--green)"; status.textContent = "Saved ✓"; setTimeout(() => status.textContent = "", 2500); }
      toast("Attendance policy saved", "success");
      if (typeof _rrApplyAttPolicyMode === "function") _rrApplyAttPolicyMode();
      if (typeof loadAttendanceLive === "function") loadAttendanceLive();
      if (typeof loadAttendanceEventLog === "function") loadAttendanceEventLog();
    }
  });
}



// Time-period the Event log shows.  Independent of the policy
// decay window — operators may want to inspect "all time" while
// running a 90-day policy, or 7 days while running a 365-day
// policy.  Stored on the function so re-render preserves the
// selection without rewiring the dropdown.
let _attLogWindowDays = 90;  // default

async function loadAttendanceEventLog() {
  const pane = document.getElementById("att-pane-log");
  if (!pane) return;
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;

  const policy = _getAttPolicy();
  const policyOn = policy.policy_enabled !== false;

  // "all" is sentinel for no lower bound.
  const isAll = _attLogWindowDays === "all";
  const since = isAll ? null : (() => { const d = new Date(); d.setDate(d.getDate() - Number(_attLogWindowDays)); return d; })();
  const sinceIso = since ? fmtIsoDate(since) : null;

  let shiftsQ = sb.from("shifts")
    .select("id, date, status, driver_id")
    .eq("dsp_id", dspId)
    .in("status", ["called_off", "no_show", "late"])
    .order("date", { ascending: false });
  if (sinceIso) shiftsQ = shiftsQ.gte("date", sinceIso);

  let coachQ = sb.from("coachings")
    .select("id, severity, triggering_shift_id, occurred_at, acknowledged_at, signed_at, metadata")
    .eq("dsp_id", dspId)
    .eq("topic", "attendance")
    .eq("driver_visible", true)
    .not("triggering_shift_id", "is", null)
    .is("archived_at", null)
    .order("occurred_at", { ascending: false });
  if (since) coachQ = coachQ.gte("occurred_at", since.toISOString());

  const [shiftsRes, driversRes, coachRes] = await Promise.all([
    shiftsQ,
    sb.from("drivers")
      .select("id, full_name, first_name, last_name, preferred_name, station:station_id (code), tier")
      .eq("dsp_id", dspId),
    coachQ,
  ]);

  if (shiftsRes.error || driversRes.error) {
    console.warn("event log load:", shiftsRes.error || driversRes.error);
    return;
  }

  const drvById = new Map((driversRes.data || []).map(d => [d.id, d]));
  const events = (shiftsRes.data || []).filter(sh => sh.driver_id);

  // Most recent coaching per triggering shift — drives the ✓ Coached
  // chip when the dispatcher has already addressed an event.
  const coachByShift = new Map();
  for (const c of (coachRes?.data || [])) {
    if (!coachByShift.has(c.triggering_shift_id)) coachByShift.set(c.triggering_shift_id, c);
  }

  const countEl = document.getElementById("att-log-count");
  if (countEl) countEl.textContent = String(events.length);

  // Per-driver totals — gives the dispatcher their own counting
  // signal to act on when the policy is off.
  const totalsByDriver = new Map();
  for (const ev of events) {
    if (!ev.driver_id) continue;
    totalsByDriver.set(ev.driver_id, (totalsByDriver.get(ev.driver_id) || 0) + 1);
  }
  const repeatCount = Array.from(totalsByDriver.values()).filter(n => n >= 2).length;

  const windowOpts = [
    [7, "Last 7 days"], [30, "Last 30 days"], [90, "Last 90 days"],
    [365, "Last 12 months"], ["all", "All time"],
  ].map(([v, lbl]) => `<option value="${v}" ${String(_attLogWindowDays) === String(v) ? "selected" : ""}>${escapeHtml(lbl)}</option>`).join("");

  // Filter bar — time-period selector + summary chip.  Always
  // rendered even when there are 0 events so the operator can
  // widen the window to find some.
  const filterBar = `
    <div class="toolbar u-mb-3">
      <div class="toolbar-left" style="display:flex;align-items:center;gap:var(--s-2-5)">
        <label style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">Window</label>
        <select id="rr-att-log-window" class="form-input" style="height:auto;padding:6px var(--s-2-5)">${windowOpts}</select>
        <span class="u-sm-subtle">
          <strong style="color:var(--text)">${events.length}</strong> event${events.length === 1 ? "" : "s"} ·
          <strong style="color:var(--text)">${totalsByDriver.size}</strong> driver${totalsByDriver.size === 1 ? "" : "s"}
          ${repeatCount > 0 ? ` · <strong style="color:var(--amber)">${repeatCount}</strong> with 2+ events` : ""}
        </span>
      </div>
    </div>`;

  if (events.length === 0) {
    pane.innerHTML = `${filterBar}<div class="rr-empty-inline">No callouts, no-shows, or late events in this window.</div>`;
    _wireAttLogWindow();
    return;
  }

  const eventLabel = { called_off: "Callout", no_show: "No-show", late: "Late" };
  const eventColor = { called_off: "var(--amber)", no_show: "var(--red)", late: "var(--text-muted)" };

  // Action column: Send-coaching button when policy is OFF (the
  // operator owns next steps from the log itself).  When policy
  // is ON, coaching flows exclusively through the Report — the
  // log stays neutral / passive so it doesn't compete with the
  // Report for the same decision.
  const actionHeader = policyOn ? "" : "<th></th>";

  pane.innerHTML = `${filterBar}
    <div class="table-wrap"><table class="table">
      <thead><tr>
        <th>Date</th><th>Driver</th><th>Station</th><th>Event</th>
        <th class="u-right" title="Driver's count of attendance events in this window">In window</th>
        <th>Coaching</th>${actionHeader}
      </tr></thead>
      <tbody>
        ${events.map(ev => {
          const d = drvById.get(ev.driver_id);
          const display = d ? displayDriverName(d) : "—";
          const station = d?.station?.code || "—";
          const initials = d ? displayDriverInitials(d) : "?";
          const tier = d?.tier ? `tier-${String(d.tier).toLowerCase()}` : "";
          const driverTotal = totalsByDriver.get(ev.driver_id) || 1;

          const c = coachByShift.get(ev.id);
          let coachCell;
          if (c) {
            const sevLabel = _coachingSevLabel(c.severity, c.topic || "attendance", c.metadata?.attendance_reason);
            const ackState = c.acknowledged_at ? (c.signed_at ? "Signed" : "Acknowledged") : "Awaiting ack";
            const chipCls  = ackState === "Awaiting ack" ? "pending" : "done";
            coachCell = `<div style="display:flex;flex-direction:column;gap:2px;align-items:flex-start"><span style="font-size:var(--fs-sm);font-weight:600">${escapeHtml(sevLabel)} <span style="color:var(--text-subtle);font-weight:500">· ${escapeHtml(_relTimeAgo(c.occurred_at))}</span></span><span class="att-coach-chip ${chipCls}">✓ ${escapeHtml(ackState)}</span></div>`;
          } else {
            coachCell = `<span class="u-subtle">—</span>`;
          }

          let actionCell = "";
          if (!policyOn) {
            const sendBtn = c
              ? `<button class="btn btn-sm btn-ghost" type="button" data-rr-coach-event="${escapeHtml(ev.id || "")}" data-rr-coach-driver="${escapeHtml(d?.id || ev.driver_id || "")}" data-rr-coach-driver-name="${escapeHtml(display)}" data-rr-coach-event-label="${escapeHtml(eventLabel[ev.status] || ev.status)}" data-rr-coach-event-date="${escapeHtml(ev.date)}" data-rr-coach-reason="${escapeHtml(ev.status || "")}" title="Already coached. Send another only if needed.">Send another</button>`
              : `<button class="btn btn-sm" type="button" data-rr-coach-event="${escapeHtml(ev.id || "")}" data-rr-coach-driver="${escapeHtml(d?.id || ev.driver_id || "")}" data-rr-coach-driver-name="${escapeHtml(display)}" data-rr-coach-event-label="${escapeHtml(eventLabel[ev.status] || ev.status)}" data-rr-coach-event-date="${escapeHtml(ev.date)}" data-rr-coach-reason="${escapeHtml(ev.status || "")}">Send coaching</button>`;
            actionCell = `<td class="u-right">${sendBtn}</td>`;
          }

          return `<tr>
            <td>${new Date(ev.date + "T12:00:00").toLocaleDateString()}</td>
            <td><div class="cell-driver"><div class="avatar-sm ${tier}">${initials}</div><div><div class="cell-name" data-rr-driver-id="${d?.id || ev.driver_id || ""}">${escapeHtml(display)}</div></div></div></td>
            <td>${escapeHtml(station)}</td>
            <td><span style="color:${eventColor[ev.status]};font-weight:600">${eventLabel[ev.status]}</span></td>
            <td style="text-align:right;font-weight:600;color:${driverTotal >= 2 ? "var(--amber)" : "var(--text)"}">${driverTotal}</td>
            <td>${coachCell}</td>
            ${actionCell}
          </tr>`;
        }).join("")}
      </tbody>
    </table></div>`;
  _wireAttLogWindow();
}

function _wireAttLogWindow() {
  const sel = document.getElementById("rr-att-log-window");
  if (!sel) return;
  sel.addEventListener("change", () => {
    const v = sel.value;
    _attLogWindowDays = (v === "all") ? "all" : Number(v);
    loadAttendanceEventLog();
  });
}

// ─── Send coaching modal — Event log entry point ────────────────────
//
// Phase 1 path: dispatcher fires a coaching ad-hoc from a single
// attendance event.  Severity choices include 'note' (no ladder
// advancement) since this surface is for the policy-OFF / soft-touch
// case.  delivery_required is per-coaching here — when the policy
// is ON, the Report path will pull severity defaults from policy
// settings instead.
let _coachCtx = null;

document.addEventListener("click", (e) => {
  // Event log row → soft-touch path (severity defaults to Verbal,
  // the Note option is available because policy may be off).
  const evBtn = e.target.closest("[data-rr-coach-event]");
  if (evBtn) {
    e.preventDefault();
    e.stopImmediatePropagation();
    _coachCtx = {
      source:      "event_log",
      event_id:    evBtn.getAttribute("data-rr-coach-event") || null,
      driver_id:   evBtn.getAttribute("data-rr-coach-driver"),
      driver_name: evBtn.getAttribute("data-rr-coach-driver-name") || "Driver",
      event_label: evBtn.getAttribute("data-rr-coach-event-label") || "Event",
      event_date:  evBtn.getAttribute("data-rr-coach-event-date") || "",
      reason:      evBtn.getAttribute("data-rr-coach-reason") || null,
      topic:       "attendance",
    };
    _openSendCoachingModal(_coachCtx);
    return;
  }
  // Attendance Report row → ladder-aware path.  Severity comes from
  // the row's coaching label; delivery default comes from the matching
  // Ladder rung block in the new policy.
  const repBtn = e.target.closest("[data-rr-coach-report]");
  if (repBtn) {
    e.preventDefault();
    e.stopImmediatePropagation();
    const sev = repBtn.getAttribute("data-rr-coach-severity") || "verbal";
    const evalP = _evalPolicy();
    const rung  = (evalP.ladder || []).find(r => r.severity === sev);
    const delDefault = rung?.delivery || "ack";
    _coachCtx = {
      source:           "report",
      driver_id:        repBtn.getAttribute("data-rr-coach-driver"),
      driver_name:      repBtn.getAttribute("data-rr-coach-driver-name") || "Driver",
      severity:         sev,
      delivery_default: delDefault,
      summary:          repBtn.getAttribute("data-rr-coach-summary") || "",
      points:           repBtn.getAttribute("data-rr-coach-points") || "0",
      occ:              repBtn.getAttribute("data-rr-coach-occ")    || "0",
      callouts:         repBtn.getAttribute("data-rr-coach-callouts") || "0",
      noshows:          repBtn.getAttribute("data-rr-coach-noshows")  || "0",
      late:             repBtn.getAttribute("data-rr-coach-late")     || "0",
      topic:            "attendance",
    };
    _openSendCoachingModal(_coachCtx);
  }
});

// The top-bar "Coach driver" pill is now a dropdown (Attendance coaching /
// General coaching) — see _rrCoachOpenDriver + the data-rr-roster-coach-menu
// handler in the roster top-strip section. Both paths coach the open record.

function _openSendCoachingModal(ctx) {
  let m = document.getElementById("rr-send-coach-modal");
  if (m) m.remove();
  m = document.createElement("div");
  m.id = "rr-send-coach-modal";
  m.style.cssText = "position:fixed;inset:0;background:var(--overlay);z-index:9999;display:flex;align-items:center;justify-content:center;padding:var(--s-6)";

  const fromReport  = ctx.source === "report";
  const dateStr     = ctx.event_date ? new Date(ctx.event_date + "T12:00:00").toLocaleDateString() : "";
  const subtitle    = fromReport
    ? `${escapeHtml(ctx.driver_name)} · ladder · ${escapeHtml(ctx.points)} pts · ${escapeHtml(ctx.occ)} occurrences`
    : `${escapeHtml(ctx.driver_name)} · ${escapeHtml(ctx.event_label || "")}${dateStr ? " · " + escapeHtml(dateStr) : ""}`;
  const sevDefault  = ctx.severity || "verbal";
  const delDefault  = ctx.delivery_default || "ack";
  const summaryVal  = fromReport
    ? (ctx.summary || `Attendance · ${ctx.driver_name}`)
    : `${ctx.event_label || ""}${dateStr ? " on " + dateStr : ""}`;
  const notesPrefill = fromReport
    ? `Over the last 90 days you've had ${ctx.callouts} callout${ctx.callouts === "1" ? "" : "s"}, ${ctx.noshows} no-show${ctx.noshows === "1" ? "" : "s"}, and ${ctx.late} late arrival${ctx.late === "1" ? "" : "s"} (${ctx.points} points · ${ctx.occ} occurrences). Let's talk about how to get back on track.`
    : "";

  // Note severity is hidden when launched from the Report — that path
  // is for ladder-tracking, and Note doesn't advance the ladder.
  const attnSfx = ctx.topic === "attendance" ? "-Attendance" : "";
  const noteOption = fromReport ? "" : `<option value="note">Note${attnSfx} · informational, no ladder advancement</option>`;

  const sel = (v) => v === sevDefault ? "selected" : "";
  const dsel = (v) => v === delDefault ? "selected" : "";
  const rsel = (v) => v === (ctx.reason || "") ? "selected" : "";

  m.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);width:520px;max-width:100%;max-height:90vh;overflow-y:auto;padding:22px 24px;box-shadow:var(--shadow-lg)">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:var(--s-3);margin-bottom:14px">
        <div>
          <div style="font-size:var(--fs-lg);font-weight:700;color:var(--text);letter-spacing:-.005em">Send coaching</div>
          <div style="font-size:var(--fs-sm);color:var(--text-subtle);margin-top:2px">${subtitle}</div>
        </div>
        <button type="button" id="rr-coach-close" style="background:none;border:0;font-size:var(--fs-xl);cursor:pointer;color:var(--text-muted);padding:0 4px;line-height:1">×</button>
      </div>

      <label style="display:block;font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px">Severity${fromReport ? ' <span style="color:var(--accent);font-weight:600;text-transform:none;letter-spacing:0">· ladder recommendation</span>' : ''}</label>
      <select id="rr-coach-sev" style="width:100%;padding:var(--s-2-5) var(--s-3);border:1px solid var(--border);border-radius:8px;background:var(--canvas);color:var(--text);font-size:var(--fs-md);margin-bottom:14px">
        ${noteOption}
        <option value="verbal"      ${sel("verbal")}>Verbal${attnSfx} · soft warning</option>
        <option value="written"     ${sel("written")}>Written${attnSfx} · documented warning</option>
        <option value="final"       ${sel("final")}>Final${attnSfx} · last warning before termination</option>
        <option value="termination" ${sel("termination")}>Termination${attnSfx} · separation</option>
      </select>

      <label style="display:block;font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px">Attendance reason</label>
      <select id="rr-coach-reason" style="width:100%;padding:var(--s-2-5) var(--s-3);border:1px solid var(--border);border-radius:8px;background:var(--canvas);color:var(--text);font-size:var(--fs-md);margin-bottom:14px">
        <option value=""           ${rsel("")}>General / not specified</option>
        <option value="no_show"    ${rsel("no_show")}>No Call/No Show</option>
        <option value="called_off" ${rsel("called_off")}>Call-Out</option>
        <option value="late"       ${rsel("late")}>Late</option>
      </select>

      <label style="display:block;font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px">Driver must${fromReport ? ' <span style="color:var(--accent);font-weight:600;text-transform:none;letter-spacing:0">· policy default</span>' : ''}</label>
      <select id="rr-coach-delivery" style="width:100%;padding:var(--s-2-5) var(--s-3);border:1px solid var(--border);border-radius:8px;background:var(--canvas);color:var(--text);font-size:var(--fs-md);margin-bottom:14px">
        <option value="none"         ${dsel("none")}>Read only · no action required</option>
        <option value="ack"          ${dsel("ack")}>Acknowledge · tap "I understand"</option>
        <option value="sign"         ${dsel("sign")}>Sign · capture signature</option>
        <option value="ack_and_sign" ${dsel("ack_and_sign")}>Acknowledge &amp; sign</option>
      </select>

      <label style="display:block;font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px">Headline</label>
      <input type="text" id="rr-coach-summary" placeholder="One-line summary the driver sees first" value="${escapeHtml(summaryVal)}" style="width:100%;padding:var(--s-2-5) var(--s-3);border:1px solid var(--border);border-radius:8px;background:var(--canvas);color:var(--text);font-size:var(--fs-md);margin-bottom:14px"/>

      <label style="display:block;font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px">Message</label>
      <textarea id="rr-coach-notes" rows="5" placeholder="What you'd like the driver to know" style="width:100%;padding:var(--s-2-5) var(--s-3);border:1px solid var(--border);border-radius:8px;background:var(--canvas);color:var(--text);font-size:var(--fs-md);font-family:inherit;line-height:1.5;resize:vertical">${escapeHtml(notesPrefill)}</textarea>

      <div style="display:flex;justify-content:flex-end;gap:var(--s-2);margin-top:18px">
        <button type="button" class="btn" id="rr-coach-cancel">Cancel</button>
        <button type="button" class="btn btn-primary" id="rr-coach-send">Send to driver</button>
      </div>
    </div>`;
  document.body.appendChild(m);

  const close = () => { m.remove(); _coachCtx = null; };
  m.addEventListener("click", (e) => { if (e.target === m) close(); });
  document.getElementById("rr-coach-close").addEventListener("click", close);
  document.getElementById("rr-coach-cancel").addEventListener("click", close);

  // Reason picker prefills the headline — the infraction lives in the
  // summary, not the severity label — until the operator types their own.
  const _scSum = document.getElementById("rr-coach-summary");
  const _scReason = document.getElementById("rr-coach-reason");
  let _scSumTouched = false;
  _scSum?.addEventListener("input", () => { _scSumTouched = true; });
  _scReason?.addEventListener("change", () => {
    const lbl = _COACHING_ATT_REASON_LABEL[_scReason.value];
    if (lbl && !_scSumTouched) _scSum.value = lbl;
  });

  document.getElementById("rr-coach-send").addEventListener("click", async () => {
    const sev      = document.getElementById("rr-coach-sev").value;
    const delivery = document.getElementById("rr-coach-delivery").value;
    const summary  = document.getElementById("rr-coach-summary").value.trim();
    const notes    = document.getElementById("rr-coach-notes").value.trim();
    if (!summary && !notes) { toast("Add a headline or message", "warn"); return; }
    const sendBtn = document.getElementById("rr-coach-send");
    sendBtn.disabled = true; sendBtn.textContent = "Sending…";
    const reason = document.getElementById("rr-coach-reason")?.value || null;
    const payload = {
      driver_id:           ctx.driver_id,
      topic:               ctx.topic || "attendance",
      severity:            sev,
      delivery_required:   delivery,
      summary,
      notes,
      triggering_shift_id: ctx.event_id || null,
      incident_date:       ctx.event_date || null,
      metadata:            reason ? { attendance_reason: reason } : {},
    };
    const { error } = await sb.rpc("send_coaching", { p_payload: payload });
    if (error) {
      sendBtn.disabled = false; sendBtn.textContent = "Send to driver";
      toast("Send failed: " + error.message, "warn");
      return;
    }
    toast("Coaching sent to " + ctx.driver_name, "success");
    close();
    // Refresh whichever surface launched the modal so the operator
    // sees their action reflected immediately.
    if (ctx.source === "report" && typeof loadAttendanceLive === "function") loadAttendanceLive();
    else if (ctx.source === "record" && _ddOpenDriverId && typeof openDriverDrawer === "function") openDriverDrawer(_ddOpenDriverId, { tab: "attendance" });
    else if (typeof loadAttendanceEventLog === "function")                   loadAttendanceEventLog();
  });
}

// Hook attTab — operator clicks Report / Policy / Log inside the
// Drivers → Attendance subview. The mockup defines window.attTab on
// load; wrap it so we can also fire our live loaders.
const _legacyAttTab = window.attTab;
window.attTab = function (name) {
  // Always close the report's KPI drilldown when switching tabs so a
  // panel left open before doesn't reappear when the operator comes
  // back to the Report tab.
  if (typeof _closeAttKpiDetail === "function") _closeAttKpiDetail();
  // Redirect any lingering "today" call to history — the Today pane was
  // moved to the sidebar Today's Plan page.
  if (name === "today") name = "history";
  // Policy builder lives in Settings → Scheduling now (under the
  // Attendance policy details card). If anything still triggers
  // attTab('policy'), bounce the operator to the new home.
  if (name === "policy") {
    if (typeof window.gotoSettingsScheduling === "function") window.gotoSettingsScheduling();
    return;
  }
  // The Report / Event log tab strip was removed — pane switching is
  // now driven by the small "Event log" text link above the table.
  // Drive the pane visibility ourselves so we don't crash on the
  // legacy attTab's querySelector against the now-absent buttons.
  document.querySelectorAll('#dr-sub-attendance .att-pane').forEach((p) => p.classList.remove("active"));
  const pane = document.getElementById("att-pane-" + name);
  if (pane) pane.classList.add("active");
  if (name === "report")  loadAttendanceLive();
  if (name === "log")     loadAttendanceEventLog();
};

// Hide / show the right tab based on the attendance policy state.
// One surface per mode:
//   • Policy OFF → Event log only.  Operator coaches manually per
//                  event from the log.
//   • Policy ON  → Report only.  Same data, packaged per-driver
//                  with points + ladder.  The Event log would just
//                  be a redundant chronological view of the same
//                  shifts the Report already aggregates.
function _rrApplyAttPolicyMode() {
  const policy   = (typeof _getAttPolicy === "function") ? _getAttPolicy() : {};
  const isOn     = policy.policy_enabled !== false;
  const reportTab  = document.querySelector('#rr-att-tabstrip [data-att="report"]');
  const reportPane = document.getElementById("att-pane-report");
  const logTab     = document.querySelector('#rr-att-tabstrip [data-att="log"]');
  const logPane    = document.getElementById("att-pane-log");
  if (!reportTab || !logTab) return;

  if (isOn) {
    // Report visible, Event log hidden.  If the Event log was active
    // when the policy got turned on, flip the active tab + pane to
    // Report so the operator isn't staring at a hidden surface.
    reportTab.style.display = "";
    logTab.style.display    = "none";
    if (logTab.classList.contains("active")) {
      logTab.classList.remove("active");
      reportTab.classList.add("active");
      if (logPane)    logPane.classList.remove("active");
      if (reportPane) reportPane.classList.add("active");
      loadAttendanceLive();
    }
  } else {
    // Event log visible, Report hidden.  Flip active to Event log
    // when needed for the same reason.
    reportTab.style.display = "none";
    logTab.style.display    = "";
    if (reportTab.classList.contains("active")) {
      reportTab.classList.remove("active");
      logTab.classList.add("active");
      if (reportPane) reportPane.classList.remove("active");
      if (logPane)    logPane.classList.add("active");
      loadAttendanceEventLog();
    }
  }
}

// Load the right data when the operator opens a settings section
// that's hosted by JS rather than baked into the HTML mockup.
document.addEventListener("click", (e) => {
  if (e.target.closest('.settings-nav-item[data-set="scheduling"]')) {
    setTimeout(() => loadAttendancePolicy(),     0);
    setTimeout(() => loadAvailabilityRequests(), 0);
  }
  if (e.target.closest('.settings-nav-item[data-set="team"]')) {
    setTimeout(() => loadTeamMembers(), 0);
  }
  // Messages / Referrals were moved here from the Pipeline subnav. Each
  // section reuses the loader that previously fired on the pipeSub click.
  // (Screening questions now live in the Funnel → Rules popover.)
  if (e.target.closest('.settings-nav-item[data-set="hiring-messages"]')) {
    setTimeout(() => loadMessagesTab(), 0);
  }
  if (e.target.closest('.settings-nav-item[data-set="referrals"]')) {
    setTimeout(() => loadReferralsTab(), 0);
  }
});

// ─── Settings · Team ─────────────────────────────────────────────────────
//
// Hydrates the Team section with live app_users rows for the caller's
// DSP, and wires the "Invite team member" button to a modal that calls
// the invite-team-member edge function.

async function loadTeamMembers() {
  const list = document.getElementById("rr-team-list");
  if (!list) return;
  const dspId  = window.RR?.dsp?.id;
  const meId   = window.RR?.user?.id;
  const meRole = window.RR?.user?.role;
  const isOwner = meRole === "owner";
  if (!dspId) { list.innerHTML = `<div class="rr-empty-inline">No DSP context</div>`; return; }

  list.innerHTML = `<div class="rr-loading">Loading team</div>`;
  const { data, error } = await sb
    .from("app_users")
    .select("id, email, full_name, role, active, allowed_pages, created_at")
    .eq("dsp_id", dspId)
    .eq("active", true)
    .order("role", { ascending: true })
    .order("created_at", { ascending: true });
  if (error) {
    list.innerHTML = `<div class="rr-empty-inline" style="color:var(--red)">${escapeHtml(error.message)}</div>`;
    return;
  }
  const rows = data || [];
  if (rows.length === 0) {
    list.innerHTML = `<div class="rr-empty-inline">No team members yet — use the button below to send the first invite.</div>`;
    return;
  }
  const initialsOf = (s) => (s || "?").split(/\s+/).map(p => p[0]).filter(Boolean).slice(0, 2).join("").toUpperCase();
  const ageDays = (iso) => Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 86400000));
  const ageLabel = (iso) => {
    const d = ageDays(iso);
    if (d === 0)  return "added today";
    if (d === 1)  return "added 1 day ago";
    if (d < 30)   return `added ${d} days ago`;
    if (d < 365)  return `added ${Math.floor(d / 30)} mo ago`;
    return `added ${Math.floor(d / 365)} y ago`;
  };
  // Top-level pages — keys must match data-view on .nav-item buttons
  // and the keys passed to goto(). Settings is always visible to
  // everyone (otherwise a restricted user has no way back to here),
  // so it isn't togglable.
  const PAGES = [
    { key: "dashboard", label: "Today" },
    { key: "pipeline",  label: "Hiring Pipeline" },
    { key: "drivers",   label: "Drivers" },
    { key: "staffing",  label: "Performance" },
    { key: "fleet",     label: "Fleet" },
    { key: "schedule",  label: "Schedule" },
    { key: "messages",  label: "Messages" },
    { key: "forms",     label: "Workflows" },
    { key: "finances",  label: "Finances" },
  ];
  list.innerHTML = rows.map(r => {
    const isMe   = r.id === meId;
    const initials = initialsOf(r.full_name || r.email);
    const sub = isMe ? `${r.email} · you` : `${r.email} · ${ageLabel(r.created_at)}`;
    const roleOpts = ["owner","ops","dispatcher"].map(opt =>
      `<option value="${opt}" ${opt === r.role ? "selected" : ""}>${opt.charAt(0).toUpperCase() + opt.slice(1)}</option>`
    ).join("");
    // Editable name input — anyone can edit their own; owners can
    // edit anyone's. The DB has matching policies (self-name update +
    // owner-write).
    const canEditName = isMe || isOwner;
    // Page permissions only togglable by owner, only on non-owner rows
    // (owners always see everything), and only on non-self rows.
    const canTogglePages = isOwner && !isMe && r.role !== "owner";
    const allowed = Array.isArray(r.allowed_pages) ? r.allowed_pages : null;
    const restrictedCount = allowed ? PAGES.filter(p => !allowed.includes(p.key)).length : 0;
    const pageBtn = canTogglePages
      ? `<button class="btn btn-sm" data-rr-team-pages="${r.id}" style="white-space:nowrap">
           ${restrictedCount > 0 ? `Pages · ${PAGES.length - restrictedCount}/${PAGES.length}` : "Pages · all"}
         </button>`
      : "";
    return `<div class="member-row" data-rr-team-row="${r.id}">
      <div class="dsp-avatar" style="width:32px;height:32px;font-size:var(--fs-xs)">${escapeHtml(initials)}</div>
      <div style="min-width:0">
        ${canEditName
          ? `<input type="text" value="${escapeHtml(r.full_name || "")}" placeholder="${escapeHtml(r.email)}"
              data-rr-team-name="${r.id}"
              style="font-size:var(--fs-md);font-weight:600;background:transparent;border:1px solid transparent;border-radius:var(--r-sm);padding:2px 6px;width:100%;color:var(--text)"
              onfocus="this.style.borderColor='var(--border-strong)';this.style.background='var(--surface)'"
              onblur="this.style.borderColor='transparent';this.style.background='transparent'">`
          : `<div style="font-size:var(--fs-md);font-weight:600;padding:2px 6px">${escapeHtml(r.full_name || r.email)}</div>`}
        <div style="font-size:var(--fs-xs);color:var(--text-subtle);padding-left:6px">${escapeHtml(sub)}</div>
      </div>
      ${pageBtn}
      <select class="form-input" style="width:140px;padding:var(--s-1) 8px;font-size:var(--fs-sm)" data-rr-team-role="${r.id}" ${isMe ? "disabled title='Cannot change your own role'" : ""}>${roleOpts}</select>
      <button class="btn btn-sm btn-danger" data-rr-team-remove="${r.id}" data-rr-team-name-display="${escapeHtml(r.full_name || r.email)}" ${isMe ? "disabled title='Cannot remove yourself'" : ""}>Remove</button>
    </div>`;
  }).join("");
}

// Inline name save on blur — debounced via the blur event itself.
document.addEventListener("blur", async (e) => {
  const inp = e.target.closest("[data-rr-team-name]");
  if (!inp) return;
  const id = inp.getAttribute("data-rr-team-name");
  const newName = inp.value.trim();
  // Skip if unchanged (the row's previous value lives in the DOM
  // before edit; we just send what's there now).
  const { error } = await sb.from("app_users").update({ full_name: newName || null }).eq("id", id);
  if (error) { toast("Save failed: " + error.message, "warn"); return; }
  toast("Name updated", "success");
  // If the user updated their own name, reflect it in window.RR.user
  // so other dashboard surfaces (workspace chip, account menu) catch up.
  if (id === window.RR?.user?.id) {
    window.RR.user.full_name = newName || null;
  }
}, true);

// Page-permissions popover. Click the "Pages" button to toggle which
// top-level views show in the teammate's sidebar.
document.addEventListener("click", async (e) => {
  const btn = e.target.closest("[data-rr-team-pages]");
  if (!btn) return;
  e.preventDefault();
  const id = btn.getAttribute("data-rr-team-pages");
  // Fetch fresh allowed_pages so we don't overwrite a parallel edit.
  const { data, error } = await sb.from("app_users")
    .select("allowed_pages, full_name, email")
    .eq("id", id).maybeSingle();
  if (error) { toast("Load failed: " + error.message, "warn"); return; }
  const PAGES = [
    { key: "dashboard", label: "Today" },
    { key: "pipeline",  label: "Hiring Pipeline" },
    { key: "drivers",   label: "Drivers" },
    { key: "staffing",  label: "Performance" },
    { key: "fleet",     label: "Fleet" },
    { key: "schedule",  label: "Schedule" },
    { key: "messages",  label: "Messages" },
    { key: "forms",     label: "Workflows" },
    { key: "finances",  label: "Finances" },
  ];
  // null/undefined allowed_pages = full access (all pages allowed).
  const current = Array.isArray(data?.allowed_pages) ? data.allowed_pages : PAGES.map(p => p.key);
  // Build modal contents.
  const teammate = data?.full_name || data?.email || "this teammate";
  const checks = PAGES.map(p =>
    `<label style="display:flex;align-items:center;gap:var(--s-2);padding:6px 4px;cursor:pointer;border-radius:var(--r-sm)" onmouseover="this.style.background='var(--surface-hover)'" onmouseout="this.style.background='transparent'">
       <input type="checkbox" data-rr-page-toggle="${p.key}" ${current.includes(p.key) ? "checked" : ""}>
       <span style="font-size:var(--fs-md)">${escapeHtml(p.label)}</span>
     </label>`
  ).join("");
  const modal = document.createElement("div");
  modal.className = "modal-backdrop";
  modal.style.display = "flex";
  modal.style.zIndex = "9999";
  modal.innerHTML = `
    <div class="modal" style="max-width:380px">
      <div class="modal-header">
        <div>
          <p class="modal-title">Sidebar pages</p>
          <p class="modal-sub" style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${escapeHtml(teammate)} will only see checked pages</p>
        </div>
        <button class="modal-close" data-rr-page-modal-close><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
      </div>
      <div class="modal-body">${checks}</div>
      <div class="modal-actions" style="display:flex;justify-content:space-between;gap:var(--s-2);padding:var(--s-3) var(--s-5);border-top:1px solid var(--border)">
        <button class="btn btn-sm btn-ghost" data-rr-page-modal-all>Allow all</button>
        <div style="display:flex;gap:var(--s-2)">
          <button class="btn btn-sm" data-rr-page-modal-close>Cancel</button>
          <button class="btn btn-sm btn-primary" data-rr-page-modal-save>Save</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  modal.addEventListener("click", async (ev) => {
    if (ev.target === modal || ev.target.closest("[data-rr-page-modal-close]")) {
      modal.remove(); return;
    }
    if (ev.target.closest("[data-rr-page-modal-all]")) {
      modal.querySelectorAll("[data-rr-page-toggle]").forEach(c => c.checked = true);
      return;
    }
    if (ev.target.closest("[data-rr-page-modal-save]")) {
      const checked = Array.from(modal.querySelectorAll("[data-rr-page-toggle]:checked"))
        .map(c => c.getAttribute("data-rr-page-toggle"));
      // If everything's checked, store NULL (= no restriction). Cleaner
      // than carrying a redundant array around.
      const value = checked.length === PAGES.length ? null : checked;
      const { error } = await sb.from("app_users").update({ allowed_pages: value }).eq("id", id);
      if (error) { toast("Save failed: " + error.message, "warn"); return; }
      toast("Page access updated", "success");
      modal.remove();
      loadTeamMembers();
    }
  });
});

// Inline role-change save (no modal — change the select, hits the
// app_users row immediately).
document.addEventListener("change", async (e) => {
  const sel = e.target.closest("[data-rr-team-role]");
  if (!sel) return;
  const id = sel.getAttribute("data-rr-team-role");
  const role = sel.value;
  const { error } = await sb.from("app_users").update({ role }).eq("id", id);
  if (error) { toast("Save failed: " + error.message, "warn"); loadTeamMembers(); return; }
  toast("Role updated", "success");
});

// Remove member — soft-delete via active=false so any audit/coaching
// rows that reference them still resolve. Keeps the auth.users row
// intact (no privileged admin call needed); the app login gate already
// rejects inactive app_users.
document.addEventListener("click", async (e) => {
  const btn = e.target.closest("[data-rr-team-remove]");
  if (!btn) return;
  const id   = btn.getAttribute("data-rr-team-remove");
  const name = btn.getAttribute("data-rr-team-name-display") || "this teammate";
  if (!(await _rrConfirmDialog({ title: "Remove teammate?", body: `Remove ${name} from the team? They'll lose dashboard access immediately. Re-invite them later if needed.`, confirmLabel: "Remove", danger: true }))) return;
  btn.disabled = true;
  const { error } = await sb.from("app_users").update({ active: false }).eq("id", id);
  if (error) { toast("Remove failed: " + error.message, "warn"); btn.disabled = false; return; }
  toast(`Removed ${name}`, "warn");
  loadTeamMembers();
});

// Open the invite modal.
document.addEventListener("click", (e) => {
  if (e.target.closest("#rr-team-invite-open")) {
    const modal = document.getElementById("modal-team-invite");
    if (!modal) return;
    modal.style.display = "flex";
    document.getElementById("rr-team-invite-email").value = "";
    document.getElementById("rr-team-invite-name").value  = "";
    document.getElementById("rr-team-invite-role").value  = "dispatcher";
    const status = document.getElementById("rr-team-invite-status");
    if (status) status.textContent = "";
    setTimeout(() => document.getElementById("rr-team-invite-email")?.focus(), 50);
  }
});

// Submit the invite — calls the invite-team-member edge function.
document.addEventListener("submit", async (e) => {
  if (e.target?.id !== "rr-team-invite-form") return;
  e.preventDefault();
  const email   = document.getElementById("rr-team-invite-email").value.trim().toLowerCase();
  const name    = document.getElementById("rr-team-invite-name").value.trim();
  const role    = document.getElementById("rr-team-invite-role").value;
  const status  = document.getElementById("rr-team-invite-status");
  const submit  = document.getElementById("rr-team-invite-submit");
  if (!email) return;

  if (status) { status.style.color = "var(--text-subtle)"; status.textContent = "Sending…"; }
  submit.disabled = true;

  try {
    const { data, error } = await sb.functions.invoke("invite-team-member", {
      method: "POST",
      body: { email, full_name: name, role },
    });
    if (error || data?.error) {
      const msg = data?.error || error?.message || "Invite failed";
      if (status) { status.style.color = "var(--red)"; status.textContent = _humanInviteError(msg); }
      submit.disabled = false;
      return;
    }
    if (status) { status.style.color = "var(--green)"; status.textContent = "Invite sent. They'll receive a magic-link email."; }
    toast("Invite sent to " + email, "success");
    setTimeout(() => {
      document.getElementById("modal-team-invite").style.display = "none";
      submit.disabled = false;
      loadTeamMembers();
    }, 900);
  } catch (err) {
    if (status) { status.style.color = "var(--red)"; status.textContent = String(err?.message || err); }
    submit.disabled = false;
  }
});

function _humanInviteError(raw) {
  const m = String(raw);
  if (m.includes("already_on_team"))    return "That email is already on your team.";
  if (m.includes("invalid_email"))      return "That doesn't look like a valid email.";
  if (m.includes("invalid_role"))       return "Pick a valid role.";
  if (m.includes("not_authenticated"))  return "Your session expired — refresh the page and try again.";
  if (m.includes("no_profile"))         return "Your account isn't linked to a tenant.";
  if (m.includes("insufficient_role"))  return "Only owners and ops can invite teammates.";
  return m;
}

// Attendance subtab order is operator-preference.  Drag to reorder;
// the order is persisted per browser via localStorage so it survives
// reloads.  Re-applies on every render of the Drivers view.
const _RR_ATT_TAB_ORDER_KEY = "rr.att.tab-order";
function _rrApplyAttTabOrder() {
  const strip = document.getElementById("rr-att-tabstrip");
  if (!strip) return;
  let order;
  try { order = JSON.parse(localStorage.getItem(_RR_ATT_TAB_ORDER_KEY) || "null"); } catch {}
  if (!Array.isArray(order)) return;
  const byKey = {};
  strip.querySelectorAll("[data-att]").forEach(el => { byKey[el.dataset.att] = el; });
  for (const k of order) if (byKey[k]) strip.appendChild(byKey[k]);
}
function _rrSaveAttTabOrder() {
  const strip = document.getElementById("rr-att-tabstrip");
  if (!strip) return;
  const order = [...strip.querySelectorAll("[data-att]")].map(el => el.dataset.att);
  try { localStorage.setItem(_RR_ATT_TAB_ORDER_KEY, JSON.stringify(order)); } catch {}
}
function _rrInitAttTabDnD() {
  const strip = document.getElementById("rr-att-tabstrip");
  if (!strip || strip.dataset.rrDndReady === "1") return;
  strip.dataset.rrDndReady = "1";
  _rrApplyAttTabOrder();

  let dragged = null;
  strip.addEventListener("dragstart", (e) => {
    const t = e.target.closest("[data-att]");
    if (!t) return;
    dragged = t;
    t.style.opacity = "0.4";
    e.dataTransfer.effectAllowed = "move";
    try { e.dataTransfer.setData("text/plain", t.dataset.att); } catch {}
  });
  strip.addEventListener("dragend", () => {
    if (dragged) dragged.style.opacity = "";
    dragged = null;
  });
  strip.addEventListener("dragover", (e) => {
    if (!dragged) return;
    e.preventDefault();
    const target = e.target.closest("[data-att]");
    if (!target || target === dragged) return;
    const rect = target.getBoundingClientRect();
    const after = (e.clientX - rect.left) > rect.width / 2;
    target.parentElement.insertBefore(dragged, after ? target.nextSibling : target);
  });
  strip.addEventListener("drop", (e) => {
    e.preventDefault();
    _rrSaveAttTabOrder();
  });
}
// Bootstrap once now (in case the user is already on Drivers →
// Attendance) and again after every drSub call so the strip exists.
_rrInitAttTabDnD();

// ─── Sidebar · Today's Plan ────────────────────────────────────────────
// The new default landing for operators. Pulls today's attendance live,
// today's coverage gaps (open shifts), and credential expirations into
// one glanceable view. Polls every 30 s while on the dashboard tab.

let _todayPlanTimer = null;
// Realtime channel for push refreshes when a driver checks in/out or a
// shift status flips. The 30-second poll above is the safety net.
let _todayPlanChannel = null;
let _todayPlanRefreshDebounce = null;

// sessionStorage keys — survive tab navigation, dropped on browser
// close. Used to render last-known data INSTANTLY on tab open while
// fresh data fetches in the background ("stale-while-revalidate").
const _TP_CACHE_KEYS = { att: "rr.tp.att", plan: "rr.tp.plan" };

function _tpCacheRead(key) {
  try {
    const raw = sessionStorage.getItem(key);
    if (!raw) return null;
    const obj = JSON.parse(raw);
    // Drop anything older than 10 minutes — better to fetch fresh.
    if (!obj?.ts || Date.now() - obj.ts > 10 * 60 * 1000) return null;
    return obj.data;
  } catch { return null; }
}
function _tpCacheWrite(key, data) {
  try { sessionStorage.setItem(key, JSON.stringify({ ts: Date.now(), data })); } catch {}
}

// 7-day Today's Plan navigator.  _tpDateIso drives every reader below;
// loadTodayPlan resets it to today on (re-)entry.  The +/- buttons walk
// the date within [today, today+6].  Attendance is only fetched when
// viewing today — future days have no clock-ins yet.
let _tpDateIso = null;
function _tpToday() { return fmtIsoDate(new Date()); }
function _tpMaxDate() {
  const d = new Date(); d.setDate(d.getDate() + 6); return fmtIsoDate(d);
}
function _tpDateShift(deltaDays) {
  const cur = _tpDateIso || _tpToday();
  const d = new Date(cur + "T12:00:00");
  d.setDate(d.getDate() + deltaDays);
  _tpDateGoTo(fmtIsoDate(d));
}
function _tpDateGoTo(iso) {
  const today = _tpToday(); const max = _tpMaxDate();
  if (!iso || iso < today || iso > max) return;
  if (iso === _tpDateIso) return;
  _tpDateIso = iso;
  _tpRenderDateLabel();
  _refreshTodayPlanData();
}
function _tpRenderDateLabel() {
  const iso = _tpDateIso || _tpToday();
  const today = _tpToday();
  const d = new Date(iso + "T12:00:00");
  const label = d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
  const isToday = iso === today;
  const tomorrow = (() => { const t = new Date(); t.setDate(t.getDate()+1); return fmtIsoDate(t); })();
  const prefix = isToday ? "" : (iso === tomorrow ? "Tomorrow · " : "");
  const dateEl = document.getElementById("rr-today-date");
  if (dateEl) dateEl.textContent = prefix + label;
  _tpRenderDayStrip();
}

// Fluent / Outlook-style mini calendar strip · 7 cells covering today
// → today+6. Lives inside #rr-today-plan-shell so it travels with the
// shell between the dashboard's Today nav and the schedule's Today
// sub-view (which mounts the same shell DOM).
function _tpRenderDayStrip() {
  const host = document.getElementById("rr-tp-daystrip");
  if (!host) return;
  const todayIso = _tpToday();
  const activeIso = _tpDateIso || todayIso;
  const maxIso = _tpMaxDate();
  const base = new Date(todayIso + "T12:00:00");
  const cells = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(base.getTime()); d.setDate(d.getDate() + i);
    const iso = fmtIsoDate(d);
    const wd = d.toLocaleDateString(undefined, { weekday: "short" }).slice(0, 3);
    const num = d.getDate();
    const cls = "tp-day-cell"
      + (iso === activeIso ? " is-active" : "")
      + (iso === todayIso ? " is-today" : "");
    const aria = d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
    cells.push(
      `<button type="button" class="${cls}" data-tp-day-iso="${iso}" aria-pressed="${iso === activeIso}" aria-label="${aria}">`
      + `<span class="tp-day-cell-wd">${wd}</span>`
      + `<span class="tp-day-cell-num">${num}</span>`
      + `</button>`
    );
  }
  const onToday = activeIso === todayIso;
  host.innerHTML =
      `<button type="button" class="tp-daystrip-arrow" id="rr-tp-daystrip-prev" title="Previous day" aria-label="Previous day"${activeIso <= todayIso ? " disabled" : ""}>`
    +   `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg>`
    + `</button>`
    + `<div class="tp-daystrip-cells">${cells.join("")}</div>`
    + `<button type="button" class="tp-daystrip-arrow" id="rr-tp-daystrip-next" title="Next day" aria-label="Next day"${activeIso >= maxIso ? " disabled" : ""}>`
    +   `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>`
    + `</button>`
    + `<button type="button" class="tp-daystrip-today${onToday ? " is-on-today" : ""}" id="rr-tp-daystrip-today" aria-label="Jump to today">`
    +   `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>`
    +   `<span>Today</span>`
    + `</button>`;
}

// Subscribe to the two tables that drive the OT headroom column. On
// any change for the current DSP, debounce-trigger a refresh so a
// burst (e.g. mass status update) doesn't fire one RPC per row.
//
// Returns silently if Realtime isn't available or the user has no DSP
// context — the 30s poll still keeps the column moving.
function _tpSubscribeRealtime() {
  // Tear down any prior subscription so we don't accumulate channels
  // on repeat entry to the view.
  if (_todayPlanChannel) {
    try { sb.removeChannel(_todayPlanChannel); }
    catch (e) { console.warn("today plan · channel teardown:", e); }
    _todayPlanChannel = null;
  }
  const dspId = window.RR?.dsp?.id;
  if (!dspId || typeof sb.channel !== "function") return;

  const kick = () => {
    if (_todayPlanRefreshDebounce) clearTimeout(_todayPlanRefreshDebounce);
    _todayPlanRefreshDebounce = setTimeout(() => {
      _todayPlanRefreshDebounce = null;
      if (_tpDateIso === _tpToday() && !document.hidden) {
        _refreshTodayPlanData();
      }
    }, 400);
  };

  const filter = "dsp_id=eq." + dspId;
  _todayPlanChannel = sb.channel("rr-tp-" + dspId)
    .on("postgres_changes", { event: "*", schema: "public", table: "driver_checkins", filter }, kick)
    .on("postgres_changes", { event: "*", schema: "public", table: "shifts",          filter }, kick)
    .subscribe();
}

async function loadTodayPlan() {
  // If the shell drifted into the schedule's Today sub-view and
  // the operator is now visiting the dashboard's Today nav, pull
  // it back to the anchor so the renderer paints into a visible
  // host. Skip when the schedule's Today host is itself visible —
  // that's the case where renderSchedTodayView just mounted the
  // shell there and called us, and yanking it back would race
  // the whole point.
  const schedHost = document.getElementById("rr-sched-today-plan-host");
  const schedHostVisible = !!schedHost?.offsetParent;
  if (!schedHostVisible && typeof _rrMoveTodayShellTo === "function") {
    _rrMoveTodayShellTo("rr-today-plan-anchor");
  }
  const shell = document.getElementById("rr-today-plan-shell");
  if (!shell) return;

  // Make sure fleet settings are loaded so _refreshTodayPlanData knows
  // whether to auto-fire today_roster_auto_assign before rendering.
  if (typeof loadFleetSettings === "function" && !window.RR?.fleetSettings) {
    loadFleetSettings();
  }

  // Reset navigator to today on every (re-)entry.
  _tpDateIso = _tpToday();
  _tpRenderDateLabel();

  if (_todayPlanTimer) clearInterval(_todayPlanTimer);
  _todayPlanTimer = setInterval(() => {
    // Poll whenever the shell is mounted in a VISIBLE host — either
    // the dashboard's Today nav OR the schedule's Today sub-view.
    // offsetParent is null for any element whose ancestor chain
    // includes display:none, so this single check covers both
    // mount points without special-casing.
    const shellVisible = !!document.getElementById("rr-today-plan-shell")?.offsetParent;
    if (shellVisible && !document.hidden && _tpDateIso === _tpToday()) {
      _refreshTodayPlanData();
    } else if (_tpDateIso !== _tpToday()) {
      // Future-day view stays static — no 30s polling.  The user can
      // re-fire from the Today button or refresh manually.
    } else {
      clearInterval(_todayPlanTimer); _todayPlanTimer = null;
      if (_todayPlanChannel) {
        try { sb.removeChannel(_todayPlanChannel); }
        catch (e) { console.warn("today plan · channel teardown:", e); }
        _todayPlanChannel = null;
      }
    }
  }, 30000);

  // Realtime push: re-fetch the roster the moment a driver checks in,
  // checks out, or a shift status flips. Drives the "Until OT" column
  // so dispatchers see headroom move in <1s when deciding whether to
  // pull a backup. The 30s interval above is the safety net for pure
  // clock advancement and missed realtime events.
  _tpSubscribeRealtime();

  // Render the skeleton FIRST so the page never sits on a single spinner.
  // Re-render whenever the expected IDs are missing — handles upgrading
  // an open tab from an older live.js that wrote a different skeleton.
  // Single unified roster card.  Wave summary cards, the separate
  // attendance approvals tool, extras list, and the coverage tile are
  // all absorbed into the roster body — one table grouped by wave with
  // status pills, inline approve/VTO/deny actions, and assigned vans.
  // Weather card removed from the Today plan per operator direction —
  // the radar still has its own surface elsewhere if/when re-enabled.
  const skeletonOk = !!document.getElementById("rr-tp-roster")
                  && !!document.getElementById("rr-tp-kpis")
                  && !!document.getElementById("rr-tp-rightrail")
                  && !!document.getElementById("rr-tp-cov")
                  && !!document.getElementById("rr-tp-daystrip");
  if (!skeletonOk) {
    shell.dataset.rrPlanShell = "1";
    // Layout (top → bottom):
    //   day strip · day picker
    //   tp-kpis   · minimal dot-pill KPI strip (replaces the old
    //               4-chip card; same numbers, Fluent voice)
    //   tp-mainrow · roster + the Coverage rail (open shifts with no
    //                driver + expiring DLs from today_plan()). The rail
    //                sits beside the roster only on wide viewports and
    //                stacks below it otherwise — see .tp-mainrow CSS.
    const skelRow = `<div class="tp-skel-row"><span class="rr-skel rr-skel-circle" style="width:28px;height:28px;flex:0 0 auto"></span><span class="rr-skel rr-skel-md" style="width:24%"></span><span class="rr-skel rr-skel-sm" style="width:14%"></span><span class="rr-skel rr-skel-sm" style="width:18%"></span><span class="rr-skel rr-skel-sm" style="width:12%;margin-left:auto"></span></div>`;
    const skelKpi = `<span class="tp-kpi-pill is-skel"><span class="rr-skel rr-skel-circle" style="width:9px;height:9px"></span><span class="rr-skel rr-skel-sm" style="width:92px"></span></span>`;
    shell.innerHTML = `
      <div id="rr-tp-daystrip" class="tp-daystrip" role="group" aria-label="Pick a day"></div>
      <div id="rr-tp-kpis" class="tp-kpis" aria-busy="true" aria-label="Today plan overview">
        ${skelKpi}${skelKpi}${skelKpi}${skelKpi}
      </div>
      <div id="rr-tp-ridealong-alerts"></div>
      <div id="rr-tp-weekrisk" class="tp-weekrisk-mount"></div>
      <div id="rr-tp-mainrow" class="tp-mainrow">
        <div id="rr-tp-roster" class="card card-flush">
          <div class="rr-tp-section-head">Today's roster</div>
          <div class="tp-skel-list" aria-busy="true">${skelRow}${skelRow}${skelRow}${skelRow}${skelRow}${skelRow}</div>
        </div>
        <aside id="rr-tp-rightrail" class="tp-rightrail card card-flush" aria-label="Coverage">
          <div id="rr-tp-cov">
            <div class="card-section-head">Coverage</div>
            <div class="tp-skel-list" aria-busy="true">${skelRow}${skelRow}</div>
          </div>
        </aside>
      </div>`;
  }

  // Paint the day strip now that #rr-tp-daystrip exists in the shell.
  _tpRenderDayStrip();

  // Stale-while-revalidate: render last-known cached data instantly so
  // the page is filled in the same frame the operator clicks Today.
  // Wrap in try/catch — if the cache shape from an earlier live.js
  // doesn't match the new render code, we'd rather drop the cache than
  // freeze the page on a "Loading…" placeholder.
  const cachedAtt  = _tpCacheRead(_TP_CACHE_KEYS.att);
  const cachedPlan = _tpCacheRead(_TP_CACHE_KEYS.plan);
  try { if (cachedAtt)  _renderTpAttendance(cachedAtt,  null); }
  catch (e) { console.warn("today plan · stale attendance cache:", e); sessionStorage.removeItem(_TP_CACHE_KEYS.att); }
  try { if (cachedPlan) _renderTpCoverage(cachedPlan,   null); }
  catch (e) { console.warn("today plan · stale coverage cache:", e);   sessionStorage.removeItem(_TP_CACHE_KEYS.plan); }

  _refreshTodayPlanData();
}

async function _refreshTodayPlanData() {
  const todayIso = _tpToday();
  const viewIso  = _tpDateIso || todayIso;
  const isToday  = viewIso === todayIso;

  // Auto-assign vans for gaps before reading the roster so the
  // unified renderer paints a clean state on first frame.  Silent on
  // failure — the operator can re-run from the card header button.
  try {
    if (window.RR?.fleetSettings?.auto_van_assign === true) {
      await sb.rpc("today_roster_auto_assign", { p_date: viewIso });
    }
  } catch (e) { console.warn("today plan · auto-assign:", e); }

  // Attendance is today-only (it reads live clock-ins).  Skip the call
  // when the operator is viewing a future day; the renderer will draw
  // a planning-mode header instead.
  //
  // overtime_intelligence() drives the "until OT" sub-line on each
  // roster row. Pulled in parallel; a failure here just hides the line.
  const [attRes, rosterRes, otRes, planRes, fleetRes, pipeRes, riskRes] = await Promise.allSettled([
    isToday ? sb.rpc("today_attendance") : Promise.resolve({ data: null, error: null }),
    sb.rpc("today_roster", { p_date: viewIso }),
    sb.rpc("overtime_intelligence"),
    // Coverage rail: open shifts + expiring DLs. today_plan() reads
    // live shift state for the current date only, so skip it on
    // future-day views (the renderer paints a static note instead).
    isToday ? sb.rpc("today_plan") : Promise.resolve({ data: null, error: null }),
    // Command-center tiles: current-state fleet readiness + hiring pipeline.
    // Date-independent; a failure just hides the tile.
    sb.rpc("fleet_execution_summary"),
    sb.rpc("pipeline_counts"),
    // Call-out exposure: drivers on an active (unresolved) FINAL corrective
    // action are the "High Risk" population most likely to call out. FINAL-only
    // — matching the roster / Schedule Callout Exposure definition exactly
    // (termination was dropped per operator definition, sw.js nonce .53) so the
    // two surfaces never disagree. Just the at-risk driver ids.
    sb.from("coachings").select("driver_id").eq("dsp_id", window.RR.dsp.id).is("archived_at", null).is("resolved_at", null).eq("severity", "final"),
  ]);

  const attData    = (attRes.status === "fulfilled"    ? attRes.value.data    : null);
  const attError   = (attRes.status === "fulfilled"    ? attRes.value.error   : attRes.reason);
  const rosterData = (rosterRes.status === "fulfilled" ? rosterRes.value.data : null);
  const rosterError= (rosterRes.status === "fulfilled" ? rosterRes.value.error: rosterRes.reason);
  const otData     = (otRes.status === "fulfilled"     ? otRes.value.data     : null);
  if (otRes.status === "fulfilled" && otRes.value.error) {
    console.warn("today plan · overtime_intelligence:", otRes.value.error);
  }

  const planData  = (planRes.status === "fulfilled" ? planRes.value.data  : null);
  const planError = (planRes.status === "fulfilled" ? planRes.value.error : planRes.reason);
  const fleetData = (fleetRes.status === "fulfilled" ? fleetRes.value.data : null);
  const pipeData  = (pipeRes.status === "fulfilled"  ? pipeRes.value.data  : null);
  // At-risk drivers (open Final/Termination CA). Null on failure → pill hides.
  const riskData  = (riskRes.status === "fulfilled"  ? riskRes.value.data  : null);

  if (attData)  _tpCacheWrite(_TP_CACHE_KEYS.att,  attData);
  if (planData) _tpCacheWrite(_TP_CACHE_KEYS.plan, planData);

  // Coverage rail. On future days today_plan() would return today's
  // gaps, not the viewed day's — paint a static note instead of
  // misleading numbers.
  try {
    if (isToday) {
      _renderTpCoverage(planData, planError);
    } else {
      const covEl = document.getElementById("rr-tp-cov");
      if (covEl) covEl.innerHTML = `<div class="card-section-head">Coverage</div>
        <div style="padding:18px;color:var(--text-subtle);font-size:var(--fs-sm);text-align:center">Live coverage is shown for today only.</div>`;
    }
  } catch (e) { console.warn("today plan · coverage render:", e); }

  // Update the meta line (page-level scheduled-driver count + on-app).
  // Pass rosterData so the future-day KPIs can synthesize counts the
  // same way the roster card does.
  try { _renderTpMeta(attData, rosterData, otData, planData, fleetData, pipeData, riskData); } catch (e) { console.warn("tp meta:", e); }

  // Week-ahead exposure heat strip (reads the schedule's canonical exposure /
  // its persisted snapshot). Best-effort; hides itself when there's no data.
  try { _renderTpWeekRisk(); } catch (e) { console.warn("tp week-risk:", e); }

  // The single unified roster card replaces the old four-card layout.
  try { _renderTpUnifiedRoster(attData, rosterData, attError || rosterError, otData); }
  catch (e) { console.error("today plan · unified render failed:", e); _renderTpUnifiedRoster(null, null, e, null); }

  // Orphaned ride-alongs (trainer called off / shift moved while a trainee
  // was paired with them). Surface only on the today/future view, not on
  // historical days.
  try { if (isToday || viewIso > todayIso) _refreshRideAlongAlerts(viewIso); }
  catch (e) { console.warn("ride-along alerts:", e); }
}

async function _refreshRideAlongAlerts(viewIso) {
  const slot = document.getElementById("rr-tp-ridealong-alerts");
  if (!slot) return;
  // Look ahead 14 days from the viewed date — catches both today's
  // orphan and any pre-activate pairings whose partner moved.
  const to = (() => {
    const d = new Date(viewIso + "T12:00:00"); d.setDate(d.getDate() + 14);
    return d.toISOString().slice(0, 10);
  })();
  const { data, error } = await sb.rpc("orphaned_ride_alongs", { p_from: viewIso, p_to: to });
  if (error) { slot.innerHTML = ""; return; }
  const rows = data || [];
  if (!rows.length) { slot.innerHTML = ""; return; }
  const fmtD = (x) => x ? new Date(x + "T12:00:00").toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) : "—";
  slot.innerHTML = rows.map(r => `
    <div class="card" style="padding:12px 16px;margin-bottom:8px;border-left:3px solid var(--red);display:flex;align-items:center;gap:12px;flex-wrap:wrap">
      <div style="font-size:18px">⚠</div>
      <div style="flex:1;min-width:240px">
        <div style="font-weight:600;font-size:var(--fs-sm)">Ride-along orphaned · ${escapeHtml(fmtD(r.ride_date))}</div>
        <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${escapeHtml(r.trainer_name || "Trainer")} → ${escapeHtml(r.trainee_name || "Trainee")} · ${escapeHtml(r.reason || "")}</div>
      </div>
      <button class="btn btn-sm" data-rr-tp-orphan-open="${escapeHtml(r.trainee_id)}">Open driver</button>
    </div>`).join("");
  slot.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-rr-tp-orphan-open]");
    if (!btn) return;
    const did = btn.getAttribute("data-rr-tp-orphan-open");
    if (did && typeof openDriverDrawer === "function") openDriverDrawer(did);
  }, { once: true });
}

function _renderTpAttendance(data, error) {
  const wavesEl  = document.getElementById("rr-tp-waves");
  const metaEl   = document.getElementById("rr-tp-meta");
  const toolEl   = document.getElementById("rr-tp-tool");
  const extrasEl = document.getElementById("rr-tp-extras");
  if (!wavesEl || !metaEl || !toolEl || !extrasEl) return;

  if (error) {
    toolEl.innerHTML = `<div class="card-section-head">Daily attendance · approvals</div>
      <div style="padding:18px;color:var(--red);font-size:var(--fs-sm);text-align:center">${escapeHtml(error.message || String(error))}</div>`;
    return;
  }

  const attRows = data?.rows || [];

  // ── Wave-level rollup ──────────────────────────────────────────────
  // For each wave: scheduled, checked-in (working OR completed), and
  // the rest (not-yet-checked-in). Percentages are computed against
  // scheduled. Operators read this top-down at the start of the day.
  const waveBuckets = new Map();
  for (const r of attRows) {
    const w = r.wave_index ?? 0;
    if (!waveBuckets.has(w)) waveBuckets.set(w, { scheduled: 0, checkedIn: 0, notIn: 0, tardy: 0, ncns: 0 });
    const b = waveBuckets.get(w);
    b.scheduled++;
    if (r.computed_outcome === "checked_in" || r.computed_outcome === "checked_out") b.checkedIn++;
    else b.notIn++;
    if (r.computed_outcome === "tardy") b.tardy++;
    if (r.computed_outcome === "ncns")  b.ncns++;
  }

  const pctOf = (a, b) => b > 0 ? Math.round((a / b) * 100) : 0;
  // Neutral palette throughout — operator wants the numbers to carry
  // the message, not the dashboard's verdict.
  const waveCard = (wave, b) => {
    const inPct  = pctOf(b.checkedIn, b.scheduled);
    const outPct = 100 - inPct;
    const flagged = b.tardy + b.ncns;
    return `
      <div class="card card-compact" style="display:flex;flex-direction:column;gap:var(--s-3)">
        <div style="display:flex;justify-content:space-between;align-items:baseline">
          <div style="font-size:var(--fs-md);font-weight:700;color:var(--text)">Wave ${escapeHtml(String(wave))}</div>
          <div class="u-xs-subtle">${b.scheduled} scheduled</div>
        </div>
        <div style="display:flex;gap:var(--s-3)">
          <div style="flex:1">
            <div style="font-size:var(--fs-xs);color:var(--text-subtle);font-weight:600;letter-spacing:.04em;text-transform:uppercase">Checked in</div>
            <div style="font-size:var(--fs-xxl);font-weight:700;color:var(--text)">${b.checkedIn}<span style="font-size:var(--fs-md);color:var(--text-subtle);font-weight:600;margin-left:6px">${inPct}%</span></div>
          </div>
          <div style="flex:1">
            <div style="font-size:var(--fs-xs);color:var(--text-subtle);font-weight:600;letter-spacing:.04em;text-transform:uppercase">Not in</div>
            <div style="font-size:var(--fs-xxl);font-weight:700;color:var(--text)">${b.notIn}<span style="font-size:var(--fs-md);color:var(--text-subtle);font-weight:600;margin-left:6px">${outPct}%</span></div>
          </div>
        </div>
        <div style="height:6px;background:var(--canvas);border-radius:var(--r-pill);overflow:hidden;display:flex">
          <div style="width:${inPct}%;background:var(--text-muted)"></div>
          <div style="width:${outPct}%;background:var(--border-strong)"></div>
        </div>
        ${flagged > 0
          ? `<div style="font-size:var(--fs-xs);color:var(--text);font-weight:600">${b.tardy} tardy · ${b.ncns} NCNS</div>`
          : `<div class="u-xs-subtle">No issues this wave</div>`}
      </div>`;
  };

  const sortedWaves = [...waveBuckets.entries()].sort((a, b) => a[0] - b[0]);
  wavesEl.innerHTML = sortedWaves.length === 0
    ? `<div class="card rr-empty-inline">No drivers scheduled today.</div>`
    : sortedWaves.map(([w, b]) => waveCard(w, b)).join("");

  // ── Meta strip (service-type breakdown + as-of) ────────────────────
  const bySvc = {};
  for (const r of attRows) {
    const sv = r.service_type_code || "—";
    if (!bySvc[sv]) bySvc[sv] = { count: 0, color: r.service_type_color || "#94a3b8" };
    bySvc[sv].count++;
  }
  const svcChips = Object.entries(bySvc).map(([code, v]) =>
    `<span style="display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:var(--r-lg);background:${v.color}22;color:${v.color};font-size:var(--fs-xs);font-weight:600;margin-right:4px">${escapeHtml(code)} · ${v.count}</span>`
  ).join("");
  metaEl.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;gap:var(--s-3);flex-wrap:wrap">
      <div>${svcChips || "<span style='color:var(--text-subtle)'>No service-type breakdown</span>"}</div>
      <div class="u-xs-subtle">As of ${escapeHtml(new Date(data.as_of).toLocaleTimeString())}</div>
    </div>`;

  // ── Daily attendance approvals card ────────────────────────────────
  // Anyone tardy / NCNS / missed-reported needs a leader decision today.
  // We show their current points + standing + recommended action and
  // expose Approve / Deny buttons.  Persistence is the next phase per
  // the product spec; for now the buttons just mark the row visually so
  // the operator can see what they've reviewed.
  const flagged = attRows.filter(r =>
    ["tardy", "ncns", "missed_reported"].includes(r.computed_outcome)
  );
  _renderTpDailyTool(flagged);

  // ── Extra drivers (Ex / cushion) roster ────────────────────────────
  const extras = attRows.filter(r => r.is_cushion);
  const extrasRows = extras.length === 0
    ? `<div class="rr-empty-inline">No extras scheduled today.</div>`
    : extras.map(r => {
        const t = r.starts_at ? new Date(r.starts_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : "—";
        // Neutral chip — Today page is a no-stoplight zone.
        const tone = { bg: "var(--canvas)", fg: "var(--text-muted)" };
        const label = _RR_OUTCOME_LABEL[r.computed_outcome] || r.computed_outcome;
        const initials = (r.driver_name || "?").split(/\s+/).map(p => p[0]).filter(Boolean).slice(0,2).join("").toUpperCase();
        return `
          <div style="display:grid;grid-template-columns:30px 1fr auto;gap:var(--s-2-5);align-items:center;padding:var(--s-2) 14px;border-top:1px solid var(--border)">
            <div class="avatar-sm" data-rr-driver-id="${escapeHtml(r.driver_id)}" style="width:30px;height:30px;font-size:var(--fs-xs)">${escapeHtml(initials)}</div>
            <div style="min-width:0">
              <div style="font-size:var(--fs-md);font-weight:600" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml(r.driver_name)}</div>
              <div class="u-xs-subtle">${escapeHtml(r.station_code || "—")} · Wave ${r.wave_index ?? 0} · ${escapeHtml(t)}</div>
            </div>
            <span style="background:${tone.bg};color:${tone.fg};font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:3px 8px;border-radius:var(--r-lg)">${escapeHtml(label)}</span>
          </div>`;
      }).join("");
  extrasEl.innerHTML = `
    <div class="card-section-head">
      Extra drivers (Ex) <span style="color:var(--text-subtle);font-weight:600">· ${extras.length}</span>
    </div>
    ${extrasRows}`;
}

// Daily approvals tool — pulls each flagged driver's current
// attendance points from the last `decay_days` of shift events, plots
// them against the policy's warn / action thresholds, and recommends
// the next step.  The Approve / Deny buttons are intentionally inert
// for now (visual only); persistence + driver notifications are the
// next phase per product direction.
async function _renderTpDailyTool(flagged) {
  const toolEl = document.getElementById("rr-tp-tool");
  if (!toolEl) return;
  // Make sure the risk-score cache is warm before we render; the
  // paint pass below will pick it up via data-rr-risk-driver slots.
  await _rrRiskLoad();

  const head = (n) => `
    <div class="card-section-head">
      Daily attendance · approvals <span style="color:var(--text-subtle);font-weight:600">· ${n}</span>
    </div>`;

  if (flagged.length === 0) {
    toolEl.innerHTML = `${head(0)}
      <div style="padding:var(--s-6);text-align:center;color:var(--green);font-size:var(--fs-md);font-weight:600">✓ No tardies or no-shows to approve right now.</div>`;
    return;
  }

  const policy = _getAttPolicy();
  const evalP  = _evalPolicy();
  const dspId  = window.RR?.dsp?.id;
  const since  = new Date(Date.now() - (evalP.decay_days || 90) * 86400000)
    .toISOString().slice(0, 10);

  // Per-event point values — same as the Report.  Missing event
  // blocks contribute zero (the operator chose not to count that
  // event type).
  const ptsCallout = evalP.events.callout ? Number(evalP.events.callout.points) || 0 : 0;
  const ptsNoshow  = evalP.events.no_show ? Number(evalP.events.no_show.points) || 0 : 0;
  const ptsLate    = evalP.events.late    ? Number(evalP.events.late.points)    || 0 : 0;
  const pointsForEvent = (st) =>
      st === "late"       ? ptsLate
    : st === "called_off" ? ptsCallout
    : st === "no_show"    ? ptsNoshow
    : 0;
  const pointsForOutcome = (oc) =>
      oc === "tardy"            ? ptsLate
    : oc === "missed_reported"  ? ptsCallout
    : oc === "ncns"             ? ptsNoshow
    : 0;

  // Map driver_id → cumulative points already accrued in window.
  let pointsMap = new Map();
  if (evalP.enabled) {
    const ids = flagged.map(r => r.driver_id);
    const { data: hist } = await sb.from("shifts")
      .select("driver_id, status")
      .eq("dsp_id", dspId)
      .in("driver_id", ids)
      .in("status", ["called_off", "no_show", "late"])
      .gte("date", since);
    for (const h of (hist || [])) {
      const p = pointsForEvent(h.status);
      if (p > 0) pointsMap.set(h.driver_id, (pointsMap.get(h.driver_id) || 0) + p);
    }
  }

  // Neutral palette — labels carry the meaning; no stoplight tints.
  const standing = (rung) => {
    if (!evalP.enabled) return { label: "Policy off", tone: "var(--text-subtle)" };
    if (!rung)          return { label: "Good standing", tone: "var(--text-subtle)" };
    if (rung.severity === "verbal") return { label: "Warning", tone: "var(--text-muted)" };
    return { label: "Action", tone: "var(--text)" };
  };

  // levelFor → severity string from the matching ladder rung; null
  // when the driver hasn't crossed the lowest threshold.
  // NCNS-terminates short-circuits to termination regardless of points.
  const levelFor = (outcome, points) => {
    if (!evalP.enabled) return null;
    if (outcome === "ncns" && evalP.ncns_terminates) return "termination";
    const rung = _evalLadderRung(evalP, points);
    return rung ? rung.severity : null;
  };
  const recommend = (outcome, level) => {
    if (!evalP.enabled) return "Logged · policy is off";
    if (level === "termination") return "Termination · review &amp; confirm";
    if (level === "final")       return "Final written warning · 1 step before termination";
    if (level === "written")     return "Written warning · log conversation";
    if (level === "verbal")      return "Verbal coaching · log conversation";
    if (outcome === "ncns")  return "Confirm no-call / no-show";
    if (outcome === "tardy") return "Note tardy · no formal action";
    return "Acknowledge missed day";
  };
  // Lookup the matching ladder rung's auto_fire + delivery — the
  // builder's source of truth.  Master auto_coaching toggle off
  // disables every auto-fire regardless.
  const rungFor = (level) => (evalP.ladder || []).find(r => r.severity === level) || null;
  const willAutoFire = (level) => {
    if (!evalP.enabled || !evalP.auto_coaching) return false;
    if (!level || level === "termination") return false;
    const r = rungFor(level);
    return !!(r && r.auto_fire);
  };
  const deliveryFor = (level) => {
    const r = rungFor(level);
    return r?.delivery || "ack";
  };

  const rows = flagged.map(r => {
    const before = pointsMap.get(r.driver_id) || 0;
    const add = (evalP.enabled ? pointsForOutcome(r.computed_outcome) : 0);
    const after = before + add;
    const lvl = levelFor(r.computed_outcome, after);
    const auto = willAutoFire(lvl);
    const st  = standing(after);
    const rec = recommend(r.computed_outcome, lvl);
    const initials = (r.driver_name || "?").split(/\s+/).map(p => p[0]).filter(Boolean).slice(0,2).join("").toUpperCase();
    // Today page is neutral — no stoplight chip on the daily approvals.
    const tone = { bg: "var(--canvas)", fg: "var(--text-muted)" };
    const label = _RR_OUTCOME_LABEL[r.computed_outcome] || r.computed_outcome;
    return `
      <div class="rr-tp-tool-row" data-driver-id="${escapeHtml(r.driver_id)}"
           style="display:grid;grid-template-columns:36px minmax(160px,1fr) 130px 1fr auto;gap:var(--s-3-5);align-items:center;padding:var(--s-3) var(--s-3-5);border-top:1px solid var(--border)">
        <div class="avatar-sm" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml(initials)}</div>
        <div style="min-width:0">
          <div style="display:flex;align-items:center;gap:var(--s-2);flex-wrap:wrap">
            <div style="font-size:var(--fs-md);font-weight:600" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml(r.driver_name)}</div>
            <span data-rr-risk-driver="${escapeHtml(r.driver_id)}"></span>
          </div>
          <div class="u-xs-subtle">${escapeHtml(r.station_code || "—")} · Wave ${r.wave_index ?? 0}</div>
        </div>
        <div>
          <span style="background:${tone.bg};color:${tone.fg};font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:3px 8px;border-radius:var(--r-lg)">${escapeHtml(label)}</span>
        </div>
        <div style="min-width:0">
          <div style="font-size:var(--fs-sm);color:var(--text)"><strong>${after} occ${after === 1 ? "" : "s"}</strong> · <span style="color:${st.tone};font-weight:600">${st.label}</span></div>
          <div class="u-xs-subtle">Next: ${rec}${auto ? " · auto-fires on Approve" : ""}</div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end">
          <button class="btn btn-sm btn-primary"
                  data-rr-tp-approve="1"
                  data-shift-id="${escapeHtml(r.shift_id)}"
                  data-outcome="${escapeHtml(r.computed_outcome)}"
                  data-driver-name="${escapeHtml(r.driver_name)}"
                  data-level="${escapeHtml(lvl || '')}"
                  data-auto-fire="${auto ? '1' : '0'}"
                  data-delivery="${escapeHtml(deliveryFor(lvl))}"
                  type="button">Confirm</button>
          <button class="btn btn-sm"
                  data-rr-tp-vto="1"
                  data-shift-id="${escapeHtml(r.shift_id)}"
                  data-outcome="${escapeHtml(r.computed_outcome)}"
                  data-driver-name="${escapeHtml(r.driver_name)}"
                  type="button">VTO</button>
          <button class="btn btn-sm"
                  data-rr-tp-deny="1"
                  data-shift-id="${escapeHtml(r.shift_id)}"
                  data-outcome="${escapeHtml(r.computed_outcome)}"
                  data-driver-name="${escapeHtml(r.driver_name)}"
                  data-level="${escapeHtml(lvl || '')}"
                  type="button">Excuse</button>
        </div>
      </div>`;
  }).join("");

  // Footer summary — what happens on Confirm given the current
  // policy + auto-coaching toggles.
  let autoCoachNote;
  if (!evalP.enabled) {
    autoCoachNote = "Attendance policy is OFF — Confirm just stamps the shift; coach manually from the Event log.";
  } else if (!evalP.auto_coaching) {
    autoCoachNote = "Auto-coaching is OFF — Confirm just stamps the shift; fire coachings manually from the Attendance Report.";
  } else {
    const levels = (evalP.ladder || []).filter(r => r.auto_fire && r.severity !== "termination").map(r => r.severity);
    autoCoachNote = levels.length === 0
      ? "Auto-coaching is ON but no ladder rungs are set to auto-fire. Confirm just stamps the shift."
      : "Auto-fires + messages the driver in the RouteReady app when the driver crosses: " + levels.join(", ") + ".";
  }

  toolEl.innerHTML = `${head(flagged.length)}${rows}
    <div style="padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);border-top:1px solid var(--border);font-size:var(--fs-xs);color:var(--text-subtle)">
      ${escapeHtml(autoCoachNote)}
    </div>`;
  _rrRiskPaint(toolEl);
}

// Approve / decline on the daily tool.  Approve hits the
// attendance_decide RPC (which stamps shifts.status, writes a coaching
// row, and DMs the driver if auto_coaching is on).  Decline opens a
// notes prompt — server enforces notes on deny.
// Auto-assign vans for today — fills the "No van" gaps with per-day
// overrides.  Confirmation step lists the gap count + names so the
// operator isn't surprised.  Re-renders the roster on success.
document.addEventListener("click", async (e) => {
  const autoBtn = e.target.closest("[data-rr-tp-auto-assign]");
  if (autoBtn) {
    e.preventDefault();
    if (autoBtn.disabled) return;
    autoBtn.disabled = true;
    const origLabel = autoBtn.innerHTML;
    autoBtn.innerHTML = `<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10" stroke-dasharray="40 20"><animateTransform attributeName="transform" type="rotate" from="0 12 12" to="360 12 12" dur="1s" repeatCount="indefinite"/></circle></svg> Assigning…`;
    try {
      const todayIso = fmtIsoDate(new Date());
      const { data, error } = await sb.rpc("today_roster_auto_assign", { p_date: todayIso });
      if (error) { toast("Auto-assign failed: " + error.message, "warn"); return; }
      const assigned   = (data && data.assigned_count)   || 0;
      const unassigned = (data && data.unassigned_count) || 0;
      if (assigned === 0 && unassigned === 0) {
        toast("No gaps to assign — every scheduled driver already has a van.", "ok");
      } else if (unassigned === 0) {
        toast(`Assigned ${assigned} van${assigned === 1 ? "" : "s"}.`, "ok");
      } else {
        toast(`Assigned ${assigned} · ${unassigned} couldn't be matched (no van available).`, "warn");
      }
      // Refresh the unified roster (attendance + van resolution).
      _tpReloadRoster();
    } finally {
      autoBtn.disabled = false;
      autoBtn.innerHTML = origLabel;
    }
    return;
  }

  // Inline van picker — click any van cell or "Assign van" chip on
  // the Today's roster to open the popover.
  const pickEl = e.target.closest("[data-rr-tp-pick-van]");
  if (pickEl) {
    e.preventDefault();
    e.stopPropagation();
    _tpOpenVanPicker(pickEl);
    return;
  }

  const ap  = e.target.closest("[data-rr-tp-approve]");
  const dn  = e.target.closest("[data-rr-tp-deny]");
  const vto = e.target.closest("[data-rr-tp-vto]");
  if (!ap && !dn && !vto) return;
  e.preventDefault();
  const btn = ap || dn || vto;
  const row = btn.closest(".rr-tp-tool-row");
  if (!row) return;

  const shiftId    = btn.dataset.shiftId;
  const outcome   = btn.dataset.outcome;
  const driverName = btn.dataset.driverName || "driver";

  // Excuse → notes required (same prompt as before, just renamed).
  // VTO    → notes optional ("offered VTO Wednesday — accepted" etc.).
  let notes = null;
  let decision = "approve";
  if (dn) {
    decision = "deny";
    const reason = window.prompt(
      `Excuse ${driverName}'s ${outcome.replace(/_/g, " ")}?\n\nNotes are required — explain why this event is excused (e.g. "approved leave", "system glitch", "documentation provided").`
    );
    if (reason === null) return;
    if (!reason.trim()) { toast("Notes required to excuse", "warn"); return; }
    notes = reason.trim();
  } else if (vto) {
    decision = "vto";
    const reason = window.prompt(
      `Mark ${driverName}'s shift as VTO?\n\nOptional notes (who offered VTO, why, etc.).`,
      ""
    );
    if (reason === null) return;
    notes = reason.trim() || null;
  }

  const btnCell = btn.parentElement;
  btnCell.innerHTML = `<span class="u-xs-subtle">Saving…</span>`;

  const level    = btn.dataset.level || null;
  const autoFire = btn.dataset.autoFire === "1";
  const delivery = btn.dataset.delivery || null;

  const { data, error } = await sb.rpc("attendance_decide", {
    p_shift_id:  shiftId,
    p_outcome:   outcome,
    p_decision:  decision,
    p_notes:     notes,
    // Auto-fire is owned by the DB trigger (trg_shift_autocoach) now — it
    // recomputes points from real shift data when the shift is approved, so
    // it can't miss the way the old JS-computed p_auto_fire could. Pass false
    // here so attendance_decide doesn't ALSO fire and double-coach.
    p_auto_fire: false,
    p_level:     level,
    p_delivery:  ap ? delivery : null,
  });

  if (error) {
    toast("Save failed: " + (error.message || String(error)), "warn");
    btnCell.innerHTML = `<span style="font-size:var(--fs-xs);color:var(--red)">${escapeHtml(error.message || "Failed")}</span>`;
    return;
  }

  const verb = ap ? "Approved" : (vto ? "Marked VTO" : "Excused");
  const tone = ap ? "var(--green)" : "var(--text-subtle)";
  btnCell.innerHTML = `<span style="font-size:var(--fs-xs);font-weight:700;color:${tone};letter-spacing:.04em;text-transform:uppercase">${escapeHtml(verb)}</span>`;
  const tailParts = [];
  // The trigger coaches on approve when the crossed rung auto-fires; reflect
  // that intent here (data.auto_fired no longer comes from attendance_decide).
  if (ap && autoFire) tailParts.push("driver coached");
  else if (ap)        tailParts.push("queued for coaching drawer");
  const tail = tailParts.length ? " · " + tailParts.join(" · ") : "";
  toast(`${verb}${tail}`, "success");
  // Fade + remove the row so the operator's queue visibly shrinks.
  // 600ms gives them time to register the inline confirmation pill
  // before it disappears.  After removal, refresh the Today's Plan
  // data so the wave KPIs reflect the new shift status.
  row.style.transition = "opacity .35s ease, transform .35s ease, max-height .35s ease, padding .35s ease, margin .35s ease";
  setTimeout(() => {
    row.style.opacity = "0";
    row.style.transform = "translateX(8px)";
    row.style.maxHeight = "0";
    row.style.paddingTop = "0";
    row.style.paddingBottom = "0";
    row.style.marginTop = "0";
    row.style.marginBottom = "0";
    row.style.overflow = "hidden";
    setTimeout(() => {
      row.remove();
      if (typeof _refreshTodayPlanData === "function") _refreshTodayPlanData();
      // Approve / VTO updates shifts.status; bring the Attendance Report
      // in sync immediately so points reconcile without a manual nav.
      // (Excuse / deny doesn't change shift status, so the report is
      // already consistent.)
      if ((ap || vto) && typeof loadAttendanceLive === "function") loadAttendanceLive();
    }, 380);
  }, 600);
});

// ─── Unified Today's roster (attendance + vans, grouped by wave) ────
// Source of truth for the home page's morning surface.  Absorbs:
//   • today_attendance.rows (computed_outcome, decision, wave_index,
//     is_cushion, checked_in_at, …)
//   • today_roster array (van resolution: name, plate, via,
//     covering_for, gap_kind)
// Joined by shift_id; grouped into one section per wave; each row
// renders driver + time + station/route (+ Ex chip) + van (click =
// picker) + status pill + inline approve/VTO/deny when appropriate.

// Status pill (Scheduled / Checked-in / Late / NCNS / …) — derived
// from today_attendance.computed_outcome but with the dispatcher-
// facing labels the user asked for, not the internal enum.
function _tpStatusPill(r) {
  const out = r?.computed_outcome || "waiting";
  const decided = !!r?.decision;
  const map = {
    waiting:          ["Scheduled",   "var(--canvas)",     "var(--text-muted)"],
    ready_to_checkin: ["Scheduled",   "var(--canvas)",     "var(--text-muted)"],
    checked_in:       ["Checked-in",  "var(--green-soft)", "var(--green)"],
    checked_out:      ["Completed",   "var(--green-soft)", "var(--green)"],
    tardy:            ["Late",        "var(--amber-soft)", "var(--amber-dark)"],
    ncns:             ["NCNS",        "var(--red-soft)",   "var(--red)"],
    missed_reported:  ["Called off",  "var(--amber-soft)", "var(--amber-dark)"],
  };
  const [label, bg, fg] = map[out] || ["—", "var(--canvas)", "var(--text-subtle)"];
  const dot = (out === "checked_in" || out === "checked_out") ? "var(--green)"
            : (out === "tardy" || out === "missed_reported") ? "var(--amber)"
            : (out === "ncns") ? "var(--red)"
            : "transparent";
  const dotMarkup = dot === "transparent" ? "" : `<span style="width:6px;height:6px;border-radius:50%;background:${dot};display:inline-block;margin-right:6px;vertical-align:middle"></span>`;
  const decidedTag = decided ? ` · <span style="font-weight:600;color:var(--text-muted)">${escapeHtml(r.decision)}</span>` : "";
  return `<span style="display:inline-flex;align-items:center;font-size:var(--fs-xs);font-weight:700;letter-spacing:.03em;padding:3px 9px;border-radius:var(--r-pill);background:${bg};color:${fg};white-space:nowrap">${dotMarkup}${escapeHtml(label)}${decidedTag}</span>`;
}

// Approve / VTO / Deny buttons.  Wired to the existing data-rr-tp-*
// handlers already in this file, so behavior is identical to the
// stand-alone attendance tool the unified roster replaces.
function _tpRowActions(r) {
  // Resolved rows: a confirmed NCNS / call-off usually means coaching later,
  // after dispatch settles — leave a quiet, hover-only follow-up link in
  // place of the decision buttons. Opt-in: ignoring it costs nothing, and
  // VTO'd / excused rows stay completely untouched.
  if (r.decision) {
    if (!/^approv/i.test(String(r.decision))) return "";
    if (!["ncns", "missed_reported"].includes(r.computed_outcome)) return "";
    const kind = r.computed_outcome === "ncns" ? "no-call/no-show" : "call-out";
    const dIso = fmtIsoDate(new Date());
    const dLbl = new Date().toLocaleDateString(undefined, { month: "short", day: "numeric" });
    return rrQtLink({
      hover: true,
      label: "Add coaching task",
      title: `Coach ${r.driver_name} — ${kind} on ${dLbl}`,
      description: `Confirmed ${kind} on Today's Plan (${dIso}).\nOpen: Drivers → ${r.driver_name} → Attendance`,
      category: "Driver Coaching",
      sourceKey: `attn:${r.driver_id}:${dIso}`,
      entityType: "driver",
      entityId: r.driver_id || null,
    });
  }
  if (!["tardy", "ncns", "missed_reported"].includes(r.computed_outcome)) return "";
  const sid = escapeHtml(r.shift_id);
  const oc  = escapeHtml(r.computed_outcome);
  const dn  = escapeHtml(r.driver_name);
  return `<div style="display:inline-flex;gap:6px;flex-wrap:nowrap">
    <button class="btn btn-sm btn-primary" data-rr-tp-approve="1" data-shift-id="${sid}" data-outcome="${oc}" data-driver-name="${dn}" type="button">Confirm</button>
    <button class="btn btn-sm"             data-rr-tp-vto="1"     data-shift-id="${sid}" data-outcome="${oc}" data-driver-name="${dn}" type="button">VTO</button>
    <button class="btn btn-sm"             data-rr-tp-deny="1"    data-shift-id="${sid}" data-outcome="${oc}" data-driver-name="${dn}" type="button">Excuse</button>
  </div>`;
}

// Top-of-page overview — a quiet SaaS summary strip above the roster.
function _renderTpMeta(attData, rosterData, otData, planData, fleetData, pipeData, riskData) {
  const el = document.getElementById("rr-tp-kpis");
  if (!el) return;
  const viewIso = (typeof _tpDateIso === "string" && _tpDateIso) || (typeof _tpToday === "function" ? _tpToday() : null);
  const todayIso = (typeof _tpToday === "function" ? _tpToday() : null);
  const planning = viewIso && todayIso && viewIso !== todayIso;
  // Future-day planning view: attendance RPC isn't called, so synthesize
  // stub rows from the roster so the KPI strip can still show Scheduled
  // / Extras / waves count.  Mirror the same synthesis the unified
  // roster does.
  if (planning && (!attData || !(attData.rows || []).length) && Array.isArray(rosterData) && rosterData.length) {
    attData = {
      rows: rosterData.map(r => ({
        shift_id:         r.shift_id,
        driver_id:        r.driver_id,
        driver_name:      r.driver_name,
        station_code:     r.station_code,
        starts_at:        r.starts_at,
        wave_index:       r.wave_index ?? 0,
        is_cushion:       !!r.is_cushion,
        computed_outcome: "scheduled",
        decision:         null,
      })),
    };
  }
  const rows = attData?.rows || [];
  el.removeAttribute("aria-busy");
  // Operational metrics drawn from data already fetched — overtime_intelligence
  // summary (unused until now) and today_plan (open routes + expiring licenses).
  // Computed BEFORE the empty-rows guard: today_attendance() only returns
  // assigned-driver shifts, but today_plan.open_shifts are *unassigned* routes,
  // so a day with routes imported but nobody assigned yet has no attendance
  // rows — and must still surface the red open-route alert.
  const otSum = (otData && otData.summary) || null;
  const otActive = otSum ? Number(otSum.drivers_active_ot) || 0 : 0;
  const otProjected = otSum ? Number(otSum.drivers_projected_ot) || 0 : 0;
  const otRiskCount = Math.max(otActive, otProjected);
  const otExposure = otSum ? Number(otSum.est_ot_exposure_usd) || 0 : 0;
  const openRoutes = (!planning && planData) ? ((planData.open_shifts || []).length) : null;
  const dlList = (!planning && planData) ? (planData.dl_expiring || []) : [];
  const dlUrgent = dlList.some((d) => Number(d.days_left) <= 0);
  const dlSoon = dlList.some((d) => Number(d.days_left) <= 2);
  // Current-state fleet readiness (VORR) + hiring pipeline — date-independent.
  const vorr = (fleetData && fleetData.vorr) || null;
  const fleetPct = vorr && vorr.percent != null ? Math.round(Number(vorr.percent)) : null;
  const fleetGrounded = vorr ? Number(vorr.grounded) || 0 : 0;
  const fleetBranded = vorr ? Number(vorr.total_branded) || 0 : 0;
  const pipeCounts = Array.isArray(pipeData) ? pipeData : [];
  const pipeMap = Object.fromEntries(pipeCounts.map((r) => [r.stage, Number(r.count) || 0]));
  const inPipeline = (pipeMap.applied || 0) + (pipeMap.screened || 0) + (pipeMap.booking_pending || 0);
  const hasOpsSignal = (openRoutes || 0) > 0 || dlList.length > 0;
  // Fleet readiness + pipeline are date-independent, so they should surface even
  // on a no-shift day (e.g. Sunday) with grounded vans or active candidates.
  const hasCurrentState = (vorr && fleetBranded > 0 && fleetPct != null) || inPipeline > 0;
  if (!rows.length && !hasOpsSignal && !hasCurrentState) {
    el.innerHTML = `<span class="tp-kpi-empty">${escapeHtml(planning ? "No shifts scheduled for this day." : "No shifts scheduled today.")}</span>`;
    _renderSchedTodayKpisMirror(null);
    return;
  }
  // On a no-shift day we still fall through (there's fleet/pipeline/open-route
  // signal) — but suppress the day-specific pills so the strip shows only the
  // meaningful current-state signals, not a row of zeros.
  const dayPills = rows.length > 0;
  const waves = new Set(rows.map(r => r.wave_index ?? 0));
  const extras = rows.filter(r => r.is_cushion).length;
  // Call-out exposure: how many of today's scheduled drivers are on an active
  // (unresolved) FINAL corrective action — the "High Risk" population most
  // likely to no-show, defined identically to the Schedule Callout Exposure
  // panel. Red when at-risk outnumbers the cushion drivers who'd cover them.
  const atRiskIds = new Set((Array.isArray(riskData) ? riskData : []).map(c => c.driver_id).filter(Boolean));
  const atRiskRows = atRiskIds.size ? rows.filter(r => atRiskIds.has(r.driver_id)) : [];
  const atRiskScheduled = atRiskRows.length;
  // Stash the named at-risk drivers so the pill's drill popover can list them
  // with a one-click "Open record". Cleared to [] when none, so a stale list
  // never survives into a day with no exposure.
  window._rrTpAtRisk = atRiskRows.map(r => ({
    id: r.driver_id,
    name: r.driver_name || r.name || "Driver",
    station: r.station_code || "",
    wave: r.wave_index ?? 0,
  }));
  const flagged = rows.filter(r => ["tardy","ncns","missed_reported"].includes(r.computed_outcome) && !r.decision).length;
  const checkedIn = rows.filter(r => ["checked_in", "checked_out"].includes(r.computed_outcome)).length;
  const navy = "#1E293B";
  const pct = rows.length ? Math.round((checkedIn / rows.length) * 100) : 0;
  const summary = {
    scheduled:  dayPills ? { value: rows.length, sub: `${waves.size} wave${waves.size === 1 ? "" : "s"}`,    tone: "navy" } : null,
    attendance: dayPills ? { value: planning ? "—" : checkedIn, sub: planning ? "Planning mode" : `${pct}% checked in`, tone: "navy" } : null,
    extras:     dayPills ? { value: extras, sub: "Cushion / Ex drivers", tone: "navy" } : null,
    openroutes: (openRoutes == null || (!dayPills && openRoutes === 0)) ? null : { value: openRoutes, sub: openRoutes === 0 ? "All routes covered" : "to assign", tone: openRoutes > 0 ? "red" : "green", onclick: "goto('schedule')", navTitle: "Open the schedule to assign routes" },
    otrisk:     (otSum && (dayPills || otRiskCount > 0)) ? { value: otRiskCount, sub: otExposure ? `~$${Math.round(otExposure).toLocaleString()} OT exposure` : `${otActive} in OT · ${otProjected} projected`, tone: otActive > 0 ? "red" : (otProjected > 0 ? "amber" : "navy"), onclick: "goto('schedule')", navTitle: "Overtime intelligence on the schedule" } : null,
    callout:    (dayPills && atRiskScheduled > 0) ? { value: atRiskScheduled, sub: `vs ${extras} cushion`, tone: atRiskScheduled > extras ? "red" : "amber", onclick: "_rrTpCalloutDrill(event)", navTitle: "At-risk drivers scheduled today — open a record to act (final corrective action)" } : null,
    license:    dlList.length ? { value: dlList.length, sub: "license expiring ≤7 days", tone: dlUrgent ? "red" : (dlSoon ? "amber" : "navy"), onclick: "window._rrGotoSubIntent={view:'schedule',sub:'roster'};goto('schedule')", navTitle: "Open the roster" } : null,
    fleet:      (vorr && fleetBranded > 0 && fleetPct != null) ? { value: `${fleetPct}%`, sub: fleetGrounded > 0 ? `${fleetGrounded} grounded` : "fleet ready", tone: vorr.threshold_status === "critical" ? "red" : (vorr.threshold_status === "warning" ? "amber" : "green"), onclick: "goto('fleet2')", navTitle: "Open Fleet" } : null,
    pipeline:   pipeCounts.length ? { value: inPipeline, sub: "in hiring pipeline", tone: "navy", onclick: "goto('pipeline')", navTitle: "Open the hiring pipeline" } : null,
    attention:  dayPills ? { value: planning ? "—" : flagged, sub: planning ? "Live attendance starts day-of" : (flagged > 0 ? `${flagged} decision${flagged === 1 ? "" : "s"} to review` : "No open attendance decisions"), tone: flagged > 0 ? "red" : "navy", spark: !planning } : null,
  };
  const toneColor = (t) => t === "red" ? "var(--red)" : t === "amber" ? "var(--amber)" : t === "green" ? "var(--green)" : navy;
  const pill = (key, label, val) => {
    if (!val) return "";
    const color = toneColor(val.tone);
    const subHtml = val.sub ? `<span class="tp-kpi-sub">${escapeHtml(String(val.sub))}</span>` : "";
    const sparkHtml = val.spark ? `<span class="tp-kpi-sparkslot" data-rr-tp-spark="${key}"></span>` : "";
    const nav = val.onclick ? ` role="button" tabindex="0" onclick="${escapeHtml(val.onclick)}"${val.navTitle ? ` title="${escapeHtml(val.navTitle)}"` : ""}` : "";
    return `<span class="tp-kpi-pill${val.onclick ? " tp-kpi-nav" : ""}" data-rr-tp-kpi="${key}"${nav}><span class="tp-kpi-dot" style="background:${color}"></span><span class="tp-kpi-text">${escapeHtml(String(val.value))} ${escapeHtml(label)}${subHtml}${sparkHtml}</span></span>`;
  };
  el.innerHTML =
      pill("scheduled",  "Scheduled",  summary.scheduled)
    + pill("attendance", "Checked in", summary.attendance)
    + pill("extras",     "Extras",     summary.extras)
    + pill("openroutes", openRoutes === 1 ? "Open route" : "Open routes", summary.openroutes)
    + pill("otrisk",     "OT risk",    summary.otrisk)
    + pill("callout",    "At-risk",    summary.callout)
    + pill("license",    dlList.length === 1 ? "License" : "Licenses", summary.license)
    + pill("fleet",      "Fleet ready", summary.fleet)
    + pill("pipeline",   inPipeline === 1 ? "Candidate" : "Candidates", summary.pipeline)
    + pill("attention",  flagged === 1 ? "Open decision" : "Open decisions", summary.attention);
  _renderSchedTodayKpisMirror(el.innerHTML);
  _fillTpSparklines();
}

// A compact inline SVG trend sparkline (area + line + emphasized endpoint),
// self-contained so any strip can drop one in. Returns "" for too-few points.
function _rrSparkline(vals, opts) {
  opts = opts || {};
  const v = (vals || []).filter((x) => typeof x === "number" && isFinite(x));
  if (v.length < 2) return "";
  const w = opts.w || 64, h = opts.h || 16, pad = 1.5;
  const lo = Math.min(...v), hi = Math.max(...v), span = (hi - lo) || 1;
  const px = (i) => pad + (i / (v.length - 1)) * (w - 2 * pad);
  const py = (val) => h - pad - ((val - lo) / span) * (h - 2 * pad);
  const pts = v.map((val, i) => [px(i), py(val)]);
  const line = pts.map((p, i) => `${i ? "L" : "M"}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
  const color = opts.color || "var(--accent,#2563eb)";
  const last = pts[pts.length - 1];
  const gid = "tpsp" + Math.random().toString(36).slice(2, 7);
  const area = `${line} L${last[0].toFixed(1)},${(h - pad).toFixed(1)} L${pts[0][0].toFixed(1)},${(h - pad).toFixed(1)} Z`;
  return `<svg class="tp-kpi-spark" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true">`
    + `<defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity="0.22"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>`
    + `<path d="${area}" fill="url(#${gid})"/>`
    + `<path d="${line}" fill="none" stroke="${color}" stroke-width="1.4" stroke-linejoin="round" stroke-linecap="round"/>`
    + `<circle cx="${last[0].toFixed(1)}" cy="${last[1].toFixed(1)}" r="1.8" fill="${color}"/></svg>`;
}

// Fill the KPI-strip sparkline slots from the existing per-day attendance
// history (a cached shifts fetch). Fire-and-forget; silent on any failure so a
// missing history never blanks the KPI strip. Fills both the dashboard strip
// and its schedule-view mirror.
async function _fillTpSparklines() {
  const slots = document.querySelectorAll('[data-rr-tp-spark="attention"]');
  if (!slots.length) return;
  try {
    const hist = await _ensureAttKpiHistory(14);
    const byDay = ((hist && hist.byDay) || []).slice(-14);
    if (byDay.length < 3) return;
    const vals = byDay.map((d) => (Number(d.callouts) || 0) + (Number(d.noshows) || 0));
    if (vals.every((x) => x === 0)) return;   // nothing meaningful to trend
    const svg = _rrSparkline(vals, { color: "var(--red,#dc2626)" });
    document.querySelectorAll('[data-rr-tp-spark="attention"]').forEach((s) => { s.innerHTML = svg; });
  } catch (e) { /* silent — the KPI numbers stand on their own */ }
}

// One-click act on the Call-out exposure pill. Instead of a bare jump to the
// schedule, clicking the At-risk pill opens a compact popover listing the
// at-risk scheduled drivers (from window._rrTpAtRisk, set in _renderTpMeta) —
// each row a button that drops the operator straight into that driver's record
// (openDriverDrawer) to message / coach / arrange coverage. A footer link still
// opens the schedule's Callout Exposure surface for the backup-plan flow.
function _rrTpCalloutDrill(ev) {
  try { ev && ev.stopPropagation && ev.stopPropagation(); } catch (_) {}
  const anchor = ev && (ev.currentTarget || ev.target && ev.target.closest && ev.target.closest('[data-rr-tp-kpi="callout"]'));
  const existing = document.getElementById("rr-tp-callout-drill");
  if (existing) { existing.remove(); if (existing._anchor === anchor) return; }
  const drivers = Array.isArray(window._rrTpAtRisk) ? window._rrTpAtRisk : [];
  if (!drivers.length) { if (typeof goto === "function") goto("schedule"); return; }

  const pop = document.createElement("div");
  pop.id = "rr-tp-callout-drill";
  pop.className = "tp-callout-drill";
  pop._anchor = anchor;
  const rowHtml = drivers.map((d) => {
    const meta = [d.station, d.wave != null && d.wave !== "" ? `Wave ${Number(d.wave) + 1}` : ""].filter(Boolean).join(" · ");
    return `<button type="button" class="tp-callout-drill-row" data-rr-callout-driver="${escapeHtml(String(d.id))}" title="Open ${escapeHtml(String(d.name))}'s record">
      <span class="tp-callout-drill-name">${escapeHtml(String(d.name))}</span>
      ${meta ? `<span class="tp-callout-drill-meta">${escapeHtml(meta)}</span>` : ""}
      <span class="tp-callout-drill-go" aria-hidden="true">→</span>
    </button>`;
  }).join("");
  pop.innerHTML = `
    <div class="tp-callout-drill-head">${drivers.length} at-risk driver${drivers.length === 1 ? "" : "s"} scheduled</div>
    <div class="tp-callout-drill-list">${rowHtml}</div>
    <button type="button" class="tp-callout-drill-foot" data-rr-callout-schedule>Plan backups in Schedule → Callout Exposure →</button>`;
  document.body.appendChild(pop);

  // Anchor below the pill, clamped into the viewport.
  const r = anchor && anchor.getBoundingClientRect ? anchor.getBoundingClientRect() : { left: 24, bottom: 80, top: 60 };
  const pw = pop.offsetWidth || 260, ph = pop.offsetHeight || 200;
  let left = Math.min(r.left, window.innerWidth - pw - 12);
  left = Math.max(12, left);
  let top = r.bottom + 6;
  if (top + ph > window.innerHeight - 12) top = Math.max(12, r.top - ph - 6);
  pop.style.left = left + "px";
  pop.style.top = top + "px";

  const close = () => { pop.remove(); document.removeEventListener("keydown", onKey, true); document.removeEventListener("click", onDoc, true); };
  const onKey = (e) => { if (e.key === "Escape") close(); };
  const onDoc = (e) => { if (!pop.contains(e.target) && e.target !== anchor && !(anchor && anchor.contains && anchor.contains(e.target))) close(); };
  pop.addEventListener("click", (e) => {
    const row = e.target.closest("[data-rr-callout-driver]");
    if (row) { const id = row.getAttribute("data-rr-callout-driver"); close(); if (typeof openDriverDrawer === "function") openDriverDrawer(id, { tab: "attendance" }); return; }
    if (e.target.closest("[data-rr-callout-schedule]")) { close(); if (typeof goto === "function") goto("schedule"); return; }
  });
  // Defer the outside-click / key listeners a tick so the opening click
  // doesn't immediately close the popover.
  setTimeout(() => { document.addEventListener("keydown", onKey, true); document.addEventListener("click", onDoc, true); }, 0);
}
window._rrTpCalloutDrill = _rrTpCalloutDrill;

// Week-ahead call-out exposure matrix — a compact heat strip on the command
// center showing, per upcoming scheduled day, whether at-risk drivers outnumber
// the cushion (exposed) or not (covered). It reads the SAME canonical exposure
// the schedule's Callout Exposure panel computes (window._rrCalloutExposure),
// falling back to a persisted snapshot (localStorage) so the strip is populated
// even before the operator opens the schedule this session. Days are filtered to
// today-forward, so a stale past week naturally drops out and the strip hides.
function _renderTpWeekRisk() {
  const el = document.getElementById("rr-tp-weekrisk");
  if (!el) return;
  const todayIso = (typeof _tpToday === "function" ? _tpToday() : null) || "";

  // Source: prefer the live in-memory exposure; else the persisted snapshot.
  let src = null, fromCache = false, generatedAt = 0;
  const live = window._rrCalloutExposure;
  if (live && Array.isArray(live.days)) {
    src = live.days;
  } else {
    try {
      const dspId = (window.RR && window.RR.dsp && window.RR.dsp.id) || "x";
      const raw = localStorage.getItem("rr.tp.weekrisk:" + dspId);
      if (raw) { const o = JSON.parse(raw); if (o && Array.isArray(o.days)) { src = o.days; fromCache = true; generatedAt = Number(o.generatedAt) || 0; } }
    } catch (_) { src = null; }
  }

  const ahead = (src || []).filter(d => d && d.iso && d.iso >= todayIso).sort((a, b) => a.iso.localeCompare(b.iso));
  if (!ahead.length) { el.innerHTML = ""; return; }   // nothing to show → stay invisible

  const exposedCount = ahead.filter(d => (d.exposure || 0) > 0).length;
  // Cell tone: exposed days scale amber → red by how many drivers are uncovered;
  // covered days stay calm. Matches the schedule panel's red/green treatment.
  const cellTone = (d) => {
    const ex = d.exposure || 0;
    if (ex <= 0) return "covered";
    return ex >= 2 ? "hot" : "warm";
  };
  const cellHtml = ahead.map((d) => {
    const ex = d.exposure || 0;
    const tone = cellTone(d);
    const big = ex > 0 ? `+${ex}` : "✓";
    const sub = ex > 0
      ? `${d.atRisk} at-risk · ${Math.max(0, d.cushionDrivers || 0)} cushion`
      : (d.cushionDrivers > 0 ? `+${d.cushionDrivers} spare` : "covered");
    const title = `${d.weekday}: ${d.label || (ex > 0 ? ex + " exposed" : "covered")} — ${d.atRisk || 0} at-risk vs ${Math.max(0, d.cushionDrivers || 0)} cushion of ${d.scheduledDrivers || 0} scheduled`;
    return `<button type="button" class="tp-wr-cell tone-${tone}" title="${escapeHtml(title)}" onclick="goto('schedule')">
      <span class="tp-wr-day">${escapeHtml(String(d.weekday || d.iso))}</span>
      <span class="tp-wr-val">${escapeHtml(big)}</span>
      <span class="tp-wr-sub">${escapeHtml(sub)}</span>
    </button>`;
  }).join("");

  const heading = exposedCount > 0
    ? `${exposedCount} exposed day${exposedCount === 1 ? "" : "s"} ahead`
    : "Covered through the week";
  const stale = fromCache && generatedAt ? `<span class="tp-wr-asof" title="From the last schedule render">as of ${escapeHtml(_rrRelTime(generatedAt))}</span>` : "";

  el.innerHTML = `
    <div class="tp-weekrisk card card-flush">
      <div class="tp-wr-head">
        <span class="tp-wr-title">Call-out exposure · days ahead</span>
        <span class="tp-wr-status ${exposedCount > 0 ? "is-exposed" : "is-covered"}">${escapeHtml(heading)}</span>
        ${stale}
      </div>
      <div class="tp-wr-strip">${cellHtml}</div>
    </div>`;
}

// Compact relative-time label ("just now", "2h ago", "yesterday", "Jul 9").
function _rrRelTime(ts) {
  const diff = Date.now() - ts;
  if (!(diff >= 0)) return "just now";
  const m = Math.floor(diff / 60000), h = Math.floor(m / 60), dys = Math.floor(h / 24);
  if (m < 2) return "just now";
  if (h < 1) return m + "m ago";
  if (dys < 1) return h + "h ago";
  if (dys === 1) return "yesterday";
  if (dys < 7) return dys + "d ago";
  try { return new Date(ts).toLocaleDateString(undefined, { month: "short", day: "numeric" }); }
  catch { return dys + "d ago"; }
}

// When the schedule's Today sub-view is the visible host for the
// Today's Plan shell, mirror the in-shell minimal KPI strip into the
// schedule-level #rr-sched-kpis pill row so the operator sees Today
// KPIs in the same place the week KPIs normally live. Leaving the
// Today sub-view triggers renderScheduleWeek which repaints the
// weekly pills, so no explicit restore is needed.
function _renderSchedTodayKpisMirror(innerHtml) {
  const schedHost = document.getElementById("rr-sched-today-plan-host");
  const visible = !!schedHost?.offsetParent;
  if (!visible) return;
  const target = document.getElementById("rr-sched-kpis");
  if (!target) return;
  if (innerHtml == null) { target.innerHTML = ""; return; }
  target.classList.add("sched-kpi-pills");
  target.innerHTML = innerHtml;
}

function _renderTpUnifiedRoster(attData, rosterData, error, otData) {
  const wrap = document.getElementById("rr-tp-roster");
  if (!wrap) return;

  // OT headroom lookup. otData is the overtime_intelligence() jsonb;
  // a null payload (RPC error, viewer not a dispatcher, etc.) just
  // suppresses the sub-line on each row.
  const otThreshold = Number(otData?.threshold_hours) || 40;
  const otWorkedByDriver = new Map();
  for (const r of (otData?.drivers || [])) {
    otWorkedByDriver.set(r.driver_id, Number(r.worked_hours) || 0);
  }
  const otHeadroomLine = (r) => {
    if (!otData) return "";
    const worked = otWorkedByDriver.get(r.driver_id) || 0;
    const todayBlock = (() => {
      if (r.starts_at && r.ends_at) {
        const h = (new Date(r.ends_at) - new Date(r.starts_at)) / 3600000;
        if (h > 0) return h;
      }
      return 10;
    })();
    const headroom = otThreshold - worked;
    if (headroom <= 0) {
      return `<div class="tp-ot-headroom is-ot" title="Worked ${worked.toFixed(1)}h of ${otThreshold}h this week">in OT now</div>`;
    }
    const left = `${headroom.toFixed(1)}h until OT`;
    if (headroom - todayBlock < 0) {
      return `<div class="tp-ot-headroom is-warn" title="Worked ${worked.toFixed(1)}h · today's ${todayBlock.toFixed(1)}h shift pushes over ${otThreshold}h">${left} · into OT after today</div>`;
    }
    return `<div class="tp-ot-headroom">${left}</div>`;
  };

  // Future-day planning mode: no attendance clock-ins yet, so the
  // attendance card is meaningless.  Synthesize stub attendance rows
  // from the roster so the rest of the renderer (which builds rows
  // off attData) works unchanged — minus the live-attendance bits.
  const viewIso = (typeof _tpDateIso === "string" && _tpDateIso) || (typeof _tpToday === "function" ? _tpToday() : null);
  const todayIso = (typeof _tpToday === "function" ? _tpToday() : null);
  const planningMode = viewIso && todayIso && viewIso !== todayIso;
  if (planningMode && (!attData || !(attData.rows || []).length)) {
    attData = {
      rows: (rosterData || []).map(r => ({
        shift_id:        r.shift_id,
        driver_id:       r.driver_id,
        driver_name:     r.driver_name,
        station_code:    r.station_code,
        starts_at:       r.starts_at,
        wave_index:      0,
        is_cushion:      false,
        computed_outcome: "scheduled",
        decision:        null,
      })),
      _planning: true,
    };
  }

  if (error) {
    wrap.innerHTML = `<div class="rr-tp-section-head">Today's roster</div>
      <div style="padding:18px 20px;color:var(--red);font-size:var(--fs-sm)">Couldn't load: ${escapeHtml(error.message || String(error))}</div>`;
    return;
  }

  const attRows = attData?.rows || [];
  const rosterByShift = new Map();
  for (const r of (rosterData || [])) rosterByShift.set(r.shift_id, r);

  if (attRows.length === 0) {
    const heading = planningMode ? "Roster · planning view" : "Today's roster";
    const msg = planningMode
      ? `No shifts scheduled for ${new Date(viewIso + "T12:00:00").toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })}.`
      : "No shifts scheduled for today.";
    wrap.innerHTML = `<div class="rr-tp-section-head">${escapeHtml(heading)}</div>
      <div style="padding:36px 20px;text-align:center;color:var(--text-subtle);font-size:var(--fs-sm)">${escapeHtml(msg)}</div>`;
    return;
  }

  // Join + normalize
  const rows = attRows.map(att => {
    const ro = rosterByShift.get(att.shift_id) || {};
    return {
      shift_id:        att.shift_id,
      driver_id:       att.driver_id,
      driver_name:     att.driver_name,
      driver_photo_path: ro.driver_photo_path,
      tier:            ro.tier,
      station_code:    att.station_code,
      route_code:      ro.route_code,
      starts_at:       att.starts_at,
      ends_at:         ro.ends_at,
      wave_index:      att.wave_index ?? 0,
      is_cushion:      !!att.is_cushion,
      van_id:          ro.van_id,
      van_name:        ro.van_name,
      van_plate:       ro.van_plate,
      van_via:         ro.van_via,
      van_via_source:  ro.van_via_source,
      covering_for:    ro.covering_for,
      gap_kind:        ro.gap_kind,
      shift_kind:      ro.shift_kind || "regular",
      computed_outcome:att.computed_outcome,
      decision:        att.decision,
      missed_reason:   att.missed_reason,
      service_type_color: att.service_type_color,
    };
  });

  // Drop drivers whose attendance has already been resolved as
  // "not working today" — once a dispatcher confirms or excuses a
  // NCNS / called-off, the driver shouldn't keep cluttering the
  // active roster. (Late drivers stay visible because they're
  // still expected to work.)
  const resolvedAbsent = (r) => !!r.decision && (r.computed_outcome === "ncns" || r.computed_outcome === "missed_reported");
  const visibleRows = rows.filter(r => !resolvedAbsent(r));

  // Onboarding shifts (Day 1+2 class training, Day 3 road training) get
  // pulled out of the main wave grid and rendered in their own section
  // so the dispatcher can scan the actual route coverage cleanly.
  const classTrainingRows = visibleRows.filter(r => r.shift_kind === "training");
  const roadTrainingRows  = visibleRows.filter(r => r.shift_kind === "ride_along");
  const regularRows       = visibleRows.filter(r => r.shift_kind !== "training" && r.shift_kind !== "ride_along");

  // Group regular rows by wave_index
  const byWave = new Map();
  for (const r of regularRows) {
    const w = r.wave_index ?? 0;
    if (!byWave.has(w)) byWave.set(w, []);
    byWave.get(w).push(r);
  }
  const waveKeys = [...byWave.keys()].sort((a, b) => a - b);

  const fmtTime = (iso) => {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  };

  const initials = (name) => (name || "?").split(/\s+/).map(p => p[0]).filter(Boolean).slice(0, 2).join("").toUpperCase();

  const tierChip = (t) => {
    if (!t) return "";
    const map = {
      "Fantastic+": ["var(--green-dark)", "var(--green-soft)"],
      "Fantastic":  ["var(--green)",      "var(--green-soft)"],
      "Great":      ["var(--accent-text)","var(--accent-soft)"],
      "Fair":       ["var(--amber-dark)", "var(--amber-soft)"],
      "Poor":       ["var(--red)",        "var(--red-soft)"],
    };
    const [fg, bg] = map[t] || ["var(--text-muted)", "var(--canvas)"];
    return `<span class="tp-tier-chip" style="background:${bg};color:${fg}">${escapeHtml(t)}</span>`;
  };

  const exTag = (r) => r.is_cushion ? `<span class="tp-ex-chip">EX</span>` : "";

  // Only "real" no-van gaps count toward the warning; class-training
  // legitimately has no van (the trainee is in the station) and a
  // resolved ride-along inherits the trainer's van, so neither hits
  // this counter.
  const noVan = regularRows.filter(r => r.gap_kind === "no_van").length;
  const headRight = (() => {
    if (noVan === 0) return "";
    return `<span style="font-size:var(--fs-xs);font-weight:700;color:var(--red);margin-right:8px">${noVan} no van</span>`;
  })();

  const autoBtn = noVan > 0
    ? `<button type="button" class="btn btn-sm btn-primary" data-rr-tp-auto-assign style="display:inline-flex;align-items:center;gap:6px">
         <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>
         Auto-assign ${noVan} van${noVan === 1 ? "" : "s"}
       </button>`
    : "";

  const renderRow = (r) => {
    const _avU = _driverPhotoUrl(r.driver_photo_path);
    const av = _avU
      ? `<img class="tp-driver-avatar" src="${escapeHtml(_avU)}" alt="">`
      : `<div class="tp-driver-avatar">${escapeHtml(initials(r.driver_name))}</div>`;

    const timeStr = (r.starts_at || r.ends_at)
      ? `<span style="font-variant-numeric:tabular-nums">${escapeHtml(fmtTime(r.starts_at))}${r.ends_at ? " – " + escapeHtml(fmtTime(r.ends_at)) : ""}</span>`
      : `<span class="u-subtle">—</span>`;

    const shiftMeta = [r.route_code, r.station_code].filter(Boolean).map(escapeHtml).join(" · ");

    const pickAttrs = `data-rr-tp-pick-van="${escapeHtml(r.driver_id)}" data-rr-tp-pick-via="${escapeHtml(r.van_via || "")}" data-rr-tp-pick-current="${escapeHtml(r.van_id || "")}" data-rr-tp-pick-driver-name="${escapeHtml(r.driver_name)}"`;
    let vanCell;
    if (r.van_name) {
      const plate = r.van_plate ? `<span class="tp-van-plate"> · ${escapeHtml(r.van_plate)}</span>` : "";
      const cover = r.van_via === "backup" && r.covering_for
        ? `<div class="tp-van-cover">Covering for ${escapeHtml(r.covering_for)}</div>`
        : "";
      vanCell = `<div class="tp-van-cell" ${pickAttrs}><span class="tp-van-name">${escapeHtml(r.van_name)}</span>${plate}${cover}</div>`;
    } else {
      vanCell = `<button type="button" class="tp-assign-van" ${pickAttrs}><span class="dot"></span>Assign van</button>`;
    }

    const actions = _tpRowActions(r);

    return `<tr class="rr-tp-tool-row" data-driver-id="${escapeHtml(r.driver_id)}">
      <td>
        <div style="display:flex;align-items:center;gap:var(--s-2-5);min-width:0">
          ${av}
          <div style="min-width:0;flex:1">
            <div style="font-weight:600;display:flex;align-items:center;flex-wrap:wrap" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml(r.driver_name)}${tierChip(r.tier)}${exTag(r)}</div>
            ${shiftMeta ? `<div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${shiftMeta}</div>` : ""}
          </div>
        </div>
      </td>
      <td style="white-space:nowrap">${timeStr}</td>
      <td>${vanCell}</td>
      <td>${_tpStatusPill(r)}</td>
      <td>${otHeadroomLine(r)}</td>
      <td class="u-right">${actions || ""}</td>
    </tr>`;
  };

  // Section header per wave.  If there's only one wave the header is
  // suppressed so the table reads as a single roster.
  const showWaveHeaders = waveKeys.length > 1;

  const sections = waveKeys.map((w, idx) => {
    const rs = byWave.get(w);
    // Wave label: use the earliest starts_at in the wave when present;
    // otherwise the wave index.
    let timeLabel = "";
    const earliest = rs.map(r => r.starts_at).filter(Boolean).sort()[0];
    if (earliest) {
      const d = new Date(earliest);
      if (!isNaN(d.getTime())) {
        timeLabel = " · " + d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
      }
    }
    const extraCount = rs.filter(r => r.is_cushion).length;
    const extraSuffix = extraCount > 0 ? ` <span style="font-size:var(--fs-xs);color:var(--amber-dark);font-weight:600;margin-left:6px">${extraCount} ex</span>` : "";

    const header = showWaveHeaders
      ? `<div class="tp-wave-head"${idx === 0 ? ' style="border-top:0"' : ""}>
           <span class="tp-wave-head-label">Wave ${w}${escapeHtml(timeLabel)}</span>
           <span class="u-xs-subtle">${rs.length} scheduled</span>
           ${extraSuffix}
         </div>`
      : "";

    // Shared colgroup pins column widths so every wave's table lines
    // up — without this, each table auto-sizes independently and the
    // columns drift apart visually.  table-layout:fixed makes the
    // browser honor the colgroup percentages exactly.
    const colgroup = `<colgroup>
      <col style="width:28%">
      <col style="width:15%">
      <col style="width:15%">
      <col style="width:12%">
      <col style="width:14%">
      <col style="width:16%">
    </colgroup>`;

    return `${header}
      <table class="tp-roster-table" style="table-layout:fixed">
        ${colgroup}
        ${idx === 0 || showWaveHeaders ? `<thead>
          <tr>
            <th>Driver</th>
            <th>Shift</th>
            <th>Van</th>
            <th>Status</th>
            <th>Until OT</th>
            <th>Action</th>
          </tr>
        </thead>` : ""}
        <tbody>${rs.map(renderRow).join("")}</tbody>
      </table>`;
  }).join("");

  // ── Training-today section ──────────────────────────────────────
  // Renders class training (Day 1+2 at the station — no van needed)
  // and road training (Day 3 ride-along — sharing the trainer's van)
  // under their own headers so the operator can scan route coverage
  // separately from onboarding scaffolding.
  const trainingTotal = classTrainingRows.length + roadTrainingRows.length;
  const renderTrainingRow = (r, isClass) => {
    const _avU = _driverPhotoUrl(r.driver_photo_path);
    const av = _avU
      ? `<img class="tp-driver-avatar" src="${escapeHtml(_avU)}" alt="">`
      : `<div class="tp-driver-avatar">${escapeHtml(initials(r.driver_name))}</div>`;
    const timeStr = (r.starts_at || r.ends_at)
      ? `<span style="font-variant-numeric:tabular-nums">${escapeHtml(fmtTime(r.starts_at))}${r.ends_at ? " – " + escapeHtml(fmtTime(r.ends_at)) : ""}</span>`
      : `<span class="u-subtle">—</span>`;

    let vanCell, statusCell;
    if (isClass) {
      // Class training: explicitly NO van. Status spells out the day.
      vanCell = `<span style="color:var(--text-subtle);font-size:var(--fs-xs)">No van — in the station</span>`;
      statusCell = `<span style="background:rgba(13,148,136,.12);color:#0F766E;font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:var(--s-1) 10px;border-radius:var(--r-lg)">Classroom training</span>`;
    } else {
      // Road training: van inherited from trainer, plus "with <Trainer>"
      const trainerName = r.covering_for || "trainer";
      if (r.van_name) {
        const plate = r.van_plate ? `<span class="tp-van-plate"> · ${escapeHtml(r.van_plate)}</span>` : "";
        vanCell = `<div class="tp-van-cell"><span class="tp-van-name">${escapeHtml(r.van_name)}</span>${plate}<div class="tp-van-cover">Sharing with ${escapeHtml(trainerName)}</div></div>`;
      } else {
        vanCell = `<span style="color:var(--red);font-size:var(--fs-xs);font-weight:700">${escapeHtml(trainerName)} has no van</span>`;
      }
      statusCell = `<span style="background:rgba(245,158,11,.14);color:#B45309;font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:var(--s-1) 10px;border-radius:var(--r-lg)">Road training</span>`;
    }
    const trainerLabel = !isClass && r.covering_for
      ? `<div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">Trainer · ${escapeHtml(r.covering_for)}</div>`
      : "";
    return `<tr class="rr-tp-tool-row" data-driver-id="${escapeHtml(r.driver_id)}">
      <td>
        <div style="display:flex;align-items:center;gap:var(--s-2-5);min-width:0">
          ${av}
          <div style="min-width:0;flex:1">
            <div style="font-weight:600;display:flex;align-items:center;flex-wrap:wrap" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml(r.driver_name)}${tierChip(r.tier)}</div>
            ${trainerLabel}
          </div>
        </div>
      </td>
      <td style="white-space:nowrap">${timeStr}</td>
      <td>${vanCell}</td>
      <td>${statusCell}</td>
      <td></td>
      <td class="u-right"></td>
    </tr>`;
  };
  const trainingColgroup = `<colgroup>
    <col style="width:28%"><col style="width:15%"><col style="width:15%"><col style="width:12%"><col style="width:14%"><col style="width:16%">
  </colgroup>`;
  const classSection = classTrainingRows.length === 0 ? "" : `
    <div class="tp-wave-head" style="background:rgba(13,148,136,.06)">
      <span class="tp-wave-head-label" style="color:#0F766E">Classroom training</span>
      <span class="u-xs-subtle">${classTrainingRows.length} driver${classTrainingRows.length === 1 ? "" : "s"} · Day 1 + 2 at the station</span>
    </div>
    <table class="tp-roster-table" style="table-layout:fixed">${trainingColgroup}
      <tbody>${classTrainingRows.map(r => renderTrainingRow(r, true)).join("")}</tbody>
    </table>`;
  const roadSection = roadTrainingRows.length === 0 ? "" : `
    <div class="tp-wave-head" style="background:rgba(245,158,11,.06)">
      <span class="tp-wave-head-label" style="color:#B45309">Road training</span>
      <span class="u-xs-subtle">${roadTrainingRows.length} driver${roadTrainingRows.length === 1 ? "" : "s"} · riding along with a trainer</span>
    </div>
    <table class="tp-roster-table" style="table-layout:fixed">${trainingColgroup}
      <tbody>${roadTrainingRows.map(r => renderTrainingRow(r, false)).join("")}</tbody>
    </table>`;
  const trainingBlock = trainingTotal === 0 ? "" : `
    <div class="rr-tp-section-head" style="display:flex;align-items:center;gap:var(--s-2-5);margin-top:var(--s-5)">
      <span>In training today</span>
      <span style="font-size:var(--fs-xs);font-weight:500;color:var(--text-subtle)">${trainingTotal} driver${trainingTotal === 1 ? "" : "s"}</span>
    </div>
    <div style="overflow-x:auto">${classSection}${roadSection}</div>`;

  wrap.innerHTML = `
    <div class="rr-tp-section-head" style="display:flex;align-items:center;gap:var(--s-2-5)">
      <span>Today's roster</span>
      <span style="font-size:var(--fs-xs);font-weight:500;color:var(--text-subtle)">${regularRows.length} scheduled${showWaveHeaders ? ` · ${waveKeys.length} waves` : ""}${trainingTotal > 0 ? ` · ${trainingTotal} in training` : ""}</span>
      <div style="margin-left:auto;display:flex;align-items:center;gap:var(--s-3)">${headRight}${autoBtn}</div>
    </div>
    <div style="overflow-x:auto">${sections}</div>
    ${trainingBlock}`;
}


// Today's roster · drivers + resolved vans for the day.  Each row
// shows who is working, the van they're rolling, a "covering for X"
// chip when a backup picked up the van, and a red "No van" chip when
// the resolver couldn't satisfy the driver — the gap-flag the
// dispatcher needs to see before 5 AM.
function _renderTpVanRoster(data, error) {
  const wrap = document.getElementById("rr-tp-vanroster");
  if (!wrap) return;
  const rows = Array.isArray(data) ? data : [];

  if (error) {
    wrap.innerHTML = `<div class="rr-tp-section-head">Today's roster · drivers + vans</div>
      <div style="padding:18px 20px;color:var(--red);font-size:var(--fs-sm)">Couldn't load roster: ${escapeHtml(error.message || String(error))}</div>`;
    return;
  }

  const noVan      = rows.filter((r) => r.gap_kind === "no_van").length;
  const coverCount = rows.filter((r) => r.van_via === "backup").length;
  const headRight  = (() => {
    const bits = [];
    if (noVan > 0)      bits.push(`<span style="color:var(--red);font-weight:700">${noVan} no van</span>`);
    if (coverCount > 0) bits.push(`<span style="color:var(--amber-dark);font-weight:600">${coverCount} covering</span>`);
    return bits.length ? `<span style="font-size:var(--fs-xs);font-weight:500;display:flex;gap:var(--s-2-5)">${bits.join("")}</span>` : "";
  })();

  if (rows.length === 0) {
    wrap.innerHTML = `<div class="rr-tp-section-head" style="display:flex;align-items:center">
        Today's roster · drivers + vans
      </div>
      <div style="padding:var(--s-8) 20px;text-align:center;color:var(--text-subtle);font-size:var(--fs-sm)">No shifts scheduled for today.</div>`;
    return;
  }

  const fmtTime = (iso) => {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  };

  const statusPill = (s) => {
    // Mirrors the shift_status enum (0025 + 0035 + 0042).
    const map = {
      scheduled:  ["var(--accent-soft)", "var(--accent-text)", "Scheduled"],
      completed:  ["var(--green-soft)",  "var(--green)",       "Completed"],
      late:       ["var(--amber-soft)",  "var(--amber-dark)",  "Late"],
      vto:        ["var(--canvas)",      "var(--text-muted)",  "VTO"],
      called_off: ["var(--red-soft)",    "var(--red)",         "Called off"],
      no_show:    ["var(--red-soft)",    "var(--red)",         "No-show"],
    };
    const [bg, fg, label] = map[s] || ["var(--canvas)", "var(--text-subtle)", s || "—"];
    return `<span style="display:inline-flex;align-items:center;font-size:10px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:2px 8px;border-radius:var(--r-pill);background:${bg};color:${fg}">${escapeHtml(label)}</span>`;
  };

  const tierChip = (t) => {
    if (!t) return "";
    const map = {
      "Fantastic+": ["#0e7c3a", "#dcfce7"],
      "Fantastic":  ["var(--green)", "var(--green-soft)"],
      "Great":      ["var(--accent-text)", "var(--accent-soft)"],
      "Fair":       ["var(--amber-dark)", "var(--amber-soft)"],
      "Poor":       ["var(--red)", "var(--red-soft)"],
    };
    const [fg, bg] = map[t] || ["var(--text-muted)", "var(--canvas)"];
    return `<span style="display:inline-flex;align-items:center;font-size:10px;font-weight:700;padding:2px 7px;border-radius:var(--r-md);background:${bg};color:${fg};margin-left:6px">${escapeHtml(t)}</span>`;
  };

  const initials = (name) => (name || "?").split(/\s+/).map((p) => p[0]).filter(Boolean).slice(0, 2).join("").toUpperCase();

  const body = rows.map((r) => {
    const _avU = _driverPhotoUrl(r.driver_photo_path);
    const av = _avU
      ? `<img src="${escapeHtml(_avU)}" alt="" style="width:32px;height:32px;border-radius:50%;object-fit:cover;flex:0 0 auto">`
      : `<div style="width:32px;height:32px;border-radius:50%;background:var(--accent-soft);color:var(--accent-text);display:flex;align-items:center;justify-content:center;font-size:var(--fs-xs);font-weight:700;flex:0 0 auto">${escapeHtml(initials(r.driver_name))}</div>`;

    const timeStr = (r.starts_at || r.ends_at)
      ? `<span style="font-variant-numeric:tabular-nums">${escapeHtml(fmtTime(r.starts_at))}${r.ends_at ? " – " + escapeHtml(fmtTime(r.ends_at)) : ""}</span>`
      : `<span class="u-subtle">—</span>`;

    const shiftMeta = [r.route_code, r.station_code].filter(Boolean).map(escapeHtml).join(" · ");

    // The whole cell is clickable — it opens the inline picker.  We
    // keep the underlying van id on the cell via data-rr-tp-pick-van
    // so the picker knows what (driver, date, currently-assigned van)
    // it's editing.  This intentionally replaces the old "click van →
    // open fleet drawer" behavior on this surface; the fleet drawer
    // is still reachable from My vehicles.
    const pickAttrs = `data-rr-tp-pick-van="${escapeHtml(r.driver_id)}" data-rr-tp-pick-via="${escapeHtml(r.van_via || "")}" data-rr-tp-pick-current="${escapeHtml(r.van_id || "")}" data-rr-tp-pick-driver-name="${escapeHtml(r.driver_name)}"`;
    let vanCell;
    if (r.van_name) {
      const plate = r.van_plate ? `<span style="color:var(--text-subtle);font-weight:500"> · ${escapeHtml(r.van_plate)}</span>` : "";
      // Backup-pick rows still show "Covering for X" because that's
      // operationally meaningful.  Override + Auto sublabels are gone
      // per direction; the whole cell is still clickable to open the
      // van picker for last-minute changes.
      const cover = r.van_via === "backup" && r.covering_for
        ? `<div style="font-size:var(--fs-xs);color:var(--amber-dark);font-weight:600;margin-top:2px">Covering for ${escapeHtml(r.covering_for)}</div>`
        : "";
      vanCell = `<div ${pickAttrs} style="cursor:pointer;border-radius:var(--r-md);padding:3px 6px;margin:-3px -6px;transition:background var(--t-fast)" onmouseover="this.style.background='var(--canvas)'" onmouseout="this.style.background='transparent'"><span style="font-weight:600">${escapeHtml(r.van_name)}</span>${plate}${cover}</div>`;
    } else {
      vanCell = `<button type="button" ${pickAttrs} style="cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-xs);font-weight:700;padding:var(--s-1) 10px;border-radius:var(--r-pill);background:var(--red-soft);color:var(--red);border:0;font-family:inherit;letter-spacing:inherit"><span style="width:6px;height:6px;border-radius:50%;background:currentColor"></span>Assign van</button>`;
    }

    return `<tr>
      <td style="padding:11px 14px;border-top:1px solid var(--border)">
        <div style="display:flex;align-items:center;gap:var(--s-2-5);min-width:0">
          ${av}
          <div style="min-width:0;flex:1">
            <div style="font-weight:600;display:flex;align-items:center;flex-wrap:wrap" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml(r.driver_name)}${tierChip(r.tier)}</div>
            ${shiftMeta ? `<div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${shiftMeta}</div>` : ""}
          </div>
        </div>
      </td>
      <td style="padding:11px 14px;border-top:1px solid var(--border);white-space:nowrap;font-size:var(--fs-sm)">${timeStr}</td>
      <td style="padding:11px 14px;border-top:1px solid var(--border);font-size:var(--fs-sm)">${vanCell}</td>
      <td style="padding:11px 14px;border-top:1px solid var(--border);text-align:right">${statusPill(r.shift_status)}</td>
    </tr>`;
  }).join("");

  // Auto-assign button — only when at least one shift is showing the
  // "No van" gap.  Clicking calls today_roster_auto_assign which fills
  // the gaps with per-day overrides without touching the standing chain.
  const autoBtn = noVan > 0
    ? `<button type="button" class="btn btn-sm btn-primary" data-rr-tp-auto-assign style="display:inline-flex;align-items:center;gap:6px">
         <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>
         Auto-assign ${noVan} van${noVan === 1 ? "" : "s"}
       </button>`
    : "";

  wrap.innerHTML = `
    <div class="rr-tp-section-head" style="display:flex;align-items:center;gap:var(--s-2-5)">
      <span>Today's roster · drivers + vans</span>
      <span style="font-size:var(--fs-xs);font-weight:500;color:var(--text-subtle)">${rows.length} scheduled</span>
      <div style="margin-left:auto;display:flex;align-items:center;gap:var(--s-3)">${headRight}${autoBtn}</div>
    </div>
    <div style="overflow-x:auto">
      <table style="width:100%;border-collapse:collapse;font-size:var(--fs-md)">
        <thead>
          <tr>
            <th style="text-align:left;padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle)">Driver</th>
            <th style="text-align:left;padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle)">Shift</th>
            <th style="text-align:left;padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle)">Van</th>
            <th style="text-align:right;padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--text-subtle)">Status</th>
          </tr>
        </thead>
        <tbody>${body}</tbody>
      </table>
    </div>`;
}

// ─── Today's roster · inline van picker ─────────────────────────────
// Small popover that lets the operator change (or clear) the van
// assigned to a driver for today.  Powered by:
//   • vehicles_pickable_for_day  → list of vans with committed/who
//   • vehicle_day_assignment_set → write the override (or clear)
// On save we re-render the roster card with the fresh today_roster.
async function _tpOpenVanPicker(anchorEl) {
  // Close any existing picker first.
  document.getElementById("rr-tp-vp-pop")?.remove();

  const driverId       = anchorEl.getAttribute("data-rr-tp-pick-van");
  const driverName     = anchorEl.getAttribute("data-rr-tp-pick-driver-name") || "Driver";
  const currentVanId   = anchorEl.getAttribute("data-rr-tp-pick-current") || "";
  const currentVia     = anchorEl.getAttribute("data-rr-tp-pick-via") || "";
  const todayIso       = fmtIsoDate(new Date());

  // Position the popover relative to the anchor.
  const rect = anchorEl.getBoundingClientRect();

  const pop = document.createElement("div");
  pop.id = "rr-tp-vp-pop";
  pop.innerHTML = `
    <style>
      #rr-tp-vp-pop{position:fixed;z-index:9998;background:var(--surface);border:1px solid var(--border-strong);border-radius:var(--r-lg);box-shadow:var(--shadow-pop);width:340px;max-height:420px;display:flex;flex-direction:column;overflow:hidden;font-size:var(--fs-md)}
      #rr-tp-vp-pop .vp-h{padding:11px 14px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}
      #rr-tp-vp-pop .vp-h .t{font-weight:600;font-size:var(--fs-sm);color:var(--text);min-width:0;text-overflow:ellipsis;white-space:nowrap;overflow:hidden}
      #rr-tp-vp-pop .vp-h .s{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px}
      #rr-tp-vp-pop .vp-h button{background:none;border:0;color:var(--text-subtle);font-size:18px;cursor:pointer;line-height:1;padding:0 4px}
      #rr-tp-vp-pop .vp-search{padding:var(--s-2-5) var(--s-3);border-bottom:1px solid var(--border)}
      #rr-tp-vp-pop .vp-search input{width:100%;padding:7px 10px;border:1px solid var(--border);border-radius:var(--r-md);font:inherit;font-size:var(--fs-sm);background:var(--canvas);color:var(--text)}
      #rr-tp-vp-pop .vp-list{overflow-y:auto;flex:1}
      #rr-tp-vp-pop .vp-row{padding:var(--s-2-5) var(--s-3-5);border-top:1px solid var(--border);display:flex;align-items:center;gap:var(--s-2-5);cursor:pointer}
      #rr-tp-vp-pop .vp-row:first-child{border-top:0}
      #rr-tp-vp-pop .vp-row:hover{background:var(--canvas)}
      #rr-tp-vp-pop .vp-row.is-disabled{cursor:not-allowed;opacity:.55}
      #rr-tp-vp-pop .vp-row.is-disabled:hover{background:transparent}
      #rr-tp-vp-pop .vp-row.is-current{background:var(--accent-soft)}
      #rr-tp-vp-pop .vp-row.is-current:hover{background:var(--accent-soft)}
      #rr-tp-vp-pop .vp-row .nm{flex:1;min-width:0}
      #rr-tp-vp-pop .vp-row .nm .n{font-weight:600;display:flex;align-items:center;gap:var(--s-2)}
      #rr-tp-vp-pop .vp-row .nm .s{font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px}
      #rr-tp-vp-pop .vp-tag{font-size:9px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:2px 7px;border-radius:var(--r-md);background:var(--canvas);color:var(--text-muted);border:1px solid var(--border)}
      #rr-tp-vp-pop .vp-tag.current{background:var(--accent-soft);color:var(--accent-text);border-color:var(--accent-border)}
      #rr-tp-vp-pop .vp-tag.taken{background:var(--amber-soft);color:var(--amber-dark);border:1px solid rgba(245,158,11,.18)}
      #rr-tp-vp-pop .vp-foot{padding:var(--s-2-5) var(--s-3-5);border-top:1px solid var(--border);display:flex;gap:var(--s-2);justify-content:space-between}
      #rr-tp-vp-pop .vp-foot .btn{font-size:var(--fs-sm)}
    </style>
    <div class="vp-h">
      <div style="min-width:0">
        <div class="t">${escapeHtml(driverName)} · today</div>
        <div class="s">Pick a van — or clear to fall back to the standing chain.</div>
      </div>
      <button type="button" data-rr-tp-vp-close aria-label="Close">×</button>
    </div>
    <div class="vp-search"><input type="search" id="rr-tp-vp-search" placeholder="Search by name or plate…" autocomplete="off"></div>
    <div class="vp-list" id="rr-tp-vp-list"><div style="padding:18px;text-align:center;color:var(--text-subtle);font-size:var(--fs-sm)">Loading…</div></div>
    <div class="vp-foot">
      <button type="button" class="btn btn-sm" data-rr-tp-vp-clear${currentVanId ? "" : " disabled"}>Clear assignment</button>
      <button type="button" class="btn btn-sm" data-rr-tp-vp-close>Cancel</button>
    </div>`;
  document.body.appendChild(pop);

  // Position — prefer below the anchor; flip up if no room.
  const popW = 340;
  const popH = pop.offsetHeight || 420;
  let left = Math.max(8, Math.min(rect.left, window.innerWidth - popW - 8));
  let top  = rect.bottom + 6;
  if (top + popH > window.innerHeight - 8) top = Math.max(8, rect.top - popH - 6);
  pop.style.left = left + "px";
  pop.style.top  = top  + "px";

  // Outside-click closes — capture phase so it runs before list clicks.
  setTimeout(() => {
    const off = (ev) => {
      if (!pop.contains(ev.target)) { pop.remove(); document.removeEventListener("click", off, true); }
    };
    document.addEventListener("click", off, true);
    pop._rrOff = off;
  }, 0);

  // Close + clear handlers
  pop.addEventListener("click", async (e) => {
    if (e.target.closest("[data-rr-tp-vp-close]")) {
      pop.remove();
      if (pop._rrOff) document.removeEventListener("click", pop._rrOff, true);
      return;
    }
    if (e.target.closest("[data-rr-tp-vp-clear]")) {
      e.preventDefault();
      const btn = e.target.closest("[data-rr-tp-vp-clear]");
      if (btn.hasAttribute("disabled")) return;
      const { error } = await sb.rpc("vehicle_day_assignment_set", { p_driver_id: driverId, p_date: todayIso, p_vehicle_id: null });
      if (error) { toast("Couldn't clear: " + error.message, "warn"); return; }
      toast("Assignment cleared. Resolver will use the standing chain.", "ok");
      pop.remove();
      if (pop._rrOff) document.removeEventListener("click", pop._rrOff, true);
      _tpReloadRoster();
      return;
    }
    const row = e.target.closest("[data-rr-tp-vp-pick]");
    if (!row || row.classList.contains("is-disabled")) return;
    const vanId = row.getAttribute("data-rr-tp-vp-pick");
    if (vanId === currentVanId) {
      pop.remove();
      if (pop._rrOff) document.removeEventListener("click", pop._rrOff, true);
      return;
    }
    const { error } = await sb.rpc("vehicle_day_assignment_set", { p_driver_id: driverId, p_date: todayIso, p_vehicle_id: vanId });
    if (error) {
      const m = error.message || "";
      const msg =
        m.includes("vehicle_grounded")        ? "That van is grounded. Unground it on the Fleet roster before assigning it to a route."
      : m.includes("vehicle_already_assigned") ? "That van is already taken for today by someone else. Clear that driver first."
      :                                          "Couldn't save: " + m;
      toast(msg, "warn");
      return;
    }
    toast(`Assigned ${row.querySelector(".n")?.textContent?.trim() || "van"} to ${driverName} for today.`, "ok");
    pop.remove();
    if (pop._rrOff) document.removeEventListener("click", pop._rrOff, true);
    _tpReloadRoster();
  });

  // Load the pickable list.
  const { data: list, error: lerr } = await sb.rpc("vehicles_pickable_for_day", { p_date: todayIso, p_driver_id: driverId });
  const listEl = document.getElementById("rr-tp-vp-list");
  if (!listEl) return;
  if (lerr) { listEl.innerHTML = `<div style="padding:18px;color:var(--red);font-size:var(--fs-sm)">${escapeHtml(lerr.message)}</div>`; return; }
  const allVans = Array.isArray(list) ? list : [];
  // Operator asked the picker to show only vans they can assign right
  // now — not a roster of every vehicle. Filter out grounded, out-of-
  // service, and vans committed to another driver. The currently-
  // assigned van always stays in the list so the operator can see what
  // they're replacing.
  const isAvailable = (v) => {
    const grounded     = v.operational_status === "grounded";
    const takenByOther = v.committed && v.id !== currentVanId && v.committed_kind !== null;
    const oos          = v.status === "out_of_service";
    return !grounded && !takenByOther && !oos;
  };
  const vans = allVans.filter((v) => v.id === currentVanId || isAvailable(v));
  if (!vans.length) {
    listEl.innerHTML = `<div style="padding:24px 18px;text-align:center;color:var(--text-subtle);font-size:var(--fs-sm)">
      No vans available right now.
      <div style="margin-top:6px;font-size:var(--fs-xs)">Every van is grounded, out of service, or committed to another driver today.</div>
    </div>`;
    return;
  }
  const renderList = (filter) => {
    const q = (filter || "").toLowerCase();
    const filtered = q
      ? vans.filter((v) => [v.name, v.plate].filter(Boolean).join(" ").toLowerCase().includes(q))
      : vans;
    if (!filtered.length) {
      listEl.innerHTML = `<div style="padding:18px;text-align:center;color:var(--text-subtle);font-size:var(--fs-sm)">No vans match.</div>`;
      return;
    }
    listEl.innerHTML = filtered.map((v) => {
      const isCurrent = v.id === currentVanId;
      const cls = "vp-row" + (isCurrent ? " is-current" : "");
      const opAttrs = `data-rr-tp-vp-pick="${escapeHtml(v.id)}"`;
      const sub = [];
      if (v.plate) sub.push(escapeHtml(v.plate));
      if (v.status === "spare") sub.push("Spare");
      const tag = isCurrent ? `<span class="vp-tag current">Current</span>` : "";
      return `<div class="${cls}" ${opAttrs}>
        <div class="nm">
          <div class="n">${escapeHtml(v.name)}${tag ? " " + tag : ""}</div>
          ${sub.length ? `<div class="s">${sub.join(" · ")}</div>` : ""}
        </div>
      </div>`;
    }).join("");
  };
  renderList("");

  const searchInput = document.getElementById("rr-tp-vp-search");
  if (searchInput) {
    searchInput.focus();
    let t = null;
    searchInput.addEventListener("input", (ev) => {
      clearTimeout(t);
      t = setTimeout(() => renderList(ev.target.value || ""), 80);
    });
  }
}

function _tpReloadRoster() {
  // The unified renderer reads both today_attendance and today_roster,
  // so re-run the master refresh instead of duplicating that logic.
  if (typeof _refreshTodayPlanData === "function") _refreshTodayPlanData();
}

// ── Today's Plan · 7-day date navigator wiring ──────────────────────
document.addEventListener("click", (e) => {
  if (!e.target.closest) return;
  // Legacy page-header nav (removed from the markup but handlers kept
  // in case other surfaces still reference these IDs).
  if (e.target.closest("#rr-tp-prev"))   { e.preventDefault(); _tpDateShift(-1); return; }
  if (e.target.closest("#rr-tp-next"))   { e.preventDefault(); _tpDateShift( 1); return; }
  if (e.target.closest("#rr-tp-today"))  {
    e.preventDefault();
    _tpDateGoTo(_tpToday());
    return;
  }
  // New in-shell day strip.
  if (e.target.closest("#rr-tp-daystrip-prev"))  { e.preventDefault(); _tpDateShift(-1); return; }
  if (e.target.closest("#rr-tp-daystrip-next"))  { e.preventDefault(); _tpDateShift( 1); return; }
  if (e.target.closest("#rr-tp-daystrip-today")) {
    e.preventDefault();
    _tpDateGoTo(_tpToday());
    return;
  }
  const cell = e.target.closest("[data-tp-day-iso]");
  if (cell) {
    e.preventDefault();
    _tpDateGoTo(cell.getAttribute("data-tp-day-iso"));
    return;
  }
});
// Keyboard shortcut: ← / → walk the navigator when the Today's Plan
// shell is visible on either the dashboard's Today nav or the
// schedule's Today sub-view. Ignored when the operator is typing.
document.addEventListener("keydown", (e) => {
  if (e.altKey || e.ctrlKey || e.metaKey) return;
  const tag = (e.target?.tagName || "").toLowerCase();
  if (tag === "input" || tag === "textarea" || tag === "select" || e.target?.isContentEditable) return;
  const shellVisible = !!document.getElementById("rr-today-plan-shell")?.offsetParent;
  if (!shellVisible) return;
  if (e.key === "ArrowLeft")  _tpDateShift(-1);
  if (e.key === "ArrowRight") _tpDateShift( 1);
});

function _renderTpCoverage(data, error) {
  const covEl = document.getElementById("rr-tp-cov");
  if (!covEl) return;

  const headHtml = (subtext) => `
    <div class="card-section-head">
      Coverage${subtext ? ` <span style="color:var(--text-subtle);font-weight:600">· ${subtext}</span>` : ""}
    </div>`;

  if (error) {
    // The most common case here is migration 0068 not yet applied —
    // surface a friendly hint instead of just the SQL error.
    const msg = String(error.message || error || "");
    const hint = /not find|does not exist|today_plan/i.test(msg)
      ? `Coverage view needs migration 0068 (today_plan). Apply it via Supabase SQL Editor and refresh.`
      : msg;
    covEl.innerHTML = `${headHtml("")}
      <div style="padding:18px;color:var(--amber);font-size:var(--fs-sm);text-align:center">${escapeHtml(hint)}</div>`;
    return;
  }

  const open  = data?.open_shifts       || [];
  const dlExp = data?.dl_expiring       || [];
  const noDot = data?.not_dot_certified || [];

  const openRows = open.length === 0
    ? `<div style="padding:18px;text-align:center;color:var(--green);font-size:var(--fs-sm);font-weight:600">✓ All shifts assigned</div>`
    : open.map(o => {
        const t = o.starts_at ? new Date(o.starts_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : "—";
        const svc = o.service_type_code ? `<span style="background:${o.service_type_color || "#94a3b8"}22;color:${o.service_type_color || "#94a3b8"};padding:2px 6px;border-radius:var(--r-sm);font-size:var(--fs-xs);font-weight:700;margin-left:6px">${escapeHtml(o.service_type_code)}</span>` : "";
        const cushion = o.is_cushion ? `<span style="background:rgba(180,83,9,.15);color:var(--amber);padding:2px 6px;border-radius:var(--r-sm);font-size:var(--fs-xs);font-weight:700;margin-left:6px">EX</span>` : "";
        return `<div style="display:flex;justify-content:space-between;align-items:center;padding:var(--s-2) 14px;border-top:1px solid var(--border);font-size:var(--fs-md)">
          <div><strong>${escapeHtml(o.station_code || "—")}</strong> · ${escapeHtml(t)} · Wave ${o.wave_index ?? 0}${svc}${cushion}</div>
          <button class="btn btn-sm" onclick="goto('schedule')">Assign</button>
        </div>`;
      }).join("");

  const dlRows = dlExp.length === 0 ? "" :
    `<div style="padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);border-top:1px solid var(--border);font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">Driver license expiring soon · ${dlExp.length}</div>`
    + dlExp.map(d => {
        const days = Number(d.days_left);
        const tone = days <= 0 ? "var(--red)" : (days <= 2 ? "var(--amber)" : "var(--text-muted)");
        const label = days < 0 ? `Expired ${-days}d ago` : days === 0 ? "Expires today" : `${days}d left`;
        return `<div style="display:grid;grid-template-columns:1fr auto;gap:var(--s-2-5);padding:var(--s-2) 14px;border-top:1px solid var(--border);font-size:var(--fs-md);align-items:center">
          <div data-rr-driver-id="${escapeHtml(d.driver_id)}" style="font-weight:600;cursor:pointer">${escapeHtml(d.driver_name)}</div>
          <span style="color:${tone};font-weight:700;font-size:var(--fs-sm)">${escapeHtml(label)}</span>
        </div>`;
      }).join("");

  // Drop the "active drivers without DOT certification" list on the
  // home page per product direction — that lives on the Drivers
  // licenses tab, no need to repeat it here.
  covEl.innerHTML = `${headHtml(`${open.length} open · ${dlExp.length} DL`)}
    ${openRows}${dlRows}`;
}


// ─── Drivers · Attendance · Today ──────────────────────────────────────
// Live KPI card + roster of who hasn't checked in. Polls every 15 s
// while the tab is visible. Operator can finalize the day with one
// click; that stamps every row's final_outcome and locks them so the
// permanent attendance record is immutable.

const _RR_OUTCOME_LABEL = {
  waiting:          "Waiting",
  ready_to_checkin: "Ready",
  checked_in:       "Checked in",
  checked_out:      "Done",
  missed_reported:  "Missed (reported)",
  tardy:            "Tardy",
  ncns:             "NCNS",
};
const _RR_OUTCOME_TONE = {
  waiting:          { bg: "var(--canvas)",            fg: "var(--text-subtle)" },
  ready_to_checkin: { bg: "var(--accent-soft)",       fg: "var(--accent)" },
  checked_in:       { bg: "rgba(22,163,74,.15)",      fg: "var(--green)" },
  checked_out:      { bg: "rgba(22,163,74,.10)",      fg: "var(--green)" },
  missed_reported:  { bg: "rgba(180,83,9,.15)",       fg: "var(--amber)" },
  tardy:            { bg: "rgba(180,83,9,.20)",       fg: "var(--amber)" },
  ncns:             { bg: "rgba(220,38,38,.15)",      fg: "var(--red)" },
};

let _todayAttPollTimer = null;

async function loadTodayAttendance() {
  const wrap = document.getElementById("rr-today-shell");
  if (!wrap) return;

  if (_todayAttPollTimer) clearInterval(_todayAttPollTimer);
  _todayAttPollTimer = setInterval(() => {
    if (document.getElementById("att-pane-today")?.classList.contains("active")
        && !document.hidden) {
      loadTodayAttendance();
    } else {
      clearInterval(_todayAttPollTimer); _todayAttPollTimer = null;
    }
  }, 15000);

  const { data, error } = await sb.rpc("today_attendance");
  if (error) {
    wrap.innerHTML = `<div style="padding:var(--s-6);color:var(--red);font-size:var(--fs-md)">${escapeHtml(error.message)}</div>`;
    return;
  }
  const rows = data?.rows || [];
  if (rows.length === 0) {
    wrap.innerHTML = `<div class="rr-empty-inline">No drivers scheduled for today.</div>`;
    return;
  }

  // Bucket counts by computed outcome for the KPI strip.
  const cnt = { total: rows.length, present: 0, working: 0, ready: 0, waiting: 0,
                missed: 0, tardy: 0, ncns: 0, finalized: 0 };
  for (const r of rows) {
    if (r.finalized) cnt.finalized++;
    switch (r.computed_outcome) {
      case "checked_in":     cnt.working++; cnt.present++; break;
      case "checked_out":                cnt.present++; break;
      case "ready_to_checkin": cnt.ready++; break;
      case "waiting":        cnt.waiting++; break;
      case "missed_reported": cnt.missed++; break;
      case "tardy":          cnt.tardy++; break;
      case "ncns":           cnt.ncns++; break;
    }
  }
  const notCheckedInYet = cnt.total - (cnt.working + (rows.filter(r => r.computed_outcome === "checked_out").length));

  // Wave + service-type breakdown.
  const byWave = {};
  const bySvc  = {};
  for (const r of rows) {
    const w = r.wave_index ?? 0;
    byWave[w] = (byWave[w] || 0) + 1;
    const k = r.service_type_code || "—";
    if (!bySvc[k]) bySvc[k] = { count: 0, color: r.service_type_color || "#94a3b8" };
    bySvc[k].count++;
  }

  const kpiCard = (label, value, sub, tone) => `
    <div class="card card-compact">
      <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-subtle);letter-spacing:.06em;text-transform:uppercase">${escapeHtml(label)}</div>
      <div style="font-size:26px;font-weight:700;margin-top:4px;color:${tone || "var(--text)"}">${escapeHtml(String(value))}</div>
      ${sub ? `<div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${sub}</div>` : ""}
    </div>`;

  // Driver-row renderer.
  const rowHtml = (r) => {
    const tone = _RR_OUTCOME_TONE[r.computed_outcome] || _RR_OUTCOME_TONE.waiting;
    const label = _RR_OUTCOME_LABEL[r.computed_outcome] || r.computed_outcome;
    const t = r.starts_at ? new Date(r.starts_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : "—";
    const inT = r.checked_in_at ? new Date(r.checked_in_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }) : null;
    const noteBits = [];
    if (inT) noteBits.push("In " + inT);
    if (r.distance_meters != null && inT) noteBits.push(`${r.distance_meters} m`);
    if (r.missed_reason) noteBits.push(`"${r.missed_reason}"`);
    return `
      <div style="display:grid;grid-template-columns:36px 1fr auto;gap:var(--s-3);align-items:center;padding:var(--s-2-5) var(--s-3-5);border-top:1px solid var(--border)">
        <div class="avatar-sm" data-rr-driver-id="${escapeHtml(r.driver_id)}">${escapeHtml((r.driver_name || "?").split(/\s+/).map(p => p[0]).filter(Boolean).slice(0,2).join("").toUpperCase())}</div>
        <div style="min-width:0">
          <div style="font-size:var(--fs-md);font-weight:600;color:var(--text)">${escapeHtml(r.driver_name)}</div>
          <div class="u-xs-subtle">${escapeHtml(r.station_code || "—")} · ${escapeHtml(t)}${noteBits.length ? " · " + escapeHtml(noteBits.join(" · ")) : ""}</div>
        </div>
        <span style="background:${tone.bg};color:${tone.fg};font-size:var(--fs-xs);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:var(--s-1) 10px;border-radius:var(--r-lg)">${escapeHtml(label)}</span>
      </div>`;
  };

  // Group by status — operator scans top-down: NCNS · tardy · ready · waiting · missed · checked-in.
  const groupOrder = [
    ["ncns",            "No-call no-show"],
    ["tardy",           "Tardy"],
    ["ready_to_checkin","Ready to check in"],
    ["waiting",         "Waiting · before window"],
    ["missed_reported", "Missed day · reported"],
    ["checked_in",      "Checked in · working"],
    ["checked_out",     "Shift complete"],
  ];
  const grouped = groupOrder.map(([k, label]) => {
    const items = rows.filter(r => r.computed_outcome === k);
    if (items.length === 0) return "";
    return `
      <div class="card card-flush u-mb-4">
        <div style="padding:var(--s-2-5) var(--s-3-5);background:var(--canvas);border-bottom:1px solid var(--border);font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">
          ${escapeHtml(label)} <span style="color:var(--text-subtle);font-weight:600">· ${items.length}</span>
        </div>
        ${items.map(rowHtml).join("")}
      </div>`;
  }).join("");

  const waveLine = Object.keys(byWave).sort()
    .map(w => `Wave ${w}: <strong>${byWave[w]}</strong>`).join(" · ");
  const svcChips = Object.entries(bySvc)
    .map(([code, v]) => `<span style="display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:var(--r-lg);background:${v.color}22;color:${v.color};font-size:var(--fs-xs);font-weight:600;margin-right:4px">${escapeHtml(code)} · ${v.count}</span>`)
    .join("");

  wrap.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:var(--s-2-5);margin-bottom:14px">
      ${kpiCard("Scheduled", cnt.total, waveLine || "today")}
      ${kpiCard("Not checked in", Math.max(0, notCheckedInYet), `${cnt.ready} ready · ${cnt.waiting} waiting`, notCheckedInYet > 0 ? "var(--amber)" : undefined)}
      ${kpiCard("Tardy / NCNS", cnt.tardy + cnt.ncns, `${cnt.tardy} tardy · ${cnt.ncns} no-show`, (cnt.tardy + cnt.ncns) > 0 ? "var(--red)" : undefined)}
      ${kpiCard("Working", cnt.working, `${cnt.missed} missed reported`, cnt.working > 0 ? "var(--green)" : undefined)}
    </div>

    <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:var(--s-2-5) var(--s-3-5);margin-bottom:14px;font-size:var(--fs-sm);color:var(--text-muted);display:flex;justify-content:space-between;align-items:center;gap:var(--s-3);flex-wrap:wrap">
      <div>${svcChips || "<span style='color:var(--text-subtle)'>No service-type breakdown</span>"}</div>
      <div style="display:flex;gap:var(--s-2);align-items:center">
        <span class="u-xs-subtle">As of ${escapeHtml(new Date(data.as_of).toLocaleTimeString())}</span>
        <button class="btn btn-sm" id="rr-today-refresh">Refresh</button>
        <button class="btn btn-sm btn-primary" id="rr-today-finalize" ${cnt.finalized === cnt.total ? "disabled" : ""}>${cnt.finalized === cnt.total ? "Already finalized" : "Approve & finalize day"}</button>
      </div>
    </div>

    ${grouped}
  `;

  document.getElementById("rr-today-refresh").addEventListener("click", loadTodayAttendance);
  document.getElementById("rr-today-finalize").addEventListener("click", async () => {
    if (!(await _rrConfirmDialog({ title: "Finalize today's attendance?", body: "This locks every record for today into the permanent log. Pending check-ins after this won't be retroactive without re-opening the day.", confirmLabel: "Finalize" }))) return;
    const today = new Date().toISOString().slice(0, 10);
    const { error } = await sb.rpc("attendance_approve_day", { p_day: today });
    if (error) { toast("Finalize failed: " + error.message, "warn"); return; }
    toast("Day finalized · permanent record updated", "success");
    loadTodayAttendance();
  });
}



async function loadDriverLicensesView() {
  const body = document.getElementById("lic-renewals-body");
  if (!body) return;

  // Wipe synchronously so any mockup-rendered rows can't flash through
  // while the live select is in flight.
  body.innerHTML = _drSkelList(7);

  const { data: rows, error } = await sb.from("drivers")
    .select("id, full_name, station:station_id (code), dl_number, dl_expires_on, status")
    .eq("dsp_id", window.RR.dsp.id)
    .not("dl_expires_on", "is", null)
    .order("dl_expires_on", { ascending: true })
    .limit(500);

  if (error) {
    body.innerHTML = _rosterEmpty({ error: true, title: "Couldn't load licenses", body: escapeHtml(error.message) });
    return;
  }
  // Licenses tab only surfaces drivers whose license is expiring within
  // the next 30 days (or already expired). Anything valid past that
  // horizon lives quietly on the driver record.
  const visible = (rows || []).filter((d) => {
    if (!d.dl_expires_on) return false;
    const days = Math.floor((new Date(d.dl_expires_on).getTime() - Date.now()) / 86400000);
    return days <= 30;
  });
  if (visible.length === 0) {
    body.innerHTML = _rosterEmpty({
      icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="2"/><line x1="3" y1="10" x2="21" y2="10"/><line x1="7" y1="15" x2="13" y2="15"/></svg>',
      title: "No licenses expiring soon",
      body: "Drivers whose license is within 30 days of expiring — or already expired — surface here automatically.",
    });
    return;
  }

  body.innerHTML = `
    <table class="table table-clickable">
      <thead><tr>
        <th style="width:32%">Driver</th>
        <th style="width:14%">Station</th>
        <th style="width:20%">DL number</th>
        <th style="width:18%">Status</th>
        <th style="width:16%">Expires</th>
      </tr></thead>
      <tbody>${visible.map(renderLicenseRow).join("")}</tbody>
    </table>`;
}

function _licenseStatusText(days) {
  if (days < 0)   return "Expired";
  if (days === 0) return "Expires today";
  if (days <= 14) return `Expires in ${days} day${days === 1 ? "" : "s"}`;
  return `Expires in ${days} days`;
}
function renderLicenseRow(d) {
  const exp = new Date(d.dl_expires_on);
  const days = Math.floor((exp.getTime() - Date.now()) / 86400000);
  const initials = displayDriverInitials(d);
  const rel = days < 0 ? `Expired ${-days}d ago` : days === 0 ? "Expires today" : `in ${days}d`;
  // Within 14 days of expiry (including already expired) → red left bar,
  // mirroring the Work Authorization "attention" treatment.
  const danger = days <= 14;
  const rowStyle = danger ? ' style="box-shadow:inset 3px 0 0 var(--red)"' : "";
  return `
    <tr data-driver-id="${d.id}" data-rr-open-driver${rowStyle}>
      <td><div class="cell-driver"><div class="avatar-sm">${initials}</div><div><div class="cell-name">${escapeHtml(displayDriverName(d))}</div></div></div></td>
      <td>${d.station?.code ? escapeHtml(d.station.code) : '<span class="u-subtle">—</span>'}</td>
      <td style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:var(--fs-sm)">${escapeHtml(d.dl_number || "—")}</td>
      <td>${escapeHtml(_licenseStatusText(days))}<div>${rrQtLink({
        hover: true,
        label: "Add renewal task",
        title: `Collect updated license from ${displayDriverName(d)} — ${days < 0 ? "expired" : `expires ${exp.toLocaleDateString(undefined, { month: "short", day: "numeric" })}`}`,
        description: `Driver's license ${_licenseStatusText(days).toLowerCase()} (${exp.toLocaleDateString()}). An expired DL blocks scheduling.\nOpen: Drivers → ${displayDriverName(d)} → Documents`,
        category: "Driver Compliance",
        sourceKey: `dl:${d.id}`,
        entityType: "driver",
        entityId: d.id,
        due: days < 0 ? _rrQtNextBusinessDay() : _rrQtDueBefore(d.dl_expires_on, 7),
      })}</div></td>
      <td>${exp.toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"})}<div class="u-xs-subtle">${rel}</div></td>
    </tr>`;
}

const _legacyDrSub = window.drSub;
window.drSub = function (sub) {
  // Close any open KPI drilldowns on subview navigation so they
  // don't reappear when the operator comes back to the page.
  if (typeof _closeAttKpiDetail === "function")     _closeAttKpiDetail();
  if (typeof _closeAvailKpiDetail === "function")   _closeAvailKpiDetail();
  if (typeof _closeRosterKpiDetail === "function")  _closeRosterKpiDetail();
  if (typeof _legacyDrSub === "function") _legacyDrSub(sub);
  // Insights strips collapse on every subview entry so the operator
  // lands on the table-first view each time. The Event log link also
  // resets so re-entering Attendance always starts on the Report pane.
  ["rr-att-insights", "rr-avail-insights"].forEach((id) => {
    const el = document.getElementById(id); if (el) el.style.display = "none";
  });
  document.querySelectorAll("#rr-att-insights-toggle, #rr-avail-insights-toggle, #rr-att-log-toggle").forEach((t) => {
    t.setAttribute("aria-pressed", "false"); t.classList.remove("is-on");
  });
  if (sub === "attendance") {
    document.querySelectorAll('#dr-sub-attendance .att-pane').forEach((p) => p.classList.remove("active"));
    document.getElementById("att-pane-report")?.classList.add("active");
  }
  if (sub === "licenses")     loadDriverLicensesView();
  if (sub === "roster")       loadDriversRoster();
  if (sub === "attendance")   { _rrApplyAttPolicyMode(); loadAttendanceLive(); _rrInitAttTabDnD(); }
  if (sub === "coaching")     loadCoachingFeed();
  if (sub === "availability") loadAvailabilityRequests();
  if (sub === "workauth")     loadDriverWorkAuthView();
  _swapDriversCta(sub);
};

// Swap the page-level CTA so it matches the active subnav. On Coaching,
// 'Add driver' becomes 'Coach a driver' and opens a driver picker that
// drops into the coaching log form for the chosen driver.
function _swapDriversCta(/* sub */) {
  // The Add driver button now lives in the Roster sub-tab's toolbar
  // (top-left of the table) and the Coach a driver button has its own
  // dedicated home in the Coaching sub-tab toolbar — no swap needed.
  // Function kept as a no-op so existing call sites don't throw.
}

// Wire the Coach a driver CTA in the Coaching sub-tab toolbar.
document.addEventListener("click", (e) => {
  if (e.target.closest("#rr-coach-cta")) {
    e.preventDefault();
    openCoachDriverPicker();
  }
});

// Driver picker → coaching log. Shown when the operator clicks 'Coach
// a driver' on Drivers > Coaching. Pick a driver from the list, modal
// closes, the coaching log form opens for that driver.
async function openCoachDriverPicker() {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;

  const { data, error } = await sb.from("drivers")
    .select("id, full_name, preferred_name, station:station_id (code)")
    .eq("dsp_id", dspId)
    .in("status", ["active", "onboarding"])
    .order("full_name");
  if (error) { toast("Couldn't load drivers: " + error.message, "warn"); return; }
  const drivers = data || [];
  if (drivers.length === 0) {
    toast("Add a driver first, then come back here to coach them.", "warn");
    return;
  }

  const m = document.createElement("div");
  m.id = "rr-coach-picker";
  m.style.cssText = "position:fixed;inset:0;background:var(--overlay);z-index:10000;display:flex;align-items:center;justify-content:center;padding:var(--s-6)";
  m.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);padding:18px 18px 14px;max-width:440px;width:100%;max-height:80vh;display:flex;flex-direction:column">
      <h3 style="margin:0 0 10px;font-size:var(--fs-lg);font-weight:600">Coach a driver</h3>
      <input id="rr-coach-picker-search" type="text" placeholder="Search drivers…" class="form-input" style="margin-bottom:10px"/>
      <div id="rr-coach-picker-list" style="flex:1;overflow-y:auto;border:1px solid var(--border);border-radius:8px"></div>
      <div style="display:flex;justify-content:flex-end;margin-top:var(--s-3)">
        <button class="btn" type="button" data-rr-coach-picker-cancel>Cancel</button>
      </div>
    </div>`;
  document.body.appendChild(m);

  const list = m.querySelector("#rr-coach-picker-list");
  const renderList = (filter) => {
    const f = (filter || "").toLowerCase().trim();
    const matches = !f ? drivers : drivers.filter(d => {
      const name = (d.preferred_name || d.full_name || "").toLowerCase();
      return name.includes(f);
    });
    if (matches.length === 0) {
      list.innerHTML = `<div class="rr-empty-inline">No drivers match.</div>`;
      return;
    }
    list.innerHTML = matches.map(d => {
      const display = d.preferred_name || d.full_name || "—";
      const station = d.station?.code || "";
      return `<div class="rr-coach-pick" data-id="${d.id}" style="padding:var(--s-2-5) var(--s-3-5);border-bottom:1px solid var(--border);cursor:pointer;display:flex;align-items:center;justify-content:space-between;font-size:var(--fs-md)">
        <span><strong>${escapeHtml(display)}</strong>${station ? ` <span style="color:var(--text-subtle);font-weight:400;margin-left:6px">${escapeHtml(station)}</span>` : ""}</span>
        <span style="color:var(--text-subtle);font-size:var(--fs-xs)">Coach →</span>
      </div>`;
    }).join("");
  };
  renderList();

  m.querySelector("#rr-coach-picker-search").addEventListener("input", (e) => renderList(e.target.value));
  m.addEventListener("click", (e) => {
    if (e.target === m || e.target.closest("[data-rr-coach-picker-cancel]")) { m.remove(); return; }
    const pick = e.target.closest(".rr-coach-pick");
    if (pick) {
      const id = pick.getAttribute("data-id");
      m.remove();
      // Same coaching log flow used everywhere else (drawer, etc.).
      // _ddDriver isn't required for create-mode; openCoachingForm only
      // needs the driverId.
      if (typeof openCoachingForm === "function") openCoachingForm(id);
    }
  });
}


let _dowMath = null;
document.addEventListener("click", (e) => {
  if (!e.target.closest("#rr-di-dow-info")) return;
  e.preventDefault();
  const m = _dowMath;
  if (!m) return;
  const old = document.getElementById("rr-di-dow-popover");
  if (old) { old.remove(); return; }
  const DOW = ["mon","tue","wed","thu","fri","sat","sun"];
  const DOW_LABEL = { mon:"Mon", tue:"Tue", wed:"Wed", thu:"Thu", fri:"Fri", sat:"Sat", sun:"Sun" };
  const tableRows = DOW.map(d => {
    const tot = m.dowTotal[d], abs = m.dowAbsent[d];
    const rate = tot > 0 ? (abs / tot * 100).toFixed(1) : "—";
    // Neutral throughout — no stoplight tint on insight popovers.
    const color = "var(--text)";
    return `
    <tr>
      <td style="padding:5px 10px;border-bottom:1px solid var(--border)"><strong>${DOW_LABEL[d]}</strong></td>
      <td style="padding:5px 10px;border-bottom:1px solid var(--border);text-align:right">${tot}</td>
      <td style="padding:5px 10px;border-bottom:1px solid var(--border);text-align:right">${abs}</td>
      <td style="padding:5px 10px;border-bottom:1px solid var(--border);text-align:right;color:${color};font-weight:600">${tot > 0 ? rate + "%" : "—"}</td>
    </tr>`;
  }).join("");
  const pop = document.createElement("div");
  pop.id = "rr-di-dow-popover";
  pop.style.cssText = "position:fixed;inset:0;background:var(--overlay);z-index:10000;display:flex;align-items:center;justify-content:center;padding:var(--s-6)";
  pop.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:22px;max-width:520px;width:100%;font-size:var(--fs-md);line-height:1.55;color:var(--text);max-height:80vh;overflow-y:auto">
      <h3 style="margin:0 0 14px;font-size:var(--fs-lg);font-weight:600">Day-of-week absence · the math</h3>
      <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.05em;text-transform:uppercase;margin-bottom:6px">Window</div>
      <div>Last <strong>90 days</strong>. Each shift counted once on the day it was scheduled.</div>
      <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.05em;text-transform:uppercase;margin-top:14px;margin-bottom:6px">Definitions</div>
      <div>· <strong>Total</strong> = shifts that had any outcome (completed, late, called_off, no_show, vto). Pure 'scheduled' (not yet started) is excluded.</div>
      <div>· <strong>Absences</strong> = called_off + no_show only. VTO is operator-approved and doesn't count.</div>
      <div style="font-family:ui-monospace,monospace;font-size:var(--fs-xs);background:var(--canvas);padding:var(--s-2) var(--s-2-5);border-radius:var(--r-sm);color:var(--text);margin-top:var(--s-2)">% absent = absences ÷ total</div>
      <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.05em;text-transform:uppercase;margin-top:14px;margin-bottom:6px">By day</div>
      <table style="width:100%;border-collapse:collapse;font-size:var(--fs-sm);margin-top:6px">
        <thead>
          <tr>
            <th style="padding:6px var(--s-2-5);text-align:left;background:var(--canvas);font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">Day</th>
            <th style="padding:6px var(--s-2-5);text-align:right;background:var(--canvas);font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">Total</th>
            <th style="padding:6px var(--s-2-5);text-align:right;background:var(--canvas);font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">Absences</th>
            <th style="padding:6px var(--s-2-5);text-align:right;background:var(--canvas);font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase">% absent</th>
          </tr>
        </thead>
        <tbody>${tableRows}</tbody>
      </table>
      <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.05em;text-transform:uppercase;margin-top:14px;margin-bottom:6px">Color thresholds</div>
      <div>· <strong style="color:var(--red)">Red</strong> = ≥1.5× the overall rate (and >5%)</div>
      <div>· <strong style="color:var(--amber)">Amber</strong> = ≥1.2× the overall rate</div>
      <div>· <strong style="color:var(--green-bright)">Green</strong> = at or below the overall rate</div>
      <div>· <span class="u-muted">Grey</span> = no shifts on that day in the window</div>
      <div style="margin-top:18px;display:flex;justify-content:flex-end">
        <button class="btn btn-sm" type="button" id="rr-di-dow-popover-close">Close</button>
      </div>
    </div>`;
  pop.addEventListener("click", (ev) => {
    if (ev.target === pop || ev.target.id === "rr-di-dow-popover-close") pop.remove();
  });
  document.body.appendChild(pop);
});


// Renewal-reminder settings live in Settings → License renewals
// (auto-reminders, channels, days, template), written to
// dsps.metadata.licenses so the background reminder job reads one place.
// (The old "block scheduling past expiry" toggle was removed — it wrote
// block_past_expiry, which no scheduling / Cover / pickup / swap code
// read; the live DL gate is Smart Fill's dl_valid rule on the Schedule view.)
function _rrPrefillLicenseSettings() {
  const lic = window.RR?.dsp?.metadata?.licenses || {};
  const setBool = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.checked = !!val;
  };
  // auto_reminders defaults ON when no record yet, to match the
  // previous mockup behavior.
  setBool("rr-lic-toggle-input",  lic.auto_reminders !== false);
  // Channels: default to SMS on (the historical channel) and in-app
  // off.  Operators opt into in-app explicitly.
  setBool("rr-lic-channel-sms",   lic.channel_sms   !== false);
  setBool("rr-lic-channel-inapp", lic.channel_inapp === true);

  const days = document.getElementById("rr-lic-days");
  if (days) days.value = Array.isArray(lic.reminder_days) ? lic.reminder_days.join(", ") : "30, 14";
  const tpl = document.getElementById("rr-lic-template");
  if (tpl && lic.sms_template) tpl.value = lic.sms_template;
}
// Hydrate when the operator opens Settings or Schedule rules.
document.addEventListener("click", (e) => {
  if (e.target.closest('.settings-nav-item[data-set="licenses"]') ||
      e.target.closest('[data-rr-nav-item="settings"]')           ||
      e.target.closest('a[href="#schedule"]')) {
    setTimeout(_rrPrefillLicenseSettings, 0);
  }
});
// Wrap goto so navigating to Settings or Schedule prefills too.
const _legacyGotoForLic = window.goto;
if (typeof _legacyGotoForLic === "function") {
  window.goto = function (view) {
    const r = _legacyGotoForLic(view);
    if (view === "settings" || view === "schedule") setTimeout(_rrPrefillLicenseSettings, 0);
    return r;
  };
}

document.addEventListener("click", async (e) => {
  if (!e.target.closest("[data-rr-lic-save]")) return;
  e.preventDefault();
  const status = document.getElementById("rr-lic-status");
  const setStatus = (text, kind) => {
    if (!status) return;
    status.style.color = kind === "warn" ? "var(--red)" : kind === "ok" ? "var(--green)" : "var(--text-subtle)";
    status.textContent = text;
  };
  const get = (id) => document.getElementById(id);
  const enabled  = get("rr-lic-toggle-input")?.checked;
  const sms      = get("rr-lic-channel-sms")?.checked;
  const inapp    = get("rr-lic-channel-inapp")?.checked;
  const daysRaw  = get("rr-lic-days")?.value || "";
  const template = get("rr-lic-template")?.value || "";
  const days = daysRaw.split(/[,\s]+/).map(s => parseInt(s, 10)).filter(n => Number.isFinite(n) && n > 0);

  setStatus("Saving…");
  const { data: dsp, error: rErr } = await sb.from("dsps").select("metadata").eq("id", window.RR.dsp.id).single();
  if (rErr) { setStatus(rErr.message, "warn"); return; }
  const md = dsp.metadata || {};
  md.licenses = {
    ...(md.licenses || {}),
    auto_reminders:    !!enabled,
    channel_sms:       !!sms,
    channel_inapp:     !!inapp,
    reminder_days:     days,
    sms_template:      template,
  };
  const { error: wErr } = await sb.from("dsps").update({ metadata: md }).eq("id", window.RR.dsp.id);
  if (wErr) { setStatus(wErr.message, "warn"); return; }
  window.RR.dsp.metadata = md;
  setStatus(`Saved at ${new Date().toLocaleTimeString()}`, "ok");
});

// Driver-message controls in the Smart Fill ("Who can work") rules · persist
// to dsps.metadata.licenses (server-side) on change so a reminder job can
// read them, and so the same values drive the DL flag's notice window.
document.addEventListener("change", async (e) => {
  const t = e.target;
  if (!t || (t.id !== "rr-sf-dl-msg-enable" && t.id !== "rr-sf-dl-msg-days")) return;
  const enableEl = document.getElementById("rr-sf-dl-msg-enable");
  const daysEl   = document.getElementById("rr-sf-dl-msg-days");
  let n = parseInt(daysEl && daysEl.value, 10);
  if (!Number.isFinite(n) || n < 1) n = 30;
  if (n > 365) n = 365;
  if (daysEl) daysEl.value = String(n);
  try {
    const { data: dsp, error: rErr } = await sb.from("dsps").select("metadata").eq("id", window.RR.dsp.id).single();
    if (rErr) throw rErr;
    const md = dsp.metadata || {};
    md.licenses = {
      ...(md.licenses || {}),
      auto_reminders: !!(enableEl && enableEl.checked),
      reminder_days:  [n],
    };
    const { error: wErr } = await sb.from("dsps").update({ metadata: md }).eq("id", window.RR.dsp.id);
    if (wErr) throw wErr;
    window.RR.dsp.metadata = md;
  } catch (err) {
    console.warn("Save DL message settings:", err && err.message);
  }
});

function renderDriverStatusBadge(s) {
  const map = {
    onboarding: { label: "Onboarding", style: "background:rgba(37,99,235,.14);color:#2563EB" },
    active:     { label: "Active",     style: "background:var(--green-soft);color:var(--green)" },
    leave:      { label: "On leave",   style: "background:var(--amber-soft);color:var(--amber)" },
    inactive:   { label: "Inactive",   style: "background:var(--canvas);color:var(--text-subtle)" },
    terminated: { label: "Terminated", style: "background:var(--red-soft);color:var(--red)" },
  };
  const v = map[s] || { label: s, style: "" };
  return `<span class="tag" style="${v.style}">${v.label}</span>`;
}

// Status → label + text-color token, preserving the roster/KPI status
// palette. Used for the inline status word in the driver-record header
// metadata line ("DCA1 • Active") so the status keeps its color without a
// full badge pill (reduces the badge clutter in the header).
function _rrDriverStatusMeta(s) {
  // Tints chosen to read on the dark, sidebar-colored record header.
  const map = {
    onboarding: { label: "Onboarding", color: "#60A5FA" },
    active:     { label: "Active",     color: "#4ADE80" },
    leave:      { label: "On leave",   color: "#FBBF24" },
    inactive:   { label: "Inactive",   color: "#94A3B8" },
    terminated: { label: "Terminated", color: "#F87171" },
  };
  return map[s] || { label: s ? String(s) : "—", color: "#94A3B8" };
}

// Roster turnover window — operator can switch via the small clock
// icon on the Turnover KPI tile. Persisted to localStorage so the
// choice carries across sessions.
const _RR_TURNOVER_TF_KEY = "rr.roster.turnover-tf";
let _rosterTurnoverDays = (() => {
  const v = parseInt(localStorage.getItem(_RR_TURNOVER_TF_KEY) || "30", 10);
  return [30, 90, 365].includes(v) ? v : 30;
})();
// Cached roster computation so the drilldown renderers don't redo
// the math.  Refreshed in refreshDriverStatRow().
let _rosterStats = null;

async function refreshDriverStatRow(rows) {
  // Active / onboarding / inactive counts.
  const counts = { active: 0, onboarding: 0, leave: 0, inactive: 0, terminated: 0 };
  for (const r of rows) counts[r.status] = (counts[r.status] || 0) + 1;
  // On-leave drivers got their own tab (PR for LOA visibility), so the
  // legacy Inactive bucket no longer rolls them in.
  const inactiveTotal = (counts.inactive || 0) + (counts.terminated || 0);

  const atRiskCount = rows.filter(r => r.status === "active" && (r.score ?? 999) < 70).length;

  const tabCounts = {
    active:     counts.active,
    onboarding: counts.onboarding,
    atrisk:     atRiskCount,
    onleave:    counts.leave,
    inactive:   inactiveTotal,
  };
  Object.entries(tabCounts).forEach(([stage, n]) => {
    const el = document.querySelector(`.dr-subview .stage-tab[data-stage="${stage}"] .stage-tab-count`);
    if (el) el.textContent = n;
  });

  const scored = rows.filter(r => r.score != null);
  const avgScore = scored.length === 0
    ? "—"
    : Math.round(scored.reduce((s, r) => s + Number(r.score), 0) / scored.length);

  // Avg tenure (months) across active + onboarding drivers with hire dates.
  const todayMs = Date.now();
  const active = rows.filter(r => r.status === "active" || r.status === "onboarding");
  const totalActive = active.length;
  const tenureMonths = active
    .filter(d => d.hire_date)
    .map(d => (todayMs - new Date(d.hire_date + "T12:00:00").getTime()) / (1000 * 60 * 60 * 24 * 30.4375))
    .sort((a, b) => a - b);
  const avgTenure = tenureMonths.length
    ? tenureMonths.reduce((s, n) => s + n, 0) / tenureMonths.length
    : null;
  const medianTenure = tenureMonths.length
    ? tenureMonths[Math.floor(tenureMonths.length / 2)]
    : 0;
  const longestMonths = tenureMonths.length ? tenureMonths[tenureMonths.length - 1] : 0;

  // % Tenured · share of the team (active + onboarding) who have been with
  // the company 30+ days. A driver with no hire date can't be counted as
  // tenured. Denominator is the full team so it reads as a workforce-
  // stability percentage (e.g. 9 of 10 → 90% tenured).
  const tenuredCount = active.filter(d =>
    d.hire_date &&
    (todayMs - new Date(d.hire_date + "T12:00:00").getTime()) / 86400000 >= 30
  ).length;
  const tenuredPct = totalActive > 0
    ? Math.round((tenuredCount / totalActive) * 100)
    : null;

  // # of active/onboarding drivers whose driver's license expires within
  // the next 30 days (already-expired included — most urgent). Matches the
  // Licenses tab's `days <= 30` rule.
  const dlExpiringList = active
    .filter(d => {
      if (!d.dl_expires_on) return false;
      const days = Math.floor((new Date(d.dl_expires_on + "T12:00:00").getTime() - todayMs) / 86400000);
      return days <= 30;
    })
    .map(d => ({
      id: d.id,
      name: rrTitleCaseName(displayDriverName(d) || d.full_name || "Driver"),
      station: d.station?.code || "—",
      dl_expires_on: d.dl_expires_on,
      days: Math.floor((new Date(d.dl_expires_on + "T12:00:00").getTime() - todayMs) / 86400000),
    }))
    .sort((a, b) => a.days - b.days);   // soonest / already-expired first
  const dlExpiringSoonCount = dlExpiringList.length;

  // % on attendance coaching · share of the team (active + onboarding)
  // with at least one active coaching on the attendance topic, at any
  // level (verbal → termination). Denominator matches % Tenured so the
  // "X of N" rollups read consistently across the KPI strip.
  const attnCoachedCount = active.filter(d => _rosterAttnCoached.has(d.id)).length;
  const attnCoachedPct = totalActive > 0
    ? Math.round((attnCoachedCount / totalActive) * 100)
    : null;

  // Turnover — terminations in the rolling window. The schema doesn't
  // track a terminated_at column; updated_at on a status='terminated'
  // row is the closest proxy.
  const winDays   = _rosterTurnoverDays;
  const winCutoff = new Date(todayMs - winDays * 86400000).toISOString();
  const priorCutoff = new Date(todayMs - winDays * 2 * 86400000).toISOString();
  const termsLastWin = rows.filter(r =>
    r.status === "terminated" && r.updated_at && r.updated_at >= winCutoff
  );
  const termsPriorWin = rows.filter(r => {
    if (r.status !== "terminated" || !r.updated_at) return false;
    return r.updated_at >= priorCutoff && r.updated_at < winCutoff;
  });
  const turnoverDenom = Math.max(1, totalActive + termsLastWin.length);
  const turnoverPct      = (termsLastWin.length  / turnoverDenom) * 100;
  const turnoverPriorPct = (termsPriorWin.length / turnoverDenom) * 100;
  const turnoverDelta    = turnoverPct - turnoverPriorPct;

  // Tenure buckets for the drilldown.
  const tenureBuckets = { "0-30": 0, "30-90": 0, "90-365": 0, "365-730": 0, "730plus": 0 };
  for (const d of active) {
    if (!d.hire_date) continue;
    const days = (todayMs - new Date(d.hire_date + "T12:00:00").getTime()) / 86400000;
    if      (days < 30)   tenureBuckets["0-30"]   += 1;
    else if (days < 90)   tenureBuckets["30-90"]  += 1;
    else if (days < 365)  tenureBuckets["90-365"] += 1;
    else if (days < 730)  tenureBuckets["365-730"]+= 1;
    else                  tenureBuckets["730plus"]+= 1;
  }

  // Score buckets for the Avg-score drilldown.
  const scoreBuckets = { "90+": 0, "80-89": 0, "70-79": 0, "50-69": 0, "lt50": 0 };
  for (const r of active) {
    const s = r.score;
    if (s == null || !Number.isFinite(Number(s))) continue;
    const v = Number(s);
    if      (v >= 90) scoreBuckets["90+"]   += 1;
    else if (v >= 80) scoreBuckets["80-89"] += 1;
    else if (v >= 70) scoreBuckets["70-79"] += 1;
    else if (v >= 50) scoreBuckets["50-69"] += 1;
    else              scoreBuckets["lt50"]  += 1;
  }
  // Top + bottom 5 by score, for the at-a-glance lists in the drilldown.
  const scoredActive = active.filter(d => d.score != null);
  const sortedByScore = scoredActive.slice().sort((a, b) => Number(b.score) - Number(a.score));
  const topFive = sortedByScore.slice(0, 5);
  const botFive = sortedByScore.slice(-5).reverse();

  // Stash everything the drilldowns need so they can render without
  // re-computing or re-fetching.
  _rosterStats = {
    totalActive, atRiskCount,
    avgScore, scoredCount: scored.length,
    scoreBuckets, topFive, botFive,
    tenureMonths, avgTenure, medianTenure, longestMonths,
    tenuredCount, tenuredPct,
    attnCoachedCount, attnCoachedPct,
    tenureBuckets,
    dlExpiring: dlExpiringList,
    winDays,
    termsLastWin, termsPriorWin,
    turnoverPct, turnoverPriorPct, turnoverDelta,
  };

  // Render the roster KPI pills (Active drivers · Drivers on LOA ·
  // Avg tenure) into whichever shared KPI strip is currently visible.
  // The Roster page lives in two places:
  //   1. /dashboard/#drivers  → #rr-roster-kpis on view-drivers
  //   2. The "Roster" cmd-tab on view-onboarding-ops → that page's
  //      #rr-ob-kpis strip, the only KPI bar visible on screen.
  // Both hosts get painted; the hidden one is invisible.
  const navy = "#1E293B";
  const amber = "#C7860B";
  const rosterPill = (key, color, label, sub, clickable, iconHtml) => {
    const cl = clickable ? ' data-clickable="true"' : "";
    // An iconHtml (a status icon) replaces the plain status dot — same
    // pattern the Schedule KPI strip uses.
    const marker = iconHtml
      ? `<span class="sched-kpi-icon">${iconHtml}</span>`
      : `<span class="sched-kpi-dot" style="background:${color}"></span>`;
    // Clickable KPIs open a pop-out drilldown report — flag them with a
    // divider line + down chevron (the Schedule split-button affordance).
    const chev = clickable
      ? `<span class="rr-kpi-chev" aria-hidden="true"><svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="2 4 6 8 10 4"/></svg></span>`
      : "";
    // Single-line pill — value only (subtext dropped per operator) so each
    // pill matches the compact Schedule pill size.
    return `<span class="sched-kpi-pill" data-rr-roster-kpi="${key}"${cl}>`
      + marker
      + `<span class="sched-kpi-text">`
      + `<span class="sched-kpi-val">${label}</span>`
      + `</span>`
      + chev
      + `</span>`;
  };
  const tenureLabel = avgTenure == null ? "— Avg tenure" : `${avgTenure.toFixed(1)} mo Avg tenure`;
  const tenureSub = avgTenure == null
    ? "Set hire dates to see tenure"
    : `Median ${medianTenure.toFixed(0)} mo · longest ${(longestMonths / 12).toFixed(1)} yr`;
  const tenuredLabel = tenuredPct == null ? "— > 30 days" : `${tenuredPct}% > 30 days`;
  const tenuredSub = tenuredPct == null
    ? "Set hire dates to see tenure"
    : `${tenuredCount} of ${totalActive} drivers`;
  // # of drivers' licenses expiring within 30 days (incl. expired).
  const dlExpColor = dlExpiringSoonCount > 0 ? amber : navy;
  const dlExpLabel = `${dlExpiringSoonCount} DL expiring`;
  const dlExpSub   = dlExpiringSoonCount > 0 ? "Within 30 days" : "None within 30 days";
  // % Tenured guardrail · ≥90% shows the Schedule "all good" (green
  // thumbs-up) icon, below 90% shows the red warning icon — the same
  // _rrKpiStatusIcon glyphs the Schedule KPI strip uses.
  const tenuredIcon = (tenuredPct == null || typeof _rrKpiStatusIcon !== "function")
    ? undefined
    : (tenuredPct >= 90
        ? _rrKpiStatusIcon("green", `${tenuredPct}% tenured — at or above the 90% target`)
        : _rrKpiStatusIcon("red", `${tenuredPct}% tenured — below the 90% target`));
  const attnLabel = attnCoachedPct == null
    ? "— On attendance coaching"
    : `${attnCoachedPct}% On attendance coaching`;
  const attnSub = attnCoachedPct == null
    ? "&nbsp;"
    : `${attnCoachedCount} of ${totalActive} · any level`;
  // On-attendance-coaching guardrail · ≤10% green, 11–19% yellow, >19%
  // red — same Schedule KPI status glyphs the % Tenured card uses.
  const attnTier = attnCoachedPct == null ? null
    : (attnCoachedPct <= 10 ? "green"
      : attnCoachedPct <= 19 ? "yellow"
      : "red");
  const attnIcon = (attnTier == null || typeof _rrKpiStatusIcon !== "function")
    ? undefined
    : _rrKpiStatusIcon(attnTier, `${attnCoachedPct}% on attendance coaching`);
  // % of the active team on a Final corrective action — "atrisk" in the
  // roster risk map is Final/Termination severity.
  const finalCaCount = active.filter(d => (_rosterRisk && _rosterRisk.get) ? _rosterRisk.get(d.id) === "atrisk" : false).length;
  const finalCaPct = totalActive > 0 ? Math.round(finalCaCount / totalActive * 100) : null;
  const finalCaLabel = finalCaPct == null ? "— Final corrective" : `${finalCaPct}% Final corrective`;
  const finalCaSub = finalCaPct == null ? "&nbsp;" : `${finalCaCount} of ${totalActive} on a final action`;
  const finalCaIcon = (finalCaPct == null || typeof _rrKpiStatusIcon !== "function")
    ? undefined
    : _rrKpiStatusIcon(finalCaCount > 0 ? "red" : "green", `${finalCaPct}% on a final corrective action`);

  // The "Active drivers" pill doubles as the roster status filter (operator
  // request): it shows the count for the current stage and opens the status
  // menu (All / Active / Seasonal / On leave / Inactive / Terminated). The
  // separate far-right toolbar filter is removed.
  const _rsStageLabel = _rrRosterStatusFilterLabel();
  let _rsStageCount;
  try { _rsStageCount = _rowsForStage(_rosterRows, _driverStage).length; }
  catch (_) { _rsStageCount = counts.active; }
  const _rsPlural = _rsStageCount === 1 ? "" : "s";
  const statusFilterLabel = _driverStage === "active"
    ? `${_rsStageCount} Active driver${_rsPlural}`
    : _driverStage === "all"
      ? `${_rsStageCount} driver${_rsPlural} · all`
      : `${_rsStageCount} ${_rsStageLabel}`;
  const activeFilterPill =
    `<button type="button" class="sched-kpi-pill sched-kpi-action rr-kpi-statusfilter" data-rr-roster-status-filter aria-haspopup="menu" aria-expanded="false" title="Filter the roster by status">`
    + `<span class="sched-kpi-text"><span class="sched-kpi-val">${statusFilterLabel}</span></span>`
    + `<span class="rr-kpi-chev" aria-hidden="true"><svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="2 4 6 8 10 4"/></svg></span>`
    + `</button>`;
  const rosterKpisHtml =
    activeFilterPill +
    // "Coach driver" toolbar pill removed (operator) — coaching now lives as a
    // per-row icon next to Separate (see _rowActionsFor / data-rr-row-coach).
    `<button type="button" class="sched-kpi-pill sched-kpi-action rr-kpi-attendance" data-rr-roster-attendance aria-haspopup="menu" aria-expanded="false" title="Attendance report &amp; policy"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><span class="sched-kpi-val">Attendance</span><span class="rr-kpi-chev" aria-hidden="true"><svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="2 4 6 8 10 4"/></svg></span></button>` +
    `<button type="button" class="sched-kpi-pill sched-kpi-action rr-kpi-metrics" data-rr-roster-metrics aria-haspopup="dialog" aria-expanded="false" title="Driver metrics · live roster overview" style="margin-left:auto"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg><span class="sched-kpi-val">Metrics</span></button>` +
    `<button type="button" class="sched-kpi-pill sched-kpi-action" data-rr-roster-add-driver aria-haspopup="menu" aria-expanded="false" title="Add a driver or bulk import"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg><span class="sched-kpi-val">Add driver</span><span class="rr-kpi-chev" aria-hidden="true"><svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="2 4 6 8 10 4"/></svg></span></button>`;
    // Metric pills (Final corrective / >30 days / DL expiring) removed per
    // operator — the top bar is now status filter + Add/Coach actions, with
    // the shared ⋯/bell/avatar chrome relocated into the roster toolbar.

  const rosterHost = document.getElementById("rr-roster-kpis");
  if (rosterHost) rosterHost.innerHTML = rosterKpisHtml;
  // Restore the Metrics drawer's persisted open state (and refresh its counts).
  if (typeof _rrSyncMetricsDrawer === "function") _rrSyncMetricsDrawer();

  // Onboarding page's roster mode · the visible KPI strip is
  // #rr-ob-kpis. Overwrite it with the roster pills while the
  // operator is in roster mode; _obCmdTab clears the strip on exit
  // (the Overview no longer paints its own pills).
  const obShell = document.getElementById("rr-ob-cmd");
  if (obShell && obShell.classList.contains("is-roster")) {
    const obHost = document.getElementById("rr-ob-kpis");
    if (obHost) obHost.innerHTML = rosterKpisHtml;
  }

  // Schedule's embedded roster/attendance sub-view · paint the roster
  // pills onto the REAL Schedule KPI board (#rr-sched-kpis) so the board
  // itself shows the roster KPIs. The board's own schedule pills are
  // cached on first overwrite (here or in schedSub) and restored on exit.
  if (typeof window._schedRosterKpiActive === "function" && window._schedRosterKpiActive()) {
    const schedHost = document.getElementById("rr-sched-kpis");
    if (schedHost) {
      if (window._schedKpiSavedHtml == null) window._schedKpiSavedHtml = schedHost.innerHTML;
      // Park the relocated chrome (bell/avatar) + the live search input out of
      // the strip BEFORE wiping it so neither is detached, then re-attach both
      // into the fresh strip: search pill on the left, chrome on the right.
      if (typeof _rrReturnChromeHome === "function") _rrReturnChromeHome();
      if (typeof _rrParkRosterSearch === "function") _rrParkRosterSearch();
      schedHost.innerHTML =
        `<span class="rr-kpi-search-host" id="rr-kpi-search-host"></span>`
        + rosterKpisHtml
        + `<span class="rr-roster-chrome-host" id="rr-roster-chrome-host"></span>`;
      if (typeof _rrMoveRosterSearchToStrip === "function") _rrMoveRosterSearchToStrip();
      if (typeof _rrMoveChromeToRoster === "function") _rrMoveChromeToRoster();
    }
  }

  // Re-render the open drilldown if one was active.
  if (_rosterKpiDetail) _renderRosterKpiDetail();
}

function setStatTile(tile, label, value, sub) {
  tile.querySelector(".stat-mini-label").textContent = label;
  const valEl = tile.querySelector(".stat-mini-value");
  valEl.textContent = value;
  valEl.style.color = "";
  const s = tile.querySelector(".stat-mini-sub");
  if (s) s.textContent = sub;
}

// ─── Roster KPI drill-down · Avg tenure + Turnover ─────────────────────
let _rosterKpiDetail = null;   // 'tenure' | 'turnover' | null

function _closeRosterKpiDetail() {
  _rosterKpiDetail = null;
  const panel = document.getElementById("rr-roster-kpi-detail");
  if (panel) { panel.style.display = "none"; panel.innerHTML = ""; panel.classList.remove("is-popout"); }
  document.querySelectorAll("[data-rr-roster-kpi]").forEach(el => el.classList.remove("active"));
  // Close any open time-frame popover too.
  document.querySelectorAll(".rr-tf-popover").forEach(el => el.remove());
}

function _renderRosterKpiDetail() {
  const panel = document.getElementById("rr-roster-kpi-detail");
  if (!panel) return;
  document.querySelectorAll("[data-rr-roster-kpi]").forEach(el => {
    el.classList.toggle("active", el.dataset.rrRosterKpi === _rosterKpiDetail);
  });
  if (!_rosterKpiDetail || !_rosterStats) {
    panel.style.display = "none"; panel.innerHTML = "";
    return;
  }
  panel.style.display = "block";
  // The DL-expiring drilldown renders as a floating pop-out card (see the
  // .is-popout styles); the others stay as full-width in-flow cards.
  panel.classList.toggle("is-popout", _rosterKpiDetail === "dlexp");

  const s = _rosterStats;

  if (_rosterKpiDetail === "dlexp") {
    // Drivers whose license expires within 30 days (already-expired
    // included), soonest first — name, station and expiry date, in a
    // floating card that emerges from near the KPI tile and overlays the
    // content (no layout shift, no backdrop/dim/blur). A close button sits
    // in the card header; clicking a row opens that driver's record inline.
    const list = s.dlExpiring || [];
    const fmtDate = (iso) => new Date(iso + "T12:00:00").toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
    const relTxt  = (days) => days < 0 ? `Expired ${-days}d ago` : days === 0 ? "Expires today" : `in ${days}d`;
    const rowsHtml = list.map(d => {
      const urgent    = d.days <= 14;                 // includes already-expired
      const barStyle  = urgent ? "box-shadow:inset 3px 0 0 var(--red);" : "";
      const dateColor = d.days < 0 ? "var(--red)" : urgent ? "var(--amber)" : "var(--text)";
      return `<div data-rr-open-driver data-driver-id="${d.id}" style="${barStyle}display:grid;grid-template-columns:1fr 70px 150px;gap:var(--s-3);align-items:center;padding:8px 10px;border-top:1px solid var(--border);font-size:var(--fs-sm);cursor:pointer">
        <div style="font-weight:600;color:var(--text)">${escapeHtml(d.name)}</div>
        <div class="u-muted">${escapeHtml(d.station)}</div>
        <div style="text-align:right;font-variant-numeric:tabular-nums"><span style="font-weight:600;color:${dateColor}">${fmtDate(d.dl_expires_on)}</span><div class="u-xs-subtle">${relTxt(d.days)}</div></div>
      </div>`;
    }).join("");
    panel.innerHTML = `<div class="rr-kpi-popcard card" style="padding:var(--s-4) var(--s-5)">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:var(--s-3);margin-bottom:var(--s-2)">
        <div style="min-width:0">
          <div style="font-size:var(--fs-md);font-weight:700;color:var(--text);letter-spacing:-.01em">Driver licenses expiring</div>
          <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${list.length} active driver${list.length === 1 ? "" : "s"} with a license expiring within 30 days. Soonest first — click a driver to open their record.</div>
        </div>
        <button class="cd-close" type="button" data-rr-roster-kpi-close aria-label="Close" style="flex:0 0 auto">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>
      <div style="max-height:340px;overflow-y:auto;margin:0 calc(var(--s-5) * -1) calc(var(--s-4) * -1);padding:0 var(--s-5) var(--s-4)">${list.length ? rowsHtml : '<div class="rr-empty-inline" style="padding:var(--s-3-5) 0">No licenses expiring within 30 days.</div>'}</div>
    </div>`;
    // Anchor the card horizontally under its KPI tile (the visible host —
    // the strip is mirrored into several hosts) so it appears to emerge
    // from the tile rather than from the content edge.
    const tile = [...document.querySelectorAll('[data-rr-roster-kpi="dlexp"]')].find(t => t.offsetParent !== null);
    const popcard = panel.querySelector(".rr-kpi-popcard");
    if (tile && popcard) {
      const tr = tile.getBoundingClientRect();
      const pr = panel.getBoundingClientRect();
      const maxLeft = Math.max(0, panel.clientWidth - popcard.offsetWidth);
      popcard.style.left = Math.max(0, Math.min(tr.left - pr.left, maxLeft)) + "px";
    }
    return;
  }

  if (_rosterKpiDetail === "score") {
    // Score-distribution buckets + top + bottom drivers.  Score is a
    // 0–100 composite on drivers.score; we tier into 90+ / 80–89 /
    // 70–79 / 50–69 / <50 with brand-blue → red so the at-risk tail
    // is obvious.
    const order  = ["90+", "80-89", "70-79", "50-69", "lt50"];
    const labels = {
      "90+":   "90 – 100  · Top tier",
      "80-89": "80 – 89   · Strong",
      "70-79": "70 – 79   · Standard",
      "50-69": "50 – 69   · At risk",
      "lt50":  "Below 50  · Critical",
    };
    const colors = {
      "90+":   "var(--green)",
      "80-89": "var(--accent)",
      "70-79": "var(--text-muted)",
      "50-69": "var(--amber)",
      "lt50":  "var(--red)",
    };
    const buckets = s.scoreBuckets;
    const total = order.reduce((sum, k) => sum + (buckets[k] || 0), 0);
    const max   = Math.max(1, ...order.map(k => buckets[k] || 0));
    const bars  = order.map(k => {
      const n   = buckets[k] || 0;
      const pct = total ? Math.round((n / total) * 100) : 0;
      const w   = (n / max) * 100;
      return `<div style="display:grid;grid-template-columns:200px 1fr 90px;gap:var(--s-3-5);align-items:center;padding:var(--s-2) 0">
        <div style="font-size:var(--fs-sm);font-weight:600;color:var(--text);font-variant-numeric:tabular-nums">${labels[k]}</div>
        <div style="background:var(--canvas);border-radius:var(--r-md);height:14px;overflow:hidden;border:1px solid var(--border)">
          <div style="background:${colors[k]};height:100%;width:${w.toFixed(1)}%;transition:width var(--t-spring)"></div>
        </div>
        <div style="font-size:var(--fs-sm);color:var(--text-muted);text-align:right"><strong style="color:var(--text)">${n}</strong> · ${pct}%</div>
      </div>`;
    }).join("");

    const driverRow = (r, color) => {
      const name = rrTitleCaseName(displayDriverName(r) || r.full_name || "Driver");
      const station = r.station?.code || "—";
      return `<div style="display:grid;grid-template-columns:1fr 80px 60px;gap:var(--s-3);align-items:center;padding:6px 0;border-top:1px solid var(--border);font-size:var(--fs-sm)">
        <div style="font-weight:600;color:var(--text)">${escapeHtml(name)}</div>
        <div class="u-muted">${escapeHtml(station)}</div>
        <div style="text-align:right;font-weight:700;color:${color};font-variant-numeric:tabular-nums">${Number(r.score).toFixed(0)}</div>
      </div>`;
    };
    const topList = s.topFive.length === 0
      ? `<div class="rr-empty-inline" style="padding:var(--s-3-5) 0">No scored drivers yet.</div>`
      : s.topFive.map(r => driverRow(r, "var(--green)")).join("");
    const botList = s.botFive.length === 0
      ? `<div class="rr-empty-inline" style="padding:var(--s-3-5) 0">No scored drivers yet.</div>`
      : s.botFive.map(r => driverRow(r, Number(r.score) < 70 ? "var(--red)" : "var(--text)")).join("");

    panel.innerHTML = `<div class="card" style="padding:var(--s-5)">
      <div class="u-mb-4">
        <div style="font-size:var(--fs-lg);font-weight:700;color:var(--text);letter-spacing:-.01em">Avg score · distribution</div>
        <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">Fleet average is ${s.avgScore} across ${s.scoredCount} scored driver${s.scoredCount === 1 ? "" : "s"}. Bars show how the team splits across performance tiers.</div>
      </div>
      ${bars}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:var(--s-4);margin-top:var(--s-4);padding-top:var(--s-3);border-top:1px solid var(--border)">
        <div>
          <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:var(--s-2)">Top 5</div>
          ${topList}
        </div>
        <div>
          <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:var(--s-2)">Bottom 5</div>
          ${botList}
        </div>
      </div>
    </div>`;
    return;
  }

  if (_rosterKpiDetail === "tenure") {
    // Tenure-distribution bar chart — same buckets the old Insights
    // page used so operators see the histogram they're used to.
    const order = ["0-30", "30-90", "90-365", "365-730", "730plus"];
    const labels = {
      "0-30":    "First 30 days",
      "30-90":   "30 – 90 days",
      "90-365":  "90 days – 1 year",
      "365-730": "1 – 2 years",
      "730plus": "2+ years",
    };
    const max = Math.max(1, ...order.map(k => s.tenureBuckets[k] || 0));
    const total = order.reduce((sum, k) => sum + (s.tenureBuckets[k] || 0), 0);
    const rows = order.map(k => {
      const n = s.tenureBuckets[k] || 0;
      const pct = total ? Math.round((n / total) * 100) : 0;
      const w = (n / max) * 100;
      return `<div style="display:grid;grid-template-columns:160px 1fr 90px;gap:var(--s-3-5);align-items:center;padding:var(--s-2) 0">
        <div style="font-size:var(--fs-sm);font-weight:600;color:var(--text)">${labels[k]}</div>
        <div style="background:var(--canvas);border-radius:var(--r-md);height:14px;overflow:hidden;border:1px solid var(--border)">
          <div style="background:var(--accent);height:100%;width:${w.toFixed(1)}%;transition:width var(--t-spring)"></div>
        </div>
        <div style="font-size:var(--fs-sm);color:var(--text-muted);text-align:right"><strong style="color:var(--text)">${n}</strong> · ${pct}%</div>
      </div>`;
    }).join("");
    panel.innerHTML = `<div class="card" style="padding:var(--s-5)">
      <div class="u-mb-3">
        <div style="font-size:var(--fs-lg);font-weight:700;color:var(--text);letter-spacing:-.01em">Tenure distribution</div>
        <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">Active + onboarding drivers grouped by how long they've been on the team. Avg ${s.avgTenure == null ? "—" : s.avgTenure.toFixed(1) + " mo"} · median ${s.medianTenure.toFixed(0)} mo.</div>
      </div>
      ${rows}
    </div>`;
    return;
  }

  if (_rosterKpiDetail === "turnover") {
    // Turnover-source breakdown.  We surface the actual termination
    // events in the window plus a quick station + tenure-at-departure
    // breakdown so the operator can see *where* the bulk is coming from.
    const winLabel = s.winDays === 365 ? "the last year" : `the last ${s.winDays} days`;
    const terms = s.termsLastWin || [];

    // Tenure-at-termination buckets — answers "are we losing rookies
    // or veterans?". Uses hire_date → updated_at gap.
    const buckets = { "0-30": 0, "30-90": 0, "90-365": 0, "365plus": 0, "no_hire": 0 };
    const stationCounts = new Map();
    for (const t of terms) {
      const stationCode = t.station?.code || "—";
      stationCounts.set(stationCode, (stationCounts.get(stationCode) || 0) + 1);
      if (!t.hire_date) { buckets["no_hire"]++; continue; }
      const daysAtTerm = (new Date(t.updated_at).getTime() - new Date(t.hire_date + "T12:00:00").getTime()) / 86400000;
      if      (daysAtTerm < 30)  buckets["0-30"]++;
      else if (daysAtTerm < 90)  buckets["30-90"]++;
      else if (daysAtTerm < 365) buckets["90-365"]++;
      else                       buckets["365plus"]++;
    }

    // Recent terminations list (most-recent first, capped at 8).
    const recent = terms
      .slice()
      .sort((a, b) => (b.updated_at || "").localeCompare(a.updated_at || ""))
      .slice(0, 8);
    const recentRows = recent.length === 0
      ? `<div class="rr-empty-inline" style="padding:var(--s-6) 0">No terminations in ${winLabel} — that's the best read on retention.</div>`
      : recent.map(t => {
          const tenureAtTerm = t.hire_date
            ? Math.floor((new Date(t.updated_at).getTime() - new Date(t.hire_date + "T12:00:00").getTime()) / 86400000)
            : null;
          const ago = Math.floor((Date.now() - new Date(t.updated_at).getTime()) / 86400000);
          const display = rrTitleCaseName(displayDriverName(t) || t.full_name || "Driver");
          return `<div style="display:grid;grid-template-columns:1fr 100px 110px 80px;gap:var(--s-3-5);align-items:center;padding:var(--s-2) 0;border-top:1px solid var(--border);font-size:var(--fs-sm)">
            <div style="font-weight:600;color:var(--text)">${escapeHtml(display)}</div>
            <div class="u-muted">${escapeHtml(t.station?.code || "—")}</div>
            <div class="u-muted">${tenureAtTerm == null ? "—" : tenureAtTerm + "d at term"}</div>
            <div style="color:var(--text-subtle);text-align:right">${ago}d ago</div>
          </div>`;
        }).join("");

    // Tenure-at-termination bars.
    const bktOrder = ["0-30", "30-90", "90-365", "365plus", "no_hire"];
    const bktLabel = {
      "0-30":    "Lost in first 30 days",
      "30-90":   "Lost 30 – 90 days in",
      "90-365":  "Lost 90 days – 1 year in",
      "365plus": "Lost after 1+ year",
      "no_hire": "No hire date on file",
    };
    const bktTotal = bktOrder.reduce((sum, k) => sum + buckets[k], 0);
    const bktMax   = Math.max(1, ...bktOrder.map(k => buckets[k]));
    const bktBars = bktOrder.map(k => {
      const n = buckets[k];
      if (n === 0 && k === "no_hire") return "";
      const pct = bktTotal ? Math.round((n / bktTotal) * 100) : 0;
      const w   = (n / bktMax) * 100;
      const isRookie = k === "0-30" || k === "30-90";
      return `<div style="display:grid;grid-template-columns:200px 1fr 80px;gap:var(--s-3-5);align-items:center;padding:6px 0">
        <div style="font-size:var(--fs-sm);font-weight:600;color:var(--text)">${bktLabel[k]}</div>
        <div style="background:var(--canvas);border-radius:var(--r-md);height:12px;overflow:hidden;border:1px solid var(--border)">
          <div style="background:${isRookie ? "var(--red)" : "var(--accent)"};height:100%;width:${w.toFixed(1)}%;transition:width var(--t-spring)"></div>
        </div>
        <div style="font-size:var(--fs-sm);color:var(--text-muted);text-align:right"><strong style="color:var(--text)">${n}</strong> · ${pct}%</div>
      </div>`;
    }).join("");

    // Station breakdown.
    const stationRows = [...stationCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .map(([code, n]) => {
        const pct = bktTotal ? Math.round((n / bktTotal) * 100) : 0;
        return `<div style="display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--border);font-size:var(--fs-sm)">
          <span style="font-weight:600">${escapeHtml(code)}</span>
          <span class="u-muted"><strong style="color:var(--text)">${n}</strong> · ${pct}%</span>
        </div>`;
      }).join("");

    panel.innerHTML = `<div class="card" style="padding:var(--s-5)">
      <div class="u-mb-4">
        <div style="font-size:var(--fs-lg);font-weight:700;color:var(--text);letter-spacing:-.01em">Where the turnover is coming from</div>
        <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:2px">${terms.length} termination${terms.length === 1 ? "" : "s"} across ${winLabel}. Use the clock icon on the KPI tile to switch the window.</div>
      </div>

      ${terms.length > 0 ? `
      <div style="display:grid;grid-template-columns:2fr 1fr;gap:var(--s-4)">
        <div>
          <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:var(--s-2)">Tenure at termination</div>
          ${bktBars}
          <div style="font-size:var(--fs-xs);color:var(--text-subtle);margin-top:var(--s-2);line-height:1.5">Red bars = early-tenure attrition. Concentrated red usually points to onboarding / fit issues; concentrated blue points to long-tenure burnout or coaching gaps.</div>
        </div>
        <div>
          <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:var(--s-2)">By station</div>
          ${stationRows}
        </div>
      </div>

      <div style="margin-top:var(--s-4);padding-top:var(--s-3);border-top:1px solid var(--border)">
        <div style="font-size:var(--fs-xs);font-weight:700;color:var(--text-muted);letter-spacing:.04em;text-transform:uppercase;margin-bottom:var(--s-2)">Recent terminations</div>
        ${recentRows}
      </div>` : recentRows}
    </div>`;
    return;
  }
}

// Click handler for the Roster KPI tiles.
document.addEventListener("click", (e) => {
  // Time-frame icon — open / close the popover.
  const tfBtn = e.target.closest("[data-rr-roster-tf-toggle]");
  if (tfBtn) {
    e.stopPropagation();
    e.preventDefault();
    const tile = tfBtn.closest(".stat-mini");
    if (!tile) return;
    const existing = tile.querySelector(".rr-tf-popover");
    if (existing) { existing.remove(); return; }
    // Close any other open popovers.
    document.querySelectorAll(".rr-tf-popover").forEach(el => el.remove());
    const opts = [{ d: 30, l: "30 days" }, { d: 90, l: "90 days" }, { d: 365, l: "1 year" }];
    const pop = document.createElement("div");
    pop.className = "rr-tf-popover";
    pop.innerHTML = opts.map(o =>
      `<button data-rr-roster-tf="${o.d}" class="${o.d === _rosterTurnoverDays ? "active" : ""}">${o.l}</button>`
    ).join("");
    tile.appendChild(pop);
    return;
  }
  // Time-frame option click.
  const tfOpt = e.target.closest("[data-rr-roster-tf]");
  if (tfOpt) {
    _rosterTurnoverDays = parseInt(tfOpt.dataset.rrRosterTf, 10) || 30;
    try { localStorage.setItem(_RR_TURNOVER_TF_KEY, String(_rosterTurnoverDays)); } catch {}
    document.querySelectorAll(".rr-tf-popover").forEach(el => el.remove());
    if (typeof refreshDriverStatRow === "function" && Array.isArray(_rosterRows)) {
      refreshDriverStatRow(_rosterRows);
    }
    return;
  }
  // Close button inside the DL pop-out card.
  if (e.target.closest("[data-rr-roster-kpi-close]")) { _closeRosterKpiDetail(); return; }
  // Click outside any popover closes them.
  if (!e.target.closest(".rr-tf-icon, .rr-tf-popover")) {
    document.querySelectorAll(".rr-tf-popover").forEach(el => el.remove());
  }
  // The DL drilldown is a floating pop-out — dismiss it on any click that
  // lands outside the card and isn't on a KPI tile (a tile click is handled
  // by the toggle below). A click on a driver row inside the card is inside
  // the card, so it opens the record without closing first.
  if (_rosterKpiDetail === "dlexp"
      && !e.target.closest(".rr-kpi-popcard")
      && !e.target.closest("[data-rr-roster-kpi]")) {
    _closeRosterKpiDetail();
  }
  // KPI tile click → open / toggle drilldown. The pop-out opens ONLY from
  // the chevron side of the pill (the split-button affordance), not the
  // whole pill body. Non-clickable pills have no chevron, so they never
  // open a drilldown.
  const card = e.target.closest("[data-rr-roster-kpi]");
  if (!card) return;
  if (!e.target.closest(".rr-kpi-chev")) return;
  const kpi = card.dataset.rrRosterKpi;
  _rosterKpiDetail = (_rosterKpiDetail === kpi) ? null : kpi;
  _renderRosterKpiDetail();
});
document.addEventListener("keydown", (e) => {
  // Escape closes the floating DL pop-out.
  if (e.key === "Escape" && _rosterKpiDetail === "dlexp") { _closeRosterKpiDetail(); return; }
  if (e.key !== "Enter" && e.key !== " ") return;
  const card = e.target.closest("[data-rr-roster-kpi]");
  if (!card) return;
  e.preventDefault();
  card.click();
});

function tenureLabel(hireDate) {
  const d = new Date(hireDate);
  if (isNaN(d)) return "—";
  const months = Math.max(0, Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60 * 24 * 30)));
  if (months < 1) {
    const days = Math.max(0, Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60 * 24)));
    return `${days}d`;
  }
  return `${months} mo`;
}

// Show the driver's preferred first name (when set) followed by last_name.
// Falls back to first_name → full_name. Used everywhere drivers are listed.
function displayDriverName(d) {
  const pref = (d?.preferred_name || "").trim();
  const first = pref || (d?.first_name || "").trim();
  const last  = (d?.last_name || "").trim();
  if (first && last) return `${first} ${last}`;
  return (first || last || (d?.full_name || "")).trim();
}
function displayDriverInitials(d) {
  const pref = (d?.preferred_name || "").trim();
  const first = pref || (d?.first_name || "").trim();
  const last  = (d?.last_name || "").trim();
  if (first || last) {
    const a = first[0] || "";
    const b = last[0]  || "";
    return (a + b).toUpperCase() || "?";
  }
  return (d?.full_name || "").split(/\s+/).map(p => p[0]).filter(Boolean).slice(0, 2).join("").toUpperCase() || "?";
}

// ─── Add applicant ─────────────────────────────────────────────────────────
//
// We bind via event delegation on a data-attribute, not by overriding the
// mockup's window.submitAddApplicant(). Module top-level await means the
// global override happens later than DOM-paint, and inline onclick handlers
// would fire the mockup stub if the user clicked early.

async function doAddApplicant() {
  const fn    = document.getElementById("aa-fn").value.trim();
  const ln    = document.getElementById("aa-ln").value.trim();
  const phone = document.getElementById("aa-phone").value.trim();
  const email = document.getElementById("aa-email").value.trim();
  const source = (document.querySelector("#modal-add-applicant .cd-pill.active")?.textContent || "Indeed").toLowerCase();

  if (!fn && !ln) { toast("Add a name first", "warn"); return; }
  if (!phone && !email) { toast("Phone or email required", "warn"); return; }

  const payload = {
    dsp_short_code: window.RR.dsp.short_code,
    first_name: fn || null,
    last_name:  ln || null,
    full_name:  `${fn} ${ln}`.trim(),
    phone:      phone ? toE164(phone) : null,
    email:      email || null,
    source,
    force_new:  true,
  };

  const { data: applicant, error } = await sb.rpc("intake_applicant", { p_payload: payload });
  if (error) { toast("Add failed: " + error.message, "warn"); return; }

  if ((applicant.phone || applicant.email) && applicant.status === "applied") {
    await sb.rpc("send_screening_link", { p_id: applicant.id });
  }

  closeModal("modal-add-applicant");
  await loadPipeline("all");
  toast(`${rrTitleCaseName(applicant.full_name)} added · screening invite queued`, "success");
}

// ─── Add driver ────────────────────────────────────────────────────────────
//
// Mockup's submitAddDriver() and modal-add-driver were a simple form. We
// route the Drivers-page "Add driver" button to the same rich driver-record
// drawer used for editing — but in CREATE mode (no driverId). On save we
// insert directly into public.drivers (the update_driver_record RPC doesn't
// accept station_id today, so create mode bypasses it).

const _originalOpenModal = window.openModal;
window.openModal = function (id) {
  if (id === "modal-add-driver") { openDriverDrawer(null); return; }
  if (typeof _originalOpenModal === "function") _originalOpenModal(id);
  if (id === "modal-broadcast") { _initBroadcastModal(); }
};

// Roster top-strip "Add driver" pill — opens a small dropdown with two
// choices: add one driver (rich driver-record drawer, create mode) or bulk
// import from a spreadsheet. Same fixed-popover mechanism + .rr-status-picker
// chrome as the neighboring status-filter / attendance pills. Delegated from
// document so it survives the KPI strip being re-rendered on every roster
// refresh.
function _rrCloseRosterAddMenu() {
  const pop = document.getElementById("rr-roster-add-menu-pop");
  if (!pop || pop.hidden) return;
  pop.hidden = true;
  pop.innerHTML = "";
  const t = document.querySelector('[data-rr-roster-add-driver][aria-expanded="true"]');
  if (t) t.setAttribute("aria-expanded", "false");
}
function _rrOpenRosterAddMenu(trigger) {
  if (!trigger) return;
  let pop = document.getElementById("rr-roster-add-menu-pop");
  if (!pop) {
    pop = document.createElement("div");
    pop.id = "rr-roster-add-menu-pop";
    pop.className = "rr-status-picker";
    pop.setAttribute("role", "menu");
    pop.hidden = true;
    document.body.appendChild(pop);
  }
  const item = (action, label, sub, svg) =>
    `<button type="button" role="menuitem" class="rr-status-picker-item" data-rr-add-menu-pick="${action}" style="align-items:flex-start;gap:10px">`
    + `<span style="display:flex;color:var(--text-muted);margin-top:1px">${svg}</span>`
    + `<span style="display:flex;flex-direction:column;text-align:left"><span class="rr-status-picker-label">${label}</span>`
    + `<span style="font-size:var(--fs-xs);color:var(--text-subtle);font-weight:400">${sub}</span></span>`
    + `</button>`;
  pop.innerHTML =
    item("single", "Add a driver", "Create one driver record",
      `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg>`)
    + item("bulk", "Bulk import", "Upload Excel/CSV or link a Google Sheet",
      `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>`);
  const r = trigger.getBoundingClientRect();
  pop.style.position = "fixed";
  pop.style.top = `${r.bottom + 6}px`;
  pop.style.minWidth = `${Math.max(220, r.width)}px`;
  pop.hidden = false;
  // Right-align to the trigger so a wide menu doesn't run off-screen.
  const w = pop.offsetWidth || 220;
  pop.style.left = `${Math.max(8, Math.min(r.right - w, window.innerWidth - w - 8))}px`;
  trigger.setAttribute("aria-expanded", "true");
}
document.addEventListener("click", (e) => {
  const trigger = e.target.closest && e.target.closest("[data-rr-roster-add-driver]");
  if (trigger) {
    e.preventDefault();
    e.stopPropagation();
    const isOpen = trigger.getAttribute("aria-expanded") === "true";
    _rrCloseRosterAddMenu();
    if (!isOpen) _rrOpenRosterAddMenu(trigger);
    return;
  }
  const pick = e.target.closest && e.target.closest("[data-rr-add-menu-pick]");
  if (pick) {
    e.preventDefault();
    e.stopPropagation();
    const action = pick.getAttribute("data-rr-add-menu-pick");
    _rrCloseRosterAddMenu();
    if (action === "bulk") openModal("modal-bulk-driver-ingest");
    else openModal("modal-add-driver");
    return;
  }
  const pop = document.getElementById("rr-roster-add-menu-pop");
  if (pop && !pop.hidden && !e.target.closest("#rr-roster-add-menu-pop")) _rrCloseRosterAddMenu();
});
document.addEventListener("keydown", (e) => { if (e.key === "Escape") _rrCloseRosterAddMenu(); });
window.addEventListener("scroll", _rrCloseRosterAddMenu, true);
window.addEventListener("resize", _rrCloseRosterAddMenu);

// ─── Broadcast (one-message-to-many) ──────────────────────────────
// The modal markup is fully styled but every audience pill, count, and
// the Send button were hardcoded mockup behavior.  This swaps the
// audience pills with live station counts, tracks the operator's
// selection, and rewires the Send button to actually fan a single
// message out to every targeted driver via dispatch_chat_send (which
// already handles SMS + push fan-out through the existing chat infra).
let _broadcastDrivers = []; // [{id, station_id, station_code}]
let _broadcastAudience = "all"; // "all" | "scheduled-today" | "station:<id>"
let _broadcastScheduledTodayIds = new Set();  // driver_ids with a non-absent shift today

async function _initBroadcastModal() {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;

  const { data, error } = await sb.from("drivers")
    .select("id, status, station_id, station:station_id (code)")
    .eq("dsp_id", dspId)
    .in("status", ["active", "onboarding"]);
  if (error) { toast("Couldn't load drivers: " + error.message, "warn"); return; }

  _broadcastDrivers = (data || []).map(d => ({
    id:           d.id,
    station_id:   d.station_id || null,
    station_code: d.station?.code || null,
  }));
  _broadcastAudience = "all";

  // "Scheduled today (excluding absences)" — shifts on today's date whose
  // status indicates the driver is actually going to run.  Excludes
  // called_off, no_show, vto (all of which mean absent).
  const today = new Date().toLocaleDateString("en-CA"); // yyyy-mm-dd in local tz
  const { data: shiftsToday, error: shiftsErr } = await sb.from("shifts")
    .select("driver_id")
    .eq("dsp_id", dspId)
    .eq("date", today)
    .in("status", ["scheduled", "late", "completed"]);
  if (shiftsErr) console.warn("broadcast · couldn't load today's shifts:", shiftsErr);
  _broadcastScheduledTodayIds = new Set((shiftsToday || []).map(s => s.driver_id).filter(Boolean));

  // Group drivers by station for per-station pill counts.
  const byStation = new Map();
  for (const d of _broadcastDrivers) {
    if (!d.station_id) continue;
    if (!byStation.has(d.station_id)) {
      byStation.set(d.station_id, { id: d.station_id, code: d.station_code, count: 0 });
    }
    byStation.get(d.station_id).count++;
  }
  const stations = Array.from(byStation.values()).sort((a, b) => (a.code || "").localeCompare(b.code || ""));

  const scheduledCount = _broadcastDrivers.filter(d => _broadcastScheduledTodayIds.has(d.id)).length;

  // Replace the static audience pill row + count line with live data.
  const modal = document.getElementById("modal-broadcast");
  if (!modal) return;
  const pillRow = modal.querySelector(".aud-pill-row");
  if (pillRow) {
    pillRow.innerHTML =
      `<button class="aud-pill active" data-rr-bcast-aud="all">All drivers (${_broadcastDrivers.length})</button>` +
      `<button class="aud-pill" data-rr-bcast-aud="scheduled-today" title="Drivers on today's schedule who haven't called off / no-showed">Scheduled today (${scheduledCount})</button>` +
      stations.map(s => `<button class="aud-pill" data-rr-bcast-aud="station:${escapeHtml(s.id)}">${escapeHtml(s.code || "—")} (${s.count})</button>`).join("");
    pillRow.querySelectorAll("[data-rr-bcast-aud]").forEach(btn => {
      btn.addEventListener("click", () => {
        pillRow.querySelectorAll(".aud-pill").forEach(p => p.classList.remove("active"));
        btn.classList.add("active");
        _broadcastAudience = btn.dataset.rrBcastAud;
        _updateBroadcastCount();
      });
    });
  }

  _updateBroadcastCount();

  // Replace the Send button's mockup onclick with the real sender.
  const sendBtn = modal.querySelector(".modal-foot .btn-primary");
  if (sendBtn) {
    sendBtn.onclick = _sendBroadcast;
  }
}

function _broadcastSelectedDrivers() {
  if (_broadcastAudience === "all") return _broadcastDrivers;
  if (_broadcastAudience === "scheduled-today") {
    return _broadcastDrivers.filter(d => _broadcastScheduledTodayIds.has(d.id));
  }
  if (_broadcastAudience.startsWith("station:")) {
    const sid = _broadcastAudience.slice("station:".length);
    return _broadcastDrivers.filter(d => d.station_id === sid);
  }
  return [];
}

function _updateBroadcastCount() {
  const modal = document.getElementById("modal-broadcast");
  const countEl = modal?.querySelector(".aud-count strong");
  if (!countEl) return;
  const n = _broadcastSelectedDrivers().length;
  countEl.textContent = `${n} driver${n === 1 ? "" : "s"}`;
  // The "X currently online" count was a mockup figure; drop it now
  // that the rest of the line is live.
  const parent = modal.querySelector(".aud-count");
  if (parent) {
    const trailing = parent.lastChild;
    if (trailing && trailing.nodeType === Node.TEXT_NODE && trailing.textContent.includes("online")) {
      trailing.textContent = " · sent via in-app + SMS";
    }
  }
}

async function _sendBroadcast() {
  const modal = document.getElementById("modal-broadcast");
  if (!modal) return;
  const ta = document.getElementById("bcast-msg");
  const body = (ta?.value || "").trim();
  if (!body) { toast("Type a message first", "warn"); return; }

  const targets = _broadcastSelectedDrivers();
  if (targets.length === 0) { toast("No drivers in the selected audience", "warn"); return; }
  if (!confirm(`Send this broadcast to ${targets.length} driver${targets.length === 1 ? "" : "s"}?`)) return;

  const sendBtn = modal.querySelector(".modal-foot .btn-primary");
  if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = "Sending…"; }

  let sent = 0, failed = 0;
  for (const d of targets) {
    const { error } = await sb.rpc("dispatch_chat_send", { p_driver_id: d.id, p_body: body });
    if (error) failed++; else sent++;
  }

  if (sendBtn) { sendBtn.disabled = false; sendBtn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg> Send broadcast`; }
  if (typeof closeModal === "function") closeModal("modal-broadcast");
  if (ta) ta.value = "";
  if (failed === 0) toast(`Broadcast sent to ${sent} driver${sent === 1 ? "" : "s"}`, "success");
  else              toast(`Broadcast sent to ${sent} of ${targets.length} drivers · ${failed} failed`, "warn");
}

let _driverStationsCache = null;
async function getDriverStationsCached() {
  if (_driverStationsCache) return _driverStationsCache;
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return [];
  const { data, error } = await sb.from("stations")
    .select("id, code, name, active")
    .eq("dsp_id", dspId)
    .eq("active", true)
    .order("code");
  if (error) { console.warn("stations load:", error.message); return []; }
  _driverStationsCache = data || [];
  return _driverStationsCache;
}

// The driver's display name as painted in the schedule grid row label
// (first text node only, so the "TRAINER" badge doesn't leak in). Used to
// personalize the assign-station prompt; falls back to a generic label.
function _gridDriverName(driverId) {
  try {
    const el = document.querySelector(`.cal-row-label-name[data-rr-driver-id="${driverId}"]`);
    const nm = el && el.childNodes[0] ? String(el.childNodes[0].nodeValue || "").trim() : "";
    return nm || "This driver";
  } catch (_) { return "This driver"; }
}

// Persist the driver's home station, refresh the grid, then resume the
// action that was blocked (opening the add-shift editor for the cell the
// operator clicked). Shared by the single- and multi-station prompts.
async function _assignDriverStationAndResume(driverId, stationId, ctx) {
  const { error } = await sb.from("drivers").update({ station_id: stationId }).eq("id", driverId);
  if (error) { toast("Couldn't assign station: " + error.message, "warn"); return; }
  toast("Station assigned", "success");
  // Re-render so the cell picks up its new station, then reopen the add flow
  // pre-filled — the operator lands right back where they were headed.
  try { if (typeof renderScheduleWeek === "function") await renderScheduleWeek(); } catch (_) {}
  if (ctx && ctx.date) {
    openShiftEditModal({
      date: ctx.date, stationId, driverId,
      anchorX: ctx.anchorX, anchorY: ctx.anchorY,
    });
  }
}

// Blocking exception → one-click fix. A driver with no home station can't be
// scheduled; instead of pointing the operator at another page, recommend the
// fix inline: "Add {name} to station {CODE}?" [Add] [Not now]. With one
// station we name it directly; with several we offer a picker; with none we
// fall back to a plain warning (nothing to assign).
async function _offerAssignStationForScheduling(driverId, ctx) {
  if (!driverId) { toast("Driver has no station — assign one in the Drivers page", "warn"); return; }
  const stations = await getDriverStationsCached();
  const name = _gridDriverName(driverId);
  if (!stations || stations.length === 0) {
    toast("Driver has no station and none are set up yet — add a station in Settings first.", "warn");
    return;
  }
  if (stations.length === 1) {
    const st = stations[0];
    toastAction(`${name} has no station. Add them to station ${st.code}?`, {
      kind: "warn",
      confirmLabel: `Add to ${st.code}`,
      dismissLabel: "Not now",
      onConfirm: () => _assignDriverStationAndResume(driverId, st.id, ctx),
    });
    return;
  }
  // Multiple stations — let the operator pick which one before assigning.
  const selId = `rr-toast-station-pick-${Math.max(0, stations.length)}-${driverId.slice(0, 8)}`;
  const options = stations
    .map(s => `<option value="${escapeHtml(s.id)}">${escapeHtml(s.code)}${s.name ? " · " + escapeHtml(s.name) : ""}</option>`)
    .join("");
  toastAction("", {
    kind: "warn",
    html: `<div style="margin-bottom:8px">${escapeHtml(name)} has no station. Add them to:</div>`
        + `<select id="${selId}" class="toast-action-select" style="width:100%;padding:5px 8px;border-radius:6px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.08);color:inherit;font:inherit">`
        + `<option value="">Choose a station…</option>${options}</select>`,
    confirmLabel: "Add",
    dismissLabel: "Not now",
    onConfirm: (el) => {
      const sel = el && el.querySelector(`#${selId}`);
      const stationId = sel && sel.value;
      if (!stationId) {
        if (sel) sel.style.borderColor = "var(--amber, #f59e0b)";
        return true; // keep the toast open until they pick a station
      }
      _assignDriverStationAndResume(driverId, stationId, ctx);
    },
  });
}

// ─── Bulk ingest (paste from Indeed CSV/TSV) ───────────────────────────────
//
// Accepts tab-OR comma-delimited paste with a header row. Maps any of
// these header labels to our fields:
//   name     ← "name", "applicant name", "full name", "candidate name"
//   first    ← "first name", "first", "given name"
//   last     ← "last name", "last", "surname", "family name"
//   email    ← "email", "email address", "e-mail"
//   phone    ← "phone", "phone number", "mobile", "cell"
//
// At minimum we need (name OR first+last) and (phone OR email). Rows
// missing both are skipped with a counter shown in the result toast.

function parseBulkText(text) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (lines.length < 2) return { rows: [], skipped: 0, headers: [] };

  // Detect delimiter: tab if any tab in header, else comma.
  const delim = lines[0].includes("\t") ? "\t" : ",";
  const headers = splitCsv(lines[0], delim).map(h => h.toLowerCase().trim());

  const idx = (...names) => headers.findIndex(h => names.some(n => h === n || h.includes(n)));
  const iName  = idx("applicant name", "candidate name", "full name", "name");
  const iFirst = idx("first name", "first", "given");
  const iLast  = idx("last name", "last", "surname", "family");
  const iEmail = idx("email address", "e-mail", "email");
  const iPhone = idx("phone number", "phone", "mobile", "cell");

  const rows = [];
  let skipped = 0;
  for (let i = 1; i < lines.length; i++) {
    const cols = splitCsv(lines[i], delim);
    let first = iFirst >= 0 ? cols[iFirst]?.trim() : "";
    let last  = iLast  >= 0 ? cols[iLast]?.trim()  : "";
    const fullName = iName >= 0 ? cols[iName]?.trim() : "";

    if (!first && !last && fullName) {
      const parts = fullName.split(/\s+/);
      first = parts[0] || "";
      last  = parts.slice(1).join(" ");
    }
    const full = (fullName || `${first} ${last}`).trim();

    const email = iEmail >= 0 ? cols[iEmail]?.trim() : "";
    const phone = iPhone >= 0 ? cols[iPhone]?.trim() : "";

    if (!full)        { skipped++; continue; }
    if (!email && !phone) { skipped++; continue; }

    rows.push({
      first_name: first || null,
      last_name:  last  || null,
      full_name:  full,
      email:      email || null,
      phone:      phone ? toE164(phone) : null,
    });
  }
  return { rows, skipped, headers };
}

// Minimal CSV splitter: handles double-quoted fields with embedded commas.
function splitCsv(line, delim) {
  const out = [];
  let cur = "", inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (inQ && line[i + 1] === '"') { cur += '"'; i++; }
      else inQ = !inQ;
    } else if (c === delim && !inQ) {
      out.push(cur); cur = "";
    } else {
      cur += c;
    }
  }
  out.push(cur);
  return out;
}

// Loose phone normalizer → E.164. Stored as +1XXXXXXXXXX for US numbers,
// otherwise passes through anything already starting with +.
function toE164(raw) {
  const digits = String(raw).replace(/[^\d+]/g, "");
  if (digits.startsWith("+")) return digits;
  if (digits.length === 10) return "+1" + digits;
  if (digits.length === 11 && digits.startsWith("1")) return "+" + digits;
  return digits ? "+" + digits : null;
}

// ── Bulk driver ingest ────────────────────────────────────────────
// Parse a pasted spreadsheet/CSV/TSV block into driver insert rows.
// Tolerant of: tabs OR commas, optional header row, surrounding
// quotes, mixed whitespace, blank lines, "$22.50"-style stray fields.
function _bdImportSplit(line, delim) {
  // Mini CSV that honours quoted commas — keeps "Smith, Jr." in one cell.
  const out = [];
  let cur = "", inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (inQ && line[i + 1] === '"') { cur += '"'; i++; }
      else inQ = !inQ;
    } else if (c === delim && !inQ) {
      out.push(cur); cur = "";
    } else { cur += c; }
  }
  out.push(cur);
  return out.map(s => s.trim().replace(/^"|"$/g, ""));
}
// Header synonyms → canonical field key.  Keys are matched after
