// ─── OKAMI (demand) + Schedule (supply) ───────────────────────────────────
//
// OKAMI: 3-week per-day per-station route TARGET grid. Editable.
// Schedule: 3-week per-day per-station coverage view (filled vs needed),
// plus time-off and open-shifts panels.

const RR_SCHED_WEEKS = 3;
const RR_DAY_SHORT   = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];

// Amazon DSP convention: weeks run Sunday → Saturday.  This helper
// returns the Sunday on-or-before `d` (matches the SQL
// `private.week_start_for(date)` redefined in migration 0265). The
// legacy `startOfWeekMonday` alias is kept as a thin shim for any
// external code that still imports the old name.
function startOfWeek(d) {
  const date = new Date(d);
  const day = date.getDay();             // 0=Sun, 1=Mon, ..., 6=Sat
  date.setDate(date.getDate() - day);    // back up to the prior Sunday
  date.setHours(0, 0, 0, 0);
  return date;
}
const startOfWeekMonday = startOfWeek;   // legacy alias — Sunday-anchored now
function fmtIsoDate(d) { return d.toISOString().slice(0, 10); }
function fmtMD(d) { return d.toLocaleDateString(undefined, { month: "short", day: "numeric" }); }
function addDays(d, n) { const x = new Date(d); x.setDate(x.getDate() + n); return x; }


// NOTE — earlier iteration of this code overwrote the OKAMI table and
// Schedule subview innerHTML, replacing the polished mockup layout with
// a generic grid. Operator pushed back; mockup design is the source of
// truth. Wiring live data INTO the mockup elements (without touching
// the structure) is queued as a follow-up.
//
// For now: leave the mockup OKAMI + Schedule views untouched. Schema
// (0025) and RPCs are still deployed and usable from SQL / future UI.

let _okamiStations = [];
let _schedDriverList = [];
// Driver column sort mode: "alpha" (A–Z, default), "wave" (by primary
// wave assignment that week), or "hours" (by hours scheduled, desc).
// Session-only — not persisted across reloads.
let _schedDriverSort = "alpha";

// Unassign every driver from every shift in the visible week. Shifts stay;
// only driver_id is cleared. Shared by the Open-shifts pool button
// (#rr-unassign-week) and the driver-header icon (#rr-sched-unassign-week-icon).
// The text button shows an "Unassigning…" label while in flight; the icon
// just gets disabled + aria-busy so its SVG isn't clobbered.
async function _runUnassignAllShiftsForWeek(triggerEl) {
  const dspId = window.RR?.dsp?.id;
  if (!dspId || !_schedStart) return;
  if (typeof _confirmLiveScheduleEdit === "function" && !_confirmLiveScheduleEdit()) return;
  const weekEndIso = fmtIsoDate(addDays(new Date(_schedStart + "T12:00:00"), 6));
  // No confirm() prompt — the action is fully undoable (we snapshot the
  // prior assignments below for Undo), so it runs immediately on click.
  const isTextBtn = triggerEl && triggerEl.id === "rr-unassign-week";
  if (triggerEl) {
    triggerEl.disabled = true;
    triggerEl.setAttribute("aria-busy", "true");
    if (isTextBtn) triggerEl.textContent = "Unassigning…";
  }
  // Snapshot the assignments we're about to clear so the bulk action can
  // be undone (restores each shift's prior driver). Same filter as the
  // clear below so the snapshot matches exactly what gets unassigned.
  let _priorAssign = [];
  try {
    const { data: _pa } = await sb.from("shifts")
      .select("id, driver_id")
      .eq("dsp_id", dspId)
      .gte("date", _schedStart)
      .lte("date", weekEndIso)
      .not("driver_id", "is", null)
      .not("shift_kind", "in", "(training,ride_along)");
    _priorAssign = _pa || [];
  } catch (_) {}
  // Confirm before wiping a finalized (live) week or a large number of
  // assignments — this instantly de-publishes and clears the week. (Undo
  // exists, but a mis-click on a live week is costly enough to gate.)
  const _isFinalized = !!window._rrWeekFinalized;
  if ((_isFinalized || _priorAssign.length >= 10) && typeof _rrConfirmDialog === "function") {
    const ok = await _rrConfirmDialog({
      title: "Unassign every shift this week?",
      body: (_isFinalized ? "This week is LIVE. Unassigning all shifts will unpublish it and " : "This will ")
        + `clear ${_priorAssign.length} driver assignment${_priorAssign.length === 1 ? "" : "s"}. You can undo this.`,
      confirmLabel: "Unassign all",
      cancelLabel: "Cancel",
    });
    if (!ok) {
      if (triggerEl) { triggerEl.disabled = false; triggerEl.removeAttribute("aria-busy"); if (isTextBtn) triggerEl.textContent = "Unassign all shifts this week"; }
      return;
    }
  }
  // Only clear route shifts. Classroom training + ride-alongs are deliberate
  // driver↔driver pairings (trainee/trainer) and must survive Unassign all,
  // same as PTO / time-off (which live in time_off_requests, not shifts).
  const { error, count } = await sb.from("shifts")
    .update({ driver_id: null }, { count: "exact" })
    .eq("dsp_id", dspId)
    .gte("date", _schedStart)
    .lte("date", weekEndIso)
    .not("driver_id", "is", null)
    .not("shift_kind", "in", "(training,ride_along)");
  if (triggerEl) {
    triggerEl.disabled = false;
    triggerEl.removeAttribute("aria-busy");
    if (isTextBtn) triggerEl.textContent = "Unassign all shifts this week";
  }
  if (error) { toast("Unassign failed: " + error.message, "warn"); return; }
  // Clearing every assignment effectively returns the week to a draft, so a
  // finalized ("Live") week auto-unfinalizes — drivers no longer see it and
  // the Draft pill comes back. Done silently; we fold it into one toast.
  let reverted = false;
  if (window._rrWeekFinalized && typeof _setWeekFinalized === "function") {
    const ok = await _setWeekFinalized(false, { silent: true });
    reverted = ok !== false;
  }
  toast(`Unassigned ${count ?? "all"} shifts for the week${reverted ? " · schedule back to draft" : ""}`, "success");
  if (_priorAssign.length && typeof _rrPushUndo === "function") {
    _rrPushUndo({
      label: `Unassigned all · ${_priorAssign.length} shift${_priorAssign.length === 1 ? "" : "s"}`,
      undo: async () => {
        // Restore each shift's prior driver. (Re-finalizing the week, if it
        // auto-reverted to draft, is left to the operator.)
        for (const row of _priorAssign) {
          const { error: e2 } = await sb.from("shifts")
            .update({ driver_id: row.driver_id }).eq("id", row.id);
          if (e2) throw new Error(e2.message);
        }
        _rrRevealNextRender = true;
        if (typeof renderScheduleWeek === "function") renderScheduleWeek();
      },
    });
  }
  // Animate the cleared shift chips OUT first (fade + scale-down), so the
  // operator watches the assignments leave, THEN repaint and re-settle
  // the surviving cards back in. We have the exact ids from _priorAssign.
  const _reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const _leaving = _reduce ? [] : _priorAssign
    .map(r => document.querySelector(`.shift-chip[data-rr-shift-id="${r.id}"]`))
    .filter(Boolean);
  const _repaint = () => {
    // Surviving cards re-settle in on the repaint, matching Smart Fill.
    _rrRevealNextRender = true;
    if (typeof renderScheduleWeek === "function") renderScheduleWeek();
  };
  if (_leaving.length) {
    _leaving.forEach(c => c.classList.add("rr-sf-card-out"));
    setTimeout(_repaint, 200);
  } else {
    _repaint();
  }
}

// Click handler for the schedule driver-sort icon — opens a small
// popover with three options (matches the Turnover KPI pattern).
document.addEventListener("click", (e) => {
  const btn = e.target.closest("#rr-sched-driver-sort-toggle");
  if (btn) {
    e.stopPropagation();
    e.preventDefault();
    const head = btn.parentElement;
    const existing = head.querySelector(".rr-tf-popover");
    if (existing) { existing.remove(); return; }
    document.querySelectorAll(".rr-tf-popover").forEach(el => el.remove());
    const opts = [
      { v: "alpha",  l: "A – Z" },
      { v: "tenure", l: "By tenure" },
      { v: "wave",   l: "By wave" },
      { v: "hours",  l: "By hours" },
      { v: "route",  l: "By route type" },
    ];
    const pop = document.createElement("div");
    pop.className = "rr-tf-popover";
    pop.style.top = "26px";
    pop.style.right = "0";
    pop.innerHTML = opts.map(o =>
      `<button data-rr-sched-sort="${o.v}" class="${o.v === _schedDriverSort ? "active" : ""}">${o.l}</button>`
    ).join("");
    head.appendChild(pop);
    return;
  }
  const opt = e.target.closest("[data-rr-sched-sort]");
  if (opt) {
    _schedDriverSort = opt.dataset.rrSchedSort || "alpha";
    document.querySelectorAll(".rr-tf-popover").forEach(el => el.remove());
    if (typeof renderScheduleWeek === "function") renderScheduleWeek();
    return;
  }
  // Focus mode — hide page chrome so the grid + open-shifts fill the screen.
  const focusBtn = e.target.closest("#rr-sched-focus-toggle");
  if (focusBtn) {
    e.preventDefault();
    e.stopPropagation();
    const on = !document.body.classList.contains("rr-sched-focus");
    document.body.classList.toggle("rr-sched-focus", on);
    focusBtn.setAttribute("aria-pressed", on ? "true" : "false");
    return;
  }
  // Hide / show the Open shifts rail. Unlike focus mode, this only collapses
  // the right-hand panel so the calendar grid fills that space; all other
  // page chrome stays. Persisted under rr-sched-hide-openshifts.
  // Operations Health show/hide — right-rail shield button. Reveals or
  // condenses the ophealth dock via the same body.rr-sched-hide-openshifts
  // class the (now-removed) in-header toggle used. aria-expanded tracks
  // "panel shown".
  const ophBtn = e.target.closest("[data-rr-ophealth-toggle]");
  if (ophBtn) {
    e.preventDefault();
    e.stopPropagation();
    const show = document.body.classList.contains("rr-sched-hide-openshifts"); // hidden → reveal
    // Slide-outs are mutually exclusive in BOTH directions: revealing the
    // dock closes any open rail panel (Notes/Tasks/Forms/Contacts/Recog),
    // just as opening one of those dismisses the dock.
    if (show && typeof _rrNtPanelCloseAll === "function") _rrNtPanelCloseAll();
    document.body.classList.toggle("rr-sched-hide-openshifts", !show);
    ophBtn.setAttribute("aria-expanded", show ? "true" : "false");
    try { localStorage.setItem("rr-sched-hide-openshifts", show ? "0" : "1"); } catch (_) {}
    return;
  }
  const osBtn = e.target.closest("#rr-sched-openshifts-toggle");
  if (osBtn) {
    e.preventDefault();
    e.stopPropagation();
    const hidden = !document.body.classList.contains("rr-sched-hide-openshifts");
    document.body.classList.toggle("rr-sched-hide-openshifts", hidden);
    osBtn.setAttribute("aria-pressed", hidden ? "true" : "false");
    osBtn.title = hidden
      ? "Show the Open shifts panel"
      : "Hide the Open shifts panel — the schedule fills the space";
    osBtn.setAttribute("aria-label", hidden ? "Show open shifts" : "Hide open shifts");
    const hideIc = osBtn.querySelector(".ic-os-hide");
    const showIc = osBtn.querySelector(".ic-os-show");
    if (hideIc && showIc) {
      hideIc.style.display = hidden ? "none" : "";
      showIc.style.display = hidden ? "" : "none";
    }
    try { localStorage.setItem("rr-sched-hide-openshifts", hidden ? "1" : "0"); } catch (_) {}
    return;
  }
  // Unassign all shifts this week — header-icon twin of the Open-shifts
  // pool button. Same action: clears every driver assignment for the
  // visible week (shifts stay). Shared logic in _runUnassignAllShiftsForWeek.
  const unassignBtn = e.target.closest("#rr-sched-unassign-week-icon");
  if (unassignBtn) {
    e.preventDefault();
    e.stopPropagation();
    _runUnassignAllShiftsForWeek(unassignBtn);
    return;
  }
  // Density cycle — Standard → Compact → Ultra-compact → Standard.
  // The DRIVER-header icon now cycles through ALL THREE grid-density
  // modes (was a binary Standard/Compact toggle). Shares the same
  // `rr-sched-density` localStorage key + body classes as the Week-
  // rules density picker, and syncs that picker's radios, so the two
  // controls stay in lockstep.
  const compactBtn = e.target.closest("#rr-sched-compact-toggle");
  if (compactBtn) {
    e.preventDefault();
    e.stopPropagation();
    // "standard" (the largest grid size) removed from the cycle per
    // operator request — the toggle now cycles Compact → Ultra → Super.
    const ORDER = ["compact", "ultra", "super"];
    const cur = document.body.classList.contains("rr-sched-super-compact")
      ? "super"
      : document.body.classList.contains("rr-sched-ultra-compact")
        ? "ultra"
        : document.body.classList.contains("rr-sched-compact")
          ? "compact"
          : "standard";
    const next = ORDER[(ORDER.indexOf(cur) + 1) % ORDER.length];
    document.body.classList.remove("rr-sched-compact", "rr-sched-ultra-compact", "rr-sched-super-compact");
    if (next === "compact")      document.body.classList.add("rr-sched-compact");
    else if (next === "ultra")   document.body.classList.add("rr-sched-ultra-compact");
    else if (next === "super")   document.body.classList.add("rr-sched-super-compact");
    try { localStorage.setItem("rr-sched-density", next); } catch (_) {}
    // Keep the Week-rules density radios in sync.
    document.querySelectorAll('input[name="rr-sched-density"]').forEach((r) => {
      r.checked = (r.value === next);
    });
    const TITLE = {
      standard: "Grid density: Standard — click for Compact",
      compact:  "Grid density: Compact — click for Ultra-compact",
      ultra:    "Grid density: Ultra-compact — click for Super-compact",
      super:    "Grid density: Super-compact — click for Compact",
    };
    compactBtn.setAttribute("aria-pressed", next === "standard" ? "false" : "true");
    compactBtn.title = TITLE[next];
    compactBtn.setAttribute("aria-label", "Grid density: " + next + " (click to cycle)");
    return;
  }
  // Weather forecast overlay — swap each day header from the date +
  // coverage/route counts to a single forecast glyph and back. No data
  // reload: _rrApplySchedWeatherToHeaders reads the markup stashed on each
  // header cell during render. When switching on, ensure the forecast is
  // loaded (schedule view may open before the dashboard weather card runs)
  // and re-apply once it lands.
  const wxBtn = e.target.closest("#rr-sched-weather-toggle");
  if (wxBtn) {
    e.preventDefault();
    e.stopPropagation();
    const on = !_rrSchedWeatherOn();
    try { localStorage.setItem("rr-sched-weather", on ? "1" : "0"); } catch (_) {}
    _rrApplySchedWeatherToHeaders();
    if (on) {
      _rrEnsureSchedWxForecast().then(() => _rrApplySchedWeatherToHeaders()).catch(() => {});
    }
    return;
  }
  // Staff view — operator wants to STAY on the Week's .cal-grid
  // layout (same chrome, same header, same row format) but see
  // only staff (role <> 'driver') instead of drivers. Hides every
  // driver row, then injects staff rows fetched from
  // staff_schedule_grid into the same .cal-wrap.
  const staffBtn = e.target.closest("#rr-sched-staff-view-toggle");
  if (staffBtn) {
    e.preventDefault();
    e.stopPropagation();
    const on = !document.body.classList.contains("rr-sched-staff-mode");
    const labelEl = document.getElementById("rr-sched-row-label");
    if (on) {
      document.body.classList.add("rr-sched-staff-mode");
      staffBtn.setAttribute("aria-pressed", "true");
      if (labelEl) labelEl.textContent = "Staff";
      try { localStorage.setItem("rr-sched-staff-only", "1"); } catch (_) {}
      _rrRenderStaffInWeekGrid();
    } else {
      document.body.classList.remove("rr-sched-staff-mode");
      staffBtn.setAttribute("aria-pressed", "false");
      if (labelEl) labelEl.textContent = "Driver";
      try { localStorage.setItem("rr-sched-staff-only", "0"); } catch (_) {}
      _rrClearStaffWeekRows();
      if (typeof renderScheduleWeek === "function") {
        try { renderScheduleWeek(); } catch (_) {}
      }
    }
    return;
  }
});

// Pull staff_schedule_grid for the visible Week and inject one
// .cal-grid row per staff member into the Week sub-view's
// .cal-wrap. Each row carries a .cal-cell-head (staff name +
// role line) and seven .cal-cell day cells; each day cell holds
// a .shift-chip for any shifts the staff member is scheduled on.
// CSS-rule body.rr-sched-staff-mode in schedule-rrx.css hides
// the original driver .cal-grid rows while we're in staff mode.
async function _rrRenderStaffInWeekGrid() {
  const calWrap = document.querySelector('#sched-sub-week .cal-wrap');
  if (!calWrap) return;
  const head = calWrap.querySelector('.cal-grid.head');
  if (!head) return;
  const start = _schedStart || fmtIsoDate(startOfWeekMonday(new Date()));
  // Loading row.
  _rrClearStaffWeekRows();
  const loading = document.createElement('div');
  loading.className = 'cal-grid rr-staff-week-row rr-staff-week-loading';
  loading.innerHTML = '<div class="cal-cell-head" style="padding:14px 16px;color:var(--text-subtle)">Loading staff schedule…</div>';
  head.parentNode.appendChild(loading);
  const { data, error } = await sb.rpc('staff_schedule_grid', { p_start: start, p_weeks: 1 });
  loading.remove();
  if (error) {
    const err = document.createElement('div');
    err.className = 'cal-grid rr-staff-week-row rr-staff-week-error';
    err.innerHTML = `<div class="cal-cell-head" style="padding:14px 16px;color:var(--red)">Couldn't load staff: ${escapeHtml(error.message)}</div>`;
    head.parentNode.appendChild(err);
    return;
  }
  const staff  = (data && data.staff)  || [];
  const shifts = (data && data.shifts) || [];
  if (!staff.length) {
    const empty = document.createElement('div');
    empty.className = 'cal-grid rr-staff-week-row rr-staff-week-empty';
    empty.innerHTML = '<div class="cal-cell-head" style="padding:14px 16px;color:var(--text-subtle)">No staff yet. Add dispatchers, fleet managers, HR, and other support staff to schedule them.</div>';
    head.parentNode.appendChild(empty);
    return;
  }
  // Bucket shifts by staff + day
  const byCell = new Map();
  for (const s of shifts) {
    const k = `${s.staff_id}|${s.date}`;
    if (!byCell.has(k)) byCell.set(k, []);
    byCell.get(k).push(s);
  }
  const startDate = new Date(start + 'T12:00:00');
  const ROLE_LABEL = {
    dispatcher: 'Dispatcher', fleet_manager: 'Fleet manager',
    hr: 'HR', ops_manager: 'Ops manager', other: 'Other',
  };
  const frag = document.createDocumentFragment();
  staff.forEach((m) => {
    const row = document.createElement('div');
    row.className = 'cal-grid rr-staff-week-row';
    row.dataset.rrStaffMember = m.id;
    const initials = (m.full_name || '?').split(/\s+/).filter(Boolean).slice(0, 2).map((p) => p[0]).join('').toUpperCase() || '?';
    const roleLine = ROLE_LABEL[m.role] || m.role || '';
    const label = `<div class="cal-cell-head cal-row-label" data-rr-no-drawer>`
      + `<div class="avatar-sm">${escapeHtml(initials)}</div>`
      + `<div><div class="cal-row-label-name">${escapeHtml(m.full_name || '—')}</div>`
      +   `<div class="cal-row-label-meta">${escapeHtml(roleLine)}</div></div>`
      + `</div>`;
    let cells = '';
    for (let i = 0; i < 7; i++) {
      const d = addDays(startDate, i);
      const iso = fmtIsoDate(d);
      const todays = byCell.get(`${m.id}|${iso}`) || [];
      const chips = todays.map((s) => {
        const t1 = s.starts_at ? new Date(s.starts_at).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }) : '';
        const t2 = s.ends_at   ? new Date(s.ends_at  ).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }) : '';
        const inner = (t1 || t2)
          ? `<div class="shift-chip-time">${escapeHtml(t1)}${t2 ? ' – ' + escapeHtml(t2) : ''}</div>`
          : `<div class="shift-chip-time">All day</div>`;
        return `<div class="shift-chip" data-rr-shift-id="${escapeHtml(s.id)}">${inner}</div>`;
      }).join('');
      cells += `<div class="cal-cell" data-iso="${iso}">${chips || '<div class="shift-chip off">Off</div>'}</div>`;
    }
    row.innerHTML = label + cells;
    frag.appendChild(row);
  });
  head.parentNode.appendChild(frag);
}

function _rrClearStaffWeekRows() {
  document.querySelectorAll('#sched-sub-week .rr-staff-week-row').forEach((el) => el.remove());
}
window._rrRenderStaffInWeekGrid = _rrRenderStaffInWeekGrid;
window._rrClearStaffWeekRows    = _rrClearStaffWeekRows;

// Rehydrate the Staff-view preference on every page load.
(function _rrHydrateStaffOnly(){
  let on = false;
  try { on = localStorage.getItem("rr-sched-staff-only") === "1"; } catch (_) {}
  if (!on) return;
  const apply = () => {
    const btn      = document.getElementById("rr-sched-staff-view-toggle");
    const labelEl  = document.getElementById("rr-sched-row-label");
    if (btn) btn.setAttribute("aria-pressed", "true");
    if (labelEl) labelEl.textContent = "Staff";
    document.body.classList.add("rr-sched-staff-mode");
    if (typeof _rrRenderStaffInWeekGrid === "function") {
      try { _rrRenderStaffInWeekGrid(); } catch (_) {}
    }
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", apply, { once: true });
  } else {
    setTimeout(apply, 200);
  }
})();

// Rehydrate the "Hide open shifts" preference on every page load.
(function _rrHydrateHideOpenShifts(){
  // Default: Operations Health hidden. It's revealed on demand from the
  // right utility rail's shield button now (the in-header toggle was
  // removed), so a fresh load starts condensed; an explicit "0"
  // preference keeps it shown.
  let hidden = true;
  try { const p = localStorage.getItem("rr-sched-hide-openshifts"); if (p !== null) hidden = p === "1"; } catch (_) {}
  const apply = () => {
    document.body.classList.toggle("rr-sched-hide-openshifts", hidden);
    const shield = document.querySelector("[data-rr-ophealth-toggle]");
    if (shield) shield.setAttribute("aria-expanded", hidden ? "false" : "true");
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", apply, { once: true });
  } else {
    setTimeout(apply, 200);
  }
})();

// Escape exits focus mode — operator safety net so a stuck class
// never traps the page chrome. Same pattern for the onboarding
// readiness-board focus mode (#rr-ob-focus-toggle on .ob-mx-head).
document.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  if (document.body.classList.contains("rr-sched-focus")) {
    document.body.classList.remove("rr-sched-focus");
    const btn = document.getElementById("rr-sched-focus-toggle");
    if (btn) btn.setAttribute("aria-pressed", "false");
  }
  if (document.body.classList.contains("rr-ob-focus")) {
    document.body.classList.remove("rr-ob-focus");
    const btn = document.getElementById("rr-ob-focus-toggle");
    if (btn) btn.setAttribute("aria-pressed", "false");
  }
  // Fleet-calendar Expand overlay — exit on Escape; repaint so the
  // VAN-header Expand icon flips back to its collapsed glyph.
  if (document.body.classList.contains("rr-fc-focus")) {
    document.body.classList.remove("rr-fc-focus");
    if (typeof _paintFleetCalendar === "function") _paintFleetCalendar();
  }
});

// Onboarding readiness-board focus toggle. Delegated so it survives
// the re-render the matrix does whenever data refreshes — the button
// re-renders too but the listener doesn't have to be rebound.
document.addEventListener("click", (e) => {
  const t = e.target.closest("#rr-ob-focus-toggle");
  if (!t) return;
  e.preventDefault();
  e.stopPropagation();
  const on = !document.body.classList.contains("rr-ob-focus");
  document.body.classList.toggle("rr-ob-focus", on);
  t.setAttribute("aria-pressed", on ? "true" : "false");
});

// Onboarding readiness-board compact toggle. Same delegated pattern
// as focus mode so it survives matrix re-renders. Persisted in
// localStorage('rr-ob-density') so the choice survives reloads —
// matches the schedule density picker's persistence model.
document.addEventListener("click", (e) => {
  const t = e.target.closest("#rr-ob-compact-toggle");
  if (!t) return;
  e.preventDefault();
  e.stopPropagation();
  const on = !document.body.classList.contains("rr-ob-compact");
  document.body.classList.toggle("rr-ob-compact", on);
  t.setAttribute("aria-pressed", on ? "true" : "false");
  try { localStorage.setItem("rr-ob-density", on ? "compact" : "standard"); } catch (er) {}
});

// Rehydrate compact state from localStorage on page load, then
// after every matrix re-render (the new button starts at
// aria-pressed="false" so we have to flip it back).
(function () {
  function applyObDensity() {
    let mode = null;
    try { mode = localStorage.getItem("rr-ob-density"); } catch (er) {}
    const on = mode === "compact";
    document.body.classList.toggle("rr-ob-compact", on);
    const btn = document.getElementById("rr-ob-compact-toggle");
    if (btn) btn.setAttribute("aria-pressed", on ? "true" : "false");
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", applyObDensity);
  } else {
    applyObDensity();
  }
  // Re-apply when the operator navigates to onboarding (the matrix
  // re-renders and the toggle button is replaced).
  document.addEventListener("click", function (e) {
    if (!e.target.closest("[data-obsub='overview'], [data-v='onboarding-ops']")) return;
    setTimeout(applyObDensity, 150);
    setTimeout(applyObDensity, 600);
  });
})();
let _okamiStart = null;
let _schedStart = null;

async function loadOkamiView() {
  await renderOkamiLive();
  bindOkamiHandlers();
  // The OKAMI page hosts a mirror of the schedule's quick-settings
  // popover inputs (Block / Cushion / Report time). Re-populate them
  // from the per-week scheduling-settings RPC every time the operator
  // lands on the page so the toolbar reflects the current week-anchor.
  if (typeof loadSchedulingSettings === "function") {
    try { loadSchedulingSettings(); } catch (e) { console.warn("OKAMI targets-rules load:", e); }
  }
}

// ─── OKAMI · 13-week list (live render + save) ─────────────────────────────

const RR_OKAMI_WEEKS = 13;
const RR_OKAMI_HIRE_LEAD_DAYS = 28; // training/onboarding lead time

function isoWeekNumber(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
}

let _okamiActiveCount = 0;
let _okamiTotalsByDateCache = null;
let _okamiStartCache = null;

// Document-level listener for the Plan Pad slider so timing of when
// bindOkamiHandlers runs can't break it. Fires on every drag tick.
let _okamiPadSaveTimer = null;
document.addEventListener("input", (e) => {
  if (e.target?.id !== "rr-okami-pad") return;
  const pct = Math.max(0, Math.min(50, parseInt(e.target.value, 10) || 0));
  const lbl = document.getElementById("rr-okami-pad-val");
  if (lbl) lbl.textContent = `${pct}%`;
  if (window.RR?.dsp?.metadata) {
    window.RR.dsp.metadata.staffing = { ...(window.RR.dsp.metadata.staffing || {}), plan_pad_pct: pct };
  }
  // If the cache hasn't populated yet (rare — operator opened OKAMI and
  // dragged before the first fetch completed), fall back to renderOkamiLive
  // so the cells eventually update.
  if (!_okamiTotalsByDateCache) {
    if (typeof renderOkamiLive === "function") renderOkamiLive();
  } else {
    _okamiRecomputeFromCache(pct);
  }
  if (_okamiPadSaveTimer) clearTimeout(_okamiPadSaveTimer);
  _okamiPadSaveTimer = setTimeout(async () => {
    const dspId = window.RR?.dsp?.id;
    if (!dspId) return;
    const meta = window.RR.dsp.metadata || {};
    await sb.from("dsps").update({ metadata: meta }).eq("id", dspId);
  }, 500);
});

// Recompute Drivers Needed + Gap cells from cached data, no network call.
// Used when the operator drags the Staffing Plan Pad slider — instant
// feedback without waiting for okami_grid to round-trip.
function _okamiRecomputeFromCache(padPct) {
  if (!_okamiTotalsByDateCache || !_okamiStartCache) return;
  const okTbody = document.getElementById("okami-tbody");
  const allOkamiRows = okTbody
    ? Array.from(okTbody.querySelectorAll("tr:not(.okami-detail)"))
    : [];
  for (let w = 0; w < allOkamiRows.length; w++) {
    const row = allOkamiRows[w];
    const weekStart = addDays(_okamiStartCache, w * 7);
    let routesMax = 0;
    for (let d = 0; d < 7; d++) {
      const t = _okamiTotalsByDateCache.get(fmtIsoDate(addDays(weekStart, d))) || 0;
      if (t > routesMax) routesMax = t;
    }
    const needed = routesMax > 0 ? Math.ceil(routesMax * 2 * (1 + padPct / 100)) : 0;
    const gap = _okamiActiveCount - needed;
    const tdCells = row.querySelectorAll("td");
    if (tdCells[2]) tdCells[2].innerHTML = `<div class="plan-calc">${needed}</div>`;
    if (tdCells[3]) tdCells[3].innerHTML = `<div class="plan-calc">${_okamiActiveCount}</div>`;
    const gapEl = tdCells[4]?.querySelector(".plan-gap");
    if (gapEl) {
      gapEl.textContent = (gap >= 0 ? "+" : "") + gap;
      gapEl.classList.remove("ok", "warn", "bad");
      // Severity class drives the graduated red (or green) gap pill on the
      // Targets page (scoped CSS; standalone OKAMI leaves the gap unstyled).
      _rrApplyGapClass(gapEl, gap);
    }
  }
  try { _rrRefreshTargetsGapCard(); } catch (_) { /* gap card is optional */ }
}
let _okamiCushionPct = 10;

async function renderOkamiLive() {
  const r = await _renderOkamiLiveImpl();
  try { _rrRefreshTargetsGapCard(); } catch (_) { /* gap card is optional */ }
  return r;
}
// Attach to window at module load so the mockup recalcOkami stub can
// always find it. Same pattern as renderOkamiDailyPanel.
window.renderOkamiLive = renderOkamiLive;
// The inline oninput="recalcOkami()" on every Routes (max) input would
// refetch the row from DB on every keystroke and reset the value the
// operator just typed. Make it a no-op — the document-level input
// delegate handles the debounced save + re-render.
window.recalcOkami = function () { /* no-op */ };

async function _renderOkamiLiveImpl() {
  const tbody = document.getElementById("okami-tbody");
  if (!tbody) return;
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;

  // Anchor OKAMI to the actual current week by default so the
  // 13-week planner rolls forward as the calendar advances. When
  // the operator opens OKAMI from a specific Week view (Route
  // planning button), `window._rrOkamiAnchorOverride` lets that
  // overlay anchor on the visible week instead, so each week
  // really gets "its own" planning horizon. Cleared after read so
  // the next non-overlay refresh snaps back to the rolling anchor.
  const _override = window._rrOkamiAnchorOverride;
  if (_override) {
    _okamiStart = _override;
    window._rrOkamiAnchorOverride = null;
  } else {
    _okamiStart = fmtIsoDate(startOfWeekMonday(new Date()));
  }
  // Mirror to window so the Risk Forecast simulate hook (defined at
  // the top of the module) can map row index → ISO week-start without
  // having to reach into this function's scope.
  window._okamiStart = _okamiStart;
  const start = new Date(_okamiStart + "T12:00:00");

  const [gridRes, drvRes] = await Promise.all([
    sb.rpc("okami_grid", { p_start: _okamiStart, p_weeks: RR_OKAMI_WEEKS }),
    sb.from("drivers")
      .select("id, status", { count: "exact", head: true })
      .eq("dsp_id", dspId)
      .in("status", ["active", "onboarding"]),
  ]);

  if (gridRes.error) { console.warn("okami_grid:", gridRes.error.message); return; }
  if (drvRes.error)  { console.warn("driver count:", drvRes.error.message); return; }

  const cells = gridRes.data || [];
  _okamiActiveCount = drvRes.count || 0;

  // Sum target_routes per ISO date across all stations.
  const totalsByDate = new Map();
  for (const c of cells) {
    totalsByDate.set(c.date, (totalsByDate.get(c.date) || 0) + (c.target_routes || 0));
  }
  // Cache for fast slider re-renders (no network round-trip per drag tick).
  _okamiTotalsByDateCache = totalsByDate;
  _okamiStartCache = start;

  // Staffing Plan Pad — 0–50% buffer above the 2× per-route baseline.
  // Persisted on dsps.metadata.staffing.plan_pad_pct, defaults to 10%.
  // This is OKAMI-only — totally separate from the schedule cushion.
  const padPct = Math.max(0, Math.min(50,
    Number(window.RR?.dsp?.metadata?.staffing?.plan_pad_pct ?? 10) || 0));
  const padInput = document.getElementById("rr-okami-pad");
  const padLabel = document.getElementById("rr-okami-pad-val");
  if (padInput && Number(padInput.value) !== padPct) padInput.value = padPct;
  if (padLabel) padLabel.textContent = `${padPct}%`;

  // Mockup only assigned id='okami-row-N' to the first three rows; rows
  // 3..12 had no id, so the older lookup silently skipped them and W21
  // through W30 never got their labels rewritten. Use every non-detail
  // row inside #okami-tbody in document order instead.
  const okTbody = document.getElementById("okami-tbody");
  const allOkamiRows = okTbody
    ? Array.from(okTbody.querySelectorAll("tr:not(.okami-detail)"))
    : [];

  // Kick the shared forecast-rates load (drivers-per-route ratio, callout /
  // attrition rates). First render may run on defaults; the repaint hooks
  // inside the loader bring the dependent surfaces up to date.
  try { _rrEnsureForecastRates(); } catch (_) {}
  // Demand formula is shared with forecast-core: ceil(peak × dpr × (1+pad)).
  // dpr comes from hiring settings (default 2 = 1 primary + 1 backup) so the
  // planner and the staffing outlook finally agree on the ratio.
  const _fcDpr = window._rrForecastRates?.driversPerRoute ?? 2;
  // Data model published for the Risk Forecast + gap card (they read THIS,
  // not the table's DOM). Rebuilt whole on every render.
  const modelWeeks = [];

  for (let w = 0; w < RR_OKAMI_WEEKS; w++) {
    const row = allOkamiRows[w];
    if (!row) continue;
    const weekStart = addDays(start, w * 7);
    const weekEnd   = addDays(weekStart, 6);

    // Routes per day across the week, then peak.
    let routesMax = 0;
    for (let d = 0; d < 7; d++) {
      const iso = fmtIsoDate(addDays(weekStart, d));
      const t = totalsByDate.get(iso) || 0;
      if (t > routesMax) routesMax = t;
    }

    const needed  = rrDriversNeeded(routesMax, { driversPerRoute: _fcDpr, padPct });
    const gap     = _okamiActiveCount - needed;
    const hireBy  = addDays(weekStart, -RR_OKAMI_HIRE_LEAD_DAYS);

    // Update week label + dates (without disturbing the expand button or tags).
    const labelEl = row.querySelector(".plan-week-label");
    const datesEl = row.querySelector(".plan-week-dates");
    if (labelEl) labelEl.textContent = `W${isoWeekNumber(weekStart)}`;
    if (datesEl) datesEl.textContent = `${fmtMD(weekStart)}–${weekEnd.getDate()}`;

    // Routes (max) is now READ-ONLY — operator edits per-day in the
    // daily drill-down panel and Routes (max) reflects the peak day.
    // Editing the cell directly used to overwrite all 7 days, which
    // destroyed per-day variation. Set readOnly + light styling so it
    // looks like a display value, not an input.
    const input = row.querySelector(".plan-route-input");
    if (input) {
      // Don't clobber a value the operator is mid-edit. This render runs after
      // the debounced save's own refresh (and after any settings save), so
      // overwriting a FOCUSED field resets the number they just typed — the
      // "Routes (max) keeps changing as I type" bug. Only sync the displayed
      // peak when the field isn't focused.
      if (document.activeElement !== input) input.value = routesMax;
      input.readOnly = false;
      input.style.background = "";
      input.style.border = "";
      input.style.cursor = "";
      input.title = "Type a value to set all 7 days. Use the drill-down panel for per-day variation.";
      input.dataset.rrOkamiWeekIdx = String(w);
    }

    const tdCells = row.querySelectorAll("td");
    // [0]=Week, [1]=Routes input, [2]=Needed, [3]=Available, [4]=Gap, [5]=Strategy, [6]=Hire by, [7]=Status
    if (tdCells[2]) tdCells[2].innerHTML = `<div class="plan-calc">${needed}</div>`;
    if (tdCells[3]) tdCells[3].innerHTML = `<div class="plan-calc">${_okamiActiveCount}</div>`;

    // Plain numbers — no color codes / pills (operator wanted less noise).
    const gapEl = tdCells[4]?.querySelector(".plan-gap");
    if (gapEl) {
      gapEl.textContent = (gap >= 0 ? "+" : "") + gap;
      gapEl.classList.remove("ok", "warn", "bad");
      // Severity class drives the graduated red (or green) gap pill on the
      // Targets page (scoped CSS; standalone OKAMI leaves the gap unstyled).
      _rrApplyGapClass(gapEl, gap);
    }

    const stratEl = tdCells[5]?.querySelector(".strategy-pills");
    if (stratEl) {
      const text = gap >= 0 ? "Hold" : (gap >= -10 ? "+8h OT" : "Hire");
      stratEl.innerHTML = `<span class="u-sm-muted">${text}</span>`;
    }

    const hireByEl = tdCells[6]?.querySelector(".plan-calc");
    const hireByText = gap >= 0 ? "—" : fmtMD(hireBy);
    if (hireByEl) {
      hireByEl.textContent = hireByText;
    }

    // Status text uses the single forecast vocabulary (audit #84):
    // On track / Watch / At risk — same words as the Risk Forecast view
    // and the gap card, driven by the same coverage thresholds.
    const statusText = gap >= 0
      ? "On track"
      : RR_FC_LABEL[(needed > 0 && _okamiActiveCount / needed < 0.80) ? "risk" : "watch"];
    const statusPill = tdCells[7]?.querySelector(".plan-status-pill");
    if (statusPill) {
      statusPill.classList.remove("ok", "warn", "bad");
      statusPill.outerHTML = `<span class="u-sm-muted">${statusText}</span>`;
    }

    modelWeeks.push({
      idx: w,
      weekStartIso: fmtIsoDate(weekStart),
      label: `W${isoWeekNumber(weekStart)}`,
      dates: `${fmtMD(weekStart)}–${weekEnd.getDate()}`,
      routesMax, needed,
      avail: _okamiActiveCount,
      gap,
      hireBy: hireByText,
      statusText,
      statusKind: gap >= 0 ? "ok" : (needed > 0 && _okamiActiveCount / needed < 0.80 ? "risk" : "tight"),
    });
  }

  window._rrOkamiModel = { startIso: _okamiStart, weeks: modelWeeks };

  // Update top hires-needed summary cell, if present. One hire covers a
  // seat in every subsequent week, so this is the DEEPEST weekly shortfall
  // — never the sum of weekly gaps (that unit is driver-weeks).
  let peakHires = 0;
  for (const mw of modelWeeks) if (mw.gap < 0 && -mw.gap > peakHires) peakHires = -mw.gap;
  const sumValue = document.querySelector(".okami-summary-grid .okami-sum:first-child .okami-sum-value");
  if (sumValue) sumValue.textContent = peakHires;

  // Keep the Targets gap card in lockstep with the fresh model.
  try { if (typeof _rrRefreshTargetsGapCard === "function") _rrRefreshTargetsGapCard(); } catch (_) {}
}

let _okamiBound = false;
let _okamiSaveTimers = new Map();
const _okamiDirtyWeeks = new Set();

function _setOkamiSaveStatus(text, kind) {
  const el = document.getElementById("rr-okami-save-status");
  if (!el) return;
  el.textContent = text || "";
  el.style.color = kind === "warn" ? "var(--red)" : kind === "ok" ? "var(--green)" : "var(--text-subtle)";
}

function bindOkamiHandlers() {
  if (_okamiBound) return;
  _okamiBound = true;

  // The mockup's recalcOkami fires on every DPR / ADW / OT / cushion
  // slider tick and writes hardcoded okamiAvail values to every row's
  // cells, overwriting our live render. Neutralize it so only our
  // renderOkamiLive controls the table. Set at module top level (no-op);
  // do NOT reassign here — the inline oninput handlers on Routes (max)
  // inputs would refetch on every keystroke and clobber typed values.

  // Slider is wired via the document-level delegate at module top level
  // so it survives any DOM re-render or re-bind timing.

  // Sync schedule: take the visible week's OKAMI route targets and
  // push them into the shifts table so the operator sees the open-
  // shift count = (route plan + cushion) match what they planned.
  //
  // Daily route values auto-save on every keystroke via saveOkamiDaily;
  // this button is the explicit "now build the shifts from those
  // targets" action. It runs the same per-week pipeline that Settings
  // → Save uses:
  //   1. regenerate_week_shifts(_schedStart) — wipes unassigned
  //      scheduled rows in the week, regenerates from okami_demand,
  //      re-stamps starts_at to wave_time − report_lead.
  //   2. apply_cushion_to_week(_schedStart) — adds cushion shifts
  //      on top so the visible total = target × (1 + cushion%).
  //
  // Previously this loop iterated every okami_demand row DSP-wide
  // and only called generate_shifts_for_date — so reducing a target
  // didn't trim excess open shifts, and cushion was never applied.
  const saveBtn = document.getElementById("rr-okami-save-plan");
  if (saveBtn) {
    saveBtn.addEventListener("click", async () => {
      const dspId = window.RR?.dsp?.id;
      if (!dspId) { _setOkamiSaveStatus("DSP not loaded", "warn"); return; }
      const ws = _schedStart;
      if (!ws) { _setOkamiSaveStatus("Pick a week first", "warn"); return; }
      saveBtn.disabled = true;
      _setOkamiSaveStatus("Saving inputs…");
      try {
        // Flush any pending debounced okami_set_target writes so the
        // rebuild reads the latest typed values. Without this, a
        // quick "type 5 → click Save" sequence (within the 400ms
        // debounce window) regenerates from stale demand.
        await flushOkamiDailyPending();
        _setOkamiSaveStatus("Building shifts…");
        _markLocalShiftMutation();
        const { error: regenErr } = await sb.rpc("regenerate_week_shifts", { p_week_start: ws });
        if (regenErr) throw regenErr;

        let cushionAdded = 0;
        try {
          const { data, error: cushionErr } = await sb.rpc("apply_cushion_to_week", { p_week_start: ws });
          if (cushionErr) console.warn(`apply_cushion_to_week (${ws}):`, cushionErr.message);
          else cushionAdded = data || 0;
        } catch (e) {
          console.warn(`apply_cushion_to_week (${ws}) threw:`, e);
        }

        _setOkamiSaveStatus(`Schedule synced ✓${cushionAdded ? ` · +${cushionAdded} cushion` : ""}`, "ok");
        toast(`Schedule synced for week of ${ws}${cushionAdded ? ` · +${cushionAdded} cushion` : ""}`, "success");

        // Re-render the calendar behind the overlay so the open-shifts
        // pool reflects the new totals as soon as the operator closes.
        if (typeof renderScheduleWeek === "function") {
          try { await renderScheduleWeek(); } catch (e) { console.warn("re-render after OKAMI sync:", e); }
        }

        // Auto-close after a beat so the operator lands back on the
        // calendar showing the new shift count, matching the
        // "auto-populate into the open shift box after I hit save"
        // expectation. They can re-open if they want more edits.
        setTimeout(() => {
          if (typeof closeOkamiOverlay === "function") closeOkamiOverlay();
          _setOkamiSaveStatus("");
        }, 900);
      } catch (err) {
        _setOkamiSaveStatus("Failed: " + (err.message || err), "warn");
      } finally {
        saveBtn.disabled = false;
      }
    });
  }

  // Cushion slider — save on commit (mouseup/keyup), not every drag tick.
  const cushion = document.getElementById("okami-cushion");
  if (cushion) {
    cushion.addEventListener("change", async () => {
      const pct = parseInt(cushion.value, 10) || 0;
      const { error } = await sb.rpc("okami_set_cushion", { p_pct: pct });
      if (error) { toast("Save failed: " + error.message, "warn"); return; }
      _okamiCushionPct = pct;
      await renderOkamiLive();
    });
  }
  // DPR + ADW + OT are UI-only (no storage yet); recalc on change.
  ["okami-dpr", "okami-adw", "okami-ot"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("change", () => renderOkamiLive());
  });

  // Override the mockup toggle so the drill-down panel renders from real data.
  window.okamiToggleDaily = function (weekIdx) {
    const detail = document.getElementById(`okami-detail-${weekIdx}`);
    const btn = document.querySelector(`#okami-row-${weekIdx} .okami-expand-btn`);
    if (!detail || !btn) return;
    const isOpen = detail.classList.toggle("open");
    btn.classList.toggle("expanded", isOpen);
    if (isOpen) renderOkamiDailyPanel(weekIdx);
  };

  // The mockup's okamiRenderDailyPanel was deleted in index.html and now
  // delegates here via window. Expose the live renderer on window so the
  // mockup stub can find it.
  window.okamiRenderDailyPanel = renderOkamiDailyPanel;
  window.renderOkamiDailyPanel = renderOkamiDailyPanel;
}

async function saveOkamiWeek(w, routesMax) {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;
  if (!_okamiStart) return;
  const weekStart = addDays(new Date(_okamiStart + "T12:00:00"), w * 7);

  if (!_okamiStations || _okamiStations.length === 0) {
    const { data, error } = await sb.from("stations")
      .select("id, code, active").eq("dsp_id", dspId).eq("active", true);
    if (error) { toast("Save failed: " + error.message, "warn"); return; }
    _okamiStations = data || [];
  }
  if (_okamiStations.length === 0) {
    toast("No stations configured — add a station before setting OKAMI", "warn");
    return;
  }

  // Single-station mode: full value to first station, zero out the rest.
  // set_okami_week_demand wrote to ALL stations which inflated the displayed
  // peak by N× when multiple active stations existed.
  const target = Math.max(0, parseInt(routesMax, 10) || 0);
  const calls = [];
  for (let d = 0; d < 7; d++) {
    const iso = fmtIsoDate(addDays(weekStart, d));
    _okamiStations.forEach((s, idx) => {
      calls.push(sb.rpc("okami_set_target", { p_date: iso, p_station_id: s.id, p_target: idx === 0 ? target : 0 }));
    });
  }
  const results = await Promise.all(calls);
  const firstErr = results.find(r => r.error);
  if (firstErr) { toast("Save failed: " + firstErr.error.message, "warn"); return; }
  await renderOkamiLive();
}

// Debounced save when the operator types into a Routes (max) cell.
const _okamiWeekSaveTimers = new Map();
document.addEventListener("input", (e) => {
  const inp = e.target.closest("input.plan-route-input");
  if (!inp) return;
  const w = parseInt(inp.dataset.rrOkamiWeekIdx ?? "-1", 10);
  if (!Number.isFinite(w) || w < 0) return;
  const prev = _okamiWeekSaveTimers.get(w);
  if (prev) clearTimeout(prev);
  _okamiWeekSaveTimers.set(w, setTimeout(() => {
    saveOkamiWeek(w, parseInt(inp.value, 10) || 0);
  }, 600));
});

// ─── OKAMI · daily drill-down panel (PR C) ─────────────────────────────────

const RR_OKAMI_DAY_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const _okamiDailySaveTimers = new Map();
let _okamiDailyDelegated = false;

async function recommendOkamiCushion(dspId) {
  const since = new Date(); since.setDate(since.getDate() - 30);
  const sinceIso = fmtIsoDate(since);
  const [scheduledRes, absentRes] = await Promise.all([
    sb.from("shifts").select("id", { count: "exact", head: true })
      .eq("dsp_id", dspId).gte("date", sinceIso)
      .in("status", ["scheduled", "completed", "called_off", "no_show"]),
    sb.from("shifts").select("id", { count: "exact", head: true })
      .eq("dsp_id", dspId).gte("date", sinceIso)
      .in("status", ["called_off", "no_show"]),
  ]);
  if (scheduledRes.error || absentRes.error) {
    return { percent: 10, source: "Using default — no data yet", absences: 0, total: 0 };
  }
  const total = scheduledRes.count || 0;
  const absences = absentRes.count || 0;
  if (total === 0) {
    return { percent: 10, source: "No scheduled shifts in last 30d", absences: 0, total: 0 };
  }
  const rate = absences / total;
  const recommended = Math.max(5, Math.min(20, Math.round(rate * 100 * 1.5)));
  return {
    percent: recommended,
    absences,
    total,
    source: `${absences} callout${absences === 1 ? "" : "s"} + no-shows over ${total} scheduled last 30d = ${(rate * 100).toFixed(1)}% absence · 1.5× safety`,
  };
}

async function renderOkamiDailyPanel(weekIdx, targetContainerId) {
  return _renderOkamiDailyPanelImpl(weekIdx, targetContainerId);
}
// Attach to window at module load so the mockup stub in index.html can
// always find it, regardless of whether OKAMI has been bound yet.
window.renderOkamiDailyPanel = renderOkamiDailyPanel;
window.okamiRenderDailyPanel = renderOkamiDailyPanel;

// ─── Schedule · Targets sub-view (in-page OKAMI daily editor) ─────
// Hosts the same per-week route-planning panel the OKAMI page shows,
// but rendered INTO the schedule page's #sched-sub-targets container
// so operators stay on the schedule (same URL, same chrome) while
// they edit per-day route targets. Save path is shared — the daily
// inputs carry data-rr-okami-daily and the document-level
// delegation handles saves regardless of which surface they live in.
async function renderScheduleTargetsSubView() {
  // Anchor OKAMI on the schedule's currently-viewed week so the
  // 13-week table (moved into this sub-view at runtime) shows the
  // right horizon and the Block / Cushion / Report-time KPI inputs
  // line up with the same week.
  if (typeof _schedStart === "string" && _schedStart) {
    _okamiStart = _schedStart;
  } else if (!_okamiStart) {
    _okamiStart = fmtIsoDate(startOfWeekMonday(new Date()));
  }
  // The standalone daily editor used to live in
  // #sched-sub-targets-daily; operators asked us to drop it now that
  // the 13-week planner is on this page (every week's daily detail
  // is reachable via the row-expand button in the table itself).
  // Save-input delegation still binds in case they open a row.
  _bindOkamiDailyInputDelegation();
  // Populate the Block / Cushion / Report-time KPI strip inputs
  // from the per-week RPC. Same loader the popover + OKAMI page use.
  if (typeof loadSchedulingSettings === "function") {
    try { loadSchedulingSettings(); } catch (e) { console.warn("Targets sub-view settings:", e); }
  }
}
window.renderScheduleTargetsSubView = renderScheduleTargetsSubView;

async function _renderOkamiDailyPanelImpl(weekIdx, targetContainerId) {
  // The daily-detail panel renders into `okami-detail-content-${weekIdx}`
  // on the OKAMI page by default. The schedule's Targets sub-view
  // hosts a SECOND surface for the same panel — passing
  // `targetContainerId` redirects the render into that host (e.g.
  // "sched-sub-targets-daily") so both surfaces share one renderer
  // and one save path.
  const containerId = targetContainerId || `okami-detail-content-${weekIdx}`;
  const container = document.getElementById(containerId);
  if (!container) return;
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;
  if (!_okamiStart) return;

  const weekStart = addDays(new Date(_okamiStart + "T12:00:00"), weekIdx * 7);
  const startIso = fmtIsoDate(weekStart);
  const days = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));
  const todayIso = fmtIsoDate(new Date());

  container.innerHTML = `<div class="rr-loading">Loading</div>`;

  // Pull demand grid + cushion recommendation + this week's waves in one go.
  // Waves come from scheduling_settings (per-week, with DSP-level fallback)
  // so the OKAMI panel always matches what Schedule will use.
  const [gridRes, recommendation, settingsRes] = await Promise.all([
    sb.rpc("okami_grid", { p_start: startIso, p_weeks: 1 }),
    recommendOkamiCushion(dspId),
    sb.rpc("scheduling_settings_for_week", { p_week_start: startIso }),
  ]);
  if (gridRes.error) {
    container.innerHTML = `<div style="padding:18px;color:var(--red);font-size:var(--fs-sm)">Failed to load: ${escapeHtml(gridRes.error.message)}</div>`;
    return;
  }
  const cells = gridRes.data || [];
  const settings = settingsRes?.data || {};
  const waves = (Array.isArray(settings.waves) && settings.waves.length > 0)
    ? settings.waves
    : [{ start: "07:00" }];
  const waveCount = waves.length;

  // Active service types determine how many rows per wave to render.
  // A DSP with only SP active (the default) gets a single row per wave,
  // looking exactly like pre-0050. Activating XL / HUB / ASU adds rows.
  if (!_okamiServiceTypes) {
    const stRes = await sb.rpc("list_service_types");
    _okamiServiceTypes = (stRes.data || []);
  }
  const activeTypes = _okamiServiceTypes.filter(t => t.active);
  if (activeTypes.length === 0) {
    activeTypes.push({ id: null, code: "SP", label: "Standard Parcel", color: "#2563EB" });
  }
  const showTypeLabel = activeTypes.length > 1;

  // Per-(wave × type) totals: dailyByBucket[waveIdx][typeIdx][dayIdx].
  // okami_grid returns one row per (date, station) with targets_by_wave
  // carrying { wave_index, service_type_code, target_routes } entries.
  const dailyByBucket = waves.map(() => activeTypes.map(() => Array(7).fill(0)));
  for (const c of cells) {
    const dayIdx = days.findIndex(d => fmtIsoDate(d) === c.date);
    if (dayIdx < 0) continue;
    const byWave = Array.isArray(c.targets_by_wave) ? c.targets_by_wave : [];
    for (const w of byWave) {
      const wIdx = w?.wave_index ?? 0;
      const stCode = w?.service_type_code || "SP";
      const tIdx = activeTypes.findIndex(t => t.code === stCode);
      if (wIdx >= 0 && wIdx < waveCount && tIdx >= 0) {
        dailyByBucket[wIdx][tIdx][dayIdx] += (w?.target_routes || 0);
      }
    }
  }

  // Day totals + week stats sum across every bucket so the footer line
  // ("Week total / Peak day") reflects all-types-all-waves demand.
  const dayTotals = Array(7).fill(0);
  for (const waveBuckets of dailyByBucket) {
    for (const typeBuckets of waveBuckets) {
      for (let i = 0; i < 7; i++) dayTotals[i] += typeBuckets[i];
    }
  }
  const totalRoutes = dayTotals.reduce((s, n) => s + n, 0);
  const peakRoutes  = dayTotals.reduce((m, n) => n > m ? n : m, 0);

  const headerLabel = `W${isoWeekNumber(weekStart)} · ${fmtMD(weekStart)}–${addDays(weekStart, 6).getDate()}`;

  // One row per (wave × active type). Single-wave + single-type weeks
  // render exactly like pre-0050. Multi-wave or multi-type weeks get
  // one labelled row per bucket — labels include type code only when
  // 2+ types active (single-type weeks just say "Routes planned").
  const rowsHtml = waves.flatMap((wave, wIdx) => {
    const waveStart = wave?.start || "07:00";
    return activeTypes.map((st, tIdx) => {
      const labelParts = ["Routes planned"];
      if (showTypeLabel) labelParts.push(escapeHtml(st.code));
      if (waveCount > 1) labelParts.push(`Wave ${wIdx + 1} (${escapeHtml(waveStart)})`);
      const label = labelParts.join(" · ");
      const stIdAttr = st.id ? `data-service-type-id="${st.id}"` : "";
      const cellsHtml = days.map((d, i) => {
        const iso = fmtIsoDate(d);
        const isToday = iso === todayIso;
        return `<div class="okami-daily-cell${isToday ? " is-today" : ""}"><input type="number" min="0" max="200" value="${dailyByBucket[wIdx][tIdx][i]}" data-rr-okami-daily="${weekIdx}" data-iso="${iso}" data-wave="${wIdx}" ${stIdAttr}/></div>`;
      }).join("");
      return `<div class="okami-daily-row">
        <div class="okami-daily-label">${label}</div>
        ${cellsHtml}
      </div>`;
    });
  }).join("");

  container.innerHTML = `
    <div class="okami-daily-panel" style="grid-template-columns:1fr">
      <div class="okami-daily-grid">
        <div class="okami-daily-grid-head">
          <div>${escapeHtml(headerLabel)}</div>
          ${RR_OKAMI_DAY_LABELS.map(l => `<div>${l}</div>`).join("")}
        </div>
        ${rowsHtml}
      </div>
      <div style="grid-column:1 / -1;display:flex;justify-content:space-between;font-size:var(--fs-xs);color:var(--text-subtle);padding:var(--s-2-5) 4px 0">
        <span>Week total <strong style="color:var(--text)">${totalRoutes}</strong> routes</span>
        <span>Peak day <strong style="color:var(--text)">${peakRoutes} routes</strong> · cushion applied in Schedule</span>
      </div>
    </div>`;

  bindOkamiDailyDelegation();
}

// Document-level input delegation for daily-target inputs binds ONCE
// at module load — doesn't depend on the OKAMI table being mounted.
// That way the Targets sub-view's inputs save correctly even on a
// session where the operator never opens the standalone OKAMI page.
let _okamiDailyInputBound = false;
function _bindOkamiDailyInputDelegation() {
  if (_okamiDailyInputBound) return;
  _okamiDailyInputBound = true;
  document.addEventListener("input", (e) => {
    const inp = e.target.closest("input[data-rr-okami-daily]");
    if (!inp) return;
    const weekIdx = parseInt(inp.dataset.rrOkamiDaily, 10);
    const iso = inp.dataset.iso;
    const waveIdx = parseInt(inp.dataset.wave || "0", 10) || 0;
    const stId = inp.dataset.serviceTypeId || null;
    if (!iso || !Number.isFinite(weekIdx)) return;
    const key = `${weekIdx}|${iso}|${waveIdx}|${stId || "default"}`;
    const prev = _okamiDailySaveTimers.get(key);
    if (prev) clearTimeout(prev.timeoutId);
    // CRITICAL: don't close over the input DOM node. If the panel
    // re-renders between input event and the 400ms timer fire (a
    // cushion change, tab refresh tick, etc. all replace
    // container.innerHTML), the captured `inp` becomes detached and
    // its .value freezes at detach time. Some keystrokes commit,
    // others don't — produces the operator's "I typed 5 but got
    // 2,2,5,5,2,2,5" symptom.
    //
    // Instead: resolve the input by its own data attributes at fire
    // time so we always read the live DOM node's current value.
    const stSelector = stId
      ? `[data-service-type-id="${stId}"]`
      : ":not([data-service-type-id])";
    const liveSelector = `input[data-rr-okami-daily="${weekIdx}"][data-iso="${iso}"][data-wave="${waveIdx}"]${stSelector}`;
    const args = {
      weekIdx, iso, waveIdx, stId,
      getValue: () => {
        const live = document.querySelector(liveSelector);
        return live ? (parseInt(live.value, 10) || 0) : (parseInt(inp.value, 10) || 0);
      },
    };
    const timeoutId = setTimeout(() => {
      _okamiDailySaveTimers.delete(key);
      saveOkamiDaily(args.weekIdx, args.iso, args.getValue(), args.waveIdx, args.stId);
    }, 400);
    _okamiDailySaveTimers.set(key, { timeoutId, args });
  });

}

function bindOkamiDailyDelegation() {
  // Daily-input save delegation is document-level and bound exactly
  // once at first call — covers both the OKAMI page and the
  // Targets sub-view in one go.
  _bindOkamiDailyInputDelegation();

  if (_okamiDailyDelegated) return;
  const tbody = document.getElementById("okami-tbody");
  if (!tbody) return;
  _okamiDailyDelegated = true;

  // Cushion + recommendation handlers stay scoped to the OKAMI
  // table — the Targets sub-view intentionally doesn't expose the
  // cushion control (planning panel only).
  tbody.addEventListener("change", async (e) => {
    const cushionInp = e.target.closest("input[data-rr-okami-cushion-pct]");
    if (cushionInp) {
      const pct = Math.max(0, Math.min(50, parseInt(cushionInp.value, 10) || 0));
      const { error } = await sb.rpc("okami_set_cushion", { p_pct: pct });
      if (error) { toast("Save failed: " + error.message, "warn"); return; }
      _okamiCushionPct = pct;
      const topInp = document.getElementById("okami-cushion");
      if (topInp) topInp.value = pct;
      const topVal = document.getElementById("okami-cushion-val");
      if (topVal) topVal.innerHTML = `${pct}<span class="frac">%</span>`;
      const openIdx = openOkamiDetailIndex();
      if (openIdx != null) renderOkamiDailyPanel(openIdx);
      renderOkamiLive();
      return;
    }
  });

  tbody.addEventListener("click", async (e) => {
    const apply = e.target.closest("[data-rr-okami-apply-rec]");
    if (!apply) return;
    const pct = parseInt(apply.dataset.rrOkamiApplyRec, 10);
    if (!Number.isFinite(pct)) return;
    const { error } = await sb.rpc("okami_set_cushion", { p_pct: pct });
    if (error) { toast("Save failed: " + error.message, "warn"); return; }
    _okamiCushionPct = pct;
    const topInp = document.getElementById("okami-cushion");
    if (topInp) topInp.value = pct;
    const topVal = document.getElementById("okami-cushion-val");
    if (topVal) topVal.innerHTML = `${pct}<span class="frac">%</span>`;
    const openIdx = openOkamiDetailIndex();
    if (openIdx != null) renderOkamiDailyPanel(openIdx);
    renderOkamiLive();
    toast(`Cushion set to ${pct}%`, "success");
  });
}

function openOkamiDetailIndex() {
  for (let i = 0; i < RR_OKAMI_WEEKS; i++) {
    const d = document.getElementById(`okami-detail-${i}`);
    if (d && d.classList.contains("open")) return i;
  }
  return null;
}

// Force every pending debounced okami_set_target save to fire NOW
// and await them all. Used before regenerate_week_shifts so the
// rebuild reads the latest typed values, not 400ms-old stale demand.
async function flushOkamiDailyPending() {
  const pending = Array.from(_okamiDailySaveTimers.values());
  _okamiDailySaveTimers.clear();
  for (const { timeoutId } of pending) clearTimeout(timeoutId);
  await Promise.all(pending.map(({ args }) =>
    saveOkamiDaily(args.weekIdx, args.iso, args.getValue(), args.waveIdx, args.stId)
  ));
}

async function saveOkamiDaily(weekIdx, iso, routes, waveIdx = 0, stId = null) {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;
  if (!_okamiStations || _okamiStations.length === 0) {
    // Order by code so saveOkamiDaily's "first station gets the
    // value, others zero" semantics is deterministic across sessions.
    const { data, error } = await sb.from("stations")
      .select("id, code, active")
      .eq("dsp_id", dspId)
      .eq("active", true)
      .order("code");
    if (error) { toast("Save failed: " + error.message, "warn"); return; }
    _okamiStations = data || [];
  }
  if (_okamiStations.length === 0) {
    toast("No stations configured — add a station before setting OKAMI", "warn");
    return;
  }
  // Single-station mode: write the full value to the first station and
  // zero out the rest. Avoids the rounding drift you'd get from
  // round(routes / station_count) when station_count > 1.
  const calls = _okamiStations.map((s, idx) =>
    sb.rpc("okami_set_target", {
      p_date:             iso,
      p_station_id:       s.id,
      p_target:           idx === 0 ? routes : 0,
      p_wave_index:       waveIdx,
      p_service_type_id:  stId,
    })
  );
  const results = await Promise.all(calls);
  const firstErr = results.find(r => r.error);
  if (firstErr) { toast("Save failed: " + firstErr.error.message, "warn"); return; }
  // Don't re-render anything after a daily save — that's what was causing
  // the per-keystroke glitch. The operator's input keeps focus + value;
  // the 13-week Routes(max) cell will refresh on next view focus
  // (window.focus listener + 30s heartbeat both call refreshActiveView).
}

// ─── Settings · Scheduling (block hours, cushion, waves) ───────────────────

// ─── Fleet settings (DSP-level) ─────────────────────────────────────
// Single source of truth for the auto-van-assign toggle.  Cached on
// window.RR.fleetSettings so the Today's Plan can read it without an
// extra round-trip on every page focus.
async function loadFleetSettings() {
  if (!window.RR?.dsp?.id) return;
  try {
    const { data, error } = await sb.rpc("fleet_settings_get");
    if (error) { console.warn("fleet_settings_get:", error.message); return; }
    window.RR.fleetSettings = data || { auto_van_assign: false };
    const toggle = document.getElementById("rr-set-auto-van-assign");
    if (toggle) {
      toggle.checked = !!data?.auto_van_assign;
      const lbl = document.querySelector("[data-rr-auto-van-label]");
      if (lbl) lbl.textContent = data?.auto_van_assign ? "On" : "Off";
    }
  } catch (e) { console.warn("loadFleetSettings:", e); }
}

document.addEventListener("change", async (e) => {
  if (e.target?.id !== "rr-set-auto-van-assign") return;
  const next = !!e.target.checked;
  const lbl = document.querySelector("[data-rr-auto-van-label]");
  if (lbl) lbl.textContent = next ? "On" : "Off";
  const { error } = await sb.rpc("fleet_settings_set", { p_auto_van_assign: next });
  if (error) {
    toast("Couldn't save: " + error.message, "warn");
    e.target.checked = !next;
    if (lbl) lbl.textContent = !next ? "On" : "Off";
    return;
  }
  window.RR.fleetSettings = { ...(window.RR.fleetSettings || {}), auto_van_assign: next };
  toast(`Auto-assign vans turned ${next ? "on" : "off"}.`, "ok");
  // If turning on, fire it for today right away so the operator sees the effect.
  if (next && typeof _refreshTodayPlanData === "function") _refreshTodayPlanData();
});


async function loadSchedulingSettings() {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return;
  if (!_schedStart) _schedStart = fmtIsoDate(startOfWeekMonday(new Date()));

  // Fleet settings live on their own DSP-level row — load them too so
  // the toggle in Settings → Scheduling reflects current state.
  loadFleetSettings();

  const { data, error } = await sb.rpc("scheduling_settings_for_week", { p_week_start: _schedStart });
  if (error) { console.warn("scheduling settings load:", error.message); return; }
  const s = data || {};

  const blockEl  = document.getElementById("rr-set-block-hours");
  const cushEl   = document.getElementById("rr-set-cushion-pct");
  const maxDaysEl = document.getElementById("rr-set-max-days");
  const leadEl    = document.getElementById("rr-set-report-lead");
  const wavesEl  = document.getElementById("rr-set-waves");
  const statusEl = document.getElementById("rr-set-sched-status");

  if (blockEl)   blockEl.value   = s.default_block_hours ?? 10;
  if (cushEl)    cushEl.value    = s.cushion_pct ?? 10;
  if (maxDaysEl) maxDaysEl.value = s.max_days_per_week ?? 5;
  if (leadEl)    leadEl.value    = s.report_lead_minutes ?? 0;

  // Mirror the same per-week values into the OKAMI page's embedded
  // Targets-rules toolbar. Both surfaces read from the same RPC
  // (scheduling_settings_for_week) and write through the same save
  // path (_saveScheduleSettings), so the OKAMI page just gets a
  // second pair of inputs bound to the same backing storage. Skip if
  // the OKAMI page isn't rendered yet.
  const okBlockEl = document.getElementById("rr-okami-set-block-hours");
  const okCushEl  = document.getElementById("rr-okami-set-cushion-pct");
  const okLeadEl  = document.getElementById("rr-okami-set-report-lead");
  if (okBlockEl) okBlockEl.value = s.default_block_hours ?? 10;
  if (okCushEl)  okCushEl.value  = s.cushion_pct ?? 10;
  if (okLeadEl)  okLeadEl.value  = s.report_lead_minutes ?? 0;

  // Same mirror for the schedule's Targets sub-view (third surface).
  // Popover ↔ OKAMI page ↔ Targets sub-view all share scheduling-
  // settings_for_week as backing storage and stay live-in-sync via
  // _rrMirrorPopoverToOkami / _rrMirrorOkamiToPopover.
  const tgBlockEl = document.getElementById("rr-sched-targets-block-hours");
  const tgCushEl  = document.getElementById("rr-sched-targets-cushion-pct");
  const tgLeadEl  = document.getElementById("rr-sched-targets-report-lead");
  if (tgBlockEl) tgBlockEl.value = s.default_block_hours ?? 10;
  if (tgCushEl)  tgCushEl.value  = s.cushion_pct ?? 10;
  if (tgLeadEl)  tgLeadEl.value  = s.report_lead_minutes ?? 0;

  // Read-only attendance rate label next to the cushion field. Operator
  // looks at it and decides their own cushion %. No click handler, no
  // mutation of any other element — kept deliberately minimal after the
  // recommendation chip kept breaking the dashboard.
  (async () => {
    try {
      const dspId = window.RR?.dsp?.id;
      const labelEl = document.getElementById("rr-cushion-rec");
      if (!dspId || !labelEl) return;
      const since = new Date(); since.setDate(since.getDate() - 30);
      const sinceIso = since.toISOString().slice(0, 10);
      const [scheduledRes, absentRes] = await Promise.all([
        sb.from("shifts").select("id", { count: "exact", head: true })
          .eq("dsp_id", dspId).gte("date", sinceIso)
          .in("status", ["scheduled", "completed", "called_off", "no_show"]),
        sb.from("shifts").select("id", { count: "exact", head: true })
          .eq("dsp_id", dspId).gte("date", sinceIso)
          .in("status", ["called_off", "no_show"]),
      ]);
      if (scheduledRes.error || absentRes.error) return;
      const total = scheduledRes.count || 0;
      const absences = absentRes.count || 0;
      const rate = total > 0 ? (absences / total * 100) : 0;
      // Inline absence rate hint inside the Cushion field's help line.
      // The span lives in the help text and just shows informational
      // rate; no longer a button.
      labelEl.textContent = total > 0
        ? ` · ${rate.toFixed(1)}% absence last 30d`
        : "";
      labelEl.title = total > 0
        ? `${absences} callouts + no-shows over ${total} scheduled shifts`
        : "";
    } catch (e) {
      console.warn("attendance rate label:", e);
    }
  })();
  const overrideEl = document.getElementById("rr-set-availability-override");
  if (overrideEl) overrideEl.checked = !!s.allow_availability_override;
  const tbEl = document.getElementById("rr-set-pref-tiebreaker");
  if (tbEl) tbEl.value = ["least_loaded","seniority","fairness"].includes(s.preference_tiebreaker) ? s.preference_tiebreaker : "least_loaded";
  // Fill order — rotational/sequential lives in the Smart Fill rules store
  // (as spread_evenly), surfaced here in Targets → Advanced settings.
  const foEl = document.getElementById("rr-set-fill-order");
  if (foEl) {
    const sf = (typeof window._rrLoadSfRules === "function") ? window._rrLoadSfRules() : {};
    foEl.value = sf.spread_evenly === false ? "sequential" : "rotational";
    const rbEl = document.getElementById("rr-set-rotation-batch");
    if (rbEl) {
      const rb = Math.max(1, Math.min(4, parseInt(sf.rotation_batch, 10) || 1));
      rbEl.value = String(rb);
    }
    const fpEl = document.getElementById("rr-set-fill-priority");
    if (fpEl) fpEl.value = sf.fill_priority === "random" ? "random" : "seniority";
    const rsEl = document.getElementById("rr-set-rotation-start-day");
    if (rsEl) rsEl.value = String(Math.max(0, Math.min(6, parseInt(sf.rotation_start_day, 10) || 0)));
    if (typeof _syncFillOrderUI === "function") _syncFillOrderUI();
  }
  // Cache the effective settings so auto-assign reads the per-week values.
  window._rrEffectiveSettings = s;
  if (wavesEl) {
    const waves = Array.isArray(s.waves) && s.waves.length ? s.waves : [{ start: "07:00" }];
    wavesEl.innerHTML = waves.map(w => _renderWaveRow(w.start)).join("");
  }
  // Cache finalized state for guard checks.
  window._rrWeekFinalized = !!s.finalized;
  _updateFinalizeButton();
  if (statusEl) {
    statusEl.style.color = "var(--text-subtle)";
    statusEl.textContent = s.is_inherited
      ? "Inherited from a previous week — Save to make this week's settings independent"
      : `Custom settings for week of ${_schedStart}`;
  }
  _rrPaintDefaultHints(s);
  loadServiceTypes();
}

// ─── Per-week drawer · DSP default hints ─────────────────────────────
// For each settings field, show a small amber line under the help text
// when the visible week overrides the DSP-wide default — e.g.
// "Overrides DSP default of 10h". Stays hidden when the value matches,
// so the form reads clean by default and only surfaces deviations.
// Reacts live to input/change so operators see the hint flip as they
// type before they save.
const _rrTiebreakerLabel = {
  least_loaded: "Fewest shifts so far",
  seniority:    "Most senior",
  fairness:     "Least recently honored",
};
function _rrPaintDefaultHints(s) {
  if (!s || !s.defaults) return;
  const D = s.defaults;
  const fields = [
    { id: "rr-set-block-hours",             get: el => parseInt(el.value, 10) || 0,                                def: parseInt(D.default_block_hours, 10) || 10,                           fmt: v => `${v}h` },
    { id: "rr-set-cushion-pct",             get: el => Math.round(parseFloat(el.value) || 0),                      def: Math.round(parseFloat(D.cushion_pct) || 0),                          fmt: v => `${v}%` },
    { id: "rr-set-max-days",                get: el => parseInt(el.value, 10) || 0,                                def: parseInt(D.max_days_per_week, 10) || 5,                              fmt: v => `${v} ${v === 1 ? "day" : "days"}` },
    { id: "rr-set-report-lead",             get: el => parseInt(el.value, 10) || 0,                                def: parseInt(D.report_lead_minutes, 10) || 0,                            fmt: v => `${v} min` },
    { id: "rr-set-availability-override",   get: el => !!el.checked,                                               def: !!D.allow_availability_override,                                     fmt: v => v ? "on" : "off" },
    { id: "rr-set-pref-tiebreaker",         get: el => el.value,                                                   def: D.preference_tiebreaker || "least_loaded",                           fmt: v => _rrTiebreakerLabel[v] || v },
  ];
  fields.forEach(f => {
    const el = document.getElementById(f.id);
    const hint = document.querySelector(`[data-rr-default-for="${f.id}"]`);
    if (!el || !hint) return;
    const cur = f.get(el);
    if (cur === f.def) {
      hint.hidden = true;
      hint.textContent = "";
      return;
    }
    hint.hidden = false;
    hint.style.fontSize  = "11px";
    hint.style.color     = "var(--amber, #b45309)";
    hint.style.marginTop = "2px";
    hint.textContent = `Overrides DSP default of ${f.fmt(f.def)}`;
  });
}
document.addEventListener("input", (e) => {
  if (!e.target?.closest?.("#sched-sub-settings")) return;
  if (window._rrEffectiveSettings) _rrPaintDefaultHints(window._rrEffectiveSettings);
});
document.addEventListener("change", (e) => {
  if (!e.target?.closest?.("#sched-sub-settings")) return;
  if (window._rrEffectiveSettings) _rrPaintDefaultHints(window._rrEffectiveSettings);
});

let _okamiServiceTypes = null;
async function loadServiceTypes() {
  const wrap = document.getElementById("rr-set-service-types");
  const { data, error } = await sb.rpc("list_service_types");
  if (error) {
    if (wrap) wrap.innerHTML = `<div style="font-size:var(--fs-xs);color:var(--red)">Failed to load: ${escapeHtml(error.message)}</div>`;
    return;
  }
  const types = data || [];
  _okamiServiceTypes = types;
  if (!wrap) return;
  // EDV / Step Van are vehicle types, not service types (Van type lives on
  // the vehicle now), so hide them from the Service Types manager. The rows
  // stay in the DB (and in _okamiServiceTypes) so nothing referencing them
  // breaks — they're just not shown/editable here.
  wrap.innerHTML = types
    .filter(t => !["EDV", "STEP"].includes(String(t.code || "").toUpperCase()))
    .map(t => `
    <div data-rr-st="${t.id}" class="rr-drawer-st-row">
      <label class="rr-toggle" title="Active in OKAMI">
        <input type="checkbox" data-rr-st-active ${t.active ? "checked" : ""}/>
        <span class="rr-toggle-track"><span class="rr-toggle-thumb"></span></span>
      </label>
      <span class="rr-drawer-st-dot" style="background:${escapeHtml(t.color)}"></span>
      <span class="rr-drawer-st-code">${escapeHtml(t.code)}</span>
      <input type="text" data-rr-st-label class="rr-drawer-st-label" value="${escapeHtml(t.label)}"/>
    </div>`).join("");
}

function _renderWaveRow(start) {
  return `<div data-rr-wave class="rr-drawer-wave-row">
    <input type="time" class="form-input" data-rr-wave-time value="${escapeHtml(start || "07:00")}"/>
    <button type="button" class="rr-drawer-wave-remove" data-rr-remove-wave title="Remove" aria-label="Remove wave">
      <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
    </button>
  </div>`;
}

// Service type: toggle active. Refreshes OKAMI rendering since the
// per-(wave × type) row count is driven by the active-type list.
document.addEventListener("change", async (e) => {
  const cb = e.target.closest?.("[data-rr-st-active]");
  if (cb) {
    const row = cb.closest("[data-rr-st]");
    const id = row?.dataset.rrSt;
    if (!id) return;
    const { error } = await sb.rpc("set_service_type", { p_id: id, p_active: cb.checked });
    if (error) { toast("Save failed: " + error.message, "warn"); cb.checked = !cb.checked; return; }
    _okamiServiceTypes = null; // bust cache so OKAMI re-renders with the new active set
    if (typeof renderOkamiLive === "function") renderOkamiLive();
    const openIdx = openOkamiDetailIndex?.();
    if (openIdx != null) renderOkamiDailyPanel(openIdx);
    toast(`${cb.checked ? "Activated" : "Deactivated"} ${row.querySelector("strong")?.textContent || "type"}`, "success");
  }
});

// Service type: rename label on blur.
document.addEventListener("blur", async (e) => {
  const inp = e.target.closest?.("[data-rr-st-label]");
  if (!inp) return;
  const row = inp.closest("[data-rr-st]");
  const id = row?.dataset.rrSt;
  if (!id) return;
  const newLabel = (inp.value || "").trim();
  if (!newLabel) return;
  const { error } = await sb.rpc("set_service_type", { p_id: id, p_label: newLabel });
  if (error) toast("Save failed: " + error.message, "warn");
}, true);

document.addEventListener("click", async (e) => {
  // Add a wave row.
  if (e.target.id === "rr-set-add-wave") {
    e.preventDefault();
    const wavesEl = document.getElementById("rr-set-waves");
    if (!wavesEl) return;
    // Suggest the next slot 25 min after the last wave.
    const lastInput = wavesEl.querySelector("[data-rr-wave]:last-child [data-rr-wave-time]");
    let next = "07:00";
    if (lastInput?.value) {
      const [h, m] = lastInput.value.split(":").map(n => parseInt(n, 10));
      const total = h * 60 + m + 25;
      next = `${String(Math.floor(total / 60) % 24).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
    }
    wavesEl.insertAdjacentHTML("beforeend", _renderWaveRow(next));
    return;
  }

  // Remove a wave row. closest() instead of matches() so clicks on
  // the inner SVG icon bubble up to the button correctly.
  // stopImmediatePropagation() is critical here — once the row is
  // removed from the DOM the click target is detached, and a
  // sibling document-level click listener (the "click outside
  // popover closes it" guard for #rr-sched-quick-settings-popover)
  // would see closest("#rr-sched-quick-settings-popover") return
  // null and close the popover. stopPropagation() alone doesn't
  // stop other listeners on the same node.
  if (e.target.closest?.("[data-rr-remove-wave]")) {
    e.preventDefault();
    e.stopImmediatePropagation();
    const row = e.target.closest("[data-rr-wave]");
    if (row) row.remove();
    return;
  }

  // Save scheduling settings (Save button inside the drawer).
  if (e.target.id === "rr-set-sched-save") {
    e.preventDefault();
    await _saveScheduleSettings({ source: "drawer" });
    return;
  }
});

// Persist the visible week's scheduling settings + regenerate the
// week's shifts. Pulled out of the inline click handler so the new
// nav-bar settings cluster can call the same flow on auto-save.
async function _saveScheduleSettings({ source = "drawer" } = {}) {
  const dspId = window.RR?.dsp?.id;
  if (!dspId) return { ok: false, error: "DSP not loaded" };
  if (!_schedStart) _schedStart = fmtIsoDate(startOfWeekMonday(new Date()));

  const block = parseInt(document.getElementById("rr-set-block-hours")?.value, 10) || 10;
  const cushion = parseInt(document.getElementById("rr-set-cushion-pct")?.value, 10) || 0;
  const maxDaysRaw = parseInt(document.getElementById("rr-set-max-days")?.value, 10);
  const maxDays = Math.max(0, Math.min(7, Number.isFinite(maxDaysRaw) ? maxDaysRaw : 5));
  const reportLead = Math.max(0, Math.min(120, parseInt(document.getElementById("rr-set-report-lead")?.value, 10) || 0));
  const allowOverride = !!document.getElementById("rr-set-availability-override")?.checked;
  const waves = Array.from(document.querySelectorAll("#rr-set-waves [data-rr-wave-time]"))
    .map(inp => ({ start: inp.value || "07:00" }))
    .filter(w => w.start);
  if (waves.length === 0) waves.push({ start: "07:00" });
  const tz = (Intl?.DateTimeFormat?.().resolvedOptions().timeZone) || "UTC";

  const status = document.getElementById("rr-set-sched-status");
  const ws = _schedStart;
  if (status) { status.style.color = "var(--text-subtle)"; status.textContent = `Saving settings for week of ${ws}…`; }

  const prefTiebreaker = (() => {
    const v = document.getElementById("rr-set-pref-tiebreaker")?.value;
    return ["least_loaded","seniority","fairness"].includes(v) ? v : "least_loaded";
  })();
  const payload = {
    week_start: ws,
    default_block_hours: block,
    cushion_pct: cushion,
    max_days_per_week: maxDays,
    allow_availability_override: allowOverride,
    report_lead_minutes: reportLead,
    preference_tiebreaker: prefTiebreaker,
    waves,
    timezone: tz,
  };

  let cushionDelta = 0;
  let failed = null;

  const { error: upErr } = await sb.rpc("upsert_scheduling_settings", { p_payload: payload });
  if (upErr) { failed = upErr.message; }

  if (!failed) {
    _markLocalShiftMutation();
    const { error: regenErr } = await sb.rpc("regenerate_week_shifts", { p_week_start: ws });
    if (regenErr) { failed = regenErr.message; }
  }

  if (!failed) {
    try {
      const { data, error: cushionErr } = await sb.rpc("apply_cushion_to_week", { p_week_start: ws });
      if (cushionErr) console.warn(`apply_cushion_to_week (${ws}):`, cushionErr.message);
      else cushionDelta = data || 0;
    } catch (e) {
      console.warn(`apply_cushion_to_week (${ws}) threw:`, e);
    }
  }

  if (failed) {
    if (status) { status.style.color = "var(--red)"; status.textContent = "Failed: " + failed; }
    if (source !== "nav") toast("Settings save failed: " + failed, "warn");
    return { ok: false, error: failed };
  }

  if (status) {
    status.style.color = "var(--green)";
    const cushionNote = cushionDelta !== 0 ? ` · cushion ${cushionDelta > 0 ? "+" : ""}${cushionDelta}` : "";
    status.textContent = `Saved for week of ${ws} ✓${cushionNote}`;
  }
  setTimeout(() => { if (status) status.textContent = ""; }, 3000);
  if (source !== "nav") toast(`Scheduling settings saved for week of ${ws}`, "success");

  // Refresh schedule view if active.
  if (typeof renderScheduleWeek === "function") {
    const sub = document.getElementById("sched-sub-week");
    if (sub) renderScheduleWeek();
  }
  // Reload settings panel so the inheritance hint updates. Only
  // close the drawer when the save came from the drawer button —
  // nav-bar auto-saves should leave the drawer state alone.
  loadSchedulingSettings();
  if (source === "drawer") closeSchedSettingsDrawer();
  return { ok: true, cushionDelta };
}

// ─── Schedule · navigation-heading settings auto-save ────────────────
// Block / Cushion / Max days / Report time now live in the nav strip.
// Changes there should trigger the same RPC chain as the drawer's
// Save button. Debounced so a rapid spinner click doesn't hit the
// regenerate endpoint several times in a row.
let _navSettingsSaveTimer = null;
const _NAV_SETTING_IDS = new Set([
  "rr-set-block-hours",
  "rr-set-cushion-pct",
  "rr-set-max-days",
  "rr-set-report-lead",
]);
function _flashNavStatus(msg, color) {
  const el = document.getElementById("rr-sched-nav-settings-status");
  if (!el) return;
  el.style.color = color || "var(--text-subtle)";
  el.textContent = msg;
}
async function _navSettingsTriggerSave(inputEl) {
  if (inputEl) inputEl.dataset.rrSaving = "1";
  _flashNavStatus("Saving…", "var(--text-subtle)");
  const res = await _saveScheduleSettings({ source: "nav" });
  if (inputEl) {
    delete inputEl.dataset.rrSaving;
    if (res?.ok) {
      inputEl.dataset.rrSaved = "1";
      setTimeout(() => { delete inputEl.dataset.rrSaved; }, 1400);
    } else {
      inputEl.dataset.rrError = "1";
      setTimeout(() => { delete inputEl.dataset.rrError; }, 2200);
    }
  }
  if (res?.ok) {
    const note = res.cushionDelta && res.cushionDelta !== 0
      ? `Saved · cushion ${res.cushionDelta > 0 ? "+" : ""}${res.cushionDelta}`
      : "Saved ✓";
    _flashNavStatus(note, "var(--green)");
    setTimeout(() => { _flashNavStatus("", ""); }, 1800);
  } else {
    _flashNavStatus(res?.error || "Save failed", "var(--red)");
    setTimeout(() => { _flashNavStatus("", ""); }, 3000);
  }
}
document.addEventListener("input", (e) => {
  const input = e.target;
  if (!input || !input.id || !_NAV_SETTING_IDS.has(input.id)) return;
  // rr-set-max-days now lives in the Smart Fill rules popover; the other
  // nav settings stay in the Targets quick-settings popover.
  if (!input.closest("#rr-sched-quick-settings-popover, #rr-sched-smartfill-rules-popover")) return;
  // Mirror the popover input into the OKAMI page's twin so both
  // surfaces stay live-in-sync when the operator has them both open.
  _rrMirrorPopoverToOkami(input.id);
  if (_navSettingsSaveTimer) clearTimeout(_navSettingsSaveTimer);
  _flashNavStatus("Editing…", "var(--text-subtle)");
  _navSettingsSaveTimer = setTimeout(() => {
    _navSettingsSaveTimer = null;
    _navSettingsTriggerSave(input);
  }, 800);
});
document.addEventListener("change", (e) => {
  // Cover the case where the user uses arrow keys / spinner without
  // triggering an `input` event in some browsers.
  const input = e.target;
  if (!input || !input.id || !_NAV_SETTING_IDS.has(input.id)) return;
  // rr-set-max-days now lives in the Smart Fill rules popover; the other
  // nav settings stay in the Targets quick-settings popover.
  if (!input.closest("#rr-sched-quick-settings-popover, #rr-sched-smartfill-rules-popover")) return;
  _rrMirrorPopoverToOkami(input.id);
  if (_navSettingsSaveTimer) clearTimeout(_navSettingsSaveTimer);
  _navSettingsSaveTimer = null;
  _navSettingsTriggerSave(input);
});

// ─── Targets-rules toolbar · three-surface mirror ─────────────────
// The Block / Cushion / Report-time inputs live on THREE surfaces now:
//   1. #rr-sched-quick-settings-popover  · the schedule ribbon shortcut
//   2. OKAMI page header  · rr-okami-set-*
//   3. Schedule's Targets sub-view  · rr-sched-targets-*
// All three read from scheduling_settings_for_week (per-week) and
// write through _saveScheduleSettings({ source: "nav" }), so they
// share one backing row. Each surface keeps its own input IDs (no
// DOM collisions) and the mirror keeps every twin in lock-step with
// whichever one the operator is editing. The popover input remains
// the canonical read source for _saveScheduleSettings so its value
// must stay authoritative whenever a twin changes.
const _RR_SETTING_TRIPLES = [
  // [popover, okami page, targets sub-view]
  ["rr-set-block-hours",  "rr-okami-set-block-hours",  "rr-sched-targets-block-hours"],
  ["rr-set-cushion-pct",  "rr-okami-set-cushion-pct",  "rr-sched-targets-cushion-pct"],
  ["rr-set-report-lead",  "rr-okami-set-report-lead",  "rr-sched-targets-report-lead"],
];
const _RR_OKAMI_SETTING_IDS = new Set(_RR_SETTING_TRIPLES.map(t => t[1]));
const _RR_TARGETS_SUB_SETTING_IDS = new Set(_RR_SETTING_TRIPLES.map(t => t[2]));
// id → [pop, okami, targetsSub] lookup so any input change can find
// its two twins by triple-membership in one pass.
const _RR_SETTING_TRIPLE_BY_ID = new Map();
for (const triple of _RR_SETTING_TRIPLES) {
  for (const id of triple) _RR_SETTING_TRIPLE_BY_ID.set(id, triple);
}

// Push a freshly-edited input's value into both of its twins so all
// three surfaces stay live-in-sync regardless of which one the
// operator was typing into. Safe to call when twins aren't mounted
// (e.g. OKAMI page never opened this session) — missing nodes are
// just skipped.
function _rrMirrorSettingTriple(sourceId) {
  const triple = _RR_SETTING_TRIPLE_BY_ID.get(sourceId);
  if (!triple) return;
  const src = document.getElementById(sourceId);
  if (!src) return;
  for (const id of triple) {
    if (id === sourceId) continue;
    const dst = document.getElementById(id);
    if (dst && dst.value !== src.value) dst.value = src.value;
  }
}
// Back-compat aliases · earlier code paths reference the two-way
// helpers by name. Each one forwards into the new three-surface
// mirror so existing callers keep working without change.
function _rrMirrorPopoverToOkami(popId) { _rrMirrorSettingTriple(popId); }
function _rrMirrorOkamiToPopover(okId)  { _rrMirrorSettingTriple(okId); }

let _okamiSettingsSaveTimer = null;
function _flashOkamiTargetsStatus(msg, color) {
  // Write the same status into both the OKAMI page toolbar and the
  // schedule's Targets sub-view toolbar so whichever one the
  // operator is looking at sees the Editing… / Saved feedback.
  for (const id of ["rr-okami-targets-rules-status", "rr-sched-targets-rules-status"]) {
    const el = document.getElementById(id);
    if (!el) continue;
    el.style.color = color || "var(--text-subtle)";
    el.textContent = msg;
  }
}
async function _okamiSettingsTriggerSave(inputEl) {
  if (inputEl) inputEl.dataset.rrSaving = "1";
  _flashOkamiTargetsStatus("Saving…", "var(--text-subtle)");
  const res = await _saveScheduleSettings({ source: "nav" });
  if (inputEl) {
    delete inputEl.dataset.rrSaving;
    if (res?.ok) {
      inputEl.dataset.rrSaved = "1";
      setTimeout(() => { delete inputEl.dataset.rrSaved; }, 1400);
    } else {
      inputEl.dataset.rrError = "1";
      setTimeout(() => { delete inputEl.dataset.rrError; }, 2200);
    }
  }
  if (res?.ok) {
    _flashOkamiTargetsStatus("Saved", "var(--green)");
    setTimeout(() => { _flashOkamiTargetsStatus("", ""); }, 1800);
  } else {
    _flashOkamiTargetsStatus(res?.error || "Save failed", "var(--red)");
    setTimeout(() => { _flashOkamiTargetsStatus("", ""); }, 3000);
  }
}
// Edit listener for the OKAMI page + Targets sub-view twins of the
// popover settings. Mirrors back to the popover (canonical) +
// triggers the same save path as the popover would.
document.addEventListener("input", (e) => {
  const input = e.target;
  if (!input || !input.id) return;
  if (!_RR_OKAMI_SETTING_IDS.has(input.id)
      && !_RR_TARGETS_SUB_SETTING_IDS.has(input.id)) return;
  _rrMirrorSettingTriple(input.id);
  if (_okamiSettingsSaveTimer) clearTimeout(_okamiSettingsSaveTimer);
  _flashOkamiTargetsStatus("Editing…", "var(--text-subtle)");
  _okamiSettingsSaveTimer = setTimeout(() => {
    _okamiSettingsSaveTimer = null;
    _okamiSettingsTriggerSave(input);
  }, 800);
});
document.addEventListener("change", (e) => {
  const input = e.target;
  if (!input || !input.id) return;
  if (!_RR_OKAMI_SETTING_IDS.has(input.id)
      && !_RR_TARGETS_SUB_SETTING_IDS.has(input.id)) return;
  _rrMirrorSettingTriple(input.id);
  if (_okamiSettingsSaveTimer) clearTimeout(_okamiSettingsSaveTimer);
  _okamiSettingsSaveTimer = null;
  _okamiSettingsTriggerSave(input);
});
// Escape closes the quick-settings popover.
document.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  const pop = document.getElementById("rr-sched-quick-settings-popover");
  if (pop && !pop.hidden) {
    _toggleSchedQuickSettings(false);
  }
});

// ─── Schedule · Settings drawer ────────────────────────────────────────
// Settings used to be a full sub-tab under Schedule. It lives next to
// the calendar now: a gear button in the Week-view toolbar opens this
// drawer, and the existing inline "go to settings" links route here
// too.
function openSchedSettingsDrawer() {
  const drawer = document.getElementById("sched-sub-settings");
  const back   = document.getElementById("rr-sched-settings-backdrop");
  if (!drawer || !back) return;
  drawer.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  back.classList.add("open");
  // Refresh form values against the visible week.
  if (typeof loadSchedulingSettings === "function") loadSchedulingSettings();
}
function closeSchedSettingsDrawer() {
  const drawer = document.getElementById("sched-sub-settings");
  const back   = document.getElementById("rr-sched-settings-backdrop");
  if (drawer) { drawer.classList.remove("open"); drawer.setAttribute("aria-hidden", "true"); }
  if (back)   back.classList.remove("open");
}
window.openSchedSettingsDrawer  = openSchedSettingsDrawer;
window.closeSchedSettingsDrawer = closeSchedSettingsDrawer;

// ─── Schedule · OKAMI overlay ───────────────────────────────────────
// Route planning used to be a separate Schedule sub-tab that called
// goto('okami'). Operators wanted it to live with the week they were
// editing, "kinda like Settings does." A new "Route planning" button
// in the Week-view toolbar opens #view-okami as a full-screen overlay
// anchored on the visible week (_schedStart), instead of always
// rolling forward to "this week + 12".
async function openOkamiOverlay() {
  const okami = document.getElementById("view-okami");
  if (!okami) return;
  // Anchor OKAMI on the week the operator is editing. _renderOkamiLiveImpl
  // reads this override on its next call and clears it.
  if (typeof _schedStart === "string" && _schedStart) {
    window._rrOkamiAnchorOverride = _schedStart;
  }

  // Update the page title BEFORE making the overlay visible. If we
  // add the overlay class first, the operator sees a brief flash of
  // the default "OKAMI" title before our setter swaps it to
  // "Route planning · week of Mon, May 4". Order matters.
  const titleEl = document.getElementById("rr-okami-page-title");
  if (titleEl && typeof _schedStart === "string" && _schedStart) {
    const d = new Date(_schedStart + "T12:00:00");
    const lbl = d.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" });
    titleEl.textContent = `Route planning · week of ${lbl}`;
  }

  okami.classList.add("rr-okami-overlay");
  const backdrop = document.getElementById("rr-okami-backdrop");
  if (backdrop) backdrop.classList.add("open");

  // Wait for OKAMI to render the 13-week table, then auto-expand
  // week-0's detail panel — that's the daily route-planning editor
  // and the only thing the overlay shows (CSS hides every other
  // row). Without this, the operator opens the overlay and sees an
  // empty white page.
  if (typeof loadOkamiView === "function") {
    try { await loadOkamiView(); } catch (e) { console.warn("OKAMI overlay load:", e); }
  }
  if (typeof window.okamiToggleDaily === "function") {
    const detail = document.getElementById("okami-detail-0");
    if (detail && !detail.classList.contains("open")) {
      window.okamiToggleDaily(0);
    } else if (typeof window.renderOkamiDailyPanel === "function") {
      // Already open from a prior session — just refresh content
      // against the new anchor week.
      window.renderOkamiDailyPanel(0);
    }
  }
}
function closeOkamiOverlay() {
  const okami = document.getElementById("view-okami");
  if (okami) okami.classList.remove("rr-okami-overlay");
  const backdrop = document.getElementById("rr-okami-backdrop");
  if (backdrop) backdrop.classList.remove("open");
  // Restore the strategic page title for the next time someone
  // navigates to OKAMI through any non-overlay path.
  const titleEl = document.getElementById("rr-okami-page-title");
  if (titleEl) {
    titleEl.innerHTML = `OKAMI <span class="rr-okami-13week-badge" style="font-size:var(--fs-xs);font-weight:500;color:var(--text-subtle);background:var(--canvas);border:1px solid var(--border);padding:3px 8px;border-radius:var(--r-md);margin-left:8px;letter-spacing:0;text-transform:none;vertical-align:middle" title="Amazon's term for the 13-week DSP route plan horizon">13-week plan</span>`;
  }
}
window.openOkamiOverlay  = openOkamiOverlay;
window.closeOkamiOverlay = closeOkamiOverlay;

// Close the OKAMI overlay when the operator navigates to a different
// sidebar view, so it doesn't sit on top of an unrelated screen.
const _origGotoForOkamiOverlay = window.goto;
window.goto = function (view) {
  // Pull the OKAMI 13-week table back into #view-okami before any
  // okami / schedule navigation — both surfaces need it home.
  if (view === "okami") _rrReturnOkami13WeekHome();
  // Leaving the schedule view entirely · return the wave/service-type editor
  // to the quick-settings popover so the popover is intact next time it opens
  // (schedSub handles placement while staying within the schedule view).
  if (view !== "schedule" && typeof _rrReturnSchedDemandHome === "function") _rrReturnSchedDemandHome();
  if (view !== "schedule" && typeof _rrReturnChromeHome === "function") _rrReturnChromeHome();
  // Entering Schedule: reclaim the bell if Fleet borrowed it (the
  // generic return above only runs for non-schedule destinations).
  if (view === "schedule" && typeof _rrReturnChromeHome === "function") {
    const bell = document.getElementById("rr-hdr-notif");
    if (bell && bell.closest("#rr-fleet-chrome-host")) _rrReturnChromeHome();
  }
  if (typeof _origGotoForOkamiOverlay === "function") _origGotoForOkamiOverlay(view);
  if (view !== "schedule" && view !== "okami") closeOkamiOverlay();
};

// ─── OKAMI 13-week table · shared between #view-okami and the
//     Schedule → Targets sub-view. Operators wanted the strategic
//     13-week view back on the Targets page; instead of cloning the
//     table (and its bindings) we move the live `.plan-table-wrap`
//     between the two surfaces so there's a single source of truth.
//     Edits to route inputs, daily-detail expands, recalcOkami() all
//     keep working because the DOM is identical — only its parent
//     changes.
function _rrReturnOkami13WeekHome() {
  const okami = document.getElementById("view-okami");
  if (!okami) return;
  const wrap = document.querySelector(".plan-table-wrap");
  if (!wrap) return;
  // Already home if its parent is the .page inside #view-okami.
  if (okami.contains(wrap)) return;
  const homeAnchor = okami.querySelector(".page");
  if (homeAnchor) homeAnchor.appendChild(wrap);
}
function _rrMoveOkami13WeekToTargets() {
  const host = document.getElementById("rr-sched-targets-13week-host");
  if (!host) return;
  const wrap = document.querySelector(".plan-table-wrap");
  if (!wrap) return;
  if (host.contains(wrap)) return;
  host.innerHTML = "";
  host.appendChild(wrap);
}
window._rrReturnOkami13WeekHome      = _rrReturnOkami13WeekHome;
window._rrMoveOkami13WeekToTargets   = _rrMoveOkami13WeekToTargets;

// ─── Route-demand editor · shared between the quick-settings popover and
//     the Schedule → Targets sub-view's "Wave times" / "Service types" pill
//     dropdowns. Same single-source-of-truth move as the 13-week table: we
//     relocate the LIVE editor sections instead of cloning them, so every
//     existing handler (add/remove wave, service toggle/rename, Save) keeps
//     working — the DOM is identical, only its parent changes. The wave
//     section + Save foot go into the Wave-times dropdown; the service-type
//     section goes into the Service-types dropdown. On exit they're
//     re-assembled into `.sched-quick-advanced` (the popover's home wrapper)
//     in their original order. Save reads the block/cushion/report twins
//     (kept in sync by the three-surface mirror) plus #rr-set-waves by id, so
//     it persists correctly from either home.
function _rrSchedDemandParts() {
  const waveSec = document.getElementById("rr-set-waves")?.closest(".rr-drawer-section") || null;
  const stSec   = document.getElementById("rr-set-service-types")?.closest(".rr-drawer-section") || null;
  const foot    = document.querySelector(".sched-quick-advanced-foot") || null;
  return { waveSec, stSec, foot };
}
function _rrReturnSchedDemandHome() {
  const adv = document.querySelector(".sched-quick-advanced");
  if (!adv) return;
  const { waveSec, stSec, foot } = _rrSchedDemandParts();
  // Re-assemble in the popover's original child order: waves, service types, foot.
  if (waveSec && waveSec.parentElement !== adv) adv.appendChild(waveSec);
  if (stSec   && stSec.parentElement   !== adv) adv.appendChild(stSec);
  if (foot    && foot.parentElement    !== adv) adv.appendChild(foot);
  // Collapse the Targets dropdowns so they don't reopen stale next visit.
  for (const id of ["rr-tgt-waves-menu", "rr-tgt-st-menu"]) {
    const m = document.getElementById(id); if (m) m.hidden = true;
  }
  for (const id of ["rr-tgt-waves-btn", "rr-tgt-st-btn"]) {
    const b = document.getElementById(id); if (b) b.setAttribute("aria-expanded", "false");
  }
}
function _rrMoveSchedDemandToTargets() {
  const wavesHost = document.getElementById("rr-sched-targets-waves-host");
  const stHost    = document.getElementById("rr-sched-targets-st-host");
  if (!wavesHost || !stHost) return;
  const { waveSec, stSec, foot } = _rrSchedDemandParts();
  if (waveSec && !wavesHost.contains(waveSec)) wavesHost.appendChild(waveSec);
  if (foot    && !wavesHost.contains(foot))    wavesHost.appendChild(foot);   // Save under the waves
  if (stSec   && !stHost.contains(stSec))       stHost.appendChild(stSec);
}
window._rrReturnSchedDemandHome    = _rrReturnSchedDemandHome;
window._rrMoveSchedDemandToTargets = _rrMoveSchedDemandToTargets;

// ─── Targets toolbar · Gap status card + Save Plan + relocated chrome ──────
// Gap card mirrors the Schedule Coverage card: shows the largest weekly driver
// shortfall across the 13-week plan (worst = most-negative gap), red when short
// and green when covered. Reads the rendered gap cells so it stays in lockstep
// with the table without re-deriving the math.
function _rrRefreshTargetsGapCard() {
  const card = document.getElementById("rr-tgt-gap-card");
  if (!card) return;
  // Read through _rrReadOkamiWeeks (the same parser the Risk Forecast view
  // uses) instead of scraping .plan-gap cells directly: it folds in the
  // 13-week simulation's PTO-adjusted availability, so the card agrees
  // with the projection after the operator runs Simulate.
  let weeks = [];
  try { weeks = (_rrReadOkamiWeeks() || []).filter((w) => Number.isFinite(w.gap)); } catch (_) {}
  if (!weeks.length) { card.hidden = true; return; }
  // Shared forecast-core assessment (same one the Risk Forecast renders
  // from): effective supply + hire-by reachability. Rates load lazily and
  // this card repaints when they land.
  _rrEnsureForecastRates();
  let A = null;
  try { A = _rrAssessOkamiPlan(weeks); } catch (_) {}
  if (!A || !A.worstWeek) { card.hidden = true; return; }
  const worst = A.worstWeek.gap;
  card.hidden = false;
  const mainEl = document.getElementById("rr-tgt-gap-card-main");
  if (mainEl) mainEl.textContent = `${worst > 0 ? "+" : ""}${worst} Driver${Math.abs(worst) === 1 ? "" : "s"}`;
  card.classList.toggle("rr-tgt-gap-card--pos", worst >= 0);
  // Prescription line — the one action the number implies. Hire count =
  // deepest shortfall among weeks hiring can still reach (one hire fills a
  // seat in every later week, so weekly gaps are never summed); deadline =
  // the earliest reachable hire-by. Once every short week is inside the
  // hire lead time, "hire by <past date>" would be fiction — say what's
  // actually left: mitigation.
  const subEl = document.getElementById("rr-tgt-gap-card-sub");
  const rx = A.prescription;
  const fmtIsoShort = (iso) => (iso ? fmtMD(new Date(iso + "T12:00:00")) : "");
  if (subEl) {
    if (rx.action === "hire") {
      // FT/PT split rides along when the flex engine has already scored the
      // first reachable week (cache-only — the card never fetches flex).
      let split = "";
      const flexData = rx.firstReachable && rx.firstReachable.weekStartIso
        ? _rrFlexBaseCached(rx.firstReachable.weekStartIso) : null;
      const wi = flexData && flexData.whatIf;
      if (wi && wi.driversNeeded > 0) split = ` (${wi.recommendedFtHires} FT + ${wi.recommendedPtHires} PT)`;
      // Upper-funnel enrichment · when the planning payload is already
      // cached, extend "Hire N" into the application quota it implies.
      // Cold cache: kick the fetch and repaint this card once it lands
      // (the fetch memoizes, so the repaint's re-entry takes the warm
      // path and can't loop). Skipped when the line already carries the
      // OT/flex tail — three clauses won't fit the card.
      let appsSuffix = "";
      if (!rx.unreachable.length && typeof _rrUpperFunnelMath === "function") {
        if (_rrHiringPlanCache) {
          const m = _rrUpperFunnelMath(_rrHiringPlanCache.data);
          const unsourced = Math.max(0, Math.ceil(rx.hires - m.expectedHires));
          if (unsourced > 0) appsSuffix = ` · ≈${_rrUfAppsNeeded(unsourced, m.e2ePct).toLocaleString()} apps`;
        } else {
          _rrFetchHiringPlanning().then(() => { try { _rrRefreshTargetsGapCard(); } catch (_) {} });
        }
      }
      subEl.textContent = rx.unreachable.length
        ? `Hire ${rx.hires}${split} by ${fmtIsoShort(rx.deadlineIso)} · ${rx.unreachable.length} wk${rx.unreachable.length === 1 ? "" : "s"} need OT/flex`
        : `Hire ${rx.hires}${split} by ${fmtIsoShort(rx.deadlineIso)}` + appsSuffix;
    } else if (rx.action === "mitigate") {
      subEl.textContent = `Hire window passed — cover ${rx.shortNow} with OT/flex`;
    } else {
      subEl.textContent = "Staffed through the plan";
    }
    subEl.hidden = false;
  }
  // A short plan gets a click-through to the full Risk forecast analysis
  // (per-week narrative, hire-by dates, simulation deltas).
  const clickable = worst < 0 && typeof _rrIntelShow === "function";
  card.classList.toggle("is-clickable", clickable);
  if (clickable) {
    card.setAttribute("role", "button");
    card.setAttribute("tabindex", "0");
    card.title = "Largest weekly driver shortfall — open the Risk forecast analysis";
  } else {
    card.removeAttribute("role");
    card.removeAttribute("tabindex");
    card.title = "Largest weekly driver shortfall across the plan";
  }
}
window._rrRefreshTargetsGapCard = _rrRefreshTargetsGapCard;

// Gap card click-through → Risk forecast intel view (only armed while the
// plan is short; _rrRefreshTargetsGapCard manages the is-clickable state).
document.addEventListener("click", (e) => {
  const card = e.target.closest && e.target.closest("#rr-tgt-gap-card.is-clickable");
  if (!card) return;
  try { _rrIntelShow("risk-forecast"); } catch (_) {}
});
document.addEventListener("keydown", (e) => {
  if (e.key !== "Enter" && e.key !== " ") return;
  const card = e.target.closest && e.target.closest("#rr-tgt-gap-card.is-clickable");
  if (!card) return;
  e.preventDefault();
  try { _rrIntelShow("risk-forecast"); } catch (_) {}
});

// Graduated gap severity for the Targets gap pill: positive = covered (green);
// negative scales light → medium → dark red with the size of the shortfall.
function _rrApplyGapClass(gapEl, gap) {
  if (!gapEl) return;
  gapEl.classList.remove("rr-tgt-gap-pos", "rr-tgt-gap-s1", "rr-tgt-gap-s2", "rr-tgt-gap-s3");
  if (gap >= 0) { gapEl.classList.add("rr-tgt-gap-pos"); return; }
  const m = Math.abs(gap);
  gapEl.classList.add(m <= 10 ? "rr-tgt-gap-s1" : m <= 40 ? "rr-tgt-gap-s2" : "rr-tgt-gap-s3");
}

// Save Plan · Targets auto-saves per week as you type, so this re-commits the
