// All of this is gated on window._rrSmartFillPageMode, so the normal
// caret/popover path is completely unaffected when the page isn't open.
function _rrOpenSmartFillPage() {
  const overlay = document.getElementById("rr-smartfill-page");
  if (!overlay) return;
  const onSched = document.getElementById("view-schedule")?.classList.contains("active");
  if (!onSched && typeof window.goto === "function") window.goto("schedule");
  const open = () => {
    // Cards-free: the full rule list (the re-homed editor) is shown flat on the
    // page with every section expanded. No cards, no reveal popout.
    const detail = document.getElementById("rr-sf-detail");
    const rules = document.getElementById("rr-sched-smartfill-rules-popover");
    const colors = document.getElementById("rr-sched-colors-popover");
    if (detail && rules && rules.parentElement !== detail) detail.appendChild(rules);
    if (detail && colors && colors.parentElement !== detail) detail.appendChild(colors);
    rules && rules.classList.add("rr-as-page");
    colors && colors.classList.add("rr-as-page");
    window._rrSmartFillPageMode = true;
    overlay.hidden = false;
    if (detail) detail.hidden = false; // always visible — no popout
    document.body.classList.add("rr-sf-page-open");
    // Seed + paint the editor (populates every control from the blob).
    try { _toggleSchedSmartFillRules(true); } catch (_) {}
    try { _rrToggleSchedColors(true); } catch (_) {}
    try { _rrPolSeedFromServer(); } catch (_) {}
    try { _rrSfSavedLabel(); } catch (_) {}
    // Expand every section so every rule is visible as plain text.
    if (detail) detail.querySelectorAll("details").forEach((d) => { d.open = true; });
    // Build the "Work Limits" 5-across row from the otherwise-scattered
    // dropdowns (Max consecutive / Max days / 5th day are top rows; Min rest +
    // Stability live in the Advanced bucket). Idempotent — only gathers once.
    try {
      const body = document.getElementById("rr-sched-smartfill-rules-body");
      if (body && !document.getElementById("rr-sf-worklimits")) {
        const head = document.createElement("div");
        head.className = "rr-sf-wl-head";
        head.textContent = "Work Limits";
        const grid = document.createElement("div");
        grid.id = "rr-sf-worklimits";
        grid.className = "rr-sf-wl-grid";
        body.insertBefore(grid, body.firstChild);
        body.insertBefore(head, grid);
        ["rr-pol-consec", "rr-pol-maxdays", "rr-pol-fifth", "rr-pol-rest", "rr-pol-stability"]
          .forEach((id) => {
            const row = document.getElementById(id)?.closest(".rr-pol-row");
            if (row) grid.appendChild(row);
          });
      }
    } catch (_) {}
    // Reflect the active child in the sidebar.
    document.querySelectorAll('.nav-sub[data-for="schedule"] .nav-sub-item')
      .forEach((b) => b.classList.toggle("active", b.dataset.key === "smartfill"));
  };
  onSched ? open() : setTimeout(open, 240);
}
window._rrOpenSmartFillPage = _rrOpenSmartFillPage;

function _rrCloseSmartFillPage() {
  // Clear page mode FIRST so the toggle calls below hide the boxes normally
  // instead of recursing back into this function.
  window._rrSmartFillPageMode = false;
  const overlay = document.getElementById("rr-smartfill-page");
  const ab = document.getElementById("rr-sched-actionbar");
  const detail = document.getElementById("rr-sf-detail");
  const rules = document.getElementById("rr-sched-smartfill-rules-popover");
  const colors = document.getElementById("rr-sched-colors-popover");
  try { _toggleSchedSmartFillRules(false); } catch (_) {}
  try { _rrToggleSchedColors(false); } catch (_) {}
  rules && rules.classList.remove("rr-as-page");
  colors && colors.classList.remove("rr-as-page");
  // Return the boxes to the action bar so the Smart Fill caret reopens them
  // as popovers exactly as before.
  if (ab && rules && rules.parentElement !== ab) ab.appendChild(rules);
  if (ab && colors && colors.parentElement !== ab) ab.appendChild(colors);
  if (detail) detail.hidden = true;
  if (overlay) overlay.hidden = true;
  document.body.classList.remove("rr-sf-page-open");
}
window._rrCloseSmartFillPage = _rrCloseSmartFillPage;

// ── Smart Fill page · overview painters ──────────────────────────────
// Everything below READS the saved policy blob and renders the page's
// overview surfaces (preset-card dropdowns, advanced counts). The dropdowns
// write back through _rrPolApply — the exact same mutation path the detailed
// editor uses — so the page never invents a second source of truth and never
// changes scheduling behavior on its own.

// Paint the preset-card dropdowns from the blob (no events dispatched).
function _rrPaintSmartFillCards() {
  if (!document.getElementById("rr-sfp-maxdays")) return; // page markup absent
  const s = (typeof _rrPolReadBlob === "function") ? (_rrPolReadBlob() || {}) : {};
  const int = (v, d) => { const n = parseInt(v, 10); return Number.isFinite(n) ? n : d; };
  const maxDays = Number.isFinite(s.maxDaysOverride) ? s.maxDaysOverride : 5;
  const consec = (typeof _rrPolHardConsec === "function" && _rrPolHardConsec()) ||
    Math.max(1, Math.min(7, int(s.woc_max_consecutive_days, 6)));
  const rest = Math.max(0, Math.min(48, int(s.min_rest_hours, 10)));
  const fifth = s.fifth_day_fill !== true ? "off"
    : (s.fifth_day_override_availability === true && int(s.target_days_per_week, 0) === 5)
      ? "require" : "allow";
  const num = (id, v) => { const el = document.getElementById(id); if (el && typeof _rrPolSelectValue === "function") _rrPolSelectValue(el, v); };
  const val = (id, v) => { const el = document.getElementById(id); if (el) el.value = v; };
  num("rr-sfp-maxdays", maxDays);
  num("rr-sfp-consec", consec);
  num("rr-sfp-rest", rest);
  val("rr-sfp-fifth", fifth);
  val("rr-sfp-preferred", s.preferred_days !== false ? "prefer" : "ignore");
}
window._rrPaintSmartFillCards = _rrPaintSmartFillCards;

// Count "active" advanced rules per group. Honest reads of real toggles —
// each contributes at most what it can actually turn on.
function _rrSfAdvCounts() {
  const s = (typeof _rrPolReadBlob === "function") ? (_rrPolReadBlob() || {}) : {};
  const intEq = (v, n) => { const p = parseInt(v, 10); return Number.isFinite(p) && p !== n; };
  let quality = 0;
  if (s.preferred_days !== false) quality++;
  if (s.attendance_penalty === true) quality++;
  const stab = (typeof _rrPolClassifyStability === "function") ? _rrPolClassifyStability(s) : "flexible";
  if (stab === "lock" || stab === "strong") quality++;
  let route = 0;
  if (s.include_onboarding !== false) route++;
  try {
    const vr = JSON.parse(localStorage.getItem("rr-sched-van-rules") || "{}");
    if (vr && typeof vr === "object" && Object.values(vr).some(Boolean)) route++;
  } catch (_) {}
  let optimization = 0;
  const prios = (s.priorities && typeof s.priorities === "object") ? s.priorities : {};
  if (["coverage", "ot_avoidance", "fairness", "preferred_days"].some((k) => intEq(prios[k], 3))) optimization++;
  if (s.fifth_day_fill === true) optimization++;
  return { quality, route, optimization, total: quality + route + optimization };
}
function _rrUpdateAdvCounts() {
  const c = _rrSfAdvCounts();
  const set = (sel, n) => { const el = document.querySelector(sel); if (el) el.textContent = n + " active"; };
  set('[data-rr-sf-count="quality"]', c.quality);
  set('[data-rr-sf-count="route"]', c.route);
  set('[data-rr-sf-count="optimization"]', c.optimization);
  const tot = document.getElementById("rr-sf-adv-total");
  if (tot) tot.textContent = c.total + " active";
}

// "Last saved" footer label, read from the server-persisted policy.
function _rrSfFmtWhen(d) {
  const now = new Date();
  const time = d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  if (d.toDateString() === now.toDateString()) return "today at " + time;
  return d.toLocaleDateString([], { month: "short", day: "numeric" }) + " at " + time;
}
function _rrSfSavedLabel() {
  const el = document.getElementById("rr-sf-saved-label");
  if (!el) return;
  const pol = window.RR && window.RR.dsp && window.RR.dsp.metadata && window.RR.dsp.metadata.staffing_policy;
  const ts = pol && pol.saved_at;
  if (ts) { const d = new Date(ts); if (!isNaN(d.getTime())) { el.textContent = "Last saved " + _rrSfFmtWhen(d); return; } }
  el.textContent = "All changes saved locally";
}
function _rrSfMarkUnsaved() {
  const el = document.getElementById("rr-sf-saved-label");
  if (el) el.textContent = "Unsaved changes";
}

// Persist the live blob to dsps.metadata.staffing_policy (shared by the
// footer Save Policy button and the detailed editor's own Save).
async function _rrPolSaveToServer(btn) {
  if (btn) btn.disabled = true;
  try {
    const dspId = window.RR && window.RR.dsp && window.RR.dsp.id;
    if (!dspId) throw new Error("DSP not loaded");
    const { data: dsp, error: rErr } = await sb.from("dsps").select("metadata").eq("id", dspId).single();
    if (rErr) throw rErr;
    const md = dsp.metadata || {};
    md.staffing_policy = {
      rules: _rrPolReadBlob(),
      consec_hard: _rrPolHardConsec(),
      saved_at: new Date().toISOString(),
    };
    const { error: wErr } = await sb.from("dsps").update({ metadata: md }).eq("id", dspId);
    if (wErr) throw wErr;
    window.RR.dsp.metadata = md;
    if (typeof toast === "function") toast("Staffing policy saved", "success");
    try { _rrSfSavedLabel(); } catch (_) {}
    return true;
  } catch (err) {
    console.warn("Save staffing policy:", err && err.message);
    if (typeof toast === "function") toast("Couldn't save policy: " + (err && err.message), "warn");
    return false;
  } finally {
    if (btn) btn.disabled = false;
  }
}
window._rrPolSaveToServer = _rrPolSaveToServer;

// Reset to defaults — clears the local policy entirely, then repaints.
function _rrSfResetPolicy() {
  if (!window.confirm("Reset Smart Fill policy to defaults? This clears every rule on this page. Click Save Policy afterward to apply it for your DSP.")) return;
  try { localStorage.removeItem(_RR_SF_RULES_KEY); } catch (_) {}
  try { localStorage.removeItem(_RR_POL_CONSEC_KEY); } catch (_) {}
  try { _restoreSmartFillRules(); } catch (_) {}
  try { _rrPolPaint(); } catch (_) {}
  try { _rrSfDiffSchedule(); } catch (_) {}
  try { _rrPaintSmartFillCards(); } catch (_) {}
  try { _rrUpdateAdvCounts(); } catch (_) {}
  const el = document.getElementById("rr-sf-saved-label");
  if (el) el.textContent = "Reset to defaults — Save Policy to apply";
}

// Reveal the detailed editor, optionally opening the relevant section.
// Each card's Edit opens this deep-settings accordion inline, with the card's
// own section auto-expanded. (Cards-only model: no separate editor box, and
// the controls already on the cards are hidden in the panel as duplicates.)
const _RR_SF_EDIT_SECTIONS = Object.freeze({
  limits:       ['[data-rr-sf-section="protections"]'],
  prefs:        ['[data-rr-sf-section="prefs"]'],
  safety:       ['[data-rr-sf-section="eligibility"]'],
  quality:      ['[data-rr-sf-section="prefs"]'],
  route:        ['[data-rr-sf-section="custom"]'],
  optimization: ['[data-rr-sf-section="engine"]'],
  all:          [],
});
function _rrSfRevealDetail(which, anchor) {
  const detail = document.getElementById("rr-sf-detail");
  if (!detail) return;
  // Re-clicking the same card's Edit collapses the panel.
  if (!detail.hidden && detail.dataset.rrFor === which) {
    detail.hidden = true;
    detail.dataset.rrFor = "";
    return;
  }
  // Drop the panel directly beneath the card (its row), full-width.
  if (anchor && anchor.parentElement) anchor.insertAdjacentElement("afterend", detail);
  detail.hidden = false;
  detail.dataset.rrFor = which;
  // The Advanced wrapper holds the sections — keep it open; its own summary is
  // hidden by CSS so the sections read as a flat accordion.
  const adv = detail.querySelector("#rr-pol-advanced");
  if (adv && adv.tagName === "DETAILS") adv.open = true;
  // Collapse every section, then open the one(s) this card maps to.
  const sections = [...detail.querySelectorAll('[data-rr-sf-section]')];
  sections.forEach((d) => { if (d.tagName === "DETAILS") d.open = false; });
  const open = (which === "all")
    ? sections
    : (_RR_SF_EDIT_SECTIONS[which] || []).map((sel) => detail.querySelector(sel)).filter(Boolean);
  open.forEach((d) => { if (d && d.tagName === "DETAILS") d.open = true; });
  try { detail.scrollIntoView({ behavior: "smooth", block: "nearest" }); } catch (_) {}
}

// ── Smart Fill page · the preset-card dropdown handler ────────────────
// Mirrors the rr-pol-* handler exactly (same _rrPolApply mutations) so the
// cards and the detailed editor stay one source of truth. Every control here
// maps to a real policy key the engine consumes.
document.addEventListener("change", (e) => {
  const el = e.target;
  if (!el || !el.id || !el.id.startsWith("rr-sfp-")) return;
  switch (el.id) {
    case "rr-sfp-maxdays": {
      const n = parseInt(el.value, 10);
      if (!Number.isFinite(n)) return;
      _rrPolApply((s) => { s.maxDaysOverride = Math.max(1, Math.min(7, n)); });
      break;
    }
    case "rr-sfp-consec": {
      const n = parseInt(el.value, 10);
      if (!Number.isFinite(n)) return;
      if ([4, 5, 6].includes(n)) { try { localStorage.setItem(_RR_POL_CONSEC_KEY, String(n)); } catch (_) {} }
      _rrPolApply((s) => { s.woc = true; s.woc_max_consecutive_days = n; });
      break;
    }
    case "rr-sfp-rest": {
      const n = parseInt(el.value, 10);
      if (!Number.isFinite(n)) return;
      _rrPolApply((s) => { s.min_rest = true; s.min_rest_hours = Math.max(0, Math.min(48, n)); });
      break;
    }
    case "rr-sfp-fifth":
      _rrPolApply((s) => {
        if (el.value === "off") { s.fifth_day_fill = false; s.fifth_day_override_availability = false; }
        else if (el.value === "allow") {
          s.fifth_day_fill = true; s.fifth_day_override_availability = false;
          if (!s.dataSources || typeof s.dataSources !== "object") s.dataSources = {};
          s.dataSources.fifth_day_optin = true;
        } else {
          s.fifth_day_fill = true; s.fifth_day_override_availability = true; s.target_days_per_week = 5;
          if (!s.dataSources || typeof s.dataSources !== "object") s.dataSources = {};
          s.dataSources.fifth_day_optin = false;
        }
      });
      break;
    case "rr-sfp-preferred":
      _rrPolApply((s) => { s.preferred_days = (el.value === "prefer"); });
      break;
    default: return;
  }
  try { _rrPaintSmartFillCards(); } catch (_) {}
  try { _rrUpdateAdvCounts(); } catch (_) {}
  try { _rrSfMarkUnsaved(); } catch (_) {}
});

// Page-level clicks: Edit / View-all reveal the editor; collapse toggles;
// footer Save / Reset.
document.addEventListener("click", (e) => {
  if (!window._rrSmartFillPageMode) return;
  const t = e.target;
  if (!t || !t.closest) return;
  const editBtn = t.closest("[data-rr-sf-edit]");
  if (editBtn) {
    e.preventDefault();
    // Anchor the inline panel below the card's row (advanced card uses its own
    // container) so it never lands inside the 3-column grid.
    const anchor = editBtn.closest("#rr-sf-advanced-card")
      || editBtn.closest(".rr-sf-cards3")
      || editBtn.closest(".rr-sf-card");
    _rrSfRevealDetail(editBtn.getAttribute("data-rr-sf-edit"), anchor);
    return;
  }
  if (t.closest("#rr-sf-adv-toggle")) {
    const card = document.getElementById("rr-sf-advanced-card");
    if (card) {
      const collapsed = card.classList.toggle("rr-collapsed");
      const tg = document.getElementById("rr-sf-adv-toggle");
      if (tg) { tg.setAttribute("aria-expanded", String(!collapsed)); tg.setAttribute("aria-label", collapsed ? "Expand advanced rules" : "Collapse advanced rules"); }
    }
    return;
  }
  const saveBtn = t.closest("#rr-sf-save");
  if (saveBtn) { e.preventDefault(); _rrPolSaveToServer(saveBtn); return; }
  if (t.closest("#rr-sf-reset")) { e.preventDefault(); _rrSfResetPolicy(); return; }
});

// Keep the overview surfaces in sync when the operator edits in the detailed
// editor while the page is open. Read-only repaint of the cards/summary —
// the edits themselves already went through the editor's own handlers.
document.addEventListener("change", (e) => {
  if (!window._rrSmartFillPageMode) return;
  if (!e.target || !e.target.closest) return;
  if (e.target.id && e.target.id.startsWith("rr-sfp-")) return; // own handler painted already
  if (!e.target.closest("#rr-sf-detail")) return;
  try { _rrPaintSmartFillCards(); } catch (_) {}
  try { _rrUpdateAdvCounts(); } catch (_) {}
  try { _rrSfMarkUnsaved(); } catch (_) {}
});

// Refresh derived rule visibility (incl. the standalone Assign Vans
// button) on initial load, not just when the popover is opened — the
// engine-hides-vans logic needs to fire before the operator even
// touches the rules card.
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => _refreshSfAdvancedGating(), { once: true });
} else {
  _refreshSfAdvancedGating();
}

// ── Van assignment rules · same pattern as Smart Fill rules ──
// Operator toggles which parts of the van auto-assign logic to
// apply on the next run. State persists in localStorage; the
// resolver in _assignVansForRange reads it via _rrLoadVanRules
// at the start of every run.
const _RR_VAN_RULES_KEY = "rr-sched-van-rules";
// Path B · the FEM auto-rescue trigger at the bottom of
// renderScheduleWeek now respects this localStorage flag so the
// operator can disable automatic van re-assignment when an at-risk
// van surfaces. Default = on (preserves existing behavior).
const _RR_VAN_AUTO_RESCUE_KEY = "rr-sched-van-auto-rescue";
function _rrVanAutoRescueEnabled() {
  try {
    const v = localStorage.getItem(_RR_VAN_AUTO_RESCUE_KEY);
    return v === null ? true : v === "1";
  } catch (_) { return true; }
}
window._rrVanAutoRescueEnabled = _rrVanAutoRescueEnabled;
const _RR_VAN_RULE_DEFAULTS = {
  primary_chain:    true,
  secondary_chain:  true,
  pool_fill:        true,
  branded_first:    true,
  fem_priority:     true,
  rescue_secondary: true,
  rescue_primary:   true,
};
function _restoreSchedVanRules() {
  let saved;
  try { saved = JSON.parse(localStorage.getItem(_RR_VAN_RULES_KEY) || "{}"); }
  catch (_) { saved = {}; }
  if (!saved || typeof saved !== "object") return;
  // Restores every van-rule checkbox on the page — the schedule popover
  // and the Fleet-assignment twin both carry [data-rr-van-rule] inputs.
  document.querySelectorAll("[data-rr-van-rule]").forEach(cb => {
    const k = cb.getAttribute("data-rr-van-rule");
    if (Object.prototype.hasOwnProperty.call(saved, k)) cb.checked = !!saved[k];
  });
}
function _toggleSchedVanRules(force) {
  const pop = document.getElementById("rr-sched-vans-rules-popover");
  const toggle = document.getElementById("rr-sched-vans-rules-toggle");
  if (!pop) return false;
  const isOpen = !pop.hidden;
  const next = (typeof force === "boolean") ? force : !isOpen;
  pop.hidden = !next;
  // Clear any inline anchor coords on close so the next opener starts from the
  // stylesheet position (the caret opener sets fixed coords under its button).
  if (!next) ["position", "top", "left", "right"].forEach((p) => pop.style.removeProperty(p));
  if (toggle) toggle.setAttribute("aria-expanded", next ? "true" : "false");
  if (next) {
    _restoreSchedVanRules();
    // The Smart Fill van switches (assign / prefer_paired) + the FEM
    // auto-rescue toggle live in this dropdown now — restore them and
    // re-apply the master dimming gate on every open.
    let saved;
    try { saved = JSON.parse(localStorage.getItem(_RR_SF_RULES_KEY) || "{}"); }
    catch (_) { saved = {}; }
    _restoreSfVans(saved && typeof saved === "object" ? saved : {});
    try {
      const auto = localStorage.getItem(_RR_VAN_AUTO_RESCUE_KEY);
      const cb = document.querySelector("[data-rr-van-auto-rescue]");
      if (cb) cb.checked = auto === null ? true : auto === "1";
    } catch (_) {}
    _rrApplyVansMasterGate();
  }
  return next;
}
window._rrToggleSchedVanRules = _toggleSchedVanRules;

// Footer link inside the Van rules dropdown → the full van / driver
// chain editor sub-view (the caret used to open it directly).
document.addEventListener("click", (e) => {
  if (!e.target.closest || !e.target.closest("#rr-van-rules-chain-link")) return;
  e.preventDefault();
  _toggleSchedVanRules(false);
  if (typeof _activateSchedSub === "function") _activateSchedSub("vans-chain");
  if (typeof renderSchedVanAssignmentsBoard === "function") renderSchedVanAssignmentsBoard();
});

// Twin of the van-rules popover, anchored under the Fleet page's
// "Fleet assignment" ribbon tile. Shares the localStorage state with
// the schedule popover, so editing either keeps both identical.
function _toggleFleetVanRules(force) {
  const pop = document.getElementById("rr-fleet-vans-rules-popover");
  const toggle = document.getElementById("rr-fleet-vans-rules-toggle");
  if (!pop) return false;
  const next = (typeof force === "boolean") ? force : pop.hidden;
  pop.hidden = !next;
  if (toggle) toggle.setAttribute("aria-expanded", next ? "true" : "false");
  if (next) _restoreSchedVanRules();
  return next;
}
window._rrToggleFleetVanRules = _toggleFleetVanRules;
document.addEventListener("click", (e) => {
  if (e.target.closest && e.target.closest("#rr-fleet-vans-rules-toggle")) {
    e.preventDefault();
    e.stopPropagation();
    _toggleFleetVanRules();
  }
});

// Attendance policy popover · anchored under the Onboarding →
// Roster → Attendance tile's Rules footer. Same pattern as the
// van-rules popover above. loadAttendancePolicy() lazy-fires on
// first open so the controls populate without forcing the user
// to visit Settings first; subsequent toggles are no-ops on the
// load side. Outside-click closes the popover.
let _attRulesLoaded = false;
function _toggleAttRules(force) {
  const pop = document.getElementById("rr-att-rules-popover");
  const toggle = document.getElementById("rr-att-rules-toggle");
  if (!pop) return false;
  const next = (typeof force === "boolean") ? force : pop.hidden;
  pop.hidden = !next;
  if (toggle) toggle.setAttribute("aria-expanded", next ? "true" : "false");
  if (next && !_attRulesLoaded) {
    _attRulesLoaded = true;
    if (typeof loadAttendancePolicy === "function") {
      try { loadAttendancePolicy(); } catch (err) { console.warn("loadAttendancePolicy:", err); }
    }
  }
  return next;
}
window._rrToggleAttRules = _toggleAttRules;
document.addEventListener("click", (e) => {
  if (e.target.closest && e.target.closest("#rr-att-rules-toggle")) {
    e.preventDefault();
    e.stopPropagation();
    _toggleAttRules();
    return;
  }
  // Outside-click closes the policy popover (any click that lands
  // outside the popover AND outside the toggle).
  const pop = document.getElementById("rr-att-rules-popover");
  if (!pop || pop.hidden) return;
  if (e.target.closest && (e.target.closest("#rr-att-rules-popover") || e.target.closest("#rr-att-rules-toggle"))) return;
  _toggleAttRules(false);
});

// Attendance policy popover · anchored under the SCHEDULE ribbon's
// Roster (V2) tile Rules chevron. The builder DOM (#att-pane-policy)
// lives in this popover now; loadAttendancePolicy() lazy-fires on first
// open so the controls populate without a trip to Settings. Self-
// contained (its own toggle id) so it sits alongside the generic V2
// rules-foot machinery without needing a legacy twin in #rr-sched-cmd.
// Outside-click closes it.
let _schedRosterPolicyLoaded = false;
function _toggleSchedRosterRules(force) {
  const pop = document.getElementById("rr-sched-roster-rules-popover");
  const toggle = document.getElementById("rr-sched-roster-rules-toggle");
  if (!pop) return false;
  const next = (typeof force === "boolean") ? force : pop.hidden;
  pop.hidden = !next;
  if (toggle) toggle.setAttribute("aria-expanded", next ? "true" : "false");
  if (next && !_schedRosterPolicyLoaded) {
    _schedRosterPolicyLoaded = true;
    if (typeof loadAttendancePolicy === "function") {
      try { loadAttendancePolicy(); } catch (err) { console.warn("loadAttendancePolicy:", err); }
    }
  }
  return next;
}
