  document.body.appendChild(m);
  const close = () => {
    m.remove();
    if (icon) icon.setAttribute("aria-expanded", "false");
  };
  m.addEventListener("click", (ev) => {
    if (ev.target === m || ev.target.closest("#rr-vans-rules-modal-close")) close();
  });
  // Esc closes.
