window._rrViolationsFinalizeDialog = _rrViolationsFinalizeDialog;

// Resolve a driver's display name + a friendly date label for the assign
// override dialog below. Best-effort — both fall back to generic phrasing.
function _rrAssignCtx(driverId, iso) {
  let driverName = "";
  try {
    const d = (window._schedDriverList || []).find(x => x.id === driverId);
    if (d && typeof displayDriverName === "function") driverName = displayDriverName(d);
  } catch (_) {}
  let dateLabel = "";
  try {
    if (iso) dateLabel = new Date(iso + "T12:00:00").toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" });
  } catch (_) {}
  return { driverName, dateLabel };
}

// In-context confirmation for a manual assignment that breaks one or more
// hard rules. Replaces the native confirm() the three manual-assign paths
// used (drag from the pool, materialize a gap, move a chip between cells).
// Promise-resolves true = "Assign anyway" (override), false = cancel.
// Mirrors the visual language of _rrViolationsFinalizeDialog so overrides
// read consistently, and defaults focus to Cancel so a reflexive Enter is
// the safe choice (never a silent override).
function _rrConfirmAssignOverride(violations, opts) {
  const list = Array.isArray(violations) ? violations.filter(Boolean) : [];
  return new Promise((resolve) => {
    if (!list.length) { resolve(true); return; }
    const o = opts || {};
    const n = list.length;
    const ctx = (o.driverName || o.dateLabel)
      ? `Assigning ${escapeHtml(o.driverName || "this driver")}${o.dateLabel ? " on " + escapeHtml(o.dateLabel) : ""} breaks ${n} rule${n === 1 ? "" : "s"}:`
      : `This assignment breaks ${n} rule${n === 1 ? "" : "s"}:`;
    const backdrop = document.createElement("div");
    backdrop.id = "rr-assign-override-backdrop";
    backdrop.style.cssText = "position:fixed;inset:0;background:rgba(15,23,42,.28);z-index:10000";
    document.body.appendChild(backdrop);
    const m = document.createElement("div");
    m.id = "rr-assign-override-modal";
    m.setAttribute("role", "alertdialog");
    m.setAttribute("aria-modal", "true");
    m.setAttribute("aria-labelledby", "rr-assign-override-title");
    m.style.cssText =
      "position:fixed;left:50%;top:84px;transform:translateX(-50%);width:420px;" +
      "max-width:calc(100vw - 24px);background:var(--surface,#fff);" +
      "border:1px solid var(--border,#E5E7EB);border-radius:12px;" +
      "box-shadow:0 16px 48px rgba(15,23,42,.24);z-index:10001;opacity:0;" +
      "transition:opacity 120ms ease-out;overflow:hidden";
    const SHOW = 5;
    const rows = list.slice(0, SHOW).map(v =>
      '<div style="display:flex;gap:8px;align-items:baseline;font-size:13px;line-height:1.5;margin-top:6px">' +
        '<span aria-hidden="true" style="flex:0 0 auto;color:#DC2626;font-weight:700;line-height:1.4">•</span>' +
        '<span style="color:var(--text,#111827)">' + escapeHtml(String(v)) + '</span>' +
      '</div>').join("");
    const more = n > SHOW
      ? `<div style="font-size:12px;color:var(--text-subtle,#6B7280);margin-top:8px">+${n - SHOW} more</div>`
      : "";
    m.innerHTML =
      '<div style="padding:16px 18px 14px">' +
        '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">' +
          '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="#DC2626" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>' +
          '<div id="rr-assign-override-title" style="font-size:15px;font-weight:700;color:var(--text,#111827)">Rule violation' + (n === 1 ? "" : "s") + '</div>' +
        '</div>' +
        '<div style="font-size:13px;line-height:1.5;color:var(--text-subtle,#6B7280)">' + ctx + '</div>' +
        rows + more +
      '</div>' +
      '<div style="display:flex;justify-content:flex-end;gap:8px;padding:12px 18px;border-top:1px solid var(--border,#E5E7EB);background:var(--canvas,#F9FAFB)">' +
        '<button type="button" class="btn btn-sm" data-rr-assign-cancel>Cancel</button>' +
        '<button type="button" class="btn btn-sm btn-primary" data-rr-assign-anyway>Assign anyway</button>' +
      '</div>';
    document.body.appendChild(m);
    requestAnimationFrame(() => { m.style.opacity = "1"; });
    let done = false;
    const finish = (val) => {
      if (done) return; done = true;
      document.removeEventListener("keydown", onKey);
      m.style.opacity = "0";
      setTimeout(() => { m.remove(); backdrop.remove(); }, 120);
      resolve(val);
    };
    // Escape cancels. Enter is intentionally NOT bound to override — the
    // focused button (Cancel by default) handles Enter/Space natively.
    const onKey = (ev) => { if (ev.key === "Escape") { ev.preventDefault(); finish(false); } };
    document.addEventListener("keydown", onKey);
    backdrop.addEventListener("click", () => finish(false));
    m.addEventListener("click", (ev) => {
      if (ev.target.closest("[data-rr-assign-cancel]")) finish(false);
      else if (ev.target.closest("[data-rr-assign-anyway]")) finish(true);
    });
    requestAnimationFrame(() => m.querySelector("[data-rr-assign-cancel]")?.focus());
  });
}
window._rrConfirmAssignOverride = _rrConfirmAssignOverride;

// ─── Finalize · premium Draft → Live state transition ──────────────────
// Treats Finalize as a ~2-second publish animation that communicates the
// schedule has officially moved from Draft to Live. Calm, enterprise,
// operational — no toasts / banners / confetti / modals.
//
//   1. Button depresses, icon → spinner, label → "Finalizing Schedule…".
//   2. The schedule WORKSPACE (KPI strip · grid · week toolbar) fades to
//      85% with a 1–2px blur — it recedes while staying readable. The
//      sidebar, title, status pill, and the active button stay crisp.
//   3. A restrained light shimmer sweeps across the KPI strip.
//   4. At ~1.5s the status pill animates Draft → Live (amber → green,
//      scale 0.9 → 1.15 → 1.0) with a soft green radial glow that fades.
//   5. Blur/opacity restore, shimmer stops, spinner clears, the button
//      settles, and the schedule rests in its Live state.
const _rrDelay = (ms) => new Promise((r) => setTimeout(r, ms));
const _RR_FIN_SPINNER =
  '<svg class="rr-fin-spinner" viewBox="0 0 24 24" width="15" height="15" fill="none" ' +
  'stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true">' +
  '<path d="M12 3a9 9 0 0 1 9 9"/></svg>';

async function _rrFinalizePublish() {
  if (window._rrFinalizePublishing) return;
  const dspId = window.RR?.dsp?.id;
  if (!dspId || !_schedStart) { await _setWeekFinalized(true); return; }

  const btn  = document.getElementById("rr-sched-finalize-h");
  const pill = document.getElementById("rr-sched-v2-status");
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // Reduced motion → publish without theatrics.
  if (reduce) { await _setWeekFinalized(true); return; }

  window._rrFinalizePublishing = true;

  // Phase 1 — button: depress + spinner + "Finalizing Schedule…".
  let btnPrevHTML = null;
  if (btn) {
    btnPrevHTML = btn.innerHTML;
    btn.classList.add("rr-fin-btn-busy");
    btn.setAttribute("aria-busy", "true");
    btn.innerHTML = `${_RR_FIN_SPINNER} Finalizing Schedule…`;
  }

  // Phases 2 + 3 — recede the workspace (fade + blur) and run the KPI
  // shimmer. Both are pure CSS driven off this one body-level class.
  document.body.classList.add("rr-sched-publishing");

  // Commit the change now; gate the pill activation on BOTH the write
  // landing and a ~1.5s beat so the transition feels deliberate.
  const rpcPromise = sb.rpc("set_schedule_finalized", { p_week_start: _schedStart, p_finalized: true });
  const [rpcRes] = await Promise.all([rpcPromise, _rrDelay(1500)]);

  if (rpcRes && rpcRes.error) {
    // Roll the visuals back and surface the failure (this is an error
    // path, not a success notification).
    document.body.classList.remove("rr-sched-publishing");
    if (btn) {
      btn.classList.remove("rr-fin-btn-busy");
      btn.removeAttribute("aria-busy");
      if (btnPrevHTML != null) btn.innerHTML = btnPrevHTML;
    }
    window._rrFinalizePublishing = false;
    toast("Failed: " + rpcRes.error.message, "warn");
    return;
  }

  // State is officially Live.
  window._rrWeekFinalized = true;

  // Phase 4 — pill Draft → Live: amber→green swap, scale pop, radial glow.
  if (pill) {
    pill.setAttribute("data-state", "live");
    const lbl = pill.querySelector(".sched-v2-status-label");
    if (lbl) lbl.textContent = "Live";
    pill.classList.add("rr-fin-activate");
    setTimeout(() => pill.classList.remove("rr-fin-activate"), 1300);
  }

  // Hold the published beat (~0.5s → ~2s total) then settle.
  await _rrDelay(500);

  // Phase 5 — settle: lift blur/opacity, stop shimmer, clear spinner, and
  // render the canonical finalized button (Live / Unfinalize).
  document.body.classList.remove("rr-sched-publishing");
  if (btn) {
    btn.classList.remove("rr-fin-btn-busy");
    btn.removeAttribute("aria-busy");
  }
  _updateFinalizeButton();
  window._rrFinalizePublishing = false;
}
window._rrFinalizePublish = _rrFinalizePublish;

document.addEventListener("click", async (e) => {
  if (e.target.closest("#schedule-cta, #rr-sched-finalize-h")) {
    e.preventDefault();
    // Ignore re-clicks while a publish animation is in flight.
    if (window._rrFinalizePublishing) return;
    const target = !window._rrWeekFinalized;
    // Advisory finalize gates — surface rule violations and callout
    // exposure before publishing. Each gets the same warning-modal
    // treatment: "Finalize Anyway" proceeds, "Review Schedule" backs out.
    // Never a hard block (existing rules still own those). When both fire,
    // violations are shown first, then callout exposure.
    if (target) {
      const hasViolations = (Number(window._rrWeekViolationCount) || 0) > 0;
      const hasExposure = !!window._rrCalloutExposure?.anyExposed;
      if (hasViolations || hasExposure) {
        if (hasViolations) {
          const proceed = await _rrViolationsFinalizeDialog(window._rrWeekViolations || []);
          if (!proceed) return;
        }
        if (hasExposure) {
          const proceed = await _rrCalloutExposureFinalizeDialog(window._rrCalloutExposure);
          if (!proceed) return;
        }
        await _rrFinalizePublish();
        return;
      }
    }
    const ok = target
      ? await _rrConfirmDialog({
          title: "Finalize this week?",
          body: (() => {
            const open = Number(window._rrOpenShiftsCount) || 0;
            const viol = Number(window._rrWeekViolationCount) || 0;
            const flags = [];
            if (open) flags.push(`${open} open route${open === 1 ? "" : "s"}`);
            if (viol) flags.push(`${viol} rule violation${viol === 1 ? "" : "s"}`);
            const preflight = flags.length
              ? `<strong>Publishing with ${flags.join(" and ")}.</strong><br>`
              : "";
            return preflight + "This marks the schedule live for drivers. Edits after this will trigger a warning prompt.";
          })(),
          confirmLabel: "Finalize",
          cancelLabel: "Cancel",
        })
      : await _rrConfirmDialog({
          title: "Unfinalize this week?",
          body: "This returns the week to draft. Drivers will no longer see it as their live schedule until you finalize again.",
          confirmLabel: "Unfinalize",
          cancelLabel: "Cancel",
        });
    if (!ok) return;
    // Draft → Live runs the premium publish transition; Unfinalize keeps
    // the plain path.
    if (target) {
      await _rrFinalizePublish();
    } else {
      await _setWeekFinalized(target);
    }
  }
});

